import requests
import re

allowed_urls = re.compile(r'^https://api\.newrelic\.com/v2/alerts_.*$')

def filter_alerts(alerts):
    return [alert for alert in alerts if alert.get('severity') in ['critical', 'warning']]

def dedupe_alerts(alerts):
    seen = set()
    unique_alerts = []
    for alert in alerts:
        alert_id = alert.get('id')
        if alert_id and alert_id not in seen:
            seen.add(alert_id)
            unique_alerts.append(alert)
    return unique_alerts

def process_alerts(alerts):
    for alert in alerts:
        print(f"Alert: {alert.get('name')} - {alert.get('severity')}")
        print(f"Description: {alert.get('description')}")
        print(f"Timestamp: {alert.get('created_at')}")
        print("-" * 40)

