import os
import sys
import stat
from pathlib import Path
import coverage
import ast
from typing import List, Set

tests_dir = Path("tests")

def generate_test(test_name, permissions=0o644):
    path = tests_dir / f"test_{test_name}.py"

    with open(path, "w") as f:
        f.write("def test_%s():\n    assert True\n" % test_name)

    os.chmod(path, permissions)

def analyze_coverage(source_dir=".", report=True):
    cov = coverage.Coverage()
    cov.start()

    # Run all existing tests
    if tests_dir.exists():
        for test_file in tests_dir.glob("test_*.py"):
            module_name = test_file.stem
            try:
                __import__(f"tests.{module_name}")
            except ImportError as e:
                print(f"Could not import {module_name}: {e}")

    cov.stop()

    if report:
        cov.report()

    return cov

def find_uncovered_functions(source_dir=".") -> List[str]:
    # Analyze Python files for functions
    functions = set()
    for path in Path(source_dir).glob("*.py"):
        if path.name.startswith("test_"):
            continue

        try:
            with open(path, "r") as f:
                tree = ast.parse(f.read(), filename=str(path))

            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    functions.add(node.name)
        except Exception as e:
            print(f"Error parsing {path}: {e}")

    # Get covered functions
    cov = analyze_coverage(source_dir, report=False)
    covered = set()

    for filename in cov.get_data().measured_files():
        try:
            with open(filename, "r") as f:
                tree = ast.parse(f.read(), filename=filename)

            line_info = cov.get_data().lines(filename)
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    if node.lineno in line_info:
                        covered.add(node.name)
        except Exception as e:
            print(f"Error analyzing coverage for {filename}: {e}")

    return list(functions - covered)

def main():
    if not tests_dir.exists():
        tests_dir.mkdir()
        init_file = tests_dir / "__init__.py"
        init_file.touch()

    if len(sys.argv) < 2:
        print("Usage: python script.py [analyze|generate] [options]")
        return

    if sys.argv[1] == "analyze":
        analyze_coverage()

    elif sys.argv[1] == "generate":
        permissions = 0o644
        if len(sys.argv) > 3 and sys.argv[2] == "--permissions":
            try:
                permissions = int(sys.argv[3], 8)
                test_names = sys.argv[4:]
            except ValueError:
                print("Invalid permissions format. Use octal (e.g. 0644)")
                return
        else:
            test_names = sys.argv[2:]

        if not test_names:
            print("Generating tests for uncovered functions...")
            test_names = find_uncovered_functions()

        for name in test_names:
            generate_test(name, permissions)
            print(f"Generated test for {name}")

if __name__ == "__main__":
    main()

if len(sys.argv) <= 1:
    generate_test("foo")
    generate_test("bar")
