from flask import Flask, request, render_template, redirect, url_for, flash
import sqlite3

app = Flask(__name__)
app.secret_key = 'your_secure_secret_key_here'

def get_db():
    db = sqlite3.connect('surveys.db')
    db.row_factory = sqlite3.Row
    return db

def init_db():
    db = get_db()
    db.execute('''
    CREATE TABLE IF NOT EXISTS surveys (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        title TEXT NOT NULL,
        description TEXT,
        created_by TEXT NOT NULL
    )''')
    db.execute('''
    CREATE TABLE IF NOT EXISTS questions (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        survey_id INTEGER NOT NULL,
        question_text TEXT NOT NULL,
        question_type TEXT NOT NULL,
        options TEXT,
        FOREIGN KEY (survey_id) REFERENCES surveys (id)
    )''')
    db.execute('''
    CREATE TABLE IF NOT EXISTS responses (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        survey_id INTEGER NOT NULL,
        respondent TEXT,
        response_data TEXT NOT NULL,
        submitted_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (survey_id) REFERENCES surveys (id)
    )''')
    db.commit()

@app.before_first_request
def setup():
    init_db()

class DB:
    @staticmethod
    def update_survey_settings(survey_id, settings):
        db = get_db()
        cursor = db.cursor()
        cursor.execute("UPDATE surveys SET title = ?, description = ? WHERE id = ?",
                     (settings.get('title'), settings.get('description'), survey_id))
        db.commit()
        return cursor.rowcount > 0

    @staticmethod
    def get_survey(survey_id):
        db = get_db()
        survey = db.execute("SELECT * FROM surveys WHERE id = ?", (survey_id,)).fetchone()
        if survey:
            questions = db.execute("SELECT * FROM questions WHERE survey_id = ?", (survey_id,)).fetchall()
            return {"survey": dict(survey), "questions": [dict(q) for q in questions]}
        return None

    @staticmethod
    def create_survey(title, description, created_by):
        db = get_db()
        cursor = db.cursor()
        cursor.execute("INSERT INTO surveys (title, description, created_by) VALUES (?, ?, ?)",
                     (title, description, created_by))
        survey_id = cursor.lastrowid
        db.commit()
        return survey_id

    @staticmethod
    def add_question(survey_id, question_text, question_type, options=None):
        db = get_db()
        cursor = db.cursor()
        cursor.execute("INSERT INTO questions (survey_id, question_text, question_type, options) VALUES (?, ?, ?, ?)",
                     (survey_id, question_text, question_type, options))
        db.commit()
        return cursor.lastrowid

    @staticmethod
    def save_response(survey_id, respondent, response_data):
        db = get_db()
        cursor = db.cursor()
        cursor.execute("INSERT INTO responses (survey_id, respondent, response_data) VALUES (?, ?, ?)",
                     (survey_id, respondent, response_data))
        db.commit()
        return cursor.lastrowid

    @staticmethod
    def get_surveys():
        db = get_db()
        return db.execute("SELECT * FROM surveys").fetchall()

    @staticmethod
    def get_responses(survey_id):
        db = get_db()
        return db.execute("SELECT * FROM responses WHERE survey_id = ?", (survey_id,)).fetchall()

db = DB()

@app.route("/")
def index():
    surveys = db.get_surveys()
    return render_template("index.html", surveys=surveys)

@app.route("/survey/new", methods=["GET", "POST"])
def create_survey():
    if request.method == "POST":
        title = request.form.get("title")
        description = request.form.get("description")
        created_by = request.form.get("created_by")

        survey_id = db.create_survey(title, description, created_by)
        return redirect(url_for("edit_survey", id=survey_id))

    return render_template("create_survey.html")

@app.route("/survey/<id>/edit", methods=["GET"])
def edit_survey(id):
    survey_data = db.get_survey(id)
    if not survey_data:
        flash("Survey not found")
        return redirect(url_for("index"))

    return render_template("edit_survey.html", survey=survey_data)

@app.route("/survey/<id>/question/add", methods=["POST"])
def add_question(id):
    question_text = request.form.get("question_text")
    question_type = request.form.get("question_type")
    options = request.form.get("options")

    db.add_question(id, question_text, question_type, options)
    return redirect(url_for("edit_survey", id=id))

@app.route("/survey/<id>", methods=["GET"])
def take_survey(id):
    survey_data = db.get_survey(id)
    if not survey_data:
        flash("Survey not found")
        return redirect(url_for("index"))

    return render_template("take_survey.html", survey=survey_data)

@app.route("/survey/<id>/submit", methods=["POST"])
def submit_survey(id):
    respondent = request.form.get("respondent")
    response_data = str(dict(request.form))

