nltk.download('punkt')
nltk.download('stopwords')

if not os.path.exists(app.config['UPLOAD_FOLDER']):
    os.makedirs(app.config['UPLOAD_FOLDER'])

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in app.config['ALLOWED_EXTENSIONS']

def extract_text(file_path):
    extension = file_path.rsplit('.', 1)[1].lower()
    if extension == 'txt':
        with open(file_path, 'r', errors='ignore') as f:
            return f.read()
    elif extension == 'pdf':
        text = ""
        with open(file_path, 'rb') as f:
            pdf_reader = PyPDF2.PdfReader(f)
            for page_num in range(len(pdf_reader.pages)):
                text += pdf_reader.pages[page_num].extract_text()
        return text
    elif extension == 'docx':
        doc = Document(file_path)
        return ' '.join([paragraph.text for paragraph in doc.paragraphs])
    return ""

def tokenize_and_stem(text):
    stop_words = set(stopwords.words('english'))
    ps = PorterStemmer()
    words = word_tokenize(text.lower())
    return [ps.stem(word) for word in words if word.isalnum() and word not in stop_words]

def load_index():
    if os.path.exists(app.config['INDEX_FILE']):
        with open(app.config['INDEX_FILE'], 'r') as f:
            return json.load(f)
    return {}

def save_index(index):
    with open(app.config['INDEX_FILE'], 'w') as f:
        json.dump(index, f)

def update_index(file_id, file_name, text):
    index = load_index()
    tokens = tokenize_and_stem(text)

    for token in set(tokens):
        if token not in index:
            index[token] = []
        if file_id not in index[token]:
            index[token].append({"id": file_id, "name": file_name})

    save_index(index)

