def upload_file():
    if 'file' not in request.files:
        flash('No file part')
        return redirect(request.url)

    files = request.files.getlist('file')

    for file in files:
        if file.filename == '':
            flash('No selected file')
            return redirect(request.url)

        if file and allowed_file(file.filename):
            filename = secure_filename(file.filename)
            file_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
            file.save(file_path)

            text = extract_text(file_path)
            file_id = os.path.basename(file_path)
            update_index(file_id, filename, text)

            flash(f'Successfully indexed {filename}')

    return redirect(url_for('index'))

@app.route('/search', methods=['GET'])
def search():
    query = request.args.get('query', '')
    if not query:
        return render_template('index.html', results=[])

    index = load_index()
    query_tokens = tokenize_and_stem(query)

    results = {}
    for token in query_tokens:
        if token in index:
            for doc in index[token]:
                if doc["id"] not in results:
                    results[doc["id"]] = {"id": doc["id"], "name": doc["name"], "score": 0}
                results[doc["id"]]["score"] += 1

    sorted_results = sorted(results.values(), key=lambda x: x["score"], reverse=True)
    return render_template('index.html', results=sorted_results, query=query)

if __name__ == '__main__':
    app.run(debug=True)
