import json
import uuid
from datetime import datetime
from typing import Dict, List, Optional, Union

class Campaign:
    def __init__(self, name: str, start_date: str, end_date: str, 
                 target_audience: List[str], channels: List[str], 
                 budget: float, description: str = ""):
        self.id = str(uuid.uuid4())
        self.name = name
        self.start_date = start_date
        self.end_date = end_date
        self.target_audience = target_audience
        self.channels = channels
        self.budget = budget
        self.description = description
        self.status = "draft"
        self.created_at = datetime.now().isoformat()
        self.updated_at = self.created_at

    def to_dict(self) -> Dict:
        return {
            "id": self.id,
            "name": self.name,
            "start_date": self.start_date,
            "end_date": self.end_date,
            "target_audience": self.target_audience,
            "channels": self.channels,
            "budget": self.budget,
            "description": self.description,
            "status": self.status,
            "created_at": self.created_at,
            "updated_at": self.updated_at
        }

    @classmethod
    def from_dict(cls, data: Dict) -> 'Campaign':
        campaign = cls(
            name=data["name"],
            start_date=data["start_date"],
            end_date=data["end_date"],
            target_audience=data["target_audience"],
            channels=data["channels"],
            budget=data["budget"],
            description=data.get("description", "")
        )
        campaign.id = data.get("id", campaign.id)
        campaign.status = data.get("status", campaign.status)
        campaign.created_at = data.get("created_at", campaign.created_at)
        campaign.updated_at = data.get("updated_at", campaign.updated_at)
        return campaign


class MarketingAutomation:
    def __init__(self, storage_file: str = "campaigns.json"):
        self.storage_file = storage_file
        self.campaigns = self._load_campaigns()

    def _load_campaigns(self) -> Dict[str, Campaign]:
        try:
            with open(self.storage_file, 'r') as f:
                data = json.load(f)
                return {id: Campaign.from_dict(campaign_data) 
                        for id, campaign_data in data.items()}
        except (FileNotFoundError, json.JSONDecodeError):
            return {}

    def _save_campaigns(self):
        with open(self.storage_file, 'w') as f:
            campaigns_dict = {id: campaign.to_dict() 
                             for id, campaign in self.campaigns.items()}
            json.dump(campaigns_dict, f, indent=2)

    def create_campaign(self, campaign_data: Dict) -> str:
        campaign = Campaign(
            name=campaign_data["name"],
            start_date=campaign_data["start_date"],
            end_date=campaign_data["end_date"],
            target_audience=campaign_data["target_audience"],
            channels=campaign_data["channels"],
            budget=campaign_data["budget"],
            description=campaign_data.get("description", "")
        )
        self.campaigns[campaign.id] = campaign
        self._save_campaigns()
        return campaign.id

    def get_campaign(self, campaign_id: str) -> Optional[Dict]:
        campaign = self.campaigns.get(campaign_id)
        if campaign:
            return campaign.to_dict()
        return None

    def update_campaign(self, campaign_id: str, updates: Dict) -> bool:
        if campaign_id not in self.campaigns:
            return False

        campaign = self.campaigns[campaign_id]
        for key, value in updates.items():
            if hasattr(campaign, key) and key not in ["id", "created_at"]:
                setattr(campaign, key, value)

        campaign.updated_at = datetime.now().isoformat()
        self._save_campaigns()
        return True

    def delete_campaign(self, campaign_id: str) -> bool:
        if campaign_id in self.campaigns:
            del self.campaigns[campaign_id]
            self._save_campaigns()
            return True
        return False

    def list_campaigns(self, filters: Optional[Dict] = None) -> List[Dict]:
        results = []

        for campaign in self.campaigns.values():
            if filters:
                include = True
                for key, value in filters.items():
                    if hasattr(campaign, key):
                        campaign_value = getattr(campaign, key)
                        if isinstance(campaign_value, list) and not isinstance(value, list):
                            if value not in campaign_value:
                                include = False
                                break
                        elif campaign_value != value:
                            include = False
                            break
                if include:
                    results.append(campaign.to_dict())
            else:
                results.append(campaign.to_dict())

        return results

    def activate_campaign(self, campaign_id: str) -> bool:
        if campaign_id in self.campaigns:
            campaign = self.campaigns[campaign_id]
            campaign.status = "active"
            campaign.updated_at = datetime.now().isoformat()
            self._save_campaigns()
            return True
        return False

    def pause_campaign(self, campaign_id: str) -> bool:
        if campaign_id in self.campaigns:
            campaign = self.campaigns[campaign_id]
            campaign.status = "paused"
            campaign.updated_at = datetime.now().isoformat()
            self._save_campaigns()
            return True
        return False
