import os
import re
import argparse
import stat

def rename_files(path, pattern=None, replacement=None, recursive=False, permissions=None):
    if not os.path.exists(path):
        print(f"Path {path} does not exist")
        return

    if recursive:
        walker = os.walk(path)
    else:
        walker = [(path, [], [f for f in os.listdir(path) if os.path.isfile(os.path.join(path, f))])]

    for root, dirs, files in walker:
        for filename in files:
            if pattern and replacement is not None:
                new_name = re.sub(pattern, replacement, filename)
            else:
                new_name = filename

            if new_name != filename:
                old_path = os.path.join(root, filename)
                new_path = os.path.join(root, new_name)

                try:
                    os.rename(old_path, new_path)
                    print(f"Renamed: {old_path} -> {new_path}")

                    if permissions:
                        os.chmod(new_path, permissions)
                        print(f"Applied permissions {oct(permissions)} to {new_path}")
                except OSError as e:
                    print(f"Error renaming {old_path}: {e}")

if __name__ == "__main__":
