import yaml
from flask import Flask, request, jsonify, abort
import os
from datetime import datetime
import uuid

app = Flask(__name__)

SIGHTINGS_FILE = 'bird_sightings.yaml'

def load_sightings():
    if os.path.exists(SIGHTINGS_FILE):
        with open(SIGHTINGS_FILE, 'r') as file:
            return yaml.safe_load(file) or []
    return []

def save_sightings(sightings):
    with open(SIGHTINGS_FILE, 'w') as file:
        yaml.dump(sightings, file)

@app.route('/sightings', methods=['POST'])
def sightings():
    sighting = request.get_json()

    if not sighting or not all(key in sighting for key in ['species', 'location', 'image_url']):
        abort(400, description="Missing required fields: species, location, image_url")

    all_sightings = load_sightings()

    new_sighting = {
        'id': str(uuid.uuid4()),
        'species': sighting['species'],
        'location': sighting['location'],
        'image_url': sighting['image_url'],
        'timestamp': datetime.now().isoformat(),
        'notes': sighting.get('notes', '')
    }

    all_sightings.append(new_sighting)
    save_sightings(all_sightings)

    return jsonify({"message": f"Sighting added: {sighting['species']}", "id": new_sighting['id']}), 201

@app.route('/sightings', methods=['GET'])
def get_sightings():
    species_filter = request.args.get('species')
    location_filter = request.args.get('location')

    sightings = load_sightings()

    if species_filter:
        sightings = [s for s in sightings if species_filter.lower() in s['species'].lower()]

    if location_filter:
        sightings = [s for s in sightings if location_filter.lower() in s['location'].lower()]

    return jsonify(sightings)

@app.route('/sightings/<sighting_id>', methods=['GET'])
def get_sighting(sighting_id):
    sightings = load_sightings()
    sighting = next((s for s in sightings if s['id'] == sighting_id), None)

    if not sighting:
        abort(404, description="Sighting not found")

    return jsonify(sighting)

if __name__ == '__main__':
    app.run(debug=True)
