from datetime import datetime
import os
import pickle
import uuid

class Plant:
    def __init__(self, name, photo_path=None):
        self.id = str(uuid.uuid4())
        self.name = name
        self.photo_path = photo_path
        self.watering_history = []
        self.notes = []
        self.last_watered = None

    def add_watering(self):
        now = datetime.now()
        self.watering_history.append(now)
        self.last_watered = now
        return now

    def add_note(self, note_text):
        now = datetime.now()
        self.notes.append((now, note_text))
        return now

    def days_since_watered(self):
        if not self.last_watered:
            return None
        delta = datetime.now() - self.last_watered
        return delta.days

class PlantJournal:
    def __init__(self, save_file='plant_journal.pkl'):
        self.plants = {}
        self.save_file = save_file
        self.load_journal()

    def add_plant(self, name, photo_path=None):
        plant = Plant(name, photo_path)
        self.plants[plant.id] = plant
        self.save_journal()
        return plant.id

    def remove_plant(self, plant_id):
        if plant_id in self.plants:
            del self.plants[plant_id]
            self.save_journal()
            return True
        return False

    def water_plant(self, plant_id):
        if plant_id in self.plants:
            watering_time = self.plants[plant_id].add_watering()
            self.save_journal()
            return watering_time
        return None

    def add_plant_note(self, plant_id, note):
        if plant_id in self.plants:
            note_time = self.plants[plant_id].add_note(note)
            self.save_journal()
            return note_time
        return None

    def update_plant_photo(self, plant_id, photo_path):
        if plant_id in self.plants:
            self.plants[plant_id].photo_path = photo_path
            self.save_journal()
            return True
        return False

    def get_plant(self, plant_id):
        return self.plants.get(plant_id)

    def get_all_plants(self):
        return self.plants

    def get_plants_needing_water(self, days=7):
        needs_water = []
        for plant_id, plant in self.plants.items():
            days_since = plant.days_since_watered()
            if days_since is None or days_since >= days:
                needs_water.append(plant_id)
        return needs_water

    def save_journal(self):
        with open(self.save_file, 'wb') as f:
            pickle.dump(self.plants, f)

    def load_journal(self):
        if os.path.exists(self.save_file):
            try:
                with open(self.save_file, 'rb') as f:
                    self.plants = pickle.load(f)
            except:
                self.plants = {}

def main():
    journal = PlantJournal()

    while True:
        print("\nHouseplant Journal")
        print("1. Add a new plant")
        print("2. List all plants")
        print("3. Record watering")
        print("4. Add a note to a plant")
        print("5. Update plant photo")
        print("6. Show plants needing water")
        print("7. Exit")

        choice = input("\nEnter your choice (1-7): ")

        if choice == "1":
            name = input("Enter plant name: ")
            photo = input("Enter photo path (optional): ")
            photo_path = photo if photo else None
            plant_id = journal.add_plant(name, photo_path)
            print(f"Added plant with ID: {plant_id}")

        elif choice == "2":
            plants = journal.get_all_plants()
            if not plants:
                print("No plants in journal")
            else:
                for pid, plant in plants.items():
                    days = plant.days_since_watered()
                    last_watered = f"{days} days ago" if days is not None else "Never"
                    print(f"ID: {pid} - {plant.name} (Last watered: {last_watered})")

        elif choice == "3":
            pid = input("Enter plant ID: ")
            result = journal.water_plant(pid)
            if result:
                print(f"Watering recorded at {result}")
            else:
                print("Plant not found")

        elif choice == "4":
            pid = input("Enter plant ID: ")
            note = input("Enter note: ")
            result = journal.add_plant_note(pid, note)
            if result:
                print(f"Note added at {result}")
            else:
                print("Plant not found")

        elif choice == "5":
            pid = input("Enter plant ID: ")
            photo = input("Enter new photo path: ")
            if journal.update_plant_photo(pid, photo):
                print("Photo updated")
            else:
                print("Plant not found")

        elif choice == "6":
            days = input("Enter days threshold (default 7): ")
            try:
                days = int(days) if days else 7
                needs_water = journal.get_plants_needing_water(days)
                if not needs_water:
                    print("No plants need watering")
                else:
                    print(f"Plants needing water (not watered in {days}+ days):")
                    for pid in needs_water:
