def extract_and_import_dialogue_data(file_path="dialogues.json", sample_size=1000):
    import json
    import random

    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            all_dialogues = json.load(file)

        if len(all_dialogues) <= sample_size:
            sample_dialogues = all_dialogues
        else:
            sample_dialogues = random.sample(all_dialogues, sample_size)

        processed_dialogues = []
        for dialogue in sample_dialogues:
            if isinstance(dialogue, dict) and 'input' in dialogue and 'response' in dialogue:
                processed_dialogues.append({
                    'input': dialogue['input'],
                    'response': dialogue['response']
                })

        return processed_dialogues
    except FileNotFoundError:
        return []
    except json.JSONDecodeError:
        return []
