from dataclasses import dataclass
from typing import List, Optional
import sqlite3
import time
import random


@dataclass
class Song:
    id: int
    title: str
    artist: str
    duration: int  # in seconds
    lyrics: str


class MusicStreamingApp:
    def __init__(self, db_path="music.db"):
        self.connection = sqlite3.connect(db_path)
        self.cursor = self.connection.cursor()
        self.setup_database()
        self.current_song = None
        self.is_playing = False
        self.playlist = []

    def setup_database(self):
        self.cursor.execute('''
        CREATE TABLE IF NOT EXISTS songs (
            id INTEGER PRIMARY KEY,
            title TEXT NOT NULL,
            artist TEXT NOT NULL,
            duration INTEGER NOT NULL,
            lyrics TEXT
        )
        ''')
        self.connection.commit()

    def add_song(self, title, artist, duration, lyrics=""):
        self.cursor.execute(
            "INSERT INTO songs (title, artist, duration, lyrics) VALUES (?, ?, ?, ?)",
            (title, artist, duration, lyrics)
        )
        self.connection.commit()
        return self.cursor.lastrowid

    def get_song(self, song_id) -> Optional[Song]:
        self.cursor.execute("SELECT * FROM songs WHERE id = ?", (song_id,))
        result = self.cursor.fetchone()
        if result:
            return Song(*result)
        return None

    def search_songs(self, query) -> List[Song]:
        self.cursor.execute(
            "SELECT * FROM songs WHERE title LIKE ? OR artist LIKE ?",
            (f"%{query}%", f"%{query}%")
        )
        return [Song(*row) for row in self.cursor.fetchall()]

    def play(self, song_id=None):
        if song_id is not None:
            song = self.get_song(song_id)
            if song:
                self.current_song = song
            else:
                print(f"Song with ID {song_id} not found")
                return
        elif not self.current_song and self.playlist:
            self.current_song = self.playlist.pop(0)
        elif not self.current_song:
            print("No song selected to play")
            return

        self.is_playing = True
        print(f"Now playing: {self.current_song.title} by {self.current_song.artist}")

    def pause(self):
        if self.is_playing:
            self.is_playing = False
            print("Playback paused")
        else:
            print("Nothing is currently playing")

    def resume(self):
        if self.current_song and not self.is_playing:
            self.is_playing = True
            print(f"Resumed: {self.current_song.title}")
        else:
            print("Nothing to resume")

    def stop(self):
        if self.current_song:
            print(f"Stopped playing: {self.current_song.title}")
            self.current_song = None
            self.is_playing = False
        else:
            print("Nothing is currently playing")

    def add_to_playlist(self, song_id):
        song = self.get_song(song_id)
        if song:
            self.playlist.append(song)
            print(f"Added to playlist: {song.title}")
        else:
            print(f"Song with ID {song_id} not found")

    def show_lyrics(self):
        if self.current_song:
            print(f"Lyrics for {self.current_song.title}:")
            print(self.current_song.lyrics)
        else:
            print("No song is currently playing")

    def get_all_songs(self) -> List[Song]:
        self.cursor.execute("SELECT * FROM songs")
        return [Song(*row) for row in self.cursor.fetchall()]

    def shuffle_playlist(self):
        if self.playlist:
            random.shuffle(self.playlist)
            print("Playlist shuffled")
        else:
            print("Playlist is empty")


def demo():
    app = MusicStreamingApp()

    # Add some sample songs
    app.add_song("Sample Song 1", "Artist A", 180, "Sample lyrics for song 1...")
    app.add_song("Sample Song 2", "Artist B", 210, "Sample lyrics for song 2...")
    app.add_song("Another Track", "Artist A", 195, "Sample lyrics for another track...")

    # List all songs
    print("Available songs:")
    for song in app.get_all_songs():
        print(f"{song.id}: {song.title} by {song.artist} ({song.duration//60}:{song.duration%60:02d})")

    # Search for songs
    print("\nSearch results for 'Sample':")
    for song in app.search_songs("Sample"):
        print(f"{song.id}: {song.title} by {song.artist}")

    # Create a playlist and play
    app.add_to_playlist(1)
    app.add_to_playlist(2)
    app.shuffle_playlist()

    app.play()
    app.show_lyrics()
    time.sleep(1)

    app.pause()
    time.sleep(1)

    app.resume()
    time.sleep(1)

    app.stop()

    # Play the next song from playlist
    app.play()


if __name__ == "__main__":
    demo()
```

