import os
import re
import argparse

def rename_files(dir_path, pattern, replacement, recursive=False, dry_run=False, verbose=False):
    count = 0

    if recursive:
        iterator = os.walk(dir_path)
    else:
        iterator = [(dir_path, [], [f for f in os.listdir(dir_path) if os.path.isfile(os.path.join(dir_path, f))])]

    for root, dirs, files in iterator:
        for filename in files:
            new_name = re.sub(pattern, replacement, filename)
            if new_name != filename:
                old_path = os.path.join(root, filename)
                new_path = os.path.join(root, new_name)

                if verbose or dry_run:
                    print(f"{old_path} -> {new_path}")

                if not dry_run:
                    try:
                        if not os.path.exists(new_path):
                            os.rename(old_path, new_path)
                            count += 1
                        else:
                            print(f"Error: Destination file already exists: {new_path}")
                    except Exception as e:
                        print(f"Error renaming {old_path}: {e}")
                else:
                    count += 1

    return count

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Rename files according to pattern")
    parser.add_argument("directory", help="Directory containing files to rename")
    parser.add_argument("pattern", help="Regex pattern to match in filenames")
    parser.add_argument("replacement", help="Replacement string")
    parser.add_argument("-r", "--recursive", action="store_true", help="Process directories recursively")
    parser.add_argument("-d", "--dry-run", action="store_true", help="Show what would be done without actually renaming")
    parser.add_argument("-v", "--verbose", action="store_true", help="Show detailed output")

    args = parser.parse_args()

    count = rename_files(args.directory, args.pattern, args.replacement, args.recursive, args.dry_run, args.verbose)

    action = "Would rename" if args.dry_run else "Renamed"
    print(f"{action} {count} files")
