import csv
import sys
import argparse
from typing import List, Dict, Callable, Any

def load_csv(file_path: str) -> List[Dict[str, Any]]:
    with open(file_path, 'r', newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        return list(reader)

def save_csv(data: List[Dict[str, Any]], file_path: str) -> None:
    if not data:
        return

    fieldnames = data[0].keys()
    with open(file_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(data)

def transform_data(data: List[Dict[str, Any]], transformations: Dict[str, Callable]) -> List[Dict[str, Any]]:
    result = []
    for row in data:
        new_row = row.copy()
        for column, transform_func in transformations.items():
            if column in new_row:
                new_row[column] = transform_func(new_row[column])
        result.append(new_row)
    return result

def main():
    parser = argparse.ArgumentParser(description='Process CSV files with transformations')
    parser.add_argument('input_file', help='Input CSV file path')
    parser.add_argument('output_file', help='Output CSV file path')
    parser.add_argument('--uppercase', nargs='+', help='Columns to convert to uppercase')
    parser.add_argument('--lowercase', nargs='+', help='Columns to convert to lowercase')
    parser.add_argument('--trim', nargs='+', help='Columns to trim whitespace')
    parser.add_argument('--multiply', nargs='+', help='Columns to multiply by a factor (format: column:factor)')

    args = parser.parse_args()

    try:
        data = load_csv(args.input_file)

        transformations = {}

        if args.uppercase:
            for col in args.uppercase:
                transformations[col] = lambda x: x.upper() if isinstance(x, str) else x

        if args.lowercase:
            for col in args.lowercase:
                transformations[col] = lambda x: x.lower() if isinstance(x, str) else x

        if args.trim:
            for col in args.trim:
                transformations[col] = lambda x: x.strip() if isinstance(x, str) else x

        if args.multiply:
            for item in args.multiply:
                parts = item.split(':')
                if len(parts) == 2:
                    col, factor = parts[0], float(parts[1])
                    transformations[col] = lambda x, f=factor: str(float(x) * f) if x and x.replace('.', '', 1).isdigit() else x

        transformed_data = transform_data(data, transformations)
        save_csv(transformed_data, args.output_file)
        print(f"Transformed data saved to {args.output_file}")

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
