import threading
import queue
import time
import uuid
import json
import os
from concurrent.futures import ThreadPoolExecutor

class LogAggregator:
    def __init__(self, storage_path, batch_size=100, flush_interval=5):
        self.storage_path = storage_path
        self.batch_size = batch_size
        self.flush_interval = flush_interval
        self.event_queue = queue.Queue()
        self.stop_event = threading.Event()
        self.worker_thread = threading.Thread(target=self._worker)

        if not os.path.exists(storage_path):
            os.makedirs(storage_path)

    def start(self):
        self.worker_thread.start()

    def stop(self):
        self.stop_event.set()
        self.worker_thread.join()

    def log_event(self, source, event_type, data):
        event = {
            'id': str(uuid.uuid4()),
            'timestamp': time.time(),
            'source': source,
            'type': event_type,
            'data': data
        }
        self.event_queue.put(event)

    def _worker(self):
        events = []
        last_flush = time.time()

        while not self.stop_event.is_set():
            try:
                event = self.event_queue.get(timeout=0.1)
                events.append(event)
                self.event_queue.task_done()

                if len(events) >= self.batch_size or (time.time() - last_flush) >= self.flush_interval:
                    self._flush_events(events)
                    events = []
                    last_flush = time.time()
            except queue.Empty:
                if events and (time.time() - last_flush) >= self.flush_interval:
                    self._flush_events(events)
                    events = []
                    last_flush = time.time()

        if events:
            self._flush_events(events)

    def _flush_events(self, events):
        if not events:
            return

        filename = f"{int(time.time())}_{uuid.uuid4()}.json"
        filepath = os.path.join(self.storage_path, filename)

        with open(filepath, 'w') as f:
            json.dump(events, f)

class DistributedLogAggregator:
    def __init__(self, storage_path, node_id, max_workers=4):
        self.storage_path = storage_path
        self.node_id = node_id
        self.aggregator = LogAggregator(os.path.join(storage_path, node_id))
        self.executor = ThreadPoolExecutor(max_workers=max_workers)

    def start(self):
        self.aggregator.start()

    def stop(self):
        self.aggregator.stop()
        self.executor.shutdown()

    def log_event(self, source, event_type, data):
        self.aggregator.log_event(source, event_type, data)

    def log_events_batch(self, events):
        for event in events:
            self.executor.submit(
                self.aggregator.log_event,
                event['source'],
                event['type'],
                event['data']
            )

def example_usage():
    system = DistributedLogAggregator("/tmp/logs", "node-1")
    system.start()

    try:
        for i in range(1000):
            system.log_event("app1", "request", {"user_id": i, "action": "login"})
            time.sleep(0.01)
    finally:
        system.stop()

if __name__ == "__main__":
    example_usage()
