import os
import subprocess
import shutil
import stat
import logging
from datetime import datetime
import yaml

logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger()

class CISystem:
    def __init__(self, config_file='ci_config.yaml'):
        self.config = self._load_config(config_file)
        self.workspace = self.config.get('workspace', 'workspace')
        self.artifacts_dir = self.config.get('artifacts_dir', 'artifacts')

    def _load_config(self, config_file):
        try:
            with open(config_file, 'r') as f:
                return yaml.safe_load(f)
        except Exception as e:
            logger.error(f"Failed to load config file: {e}")
            return {}

    def checkout_code(self, repo_url, branch='main'):
        try:
            if not os.path.exists(self.workspace):
                os.makedirs(self.workspace)

            os.chdir(self.workspace)
            if os.path.exists('.git'):
                logger.info("Repository exists, pulling latest changes")
                subprocess.run(['git', 'fetch', '--all'], check=True)
                subprocess.run(['git', 'checkout', branch], check=True)
                subprocess.run(['git', 'pull'], check=True)
            else:
                logger.info(f"Cloning repository {repo_url}")
                subprocess.run(['git', 'clone', repo_url, '.'], check=True)
                subprocess.run(['git', 'checkout', branch], check=True)

            return True
        except subprocess.CalledProcessError as e:
            logger.error(f"Failed to checkout code: {e}")
            return False

    def build_code(self):
        try:
            os.chdir(self.workspace)
            if os.path.exists('build.sh'):
                logger.info("Running build.sh")
                subprocess.run(['chmod', '+x', 'build.sh'], check=True)
                subprocess.run(['./build.sh'], check=True)
            elif os.path.exists('Makefile'):
                logger.info("Running make")
                subprocess.run(['make'], check=True)
            elif os.path.exists('setup.py'):
                logger.info("Running python setup.py build")
                subprocess.run(['python', 'setup.py', 'build'], check=True)
            else:
                logger.warning("No recognized build system found")

            return True
        except subprocess.CalledProcessError as e:
            logger.error(f"Build failed: {e}")
            return False

    def collect_artifacts(self, permissions=0o755):
        try:
            if not os.path.exists(self.artifacts_dir):
                os.makedirs(self.artifacts_dir)

            timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
            artifact_path = os.path.join(self.artifacts_dir, f'build_{timestamp}')
            os.makedirs(artifact_path)

            artifacts_config = self.config.get('artifacts', [])
            if not artifacts_config:
                logger.warning("No artifacts specified in config")

            for artifact in artifacts_config:
                source = os.path.join(self.workspace, artifact)
                if os.path.exists(source):
                    if os.path.isdir(source):
                        dest = os.path.join(artifact_path, os.path.basename(source))
                        shutil.copytree(source, dest)
                    else:
                        shutil.copy2(source, artifact_path)

                    # Set permissions
                    target_path = os.path.join(artifact_path, os.path.basename(source))
                    os.chmod(target_path, permissions)
                    logger.info(f"Collected artifact: {source} with permissions {oct(permissions)}")
                else:
                    logger.warning(f"Artifact not found: {source}")

            return artifact_path
        except Exception as e:
            logger.error(f"Failed to collect artifacts: {e}")
            return None

    def run_pipeline(self, repo_url, branch='main', permissions=0o755):
        logger.info(f"Starting CI pipeline for {repo_url} branch {branch}")

        if not self.checkout_code(repo_url, branch):
            return False

        if not self.build_code():
            return False

        artifacts_path = self.collect_artifacts(permissions)
        if not artifacts_path:
            return False

        logger.info(f"CI pipeline completed successfully. Artifacts at: {artifacts_path}")
        return True

if __name__ == "__main__":
    ci = CISystem()
    ci.run_pipeline(
        repo_url="https://github.com/username/repo.git",
        branch="main",
        permissions=0o755
    )
