import os
import json
import yaml

class ConfigManager:
    def __init__(self, config_path="config.json"):
        self.config_path = config_path
        self.config = self.load_config()

    def load_config(self):
        if not os.path.exists(self.config_path):
            return self.create_default_config()

        file_ext = os.path.splitext(self.config_path)[1].lower()

        try:
            with open(self.config_path, 'r') as f:
                if file_ext == '.json':
                    return json.load(f)
                elif file_ext in ['.yaml', '.yml']:
                    return yaml.safe_load(f)
                else:
                    raise ValueError(f"Unsupported config format: {file_ext}")
        except (json.JSONDecodeError, yaml.YAMLError) as e:
            print(f"Error parsing config file: {e}")
            return self.create_default_config()

    def create_default_config(self):
        default_config = {
            "app_name": "My Application",
            "debug_mode": False,
            "theme": "default",
            "max_connections": 100,
            "log_level": "info"
        }

        self.save_config(default_config)
        return default_config

    def save_config(self, config_data=None):
        if config_data is not None:
            self.config = config_data

        file_ext = os.path.splitext(self.config_path)[1].lower()

        try:
            with open(self.config_path, 'w') as f:
                if file_ext == '.json':
                    json.dump(self.config, f, indent=4)
                elif file_ext in ['.yaml', '.yml']:
                    yaml.dump(self.config, f)
                else:
                    raise ValueError(f"Unsupported config format: {file_ext}")
        except Exception as e:
            print(f"Error saving config file: {e}")

    def get(self, key, default=None):
        return self.config.get(key, default)

    def set(self, key, value):
        self.config[key] = value
        self.save_config()

    def update(self, new_values):
        self.config.update(new_values)
        self.save_config()

if __name__ == "__main__":
    config = ConfigManager("config.json")

    print(f"Current config: {config.config}")

    config.set("theme", "dark")
    config.update({"debug_mode": True, "log_level": "debug"})

    print(f"Updated config: {config.config}")
