        goal = float(request.form['goal'])
        end_date = datetime.strptime(request.form['end_date'], '%Y-%m-%d')

        campaign = Campaign(title=title, description=description, 
                           goal=goal, end_date=end_date, 
                           user_id=current_user.id)
        db.session.add(campaign)
        db.session.commit()

        files = request.files.getlist('media')
        for file in files:
            if file and allowed_file(file.filename):
                filename = secure_filename(file.filename)
                file_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
                file.save(file_path)

                file_type = 'video' if filename.rsplit('.', 1)[1].lower() in ['mp4', 'mov', 'avi'] else 'image'
                media = Media(filename=filename, file_path=file_path, 
                             type=file_type, campaign_id=campaign.id)
                db.session.add(media)

        db.session.commit()
        flash('Campaign created successfully!')
        return redirect(url_for('campaign', campaign_id=campaign.id))

