import stat
import hashlib
from datetime import datetime

def calculate_md5(filepath):
    hash_md5 = hashlib.md5()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def sync_files(local_dir, remote_dir, hostname, username, password=None, private_key_path=None, port=22):
    ssh = paramiko.SSHClient()
    ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())

    if private_key_path:
        private_key = paramiko.RSAKey.from_private_key_file(private_key_path)
        ssh.connect(hostname, port=port, username=username, pkey=private_key)
    else:
        ssh.connect(hostname, port=port, username=username, password=password)

    sftp = ssh.open_sftp()

    try:
        for root, dirs, files in os.walk(local_dir):
            remote_root = os.path.join(remote_dir, os.path.relpath(root, local_dir))

            try:
                sftp.stat(remote_root)
            except FileNotFoundError:
                sftp.mkdir(remote_root)

            for file in files:
                local_path = os.path.join(root, file)
                remote_path = os.path.join(remote_root, file)
                local_stat = os.stat(local_path)
                local_mtime = local_stat.st_mtime
                local_mode = local_stat.st_mode

                try:
                    remote_stat = sftp.stat(remote_path)
                    remote_mtime = remote_stat.st_mtime
                    remote_mode = remote_stat.st_mode

                    if local_mtime > remote_mtime:
                        local_md5 = calculate_md5(local_path)
                        with sftp.open(remote_path, 'rb') as f:
                            remote_md5 = hashlib.md5(f.read()).hexdigest()

                        if local_md5 != remote_md5:
