                    elif local_mode != remote_mode:
                        sftp.chmod(remote_path, local_mode)
                        print(f"Changed permissions: {remote_path}")
                except FileNotFoundError:
                    sftp.put(local_path, remote_path)
                    sftp.chmod(remote_path, local_mode)
                    print(f"Created: {remote_path}")

        for root, dirs, files in os.walk(local_dir):
            remote_root = os.path.join(remote_dir, os.path.relpath(root, local_dir))
            try:
                remote_items = sftp.listdir_attr(remote_root)
                local_items = os.listdir(root)

