import zipfile
import tarfile
import rarfile
import py7zr
import os

class Extractor:
    def __init__(self, filepath):
        self.filepath = filepath
        self.extension = os.path.splitext(filepath)[1].lower()

    def extract(self, destination=None):
        if destination is None:
            destination = os.path.dirname(self.filepath)

        if self.extension == '.zip':
            return self._extract_zip(destination)
        elif self.extension in ['.tar', '.gz', '.bz2', '.xz']:
            return self._extract_tar(destination)
        elif self.extension == '.rar':
            return self._extract_rar(destination)
        elif self.extension == '.7z':
            return self._extract_7z(destination)
        else:
            raise ValueError(f"Unsupported archive format: {self.extension}")

    def _extract_zip(self, destination):
        with zipfile.ZipFile(self.filepath, 'r') as zip_ref:
            zip_ref.extractall(destination)
        return destination

    def _extract_tar(self, destination):
        with tarfile.open(self.filepath, 'r:*') as tar_ref:
            tar_ref.extractall(destination)
        return destination

    def _extract_rar(self, destination):
        with rarfile.RarFile(self.filepath) as rar_ref:
            rar_ref.extractall(destination)
        return destination

    def _extract_7z(self, destination):
        with py7zr.SevenZipFile(self.filepath, mode='r') as seven_ref:
            seven_ref.extractall(destination)
        return destination

    def list_contents(self):
        if self.extension == '.zip':
            return self._list_zip_contents()
        elif self.extension in ['.tar', '.gz', '.bz2', '.xz']:
            return self._list_tar_contents()
        elif self.extension == '.rar':
            return self._list_rar_contents()
        elif self.extension == '.7z':
            return self._list_7z_contents()
        else:
            raise ValueError(f"Unsupported archive format: {self.extension}")

    def _list_zip_contents(self):
        with zipfile.ZipFile(self.filepath, 'r') as zip_ref:
            return zip_ref.namelist()

    def _list_tar_contents(self):
        with tarfile.open(self.filepath, 'r:*') as tar_ref:
            return [member.name for member in tar_ref.getmembers()]

    def _list_rar_contents(self):
        with rarfile.RarFile(self.filepath) as rar_ref:
            return rar_ref.namelist()

    def _list_7z_contents(self):
        with py7zr.SevenZipFile(self.filepath, mode='r') as seven_ref:
            return list(seven_ref.getnames())
