from urllib.parse import urljoin, urlparse
import concurrent.futures

class WebsiteCrawler:
    def __init__(self, start_url, max_pages=100):
        self.start_url = start_url
        self.domain = urlparse(start_url).netloc
        self.visited_urls = set()
        self.broken_links = []
        self.missing_images = []
        self.max_pages = max_pages
        self.session = requests.Session()
        self.session.headers.update({
            'User-Agent': 'Mozilla/5.0 (compatible; BrokenLinkChecker/1.0)'
        })

    def is_valid_url(self, url):
        parsed = urlparse(url)
        return bool(parsed.netloc) and parsed.netloc == self.domain

    def crawl(self):
        self._process_url(self.start_url)
        return {
            'broken_links': self.broken_links,
            'missing_images': self.missing_images
        }

    def _process_url(self, url):
        if len(self.visited_urls) >= self.max_pages:
            return

        if url in self.visited_urls or not self.is_valid_url(url):
            return

        self.visited_urls.add(url)
        print(f"Crawling: {url}")

        try:
            response = self.session.get(url, timeout=10)
            if response.status_code != 200:
                self.broken_links.append((url, response.status_code))
                return

            soup = BeautifulSoup(response.text, 'html.parser')

            self._check_links(soup, url)
            self._check_images(soup, url)

        except requests.RequestException as e:
            self.broken_links.append((url, str(e)))

    def _check_links(self, soup, base_url):
        links = soup.find_all('a')
        urls_to_check = []

        for link in links:
            href = link.get('href')
            if not href:
                continue

            full_url = urljoin(base_url, href)
            if self.is_valid_url(full_url) and full_url not in self.visited_urls:
                urls_to_check.append(full_url)

        with concurrent.futures.ThreadPoolExecutor(max_workers=5) as executor:
            executor.map(self._process_url, urls_to_check)

    def _check_images(self, soup, base_url):
        images = soup.find_all('img')

        for img in images:
            src = img.get('src')
            if not src:
                continue

            img_url = urljoin(base_url, src)

            try:
                response = self.session.head(img_url, timeout=5)
                if response.status_code != 200:
                    self.missing_images.append((img_url, response.status_code, base_url))
            except requests.RequestException as e:
                self.missing_images.append((img_url, str(e), base_url))

if __name__ == "__main__":
    start_url = "https://example.com"
    crawler = WebsiteCrawler(start_url, max_pages=50)
    results = crawler.crawl()

    print("\nBroken Links:")
    for url, status in results['broken_links']:
        print(f"- {url} (Status: {status})")

    print("\nMissing Images:")
    for url, status, page in results['missing_images']:
        print(f"- {url} (Status: {status}) on page {page}")
