def load_config():
    if CONFIG_FILE.exists():
        with open(CONFIG_FILE, 'r') as f:
            return yaml.safe_load(f)
    return {
        'extensions': ['.py', '.js', '.html', '.css'],
        'rules': {
            'trailing_whitespace': True,
            'ensure_newline_at_eof': True,
            'tabs_to_spaces': True,
            'space_count': 4,
            'trim_empty_lines': True
        }
    }

def reformat(contents, config=None):
    if config is None:
        config = load_config()

    rules = config.get('rules', {})

    if rules.get('trailing_whitespace', False):
        contents = re.sub(r'[ \t]+$', '', contents, flags=re.MULTILINE)

    if rules.get('tabs_to_spaces', False):
        space_count = rules.get('space_count', 4)
        contents = contents.replace('\t', ' ' * space_count)

    if rules.get('trim_empty_lines', False):
        contents = re.sub(r'\n{3,}', '\n\n', contents)

    if rules.get('ensure_newline_at_eof', False) and contents and not contents.endswith('\n'):
        contents += '\n'

    return contents

def process_file(filepath: Path) -> None:
    config = load_config()
    file_ext = filepath.suffix.lower()

    if file_ext not in config.get('extensions', []):
        return

    try:
        with open(filepath, 'r', encoding='utf-8') as f:
            contents = f.read()

        new_contents = reformat(contents, config)

        if new_contents != contents:
            with open(filepath, 'w', encoding='utf-8') as f:
                f.write(new_contents)
            print(f"Reformatted: {filepath}")
    except Exception as e:
        print(f"Error processing {filepath}: {e}")

def walk_dir(dirpath: Path) -> None:
    for entry in os.scandir(dirpath):
        entry_path = Path(entry.path)
        if entry.is_file():
            process_file(entry_path)
        elif entry.is_dir() and not entry_path.name.startswith('.'):
            walk_dir(entry_path)

if __name__ == '__main__':
    walk_dir(SOURCE_DIR)
