import re
import requests

def trace_redirects(url):
    history = [url]

    while True:
        try:
            resp = requests.get(url, allow_redirects=False, timeout=10)

            if resp.status_code in (301, 302, 303, 307, 308):
                url = resp.headers.get('location')

                if not url:
                    break

                if not re.match(r'^https?://', url):
                    if url.startswith('/'):
                        parsed = requests.utils.urlparse(history[0])
                        url = f"{parsed.scheme}://{parsed.netloc}{url}"
                    else:
                        base_url = '/'.join(history[-1].split('/')[:-1])
                        url = f"{base_url}/{url}"

                if url in history:
                    break

                history.append(url)
            else:
                break

        except Exception as e:
            print(f"Error: {e}")
            break

    print("Redirect chain:")
    for i, link in enumerate(history):
