import os
import shutil

def copy_package(package, destination):
    try:
        if os.path.exists(destination):
            if os.path.isdir(destination):
                if os.path.exists(os.path.join(destination, os.path.basename(package))):
                    shutil.rmtree(os.path.join(destination, os.path.basename(package)))
            else:
                os.makedirs(destination, exist_ok=True)
        else:
            os.makedirs(destination, exist_ok=True)

        if not os.path.exists(package):
            import importlib
            module = importlib.import_module(package)
            package_path = os.path.dirname(module.__file__)
            shutil.copytree(package_path, os.path.join(destination, package))
        else:
            shutil.copytree(package, destination)
    except Exception as e:
        raise Exception(f"Failed to copy package: {str(e)}")

