from flask import Flask, request, jsonify, session
from flask_socketio import SocketIO, join_room, leave_room, emit
import uuid

app = Flask(__name__)
app.secret_key = uuid.uuid4().hex
socketio = SocketIO(app, cors_allowed_origins="*")

chat_rooms = {}
users = {}

@app.route('/api/register', methods=['POST'])
def register():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')

    if not username or not password:
        return jsonify({"error": "Username and password required"}), 400

    if username in users:
        return jsonify({"error": "Username already exists"}), 400

    users[username] = {"password": password}
    return jsonify({"message": "User registered successfully"}), 201

@app.route('/api/login', methods=['POST'])
def login():
    data = request.get_json()
    username = data.get('username')
    password = data.get('password')

    if not username or not password:
        return jsonify({"error": "Username and password required"}), 400

    if username not in users or users[username]["password"] != password:
        return jsonify({"error": "Invalid credentials"}), 401

    session['username'] = username
    return jsonify({"message": "Login successful"}), 200

@app.route('/api/logout', methods=['POST'])
def logout():
    session.pop('username', None)
    return jsonify({"message": "Logout successful"}), 200

@app.route('/api/rooms', methods=['GET'])
def get_rooms():
    return jsonify({"rooms": list(chat_rooms.keys())}), 200

@app.route('/api/rooms', methods=['POST'])
def create_room():
    if 'username' not in session:
        return jsonify({"error": "Authentication required"}), 401

    data = request.get_json()
    room_name = data.get('name')

    if not room_name:
        return jsonify({"error": "Room name required"}), 400

    if room_name in chat_rooms:
        return jsonify({"error": "Room already exists"}), 400

    chat_rooms[room_name] = {"messages": [], "users": []}
    return jsonify({"message": "Room created successfully"}), 201

@socketio.on('join')
def on_join(data):
    if 'username' not in session:
        return

    username = session['username']
    room = data['room']

    if room not in chat_rooms:
        return

    join_room(room)
    chat_rooms[room]['users'].append(username)
    emit('user_joined', {'username': username}, room=room)

@socketio.on('leave')
def on_leave(data):
    if 'username' not in session:
        return

    username = session['username']
    room = data['room']

    if room not in chat_rooms:
        return

    leave_room(room)
    chat_rooms[room]['users'].remove(username)
    emit('user_left', {'username': username}, room=room)

@socketio.on('message')
def handle_message(data):
    if 'username' not in session:
        return

    username = session['username']
    room = data['room']
    message = data['message']

    if room not in chat_rooms:
        return

    msg_data = {'username': username, 'message': message}
    chat_rooms[room]['messages'].append(msg_data)
    emit('message', msg_data, room=room)

if __name__ == '__main__':
    socketio.run(app, debug=True)
