import os
import json
import hashlib
import shutil
import datetime
import uuid
from pathlib import Path

class SourceControl:
    def __init__(self, repo_path):
        self.repo_path = Path(repo_path)
        self.sc_dir = self.repo_path / '.sc'
        self.versions_dir = self.sc_dir / 'versions'
        self.checkout_file = self.sc_dir / 'checkouts.json'

        if not self.sc_dir.exists():
            self._initialize_repo()

    def _initialize_repo(self):
        self.sc_dir.mkdir(exist_ok=True)
        self.versions_dir.mkdir(exist_ok=True)

        with open(self.checkout_file, 'w') as f:
            json.dump({}, f)

    def _get_file_hash(self, file_path):
        with open(file_path, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()

    def _get_checkouts(self):
        with open(self.checkout_file, 'r') as f:
            return json.load(f)

    def _save_checkouts(self, checkouts):
        with open(self.checkout_file, 'w') as f:
            json.dump(checkouts, f, indent=2)

    def checkout(self, file_path):
        rel_path = Path(file_path).relative_to(self.repo_path)

        checkouts = self._get_checkouts()

        if str(rel_path) in checkouts:
            return False, f"File already checked out by {checkouts[str(rel_path)]['user']}"

        checkouts[str(rel_path)] = {
            "user": os.environ.get("USER", "unknown"),
            "timestamp": datetime.datetime.now().isoformat(),
            "checkout_id": str(uuid.uuid4())
        }

        self._save_checkouts(checkouts)
        return True, f"File checked out successfully"

    def checkin(self, file_path):
        rel_path = Path(file_path).relative_to(self.repo_path)

        checkouts = self._get_checkouts()

        if str(rel_path) not in checkouts:
            return False, "File is not checked out"

        checkout_info = checkouts[str(rel_path)]
        if checkout_info["user"] != os.environ.get("USER", "unknown"):
            return False, f"File is checked out by {checkout_info['user']}"

        file_hash = self._get_file_hash(file_path)
        version_path = self.versions_dir / file_hash

        if not version_path.exists():
            shutil.copy2(file_path, version_path)

        del checkouts[str(rel_path)]
        self._save_checkouts(checkouts)

        return True, "File checked in successfully"

    def status(self):
        checkouts = self._get_checkouts()
        if not checkouts:
            return "No files are currently checked out"

        result = "Checked out files:\n"
        for file_path, info in checkouts.items():
            result += f"{file_path} - checked out by {info['user']} at {info['timestamp']}\n"

        return result

    def discard_checkout(self, file_path):
        rel_path = Path(file_path).relative_to(self.repo_path)

        checkouts = self._get_checkouts()

        if str(rel_path) not in checkouts:
            return False, "File is not checked out"

        checkout_info = checkouts[str(rel_path)]
        if checkout_info["user"] != os.environ.get("USER", "unknown"):
            return False, f"File is checked out by {checkout_info['user']}"

        del checkouts[str(rel_path)]
        self._save_checkouts(checkouts)

        return True, "Checkout discarded successfully"

if __name__ == "__main__":
    import sys

    if len(sys.argv) < 3:
        print("Usage: python source_control.py <command> <repo_path> [file_path]")
        sys.exit(1)

    command = sys.argv[1]
    repo_path = sys.argv[2]
    sc = SourceControl(repo_path)

    if command == "status":
        print(sc.status())
    elif command in ["checkout", "checkin", "discard"] and len(sys.argv) > 3:
        file_path = sys.argv[3]
        if command == "checkout":
            success, message = sc.checkout(file_path)
        elif command == "checkin":
            success, message = sc.checkin(file_path)
        elif command == "discard":
            success, message = sc.discard_checkout(file_path)
        print(message)
    else:
        print(f"Unknown command: {command}")
