import os
import tarfile
import zipfile
import py7zr
import rarfile
import shutil

def extract_compressed_file(file_path, extract_path=None):
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File not found: {file_path}")

    if extract_path is None:
        extract_path = os.path.dirname(file_path)

    file_extension = os.path.splitext(file_path)[1].lower()

    try:
        if file_extension in ['.tar', '.gz', '.tgz', '.bz2', '.tbz2']:
            with tarfile.open(file_path, 'r:*') as tar:
                tar.extractall(path=extract_path)

        elif file_extension in ['.zip']:
            with zipfile.ZipFile(file_path, 'r') as zip_ref:
                zip_ref.extractall(extract_path)

        elif file_extension in ['.7z']:
            with py7zr.SevenZipFile(file_path, mode='r') as z:
                z.extractall(path=extract_path)

        elif file_extension in ['.rar']:
            with rarfile.RarFile(file_path) as rf:
                rf.extractall(extract_path)

        else:
            raise ValueError(f"Unsupported file format: {file_extension}")

        return extract_path

    except Exception as e:
        raise Exception(f"Error extracting {file_path}: {str(e)}")

def is_archive(file_path):
    supported_extensions = ['.zip', '.tar', '.gz', '.tgz', '.bz2', '.tbz2', '.7z', '.rar']
    return os.path.splitext(file_path)[1].lower() in supported_extensions

def list_archive_contents(file_path):
    file_extension = os.path.splitext(file_path)[1].lower()

    if file_extension in ['.tar', '.gz', '.tgz', '.bz2', '.tbz2']:
        with tarfile.open(file_path, 'r:*') as tar:
            return tar.getnames()

    elif file_extension in ['.zip']:
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            return zip_ref.namelist()

    elif file_extension in ['.7z']:
        with py7zr.SevenZipFile(file_path, mode='r') as z:
            return [f.filename for f in z.getnames()]

    elif file_extension in ['.rar']:
        with rarfile.RarFile(file_path) as rf:
            return rf.namelist()

    else:
        raise ValueError(f"Unsupported file format: {file_extension}")
