// Create a simple garden planner application

// Garden class to manage individual gardens
class Garden {
  constructor(name, width, length) {
    this.name = name;
    this.width = width;
    this.length = length;
    this.plants = [];
  }

  addPlant(plant, x, y) {
    this.plants.push({
      ...plant,
      position: { x, y }
    });
  }

  removePlant(index) {
    this.plants.splice(index, 1);
  }
}

// Plant class to store plant information
class Plant {
  constructor(name, type, season, height, width, color) {
    this.name = name;
    this.type = type;
    this.season = season;
    this.height = height;
    this.width = width;
    this.color = color;
  }
}

// GardenPlanner application
class GardenPlanner {
  constructor() {
    this.gardens = [];
    this.plantCatalog = [];
  }

  createGarden(name, width, length) {
    const garden = new Garden(name, width, length);
    this.gardens.push(garden);
    return garden;
  }

  deleteGarden(index) {
    this.gardens.splice(index, 1);
  }

  addPlantToCatalog(plant) {
    this.plantCatalog.push(plant);
  }

  renderGarden(gardenIndex) {
    const garden = this.gardens[gardenIndex];
    const canvas = document.createElement('canvas');
    canvas.width = garden.width * 50;
    canvas.height = garden.length * 50;
    const ctx = canvas.getContext('2d');

    // Draw soil background
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw grid
    ctx.strokeStyle = '#543D2C';
    ctx.lineWidth = 1;

    for (let x = 0; x <= garden.width; x++) {
      ctx.beginPath();
      ctx.moveTo(x * 50, 0);
      ctx.lineTo(x * 50, canvas.height);
      ctx.stroke();
    }

    for (let y = 0; y <= garden.length; y++) {
      ctx.beginPath();
      ctx.moveTo(0, y * 50);
      ctx.lineTo(canvas.width, y * 50);
      ctx.stroke();
    }

    // Draw plants
    garden.plants.forEach(plant => {
      ctx.fillStyle = plant.color;
      const x = plant.position.x * 50 + 5;
      const y = plant.position.y * 50 + 5;
      ctx.beginPath();
      ctx.arc(x + 20, y + 20, 20, 0, 2 * Math.PI);
      ctx.fill();

      ctx.fillStyle = 'white';
      ctx.font = '10px Arial';
      ctx.fillText(plant.name, x + 5, y + 25);
    });

    return canvas;
  }

  saveGardenPlan(gardenIndex) {
    const garden = this.gardens[gardenIndex];
    return JSON.stringify(garden);
  }

  loadGardenPlan(planData) {
    const garden = JSON.parse(planData);
    this.gardens.push(garden);
    return this.gardens.length - 1;
  }
}

// Example usage
const planner = new GardenPlanner();

// Add some plants to catalog
planner.addPlantToCatalog(new Plant('Tomato', 'Vegetable', 'Summer', 3, 2, '#ff6347'));
planner.addPlantToCatalog(new Plant('Carrot', 'Root', 'Spring', 1, 1, '#ff8c00'));
planner.addPlantToCatalog(new Plant('Lettuce', 'Leafy', 'Spring', 1, 1, '#90ee90'));
planner.addPlantToCatalog(new Plant('Sunflower', 'Flower', 'Summer', 6, 2, '#ffd700'));
