class TestSuite:
    def __init__(self, cloud_provider, region, test_script, output_path):
        self.cloud_provider = cloud_provider
        self.region = region
        self.test_script = test_script
        self.output_path = output_path
        self.test_id = str(uuid.uuid4())
        self.vm_instances = []
        self.setup_logging()

    def setup_logging(self):
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
            handlers=[
                logging.FileHandler(f"test_run_{self.test_id}.log"),
                logging.StreamHandler()
            ]
        )
        self.logger = logging.getLogger(__name__)

    def provision_vms(self, count, vm_config):
        self.logger.info(f"Provisioning {count} VMs in {self.cloud_provider}")

        if self.cloud_provider == "aws":
            return self._provision_aws_vms(count, vm_config)
        elif self.cloud_provider == "azure":
            return self._provision_azure_vms(count, vm_config)
        elif self.cloud_provider == "gcp":
            return self._provision_gcp_vms(count, vm_config)
        else:
            self.logger.error(f"Unsupported cloud provider: {self.cloud_provider}")
            raise ValueError(f"Unsupported cloud provider: {self.cloud_provider}")

    def _provision_aws_vms(self, count, vm_config):
        ec2 = boto3.resource('ec2', region_name=self.region)

        instances = ec2.create_instances(
            ImageId=vm_config.get('image_id'),
            InstanceType=vm_config.get('instance_type', 't2.micro'),
            MinCount=count,
            MaxCount=count,
            KeyName=vm_config.get('key_name'),
            SecurityGroupIds=vm_config.get('security_group_ids', []),
            TagSpecifications=[
                {
                    'ResourceType': 'instance',
                    'Tags': [
                        {'Key': 'Name', 'Value': f'TestVM-{self.test_id}'},
                        {'Key': 'TestId', 'Value': self.test_id}
                    ]
                }
            ]
        )

        instance_ids = [instance.id for instance in instances]
        self.vm_instances.extend(instance_ids)
        self.logger.info(f"Provisioned AWS instances: {instance_ids}")
        return instance_ids

    def _provision_azure_vms(self, count, vm_config):
        credential = DefaultAzureCredential()
        compute_client = ComputeManagementClient(credential, vm_config.get('subscription_id'))

        vm_ids = []
        for i in range(count):
            vm_name = f"testvm-{self.test_id}-{i}"
            async_vm_creation = compute_client.virtual_machines.begin_create_or_update(
                vm_config.get('resource_group'),
                vm_name,
                {
                    'location': self.region,
                    'hardware_profile': {
                        'vm_size': vm_config.get('vm_size', 'Standard_DS1_v2')
                    },
                    'storage_profile': {
                        'image_reference': {
                            'publisher': vm_config.get('publisher'),
                            'offer': vm_config.get('offer'),
                            'sku': vm_config.get('sku'),
                            'version': 'latest'
                        }
                    },
                    'os_profile': {
                        'computer_name': vm_name,
                        'admin_username': vm_config.get('admin_username'),
                        'admin_password': vm_config.get('admin_password')
                    },
                    'network_profile': {
                        'network_interfaces': [{
                            'id': vm_config.get('network_interface_id')
                        }]
                    }
                }
            )
            vm_result = async_vm_creation.result()
            vm_ids.append(vm_result.id)

        self.vm_instances.extend(vm_ids)
        self.logger.info(f"Provisioned Azure VMs: {vm_ids}")
