import requests
from bs4 import BeautifulSoup
import urllib.parse
from collections import deque
import time
import re
from urllib.robotparser import RobotFileParser

class WebCrawler:
    def __init__(self, start_url, max_pages=100, delay=1):
        self.start_url = start_url
        self.max_pages = max_pages
        self.delay = delay
        self.visited_urls = set()
        self.queue = deque([start_url])
        self.downloaded_pages = {}
        self.robots_cache = {}

    def get_robots_parser(self, url):
        parsed_url = urllib.parse.urlparse(url)
        base_url = f"{parsed_url.scheme}://{parsed_url.netloc}"

        if base_url not in self.robots_cache:
            robots_url = f"{base_url}/robots.txt"
            parser = RobotFileParser()
            parser.set_url(robots_url)
            try:
                parser.read()
            except:
                parser = None
            self.robots_cache[base_url] = parser

        return self.robots_cache[base_url]

    def can_fetch(self, url):
        robots_parser = self.get_robots_parser(url)
        if robots_parser:
            return robots_parser.can_fetch("*", url)
        return True

    def normalize_url(self, url, base_url):
        return urllib.parse.urljoin(base_url, url)

    def is_valid_url(self, url):
        parsed = urllib.parse.urlparse(url)
        return bool(parsed.netloc) and bool(parsed.scheme) and parsed.scheme in ['http', 'https']

    def download_page(self, url):
        try:
            headers = {'User-Agent': 'PythonCrawler/1.0'}
            response = requests.get(url, headers=headers, timeout=10)
            if response.status_code == 200 and 'text/html' in response.headers.get('Content-Type', ''):
                return response.text
        except Exception as e:
            print(f"Error downloading {url}: {e}")
        return None

    def extract_links(self, html, base_url):
        links = set()
        soup = BeautifulSoup(html, 'html.parser')
        for a_tag in soup.find_all('a', href=True):
            link = self.normalize_url(a_tag['href'], base_url)
            if self.is_valid_url(link):
                links.add(link)
        return links

    def crawl(self):
        count = 0

        while self.queue and count < self.max_pages:
            url = self.queue.popleft()

            if url in self.visited_urls:
                continue

            if not self.can_fetch(url):
                print(f"Skipping {url} (disallowed by robots.txt)")
                self.visited_urls.add(url)
                continue

            print(f"Crawling: {url}")
            html = self.download_page(url)

            if html:
                self.downloaded_pages[url] = html
                self.visited_urls.add(url)
                count += 1

                links = self.extract_links(html, url)
                for link in links:
                    if link not in self.visited_urls:
                        self.queue.append(link)

            time.sleep(self.delay)

        print(f"Crawling complete. Downloaded {len(self.downloaded_pages)} pages.")
        return self.downloaded_pages

if __name__ == "__main__":
    crawler = WebCrawler("https://example.com", max_pages=10, delay=2)
    pages = crawler.crawl()
