from flask import Flask, render_template, request, redirect, url_for, flash
from flask_sqlalchemy import SQLAlchemy
from flask_login import LoginManager, UserMixin, login_user, logout_user, login_required, current_user
from werkzeug.security import generate_password_hash, check_password_hash

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///apartments.db'
db = SQLAlchemy(app)
login_manager = LoginManager(app)
login_manager.login_view = 'login'

class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(50), unique=True, nullable=False)
    password_hash = db.Column(db.String(100), nullable=False)
    is_admin = db.Column(db.Boolean, default=False)
    listings = db.relationship('Apartment', backref='owner', lazy=True)

class Apartment(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    unit_number = db.Column(db.String(10), nullable=False)
    bedrooms = db.Column(db.Integer, nullable=False)
    bathrooms = db.Column(db.Float, nullable=False)
    rent = db.Column(db.Float, nullable=False)
    available = db.Column(db.Boolean, default=True)
    description = db.Column(db.Text)
    owner_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    amenities = db.relationship('Amenity', backref='apartment', lazy=True)

class Amenity(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(50), nullable=False)
    apartment_id = db.Column(db.Integer, db.ForeignKey('apartment.id'), nullable=False)

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@app.route('/')
def index():
    apartments = Apartment.query.filter_by(available=True).all()
    return render_template('index.html', apartments=apartments)

@app.route('/apartment/<int:id>')
def apartment_detail(id):
    apartment = Apartment.query.get_or_404(id)
    return render_template('apartment_detail.html', apartment=apartment)

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        if User.query.filter_by(username=username).first():
            flash('Username already exists')
            return redirect(url_for('register'))

        new_user = User(
            username=username,
            password_hash=generate_password_hash(password)
        )
        db.session.add(new_user)
        db.session.commit()

        flash('Account created successfully')
        return redirect(url_for('login'))

    return render_template('register.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        user = User.query.filter_by(username=username).first()

        if not user or not check_password_hash(user.password_hash, password):
            flash('Invalid username or password')
            return redirect(url_for('login'))

        login_user(user)
        return redirect(url_for('index'))

    return render_template('login.html')

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('index'))

@app.route('/add_listing', methods=['GET', 'POST'])
@login_required
def add_listing():
    if request.method == 'POST':
        unit_number = request.form['unit_number']
        bedrooms = request.form['bedrooms']
        bathrooms = request.form['bathrooms']
        rent = request.form['rent']
        description = request.form['description']

        new_apartment = Apartment(
            unit_number=unit_number,
            bedrooms=bedrooms,
            bathrooms=bathrooms,
            rent=rent,
            description=description,
            owner=current_user
        )
        db.session.add(new_apartment)
        db.session.commit()

        amenities = request.form.getlist('amenities')
        for amenity_name in amenities:
            new_amenity = Amenity(name=amenity_name, apartment=new_apartment)
            db.session.add(new_amenity)
        db.session.commit()

        flash('Listing added successfully')
        return redirect(url_for('my_listings'))

    return render_template('add_listing.html')

@app.route('/my_listings')
@login_required
def my_listings():
    apartments = Apartment.query.filter_by(owner=current_user).all()
    return render_template('my_listings.html', apartments=apartments)

@app.route('/edit_listing/<int:id>', methods=['GET', 'POST'])
@login_required
def edit_listing(id):
    apartment = Apartment.query.get_or_404(id)

    if apartment.owner != current_user and not current_user.is_admin:
        flash('You do not have permission to edit this listing')
        return redirect(url_for('index'))

    if request.method == 'POST':
        apartment.unit_number = request.form['unit_number']
        apartment.bedrooms = request.form['bedrooms']
        apartment.bathrooms = request.form['bathrooms']
        apartment.rent = request.form['rent']
        apartment.description = request.form['description']
        apartment.available = 'available' in request.form

        for amenity in apartment.amenities:
            db.session.delete(amenity)

        amenities = request.form.getlist('amenities')
        for amenity_name in amenities:
            new_amenity = Amenity(name=amenity_name, apartment=apartment)
            db.session.add(new_amenity)

        db.session.commit()
        flash('Listing updated successfully')
        return redirect(url_for('my_listings'))

    return render_template('edit_listing.html', apartment=apartment)

@app.route('/delete_listing/<int:id>')
@login_required
def delete_listing(id):
    apartment = Apartment.query.get_or_404(id)

    if apartment.owner != current_user and not current_user.is_admin:
        flash('You do not have permission to delete this listing')
        return redirect(url_for('index'))

    for amenity in apartment.amenities:
        db.session.delete(amenity)

    db.session.delete(apartment)
    db.session.commit()
    flash('Listing deleted successfully')
    return redirect(url_for('my_listings'))

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(debug=True)
