import os
import hashlib
import shutil
import json
from pathlib import Path
from typing import Dict, List, Optional, Union
import tarfile
import tempfile

class ArtifactManager:
    def __init__(self, repository_path: str):
        self.repository_path = Path(repository_path)
        self.repository_path.mkdir(parents=True, exist_ok=True)
        self.index_path = self.repository_path / "index.json"
        self.artifacts_path = self.repository_path / "artifacts"
        self.artifacts_path.mkdir(exist_ok=True)
        self._load_index()

    def _load_index(self):
        if self.index_path.exists():
            with open(self.index_path, 'r') as f:
                self.index = json.load(f)
        else:
            self.index = {}
            self._save_index()

    def _save_index(self):
        with open(self.index_path, 'w') as f:
            json.dump(self.index, f, indent=2)

    def _compute_hash(self, file_path: Union[str, Path]) -> str:
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(8192), b''):
                sha256.update(chunk)
        return sha256.hexdigest()

    def add_artifact(self, file_path: Union[str, Path], 
                    name: str, 
                    version: str, 
                    metadata: Optional[Dict] = None) -> str:
        file_path = Path(file_path)
        if not file_path.exists():
            raise FileNotFoundError(f"Artifact file {file_path} not found")

        artifact_hash = self._compute_hash(file_path)
        artifact_info = {
            "name": name,
            "version": version,
            "hash": artifact_hash,
            "original_filename": file_path.name,
            "metadata": metadata or {},
            "added_at": os.path.getmtime(file_path)
        }

        target_path = self.artifacts_path / artifact_hash

        if not target_path.exists():
            shutil.copy2(file_path, target_path)

        artifact_id = f"{name}-{version}"
        self.index[artifact_id] = artifact_info
        self._save_index()

        return artifact_id

    def get_artifact(self, name: str, version: str) -> Optional[Path]:
        artifact_id = f"{name}-{version}"
        if artifact_id not in self.index:
            return None

        artifact_hash = self.index[artifact_id]["hash"]
        artifact_path = self.artifacts_path / artifact_hash

        if not artifact_path.exists():
            return None

        return artifact_path

    def export_artifact(self, name: str, version: str, target_path: Union[str, Path]) -> bool:
        artifact_path = self.get_artifact(name, version)
        if not artifact_path:
            return False

        target_path = Path(target_path)
        if target_path.is_dir():
            original_name = self.index[f"{name}-{version}"]["original_filename"]
            target_path = target_path / original_name

        shutil.copy2(artifact_path, target_path)
        return True

    def remove_artifact(self, name: str, version: str) -> bool:
        artifact_id = f"{name}-{version}"
        if artifact_id not in self.index:
            return False

        artifact_hash = self.index[artifact_id]["hash"]
        artifact_path = self.artifacts_path / artifact_hash

        if artifact_path.exists():
            if not self._is_hash_referenced_elsewhere(artifact_hash, artifact_id):
                artifact_path.unlink()

        del self.index[artifact_id]
        self._save_index()
        return True

    def _is_hash_referenced_elsewhere(self, hash_value: str, current_id: str) -> bool:
        for artifact_id, info in self.index.items():
            if artifact_id != current_id and info["hash"] == hash_value:
                return True
        return False

    def list_artifacts(self, name_filter: Optional[str] = None) -> List[Dict]:
        results = []
        for artifact_id, info in self.index.items():
            if not name_filter or name_filter in info["name"]:
                results.append({
                    "id": artifact_id,
                    **info
                })
        return results

    def create_package(self, artifacts: List[Dict[str, str]], output_path: Union[str, Path]) -> Path:
        with tempfile.TemporaryDirectory() as tmpdir:
            tmp_path = Path(tmpdir)
            manifest = []

            for artifact in artifacts:
                name = artifact["name"]
                version = artifact["version"]
                output_name = artifact.get("output_name", f"{name}-{version}")

                artifact_path = self.get_artifact(name, version)
                if not artifact_path:
                    raise ValueError(f"Artifact {name}-{version} not found")

                dest_path = tmp_path / output_name
                shutil.copy2(artifact_path, dest_path)

                artifact_info = self.index[f"{name}-{version}"]
                manifest.append({
                    "name": name,
                    "version": version,
                    "hash": artifact_info["hash"],
                    "path": output_name,
                    "metadata": artifact_info["metadata"]
                })

            with open(tmp_path / "manifest.json", "w") as f:
                json.dump(manifest, f, indent=2)

            output_path = Path(output_path)
            with tarfile.open(output_path, "w:gz") as tar:
                for file_path in tmp_path.iterdir():
                    tar.add(file_path, arcname=file_path.name)

            return output_path
