    try:
        schema = json.loads(schema_str)
    except json.JSONDecodeError as e:
        return [f"JSON parsing error: {str(e)}"]

    validator_cls = get_validator_class(schema_version)
    errors = []

    try:
        validator_cls.check_schema(schema)
    except jsonschema.exceptions.SchemaError as e:
        errors.append(f"Schema validation error: {str(e)}")

    return errors

def main():
    import sys

    if len(sys.argv) > 1:
        with open(sys.argv[1], 'r') as f:
            schema_str = f.read()

        schema_version = sys.argv[2] if len(sys.argv) > 2 else "draft7"
        errors = lint_schema(schema_str, schema_version)

        if errors:
            print("Schema contains errors:")
            for error in errors:
                print(f"- {error}")
            sys.exit(1)
        else:
            print("Schema is valid.")
    else:
