import io
import zipfile
from typing import List, Union, Optional, BinaryIO
import boto3
from botocore.exceptions import ClientError


class CloudZipExtractor:
    def __init__(self, s3_client=None, azure_client=None, gcp_client=None):
        self.s3_client = s3_client or boto3.client('s3')
        self.azure_client = azure_client
        self.gcp_client = gcp_client

    def extract_from_s3(self, bucket: str, key: str, 
                        extract_path: Optional[str] = None,
                        password: Optional[bytes] = None) -> List[str]:
        try:
            response = self.s3_client.get_object(Bucket=bucket, Key=key)
            zip_content = response['Body'].read()
            return self._extract_zip(zip_content, extract_path, password)
        except ClientError as e:
            raise Exception(f"Failed to retrieve S3 object: {e}")

    def extract_from_stream(self, stream: BinaryIO, 
                           extract_path: Optional[str] = None,
                           password: Optional[bytes] = None) -> List[str]:
        zip_content = stream.read()
        return self._extract_zip(zip_content, extract_path, password)

    def _extract_zip(self, zip_content: bytes, 
                    extract_path: Optional[str] = None,
                    password: Optional[bytes] = None) -> List[str]:
        extracted_files = []

        with io.BytesIO(zip_content) as zip_buffer:
            with zipfile.ZipFile(zip_buffer) as zip_file:
                if password:
                    zip_file.setpassword(password)

                for file_info in zip_file.infolist():
                    extracted_files.append(file_info.filename)

                    if extract_path:
                        zip_file.extract(file_info, extract_path)

        return extracted_files

    def list_zip_contents(self, bucket: str, key: str, 
                         password: Optional[bytes] = None) -> List[str]:
        response = self.s3_client.get_object(Bucket=bucket, Key=key)
        zip_content = response['Body'].read()

        with io.BytesIO(zip_content) as zip_buffer:
            with zipfile.ZipFile(zip_buffer) as zip_file:
                if password:
                    zip_file.setpassword(password)
                return zip_file.namelist()

    def extract_file_from_s3(self, bucket: str, key: str, 
                            file_path: str, output_path: Optional[str] = None,
                            password: Optional[bytes] = None) -> bool:
        response = self.s3_client.get_object(Bucket=bucket, Key=key)
        zip_content = response['Body'].read()

        with io.BytesIO(zip_content) as zip_buffer:
            with zipfile.ZipFile(zip_buffer) as zip_file:
                if password:
                    zip_file.setpassword(password)

                if file_path in zip_file.namelist():
                    if output_path:
                        zip_file.extract(file_path, output_path)
                        return True
                    else:
                        return zip_file.read(file_path)
                else:
                    return False
