import os
import json
import shutil
import hashlib
import datetime

class VersionControl:
    def __init__(self, repo_path):
        self.repo_path = repo_path
        self.vcs_dir = os.path.join(repo_path, '.vcs')
        self.objects_dir = os.path.join(self.vcs_dir, 'objects')
        self.metadata_dir = os.path.join(self.vcs_dir, 'metadata')
        self.init_repo()

    def init_repo(self):
        if not os.path.exists(self.vcs_dir):
            os.makedirs(self.vcs_dir)
            os.makedirs(self.objects_dir)
            os.makedirs(self.metadata_dir)
            self.create_head()

    def create_head(self):
        head_file = os.path.join(self.vcs_dir, 'HEAD')
        with open(head_file, 'w') as f:
            f.write('')

    def hash_content(self, content):
        return hashlib.sha256(content.encode()).hexdigest()

    def store_object(self, content):
        object_id = self.hash_content(content)
        object_path = os.path.join(self.objects_dir, object_id)
        if not os.path.exists(object_path):
            with open(object_path, 'w') as f:
                f.write(content)
        return object_id

    def get_file_permissions(self, file_path):
        if not os.path.exists(file_path):
            return None
        return {
            'mode': oct(os.stat(file_path).st_mode)[-3:],
            'owner': os.stat(file_path).st_uid,
            'group': os.stat(file_path).st_gid,
        }

    def add(self, path):
        rel_path = os.path.relpath(path, self.repo_path)
        if os.path.isfile(path):
            with open(path, 'r') as f:
                content = f.read()
            object_id = self.store_object(content)
            metadata = {
                'type': 'file',
                'permissions': self.get_file_permissions(path),
                'object_id': object_id,
                'timestamp': datetime.datetime.now().isoformat()
            }
            self.store_metadata(rel_path, metadata)
        elif os.path.isdir(path):
            self.add_directory(path)

    def add_directory(self, dir_path):
        rel_path = os.path.relpath(dir_path, self.repo_path)
        if rel_path == '.vcs':
