        metadata = {
            'type': 'directory',
            'permissions': self.get_file_permissions(dir_path),
            'timestamp': datetime.datetime.now().isoformat(),
            'contents': []
        }

        for item in os.listdir(dir_path):
            item_path = os.path.join(dir_path, item)
            if os.path.isdir(item_path) and item != '.vcs':
                self.add_directory(item_path)
                metadata['contents'].append(item)
            elif os.path.isfile(item_path):
                self.add(item_path)
                metadata['contents'].append(item)

        self.store_metadata(rel_path, metadata)

