from pathlib import Path

def find_large_files(dirpath, threshold):
    files = []
    for f in Path(dirpath).glob('**/*'):
        if f.is_file() and f.stat().st_size > threshold:
            files.append(f)
    return files

def change_permissions(filepath, mode):
    try:
        os.chmod(filepath, mode)
        return True
    except OSError:
        return False

def remove_large_files(files):
    removed = []
    for f in files:
        try:
            filepath = str(f)
            print(f"Removing {filepath} ({f.stat().st_size} bytes)")
            os.remove(filepath)
            removed.append(f)
        except OSError as e:
            print(f"Failed to remove {filepath}: {e}")
    return removed

def main():
    import argparse

    parser = argparse.ArgumentParser(description="Manage large files on disk")
    parser.add_argument("directory", help="Directory to scan")
    parser.add_argument("--threshold", type=int, default=100000000, 
                        help="Size threshold in bytes (default: 100MB)")
    parser.add_argument("--action", choices=["list", "delete", "chmod"], default="list",
                        help="Action to perform on large files")
    parser.add_argument("--permissions", type=int, default=0o644,
                        help="Permissions to set if using chmod action (octal)")

    args = parser.parse_args()

    files = find_large_files(args.directory, args.threshold)

    if args.action == "list":
        total_size = sum(f.stat().st_size for f in files)
        for f in files:
            print(f"{f} - {f.stat().st_size} bytes")
        print(f"Found {len(files)} files over {args.threshold} bytes, total size: {total_size} bytes")

    elif args.action == "delete":
        confirmation = input(f"Are you sure you want to delete {len(files)} files? (y/n): ")
        if confirmation.lower() == 'y':
            removed = remove_large_files(files)
            print(f"Removed {len(removed)} files over threshold size")
        else:
            print("Operation cancelled")

    elif args.action == "chmod":
        changed = 0
        for f in files:
            if change_permissions(str(f), args.permissions):
                changed += 1
                print(f"Changed permissions for {f}")
        print(f"Changed permissions for {changed} of {len(files)} files")

if __name__ == "__main__":
    main()
