    try:
        data = request.get_json() if request.is_json else yaml.safe_load(request.form['redeem_data'])
        user_id = data.get('user_id')
        points = int(data.get('points', 0))
        reward_type = data.get('reward_type', 'cash')

        if not user_id or points <= 0:
            return jsonify({'error': 'Invalid user ID or points value'}), 400

        if user_id not in user_rewards:
            user_rewards[user_id] = {'points': 0, 'redeemed': 0}

        if user_rewards[user_id]['points'] < points:
            return jsonify({'error': 'Insufficient points balance'}), 400

        user_rewards[user_id]['points'] -= points
        user_rewards[user_id]['redeemed'] += points

        conversion_rate = 0.01
        value = points * conversion_rate

        return jsonify({
            'message': 'Points redeemed!',
            'user_id': user_id,
            'points_redeemed': points,
            'reward_type': reward_type,
            'value': value,
            'remaining_points': user_rewards[user_id]['points']
        })
    except Exception as e:
        return jsonify({'error': str(e)}), 500

