import os
import socket
import zlib
import hashlib
import json
import threading
import time
from pathlib import Path
from typing import Dict, List, Optional, Tuple, Set

class DistributedFS:
    def __init__(self, local_storage_path: str, port: int = 8000):
        self.local_storage_path = Path(local_storage_path)
        self.local_storage_path.mkdir(exist_ok=True, parents=True)
        self.port = port
        self.peers = set()
        self.block_map = {}
        self.file_map = {}
        self.load_metadata()

    def load_metadata(self):
        metadata_path = self.local_storage_path / "metadata.json"
        if metadata_path.exists():
            with open(metadata_path, "r") as f:
                data = json.load(f)
                self.block_map = data.get("block_map", {})
                self.file_map = data.get("file_map", {})

    def save_metadata(self):
        metadata_path = self.local_storage_path / "metadata.json"
        with open(metadata_path, "w") as f:
            json.dump({
                "block_map": self.block_map,
                "file_map": self.file_map
            }, f)

    def add_peer(self, host: str, port: int = 8000):
        self.peers.add((host, port))

    def remove_peer(self, host: str, port: int = 8000):
        self.peers.discard((host, port))

    def split_file(self, file_path: str, block_size: int = 1024*1024) -> List[str]:
        block_hashes = []
        file_path = Path(file_path)

        with open(file_path, "rb") as f:
            while True:
                block_data = f.read(block_size)
                if not block_data:
                    break

                compressed_data = zlib.compress(block_data)
                block_hash = hashlib.sha256(compressed_data).hexdigest()
                block_hashes.append(block_hash)

                block_path = self.local_storage_path / block_hash
                if not block_path.exists():
                    with open(block_path, "wb") as block_file:
                        block_file.write(compressed_data)

        self.file_map[str(file_path)] = block_hashes
        self.save_metadata()
        return block_hashes

    def reconstruct_file(self, file_path: str, output_path: str) -> bool:
        if file_path not in self.file_map:
            return self.fetch_file_from_peers(file_path, output_path)

        block_hashes = self.file_map[file_path]
        with open(output_path, "wb") as out_file:
            for block_hash in block_hashes:
                block_path = self.local_storage_path / block_hash
                if not block_path.exists():
                    if not self.fetch_block_from_peers(block_hash):
                        return False

                with open(block_path, "rb") as block_file:
                    compressed_data = block_file.read()
                    data = zlib.decompress(compressed_data)
                    out_file.write(data)
        return True

    def fetch_block_from_peers(self, block_hash: str) -> bool:
        for peer in self.peers:
            try:
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                    s.connect(peer)
                    s.sendall(f"GET_BLOCK {block_hash}".encode())
                    response = s.recv(4096)

                    if response.startswith(b"BLOCK "):
                        compressed_data = response[6:]
                        block_path = self.local_storage_path / block_hash
                        with open(block_path, "wb") as f:
                            f.write(compressed_data)
                        return True
            except:
                pass
        return False

    def fetch_file_from_peers(self, file_path: str, output_path: str) -> bool:
        for peer in self.peers:
            try:
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                    s.connect(peer)
                    s.sendall(f"GET_FILE_INFO {file_path}".encode())
                    response = s.recv(4096).decode()

                    if response.startswith("FILE_INFO "):
                        block_hashes = json.loads(response[10:])
                        self.file_map[file_path] = block_hashes
                        self.save_metadata()
                        return self.reconstruct_file(file_path, output_path)
            except:
                pass
        return False

    def start_server(self):
        server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        server.bind(('0.0.0.0', self.port))
        server.listen(5)

        while True:
            client, _ = server.accept()
            threading.Thread(target=self.handle_client, args=(client,)).start()

    def handle_client(self, client):
        try:
            data = client.recv(1024).decode()

            if data.startswith("GET_BLOCK "):
                block_hash = data[10:]
                block_path = self.local_storage_path / block_hash

                if block_path.exists():
                    with open(block_path, "rb") as f:
                        compressed_data = f.read()
                        client.sendall(b"BLOCK " + compressed_data)
                else:
                    client.sendall(b"ERROR Block not found")

            elif data.startswith("GET_FILE_INFO "):
                file_path = data[13:]

                if file_path in self.file_map:
                    block_hashes = self.file_map[file_path]
                    client.sendall(f"FILE_INFO {json.dumps(block_hashes)}".encode())
                else:
                    client.sendall(b"ERROR File not found")
        except:
            pass
        finally:
            client.close()

    def sync_with_peers(self):
        for peer in self.peers:
            try:
                with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
                    s.connect(peer)
                    s.sendall(b"LIST_FILES")
                    response = s.recv(8192).decode()

                    if response.startswith("FILES "):
                        peer_files = json.loads(response[6:])
                        for file_path, blocks in peer_files.items():
                            if file_path not in self.file_map:
                                self.file_map[file_path] = blocks
                                self.save_metadata()
            except:
                pass
