import os
import zipfile
import tarfile
import gzip
import bz2
import shutil
import patoolib
import py7zr

def extract_zip(zip_path, extract_to=None):
    if extract_to is None:
        extract_to = os.path.dirname(zip_path)
    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        zip_ref.extractall(extract_to)
    return extract_to

def extract_tar(tar_path, extract_to=None):
    if extract_to is None:
        extract_to = os.path.dirname(tar_path)
    with tarfile.open(tar_path) as tar_ref:
        tar_ref.extractall(extract_to)
    return extract_to

def extract_gz(gz_path, extract_to=None):
    if extract_to is None:
        extract_to = os.path.dirname(gz_path)
    output_path = os.path.join(extract_to, os.path.basename(gz_path)[:-3])
    with gzip.open(gz_path, 'rb') as f_in:
        with open(output_path, 'wb') as f_out:
            shutil.copyfileobj(f_in, f_out)
    return output_path

def extract_bz2(bz2_path, extract_to=None):
    if extract_to is None:
        extract_to = os.path.dirname(bz2_path)
    output_path = os.path.join(extract_to, os.path.basename(bz2_path)[:-4])
    with bz2.open(bz2_path, 'rb') as f_in:
        with open(output_path, 'wb') as f_out:
            shutil.copyfileobj(f_in, f_out)
    return output_path

def extract_7z(seven_z_path, extract_to=None):
    if extract_to is None:
        extract_to = os.path.dirname(seven_z_path)
    with py7zr.SevenZipFile(seven_z_path, 'r') as seven_z_ref:
        seven_z_ref.extractall(extract_to)
    return extract_to

def extract_rar(rar_path, extract_to=None):
    if extract_to is None:
        extract_to = os.path.dirname(rar_path)
    patoolib.extract_archive(rar_path, outdir=extract_to)
    return extract_to

def extract_archive(archive_path, extract_to=None):
    if extract_to is None:
        extract_to = os.path.dirname(archive_path)

    if not os.path.exists(extract_to):
        os.makedirs(extract_to)

    ext = os.path.splitext(archive_path)[1].lower()

    if ext == '.zip':
        return extract_zip(archive_path, extract_to)
    elif ext in ['.tar', '.tgz']:
        return extract_tar(archive_path, extract_to)
    elif ext == '.gz' and not archive_path.endswith('.tar.gz'):
        return extract_gz(archive_path, extract_to)
    elif ext == '.bz2' and not archive_path.endswith('.tar.bz2'):
        return extract_bz2(archive_path, extract_to)
    elif ext == '.7z':
        return extract_7z(archive_path, extract_to)
    elif ext == '.rar':
        return extract_rar(archive_path, extract_to)
    else:
        try:
            patoolib.extract_archive(archive_path, outdir=extract_to)
            return extract_to
        except Exception as e:
            raise ValueError(f"Unsupported archive format: {ext}")

if __name__ == "__main__":
    import sys
    if len(sys.argv) > 1:
        archive_path = sys.argv[1]
        extract_to = sys.argv[2] if len(sys.argv) > 2 else None
        result = extract_archive(archive_path, extract_to)
        print(f"Extracted to: {result}")
    else:
        print("Usage: python extract.py [archive_path] [extract_to (optional)]")
