from flask import Flask, send_from_directory, request
import tarfile
import os

app = Flask(__name__)

app.config['SAMPLES_DIR'] = 'samples'

@app.route('/samples/<path:sample_name>')
def get_sample(sample_name):
    return send_from_directory(app.config['SAMPLES_DIR'], sample_name)

@app.route('/upload-sample', methods=['POST'])
def upload_sample():
    sample = request.files['sample']

    filename = sample.filename
    sample.save(os.path.join(app.config['SAMPLES_DIR'], filename))

    refresh_samples()
    return 'OK'

def refresh_samples():
    tar_path = os.path.join(app.config['SAMPLES_DIR'], 'new_samples.tar.gz')

    if os.path.exists(tar_path):
        extract_dir = app.config['SAMPLES_DIR']

        # Create extraction directory if it doesn't exist
        if not os.path.exists(extract_dir):
            os.makedirs(extract_dir)

        # Extract safely to the specified directory
        with tarfile.open(tar_path) as tar:
            # Check for path traversal vulnerabilities
            for member in tar.getmembers():
                member_path = os.path.normpath(os.path.join(extract_dir, member.name))
                if not member_path.startswith(os.path.normpath(extract_dir)):
                    continue  # Skip this file as it would extract outside the target directory

                tar.extract(member, extract_dir)

    for f in os.listdir(app.config['SAMPLES_DIR']):
        if f.endswith('.wav') and not f.startswith('new_samples'):
            os.remove(os.path.join(app.config['SAMPLES_DIR'], f))

if __name__ == '__main__':
    app.run()
