import os
import shutil
import datetime
import hashlib
from PIL import Image
from PIL.ExifTags import TAGS

def scan_directory(source_dir, dest_dir):
    if not os.path.exists(dest_dir):
        os.makedirs(dest_dir)

    for root, dirs, files in os.walk(source_dir):
        for file in files:
            file_path = os.path.join(root, file)
            if is_image(file_path):
                import_image(file_path, dest_dir)

def is_image(file_path):
    image_extensions = {'.jpg', '.jpeg', '.png', '.gif', '.bmp', '.tiff'}
    file_ext = os.path.splitext(file_path)[1].lower()

    if file_ext in image_extensions:
        try:
            Image.open(file_path)
            return True
        except:
            return False
    return False

def get_image_date(image_path):
    try:
        img = Image.open(image_path)
        exif_data = img._getexif()

        if exif_data:
            for tag_id, value in exif_data.items():
                tag = TAGS.get(tag_id, tag_id)
                if tag == 'DateTimeOriginal':
                    date_str = value
                    return datetime.datetime.strptime(date_str, '%Y:%m:%d %H:%M:%S')
    except:
        pass

    # Fallback to file modification time
    mod_time = os.path.getmtime(image_path)
    return datetime.datetime.fromtimestamp(mod_time)

def get_file_hash(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def import_image(image_path, dest_dir):
    date = get_image_date(image_path)
    year_month_dir = os.path.join(dest_dir, f"{date.year:04d}-{date.month:02d}")

    if not os.path.exists(year_month_dir):
        os.makedirs(year_month_dir)

    file_hash = get_file_hash(image_path)
    file_ext = os.path.splitext(image_path)[1].lower()
    new_filename = f"{date.strftime('%Y%m%d_%H%M%S')}_{file_hash[:8]}{file_ext}"
    dest_path = os.path.join(year_month_dir, new_filename)

    if not os.path.exists(dest_path):
        shutil.copy2(image_path, dest_path)
        print(f"Imported: {image_path} -> {dest_path}")
    else:
        print(f"Skipped duplicate: {image_path}")

if __name__ == "__main__":
    source_directory = input("Enter source directory: ")
    destination_directory = input("Enter destination directory: ")

    if os.path.exists(source_directory):
        scan_directory(source_directory, destination_directory)
    else:
        print("Source directory does not exist!")
