import tarfile
import os
import zipfile
import gzip
import shutil

def extract_all(tar_archive):
    if tar_archive.endswith('.tar.gz') or tar_archive.endswith('.tgz'):
        tar = tarfile.open(tar_archive)
        tar.extractall()
        tar.close()
    elif tar_archive.endswith('.zip'):
        with zipfile.ZipFile(tar_archive, 'r') as zip_ref:
            zip_ref.extractall()
    elif tar_archive.endswith('.gz') and not tar_archive.endswith('.tar.gz'):
        with gzip.open(tar_archive, 'rb') as f_in:
            with open(tar_archive[:-3], 'wb') as f_out:
                shutil.copyfileobj(f_in, f_out)

def extract_single_file(archive_path, file_path, destination=None):
    if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
        with tarfile.open(archive_path) as tar:
            member = tar.getmember(file_path)
            if destination:
                tar.extract(member, path=destination)
            else:
                tar.extract(member)
    elif archive_path.endswith('.zip'):
        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            if destination:
                zip_ref.extract(file_path, path=destination)
            else:
                zip_ref.extract(file_path)

def list_archive_contents(archive_path):
    if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
        with tarfile.open(archive_path) as tar:
            return tar.getnames()
    elif archive_path.endswith('.zip'):
        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            return zip_ref.namelist()

