import os
import subprocess

def git_init(repo_path):
    os.makedirs(repo_path, exist_ok=True)
    subprocess.run(['git', 'init'], cwd=repo_path)

def git_clone(repo_url, target_path):
    subprocess.run(['git', 'clone', repo_url, target_path])

def git_add(repo_path, file_pattern):
    subprocess.run(['git', 'add', file_pattern], cwd=repo_path)

def git_commit(repo_path, message):
    subprocess.run(['git', 'commit', '-m', message], cwd=repo_path)

def git_push(repo_path, remote='origin', branch='main'):
    subprocess.run(['git', 'push', remote, branch], cwd=repo_path)

def git_pull(repo_path, remote='origin', branch='main'):
    subprocess.run(['git', 'pull', remote, branch], cwd=repo_path)

def git_status(repo_path):
    result = subprocess.run(['git', 'status'], cwd=repo_path, text=True, capture_output=True)
    return result.stdout

def git_log(repo_path, n=5):
    result = subprocess.run(['git', 'log', f'-{n}', '--oneline'], cwd=repo_path, text=True, capture_output=True)
    return result.stdout

def git_branch(repo_path, new_branch=None):
    if new_branch:
        subprocess.run(['git', 'checkout', '-b', new_branch], cwd=repo_path)
    else:
        result = subprocess.run(['git', 'branch'], cwd=repo_path, text=True, capture_output=True)
        return result.stdout

if __name__ == "__main__":
    repo_dir = "my_git_repo"
    git_init(repo_dir)

    with open(f"{repo_dir}/example.txt", "w") as f:
        f.write("Initial content")

    git_add(repo_dir, ".")
    git_commit(repo_dir, "Initial commit")

    print(git_status(repo_dir))
