def add_note(content, tags=None):
    if not NOTES_DIR.exists():
        NOTES_DIR.mkdir(parents=True)

    timestamp = datetime.datetime.now().isoformat()
    note_id = hashlib.md5(f"{timestamp}{content}".encode()).hexdigest()[:10]

    note_content = f"# Note {note_id}\nCreated: {timestamp}\n"
    if tags:
        note_content += f"Tags: {', '.join(tags)}\n"
    note_content += f"\n{content}\n"

    note_path = NOTES_DIR / note_id
    with open(note_path, 'w') as f:
        f.write(note_content)

    return note_id

def list_notes(tag=None):
    if not NOTES_DIR.exists():
        return []

