        if path.is_symlink():
            path = path.resolve()
        try:
            with open(path, 'r') as f:
                content = f.read()
                if tag:
                    tag_match = re.search(r'Tags: (.*)', content)
                    if not tag_match or tag.lower() not in tag_match.group(1).lower():
                        continue
