class Stock:
    def __init__(self, symbol):
        self.symbol = symbol
        self.data = None
        self.refresh_data()

    def refresh_data(self):
        self.data = yf.Ticker(self.symbol)

    def get_current_price(self):
        self.refresh_data()
        return self.data.info.get('regularMarketPrice', 0)

    def get_historical_data(self, period="1mo"):
        return self.data.history(period=period)

class Portfolio:
    def __init__(self, initial_cash=10000):
        self.cash = initial_cash
        self.holdings = {}
        self.transaction_history = []

    def buy(self, symbol, quantity, price):
        cost = quantity * price
        if cost > self.cash:
            return False, "Insufficient funds"

        if symbol in self.holdings:
            self.holdings[symbol]['quantity'] += quantity
            self.holdings[symbol]['total_cost'] += cost
        else:
            self.holdings[symbol] = {
                'quantity': quantity,
                'total_cost': cost
            }

        self.cash -= cost
        self.transaction_history.append({
            'type': 'BUY',
            'symbol': symbol,
            'quantity': quantity,
            'price': price,
            'timestamp': datetime.now()
        })
        return True, f"Bought {quantity} shares of {symbol} at ${price:.2f}"

    def sell(self, symbol, quantity, price):
        if symbol not in self.holdings:
            return False, f"You don't own any shares of {symbol}"

        if quantity > self.holdings[symbol]['quantity']:
            return False, f"You don't have enough shares of {symbol}"

        proceeds = quantity * price
        self.cash += proceeds
        self.holdings[symbol]['quantity'] -= quantity

        if self.holdings[symbol]['quantity'] == 0:
            del self.holdings[symbol]

        self.transaction_history.append({
            'type': 'SELL',
            'symbol': symbol,
            'quantity': quantity,
            'price': price,
            'timestamp': datetime.now()
        })
        return True, f"Sold {quantity} shares of {symbol} at ${price:.2f}"

    def get_portfolio_value(self, stock_prices=None):
        total_value = self.cash
        for symbol, details in self.holdings.items():
            if stock_prices and symbol in stock_prices:
                price = stock_prices[symbol]
            else:
                price = Stock(symbol).get_current_price()
            total_value += details['quantity'] * price
        return total_value

    def get_portfolio_summary(self, stock_prices=None):
        summary = []
