import datetime
import uuid
from typing import List, Dict, Optional

class Person:
    def __init__(self, name: str, email: str, phone: str):
        self.id = str(uuid.uuid4())
        self.name = name
        self.email = email
        self.phone = phone

class Tenant(Person):
    def __init__(self, name: str, email: str, phone: str, credit_score: int = 0):
        super().__init__(name, email, phone)
        self.credit_score = credit_score
        self.rent_history: List[RentPayment] = []

class Property:
    def __init__(self, address: str, bedrooms: int, bathrooms: int, rent: float, owner_id: str):
        self.id = str(uuid.uuid4())
        self.address = address
        self.bedrooms = bedrooms
        self.bathrooms = bathrooms
        self.rent = rent
        self.owner_id = owner_id
        self.status = "available"
        self.tenant_id = None

class RentPayment:
    def __init__(self, tenant_id: str, property_id: str, amount: float):
        self.id = str(uuid.uuid4())
        self.tenant_id = tenant_id
        self.property_id = property_id
        self.amount = amount
        self.date = datetime.datetime.now()
        self.status = "pending"

class MaintenanceRequest:
    def __init__(self, property_id: str, description: str, tenant_id: str):
        self.id = str(uuid.uuid4())
        self.property_id = property_id
        self.description = description
        self.tenant_id = tenant_id
        self.date_submitted = datetime.datetime.now()
        self.status = "open"
        self.resolved_date = None

class PropertyManager:
    def __init__(self):
        self.properties: Dict[str, Property] = {}
        self.tenants: Dict[str, Tenant] = {}
        self.owners: Dict[str, Person] = {}
        self.payments: Dict[str, RentPayment] = {}
        self.maintenance_requests: Dict[str, MaintenanceRequest] = {}

    def add_property(self, address: str, bedrooms: int, bathrooms: int, rent: float, owner_id: str) -> Property:
        if owner_id not in self.owners:
            raise ValueError("Owner does not exist")
        property = Property(address, bedrooms, bathrooms, rent, owner_id)
        self.properties[property.id] = property
        return property

    def add_owner(self, name: str, email: str, phone: str) -> Person:
        owner = Person(name, email, phone)
        self.owners[owner.id] = owner
        return owner

    def add_tenant(self, name: str, email: str, phone: str, credit_score: int = 0) -> Tenant:
        tenant = Tenant(name, email, phone, credit_score)
        self.tenants[tenant.id] = tenant
        return tenant

    def screen_tenant(self, tenant_id: str) -> bool:
        if tenant_id not in self.tenants:
            raise ValueError("Tenant does not exist")
        tenant = self.tenants[tenant_id]
        return tenant.credit_score >= 650

    def assign_tenant_to_property(self, property_id: str, tenant_id: str) -> None:
        if property_id not in self.properties:
            raise ValueError("Property does not exist")
        if tenant_id not in self.tenants:
            raise ValueError("Tenant does not exist")

        property = self.properties[property_id]
        if property.status != "available":
            raise ValueError("Property is not available")

        if not self.screen_tenant(tenant_id):
            raise ValueError("Tenant did not pass screening")

        property.tenant_id = tenant_id
        property.status = "occupied"

    def collect_rent(self, tenant_id: str, property_id: str, amount: float) -> RentPayment:
        if property_id not in self.properties:
            raise ValueError("Property does not exist")
        if tenant_id not in self.tenants:
            raise ValueError("Tenant does not exist")

        property = self.properties[property_id]
        if property.tenant_id != tenant_id:
            raise ValueError("Tenant is not assigned to this property")

        payment = RentPayment(tenant_id, property_id, amount)
        self.payments[payment.id] = payment
        self.tenants[tenant_id].rent_history.append(payment)
        return payment

    def process_payment(self, payment_id: str) -> None:
        if payment_id not in self.payments:
            raise ValueError("Payment does not exist")

        payment = self.payments[payment_id]
        payment.status = "completed"

    def submit_maintenance_request(self, property_id: str, description: str, tenant_id: str) -> MaintenanceRequest:
        if property_id not in self.properties:
            raise ValueError("Property does not exist")

        property = self.properties[property_id]
        if property.tenant_id != tenant_id:
            raise ValueError("Tenant is not assigned to this property")

        request = MaintenanceRequest(property_id, description, tenant_id)
        self.maintenance_requests[request.id] = request
        return request

    def resolve_maintenance_request(self, request_id: str) -> None:
        if request_id not in self.maintenance_requests:
            raise ValueError("Maintenance request does not exist")

        request = self.maintenance_requests[request_id]
        request.status = "resolved"
        request.resolved_date = datetime.datetime.now()

    def get_available_properties(self) -> List[Property]:
        return [p for p in self.properties.values() if p.status == "available"]

    def get_owner_properties(self, owner_id: str) -> List[Property]:
        return [p for p in self.properties.values() if p.owner_id == owner_id]

    def get_tenant_rent_history(self, tenant_id: str) -> List[RentPayment]:
        if tenant_id not in self.tenants:
            raise ValueError("Tenant does not exist")
        return self.tenants[tenant_id].rent_history

    def get_property_maintenance_history(self, property_id: str) -> List[MaintenanceRequest]:
        return [r for r in self.maintenance_requests.values() if r.property_id == property_id]
