import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse

def check_links(url):
    try:
        response = requests.get(url)
        response.raise_for_status()

        soup = BeautifulSoup(response.text, 'html.parser')
        links = soup.find_all('a', href=True)

        broken_links = []
        working_links = []

        for link in links:
            href = link['href']
            absolute_url = urljoin(url, href)

            if urlparse(absolute_url).netloc == urlparse(url).netloc:
                try:
                    link_response = requests.head(absolute_url, allow_redirects=True, timeout=5)
                    if link_response.status_code >= 400:
                        broken_links.append((absolute_url, link_response.status_code))
                    else:
                        working_links.append((absolute_url, link_response.status_code))
                except requests.RequestException:
                    broken_links.append((absolute_url, "Connection Error"))

        return {
            "broken_links": broken_links,
            "working_links": working_links
        }

    except requests.RequestException as e:
        return {"error": str(e)}

if __name__ == "__main__":
    target_url = input("Enter the URL to check for broken links: ")
    result = check_links(target_url)

    if "error" in result:
        print(f"Error: {result['error']}")
    else:
        print("\nBroken Links:")
        for link, status in result["broken_links"]:
            print(f"- {link} (Status: {status})")

        print(f"\nFound {len(result['broken_links'])} broken links and {len(result['working_links'])} working links")
