import os
import tarfile
import zipfile
import re
from datetime import datetime, timedelta

def archive_files(root_dir, archive_path, file_patterns=None, extensions=None, 
                  min_size=None, max_size=None, modified_since=None, 
                  archive_type='zip', exclude_dirs=None):

    if archive_type not in ['zip', 'tar', 'tgz']:
        raise ValueError("archive_type must be 'zip', 'tar', or 'tgz'")

    if archive_type == 'zip':
        archive = zipfile.ZipFile(archive_path, 'w')
    else:
        mode = 'w:gz' if archive_type == 'tgz' else 'w'
        archive = tarfile.open(archive_path, mode)

    if file_patterns:
        patterns = [re.compile(pattern) for pattern in file_patterns]
    else:
        patterns = None

    if modified_since:
        cutoff_date = datetime.now() - timedelta(days=modified_since)
    else:
        cutoff_date = None

    exclude_dirs = set(exclude_dirs or [])

    try:
        for dirpath, dirnames, filenames in os.walk(root_dir):
            dirnames[:] = [d for d in dirnames if d not in exclude_dirs]

            for filename in filenames:
                filepath = os.path.join(dirpath, filename)

                # Check extensions
                if extensions and not any(filename.endswith(ext) for ext in extensions):
                    continue

                # Check patterns
                if patterns and not any(pattern.search(filename) for pattern in patterns):
                    continue

                # Check size
                file_size = os.path.getsize(filepath)
                if min_size and file_size < min_size:
                    continue
                if max_size and file_size > max_size:
                    continue

                # Check modification time
                if cutoff_date:
                    mtime = datetime.fromtimestamp(os.path.getmtime(filepath))
                    if mtime < cutoff_date:
                        continue

                # Add file to archive
                arcname = os.path.relpath(filepath, root_dir)
                if archive_type == 'zip':
                    archive.write(filepath, arcname)
                else:
                    archive.add(filepath, arcname)
    finally:
        archive.close()

    return archive_path
