from PIL import Image
from PIL.ExifTags import TAGS

def get_exif(fname):
    try:
        image = Image.open(fname)
        exif_data = image._getexif()
        if exif_data:
            return {TAGS.get(tag, tag): value for tag, value in exif_data.items()}
        return {}
    except Exception:
        return {}

def rename_images(path):
    for fname in glob.glob(os.path.join(path, '*.jpg')):
        try:
            exif = get_exif(fname)
            if 'DateTimeOriginal' in exif:
                date = exif['DateTimeOriginal'].split(' ')[0].replace(':', '-')
                base_name = os.path.basename(fname)
                new_name = os.path.join(path, f"{date}_{base_name}")
                if new_name != fname and not os.path.exists(new_name):
                    os.rename(fname, new_name)
                    print(f"Renamed {fname} to {new_name}")
                elif new_name != fname:
                    print(f"Skipping {fname} as {new_name} already exists")
            else:
                print(f"No DateTimeOriginal in EXIF for {fname}")
