const puppeteer = require('puppeteer');
const fs = require('fs');
const path = require('path');
const urlParser = require('url');

async function takeSnapshot(url, excludedSubdomains = [], outputDir = './snapshots') {
  if (!url.startsWith('http')) {
    url = 'https://' + url;
  }

  const parsedUrl = urlParser.parse(url);
  const domain = parsedUrl.hostname;

  const browser = await puppeteer.launch();
  const page = await browser.newPage();

  await page.setRequestInterception(true);

  page.on('request', request => {
    const reqUrl = request.url();
    const reqUrlParsed = urlParser.parse(reqUrl);

    if (reqUrlParsed.hostname) {
      for (const excludedSubdomain of excludedSubdomains) {
        if (reqUrlParsed.hostname === `${excludedSubdomain}.${domain}` || 
            reqUrlParsed.hostname.endsWith(`.${excludedSubdomain}.${domain}`)) {
          return request.abort();
        }
      }
    }
    request.continue();
  });

  await page.goto(url, { waitUntil: 'networkidle2' });

  const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
  const urlSlug = url.replace(/[^a-zA-Z0-9]/g, '_').substring(0, 50);
  const outputFolder = path.join(outputDir, `${urlSlug}_${timestamp}`);

  fs.mkdirSync(outputFolder, { recursive: true });

  await page.screenshot({ path: path.join(outputFolder, 'screenshot.png'), fullPage: true });
  await fs.promises.writeFile(path.join(outputFolder, 'content.html'), await page.content());

  const resources = await page.evaluate(() => {
    return {
      links: Array.from(document.querySelectorAll('a')).map(a => a.href),
      images: Array.from(document.querySelectorAll('img')).map(img => img.src),
      scripts: Array.from(document.querySelectorAll('script')).map(script => script.src),
      styles: Array.from(document.querySelectorAll('link[rel="stylesheet"]')).map(link => link.href),
    };
  });

  await fs.promises.writeFile(path.join(outputFolder, 'resources.json'), JSON.stringify(resources, null, 2));

  await browser.close();

  return outputFolder;
}

