import os
import subprocess
import argparse
import glob
import json
import shutil
from datetime import datetime

class BuildSystem:
    def __init__(self, config_file=None):
        self.config = {
            "source_dir": "src",
            "build_dir": "build",
            "output_dir": "bin",
            "compiler": "gcc",
            "compiler_flags": ["-Wall", "-O2"],
            "file_extensions": [".c", ".cpp"],
            "exclude_patterns": []
        }

        if config_file and os.path.exists(config_file):
            with open(config_file, 'r') as f:
                self.config.update(json.load(f))

        self.ensure_directories()

    def ensure_directories(self):
        for directory in [self.config["build_dir"], self.config["output_dir"]]:
            if not os.path.exists(directory):
                os.makedirs(directory)

    def find_source_files(self):
        source_files = []
        for ext in self.config["file_extensions"]:
            for file in glob.glob(f"{self.config['source_dir']}/**/*{ext}", recursive=True):
                exclude = False
                for pattern in self.config["exclude_patterns"]:
                    if pattern in file:
                        exclude = True
                        break
                if not exclude:
                    source_files.append(file)
        return source_files

    def get_object_file_path(self, source_file):
        rel_path = os.path.relpath(source_file, self.config["source_dir"])
        obj_name = os.path.splitext(rel_path)[0] + ".o"
        return os.path.join(self.config["build_dir"], obj_name)

    def ensure_parent_directory(self, file_path):
        parent_dir = os.path.dirname(file_path)
        if parent_dir and not os.path.exists(parent_dir):
            os.makedirs(parent_dir)

    def needs_rebuild(self, source_file, object_file):
        if not os.path.exists(object_file):
            return True

        source_mtime = os.path.getmtime(source_file)
        object_mtime = os.path.getmtime(object_file)

        return source_mtime > object_mtime

    def compile_file(self, source_file):
        object_file = self.get_object_file_path(source_file)
        self.ensure_parent_directory(object_file)

        if not self.needs_rebuild(source_file, object_file):
            print(f"Skipping {source_file} (up to date)")
            return object_file

        print(f"Compiling {source_file}")

        command = [self.config["compiler"]] + self.config["compiler_flags"] + ["-c", source_file, "-o", object_file]

        try:
            subprocess.run(command, check=True)
            return object_file
        except subprocess.CalledProcessError as e:
            print(f"Error compiling {source_file}: {e}")
            return None

    def link(self, object_files, output_name):
        if not object_files:
            print("No object files to link")
            return False

        output_path = os.path.join(self.config["output_dir"], output_name)
        print(f"Linking {output_path}")

        command = [self.config["compiler"]] + object_files + ["-o", output_path]

        try:
            subprocess.run(command, check=True)
            print(f"Build successful: {output_path}")
            return True
        except subprocess.CalledProcessError as e:
            print(f"Error linking {output_path}: {e}")
            return False

    def clean(self):
        for directory in [self.config["build_dir"], self.config["output_dir"]]:
            if os.path.exists(directory):
                shutil.rmtree(directory)
                os.makedirs(directory)
        print("Clean completed")

    def build(self, output_name="program"):
        source_files = self.find_source_files()
        if not source_files:
            print("No source files found")
            return False

        print(f"Found {len(source_files)} source files")

        object_files = []
        for source_file in source_files:
            obj_file = self.compile_file(source_file)
            if obj_file:
                object_files.append(obj_file)

        return self.link(object_files, output_name)

def main():
    parser = argparse.ArgumentParser(description="Simple Build System")
    parser.add_argument("--config", help="Path to build configuration file")
    parser.add_argument("--clean", action="store_true", help="Clean build artifacts")
    parser.add_argument("--output", default="program", help="Name of the output executable")

    args = parser.parse_args()

    builder = BuildSystem(args.config)

    if args.clean:
        builder.clean()

    success = builder.build(args.output)
    return 0 if success else 1

if __name__ == "__main__":
    exit(main())
