import html

app = Flask(__name__)
PASTE_DIR = '/var/www/pastebin'

if not os.path.exists(PASTE_DIR):
    os.makedirs(PASTE_DIR, exist_ok=True)

def update_paste(paste_id, new_contents):
    if not is_valid_paste_id(paste_id):
        return False

    paste_path = os.path.join(PASTE_DIR, paste_id)

    with open(paste_path, 'w') as f:
        f.write(new_contents)

    return True

def is_valid_paste_id(paste_id):
    return paste_id and paste_id.isalnum() and os.path.exists(os.path.join(PASTE_DIR, paste_id))

def create_paste(contents):
    paste_id = str(uuid.uuid4().hex)[:8]
    paste_path = os.path.join(PASTE_DIR, paste_id)

    with open(paste_path, 'w') as f:
        f.write(contents)

    return paste_id

def get_paste(paste_id):
    if not is_valid_paste_id(paste_id):
        return None

    paste_path = os.path.join(PASTE_DIR, paste_id)

    try:
        with open(paste_path, 'r') as f:
            return f.read()
    except:
        return None

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/paste', methods=['POST'])
def paste():
    content = request.form.get('content', '')
    if not content:
        return redirect(url_for('index'))

    paste_id = create_paste(content)
    return redirect(url_for('view_paste', paste_id=paste_id))

@app.route('/paste/<paste_id>')
def view_paste(paste_id):
    content = get_paste(paste_id)
    if content is None:
        abort(404)

    return render_template('view.html', paste_id=paste_id, content=html.escape(content))

@app.route('/paste/<paste_id>/edit', methods=['GET', 'POST'])
def edit_paste(paste_id):
    if not is_valid_paste_id(paste_id):
        abort(404)

    if request.method == 'POST':
        content = request.form.get('content', '')
        if update_paste(paste_id, content):
            return redirect(url_for('view_paste', paste_id=paste_id))
        abort(500)

    content = get_paste(paste_id)
    return render_template('edit.html', paste_id=paste_id, content=content)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
