from flask import Flask, request, jsonify, render_template
import os
import uuid
import json
from werkzeug.utils import secure_filename

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = 'uploads/'
app.config['GAMES_FOLDER'] = 'games/'
app.config['ALLOWED_EXTENSIONS'] = {'png', 'jpg', 'jpeg', 'mp3', 'wav'}

if not os.path.exists(app.config['UPLOAD_FOLDER']):
    os.makedirs(app.config['UPLOAD_FOLDER'])
if not os.path.exists(app.config['GAMES_FOLDER']):
    os.makedirs(app.config['GAMES_FOLDER'])

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in app.config['ALLOWED_EXTENSIONS']

class Game:
    def __init__(self, name, creator):
        self.id = str(uuid.uuid4())
        self.name = name
        self.creator = creator
        self.scenes = []
        self.assets = {'images': [], 'audio': []}
        self.ui_elements = []
        self.logic = []

    def to_dict(self):
        return {
            'id': self.id,
            'name': self.name,
            'creator': self.creator,
            'scenes': self.scenes,
            'assets': self.assets,
            'ui_elements': self.ui_elements,
            'logic': self.logic
        }

games = {}

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/api/games', methods=['GET'])
def get_games():
    return jsonify([game.to_dict() for game in games.values()])

@app.route('/api/games', methods=['POST'])
def create_game():
    data = request.json
    if not data or 'name' not in data or 'creator' not in data:
        return jsonify({'error': 'Name and creator required'}), 400

    game = Game(data['name'], data['creator'])
    games[game.id] = game

    with open(f"{app.config['GAMES_FOLDER']}{game.id}.json", 'w') as f:
        json.dump(game.to_dict(), f)

    return jsonify(game.to_dict()), 201

@app.route('/api/games/<game_id>', methods=['GET'])
def get_game(game_id):
    if game_id not in games:
        return jsonify({'error': 'Game not found'}), 404
    return jsonify(games[game_id].to_dict())

@app.route('/api/games/<game_id>/scenes', methods=['POST'])
def add_scene(game_id):
    if game_id not in games:
        return jsonify({'error': 'Game not found'}), 404

    data = request.json
    if not data or 'name' not in data:
        return jsonify({'error': 'Scene name required'}), 400

    scene = {
        'id': str(uuid.uuid4()),
        'name': data['name'],
        'elements': []
    }

    games[game_id].scenes.append(scene)

    with open(f"{app.config['GAMES_FOLDER']}{game_id}.json", 'w') as f:
        json.dump(games[game_id].to_dict(), f)

    return jsonify(scene), 201

@app.route('/api/games/<game_id>/assets', methods=['POST'])
def upload_asset(game_id):
    if game_id not in games:
        return jsonify({'error': 'Game not found'}), 404

    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        asset_id = str(uuid.uuid4())
        new_filename = f"{asset_id}_{filename}"
        filepath = os.path.join(app.config['UPLOAD_FOLDER'], new_filename)
        file.save(filepath)

        asset_type = 'images' if file.filename.rsplit('.', 1)[1].lower() in {'png', 'jpg', 'jpeg'} else 'audio'
        asset = {
            'id': asset_id,
            'name': filename,
            'path': filepath,
            'type': asset_type
        }

        games[game_id].assets[asset_type].append(asset)

        with open(f"{app.config['GAMES_FOLDER']}{game_id}.json", 'w') as f:
            json.dump(games[game_id].to_dict(), f)

        return jsonify(asset), 201

    return jsonify({'error': 'File type not allowed'}), 400

@app.route('/api/games/<game_id>/logic', methods=['POST'])
def add_logic(game_id):
    if game_id not in games:
        return jsonify({'error': 'Game not found'}), 404

    data = request.json
    if not data or 'type' not in data or 'condition' not in data or 'action' not in data:
        return jsonify({'error': 'Logic definition required'}), 400

    logic = {
        'id': str(uuid.uuid4()),
        'type': data['type'],
        'condition': data['condition'],
        'action': data['action']
    }

