import datetime
import logging
import sched
import subprocess
import time
from dataclasses import dataclass
from typing import Callable, Dict, List, Optional, Union

@dataclass
class Task:
    name: str
    command: Union[str, Callable]
    schedule_time: datetime.datetime
    repeat_interval: Optional[int] = None  # in seconds
    last_run: Optional[datetime.datetime] = None

class JobScheduler:
    def __init__(self, log_file="scheduler.log"):
        self.scheduler = sched.scheduler(time.time, time.sleep)
        self.tasks = {}
        self.setup_logging(log_file)

    def setup_logging(self, log_file):
        logging.basicConfig(
            filename=log_file,
            level=logging.INFO,
            format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
            datefmt='%Y-%m-%d %H:%M:%S'
        )
        self.logger = logging.getLogger('JobScheduler')

    def add_task(self, name: str, command: Union[str, Callable], 
                schedule_time: datetime.datetime, repeat_interval: Optional[int] = None) -> None:
        task = Task(name, command, schedule_time, repeat_interval)
        self.tasks[name] = task
        self._schedule_task(task)
        self.logger.info(f"Added task: {name}")

    def _schedule_task(self, task: Task) -> None:
        now = datetime.datetime.now()
        if task.schedule_time < now:
            if task.repeat_interval:
                time_diff = (now - task.schedule_time).total_seconds()
                intervals_passed = int(time_diff // task.repeat_interval) + 1
                task.schedule_time = task.schedule_time + datetime.timedelta(
                    seconds=intervals_passed * task.repeat_interval
                )
            else:
                self.logger.warning(f"Task {task.name} scheduled in the past and won't run")
                return

        delay = (task.schedule_time - now).total_seconds()
        self.scheduler.enter(delay, 1, self._run_task, argument=(task,))

    def _run_task(self, task: Task) -> None:
        self.logger.info(f"Running task: {task.name}")
        task.last_run = datetime.datetime.now()

        try:
            if callable(task.command):
                result = task.command()
                self.logger.info(f"Task {task.name} completed with result: {result}")
            else:
                process = subprocess.run(
                    task.command, 
                    shell=True, 
                    capture_output=True, 
                    text=True
                )
                output = process.stdout.strip()
                error = process.stderr.strip()

                if process.returncode == 0:
                    self.logger.info(f"Task {task.name} completed successfully")
                    if output:
                        self.logger.info(f"Output: {output}")
                else:
                    self.logger.error(f"Task {task.name} failed with code {process.returncode}")
                    if error:
                        self.logger.error(f"Error: {error}")

            if task.repeat_interval:
                task.schedule_time = datetime.datetime.now() + datetime.timedelta(seconds=task.repeat_interval)
                self._schedule_task(task)

        except Exception as e:
            self.logger.error(f"Error executing task {task.name}: {str(e)}")

    def remove_task(self, name: str) -> bool:
        if name in self.tasks:
            del self.tasks[name]
            self.logger.info(f"Removed task: {name}")
            return True
        return False

    def list_tasks(self) -> List[Dict]:
        task_list = []
        now = datetime.datetime.now()
        for name, task in self.tasks.items():
            task_list.append({
                "name": name,
                "next_run": task.schedule_time,
                "time_remaining": (task.schedule_time - now).total_seconds(),
                "last_run": task.last_run,
                "repeat_interval": task.repeat_interval
            })
        return task_list

    def run(self) -> None:
        self.logger.info("Starting scheduler")
        while True:
            try:
                self.scheduler.run(blocking=False)
                time.sleep(1)
            except KeyboardInterrupt:
                self.logger.info("Scheduler stopped by user")
                break
            except Exception as e:
                self.logger.error(f"Error in scheduler: {str(e)}")
