import json
import uuid
import hashlib
import os
from datetime import datetime

class UserAccount:
    def __init__(self, username, email, password):
        self.user_id = str(uuid.uuid4())
        self.username = username
        self.email = email
        self.password_hash = self._hash_password(password)
        self.created_at = datetime.now().isoformat()
        self.settings = {
            "theme": "light",
            "notifications": True,
            "language": "en"
        }
        self.profile = {
            "display_name": username,
            "bio": "",
            "avatar": ""
        }

    def _hash_password(self, password):
        salt = os.urandom(32)
        key = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
        return salt.hex() + ':' + key.hex()

    def verify_password(self, password):
        salt_hex, key_hex = self.password_hash.split(':')
        salt = bytes.fromhex(salt_hex)
        stored_key = bytes.fromhex(key_hex)
        new_key = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
        return new_key == stored_key

    def update_profile(self, display_name=None, bio=None, avatar=None):
        if display_name:
            self.profile["display_name"] = display_name
        if bio:
            self.profile["bio"] = bio
        if avatar:
            self.profile["avatar"] = avatar
        return self.profile

    def update_setting(self, setting_name, value):
        if setting_name in self.settings:
            self.settings[setting_name] = value
            return True
        return False

    def to_dict(self):
        return {
            "user_id": self.user_id,
            "username": self.username,
            "email": self.email,
            "password_hash": self.password_hash,
            "created_at": self.created_at,
            "settings": self.settings,
            "profile": self.profile
        }

    @classmethod
    def from_dict(cls, data):
        user = cls(data["username"], data["email"], "")
        user.user_id = data["user_id"]
        user.password_hash = data["password_hash"]
        user.created_at = data["created_at"]
        user.settings = data["settings"]
        user.profile = data["profile"]
        return user


class AccountManager:
    def __init__(self, storage_file="accounts.json"):
        self.storage_file = storage_file
        self.accounts = {}
        self.load_accounts()

    def load_accounts(self):
        try:
            with open(self.storage_file, 'r') as f:
                accounts_data = json.load(f)
                for user_id, account_data in accounts_data.items():
                    self.accounts[user_id] = UserAccount.from_dict(account_data)
        except (FileNotFoundError, json.JSONDecodeError):
            self.accounts = {}

    def save_accounts(self):
        accounts_data = {user_id: account.to_dict() for user_id, account in self.accounts.items()}
        with open(self.storage_file, 'w') as f:
            json.dump(accounts_data, f, indent=4)

    def create_account(self, username, email, password):
        for account in self.accounts.values():
            if account.username == username:
                return None, "Username already exists"
            if account.email == email:
                return None, "Email already in use"

        new_account = UserAccount(username, email, password)
        self.accounts[new_account.user_id] = new_account
        self.save_accounts()
        return new_account, "Account created successfully"

    def authenticate(self, username, password):
        for account in self.accounts.values():
            if account.username == username and account.verify_password(password):
                return account
        return None

    def get_account(self, user_id):
        return self.accounts.get(user_id)

    def update_account_profile(self, user_id, display_name=None, bio=None, avatar=None):
        account = self.get_account(user_id)
        if account:
            account.update_profile(display_name, bio, avatar)
            self.save_accounts()
            return True
        return False

    def update_account_settings(self, user_id, setting_name, value):
        account = self.get_account(user_id)
        if account and account.update_setting(setting_name, value):
            self.save_accounts()
            return True
        return False

    def delete_account(self, user_id):
        if user_id in self.accounts:
            del self.accounts[user_id]
            self.save_accounts()
            return True
        return False
