from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
from flask_bcrypt import Bcrypt
from datetime import datetime
import jwt
import os

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///marketplace.db'
app.config['SECRET_KEY'] = os.urandom(24)
db = SQLAlchemy(app)
bcrypt = Bcrypt(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(50), unique=True, nullable=False)
    email = db.Column(db.String(100), unique=True, nullable=False)
    password = db.Column(db.String(100), nullable=False)
    is_seller = db.Column(db.Boolean, default=False)
    listings = db.relationship('Listing', backref='seller', lazy=True)

class Listing(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(100), nullable=False)
    description = db.Column(db.Text, nullable=False)
    price = db.Column(db.Float, nullable=False)
    category = db.Column(db.String(50), nullable=False)
    condition = db.Column(db.String(20), nullable=False)
    date_posted = db.Column(db.DateTime, default=datetime.utcnow)
    seller_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()

    if User.query.filter_by(username=data['username']).first():
        return jsonify({'message': 'Username already exists'}), 400

    if User.query.filter_by(email=data['email']).first():
        return jsonify({'message': 'Email already exists'}), 400

    hashed_password = bcrypt.generate_password_hash(data['password']).decode('utf-8')
    user = User(username=data['username'], email=data['email'], password=hashed_password, is_seller=data.get('is_seller', False))

    db.session.add(user)
    db.session.commit()

    return jsonify({'message': 'User registered successfully'}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()

    user = User.query.filter_by(email=data['email']).first()
    if not user or not bcrypt.check_password_hash(user.password, data['password']):
        return jsonify({'message': 'Invalid credentials'}), 401

    token = jwt.encode({'user_id': user.id}, app.config['SECRET_KEY'], algorithm='HS256')

    return jsonify({'token': token, 'user_id': user.id, 'is_seller': user.is_seller})

def token_required(f):
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization')
        if not token:
            return jsonify({'message': 'Token is missing'}), 401

        try:
            token = token.split(" ")[1]
            data = jwt.decode(token, app.config['SECRET_KEY'], algorithms=['HS256'])
            current_user = User.query.get(data['user_id'])
            if not current_user:
                return jsonify({'message': 'Invalid token'}), 401
        except:
            return jsonify({'message': 'Invalid token'}), 401

        return f(current_user, *args, **kwargs)

    decorated.__name__ = f.__name__
    return decorated

@app.route('/listings', methods=['POST'])
@token_required
def create_listing(current_user):
    if not current_user.is_seller:
        return jsonify({'message': 'Only sellers can create listings'}), 403

    data = request.get_json()

    listing = Listing(
        title=data['title'],
        description=data['description'],
        price=data['price'],
        category=data['category'],
        condition=data['condition'],
        seller_id=current_user.id
    )

    db.session.add(listing)
    db.session.commit()

    return jsonify({'message': 'Listing created successfully'}), 201

@app.route('/listings', methods=['GET'])
def get_listings():
    category = request.args.get('category')
    condition = request.args.get('condition')
    min_price = request.args.get('min_price')
    max_price = request.args.get('max_price')

    query = Listing.query

    if category:
        query = query.filter_by(category=category)

    if condition:
        query = query.filter_by(condition=condition)

    if min_price:
        query = query.filter(Listing.price >= float(min_price))

    if max_price:
        query = query.filter(Listing.price <= float(max_price))

    listings = query.order_by(Listing.date_posted.desc()).all()

    result = []
    for listing in listings:
        result.append({
            'id': listing.id,
            'title': listing.title,
            'description': listing.description,
            'price': listing.price,
            'category': listing.category,
            'condition': listing.condition,
            'date_posted': listing.date_posted.strftime('%Y-%m-%d %H:%M:%S'),
            'seller_id': listing.seller_id
        })

    return jsonify(result)

@app.route('/listings/<int:listing_id>', methods=['GET'])
def get_listing(listing_id):
    listing = Listing.query.get_or_404(listing_id)

    return jsonify({
        'id': listing.id,
        'title': listing.title,
        'description': listing.description,
        'price': listing.price,
        'category': listing.category,
        'condition': listing.condition,
        'date_posted': listing.date_posted.strftime('%Y-%m-%d %H:%M:%S'),
        'seller_id': listing.seller_id
    })

@app.route('/listings/<int:listing_id>', methods=['PUT'])
@token_required
def update_listing(current_user, listing_id):
    listing = Listing.query.get_or_404(listing_id)

    if listing.seller_id != current_user.id:
        return jsonify({'message': 'You can only update your own listings'}), 403

    data = request.get_json()

    listing.title = data.get('title', listing.title)
    listing.description = data.get('description', listing.description)
    listing.price = data.get('price', listing.price)
    listing.category = data.get('category', listing.category)
    listing.condition = data.get('condition', listing.condition)

    db.session.commit()

    return jsonify({'message': 'Listing updated successfully'})

@app.route('/listings/<int:listing_id>', methods=['DELETE'])
@token_required
def delete_listing(current_user, listing_id):
    listing = Listing.query.get_or_404(listing_id)

    if listing.seller_id != current_user.id:
        return jsonify({'message': 'You can only delete your own listings'}), 403

    db.session.delete(listing)
    db.session.commit()

    return jsonify({'message': 'Listing deleted successfully'})

if __name__ == '__main__':
