        db.execute('''
        CREATE TABLE IF NOT EXISTS documents (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            filename TEXT NOT NULL,
            uploaded_by TEXT NOT NULL,
            upload_date TIMESTAMP NOT NULL,
            description TEXT
        )
        ''')
