@app.route('/')
def home():
    return render_template('index.html')

@app.route('/weather')
def get_weather():
    city = request.args.get('city', 'London')

    params = {
        'q': city,
        'appid': WEATHER_API_KEY,
        'units': 'metric'
    }

    response = requests.get(API_URL, params=params)

    if response.status_code == 200:
        data = response.json()
        forecast = process_forecast(data)
        return jsonify(forecast)
    else:
        return jsonify({'error': 'Weather data not available'}), 404

def process_forecast(data):
    processed = {
        'city': data['city']['name'],
        'country': data['city']['country'],
        'forecasts': []
    }

    for item in data['list']:
        forecast = {
            'datetime': datetime.fromtimestamp(item['dt']).strftime('%Y-%m-%d %H:%M'),
            'temp': item['main']['temp'],
            'feels_like': item['main']['feels_like'],
            'description': item['weather'][0]['description'],
            'icon': f"https://openweathermap.org/img/wn/{item['weather'][0]['icon']}@2x.png",
            'wind_speed': item['wind']['speed'],
            'humidity': item['main']['humidity']
        }
        processed['forecasts'].append(forecast)

    return processed

