import pandas as pd
import time
import random

def fetch_html(url):
    headers = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36"
    }
    response = requests.get(url, headers=headers)
    response.raise_for_status()
    return response.text

def parse_html(html):
    soup = BeautifulSoup(html, 'html.parser')
    return soup

def extract_data(soup, selectors):
    results = []
    items = soup.select(selectors['container'])

    for item in items:
        data = {}
        for key, selector in selectors['fields'].items():
            element = item.select_one(selector)
            if element:
                data[key] = element.get_text().strip()
            else:
                data[key] = None
        results.append(data)

    return results

def scrape_website(url, selectors, pages=1):
    all_data = []

    for i in range(1, pages + 1):
        page_url = f"{url}?page={i}" if i > 1 else url

        try:
            html = fetch_html(page_url)
            soup = parse_html(html)
            data = extract_data(soup, selectors)
            all_data.extend(data)

            if i < pages:
                delay = random.uniform(1, 3)
                time.sleep(delay)

        except Exception as e:
            print(f"Error scraping page {i}: {e}")

    return all_data

