def calculate_tax(income, deductions=0, credits=0):
    taxable_income = max(0, income - deductions)

    # Calculate tax based on progressive tax brackets
    tax = 0

    if taxable_income <= 10000:
        tax = taxable_income * 0.10
    elif taxable_income <= 40000:
        tax = 10000 * 0.10 + (taxable_income - 10000) * 0.12
    elif taxable_income <= 85000:
        tax = 10000 * 0.10 + 30000 * 0.12 + (taxable_income - 40000) * 0.22
    elif taxable_income <= 165000:
        tax = 10000 * 0.10 + 30000 * 0.12 + 45000 * 0.22 + (taxable_income - 85000) * 0.24
    elif taxable_income <= 210000:
        tax = 10000 * 0.10 + 30000 * 0.12 + 45000 * 0.22 + 80000 * 0.24 + (taxable_income - 165000) * 0.32
    elif taxable_income <= 520000:
        tax = 10000 * 0.10 + 30000 * 0.12 + 45000 * 0.22 + 80000 * 0.24 + 45000 * 0.32 + (taxable_income - 210000) * 0.35
    else:
        tax = 10000 * 0.10 + 30000 * 0.12 + 45000 * 0.22 + 80000 * 0.24 + 45000 * 0.32 + 310000 * 0.35 + (taxable_income - 520000) * 0.37

    tax = max(0, tax - credits)
    return tax

def tax_filing_service():
    print("Welcome to the Tax Filing Service")

    try:
        income = float(input("Enter your total income for the year: $"))

        print("\nDeductions:")
        standard_deduction = 12950  # Standard deduction for 2022 (single filer)
        print(f"Standard deduction: ${standard_deduction}")
        itemized = input("Do you want to itemize deductions instead? (yes/no): ").lower() == "yes"

        if itemized:
            deductions = float(input("Enter your total itemized deductions: $"))
        else:
            deductions = standard_deduction

        credits = float(input("\nEnter any tax credits you qualify for: $"))

        tax_owed = calculate_tax(income, deductions, credits)

        print("\n----- Tax Summary -----")
        print(f"Gross Income: ${income:.2f}")
        print(f"Deductions: ${deductions:.2f}")
        print(f"Taxable Income: ${max(0, income - deductions):.2f}")
        print(f"Tax Credits: ${credits:.2f}")
        print(f"Tax Owed: ${tax_owed:.2f}")

    except ValueError:
        print("Invalid input. Please enter numeric values for income, deductions, and credits.")

if __name__ == "__main__":
    tax_filing_service()
