def retrieve_document(query, collection_path):
    index_path = Path(collection_path) / 'index.txt'
    results = []

    if not index_path.exists():
        return results

    query_terms = set(query.split())
    matching_docs = {}

    with open(index_path, 'r') as f:
        for line in f:
            word, docs = line.strip().split(':', 1)
            if word in query_terms:
                for doc in docs.split(','):
                    matching_docs[doc] = matching_docs.get(doc, 0) + 1

    sorted_results = sorted(matching_docs.items(), key=lambda x: x[1], reverse=True)
    results = [doc for doc, count in sorted_results]

