from flask import Flask, request, render_template, url_for, redirect
from PIL import Image, ImageDraw, ImageFont
import os
import uuid
import base64
from io import BytesIO
import re

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = 'static/uploads'
app.config['MAX_CONTENT_LENGTH'] = 16 * 1024 * 1024  # 16MB max upload

if not os.path.exists(app.config['UPLOAD_FOLDER']):
    os.makedirs(app.config['UPLOAD_FOLDER'])

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/meme', methods=['GET', 'POST'])
def meme():
    if request.method == 'POST':
        top_text = request.form.get('top_text', '')
        bottom_text = request.form.get('bottom_text', '')

        if 'image' not in request.files:
            return redirect(url_for('index'))

        image_file = request.files['image']
        if image_file.filename == '':
            return redirect(url_for('index'))

        if image_file and allowed_file(image_file.filename):
            filename = str(uuid.uuid4()) + os.path.splitext(image_file.filename)[1]
            filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
            image_file.save(filepath)

            meme_path = create_meme(filepath, top_text, bottom_text)
            return render_template('result.html', meme_path=meme_path)

    top_text = request.args.get('top_text', '')
    bottom_text = request.args.get('bottom_text', '')
    image = request.args.get('image', '')

    if not image or not is_safe_url(image):
        return render_template('index.html')

    data = {
        'image': image,
        'top_text': top_text,
        'bottom_text': bottom_text
    }

    return render_template('meme.html', data=data)

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in {'png', 'jpg', 'jpeg', 'gif'}

def is_safe_url(url):
    return re.match(r'^https?://(.*?)\.(jpg|jpeg|png|gif)$', url, re.IGNORECASE) is not None

def create_meme(image_path, top_text, bottom_text):
    img = Image.open(image_path)
    draw = ImageDraw.Draw(img)

    width, height = img.size
    font_size = int(width / 15)
    font = ImageFont.truetype("arial.ttf", font_size)

    # Add top text
    top_text_width, top_text_height = draw.textsize(top_text, font=font)
    top_text_position = ((width - top_text_width) / 2, height * 0.05)

    # Add black outline
    for offset in [(1,1), (-1,1), (1,-1), (-1,-1)]:
        draw.text((top_text_position[0]+offset[0], top_text_position[1]+offset[1]), 
                  top_text, font=font, fill=(0,0,0))

    # Add white text
    draw.text(top_text_position, top_text, font=font, fill=(255,255,255))

    # Add bottom text
    bottom_text_width, bottom_text_height = draw.textsize(bottom_text, font=font)
    bottom_text_position = ((width - bottom_text_width) / 2, height * 0.85)

    # Add black outline
    for offset in [(1,1), (-1,1), (1,-1), (-1,-1)]:
        draw.text((bottom_text_position[0]+offset[0], bottom_text_position[1]+offset[1]), 
                  bottom_text, font=font, fill=(0,0,0))

    # Add white text
    draw.text(bottom_text_position, bottom_text, font=font, fill=(255,255,255))

    # Save the modified image
    output_path = os.path.join(app.config['UPLOAD_FOLDER'], f"meme_{uuid.uuid4()}.jpg")
    img.save(output_path)

    return output_path.replace('static/', '')

if __name__ == '__main__':
    app.run(debug=True)
