import os
import shutil
import hashlib
import json
import datetime

class SourceControlSystem:
    def __init__(self, repo_path):
        self.repo_path = repo_path
        self.scm_dir = os.path.join(repo_path, '.scm')
        self.versions_dir = os.path.join(self.scm_dir, 'versions')
        self.checkout_file = os.path.join(self.scm_dir, 'checkouts.json')

        if not os.path.exists(self.scm_dir):
            os.makedirs(self.scm_dir)
            os.makedirs(self.versions_dir)
            with open(self.checkout_file, 'w') as f:
                json.dump({}, f)

    def get_checkouts(self):
        with open(self.checkout_file, 'r') as f:
            return json.load(f)

    def save_checkouts(self, checkouts):
        with open(self.checkout_file, 'w') as f:
            json.dump(checkouts, f)

    def file_hash(self, file_path):
        with open(file_path, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()

    def checkout(self, file_path, user):
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File {file_path} does not exist")

        rel_path = os.path.relpath(file_path, self.repo_path)
        checkouts = self.get_checkouts()

        if rel_path in checkouts:
            if checkouts[rel_path]['user'] != user:
                raise PermissionError(f"File is already checked out by {checkouts[rel_path]['user']}")
        else:
            file_hash = self.file_hash(file_path)
            version_path = os.path.join(self.versions_dir, file_hash)

            if not os.path.exists(version_path):
                shutil.copy2(file_path, version_path)

            checkouts[rel_path] = {
                'user': user,
                'hash': file_hash,
                'timestamp': datetime.datetime.now().isoformat()
            }

            self.save_checkouts(checkouts)
            print(f"File {rel_path} checked out by {user}")

    def checkin(self, file_path, user):
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File {file_path} does not exist")

        rel_path = os.path.relpath(file_path, self.repo_path)
        checkouts = self.get_checkouts()

        if rel_path not in checkouts:
            raise ValueError(f"File {rel_path} is not checked out")

        if checkouts[rel_path]['user'] != user:
            raise PermissionError(f"File is checked out by {checkouts[rel_path]['user']}, not {user}")

        file_hash = self.file_hash(file_path)
        version_path = os.path.join(self.versions_dir, file_hash)

        if not os.path.exists(version_path):
            shutil.copy2(file_path, version_path)

        del checkouts[rel_path]
        self.save_checkouts(checkouts)
        print(f"File {rel_path} checked in by {user}")

    def list_checkouts(self):
        checkouts = self.get_checkouts()
        for file_path, info in checkouts.items():
            print(f"{file_path} - checked out by {info['user']} at {info['timestamp']}")

# Example usage
if __name__ == "__main__":
    scs = SourceControlSystem("./my_repo")

    # Create test file
    with open("./my_repo/test.txt", "w") as f:
        f.write("Initial content")

    # Checkout the file
    scs.checkout("./my_repo/test.txt", "user1")

    # Modify the file
    with open("./my_repo/test.txt", "w") as f:
        f.write("Modified content")

    # Check in the file
    scs.checkin("./my_repo/test.txt", "user1")
