import os
from PIL import Image

def get_dimensions(size):
    sizes = {
        'small': (400, 300),
        'medium': (800, 600),
        'large': (1200, 900)
    }
    return sizes[size]

def resize_img(path, size):
    img = Image.open(path)
    img = img.resize(size)
    output_path = os.path.splitext(path)[0] + "_resized" + os.path.splitext(path)[1]
    img.save(output_path)

if __name__ == "__main__":
    with open('rules.csv') as f:
        for line in f:
            if line.strip():
                path, size = line.strip().split(',')
                if os.path.exists(path):
                    try:
                        resize_img(path, get_dimensions(size))
                    except KeyError:
                        print(f"Invalid size for {path}: {size}")
                    except Exception as e:
                        print(f"Error processing {path}: {e}")
                else:
                    print(f"File not found: {path}")
