import json
import os
import threading
import time
import socket
import requests
from flask import Flask, request, jsonify

app = Flask(__name__)

class KeyValueStore:
    def __init__(self, storage_path="data.json", replicas=None):
        self.storage_path = storage_path
        self.replicas = replicas or []
        self.lock = threading.RLock()
        self.data = self._load_data()
        self._start_heartbeat()

    def _load_data(self):
        if os.path.exists(self.storage_path):
            try:
                with open(self.storage_path, 'r') as f:
                    return json.load(f)
            except json.JSONDecodeError:
                return {}
        return {}

    def _save_data(self):
        with open(self.storage_path, 'w') as f:
            json.dump(self.data, f)

    def get(self, key):
        with self.lock:
            return self.data.get(key)

    def set(self, key, value):
        with self.lock:
            self.data[key] = value
            self._save_data()
            self._replicate_operation("set", key, value)
            return True

    def delete(self, key):
        with self.lock:
            if key in self.data:
                del self.data[key]
                self._save_data()
                self._replicate_operation("delete", key)
                return True
            return False

    def _replicate_operation(self, operation, key, value=None):
        for replica in self.replicas:
            try:
                if operation == "set":
                    requests.post(f"http://{replica}/replicate", 
                                 json={"operation": "set", "key": key, "value": value},
                                 timeout=1)
                elif operation == "delete":
                    requests.post(f"http://{replica}/replicate", 
                                 json={"operation": "delete", "key": key},
                                 timeout=1)
            except requests.RequestException:
                pass

    def _start_heartbeat(self):
        def send_heartbeats():
            while True:
                for replica in self.replicas[:]:
                    try:
                        response = requests.get(f"http://{replica}/health", timeout=1)
                        if response.status_code != 200:
                            print(f"Replica {replica} is unhealthy")
                    except requests.RequestException:
                        print(f"Cannot reach replica {replica}")
                time.sleep(5)

        heartbeat_thread = threading.Thread(target=send_heartbeats, daemon=True)
        heartbeat_thread.start()

    def add_replica(self, replica_address):
        if replica_address not in self.replicas:
            self.replicas.append(replica_address)
            return True
        return False

    def remove_replica(self, replica_address):
        if replica_address in self.replicas:
            self.replicas.remove(replica_address)
            return True
        return False

    def sync_to_replica(self, replica_address):
        try:
            requests.post(f"http://{replica_address}/sync", json=self.data, timeout=5)
            return True
        except requests.RequestException:
            return False

store = KeyValueStore()

@app.route('/get/<key>', methods=['GET'])
def get_value(key):
    value = store.get(key)
    if value is None:
        return jsonify({"error": "Key not found"}), 404
    return jsonify({"key": key, "value": value})

@app.route('/set', methods=['POST'])
def set_value():
    data = request.json
    if not data or 'key' not in data or 'value' not in data:
        return jsonify({"error": "Invalid request"}), 400

    store.set(data['key'], data['value'])
    return jsonify({"status": "success"})

@app.route('/delete/<key>', methods=['DELETE'])
def delete_value(key):
    success = store.delete(key)
    if success:
        return jsonify({"status": "success"})
    return jsonify({"error": "Key not found"}), 404

@app.route('/replicate', methods=['POST'])
def replicate():
    data = request.json
    if not data or 'operation' not in data or 'key' not in data:
        return jsonify({"error": "Invalid replication request"}), 400

    if data['operation'] == 'set' and 'value' in data:
        with store.lock:
            store.data[data['key']] = data['value']
            store._save_data()
    elif data['operation'] == 'delete':
        with store.lock:
            if data['key'] in store.data:
                del store.data[data['key']]
                store._save_data()

    return jsonify({"status": "success"})

@app.route('/sync', methods=['POST'])
def sync():
    data = request.json
    with store.lock:
        store.data = data
        store._save_data()
    return jsonify({"status": "success"})

@app.route('/health', methods=['GET'])
def health_check():
    return jsonify({"status": "healthy"})

@app.route('/admin/replicas', methods=['GET'])
