    data = request.json
    if not data or 'address' not in data:
        return jsonify({"error": "Invalid request"}), 400

    success = store.add_replica(data['address'])
    if success:
        store.sync_to_replica(data['address'])
        return jsonify({"status": "success"})
    return jsonify({"error": "Replica already exists"}), 400

