import os
import tarfile
import zipfile
import shutil
import subprocess
from pathlib import Path


class ArchiveExtractor:
    def extract_tar(self, archive_path, extract_path=None):
        if extract_path is None:
            extract_path = os.path.dirname(archive_path)

        with tarfile.open(archive_path) as tar:
            tar.extractall(path=extract_path)
        return extract_path

    def extract_zip(self, archive_path, extract_path=None):
        if extract_path is None:
            extract_path = os.path.dirname(archive_path)

        with zipfile.ZipFile(archive_path) as zip_file:
            zip_file.extractall(extract_path)
        return extract_path

    def extract_rar(self, archive_path, extract_path=None):
        if extract_path is None:
            extract_path = os.path.dirname(archive_path)

        try:
            subprocess.run(["unrar", "x", archive_path, extract_path], check=True)
            return extract_path
        except subprocess.CalledProcessError:
            raise Exception("Failed to extract RAR file. Make sure 'unrar' is installed.")

    def extract_7z(self, archive_path, extract_path=None):
        if extract_path is None:
            extract_path = os.path.dirname(archive_path)

        try:
            subprocess.run(["7z", "x", archive_path, f"-o{extract_path}"], check=True)
            return extract_path
        except subprocess.CalledProcessError:
            raise Exception("Failed to extract 7z file. Make sure '7z' is installed.")


class ImageMounter:
    def mount_iso(self, iso_path, mount_point=None):
        if mount_point is None:
            mount_point = f"/tmp/iso_mount_{os.path.basename(iso_path)}"

        os.makedirs(mount_point, exist_ok=True)
        try:
            subprocess.run(["mount", "-o", "loop", iso_path, mount_point], check=True)
            return mount_point
        except subprocess.CalledProcessError:
            raise Exception("Failed to mount ISO. Make sure you have sufficient permissions.")

    def unmount(self, mount_point):
        try:
            subprocess.run(["umount", mount_point], check=True)
            return True
        except subprocess.CalledProcessError:
            raise Exception("Failed to unmount. Make sure the mount point is valid.")


class UtilityLibrary:
    def __init__(self):
        self.archive_extractor = ArchiveExtractor()
        self.image_mounter = ImageMounter()

    def extract(self, file_path, extract_path=None):
        file_path = Path(file_path)
        suffix = file_path.suffix.lower()

        if suffix in ('.tar', '.gz', '.bz2', '.xz'):
            return self.archive_extractor.extract_tar(file_path, extract_path)
        elif suffix == '.zip':
            return self.archive_extractor.extract_zip(file_path, extract_path)
        elif suffix == '.rar':
            return self.archive_extractor.extract_rar(file_path, extract_path)
        elif suffix == '.7z':
            return self.archive_extractor.extract_7z(file_path, extract_path)
        elif suffix == '.iso':
            return self.image_mounter.mount_iso(file_path, extract_path)
        else:
            raise ValueError(f"Unsupported file format: {suffix}")
