    {"id": 4, "name": "Leather Belt", "description": "Classic leather belt with metal buckle", "category": "accessories"},
    {"id": 5, "name": "Phone Case", "description": "Protective case for smartphones", "category": "accessories"},
    {"id": 6, "name": "Tablet", "description": "10-inch display with long battery life", "category": "electronics"},
    {"id": 7, "name": "Laptop Bag", "description": "Water-resistant bag for laptops", "category": "accessories"},
    {"id": 8, "name": "Bluetooth Speaker", "description": "Portable wireless speaker with deep bass", "category": "electronics"}
]

def get_product_recommendations(query, n=3):
    df = pd.DataFrame(products)

    # Combine name, description and category for better matching
    df['content'] = df['name'] + ' ' + df['description'] + ' ' + df['category']

    # Create vectorizer and calculate similarity
    vectorizer = TfidfVectorizer(stop_words='english')
    tfidf_matrix = vectorizer.fit_transform(df['content'])

    # Transform search query
    query_vec = vectorizer.transform([query])

    # Calculate similarity between query and all products
    similarity = cosine_similarity(query_vec, tfidf_matrix).flatten()

    # Get indices of top N similar products
    indices = similarity.argsort()[:-n-1:-1]

    return [products[i] for i in indices]

