import os
import subprocess
import yaml
import argparse
from collections import defaultdict
import networkx as nx

class BuildSystem:
    def __init__(self, config_file):
        self.config = self.load_config(config_file)
        self.build_graph = self.create_dependency_graph()

    def load_config(self, config_file):
        with open(config_file, 'r') as f:
            return yaml.safe_load(f)

    def create_dependency_graph(self):
        G = nx.DiGraph()
        for target, info in self.config['targets'].items():
            G.add_node(target)
            if 'dependencies' in info:
                for dep in info['dependencies']:
                    G.add_edge(dep, target)
        return G

    def check_cycles(self):
        if not nx.is_directed_acyclic_graph(self.build_graph):
            cycles = list(nx.simple_cycles(self.build_graph))
            raise ValueError(f"Circular dependencies detected: {cycles}")

    def build_target(self, target):
        if target not in self.config['targets']:
            raise ValueError(f"Target '{target}' not found in build configuration")

        target_info = self.config['targets'][target]

        if 'dependencies' in target_info:
            for dep in target_info['dependencies']:
                self.build_target(dep)

        print(f"Building {target}...")
        if 'commands' in target_info:
            for cmd in target_info['commands']:
                print(f"  Executing: {cmd}")
                subprocess.run(cmd, shell=True, check=True)

        print(f"Completed {target}")

    def build_all(self):
        self.check_cycles()
        build_order = list(nx.topological_sort(self.build_graph))

        for target in build_order:
            if target in self.config['targets']:
                self.build_target(target)

def main():
    parser = argparse.ArgumentParser(description='Build system')
    parser.add_argument('--config', default='build.yaml', help='Build configuration file')
    parser.add_argument('--target', help='Specific target to build')
    args = parser.parse_args()

    builder = BuildSystem(args.config)

    if args.target:
        builder.build_target(args.target)
    else:
        builder.build_all()

if __name__ == '__main__':
    main()
