from werkzeug.utils import secure_filename
import os
import pytesseract
from PIL import Image
import re
import uuid
import datetime
import json

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = 'uploads/'
app.config['ALLOWED_EXTENSIONS'] = {'png', 'jpg', 'jpeg', 'pdf', 'tiff'}
os.makedirs(app.config['UPLOAD_FOLDER'], exist_ok=True)

def allowed_file(filename):
    return '.' in filename and \
           filename.rsplit('.', 1)[1].lower() in app.config['ALLOWED_EXTENSIONS']

def extract_text_from_image(file_path):
    return pytesseract.image_to_string(Image.open(file_path))

def parse_receipt(text):
    # Simple pattern matching for date, total amount, and vendor
    date_pattern = r'\d{1,2}[/-]\d{1,2}[/-]\d{2,4}'
    amount_pattern = r'\$\s*\d+\.\d{2}'

    dates = re.findall(date_pattern, text)
    amounts = re.findall(amount_pattern, text)

    # Extract vendor (assuming it's usually at the top of receipt)
    lines = text.split('\n')
    vendor = lines[0] if lines else "Unknown"

    # Get the largest amount as the total
    total = max([float(amount.replace('$', '').strip()) for amount in amounts], default=0) if amounts else 0

    return {
        'vendor': vendor,
        'date': dates[0] if dates else datetime.datetime.now().strftime('%m/%d/%Y'),
        'total': total,
        'raw_text': text
    }

@app.route('/upload', methods=['POST'])
def upload_receipt():
    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    if file and allowed_file(file.filename):
        filename = secure_filename(file.filename)
        unique_filename = f"{uuid.uuid4()}_{filename}"
        file_path = os.path.join(app.config['UPLOAD_FOLDER'], unique_filename)
        file.save(file_path)

        try:
            text = extract_text_from_image(file_path)
            parsed_data = parse_receipt(text)

            # Save parsed data to a database or file
            expense_id = str(uuid.uuid4())
            parsed_data['id'] = expense_id
            parsed_data['filename'] = unique_filename

            with open(f"{app.config['UPLOAD_FOLDER']}/{expense_id}.json", 'w') as f:
                json.dump(parsed_data, f)

            return jsonify({
                'success': True,
                'expense_id': expense_id,
                'parsed_data': parsed_data
            })

        except Exception as e:
            return jsonify({'error': str(e)}), 500

    return jsonify({'error': 'File type not allowed'}), 400

@app.route('/expenses', methods=['GET'])
def get_expenses():
    expenses = []
    for filename in os.listdir(app.config['UPLOAD_FOLDER']):
        if filename.endswith('.json'):
            with open(os.path.join(app.config['UPLOAD_FOLDER'], filename), 'r') as f:
                expenses.append(json.load(f))

    return jsonify({'expenses': expenses})

