#!/usr/bin/env python3
import os
import argparse
import subprocess
from datetime import datetime

def get_human_readable_size(size_bytes):
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if size_bytes < 1024:
            return f"{size_bytes:.2f} {unit}"
        size_bytes /= 1024
    return f"{size_bytes:.2f} PB"

def find_large_files(start_path, threshold_mb):
    threshold_bytes = threshold_mb * 1024 * 1024
    large_files = []

    for root, _, files in os.walk(start_path):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                file_size = os.path.getsize(file_path)
                if file_size >= threshold_bytes:
                    large_files.append((file_path, file_size))
            except (FileNotFoundError, PermissionError):
                continue

    return sorted(large_files, key=lambda x: x[1], reverse=True)

def change_permissions(file_path, permission):
    try:
        subprocess.run(['chmod', permission, file_path], check=True)
        return True
    except subprocess.CalledProcessError:
        return False

def main():
    parser = argparse.ArgumentParser(description='Analyze disk usage and manage large files')
    parser.add_argument('--path', default='.', help='Starting directory path')
    parser.add_argument('--threshold', type=float, default=100, help='Size threshold in MB')
    parser.add_argument('--action', choices=['list', 'permissions', 'delete'], default='list',
                        help='Action to perform on large files')
    parser.add_argument('--permission', default='644', help='Permission to set (octal)')
    args = parser.parse_args()

    print(f"Scanning {os.path.abspath(args.path)} for files larger than {args.threshold} MB...")
    large_files = find_large_files(args.path, args.threshold)

    if not large_files:
        print("No files found exceeding the threshold.")
        return

    total_size = sum(size for _, size in large_files)
    print(f"Found {len(large_files)} files exceeding {args.threshold} MB, total size: {get_human_readable_size(total_size)}")

    if args.action == 'list':
        for file_path, file_size in large_files:
            print(f"{get_human_readable_size(file_size)}\t{file_path}")

    elif args.action == 'permissions':
        for file_path, file_size in large_files:
            print(f"Changing permissions of {file_path} ({get_human_readable_size(file_size)}) to {args.permission}")
            success = change_permissions(file_path, args.permission)
            if not success:
                print(f"Failed to change permissions for {file_path}")

    elif args.action == 'delete':
        for file_path, file_size in large_files:
            confirm = input(f"Delete {file_path} ({get_human_readable_size(file_size)})? [y/N] ")
            if confirm.lower() == 'y':
                try:
                    os.remove(file_path)
                    print(f"Deleted {file_path}")
                except (PermissionError, OSError) as e:
                    print(f"Failed to delete {file_path}: {e}")

if __name__ == '__main__':
    main()
