def extract_zip_metadata(file_path):
    try:
        with zipfile.ZipFile(file_path, 'r') as zip_file:
            file_list = zip_file.infolist()
            metadata = {
                "Files": len(file_list),
                "File_List": [
                    {
                        "Filename": info.filename,
                        "Modified": info.date_time,
                        "Compressed Size": info.compress_size,
                        "Uncompressed Size": info.file_size
                    }
                    for info in file_list
                ]
            }
            return metadata
    except Exception as e:
        return {"Error": str(e)}

def detect_file_type(file_path):
    mime = magic.Magic(mime=True)
    file_type = mime.from_file(file_path)
    return file_type

def extract_metadata(file_path):
    if not os.path.isfile(file_path):
        return {"Error": f"File {file_path} does not exist"}

    file_type = detect_file_type(file_path)

    if "image" in file_type:
        return extract_image_metadata(file_path)
    elif file_type == "application/pdf":
        return extract_pdf_metadata(file_path)
    elif file_type == "application/vnd.openxmlformats-officedocument.wordprocessingml.document":
        return extract_docx_metadata(file_path)
    elif file_type in ["application/zip", "application/x-zip-compressed"]:
        return extract_zip_metadata(file_path)
    else:
        return {"Error": f"Unsupported file type: {file_type}"}

def main():
    parser = argparse.ArgumentParser(description="Extract metadata from files")
    parser.add_argument("file_path", help="Path to the file")
    parser.add_argument("-o", "--output", help="Output file path")
    args = parser.parse_args()

    metadata = extract_metadata(args.file_path)

    if args.output:
        with open(args.output, 'w') as f:
            pprint.pprint(metadata, stream=f)
    else:
        pprint.pprint(metadata)

if __name__ == "__main__":
    main()
```

