import os
import hashlib
import shutil
from collections import defaultdict
import argparse

def calculate_file_hash(file_path, block_size=65536):
    hasher = hashlib.sha256()
    with open(file_path, 'rb') as file:
        buffer = file.read(block_size)
        while len(buffer) > 0:
            hasher.update(buffer)
            buffer = file.read(block_size)
    return hasher.hexdigest()

def find_duplicate_files(directories):
    file_hashes = defaultdict(list)

    for directory in directories:
        for root, _, files in os.walk(directory):
            for filename in files:
                file_path = os.path.join(root, filename)
                try:
                    file_hash = calculate_file_hash(file_path)
                    file_size = os.path.getsize(file_path)
                    file_hashes[(file_hash, file_size)].append(file_path)
                except (IOError, PermissionError):
                    print(f"Could not access {file_path}")

    duplicate_files = {key: paths for key, paths in file_hashes.items() if len(paths) > 1}
    return duplicate_files

def set_permissions(file_path, permissions):
    try:
        os.chmod(file_path, permissions)
        print(f"Set permissions {oct(permissions)} on {file_path}")
        return True
    except (IOError, PermissionError):
        print(f"Failed to set permissions on {file_path}")
        return False

def delete_file(file_path):
    try:
        os.remove(file_path)
        print(f"Deleted {file_path}")
        return True
    except (IOError, PermissionError):
        print(f"Failed to delete {file_path}")
        return False

def main():
    parser = argparse.ArgumentParser(description='Disk space analyzer to find and manage duplicate files')
    parser.add_argument('directories', metavar='DIR', type=str, nargs='+', help='directories to scan')
    parser.add_argument('--delete', action='store_true', help='delete duplicate files')
    parser.add_argument('--permissions', type=str, help='set permissions on remaining files (octal format, e.g. 0o644)')

    args = parser.parse_args()

    duplicate_files = find_duplicate_files(args.directories)

    if not duplicate_files:
        print("No duplicate files found.")
        return

    total_wasted_space = 0
    file_count = 0

    print("\nDuplicate files found:")
    for (_, size), paths in duplicate_files.items():
        print(f"\nSize: {size} bytes")
        for path in paths:
            print(f"  {path}")
        wasted_space = size * (len(paths) - 1)
        total_wasted_space += wasted_space
        file_count += len(paths) - 1

    print(f"\nTotal wasted space: {total_wasted_space} bytes ({total_wasted_space / (1024 * 1024):.2f} MB)")
    print(f"Duplicate file count: {file_count}")

    if args.delete:
        for (_, _), paths in duplicate_files.items():
            keep_file = paths[0]
            print(f"\nKeeping: {keep_file}")
            for path in paths[1:]:
                delete_file(path)

            if args.permissions:
                try:
                    perm = int(args.permissions, 8)
                    set_permissions(keep_file, perm)
                except ValueError:
                    print(f"Invalid permission format: {args.permissions}")

if __name__ == "__main__":
    main()
```

