    }

    public function getEmail() {
        return $this->email;
    }

    public function setEmail($email) {
        $this->email = $email;
    }

    public function verifyPassword($password) {
        return password_verify($password, $this->passwordHash);
    }

    public function setPassword($password) {
        $this->passwordHash = password_hash($password, PASSWORD_DEFAULT);
    }

    public function getSetting($key) {
        return isset($this->settings[$key]) ? $this->settings[$key] : null;
    }

    public function setSetting($key, $value) {
        $this->settings[$key] = $value;
    }

    public function getAllSettings() {
        return $this->settings;
    }
}

class UserManager {
    private $db;

    public function __construct($db) {
        $this->db = $db;
    }

    public function getUserById($id) {
        $stmt = $this->db->prepare("SELECT * FROM users WHERE id = ?");
        $stmt->execute([$id]);
        return $this->createUserFromData($stmt->fetch());
    }

    public function getUserByEmail($email) {
        $stmt = $this->db->prepare("SELECT * FROM users WHERE email = ?");
        $stmt->execute([$email]);
        return $this->createUserFromData($stmt->fetch());
    }

    public function createUser($username, $email, $password) {
        $passwordHash = password_hash($password, PASSWORD_DEFAULT);
        $stmt = $this->db->prepare("INSERT INTO users (username, email, password_hash) VALUES (?, ?, ?)");
        $stmt->execute([$username, $email, $passwordHash]);
        return $this->getUserById($this->db->lastInsertId());
    }

    public function updateUser(User $user) {
        $stmt = $this->db->prepare("UPDATE users SET username = ?, email = ?, password_hash = ? WHERE id = ?");
        $stmt->execute([
            $user->getUsername(),
            $user->getEmail(),
            $user->getPasswordHash(),
            $user->getId()
        ]);

        $this->saveUserSettings($user);
        return true;
    }

    public function saveUserSettings(User $user) {
        $stmt = $this->db->prepare("DELETE FROM user_settings WHERE user_id = ?");
        $stmt->execute([$user->getId()]);

        $settings = $user->getAllSettings();
        foreach ($settings as $key => $value) {
            $stmt = $this->db->prepare("INSERT INTO user_settings (user_id, setting_key, setting_value) VALUES (?, ?, ?)");
            $stmt->execute([$user->getId(), $key, $value]);
        }
    }

    private function createUserFromData($data) {
        if (!$data) {
            return null;
        }

        $settings = $this->loadUserSettings($data['id']);
        return new User(
            $data['id'],
            $data['username'],
            $data['email'],
            $data['password_hash'],
            $settings
        );
    }

    private function loadUserSettings($userId) {
        $stmt = $this->db->prepare("SELECT setting_key, setting_value FROM user_settings WHERE user_id = ?");
        $stmt->execute([$userId]);
        $settings = [];

        while ($row = $stmt->fetch()) {
            $settings[$row['setting_key']] = $row['setting_value'];
        }

        return $settings;
    }
}
