from typing import Dict, List, Optional

class Medication:
    def __init__(self, name: str, dosage: str, frequency: str, time_of_day: List[str]):
        self.name = name
        self.dosage = dosage
        self.frequency = frequency
        self.time_of_day = time_of_day
        self.last_taken = None

    def take_medication(self):
        self.last_taken = datetime.datetime.now()
        return f"Marked {self.name} as taken at {self.last_taken.strftime('%Y-%m-%d %H:%M')}"

    def to_dict(self):
        return {
            "name": self.name,
            "dosage": self.dosage,
            "frequency": self.frequency,
            "time_of_day": self.time_of_day,
            "last_taken": self.last_taken.strftime('%Y-%m-%d %H:%M') if self.last_taken else None
        }

    @classmethod
    def from_dict(cls, data):
        med = cls(data["name"], data["dosage"], data["frequency"], data["time_of_day"])
        if data["last_taken"]:
            med.last_taken = datetime.datetime.strptime(data["last_taken"], '%Y-%m-%d %H:%M')
        return med

class MedicationReminder:
    def __init__(self):
        self.medications: Dict[str, Medication] = {}
        self.load_medications()

    def add_medication(self, name: str, dosage: str, frequency: str, time_of_day: List[str]) -> str:
        if name in self.medications:
            return f"Medication {name} already exists"

        self.medications[name] = Medication(name, dosage, frequency, time_of_day)
        self.save_medications()
        return f"Added {name} to medication list"

    def remove_medication(self, name: str) -> str:
        if name not in self.medications:
            return f"Medication {name} not found"

        del self.medications[name]
        self.save_medications()
        return f"Removed {name} from medication list"

    def take_medication(self, name: str) -> str:
        if name not in self.medications:
            return f"Medication {name} not found"

        result = self.medications[name].take_medication()
        self.save_medications()
        return result

    def get_medication_info(self, name: str) -> Optional[Dict]:
        if name not in self.medications:
            return None

        return self.medications[name].to_dict()

    def list_all_medications(self) -> List[Dict]:
        return [med.to_dict() for med in self.medications.values()]

    def get_due_medications(self) -> List[Dict]:
        now = datetime.datetime.now()
        current_time = now.strftime("%H:%M")

        due_meds = []
        for med in self.medications.values():
            for time_str in med.time_of_day:
                # Check if current time is within 30 minutes of scheduled time
                scheduled_time = datetime.datetime.strptime(time_str, "%H:%M").time()
                current_datetime = datetime.datetime.strptime(current_time, "%H:%M").time()

                # Calculate time difference in minutes
                t1 = datetime.timedelta(hours=scheduled_time.hour, minutes=scheduled_time.minute)
                t2 = datetime.timedelta(hours=current_datetime.hour, minutes=current_datetime.minute)
                diff_minutes = abs((t1 - t2).total_seconds() / 60)

                if diff_minutes <= 30:
                    if med.last_taken is None or (now - med.last_taken).total_seconds() / 3600 >= 1:
                        due_meds.append(med.to_dict())
                        break

        return due_meds

    def save_medications(self):
        with open("medications.json", "w") as f:
            json.dump({name: med.to_dict() for name, med in self.medications.items()}, f)

    def load_medications(self):
        try:
            with open("medications.json", "r") as f:
                data = json.load(f)
                self.medications = {name: Medication.from_dict(med_data) for name, med_data in data.items()}
        except (FileNotFoundError, json.JSONDecodeError):
