import heapq
import time
import uuid
from enum import Enum
from threading import Lock, Thread
from typing import Dict, List, Optional, Tuple, Callable

class NodeStatus(Enum):
    HEALTHY = "healthy"
    UNHEALTHY = "unhealthy"
    DEAD = "dead"

class Job:
    def __init__(self, job_id: str, payload: dict, priority: int = 0):
        self.id = job_id
        self.payload = payload
        self.priority = priority
        self.created_at = time.time()
        self.assigned_to = None
        self.completed = False
        self.result = None

class Node:
    def __init__(self, node_id: str, capacity: int = 5):
        self.id = node_id
        self.status = NodeStatus.HEALTHY
        self.capacity = capacity
        self.current_jobs: Dict[str, Job] = {}
        self.last_heartbeat = time.time()

    def can_accept_job(self) -> bool:
        return self.status == NodeStatus.HEALTHY and len(self.current_jobs) < self.capacity

    def assign_job(self, job: Job) -> bool:
        if not self.can_accept_job():
            return False
        self.current_jobs[job.id] = job
        job.assigned_to = self.id
        return True

    def complete_job(self, job_id: str, result: any) -> Optional[Job]:
        if job_id not in self.current_jobs:
            return None
        job = self.current_jobs.pop(job_id)
        job.completed = True
        job.result = result
        return job

    def send_heartbeat(self):
        self.last_heartbeat = time.time()

    def check_health(self, timeout: int = 10) -> NodeStatus:
        if time.time() - self.last_heartbeat > timeout * 2:
            self.status = NodeStatus.DEAD
        elif time.time() - self.last_heartbeat > timeout:
            self.status = NodeStatus.UNHEALTHY
        return self.status

class ClusterManager:
    def __init__(self, heartbeat_interval: int = 5, node_timeout: int = 10):
        self.nodes: Dict[str, Node] = {}
        self.job_queue: List[Tuple[int, float, str, Job]] = []  # priority, timestamp, job_id, job
        self.completed_jobs: Dict[str, Job] = {}
        self.heartbeat_interval = heartbeat_interval
        self.node_timeout = node_timeout
        self.lock = Lock()
        self._running = False
        self._scheduler_thread = None
        self._health_check_thread = None

    def register_node(self, node_id: str = None, capacity: int = 5) -> str:
        with self.lock:
            if node_id is None:
                node_id = str(uuid.uuid4())
            if node_id in self.nodes:
                return ""
            self.nodes[node_id] = Node(node_id, capacity)
            return node_id

    def deregister_node(self, node_id: str) -> bool:
        with self.lock:
            if node_id not in self.nodes:
                return False
            node = self.nodes.pop(node_id)
            self._requeue_jobs(node)
            return True

    def _requeue_jobs(self, node: Node):
        for job_id, job in node.current_jobs.items():
            job.assigned_to = None
            self.submit_job(job)

    def submit_job(self, job: Job = None, payload: dict = None, priority: int = 0) -> Optional[str]:
        with self.lock:
            if job is None:
                if payload is None:
                    return None
                job_id = str(uuid.uuid4())
                job = Job(job_id, payload, priority)

            heapq.heappush(
                self.job_queue,
                (-job.priority, job.created_at, job.id, job)
            )
            return job.id

    def get_job(self, node_id: str) -> Optional[Job]:
        with self.lock:
            if node_id not in self.nodes or not self.nodes[node_id].can_accept_job():
                return None

            if not self.job_queue:
                return None

            _, _, _, job = heapq.heappop(self.job_queue)
            if self.nodes[node_id].assign_job(job):
                return job
            else:
                self.submit_job(job)
                return None

    def complete_job(self, node_id: str, job_id: str, result: any) -> bool:
        with self.lock:
            if node_id not in self.nodes:
                return False

            job = self.nodes[node_id].complete_job(job_id, result)
            if job:
                self.completed_jobs[job_id] = job
                return True
            return False

    def send_heartbeat(self, node_id: str) -> bool:
        with self.lock:
            if node_id not in self.nodes:
                return False
            self.nodes[node_id].send_heartbeat()
            if self.nodes[node_id].status != NodeStatus.HEALTHY:
                self.nodes[node_id].status = NodeStatus.HEALTHY
            return True

    def _check_node_health(self):
        with self.lock:
            for node_id, node in list(self.nodes.items()):
                status = node.check_health(self.node_timeout)
                if status == NodeStatus.DEAD:
                    self._requeue_jobs(node)
                    del self.nodes[node_id]

    def _scheduler_loop(self):
        while self._running:
            self._check_node_health()
            time.sleep(self.heartbeat_interval)

    def start(self):
        with self.lock:
            if self._running:
                return
            self._running = True
            self._scheduler_thread = Thread(target=self._scheduler_loop)
            self._scheduler_thread.daemon = True
            self._scheduler_thread.start()

    def stop(self):
        with self.lock:
            self._running = False
            if self._scheduler_thread:
                self._scheduler_thread.join(timeout=5)
                self._scheduler_thread = None
```

