import json
import os
import yaml
import toml

class ConfigManager:
    def __init__(self, default_config_path, user_config_path=None, format="json"):
        self.default_config_path = default_config_path
        self.user_config_path = user_config_path or default_config_path
        self.format = format.lower()
        self.config = self.load_config()

    def load_config(self):
        default_config = self.read_config_file(self.default_config_path)

        if self.user_config_path != self.default_config_path and os.path.exists(self.user_config_path):
            user_config = self.read_config_file(self.user_config_path)
            return self.merge_configs(default_config, user_config)

        return default_config

    def read_config_file(self, path):
        if not os.path.exists(path):
            return {}

        with open(path, 'r') as file:
            if self.format == "json":
                return json.load(file)
            elif self.format == "yaml":
                return yaml.safe_load(file)
            elif self.format == "toml":
                return toml.load(file)
            else:
                raise ValueError(f"Unsupported format: {self.format}")

    def merge_configs(self, default_config, user_config):
        merged = default_config.copy()

        for key, value in user_config.items():
            if isinstance(value, dict) and key in merged and isinstance(merged[key], dict):
                merged[key] = self.merge_configs(merged[key], value)
            else:
                merged[key] = value

        return merged

    def get(self, key, default=None):
        keys = key.split('.')
        value = self.config

        for k in keys:
            if isinstance(value, dict) and k in value:
                value = value[k]
            else:
                return default

        return value

    def save_user_config(self, config=None):
        config_to_save = config if config is not None else self.config

        directory = os.path.dirname(self.user_config_path)
        if directory and not os.path.exists(directory):
            os.makedirs(directory)

        with open(self.user_config_path, 'w') as file:
            if self.format == "json":
                json.dump(config_to_save, file, indent=2)
            elif self.format == "yaml":
                yaml.dump(config_to_save, file)
            elif self.format == "toml":
                toml.dump(config_to_save, file)
