import os
import requests
import zipfile
import shutil
import json
from tqdm import tqdm

class ModInstaller:
    def __init__(self, game_path, mods_repo_url):
        self.game_path = game_path
        self.mods_repo_url = mods_repo_url
        self.mods_path = os.path.join(game_path, "mods")
        self.mods_list = []

        if not os.path.exists(self.mods_path):
            os.makedirs(self.mods_path)

    def fetch_available_mods(self):
        try:
            response = requests.get(f"{self.mods_repo_url}/mods.json")
            response.raise_for_status()
            self.mods_list = response.json()
            return self.mods_list
        except requests.exceptions.RequestException as e:
            print(f"Error fetching mod list: {e}")
            return []

    def download_mod(self, mod_id):
        mod = next((m for m in self.mods_list if m['id'] == mod_id), None)
        if not mod:
            print(f"Mod {mod_id} not found")
            return False

        try:
            download_url = f"{self.mods_repo_url}/downloads/{mod['file']}"
            print(f"Downloading {mod['name']}...")

            temp_path = os.path.join(os.path.dirname(self.mods_path), "temp_mod.zip")
            with requests.get(download_url, stream=True) as r:
                r.raise_for_status()
                total_size = int(r.headers.get('content-length', 0))
                with open(temp_path, 'wb') as f, tqdm(total=total_size, unit='B', unit_scale=True) as pbar:
                    for chunk in r.iter_content(chunk_size=8192):
                        f.write(chunk)
                        pbar.update(len(chunk))

            return self.install_mod(temp_path, mod_id)

        except requests.exceptions.RequestException as e:
            print(f"Error downloading mod: {e}")
            return False

    def install_mod(self, zip_path, mod_id):
        mod_install_path = os.path.join(self.mods_path, mod_id)

        if os.path.exists(mod_install_path):
            shutil.rmtree(mod_install_path)

        try:
            os.makedirs(mod_install_path)

            with zipfile.ZipFile(zip_path, 'r') as zip_ref:
                zip_ref.extractall(mod_install_path)

            os.remove(zip_path)
            print(f"Mod installed successfully to {mod_install_path}")
            return True

        except (zipfile.BadZipFile, OSError) as e:
            print(f"Error installing mod: {e}")
            return False

    def list_installed_mods(self):
        installed = []
        for item in os.listdir(self.mods_path):
            mod_path = os.path.join(self.mods_path, item)
            if os.path.isdir(mod_path):
                mod_info_path = os.path.join(mod_path, "mod.json")
                if os.path.exists(mod_info_path):
                    try:
                        with open(mod_info_path, 'r') as f:
                            mod_info = json.load(f)
                            installed.append(mod_info)
                    except json.JSONDecodeError:
                        installed.append({"id": item, "name": item, "error": "Invalid mod info"})
                else:
                    installed.append({"id": item, "name": item})
        return installed

    def uninstall_mod(self, mod_id):
        mod_path = os.path.join(self.mods_path, mod_id)
        if os.path.exists(mod_path):
            shutil.rmtree(mod_path)
            print(f"Mod {mod_id} uninstalled successfully")
            return True
        else:
            print(f"Mod {mod_id} not found")
            return False


if __name__ == "__main__":
    game_path = os.path.expanduser("~/Documents/0ad")
    repo_url = "https://example.com/0ad-mods"

    installer = ModInstaller(game_path, repo_url)

    print("Fetching available mods...")
    mods = installer.fetch_available_mods()

    print("\nAvailable mods:")
    for i, mod in enumerate(mods, 1):
        print(f"{i}. {mod['name']} - {mod['description']}")

    choice = int(input("\nEnter mod number to install (0 to exit): "))
    if 0 < choice <= len(mods):
        installer.download_mod(mods[choice-1]['id'])

    print("\nInstalled mods:")
    for mod in installer.list_installed_mods():
        print(f"- {mod.get('name', mod['id'])}")
