import os
import hashlib
import shutil
import json
import glob
import datetime


class BinaryArtifactManager:
    def __init__(self, repository_path):
        self.repository_path = repository_path
        self.metadata_file = os.path.join(repository_path, "artifacts.json")
        self.artifacts = self._load_metadata()

        if not os.path.exists(repository_path):
            os.makedirs(repository_path)

    def _load_metadata(self):
        if os.path.exists(self.metadata_file):
            with open(self.metadata_file, 'r') as f:
                return json.load(f)
        return {}

    def _save_metadata(self):
        with open(self.metadata_file, 'w') as f:
            json.dump(self.artifacts, f, indent=2)

    def _calculate_hash(self, file_path):
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for block in iter(lambda: f.read(4096), b''):
                sha256.update(block)
        return sha256.hexdigest()

    def add_artifact(self, file_path, tags=None, version=None):
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File {file_path} does not exist")

        file_name = os.path.basename(file_path)
        file_hash = self._calculate_hash(file_path)
        destination = os.path.join(self.repository_path, file_hash[:2], file_hash[2:4], file_hash)

        os.makedirs(os.path.dirname(destination), exist_ok=True)

        shutil.copy2(file_path, destination)

        artifact_info = {
            "original_name": file_name,
            "hash": file_hash,
            "path": os.path.relpath(destination, self.repository_path),
            "size": os.path.getsize(file_path),
            "timestamp": datetime.datetime.now().isoformat(),
            "tags": tags or [],
            "version": version
        }

        self.artifacts[file_hash] = artifact_info
        self._save_metadata()

        return file_hash

    def get_artifact(self, artifact_id):
        if artifact_id in self.artifacts:
            return os.path.join(self.repository_path, self.artifacts[artifact_id]["path"])
        return None

    def extract_artifact(self, artifact_id, destination=None):
        artifact_path = self.get_artifact(artifact_id)
        if not artifact_path:
            return None

        if destination is None:
            destination = self.artifacts[artifact_id]["original_name"]

        shutil.copy2(artifact_path, destination)
        return destination

    def list_artifacts(self, tag=None, version=None):
        results = []

        for artifact_id, info in self.artifacts.items():
            if tag and tag not in info.get("tags", []):
                continue

            if version and info.get("version") != version:
                continue

            results.append({
                "id": artifact_id,
                "name": info["original_name"],
                "version": info.get("version"),
                "tags": info.get("tags", []),
                "size": info["size"]
            })

        return results

    def delete_artifact(self, artifact_id):
        if artifact_id not in self.artifacts:
            return False

        artifact_path = os.path.join(self.repository_path, self.artifacts[artifact_id]["path"])

        if os.path.exists(artifact_path):
            os.remove(artifact_path)

        del self.artifacts[artifact_id]
        self._save_metadata()

        return True

    def search_artifacts(self, query):
        results = []
        query = query.lower()

        for artifact_id, info in self.artifacts.items():
            if query in info["original_name"].lower():
                results.append(artifact_id)
            elif any(query in tag.lower() for tag in info.get("tags", [])):
                results.append(artifact_id)
            elif info.get("version") and query in info["version"].lower():
                results.append(artifact_id)

        return results

    def cleanup_unused_files(self):
        known_paths = {os.path.join(self.repository_path, info["path"]) 
                      for info in self.artifacts.values()}

        all_files = glob.glob(os.path.join(self.repository_path, "**/*"), recursive=True)
        files_to_remove = [f for f in all_files 
                          if os.path.isfile(f) and f != self.metadata_file and f not in known_paths]

        for file_path in files_to_remove:
            os.remove(file_path)

        return len(files_to_remove)
