import hashlib
import json
import time
import argparse
from pathlib import Path

class DifferentialBackup:
    def __init__(self, source_dir, backup_dir):
        self.source_dir = Path(source_dir).resolve()
        self.backup_dir = Path(backup_dir).resolve()
        self.metadata_file = self.backup_dir / "backup_metadata.json"
        self.old_hashes = {}
        self.new_hashes = {}
        self.changed_files = []

    def load_metadata(self):
        if self.metadata_file.exists():
            with open(self.metadata_file, 'r') as f:
                self.old_hashes = json.load(f)
        else:
            self.old_hashes = {}

    def save_metadata(self):
        with open(self.metadata_file, 'w') as f:
            json.dump(self.new_hashes, f, indent=2)

    def compute_file_hash(self, filepath):
        hasher = hashlib.sha256()
        with open(filepath, 'rb') as f:
            buf = f.read(65536)
            while len(buf) > 0:
                hasher.update(buf)
                buf = f.read(65536)
        return hasher.hexdigest()

    def scan_files(self):
        for root, _, files in os.walk(self.source_dir):
            for filename in files:
                filepath = Path(root) / filename
                if filepath.is_file():
                    rel_path = str(filepath.relative_to(self.source_dir))
                    try:
                        file_hash = self.compute_file_hash(filepath)
                        self.new_hashes[rel_path] = {
                            'hash': file_hash,
                            'mtime': filepath.stat().st_mtime
                        }

                        if rel_path not in self.old_hashes or self.old_hashes[rel_path]['hash'] != file_hash:
                            self.changed_files.append(rel_path)
                    except (PermissionError, FileNotFoundError):
                        continue

    def create_backup(self):
        if not self.changed_files:
            print("No changes detected, skipping backup.")
            return None

        timestamp = time.strftime("%Y%m%d-%H%M%S")
        backup_file = self.backup_dir / f"backup-{timestamp}.tar.gz"

        with tarfile.open(backup_file, "w:gz") as tar:
            for file_path in self.changed_files:
                abs_path = self.source_dir / file_path
                if abs_path.exists():
                    tar.add(abs_path, arcname=file_path)
                    print(f"Added to backup: {file_path}")

        return backup_file

    def run_backup(self):
        os.makedirs(self.backup_dir, exist_ok=True)
        self.load_metadata()
        self.scan_files()
        backup_file = self.create_backup()
        self.save_metadata()

        if backup_file:
            print(f"Backup completed: {backup_file}")
            print(f"Files changed: {len(self.changed_files)}")

        return backup_file

def main():
    parser = argparse.ArgumentParser(description="Differential backup tool")
    parser.add_argument("source", help="Source directory to backup")
    parser.add_argument("destination", help="Destination directory for backups")
    args = parser.parse_args()

    backup = DifferentialBackup(args.source, args.destination)
    backup.run_backup()

if __name__ == "__main__":
    main()
