def init_db():
    conn = sqlite3.connect('ideas.db')
    c = conn.cursor()
    c.execute('''
    CREATE TABLE IF NOT EXISTS ideas
    (id INTEGER PRIMARY KEY AUTOINCREMENT,
    idea TEXT NOT NULL,
    description TEXT)
    ''')
    conn.commit()
    conn.close()

@app.route("/", methods=["GET"])
def home():
    conn = sqlite3.connect('ideas.db')
    c = conn.cursor()
    c.execute("SELECT id, idea, description FROM ideas")
    ideas = c.fetchall()
    conn.close()
    return render_template("index.html", ideas=ideas)

@app.route("/idea/<idea_id>", methods=["POST"])
def idea(idea_id):
    idea = request.form.get("idea")
    description = request.form.get("description")

    if not idea:
        return "Idea is required", 400

    conn = sqlite3.connect('ideas.db')
    c = conn.cursor()

    if idea_id == "new":
        c.execute("INSERT INTO ideas (idea, description) VALUES (?, ?)", (idea, description))
    else:
        c.execute("UPDATE ideas SET idea = ?, description = ? WHERE id = ?", (idea, description, idea_id))

    conn.commit()
    conn.close()

    return redirect(url_for('home'))

@app.route("/idea/new", methods=["GET"])
def new_idea():
    return render_template("idea_form.html", idea=None, description=None, idea_id="new")

@app.route("/idea/<idea_id>/edit", methods=["GET"])
def edit_idea(idea_id):
    conn = sqlite3.connect('ideas.db')
    c = conn.cursor()
    c.execute("SELECT idea, description FROM ideas WHERE id = ?", (idea_id,))
    result = c.fetchone()
    conn.close()

    if not result:
        return "Idea not found", 404

    idea, description = result
    return render_template("idea_form.html", idea=idea, description=description, idea_id=idea_id)

@app.route("/idea/<idea_id>/delete", methods=["POST"])
def delete_idea(idea_id):
    conn = sqlite3.connect('ideas.db')
    c = conn.cursor()
    c.execute("DELETE FROM ideas WHERE id = ?", (idea_id,))
    conn.commit()
    conn.close()

    return redirect(url_for('home'))

if __name__ == "__main__":
    init_db()
    app.run()
