import SwiftUI
import CoreLocation
import MapKit

struct Run: Identifiable, Codable {
    var id = UUID()
    var name: String
    var date: Date
    var distance: Double
    var duration: TimeInterval
    var maxSpeed: Double
    var averageSpeed: Double
    var locations: [CLLocationCoordinate2D]
    var liftRide: Bool
}

extension CLLocationCoordinate2D: Codable {
    enum CodingKeys: String, CodingKey {
        case latitude, longitude
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        let latitude = try container.decode(Double.self, forKey: .latitude)
        let longitude = try container.decode(Double.self, forKey: .longitude)
        self.init(latitude: latitude, longitude: longitude)
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.container(keyedBy: CodingKeys.self)
        try container.encode(latitude, forKey: .latitude)
        try container.encode(longitude, forKey: .longitude)
    }
}

class LocationManager: NSObject, ObservableObject, CLLocationManagerDelegate {
    private var locationManager = CLLocationManager()
    @Published var locations: [CLLocationCoordinate2D] = []
    @Published var isTracking = false
    @Published var currentSpeed: Double = 0
    @Published var maxSpeed: Double = 0
    @Published var distance: Double = 0
    @Published var startTime: Date?

    override init() {
        super.init()
        locationManager.delegate = self
        locationManager.desiredAccuracy = kCLLocationAccuracyBest
        locationManager.distanceFilter = 5
        locationManager.requestWhenInUseAuthorization()
    }

    func startTracking(isLift: Bool = false) {
        locations.removeAll()
        isTracking = true
        maxSpeed = 0
        distance = 0
        startTime = Date()
        locationManager.startUpdatingLocation()
    }

    func stopTracking() -> Run? {
        locationManager.stopUpdatingLocation()
        guard isTracking, let startTime = startTime, !locations.isEmpty else { return nil }

        let duration = Date().timeIntervalSince(startTime)
        let averageSpeed = duration > 0 ? distance / duration : 0

        let run = Run(
            name: "Run \(Date())",
            date: startTime,
            distance: distance,
            duration: duration,
            maxSpeed: maxSpeed,
            averageSpeed: averageSpeed,
            locations: locations,
            liftRide: false
        )

        isTracking = false
        return run
    }

    func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        guard isTracking, let location = locations.last else { return }

        let coordinate = location.coordinate
        self.locations.append(coordinate)

        if self.locations.count >= 2 {
            let lastLocation = self.locations[self.locations.count - 2]
            let newLocation = coordinate

            let loc1 = CLLocation(latitude: lastLocation.latitude, longitude: lastLocation.longitude)
            let loc2 = CLLocation(latitude: newLocation.latitude, longitude: newLocation.longitude)

            let distanceInMeters = loc1.distance(from: loc2)
            distance += distanceInMeters / 1000 // convert to km
        }

        currentSpeed = location.speed > 0 ? location.speed * 3.6 : 0 // convert to km/h
        maxSpeed = max(maxSpeed, currentSpeed)
    }
}

class RunStore: ObservableObject {
    @Published var runs: [Run] = []

    init() {
        loadRuns()
    }

    func addRun(_ run: Run) {
        runs.append(run)
        saveRuns()
    }

    func removeRun(at index: Int) {
        runs.remove(at: index)
        saveRuns()
    }

    private func loadRuns() {
        if let data = UserDefaults.standard.data(forKey: "runs") {
            if let decoded = try? JSONDecoder().decode([Run].self, from: data) {
                runs = decoded
                return
            }
        }
        runs = []
    }

    private func saveRuns() {
        if let encoded = try? JSONEncoder().encode(runs) {
            UserDefaults.standard.set(encoded, forKey: "runs")
        }
    }
}

struct TrackingView: View {
    @StateObject private var locationManager = LocationManager()
    @EnvironmentObject var runStore: RunStore
    @State private var isLiftRide = false
    @State private var showingAlert = false

    var body: some View {
        VStack {
            if locationManager.isTracking {
                MapView(coordinates: locationManager.locations)
                    .frame(height: 300)
                    .cornerRadius(10)

                VStack(spacing: 20) {
                    StatsRow(label: "Current Speed", value: "\(String(format: "%.1f", locationManager.currentSpeed)) km/h")
                    StatsRow(label: "Max Speed", value: "\(String(format: "%.1f", locationManager.maxSpeed)) km/h")
                    StatsRow(label: "Distance", value: "\(String(format: "%.2f", locationManager.distance)) km")
                    StatsRow(label: "Duration", value: formattedDuration)
                    StatsRow(label: "Type", value: isLiftRide ? "Lift Ride" : "Ski/Board Run")
                }
                .padding()

                Button("Stop Tracking") {
                    if let run = locationManager.stopTracking() {
                        var runWithType = run
                        runWithType.liftRide = isLiftRide
                        runStore.addRun(runWithType)
                        showingAlert = true
                    }
                }
                .padding()
                .background(Color.red)
                .foregroundColor(.white)
                .cornerRadius(10)
                .padding()
            } else {
                VStack(spacing: 20) {
                    Text("Start tracking a new run")
                        .font(.title)

                    Toggle("Lift Ride", isOn: $isLiftRide)
                        .padding()

                    Button("Start Tracking") {
                        locationManager.startTracking(isLift: isLiftRide)
                    }
                    .padding()
                    .background(Color.blue)
                    .foregroundColor(.white)
                    .cornerRadius(10)
                }
