            return redirect(url_for('display_feed', feed_url=feed_url))
    return render_template('index.html')

@app.route('/feed')
def display_feed():
    feed_url = request.args.get('feed_url')
    if not feed_url:
        return redirect(url_for('index'))

    feed = feedparser.parse(feed_url)

    if feed.bozo and not feed.entries:
        error = "Invalid feed or URL"
        return render_template('index.html', error=error)

    feed_data = {
        'title': feed.feed.get('title', 'No Title'),
        'subtitle': feed.feed.get('subtitle', ''),
        'link': feed.feed.get('link', ''),
        'updated': feed.feed.get('updated', ''),
        'entries': []
    }

    for entry in feed.entries:
        feed_data['entries'].append({
            'title': entry.get('title', 'No Title'),
            'link': entry.get('link', ''),
            'description': html.escape(entry.get('description', entry.get('summary', ''))),
            'published': entry.get('published', entry.get('updated', '')),
            'author': entry.get('author', 'Unknown')
        })

    return render_template('feed.html', feed=feed_data)

if __name__ == '__main__':
