import os
import tarfile
import tempfile
import subprocess

def convert_video(video_path, output_format):
    output_path = os.path.splitext(video_path)[0] + '.' + output_format
    try:
        subprocess.run(['ffmpeg', '-i', video_path, '-c:v', 'libx264', '-c:a', 'aac', output_path], 
                      check=True, capture_output=True)
        return output_path
    except subprocess.CalledProcessError:
        return None

def convert_videos_in_dir(dir_path, output_format):
    for fname in os.listdir(dir_path):
        video_path = os.path.join(dir_path, fname)
        if os.path.isfile(video_path) and fname.endswith((".mp4", ".mov", ".avi")):
            convert_video(video_path, output_format)

def convert_videos_in_tarball(tar_path, output_format):
    tar = tarfile.open(tar_path)
    temp_dir = tempfile.mkdtemp()

    tar.extractall(path=temp_dir)
    tar.close()

    for root, dirs, files in os.walk(temp_dir):
        for file in files:
            if file.endswith((".mp4", ".mov", ".avi")):
                video_path = os.path.join(root, file)
                convert_video(video_path, output_format)

    # Clean up
    for root, dirs, files in os.walk(temp_dir, topdown=False):
        for file in files:
            os.remove(os.path.join(root, file))
        for dir in dirs:
            os.rmdir(os.path.join(root, dir))
    os.rmdir(temp_dir)

