from datetime import datetime
from typing import List, Dict, Optional
import uuid

class Flight:
    def __init__(self, flight_number: str, airline: str, departure_airport: str, 
                arrival_airport: str, departure_time: datetime, arrival_time: datetime, price: float):
        self.flight_number = flight_number
        self.airline = airline
        self.departure_airport = departure_airport
        self.arrival_airport = arrival_airport
        self.departure_time = departure_time
        self.arrival_time = arrival_time
        self.price = price

    def __str__(self):
        return f"{self.airline} {self.flight_number}: {self.departure_airport} to {self.arrival_airport} on {self.departure_time.strftime('%Y-%m-%d %H:%M')}"

class Hotel:
    def __init__(self, name: str, address: str, check_in_date: datetime, 
                check_out_date: datetime, room_type: str, price_per_night: float):
        self.name = name
        self.address = address
        self.check_in_date = check_in_date
        self.check_out_date = check_out_date
        self.room_type = room_type
        self.price_per_night = price_per_night

    def get_total_price(self) -> float:
        nights = (self.check_out_date - self.check_in_date).days
        return nights * self.price_per_night

    def __str__(self):
        return f"{self.name}: {self.room_type} from {self.check_in_date.strftime('%Y-%m-%d')} to {self.check_out_date.strftime('%Y-%m-%d')}"

class Trip:
    def __init__(self, trip_name: str, traveler_name: str, traveler_email: str):
        self.id = str(uuid.uuid4())
        self.trip_name = trip_name
        self.traveler_name = traveler_name
        self.traveler_email = traveler_email
        self.flights: List[Flight] = []
        self.hotels: List[Hotel] = []
        self.is_booked = False

    def add_flight(self, flight: Flight):
        self.flights.append(flight)

    def add_hotel(self, hotel: Hotel):
        self.hotels.append(hotel)

    def get_total_price(self) -> float:
        flight_total = sum(flight.price for flight in self.flights)
        hotel_total = sum(hotel.get_total_price() for hotel in self.hotels)
        return flight_total + hotel_total

    def book(self) -> bool:
        if not self.flights:
            raise ValueError("Trip must have at least one flight")
        self.is_booked = True
        return True

    def get_itinerary(self) -> str:
        result = f"Trip: {self.trip_name}\nTraveler: {self.traveler_name}\n\nFlights:\n"
        for flight in sorted(self.flights, key=lambda f: f.departure_time):
            result += f"- {flight}\n"

        if self.hotels:
            result += "\nHotels:\n"
            for hotel in sorted(self.hotels, key=lambda h: h.check_in_date):
                result += f"- {hotel}\n"

        result += f"\nTotal Price: ${self.get_total_price():.2f}"
        return result

class BookingSystem:
    def __init__(self):
        self.trips: Dict[str, Trip] = {}
        self.available_flights: List[Flight] = []
        self.available_hotels: List[Hotel] = []

    def create_trip(self, trip_name: str, traveler_name: str, traveler_email: str) -> Trip:
        trip = Trip(trip_name, traveler_name, traveler_email)
        self.trips[trip.id] = trip
        return trip

    def get_trip(self, trip_id: str) -> Optional[Trip]:
        return self.trips.get(trip_id)

    def add_available_flight(self, flight: Flight):
        self.available_flights.append(flight)

    def add_available_hotel(self, hotel: Hotel):
        self.available_hotels.append(hotel)

    def search_flights(self, departure: str, arrival: str, date: datetime) -> List[Flight]:
        return [
            flight for flight in self.available_flights
            if flight.departure_airport == departure and
               flight.arrival_airport == arrival and
               flight.departure_time.date() == date.date()
        ]

    def search_hotels(self, location: str, check_in: datetime, check_out: datetime) -> List[Hotel]:
        return [
            hotel for hotel in self.available_hotels
            if location in hotel.address and
               hotel.check_in_date.date() <= check_in.date() and
               hotel.check_out_date.date() >= check_out.date()
        ]
