                'tar',
                self.source_path,
                None,
                True,
                mode
            )
        else:
            with tarfile.open(self.output_path, f'w:{mode}') as tar:
                tar.add(self.source_path, arcname=os.path.basename(self.source_path))
        return self.output_path

    def _compress_7z(self):
