@app.route('/')
def home():
    return render_template('index.html', articles=articles)

@app.route('/article', methods=['GET', 'POST'])
def article():
    if request.method == 'POST':
        title = request.form.get('title')
        content = request.form.get('content')

        # Validate input
        if not title or not content:
            return jsonify({'error': 'Title and content are required'}), 400

        article_id = str(uuid.uuid4())

        # Handle image upload
        image_filename = None
        if 'image' in request.files:
            image = request.files['image']
            if image.filename:
                image_filename = secure_filename(image.filename)
                image_path = os.path.join(app.config['UPLOAD_FOLDER'], image_filename)
                image.save(image_path)

        # Handle video upload
        video_filename = None
        if 'video' in request.files:
            video = request.files['video']
            if video.filename:
                video_filename = secure_filename(video.filename)
                video_path = os.path.join(app.config['UPLOAD_FOLDER'], video_filename)
                video.save(video_path)

        articles[article_id] = {
            'id': article_id,
            'title': title,
            'content': content,
            'image': image_filename,
            'video': video_filename
        }

        return jsonify({'id': article_id, 'message': 'Article created successfully'})

    # GET method - list articles or get specific article
    article_id = request.args.get('id')
    if article_id:
        if article_id in articles:
            return jsonify(articles[article_id])
        return jsonify({'error': 'Article not found'}), 404

    return jsonify(list(articles.values()))

@app.route('/article/<article_id>', methods=['GET', 'PUT', 'DELETE'])
def manage_article(article_id):
    if article_id not in articles:
        return jsonify({'error': 'Article not found'}), 404

    if request.method == 'GET':
        return jsonify(articles[article_id])

    elif request.method == 'PUT':
        data = request.get_json()
        if 'title' in data:
            articles[article_id]['title'] = data['title']
        if 'content' in data:
            articles[article_id]['content'] = data['content']
        return jsonify({'message': 'Article updated successfully'})

    elif request.method == 'DELETE':
        # Delete associated files
        if articles[article_id]['image']:
            try:
                os.remove(os.path.join(app.config['UPLOAD_FOLDER'], articles[article_id]['image']))
            except:
                pass
        if articles[article_id]['video']:
            try:
                os.remove(os.path.join(app.config['UPLOAD_FOLDER'], articles[article_id]['video']))
            except:
                pass

        del articles[article_id]
        return jsonify({'message': 'Article deleted successfully'})

