  createdAt: { type: Date, default: Date.now },
  answers: [{
    content: String,
    userId: String,
    createdAt: { type: Date, default: Date.now },
    votes: { type: Number, default: 0 }
  }]
});

const Question = mongoose.model('Question', QuestionSchema);

