import tarfile
import os
import json
import hashlib
from datetime import datetime

def create_dataset_tarball(dataset_files, output_file, metadata=None):
    with tarfile.open(output_file, "w:gz") as tar:
        # Add each file to the tarball
        for file_path in dataset_files:
            if os.path.exists(file_path):
                file_name = os.path.basename(file_path)
                tar.add(file_path, arcname=f"data/{file_name}")

        # Create and add metadata
        if metadata is None:
            metadata = {}

        # Add basic metadata
        metadata.update({
            "created_at": datetime.now().isoformat(),
            "file_count": len(dataset_files),
            "files": [os.path.basename(f) for f in dataset_files if os.path.exists(f)],
            "checksums": {os.path.basename(f): calculate_checksum(f) for f in dataset_files if os.path.exists(f)}
        })

        # Write metadata to a file and add to tarball
        metadata_file = "metadata.json"
        with open(metadata_file, "w") as f:
            json.dump(metadata, f, indent=2)

        tar.add(metadata_file, arcname="metadata.json")
        os.remove(metadata_file)

def extract_dataset(tar_file):
    tar = tarfile.open(tar_file)
    tar.extractall()
    metadata = {}
    if "metadata.json" in [m.name for m in tar.getmembers()]:
        tar.extract("metadata.json")
        with open("metadata.json", "r") as f:
            metadata = json.load(f)
    tar.close()
    return metadata

def calculate_checksum(file_path):
    sha256 = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for block in iter(lambda: f.read(4096), b''):
            sha256.update(block)
    return sha256.hexdigest()

def validate_dataset(tar_file):
    metadata = extract_dataset(tar_file)
    if not metadata or "checksums" not in metadata:
        return False

    for file_name, checksum in metadata["checksums"].items():
        file_path = os.path.join("data", file_name)
        if not os.path.exists(file_path):
            return False
        if calculate_checksum(file_path) != checksum:
            return False

    return True
