    def listen_for_connections(self):
        while True:
            client_socket, addr = self.server_socket.accept()
            threading.Thread(target=self.handle_connection, args=(client_socket,), daemon=True).start()

    def handle_connection(self, client_socket):
        try:
            data = b''
