import os
import shutil
import argparse
from datetime import datetime
import stat
import sys

def sync_directories(source_dir, dest_dir, overwrite=False, preserve_permissions=False, recursive=False, verbose=False):
    if not os.path.exists(source_dir):
        raise FileNotFoundError(f"Source directory {source_dir} does not exist")

    if not os.path.exists(dest_dir):
        os.makedirs(dest_dir)

    files = []
    if recursive:
        for root, _, filenames in os.walk(source_dir):
            rel_path = os.path.relpath(root, source_dir)
            for filename in filenames:
                files.append(os.path.join(rel_path, filename))
    else:
        files = [f for f in os.listdir(source_dir) if os.path.isfile(os.path.join(source_dir, f))]

    for file in files:
        src_file = os.path.join(source_dir, file)
        dst_file = os.path.join(dest_dir, file)

        dst_dir = os.path.dirname(dst_file)
        if not os.path.exists(dst_dir):
            os.makedirs(dst_dir)

        if not os.path.exists(dst_file) or overwrite:
            if verbose:
                print(f"Copying {src_file} to {dst_file}")

            if preserve_permissions:
                shutil.copy2(src_file, dst_file)
            else:
                shutil.copy(src_file, dst_file)
        elif verbose:
            print(f"Skipping {src_file} (already exists and overwrite is False)")

def main():
    parser = argparse.ArgumentParser(description="Synchronize files between directories")
    parser.add_argument("source", help="Source directory")
    parser.add_argument("destination", help="Destination directory")
    parser.add_argument("-o", "--overwrite", action="store_true", help="Overwrite existing files")
    parser.add_argument("-p", "--preserve", action="store_true", help="Preserve file permissions")
    parser.add_argument("-r", "--recursive", action="store_true", help="Recurse into subdirectories")
    parser.add_argument("-v", "--verbose", action="store_true", help="Verbose output")

    args = parser.parse_args()

    try:
        sync_directories(
            args.source,
            args.destination,
            overwrite=args.overwrite,
            preserve_permissions=args.preserve,
            recursive=args.recursive,
            verbose=args.verbose
        )
    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
    main()
