def parse_receipt(text):
    receipt_data = {
        'date': None,
        'total': None,
        'merchant': None,
        'items': []
    }

    lines = text.split('\n')

    # Extract merchant (assuming it's in the first line)
    if lines:
        receipt_data['merchant'] = lines[0].strip()

    # Extract total amount
    total_pattern = re.compile(r'total[:\s]*\$?(\d+\.\d{2})', re.IGNORECASE)
    for line in lines:
        total_match = total_pattern.search(line)
        if total_match:
            receipt_data['total'] = float(total_match.group(1))
            break

    # Extract date
    date_pattern = re.compile(r'(\d{1,2}[/.-]\d{1,2}[/.-]\d{2,4})')
    for line in lines:
        date_match = date_pattern.search(line)
        if date_match:
            receipt_data['date'] = date_match.group(1)
            break

    # Extract items (basic implementation)
    item_pattern = re.compile(r'^(.+?)\s+\$?(\d+\.\d{2})$')
    for line in lines:
        item_match = item_pattern.search(line)
        if item_match and 'total' not in line.lower():
            item_name = item_match.group(1).strip()
            item_price = float(item_match.group(2))
            receipt_data['items'].append({
                'name': item_name,
                'price': item_price
            })

