import os
import heapq
from pathlib import Path

def get_file_size(file_path):
    try:
        return os.path.getsize(file_path)
    except (OSError, FileNotFoundError):
        return 0

def scan_directory(directory, top_n=20):
    largest_files = []
    total_size = 0

    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            size = get_file_size(file_path)
            total_size += size

            if len(largest_files) < top_n:
                heapq.heappush(largest_files, (size, file_path))
            else:
                heapq.heappushpop(largest_files, (size, file_path))

    return sorted(largest_files, reverse=True), total_size

def format_size(size):
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if size < 1024.0:
            return f"{size:.2f} {unit}"
        size /= 1024.0

def main():
    directory = input("Enter directory path to analyze: ")
    top_n = int(input("How many top files to display? [20]: ") or "20")

    if not os.path.isdir(directory):
        print(f"Error: {directory} is not a valid directory")
        return

    print(f"\nScanning {directory}...")
    largest_files, total_size = scan_directory(directory, top_n)

    print(f"\nTotal space used: {format_size(total_size)}")
    print(f"\nTop {len(largest_files)} largest files:")

    for i, (size, path) in enumerate(largest_files, 1):
        print(f"{i}. {format_size(size)} - {path}")
        percentage = (size / total_size) * 100 if total_size > 0 else 0
        print(f"   {percentage:.2f}% of total space")

if __name__ == "__main__":
