import redis
import uuid
import json
import time
from typing import Dict, Any, Optional

class DistributedQueue:
    def __init__(self, redis_host: str = "localhost", redis_port: int = 6379, queue_name: str = "task_queue"):
        self.redis_client = redis.Redis(host=redis_host, port=redis_port)
        self.queue_name = queue_name
        self.processing_queue = f"{queue_name}_processing"

    def enqueue(self, data: Dict[str, Any]) -> str:
        task_id = str(uuid.uuid4())
        task = {
            "id": task_id,
            "data": data,
            "timestamp": time.time()
        }
        self.redis_client.lpush(self.queue_name, json.dumps(task))
        return task_id

    def dequeue(self, timeout: int = 0) -> Optional[Dict[str, Any]]:
        result = self.redis_client.brpoplpush(self.queue_name, self.processing_queue, timeout)
        if result:
            task = json.loads(result)
            return task
        return None

    def complete(self, task_id: str) -> None:
        for idx in range(self.redis_client.llen(self.processing_queue)):
            task_json = self.redis_client.lindex(self.processing_queue, idx)
            if task_json:
                task = json.loads(task_json)
                if task["id"] == task_id:
                    self.redis_client.lrem(self.processing_queue, 1, task_json)
                    break

    def requeue_timed_out(self, timeout_seconds: int = 300) -> int:
        now = time.time()
        count = 0

        for idx in range(self.redis_client.llen(self.processing_queue)):
            task_json = self.redis_client.lindex(self.processing_queue, idx)
            if task_json:
                task = json.loads(task_json)
                if now - task["timestamp"] > timeout_seconds:
                    self.redis_client.lrem(self.processing_queue, 1, task_json)
                    self.redis_client.lpush(self.queue_name, task_json)
                    count += 1

        return count

class Node:
    def __init__(self, node_id: str, redis_host: str = "localhost", redis_port: int = 6379):
        self.node_id = node_id
        self.queue = DistributedQueue(redis_host, redis_port)

    def submit_task(self, user_input: Dict[str, Any]) -> str:
        return self.queue.enqueue({
            "user_input": user_input,
            "source_node": self.node_id,
            "status": "pending"
        })

    def process_tasks(self, callback):
        while True:
            task = self.queue.dequeue(timeout=1)
            if task:
                try:
                    result = callback(task["data"]["user_input"])
                    self.queue.complete(task["id"])
                except Exception as e:
                    print(f"Error processing task {task['id']}: {e}")
            time.sleep(0.1)

def example_usage():
    node1 = Node("node1")
    node2 = Node("node2")

    task_id = node1.submit_task({"command": "process_image", "params": {"url": "http://example.com/image.jpg"}})
    print(f"Submitted task: {task_id}")

    def process_callback(user_input):
        print(f"Processing: {user_input}")
        return {"status": "completed", "result": "processed successfully"}

    node2.process_tasks(process_callback)

if __name__ == "__main__":
    example_usage()
