def extract_and_organize(tar_path):
    tar = tarfile.open(tar_path)
    tar.extractall()
    tar.close()

    os.makedirs('lib', exist_ok=True)
    os.makedirs('tests', exist_ok=True)

    for member in tar.getmembers():
        if member.name.startswith('src/'):
            if os.path.exists(member.name):
                dest_path = os.path.join('lib', os.path.basename(member.name))
                shutil.move(member.name, dest_path)
        elif member.name.startswith('tests/'):
