import ast
import sys
from typing import Any, Dict, List, Optional, Set, Tuple, Union

def infer_type(node: ast.AST) -> str:
    if isinstance(node, ast.Num):
        if isinstance(node.n, int):
            return "int"
        elif isinstance(node.n, float):
            return "float"
        return "Any"
    elif isinstance(node, ast.Str):
        return "str"
    elif isinstance(node, ast.List):
        return "List[Any]"
    elif isinstance(node, ast.Dict):
        return "Dict[Any, Any]"
    elif isinstance(node, ast.Tuple):
        return "Tuple[Any, ...]"
    elif isinstance(node, ast.Set):
        return "Set[Any]"
    elif isinstance(node, ast.NameConstant):
        if node.value is None:
            return "None"
        elif isinstance(node.value, bool):
            return "bool"
    elif isinstance(node, ast.Call):
        if isinstance(node.func, ast.Name):
            if node.func.id in ['int', 'float', 'str', 'bool', 'list', 'dict', 'tuple', 'set']:
                return node.func.id
    return "Any"

class TypeAnnotator(ast.NodeVisitor):
    def __init__(self):
        self.functions = {}
        self.imports = set()

    def visit_FunctionDef(self, node):
        arg_types = {}
        for arg in node.args.args:
            if arg.annotation is None:
                arg.annotation = ast.Name(id='Any', ctx=ast.Load())
                arg_types[arg.arg] = 'Any'

        if node.returns is None:
            node.returns = ast.Name(id='Any', ctx=ast.Load())

        self.functions[node.name] = {
            'args': arg_types,
            'return': 'Any'
        }

        self.generic_visit(node)

    def visit_Import(self, node):
        for name in node.names:
            if name.name == 'typing':
                self.imports.add('typing')
        self.generic_visit(node)

    def visit_ImportFrom(self, node):
        if node.module == 'typing':
            self.imports.add('typing')
        self.generic_visit(node)

def add_typing_import(tree: ast.AST) -> ast.AST:
    has_typing = False
    for node in ast.walk(tree):
        if isinstance(node, (ast.Import, ast.ImportFrom)):
            if isinstance(node, ast.Import):
                for name in node.names:
                    if name.name == 'typing':
                        has_typing = True
            elif isinstance(node, ast.ImportFrom) and node.module == 'typing':
                has_typing = True

    if not has_typing:
        typing_import = ast.Import(names=[ast.alias(name='typing', asname=None)])
        tree.body.insert(0, typing_import)

    return tree

def annotate_file(file_path: str) -> str:
    with open(file_path, 'r') as f:
        code = f.read()

    tree = ast.parse(code)
    annotator = TypeAnnotator()
    annotator.visit(tree)

    if 'Any' in str(ast.dump(tree)):
        tree = add_typing_import(tree)

    return ast.unparse(tree)

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python type_annotator.py <python_file>")
        sys.exit(1)

    file_path = sys.argv[1]
    annotated_code = annotate_file(file_path)

    output_path = file_path.replace('.py', '_annotated.py')
    with open(output_path, 'w') as f:
        f.write(annotated_code)

