import argparse
import sys

def concatenate_files(input_files, output_file=None):
    output = sys.stdout if output_file is None else open(output_file, 'wb')

    try:
        for file_path in input_files:
            try:
                with open(file_path, 'rb') as f:
                    while True:
                        buffer = f.read(8192)
                        if not buffer:
                            break
                        output.write(buffer)
            except IOError as e:
                print(f"Error reading {file_path}: {e}", file=sys.stderr)
    finally:
        if output is not sys.stdout:
            output.close()

def main():
    parser = argparse.ArgumentParser(description='Concatenate multiple files into one.')
    parser.add_argument('input_files', nargs='+', help='Input files to concatenate')
    parser.add_argument('-o', '--output', help='Output file (default: stdout)')

    args = parser.parse_args()
    concatenate_files(args.input_files, args.output)

if __name__ == '__main__':
    main()
