    if 'name' not in request.form or 'story' not in request.form or 'image' not in request.files:
        return jsonify({"error": "Missing required fields"}), 400

    name = request.form.get("name")
    story = request.form.get("story")
    image = request.files["image"]

    if name.strip() == "" or story.strip() == "":
        return jsonify({"error": "Name and story cannot be empty"}), 400

    if image.filename == '':
        return jsonify({"error": "No image selected"}), 400

    ext = os.path.splitext(image.filename)[1].lower()
    if ext not in ['.jpg', '.jpeg', '.png', '.gif']:
        return jsonify({"error": "Invalid image format"}), 400

    filename = secure_filename(str(uuid.uuid4()) + ext)
    filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
    image.save(filepath)

    story_id = str(uuid.uuid4())
    stories.append({
        "id": story_id,
        "name": name,
        "story": story,
        "image": filename
    })

