import os
import requests
import hashlib
from urllib.parse import urlparse
from datetime import datetime

class BrowserCache:
    def __init__(self, cache_dir="cache"):
        self.cache_dir = cache_dir
        if not os.path.exists(cache_dir):
            os.makedirs(cache_dir)
        self.history = []

    def url_to_filename(self, url):
        url_hash = hashlib.md5(url.encode()).hexdigest()
        parsed_url = urlparse(url)
        domain = parsed_url.netloc
        return f"{domain}_{url_hash}"

    def save_to_cache(self, url, content):
        filename = self.url_to_filename(url)
        filepath = os.path.join(self.cache_dir, filename)
        with open(filepath, 'wb') as f:
            f.write(content)
        return filepath

    def get_from_cache(self, url):
        filename = self.url_to_filename(url)
        filepath = os.path.join(self.cache_dir, filename)
        if os.path.exists(filepath):
            with open(filepath, 'rb') as f:
                return f.read()
        return None

    def visit(self, url):
        self.history.append((url, datetime.now()))

        cached_content = self.get_from_cache(url)
        if cached_content:
            print(f"Loading {url} from cache")
            return cached_content

        try:
            print(f"Fetching {url} from internet")
            response = requests.get(url, timeout=10)
            if response.status_code == 200:
                content = response.content
                self.save_to_cache(url, content)
                return content
            else:
                print(f"Error: Status code {response.status_code}")
                return None
        except Exception as e:
            print(f"Error fetching {url}: {e}")
            return None

    def show_history(self):
        for url, timestamp in self.history:
            print(f"{timestamp.strftime('%Y-%m-%d %H:%M:%S')} - {url}")

    def clear_cache(self):
        for file in os.listdir(self.cache_dir):
            os.remove(os.path.join(self.cache_dir, file))
        print("Cache cleared")

# Example usage
if __name__ == "__main__":
    browser = BrowserCache()
    content = browser.visit("https://example.com")
    if content:
        print(f"Page size: {len(content)} bytes")

    # Visit again (should be from cache)
    content = browser.visit("https://example.com")

    browser.show_history()
