                        if amount > highest_bid:
                            highest_bid = amount
                            highest_bidder = parts[1]
                    except ValueError:
                        continue

        if bid_amount and bidder_name and bid_amount > highest_bid:
            f.write(f"{listing_id},{bidder_name},{bid_amount}\n")
            highest_bid = bid_amount
            highest_bidder = bidder_name

    return render_template_string("""
        <h2>Auction for Listing #{{ listing_id }}</h2>
        {% if highest_bidder %}
        <p>Current highest bid: ${{ highest_bid }} by {{ highest_bidder }}</p>
