                'date': reminder_date,
                'text': reminder_text
            })

    with open('user_data.p', 'wb') as f:
        pickle.dump(all_users, f)

    return "Reminder added"

@app.route('/get_user_data', methods=['GET'])
def get_user_data():
    name = request.args.get('name')

    if not os.path.exists('user_data.p'):
        return jsonify({"error": "No users found"}), 404

    with open('user_data.p', 'rb') as f:
        all_users = pickle.load(f)

    for user in all_users:
        if user['name'] == name:
            user['current_week'] = int((datetime.now() - user['conception_date']).days / 7)
            return jsonify(user)

    return jsonify({"error": "User not found"}), 404

def generate_milestones(conception_date):
    milestones = [
        {'week': 4, 'description': 'Heart begins to beat'},
        {'week': 8, 'description': 'All essential organs have begun to form'},
        {'week': 12, 'description': 'First trimester complete'},
        {'week': 16, 'description': 'Gender can be determined'},
        {'week': 20, 'description': 'Halfway through pregnancy'},
        {'week': 24, 'description': 'Viability milestone'},
        {'week': 28, 'description': 'Second trimester complete'},
        {'week': 37, 'description': 'Pregnancy is full term'},
        {'week': 40, 'description': 'Due date'}
    ]

    for milestone in milestones:
        milestone['date'] = conception_date + timedelta(days=milestone['week']*7)

    return milestones

