import requests
from bs4 import BeautifulSoup
import argparse

def fetch_html(url):
    try:
        headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.124 Safari/537.36'}
        response = requests.get(url, headers=headers, timeout=10)
        response.raise_for_status()
        return response.text
    except requests.exceptions.RequestException as e:
        print(f"Error fetching URL: {e}")
        return None

def parse_html(html):
    if not html:
        return None

    soup = BeautifulSoup(html, 'html.parser')
    return soup

def extract_data(soup):
    if not soup:
        return {}

    data = {
        'title': soup.title.text if soup.title else '',
        'links': [{'text': link.text.strip(), 'href': link.get('href')} for link in soup.find_all('a') if link.get('href')],
        'paragraphs': [p.text.strip() for p in soup.find_all('p') if p.text.strip()],
        'headings': [h.text.strip() for h in soup.find_all(['h1', 'h2', 'h3', 'h4', 'h5', 'h6']) if h.text.strip()]
    }
    return data

def scrape_url(url):
    html = fetch_html(url)
    soup = parse_html(html)
    data = extract_data(soup)
    return data

def main():
    parser = argparse.ArgumentParser(description='Web scraper for fetching and parsing HTML from URLs')
    parser.add_argument('--url', type=str, help='URL to scrape')
    parser.add_argument('--urls', type=str, help='File containing URLs to scrape, one per line')
    args = parser.parse_args()

    urls = []
    if args.url:
        urls.append(args.url)
    elif args.urls:
        try:
            with open(args.urls, 'r') as f:
                urls = [line.strip() for line in f if line.strip()]
        except Exception as e:
            print(f"Error reading URLs file: {e}")
    else:
        print("Please provide either --url or --urls argument")
        return

    for url in urls:
        print(f"Scraping: {url}")
        data = scrape_url(url)
        print(f"Title: {data.get('title', '')}")
        print(f"Found {len(data.get('links', []))} links")
        print(f"Found {len(data.get('paragraphs', []))} paragraphs")
        print(f"Found {len(data.get('headings', []))} headings")
        print("-" * 50)

if __name__ == "__main__":
    main()
