import os
import shutil
import hashlib
import time
from collections import defaultdict

def find_duplicate_files(path):
    files = {}
    for root, dirs, filenames in os.walk(path):
        for filename in filenames:
            filepath = os.path.join(root, filename)
            with open(filepath, 'rb') as f:
                checksum = hashlib.md5(f.read()).hexdigest()
            if checksum in files:
                files[checksum].append(filepath)
            else:
                files[checksum] = [filepath]
    return files

def delete_duplicates(files):
    for checksum, flist in files.items():
        if len(flist) > 1:
            for f in flist[1:]:
                print(f'Deleting {f}')
                os.remove(f)

def find_large_files(path, size_limit_mb=100):
    large_files = []
    size_limit = size_limit_mb * 1024 * 1024
    for root, dirs, filenames in os.walk(path):
        for filename in filenames:
            filepath = os.path.join(root, filename)
            try:
                file_size = os.path.getsize(filepath)
                if file_size > size_limit:
                    large_files.append((filepath, file_size))
            except (OSError, FileNotFoundError):
                continue
    return sorted(large_files, key=lambda x: x[1], reverse=True)

def find_old_files(path, days=90):
    old_files = []
    cutoff = time.time() - (days * 86400)
    for root, dirs, filenames in os.walk(path):
        for filename in filenames:
            filepath = os.path.join(root, filename)
            try:
                last_access = os.path.getatime(filepath)
                if last_access < cutoff:
                    old_files.append((filepath, last_access))
            except (OSError, FileNotFoundError):
                continue
    return old_files

def analyze_directory_sizes(path):
    dir_sizes = defaultdict(int)
    for root, dirs, filenames in os.walk(path):
        for filename in filenames:
            filepath = os.path.join(root, filename)
            try:
                size = os.path.getsize(filepath)
                dir_sizes[root] += size
            except (OSError, FileNotFoundError):
                continue
    return sorted(dir_sizes.items(), key=lambda x: x[1], reverse=True)

def format_size(size_bytes):
    for unit in ['B', 'KB', 'MB', 'GB', 'TB']:
        if size_bytes < 1024.0:
            return f"{size_bytes:.2f} {unit}"
        size_bytes /= 1024.0
    return f"{size_bytes:.2f} PB"

def organize_files_by_type(path, target_dir):
    extensions = defaultdict(list)
    for root, dirs, filenames in os.walk(path):
        for filename in filenames:
            filepath = os.path.join(root, filename)
            ext = os.path.splitext(filename)[1].lower()
            if ext:
                extensions[ext[1:]].append(filepath)
            else:
                extensions['no_extension'].append(filepath)

    for ext, files in extensions.items():
        ext_dir = os.path.join(target_dir, ext)
        os.makedirs(ext_dir, exist_ok=True)
        for file in files:
            dest = os.path.join(ext_dir, os.path.basename(file))
            try:
                shutil.copy2(file, dest)
                print(f"Copied {file} to {dest}")
            except (shutil.Error, OSError) as e:
                print(f"Error copying {file}: {str(e)}")

if __name__ == '__main__':
    print("Disk Usage Analyzer and Cleaner")
    print("1. Find and delete duplicate files")
    print("2. Find large files")
    print("3. Find old files")
    print("4. Analyze directory sizes")
    print("5. Organize files by type")

    choice = input("Enter your choice (1-5): ")
