        dup_count = sum(len(flist) - 1 for flist in files.values() if len(flist) > 1)
        print(f"Found {dup_count} duplicate files")
        if dup_count > 0:
            confirm = input("Delete all duplicates? (y/n): ")
            if confirm.lower() == 'y':
                delete_duplicates(files)
    elif choice == '2':
        size_limit = int(input("Enter minimum size in MB: "))
        large_files = find_large_files(path, size_limit)
        print(f"Found {len(large_files)} files larger than {size_limit} MB")
        for file, size in large_files[:20]:
            print(f"{file}: {format_size(size)}")
    elif choice == '3':
        days = int(input("Enter minimum age in days: "))
        old_files = find_old_files(path, days)
        print(f"Found {len(old_files)} files not accessed in {days} days")
        for file, timestamp in old_files[:20]:
            print(f"{file}: last accessed {time.strftime('%Y-%m-%d', time.localtime(timestamp))}")
    elif choice == '4':
        dir_sizes = analyze_directory_sizes(path)
        print("Top directories by size:")
        for directory, size in dir_sizes[:20]:
            print(f"{directory}: {format_size(size)}")
    elif choice == '5':
        target_dir = input("Enter target directory for organized files: ")
        organize_files_by_type(path, target_dir)
