import datetime
import json
import os

class HabitTracker:
    def __init__(self, filename="habits.json"):
        self.filename = filename
        self.habits = {}
        self.load_data()

    def load_data(self):
        if os.path.exists(self.filename):
            with open(self.filename, 'r') as f:
                self.habits = json.load(f)
        else:
            self.habits = {"habits": {}}
            self.save_data()

    def save_data(self):
        with open(self.filename, 'w') as f:
            json.dump(self.habits, f, indent=4)

    def add_habit(self, name, goal, frequency="daily", target=1):
        if name in self.habits["habits"]:
            return False

        self.habits["habits"][name] = {
            "goal": goal,
            "frequency": frequency,
            "target": target,
            "created_at": datetime.datetime.now().strftime("%Y-%m-%d"),
            "completions": {}
        }
        self.save_data()
        return True

    def remove_habit(self, name):
        if name in self.habits["habits"]:
            del self.habits["habits"][name]
            self.save_data()
            return True
        return False

    def complete_habit(self, name, date=None, count=1):
        if date is None:
            date = datetime.datetime.now().strftime("%Y-%m-%d")

        if name not in self.habits["habits"]:
            return False

        completions = self.habits["habits"][name]["completions"]
        if date in completions:
            completions[date] += count
        else:
            completions[date] = count

        self.save_data()
        return True

    def get_habits(self):
        return list(self.habits["habits"].keys())

    def get_habit_details(self, name):
        if name in self.habits["habits"]:
            return self.habits["habits"][name]
        return None

    def get_stats(self, name, days=30):
        if name not in self.habits["habits"]:
            return None

        habit = self.habits["habits"][name]
        today = datetime.datetime.now()
        stats = {"total_completions": 0, "streak": 0, "best_streak": 0, "days_completed": 0}

        for i in range(days):
            date = (today - datetime.timedelta(days=i)).strftime("%Y-%m-%d")
            if date in habit["completions"] and habit["completions"][date] >= habit["target"]:
                stats["total_completions"] += habit["completions"][date]
                stats["days_completed"] += 1
                stats["streak"] += 1
                stats["best_streak"] = max(stats["best_streak"], stats["streak"])
            else:
                stats["streak"] = 0

        return stats

def main():
