import os
import argparse
import re
import stat

def rename_files(path, pattern=None, replacement=None, recursive=False, permissions=None):
    file_count = 0

    def process_dir(directory):
        nonlocal file_count
        items = os.listdir(directory)

        for item in items:
            item_path = os.path.join(directory, item)

            if os.path.isdir(item_path) and recursive:
                process_dir(item_path)
            elif os.path.isfile(item_path):
                if pattern is not None and replacement is not None:
                    new_name = re.sub(pattern, replacement, item)
                else:
                    parts = item.split('.')
                    if len(parts) > 1:
                        new_name = '_'.join(parts[:-1]) + '.' + parts[-1]
                    else:
                        new_name = item

                if new_name != item:
                    new_path = os.path.join(directory, new_name)
                    os.rename(item_path, new_path)

                    if permissions is not None:
                        os.chmod(new_path, permissions)

                    file_count += 1

    process_dir(path)
    return file_count

def parse_permissions(perm_str):
    if perm_str.isdigit() and len(perm_str) <= 4:
        return int(perm_str, 8)

    mode = 0
    if 'r' in perm_str: mode |= stat.S_IRUSR
    if 'w' in perm_str: mode |= stat.S_IWUSR
    if 'x' in perm_str: mode |= stat.S_IXUSR

    return mode

def main():
    parser = argparse.ArgumentParser(description='Bulk rename files based on patterns')
    parser.add_argument('path', help='Directory path containing files to rename')
    parser.add_argument('-p', '--pattern', help='Regex pattern to match in filenames')
    parser.add_argument('-r', '--replacement', help='Replacement string for matched pattern')
    parser.add_argument('-R', '--recursive', action='store_true', help='Process directories recursively')
    parser.add_argument('-m', '--mode', help='Permissions for renamed files (octal or rwx format)')

    args = parser.parse_args()

    permissions = None
    if args.mode:
        permissions = parse_permissions(args.mode)

    count = rename_files(args.path, args.pattern, args.replacement, args.recursive, permissions)
    print(f"Renamed {count} files")

if __name__ == "__main__":
    main()
