import os

app = Flask(__name__)

QUESTS_FILE = 'player_quests.yaml'

def load_quests():
    if os.path.exists(QUESTS_FILE):
        with open(QUESTS_FILE, 'r') as file:
            return yaml.safe_load(file) or {}
    return {}

def save_quests(quests_data):
    with open(QUESTS_FILE, 'w') as file:
        yaml.dump(quests_data, file)

@app.route('/quests', methods=['POST'])
def update_quests():
    data = request.get_json()

    if not data or 'player_id' not in data:
        return jsonify({'error': 'Missing player_id'}), 400

    player_id = data['player_id']
    quests_data = load_quests()

    if player_id not in quests_data:
        quests_data[player_id] = {'quests': {}}

    if 'completed_quest' in data:
        quest_id = data['completed_quest']
        quests_data[player_id]['quests'][quest_id] = {'status': 'completed'}

    if 'started_quest' in data:
        quest_id = data['started_quest']
        quests_data[player_id]['quests'][quest_id] = {'status': 'in_progress'}

    if 'quest_progress' in data:
        for quest_id, progress in data['quest_progress'].items():
            if quest_id not in quests_data[player_id]['quests']:
                quests_data[player_id]['quests'][quest_id] = {'status': 'in_progress'}
            quests_data[player_id]['quests'][quest_id]['progress'] = progress

    save_quests(quests_data)
    return jsonify({'status': 'ok'})

@app.route('/quests/<player_id>', methods=['GET'])
