import os
import time
import psutil
import traceback
from datetime import datetime

class Logger:
    def __init__(self, filename):
        self.filename = filename
        os.makedirs(os.path.dirname(filename), exist_ok=True)
        self.file = open(filename, 'a')

    def log(self, msg):
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        self.file.write(f"[{timestamp}] {msg}\n")
        self.file.flush()

    def close(self):
        self.file.close()

class PerformanceMonitor:
    def __init__(self, log_file='/var/log/perfmon.log', interval=60):
        self.logger = Logger(log_file)
        self.interval = interval
        self.running = False

    def start(self):
        self.running = True
        self.logger.log("Performance monitoring started")

        try:
            while self.running:
                self._collect_metrics()
                time.sleep(self.interval)
        except Exception as e:
            self.logger.log(f"Error in monitoring: {str(e)}")
            self.logger.log(traceback.format_exc())
        finally:
            self.logger.close()

    def stop(self):
        self.running = False
        self.logger.log("Performance monitoring stopped")

    def _collect_metrics(self):
        cpu = psutil.cpu_percent(interval=1)
        memory = psutil.virtual_memory()
        disk = psutil.disk_usage('/')

        metrics = {
            "cpu_percent": cpu,
            "memory_percent": memory.percent,
            "memory_used_gb": round(memory.used / (1024**3), 2),
            "disk_percent": disk.percent,
            "disk_free_gb": round(disk.free / (1024**3), 2)
        }

        self.logger.log(f"METRICS: {metrics}")

        if cpu > 90:
            self.logger.log(f"ALERT: High CPU usage: {cpu}%")
        if memory.percent > 90:
            self.logger.log(f"ALERT: High memory usage: {memory.percent}%")
        if disk.percent > 90:
            self.logger.log(f"ALERT: Disk space critical: {disk.percent}%")

logger = Logger('/var/log/app.log')
logger.log('Starting up...')
logger.close()

if __name__ == "__main__":
    monitor = PerformanceMonitor()
    try:
        monitor.start()
    except KeyboardInterrupt:
        monitor.stop()
