// Song model
class Song {
  constructor(id, title, artist, album, duration, imageUrl) {
    this.id = id;
    this.title = title;
    this.artist = artist;
    this.album = album;
    this.duration = duration;
    this.imageUrl = imageUrl;
    this.lyrics = null;
  }

  setLyrics(lyrics) {
    this.lyrics = lyrics;
  }

  formatDuration() {
    const minutes = Math.floor(this.duration / 60);
    const seconds = this.duration % 60;
    return `${minutes}:${seconds < 10 ? '0' + seconds : seconds}`;
  }
}

// Music player
class MusicPlayer {
  constructor() {
    this.currentSong = null;
    this.playlist = [];
    this.isPlaying = false;
    this.audio = new Audio();
    this.setupEventListeners();
  }

  setupEventListeners() {
    this.audio.addEventListener('ended', () => this.playNext());
  }

  playSong(song) {
    this.currentSong = song;
    this.audio.src = `https://api.music-stream.com/tracks/${song.id}`;
    this.audio.play();
    this.isPlaying = true;
  }

  pause() {
    this.audio.pause();
    this.isPlaying = false;
  }

  resume() {
    this.audio.play();
    this.isPlaying = true;
  }

  playNext() {
    const currentIndex = this.playlist.findIndex(song => song.id === this.currentSong.id);
    if (currentIndex < this.playlist.length - 1) {
      this.playSong(this.playlist[currentIndex + 1]);
    }
  }

  playPrevious() {
    const currentIndex = this.playlist.findIndex(song => song.id === this.currentSong.id);
    if (currentIndex > 0) {
      this.playSong(this.playlist[currentIndex - 1]);
    }
  }

  addToPlaylist(song) {
    this.playlist.push(song);
  }

  clearPlaylist() {
    this.playlist = [];
  }
}

// API service
class MusicApiService {
  constructor(apiKey) {
    this.apiKey = apiKey;
    this.baseUrl = 'https://api.music-stream.com';
  }

  async searchSongs(query) {
    const response = await fetch(`${this.baseUrl}/search?q=${query}&key=${this.apiKey}`);
    const data = await response.json();

    return data.tracks.map(track => new Song(
      track.id,
      track.title,
      track.artist,
      track.album,
      track.duration,
      track.image_url
    ));
  }

  async getSongLyrics(songId) {
    const response = await fetch(`${this.baseUrl}/lyrics/${songId}?key=${this.apiKey}`);
    const data = await response.json();
    return data.lyrics;
  }

  async getArtistInfo(artistId) {
    const response = await fetch(`${this.baseUrl}/artists/${artistId}?key=${this.apiKey}`);
    return await response.json();
  }
}

// User interface handler
class MusicApp {
  constructor() {
    this.player = new MusicPlayer();
    this.api = new MusicApiService('YOUR_API_KEY');
    this.init();
  }

  init() {
    document.getElementById('search-button').addEventListener('click', () => this.handleSearch());
    document.getElementById('play-button').addEventListener('click', () => this.togglePlay());
    document.getElementById('next-button').addEventListener('click', () => this.player.playNext());
    document.getElementById('prev-button').addEventListener('click', () => this.player.playPrevious());
  }

  async handleSearch() {
    const query = document.getElementById('search-input').value;
    if (!query) return;

    const songs = await this.api.searchSongs(query);
    this.displaySearchResults(songs);
  }

  displaySearchResults(songs) {
    const resultsContainer = document.getElementById('search-results');
    resultsContainer.innerHTML = '';

    songs.forEach(song => {
      const songElement = document.createElement('div');
      songElement.className = 'song-item';
      songElement.innerHTML = `
        <img src="${song.imageUrl}" alt="${song.title}">
        <div class="song-info">
          <h3>${song.title}</h3>
          <p>${song.artist}</p>
          <p>${song.formatDuration()}</p>
        </div>
      `;

      songElement.addEventListener('click', () => this.handleSongSelect(song));
      resultsContainer.appendChild(songElement);
    });
  }

  async handleSongSelect(song) {
    const lyrics = await this.api.getSongLyrics(song.id);
    song.setLyrics(lyrics);

    this.player.addToPlaylist(song);
    this.player.playSong(song);
    this.updateNowPlaying();
    this.displayLyrics(lyrics);
  }

  togglePlay() {
    if (!this.player.currentSong) return;

    if (this.player.isPlaying) {
      this.player.pause();
    } else {
      this.player.resume();
    }

    this.updatePlayButton();
  }

  updatePlayButton() {
    const playButton = document.getElementById('play-button');
    playButton.textContent = this.player.isPlaying ? 'Pause' : 'Play';
  }

  updateNowPlaying() {
    const song = this.player.currentSong;
    if (!song) return;

    document.getElementById('now-playing-title').textContent = song.title;
    document.getElementById('now-playing-artist').textContent = song.artist;
    document.getElementById('now-playing-image').src = song.imageUrl;
    this.updatePlayButton();
  }

  displayLyrics(lyrics) {
    const lyricsContainer = document.getElementById('lyrics-container');
    lyricsContainer.textContent = lyrics || 'Lyrics not available';
  }
}

// Initialize the app
const app = new MusicApp();
