import os
import sys
import argparse
from collections import defaultdict

def parse_file(file_path):
    with open(file_path, 'r', encoding='utf-8', errors='replace') as f:
        lines = f.readlines()

    comments = []
    code_lines = 0
    in_multi_comment = False

    for line in lines:
        line = line.strip()

        if not line:
            continue

        if in_multi_comment:
            comments.append(line)
            if "*/" in line:
                in_multi_comment = False
            continue

        if line.startswith("//"):
            comments.append(line)
        elif line.startswith("/*"):
            comments.append(line)
            if "*/" not in line:
                in_multi_comment = True
        elif line.startswith("#"):  # For Python, shell scripts
            comments.append(line)
        else:
            # Check for inline comments
            if "//" in line:
                comments.append(line[line.index("//"):])
                code_lines += 1
            elif "#" in line:
                comments.append(line[line.index("#"):])
                code_lines += 1
            else:
                code_lines += 1

    return comments, code_lines

def get_metrics(path):
    all_comments = []
    total_code_lines = 0
    metrics = {}

    if os.path.isfile(path):
        comments, code_lines = parse_file(path)
        all_comments.extend(comments)
        total_code_lines += code_lines
    else:
        for root, _, files in os.walk(path):
            for file in files:
                if file.endswith(('.py', '.js', '.java', '.c', '.cpp', '.h', '.cs', '.php')):
                    file_path = os.path.join(root, file)
                    try:
                        comments, code_lines = parse_file(file_path)
                        all_comments.extend(comments)
                        total_code_lines += code_lines
                    except Exception as e:
                        print(f"Error processing {file_path}: {e}", file=sys.stderr)

    comment_lines = len(all_comments)
    total_lines = comment_lines + total_code_lines

    if total_lines > 0:
        comment_density = (comment_lines / total_lines) * 100
    else:
        comment_density = 0

    metrics["total_lines"] = total_lines
    metrics["code_lines"] = total_code_lines
    metrics["comment_lines"] = comment_lines
    metrics["comment_density"] = f"{comment_density:.2f}%"

    return metrics

def format_report(metrics):
    report = []
    report.append("CODE COMMENT ANALYSIS REPORT")
    report.append("=" * 30)
    report.append(f"Total lines: {metrics['total_lines']}")
    report.append(f"Code lines: {metrics['code_lines']}")
    report.append(f"Comment lines: {metrics['comment_lines']}")
    report.append(f"Comment density: {metrics['comment_density']}")

    return "\n".join(report)

def analyze_comments(path):
    metrics = get_metrics(path)
    report = format_report(metrics)

    if args.output:
        output_file = args.output
        mode = 0o644  # Default: owner can read/write, others can read

        if args.permissions:
            try:
                mode = int(args.permissions, 8)
            except ValueError:
                print(f"Invalid permissions: {args.permissions}", file=sys.stderr)

        with open(output_file, 'w') as f:
            f.write(report)

        os.chmod(output_file, mode)
    else:
        print(report)

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description='Analyze code comments and calculate metrics')
    parser.add_argument('path', help='Path to file or directory to analyze')
    parser.add_argument('-o', '--output', help='Output file path')
    parser.add_argument('-p', '--permissions', help='File permissions (octal, e.g. 644)')
    args = parser.parse_args()

    analyze_comments(args.path)
```

