import tarfile
import os
import requests
import subprocess
import time

def clone_repo(repo_url, target_dir=None):
    if target_dir:
        os.makedirs(target_dir, exist_ok=True)
        os.chdir(target_dir)

    subprocess.run(["git", "clone", repo_url])

def extract_repo(repo_archive):
    tar = tarfile.open(repo_archive)
    tar.extractall()
    tar.close()

    os.chdir(os.path.basename(repo_archive.replace(".tar.gz", "")))

def sync_repo(repo_url, local_path=None):
    if local_path:
        if not os.path.exists(local_path):
            clone_repo(repo_url, os.path.dirname(local_path))
        else:
            os.chdir(local_path)
            subprocess.run(["git", "pull"])
    else:
        repo_name = repo_url.split("/")[-1].replace(".git", "")
        if os.path.exists(repo_name):
            os.chdir(repo_name)
            subprocess.run(["git", "pull"])
        else:
            clone_repo(repo_url)

def schedule_sync(repo_url, local_path=None, interval_hours=24):
    while True:
        sync_repo(repo_url, local_path)
        time.sleep(interval_hours * 3600)

if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="Sync files from a remote git repository")
    parser.add_argument("repo_url", help="URL of the git repository")
    parser.add_argument("--local-path", help="Local path to sync to")
    parser.add_argument("--schedule", type=float, help="Schedule sync every X hours")
    parser.add_argument("--archive", help="Extract from tar.gz archive instead of git")

    args = parser.parse_args()

    if args.archive:
        extract_repo(args.archive)
    elif args.schedule:
        schedule_sync(args.repo_url, args.local_path, args.schedule)
    else:
        sync_repo(args.repo_url, args.local_path)
