import os
import time

app = Flask(__name__)

TRANSACTIONS_FILE = "transactions.yaml"

@app.route("/get_latest_transactions", methods=["POST"])
def get_latest_transactions():
    try:
        limit = int(request.form.get('limit', 10))

        if os.path.exists(TRANSACTIONS_FILE):
            with open(TRANSACTIONS_FILE, 'r') as file:
                all_transactions = yaml.safe_load(file) or []
        else:
            all_transactions = []

        sorted_transactions = sorted(all_transactions, key=lambda x: x.get('timestamp', 0), reverse=True)
        transactions = sorted_transactions[:limit]

        return jsonify({"status": "success", "transactions": transactions})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 400

@app.route("/add_transaction", methods=["POST"])
def add_transaction():
    try:
        transaction_type = request.form.get('type')
        amount = float(request.form.get('amount'))
        category = request.form.get('category', '')
        description = request.form.get('description', '')

        if transaction_type not in ['income', 'expense']:
            return jsonify({"status": "error", "message": "Invalid transaction type"}), 400

        if amount <= 0:
            return jsonify({"status": "error", "message": "Amount must be positive"}), 400

        transaction = {
            "type": transaction_type,
            "amount": amount,
            "category": category,
            "description": description,
            "timestamp": int(time.time())
        }

        if os.path.exists(TRANSACTIONS_FILE):
            with open(TRANSACTIONS_FILE, 'r') as file:
                transactions = yaml.safe_load(file) or []
        else:
            transactions = []

        transactions.append(transaction)

        with open(TRANSACTIONS_FILE, 'w') as file:
            yaml.dump(transactions, file)

        return jsonify({"status": "success", "transaction": transaction})
    except Exception as e:
        return jsonify({"status": "error", "message": str(e)}), 400

if __name__ == "__main__":
    app.run(debug=True)
