from collections import defaultdict

class TrieNode:
    def __init__(self):
        self.children = defaultdict(TrieNode)
        self.is_end = False
        self.suggestions = []

class Autocomplete:
    def __init__(self, max_suggestions=5):
        self.root = TrieNode()
        self.max_suggestions = max_suggestions

    def insert(self, word):
        node = self.root
        for char in word:
            node = node.children[char]
        node.is_end = True

    def build_suggestions(self):
        self._dfs_build_suggestions(self.root, "")

    def _dfs_build_suggestions(self, node, prefix):
        if node.is_end:
            node.suggestions.append(prefix)

        for char, child_node in sorted(node.children.items()):
            self._dfs_build_suggestions(child_node, prefix + char)
            node.suggestions.extend(child_node.suggestions[:self.max_suggestions - len(node.suggestions)])
            node.suggestions = node.suggestions[:self.max_suggestions]

    def get_suggestions(self, prefix):
        node = self.root
        for char in prefix:
            if char not in node.children:
                return []
            node = node.children[char]
        return node.suggestions

def demo():
    words = ["apple", "application", "apply", "apartment", "book", "banana", "ball", "cat", "catastrophe"]

    autocomplete = Autocomplete()
    for word in words:
        autocomplete.insert(word)

    autocomplete.build_suggestions()

    while True:
        query = input("Enter search query (or 'q' to quit): ")
        if query.lower() == 'q':
            break
        suggestions = autocomplete.get_suggestions(query)
        print(f"Suggestions for '{query}':")
        for suggestion in suggestions:
            print(f"  - {suggestion}")

if __name__ == "__main__":
    demo()
