from flask import Flask, render_template, request, redirect, url_for, flash
from flask_sqlalchemy import SQLAlchemy
from flask_login import LoginManager, UserMixin, login_user, login_required, logout_user, current_user
from werkzeug.security import generate_password_hash, check_password_hash
from datetime import datetime

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///therapy.db'
db = SQLAlchemy(app)
login_manager = LoginManager(app)
login_manager.login_view = 'login'

class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(100), nullable=False)
    email = db.Column(db.String(100), unique=True, nullable=False)
    password = db.Column(db.String(200), nullable=False)
    is_therapist = db.Column(db.Boolean, default=False)
    exercises = db.relationship('Exercise', backref='author', lazy=True)

class Exercise(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(100), nullable=False)
    description = db.Column(db.Text, nullable=False)
    created_at = db.Column(db.DateTime, default=datetime.utcnow)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    steps = db.relationship('Step', backref='exercise', lazy=True, cascade="all, delete-orphan")

class Step(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    order = db.Column(db.Integer, nullable=False)
    content = db.Column(db.Text, nullable=False)
    exercise_id = db.Column(db.Integer, db.ForeignKey('exercise.id'), nullable=False)

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@app.route('/')
def index():
    exercises = Exercise.query.order_by(Exercise.created_at.desc()).all()
    return render_template('index.html', exercises=exercises)

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        name = request.form.get('name')
        email = request.form.get('email')
        password = request.form.get('password')
        is_therapist = True if request.form.get('is_therapist') else False

        user = User.query.filter_by(email=email).first()
        if user:
            flash('Email already exists.')
            return redirect(url_for('register'))

        hashed_password = generate_password_hash(password, method='pbkdf2:sha256')
        new_user = User(name=name, email=email, password=hashed_password, is_therapist=is_therapist)

        db.session.add(new_user)
        db.session.commit()

        return redirect(url_for('login'))

    return render_template('register.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        email = request.form.get('email')
        password = request.form.get('password')

        user = User.query.filter_by(email=email).first()

        if not user or not check_password_hash(user.password, password):
            flash('Please check your login details and try again.')
            return redirect(url_for('login'))

        login_user(user)
        return redirect(url_for('index'))

    return render_template('login.html')

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('index'))

@app.route('/exercise/new', methods=['GET', 'POST'])
@login_required
def new_exercise():
    if not current_user.is_therapist:
        flash('Only therapists can create exercises.')
        return redirect(url_for('index'))

    if request.method == 'POST':
        title = request.form.get('title')
        description = request.form.get('description')

        new_exercise = Exercise(title=title, description=description, author=current_user)
        db.session.add(new_exercise)
        db.session.commit()

        steps_content = request.form.getlist('step')
        for i, content in enumerate(steps_content, 1):
            if content.strip():
                step = Step(order=i, content=content, exercise=new_exercise)
                db.session.add(step)

        db.session.commit()
        flash('Exercise created successfully!')
        return redirect(url_for('index'))

    return render_template('new_exercise.html')

@app.route('/exercise/<int:id>')
def view_exercise(id):
    exercise = Exercise.query.get_or_404(id)
    steps = Step.query.filter_by(exercise_id=id).order_by(Step.order).all()
    return render_template('view_exercise.html', exercise=exercise, steps=steps)

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(debug=True)
