from datetime import datetime, timedelta
from typing import Dict, List, Optional

class User:
    def __init__(self, user_id: str, name: str, email: str):
        self.user_id = user_id
        self.name = name
        self.email = email
        self.balance = 0.0

    def add_funds(self, amount: float) -> bool:
        if amount <= 0:
            return False
        self.balance += amount
        return True

    def withdraw_funds(self, amount: float) -> bool:
        if amount <= 0 or amount > self.balance:
            return False
        self.balance -= amount
        return True

class Project:
    def __init__(self, project_id: str, title: str, description: str, 
                creator_id: str, funding_goal: float, deadline: datetime):
        self.project_id = project_id
        self.title = title
        self.description = description
        self.creator_id = creator_id
        self.funding_goal = funding_goal
        self.deadline = deadline
        self.current_funding = 0.0
        self.backers: Dict[str, float] = {}
        self.is_active = True

    def add_backer(self, user_id: str, amount: float) -> bool:
        if not self.is_active or datetime.now() > self.deadline or amount <= 0:
            return False

        if user_id in self.backers:
            self.backers[user_id] += amount
        else:
            self.backers[user_id] = amount

        self.current_funding += amount

        if self.current_funding >= self.funding_goal:
            self.mark_as_funded()

        return True

    def mark_as_funded(self) -> None:
        self.is_active = False

    def cancel_project(self) -> bool:
        if self.current_funding > 0:
            return False
        self.is_active = False
        return True

    def is_funded(self) -> bool:
        return self.current_funding >= self.funding_goal

    def time_remaining(self) -> Optional[timedelta]:
        if not self.is_active:
            return None
        remaining = self.deadline - datetime.now()
        return remaining if remaining.total_seconds() > 0 else timedelta(0)

class CrowdfundingPlatform:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.projects: Dict[str, Project] = {}
        self.next_user_id = 1
        self.next_project_id = 1

    def register_user(self, name: str, email: str) -> str:
        user_id = f"U{self.next_user_id}"
        self.next_user_id += 1
        self.users[user_id] = User(user_id, name, email)
        return user_id

    def create_project(self, title: str, description: str, creator_id: str, 
                      funding_goal: float, days_to_deadline: int) -> Optional[str]:
        if creator_id not in self.users:
            return None

        if funding_goal <= 0 or days_to_deadline <= 0:
            return None

        deadline = datetime.now() + timedelta(days=days_to_deadline)
        project_id = f"P{self.next_project_id}"
        self.next_project_id += 1

        self.projects[project_id] = Project(
            project_id, title, description, creator_id, 
            funding_goal, deadline
        )

        return project_id

    def back_project(self, user_id: str, project_id: str, amount: float) -> bool:
        if user_id not in self.users or project_id not in self.projects:
            return False

        user = self.users[user_id]
        project = self.projects[project_id]

        if user_id == project.creator_id:
            return False

        if not user.withdraw_funds(amount):
            return False

        if not project.add_backer(user_id, amount):
            user.add_funds(amount)
            return False

        return True

    def get_user_backed_projects(self, user_id: str) -> List[str]:
        if user_id not in self.users:
            return []

        return [p.project_id for p in self.projects.values() if user_id in p.backers]

    def get_user_created_projects(self, user_id: str) -> List[str]:
        if user_id not in self.users:
            return []

        return [p.project_id for p in self.projects.values() if p.creator_id == user_id]
