        if not os.path.exists(sample_path) or not os.path.isfile(sample_path):
            return Response(status=status.HTTP_404_NOT_FOUND)
        if not os.path.abspath(sample_path).startswith(os.path.abspath(SAMPLES_DIR)):
            return Response(status=status.HTTP_403_FORBIDDEN)
        return FileResponse(open(sample_path, 'rb'), content_type='application/octet-stream')

    def post(self, request, format=None):
        if 'sample' not in request.data:
            return Response(status=status.HTTP_400_BAD_REQUEST)

        sample = request.data['sample']
        filename = sample.name

        if not os.path.exists(SAMPLES_DIR):
            os.makedirs(SAMPLES_DIR)

        file_path = os.path.join(SAMPLES_DIR, filename)
        with open(file_path, 'wb+') as f:
            for chunk in sample.chunks():
                f.write(chunk)

        if filename.endswith('.zip') or filename.endswith('.tar.gz'):
            refresh_samples(file_path)

        return Response(status=status.HTTP_201_CREATED)

def refresh_samples(archive_path):
    temp_dir = os.path.join(SAMPLES_DIR, 'temp_extract')

    if os.path.exists(temp_dir):
        shutil.rmtree(temp_dir)
    os.makedirs(temp_dir)

    if archive_path.endswith('.tar.gz'):
        with tarfile.open(archive_path, 'r:gz') as tar:
            members = [m for m in tar.getmembers() if m.isfile() and not m.name.startswith('/') and '..' not in m.name]
            tar.extractall(path=temp_dir, members=members)
    elif archive_path.endswith('.zip'):
        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            for zip_info in zip_ref.infolist():
                if not zip_info.is_dir() and not zip_info.filename.startswith('/') and '..' not in zip_info.filename:
                    zip_ref.extract(zip_info, path=temp_dir)

    for f in os.listdir(SAMPLES_DIR):
        file_path = os.path.join(SAMPLES_DIR, f)
        if os.path.isfile(file_path) and f.endswith('.wav') and not f.startswith('new_samples'):
            os.remove(file_path)

