// App.js
import React, { useState, useEffect } from 'react';
import { View, Text, TextInput, Button, ScrollView, StyleSheet, Alert } from 'react-native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import DateTimePicker from '@react-native-community/datetimepicker';
import uuid from 'react-native-uuid';

export default function App() {
  const [bills, setBills] = useState([]);
  const [newBill, setNewBill] = useState({
    id: '',
    name: '',
    amount: '',
    dueDate: new Date(),
    accountNumber: '',
    isPaid: false
  });
  const [showDatePicker, setShowDatePicker] = useState(false);

  useEffect(() => {
    loadBills();
  }, []);

  const loadBills = async () => {
    try {
      const storedBills = await AsyncStorage.getItem('bills');
      if (storedBills) {
        setBills(JSON.parse(storedBills));
      }
    } catch (error) {
      Alert.alert('Error', 'Failed to load bills');
    }
  };

  const saveBills = async (updatedBills) => {
    try {
      await AsyncStorage.setItem('bills', JSON.stringify(updatedBills));
    } catch (error) {
      Alert.alert('Error', 'Failed to save bills');
    }
  };

  const addBill = () => {
    if (!newBill.name || !newBill.amount || !newBill.accountNumber) {
      Alert.alert('Error', 'Please fill all required fields');
      return;
    }

    const billWithId = {
      ...newBill,
      id: uuid.v4(),
      amount: parseFloat(newBill.amount)
    };

    const updatedBills = [...bills, billWithId];
    setBills(updatedBills);
    saveBills(updatedBills);

    setNewBill({
      id: '',
      name: '',
      amount: '',
      dueDate: new Date(),
      accountNumber: '',
      isPaid: false
    });
  };

  const togglePaid = (id) => {
    const updatedBills = bills.map(bill => 
      bill.id === id ? { ...bill, isPaid: !bill.isPaid } : bill
    );
    setBills(updatedBills);
    saveBills(updatedBills);
  };

  const deleteBill = (id) => {
    const updatedBills = bills.filter(bill => bill.id !== id);
    setBills(updatedBills);
    saveBills(updatedBills);
  };

  const onDateChange = (event, selectedDate) => {
    setShowDatePicker(false);
    if (selectedDate) {
      setNewBill({ ...newBill, dueDate: selectedDate });
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.header}>Bill Payment Tracker</Text>

      <View style={styles.inputContainer}>
        <TextInput
          style={styles.input}
          placeholder="Bill Name"
          value={newBill.name}
          onChangeText={(text) => setNewBill({ ...newBill, name: text })}
        />

        <TextInput
          style={styles.input}
          placeholder="Amount"
          value={newBill.amount}
          onChangeText={(text) => setNewBill({ ...newBill, amount: text })}
          keyboardType="numeric"
        />

        <TextInput
          style={styles.input}
          placeholder="Account Number"
          value={newBill.accountNumber}
          onChangeText={(text) => setNewBill({ ...newBill, accountNumber: text })}
        />

        <Button title="Select Due Date" onPress={() => setShowDatePicker(true)} />
        {showDatePicker && (
          <DateTimePicker
            value={newBill.dueDate}
            mode="date"
            display="default"
            onChange={onDateChange}
          />
        )}

        <Text style={styles.dateText}>
          Due Date: {newBill.dueDate.toLocaleDateString()}
        </Text>

        <Button title="Add Bill" onPress={addBill} />
      </View>

      <ScrollView style={styles.billList}>
        {bills.map(bill => (
          <View key={bill.id} style={styles.billItem}>
            <View style={styles.billDetails}>
              <Text style={styles.billName}>{bill.name}</Text>
              <Text>Amount: ${bill.amount.toFixed(2)}</Text>
              <Text>Due: {new Date(bill.dueDate).toLocaleDateString()}</Text>
              <Text>Account: {bill.accountNumber}</Text>
              <Text>Status: {bill.isPaid ? 'Paid' : 'Unpaid'}</Text>
            </View>
            <View style={styles.billActions}>
              <Button
                title={bill.isPaid ? "Mark Unpaid" : "Mark Paid"}
                onPress={() => togglePaid(bill.id)}
              />
              <Button
                title="Delete"
                color="red"
                onPress={() => deleteBill(bill.id)}
              />
            </View>
          </View>
        ))}
      </ScrollView>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
