import datetime
import json
import os
from dataclasses import dataclass
from typing import List, Dict, Optional


@dataclass
class BirdSighting:
    species: str
    date: datetime.datetime
    location: tuple[float, float]  # (latitude, longitude)
    notes: Optional[str] = None


class BirdWatchingApp:
    def __init__(self, data_file="bird_sightings.json"):
        self.data_file = data_file
        self.sightings: List[Dict] = self._load_sightings()

    def _load_sightings(self) -> List[Dict]:
        if os.path.exists(self.data_file):
            try:
                with open(self.data_file, 'r') as f:
                    return json.load(f)
            except json.JSONDecodeError:
                return []
        return []

    def _save_sightings(self):
        with open(self.data_file, 'w') as f:
            json.dump(self.sightings, f, indent=2, default=str)

    def add_sighting(self, species: str, location: tuple[float, float], 
                     notes: Optional[str] = None) -> int:
        sighting = {
            "id": len(self.sightings) + 1,
            "species": species,
            "date": datetime.datetime.now(),
            "location": location,
            "notes": notes
        }
        self.sightings.append(sighting)
        self._save_sightings()
        return sighting["id"]

    def get_all_sightings(self) -> List[Dict]:
        return self.sightings

    def get_sighting_by_id(self, sighting_id: int) -> Optional[Dict]:
        for sighting in self.sightings:
            if sighting["id"] == sighting_id:
                return sighting
        return None

    def search_by_species(self, species: str) -> List[Dict]:
        return [s for s in self.sightings if s["species"].lower() == species.lower()]

    def search_by_location(self, lat: float, lon: float, radius_km: float = 1.0) -> List[Dict]:
        def distance(loc1, loc2):
            # Simple Euclidean distance - for a proper implementation,
            # use a geodesic distance calculation
            return ((loc1[0] - loc2[0]) ** 2 + (loc1[1] - loc2[1]) ** 2) ** 0.5

        return [s for s in self.sightings 
                if distance(s["location"], (lat, lon)) <= radius_km]

    def get_statistics(self) -> Dict:
        species_count = {}
        for sighting in self.sightings:
            species = sighting["species"]
            species_count[species] = species_count.get(species, 0) + 1

        return {
            "total_sightings": len(self.sightings),
            "unique_species": len(species_count),
            "species_counts": species_count
        }


# Example usage
if __name__ == "__main__":
    app = BirdWatchingApp()

    # Add some sightings
    app.add_sighting("Robin", (40.7128, -74.0060), "Beautiful red breast")
    app.add_sighting("Blue Jay", (40.7129, -74.0061), "Very loud call")
    app.add_sighting("Robin", (40.7130, -74.0062))

    # Get all sightings
    all_sightings = app.get_all_sightings()
    print(f"Total sightings: {len(all_sightings)}")

    # Search by species
    robins = app.search_by_species("Robin")
    print(f"Robin sightings: {len(robins)}")

    # Get statistics
    stats = app.get_statistics()
    print(f"Statistics: {stats}")
