import os

def update_product(filename, product_id, updates):
    temp_filename = filename + '.tmp'
    product_found = False

    if not os.path.exists(filename):
        with open(filename, 'w') as f:
            f.write(f'id:{product_id}\n')
            for key, value in updates.items():
                f.write(f'{key}:{value}\n')
        return

    with open(filename, 'r') as input_file, open(temp_filename, 'w') as output_file:
        current_id = None
        skip_line = False

        for line in input_file:
            line = line.strip()

            if line.startswith('id:'):
                current_id = line.split(':', 1)[1].strip()
                if current_id == str(product_id):
                    product_found = True
                    output_file.write(f'id:{product_id}\n')
                    for key, value in updates.items():
                        output_file.write(f'{key}:{value}\n')
                    skip_line = True
                else:
                    output_file.write(line + '\n')
                    skip_line = False
            elif skip_line and current_id == str(product_id):
                if not any(line.startswith(f'{key}:') for key in updates):
                    output_file.write(line + '\n')
            else:
                output_file.write(line + '\n')

    if not product_found:
        with open(temp_filename, 'a') as f:
            f.write(f'id:{product_id}\n')
            for key, value in updates.items():
                f.write(f'{key}:{value}\n')

    os.replace(temp_filename, filename)
