        try:
            data = yaml.safe_load(file) or {}
        except yaml.YAMLError:
            data = {}

        file.seek(0)
        file.truncate()

        if 'locations' not in data:
            data['locations'] = []

        data['locations'].append(location_data)
        yaml.dump(data, file, default_flow_style=False)

