import hashlib
import os
import datetime
import uuid

class User:
    def __init__(self, name, email, password):
        self.user_id = str(uuid.uuid4())
        self.name = name
        self.email = email
        self.password_hash = self._hash_password(password)
        self.accounts = []

    def _hash_password(self, password):
        salt = os.urandom(32)
        key = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
        return salt + key

    def verify_password(self, password):
        salt = self.password_hash[:32]
        stored_key = self.password_hash[32:]
        key = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt, 100000)
        return key == stored_key

    def add_account(self, account):
        self.accounts.append(account)

    def get_accounts(self):
        return self.accounts

class Account:
    def __init__(self, account_type, initial_balance=0):
        self.account_id = str(uuid.uuid4())
        self.account_type = account_type
        self.balance = initial_balance
        self.transactions = []

    def deposit(self, amount, description="Deposit"):
        if amount <= 0:
            raise ValueError("Amount must be positive")
        self.balance += amount
        transaction = Transaction(self.account_id, "deposit", amount, description)
        self.transactions.append(transaction)
        return transaction

    def withdraw(self, amount, description="Withdrawal"):
        if amount <= 0:
            raise ValueError("Amount must be positive")
        if amount > self.balance:
            raise ValueError("Insufficient funds")
        self.balance -= amount
        transaction = Transaction(self.account_id, "withdrawal", amount, description)
        self.transactions.append(transaction)
        return transaction

    def get_balance(self):
        return self.balance

    def get_transactions(self):
        return self.transactions

class Transaction:
    def __init__(self, account_id, transaction_type, amount, description):
        self.transaction_id = str(uuid.uuid4())
        self.account_id = account_id
        self.timestamp = datetime.datetime.now()
        self.transaction_type = transaction_type
        self.amount = amount
        self.description = description

class Bank:
    def __init__(self):
        self.users = {}
        self.accounts = {}

    def register_user(self, name, email, password):
        if email in self.users:
            raise ValueError("Email already registered")
        user = User(name, email, password)
        self.users[email] = user
        return user

    def authenticate_user(self, email, password):
        if email not in self.users:
            return None
        user = self.users[email]
        if user.verify_password(password):
            return user
        return None

    def create_account(self, user, account_type, initial_balance=0):
        account = Account(account_type, initial_balance)
        user.add_account(account)
        self.accounts[account.account_id] = account
        return account

    def transfer(self, from_account, to_account, amount, description="Transfer"):
        if amount <= 0:
            raise ValueError("Amount must be positive")
        if amount > from_account.balance:
            raise ValueError("Insufficient funds")
        from_account.withdraw(amount, f"Transfer to account {to_account.account_id}: {description}")
        to_account.deposit(amount, f"Transfer from account {from_account.account_id}: {description}")

    def pay_bill(self, account, payee, amount, description="Bill Payment"):
        if amount <= 0:
            raise ValueError("Amount must be positive")
        if amount > account.balance:
            raise ValueError("Insufficient funds")
        return account.withdraw(amount, f"Bill payment to {payee}: {description}")

class BankingApp:
    def __init__(self):
        self.bank = Bank()
        self.current_user = None

    def register(self, name, email, password):
        return self.bank.register_user(name, email, password)

    def login(self, email, password):
        self.current_user = self.bank.authenticate_user(email, password)
        return self.current_user is not None

    def logout(self):
        self.current_user = None

    def create_account(self, account_type, initial_balance=0):
        if not self.current_user:
            raise ValueError("User not logged in")
        return self.bank.create_account(self.current_user, account_type, initial_balance)

    def list_accounts(self):
        if not self.current_user:
            raise ValueError("User not logged in")
        return self.current_user.get_accounts()

    def view_balance(self, account):
        if not self.current_user:
            raise ValueError("User not logged in")
        return account.get_balance()

    def view_transactions(self, account):
        if not self.current_user:
            raise ValueError("User not logged in")
        return account.get_transactions()

    def deposit(self, account, amount, description="Deposit"):
        if not self.current_user:
            raise ValueError("User not logged in")
        return account.deposit(amount, description)

    def withdraw(self, account, amount, description="Withdrawal"):
        if not self.current_user:
            raise ValueError("User not logged in")
        return account.withdraw(amount, description)

    def transfer(self, from_account, to_account, amount, description="Transfer"):
        if not self.current_user:
            raise ValueError("User not logged in")
        self.bank.transfer(from_account, to_account, amount, description)

    def pay_bill(self, account, payee, amount, description="Bill Payment"):
        if not self.current_user:
            raise ValueError("User not logged in")
        return self.bank.pay_bill(account, payee, amount, description)
