import datetime
import json
import os

class Event:
    def __init__(self, title, date, time, description, location, created_by):
        self.title = title
        self.date = date
        self.time = time
        self.description = description
        self.location = location
        self.created_by = created_by
        self.event_id = self._generate_id()

    def _generate_id(self):
        return f"{self.date}-{self.time}-{hash(self.title + self.description)}"

    def to_dict(self):
        return {
            "title": self.title,
            "date": self.date,
            "time": self.time,
            "description": self.description,
            "location": self.location,
            "created_by": self.created_by,
            "event_id": self.event_id
        }

    @classmethod
    def from_dict(cls, data):
        event = cls(
            data["title"], 
            data["date"], 
            data["time"], 
            data["description"], 
            data["location"], 
            data["created_by"]
        )
        event.event_id = data["event_id"]
        return event

class FamilyCalendar:
    def __init__(self, family_name):
        self.family_name = family_name
        self.events = {}
        self.users = set()
        self.file_path = f"{family_name}_calendar.json"
        self.load_calendar()

    def add_user(self, username):
        self.users.add(username)
        self.save_calendar()
        return f"User {username} added to {self.family_name} calendar"

    def add_event(self, username, title, date, time, description="", location=""):
        if username not in self.users:
            return f"User {username} not found in {self.family_name} calendar"

        try:
            datetime.datetime.strptime(date, "%Y-%m-%d")
            datetime.datetime.strptime(time, "%H:%M")
        except ValueError:
            return "Invalid date or time format. Use YYYY-MM-DD for date and HH:MM for time."

        event = Event(title, date, time, description, location, username)
        self.events[event.event_id] = event
        self.save_calendar()
        return f"Event '{title}' added successfully"

    def get_events_by_date(self, date):
        try:
            datetime.datetime.strptime(date, "%Y-%m-%d")
        except ValueError:
            return "Invalid date format. Use YYYY-MM-DD."

        events = [event for event in self.events.values() if event.date == date]
        return sorted(events, key=lambda e: e.time)

    def update_event(self, event_id, username, **kwargs):
        if event_id not in self.events:
            return "Event not found"

        event = self.events[event_id]
        if event.created_by != username and username not in self.users:
            return "You don't have permission to update this event"

        for key, value in kwargs.items():
            if hasattr(event, key):
                setattr(event, key, value)

        self.save_calendar()
        return f"Event '{event.title}' updated successfully"

    def delete_event(self, event_id, username):
        if event_id not in self.events:
            return "Event not found"

        event = self.events[event_id]
        if event.created_by != username and username not in self.users:
            return "You don't have permission to delete this event"

        del self.events[event_id]
        self.save_calendar()
        return f"Event '{event.title}' deleted successfully"

    def save_calendar(self):
        data = {
            "family_name": self.family_name,
            "users": list(self.users),
            "events": {event_id: event.to_dict() for event_id, event in self.events.items()}
        }

        with open(self.file_path, 'w') as f:
            json.dump(data, f, indent=2)

    def load_calendar(self):
        if not os.path.exists(self.file_path):
            return

        try:
            with open(self.file_path, 'r') as f:
                data = json.load(f)

            self.family_name = data.get("family_name", self.family_name)
            self.users = set(data.get("users", []))

            events_data = data.get("events", {})
            self.events = {
                event_id: Event.from_dict(event_data) 
                for event_id, event_data in events_data.items()
            }
        except Exception as e:
            print(f"Error loading calendar: {e}")

def main():
    calendar = FamilyCalendar("Smith")

    calendar.add_user("Mom")
    calendar.add_user("Dad")
    calendar.add_user("Son")

    calendar.add_event("Mom", "Dentist", "2023-10-20", "14:30", "Regular checkup", "Dental Clinic")
    calendar.add_event("Dad", "Soccer Game", "2023-10-20", "18:00", "School championship", "Sports Field")

    print("Events on 2023-10-20:")
    for event in calendar.get_events_by_date("2023-10-20"):
        print(f"{event.time} - {event.title} (Added by {event.created_by})")
        print(f"  Location: {event.location}")
        print(f"  Description: {event.description}")

if __name__ == "__main__":
    main()
