import os
import re
import argparse
import sys

def batch_rename(dir_path, find, replace, recursive=False, dry_run=False, case_sensitive=True):
    if not os.path.isdir(dir_path):
        print(f"Error: {dir_path} is not a valid directory")
        return

    flags = 0 if case_sensitive else re.IGNORECASE
    pattern = re.compile(find, flags)

    walk_func = os.walk if recursive else lambda d: [(d, [], [f for f in os.listdir(d) if os.path.isfile(os.path.join(d, f))])]

    for root, dirs, files in walk_func(dir_path):
        for filename in files:
            if pattern.search(filename):
                new_name = pattern.sub(replace, filename)
                if new_name != filename:
                    old_path = os.path.join(root, filename)
                    new_path = os.path.join(root, new_name)

                    if dry_run:
                        print(f"Would rename '{old_path}' to '{new_path}'")
                    else:
                        try:
                            if os.path.exists(new_path):
                                print(f"Error: Cannot rename '{old_path}' - '{new_path}' already exists")
                            else:
                                os.rename(old_path, new_path)
                                print(f"Renamed '{old_path}' to '{new_path}'")
                        except Exception as e:
                            print(f"Error renaming '{old_path}': {e}")

def main():
    parser = argparse.ArgumentParser(description='Batch rename files using regular expressions')
    parser.add_argument('dir_path', help='Directory containing files to rename')
    parser.add_argument('find', help='Regular expression pattern to find')
    parser.add_argument('replace', help='Replacement string (can include regex groups like \\1)')
    parser.add_argument('-r', '--recursive', action='store_true', help='Process subdirectories recursively')
    parser.add_argument('-d', '--dry-run', action='store_true', help='Show what would be renamed without making changes')
    parser.add_argument('-i', '--case-insensitive', action='store_true', help='Make pattern matching case insensitive')

    args = parser.parse_args()

    batch_rename(
        args.dir_path,
        args.find,
        args.replace,
        recursive=args.recursive,
        dry_run=args.dry_run,
        case_sensitive=not args.case_insensitive
    )

if __name__ == "__main__":
    main()
