        return None

    try:
        subprocess.run(["ffmpeg", "-i", input_path, "-c", "copy", output_path], check=True)
        return output_path
    except subprocess.CalledProcessError:
        return None

def transcode_video(input_path, output_path, format_settings):
    if not os.path.exists(input_path):
        return None

    codec = format_settings.get("codec", "libx264")
    resolution = format_settings.get("resolution", "1280x720")
    bitrate = format_settings.get("bitrate", "1M")

    try:
        subprocess.run([
            "ffmpeg", "-i", input_path, 
            "-c:v", codec, 
            "-s", resolution, 
            "-b:v", bitrate, 
            "-c:a", "aac", 
            output_path
        ], check=True)
        return output_path
    except subprocess.CalledProcessError:
        return None

def process_video(video_url, video_id, formats):
    download_dir = "downloads"
    process_dir = "processed"
    output_dir = "transcoded"

    os.makedirs(download_dir, exist_ok=True)
    os.makedirs(process_dir, exist_ok=True)
    os.makedirs(output_dir, exist_ok=True)

    download_path = os.path.join(download_dir, f"{video_id}.mp4")
    process_path = os.path.join(process_dir, f"{video_id}.mp4")

    if download_video(video_url, download_path):
        if decompress_video(download_path, process_path):
            results = []

            with concurrent.futures.ThreadPoolExecutor(max_workers=3) as executor:
                futures = {}

                for fmt_name, fmt_settings in formats.items():
                    output_path = os.path.join(output_dir, f"{video_id}_{fmt_name}.mp4")
                    future = executor.submit(transcode_video, process_path, output_path, fmt_settings)
                    futures[future] = fmt_name

                for future in concurrent.futures.as_completed(futures):
                    fmt_name = futures[future]
                    result = future.result()
                    if result:
                        results.append((fmt_name, result))

            return results

    return []

def main():
    video_queue = [
        ("https://example.com/video1.mp4", "video1"),
        ("https://example.com/video2.mp4", "video2")
    ]

    formats = {
        "720p": {"resolution": "1280x720", "bitrate": "2M"},
        "480p": {"resolution": "854x480", "bitrate": "1M"},
        "360p": {"resolution": "640x360", "bitrate": "600K"}
    }

    for video_url, video_id in video_queue:
        results = process_video(video_url, video_id, formats)
        print(f"Video {video_id} transcoded to formats: {results}")

if __name__ == "__main__":
    main()
