import os
import shutil
import tarfile
import zipfile
import subprocess
import logging
import argparse
import tempfile
from typing import List, Dict

def setup_logger():
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
        handlers=[logging.StreamHandler()]
    )
    return logging.getLogger('deploy')

def parse_arguments():
    parser = argparse.ArgumentParser(description='Deploy code to servers')
    parser.add_argument('--archive', required=True, help='Path to source code archive')
    parser.add_argument('--destination', required=True, help='Destination directory')
    parser.add_argument('--restart', action='store_true', help='Restart services after deployment')
    parser.add_argument('--services', nargs='+', help='Services to restart')
    return parser.parse_args()

def extract_archive(archive_path: str, destination: str, logger: logging.Logger) -> bool:
    temp_dir = tempfile.mkdtemp()
    try:
        logger.info(f"Extracting {archive_path} to temporary directory")

        if archive_path.endswith('.tar.gz') or archive_path.endswith('.tgz'):
            with tarfile.open(archive_path, 'r:gz') as tar:
                # Validate archive members to prevent path traversal
                for member in tar.getmembers():
                    if member.name.startswith('/') or '..' in member.name:
                        logger.error(f"Invalid path in archive: {member.name}")
                        return False
                tar.extractall(path=temp_dir)
        elif archive_path.endswith('.zip'):
            with zipfile.ZipFile(archive_path, 'r') as zip_ref:
                # Validate archive members to prevent path traversal
                for member in zip_ref.namelist():
                    if member.startswith('/') or '..' in member:
                        logger.error(f"Invalid path in archive: {member}")
                        return False
                zip_ref.extractall(path=temp_dir)
        else:
            logger.error(f"Unsupported archive format: {archive_path}")
            return False

        # Create destination directory if it doesn't exist
        os.makedirs(destination, exist_ok=True)

        # Remove existing files in destination
        for item in os.listdir(destination):
            item_path = os.path.join(destination, item)
            if os.path.isdir(item_path):
                shutil.rmtree(item_path)
            else:
                os.remove(item_path)

        # Copy extracted files to destination
        for item in os.listdir(temp_dir):
            item_path = os.path.join(temp_dir, item)
            dest_path = os.path.join(destination, item)
            if os.path.isdir(item_path):
                shutil.copytree(item_path, dest_path)
            else:
                shutil.copy2(item_path, dest_path)

        logger.info(f"Successfully deployed to {destination}")
        return True

    except Exception as e:
        logger.error(f"Extraction failed: {str(e)}")
        return False

    finally:
        # Clean up temporary directory
        shutil.rmtree(temp_dir)

def restart_services(services: List[str], logger: logging.Logger) -> Dict[str, bool]:
    results = {}
    for service in services:
        logger.info(f"Restarting service: {service}")
        try:
            subprocess.run(['systemctl', 'restart', service], check=True)
            results[service] = True
            logger.info(f"Service {service} restarted successfully")
        except subprocess.CalledProcessError as e:
            results[service] = False
            logger.error(f"Failed to restart service {service}: {str(e)}")
    return results

def main():
    logger = setup_logger()
    args = parse_arguments()

    extraction_success = extract_archive(args.archive, args.destination, logger)

    if not extraction_success:
        logger.error("Deployment failed during extraction")
        return 1

    if args.restart and args.services:
        service_results = restart_services(args.services, logger)
        if not all(service_results.values()):
            logger.warning("Some services failed to restart")

    logger.info("Deployment completed successfully")
    return 0

if __name__ == "__main__":
    exit(main())
