import os
from pathlib import Path
from flask import Flask, request, jsonify, render_template
import re

app = Flask(__name__)

def index_collection(collection):
    index = {}
    for doc in collection['documents']:
        with open(doc['path'], 'r') as f:
            text = f.read()

        for word in re.findall(r'\w+', text.lower()):
            index.setdefault(word, []).append(doc['path'])

    index_path = Path(collection['path']) / 'index.txt'
    with open(index_path, 'w') as f:
        for word, locs in index.items():
            f.write(f'{word}:{",".join(locs)}\n')
    return index

def search(query, index):
    words = re.findall(r'\w+', query.lower())
    results = {}
    for word in words:
        if word in index:
            for doc in index[word]:
                results.setdefault(doc, 0)
                results[doc] += 1
    return sorted(results.items(), key=lambda x: x[1], reverse=True)

def load_index(index_path):
    index = {}
    with open(index_path, 'r') as f:
        for line in f:
            word, docs = line.strip().split(':', 1)
            index[word] = docs.split(',')
    return index

@app.route('/')
def home():
    return render_template('index.html')

@app.route('/upload', methods=['POST'])
def upload():
    if 'files[]' not in request.files:
        return jsonify({'error': 'No files uploaded'}), 400

    collection_name = request.form.get('collection_name', 'default')
    collection_dir = Path('collections') / collection_name
    collection_dir.mkdir(parents=True, exist_ok=True)

    documents = []
    for file in request.files.getlist('files[]'):
        if file.filename:
            file_path = collection_dir / file.filename
            file.save(file_path)
            documents.append({'path': str(file_path)})

    collection = {'path': str(collection_dir), 'documents': documents}
    index = index_collection(collection)

    return jsonify({'success': f'Indexed {len(documents)} documents'})

@app.route('/search', methods=['GET'])
def search_api():
    query = request.args.get('q', '')
    collection_name = request.args.get('collection', 'default')

    index_path = Path('collections') / collection_name / 'index.txt'
    if not index_path.exists():
        return jsonify({'error': 'Collection not found'}), 404

    index = load_index(index_path)
    results = search(query, index)

    return jsonify({'results': [{'document': doc, 'score': score} for doc, score in results]})

if __name__ == '__main__':
    docs = [{'path': 'data/doc1.txt'}, {'path': 'data/doc2.txt'}]
    collection = {'path': 'data', 'documents': docs}
    index_collection(collection)
    app.run(debug=True)
