import os
import zipfile
import subprocess
import json
import argparse
import logging
from datetime import datetime

def setup_logging():
    logging.basicConfig(
        level=logging.INFO,
        format='%(asctime)s - %(name)s - %(levelname)s - %(message)s',
        filename='/var/www/results/test_automation.log'
    )
    return logging.getLogger('test_automation')

def parse_args():
    parser = argparse.ArgumentParser(description='Automated VM Test Suite')
    parser.add_argument('--config', type=str, default='/etc/test_config.json', 
                        help='Path to configuration file')
    parser.add_argument('--permissions', type=str, default='750',
                        help='Output file permissions (octal)')
    parser.add_argument('--owner', type=str, default='www-data',
                        help='Owner for output files')
    parser.add_argument('--group', type=str, default='www-data',
                        help='Group for output files')
    return parser.parse_args()

def load_config(config_path):
    with open(config_path, 'r') as f:
        return json.load(f)

def provision_vm(config, logger):
    vm_name = f"test-vm-{datetime.now().strftime('%Y%m%d-%H%M%S')}"
    logger.info(f"Provisioning VM: {vm_name}")

    try:
        subprocess.run([
            'ansible-playbook', 
            config['provision_playbook'],
            '-e', f"vm_name={vm_name}"
        ], check=True)
        return vm_name
    except subprocess.CalledProcessError as e:
        logger.error(f"Failed to provision VM: {e}")
        return None

def run_tests(vm_name, config, logger):
    output_dir = f"/var/www/results/test_run_{datetime.now().strftime('%Y%m%d-%H%M%S')}"
    os.makedirs(output_dir, exist_ok=True)

    logger.info(f"Running tests on VM: {vm_name}")
    try:
        result = subprocess.run([
            'ansible-playbook',
            config['test_playbook'],
            '-e', f"vm_name={vm_name}",
            '-e', f"output_dir={output_dir}"
        ], check=True, capture_output=True, text=True)

        with open(f"{output_dir}/ansible.log", 'w') as f:
            f.write(result.stdout)

        return output_dir
    except subprocess.CalledProcessError as e:
        logger.error(f"Failed to run tests: {e}")
        with open(f"{output_dir}/error.log", 'w') as f:
            f.write(e.stdout)
            f.write(e.stderr)
        return output_dir

def cleanup_vm(vm_name, config, logger):
    logger.info(f"Cleaning up VM: {vm_name}")
    try:
        subprocess.run([
            'ansible-playbook',
            config['cleanup_playbook'],
            '-e', f"vm_name={vm_name}"
        ], check=True)
    except subprocess.CalledProcessError as e:
        logger.error(f"Failed to cleanup VM: {e}")

def set_permissions(path, permissions, owner, group, logger):
    logger.info(f"Setting permissions on {path}: {permissions} {owner}:{group}")
    try:
        if os.path.isdir(path):
            for root, dirs, files in os.walk(path):
                for d in dirs:
                    os.chmod(os.path.join(root, d), int(permissions, 8))
                    subprocess.run(['chown', f"{owner}:{group}", os.path.join(root, d)], check=True)
                for f in files:
                    os.chmod(os.path.join(root, f), int(permissions, 8))
                    subprocess.run(['chown', f"{owner}:{group}", os.path.join(root, f)], check=True)
        else:
            os.chmod(path, int(permissions, 8))
            subprocess.run(['chown', f"{owner}:{group}", path], check=True)
    except (OSError, subprocess.CalledProcessError) as e:
        logger.error(f"Failed to set permissions: {e}")

def create_zip():
    zip_path = '/var/www/results/results.zip'

    with zipfile.ZipFile(zip_path, 'w') as zipf:
        for root, dirs, files in os.walk('/var/www/results'):
            for f in files:
                if f != 'results.zip':
                    zipf.write(os.path.join(root, f),
                               arcname=os.path.join('results', f))
    return zip_path

def main():
    args = parse_args()
    logger = setup_logging()

    try:
        config = load_config(args.config)

        vm_name = provision_vm(config, logger)
        if not vm_name:
            return 1

        output_dir = run_tests(vm_name, config, logger)
        cleanup_vm(vm_name, config, logger)

        set_permissions(output_dir, args.permissions, args.owner, args.group, logger)

        zip_path = create_zip()
        set_permissions(zip_path, args.permissions, args.owner, args.group, logger)

        logger.info("Test automation completed successfully")
        return 0

    except Exception as e:
        logger.error(f"Unexpected error: {e}")
        return 1

if __name__ == "__main__":
    exit(main())
