import os
import shutil
import argparse
import stat

def copy_files(source_dir, dest_dir, permissions=None):
    if not os.path.exists(source_dir):
        print(f"Error: Source directory '{source_dir}' does not exist.")
        return False

    if not os.path.exists(dest_dir):
        os.makedirs(dest_dir)

    for item in os.listdir(source_dir):
        source_path = os.path.join(source_dir, item)
        dest_path = os.path.join(dest_dir, item)

        if os.path.isfile(source_path):
            shutil.copy2(source_path, dest_path)

            if permissions:
                os.chmod(dest_path, permissions)

            print(f"Copied: {source_path} -> {dest_path}")
        elif os.path.isdir(source_path):
            copy_files(source_path, dest_path, permissions)

    return True

def main():
    parser = argparse.ArgumentParser(description="Copy files with custom permissions")
    parser.add_argument("source", help="Source directory path")
    parser.add_argument("destination", help="Destination directory path")
    parser.add_argument("-p", "--permissions", help="Permissions in octal (e.g., 0o755)")

    args = parser.parse_args()

    perm = None
    if args.permissions:
        try:
            perm = int(args.permissions, 8)
        except ValueError:
            print(f"Invalid permissions format: {args.permissions}")
            return

    copy_files(args.source, args.destination, perm)

if __name__ == "__main__":
    main()
