from typing import List, Dict, Optional
import uuid
import datetime

class User:
    def __init__(self, name: str, email: str):
        self.id = str(uuid.uuid4())
        self.name = name
        self.email = email
        self.created_at = datetime.datetime.now()

class Driver(User):
    def __init__(self, name: str, email: str, vehicle_model: str, license_plate: str):
        super().__init__(name, email)
        self.vehicle_model = vehicle_model
        self.license_plate = license_plate
        self.available = False
        self.current_location = None
        self.rating = 0.0
        self.ride_count = 0

    def toggle_availability(self):
        self.available = not self.available
        return self.available

    def update_location(self, location):
        self.current_location = location

class Passenger(User):
    def __init__(self, name: str, email: str):
        super().__init__(name, email)
        self.current_location = None
        self.rating = 0.0
        self.ride_count = 0

    def update_location(self, location):
        self.current_location = location

class Ride:
    def __init__(self, passenger: Passenger, pickup_location, destination):
        self.id = str(uuid.uuid4())
        self.passenger = passenger
        self.driver = None
        self.pickup_location = pickup_location
        self.destination = destination
        self.status = "REQUESTED"
        self.created_at = datetime.datetime.now()
        self.completed_at = None
        self.price = 0.0

    def assign_driver(self, driver: Driver):
        self.driver = driver
        self.status = "ASSIGNED"
        return True

    def start_ride(self):
        if self.status != "ASSIGNED":
            return False
        self.status = "IN_PROGRESS"
        return True

    def complete_ride(self):
        if self.status != "IN_PROGRESS":
            return False
        self.status = "COMPLETED"
        self.completed_at = datetime.datetime.now()
        return True

    def cancel_ride(self):
        if self.status in ["COMPLETED", "CANCELLED"]:
            return False
        self.status = "CANCELLED"
        return True

class RideMatchingService:
    def __init__(self):
        self.drivers: List[Driver] = []
        self.passengers: List[Passenger] = []
        self.rides: Dict[str, Ride] = {}

    def register_driver(self, driver: Driver):
        self.drivers.append(driver)
        return driver

    def register_passenger(self, passenger: Passenger):
        self.passengers.append(passenger)
        return passenger

    def request_ride(self, passenger: Passenger, pickup_location, destination) -> Optional[Ride]:
        ride = Ride(passenger, pickup_location, destination)
        self.rides[ride.id] = ride

        matched_driver = self._find_driver(pickup_location)
        if matched_driver:
            ride.assign_driver(matched_driver)
            matched_driver.toggle_availability()

        return ride

    def _find_driver(self, pickup_location) -> Optional[Driver]:
        available_drivers = [d for d in self.drivers if d.available]
        if not available_drivers:
            return None

        # In a real app, use geospatial queries to find nearest driver
        # For this example, just return the first available driver
        return available_drivers[0] if available_drivers else None

    def get_ride_status(self, ride_id: str) -> Optional[str]:
        if ride_id in self.rides:
            return self.rides[ride_id].status
        return None
