#!/usr/bin/env python3
import os
import re
import argparse
import stat
from pathlib import Path


def rename_files(directory, pattern, replacement, recursive=False, permissions=None):
    dir_path = Path(directory)
    if not dir_path.exists() or not dir_path.is_dir():
        print(f"Error: {directory} is not a valid directory")
        return

    files_to_process = []
    if recursive:
        for root, _, files in os.walk(dir_path):
            for file in files:
                files_to_process.append(Path(root) / file)
    else:
        files_to_process = [f for f in dir_path.iterdir() if f.is_file()]

    for file_path in files_to_process:
        new_name = re.sub(pattern, replacement, file_path.name)
        if new_name != file_path.name:
            new_path = file_path.parent / new_name
            try:
                file_path.rename(new_path)
                print(f"Renamed: {file_path} → {new_path}")

                if permissions is not None:
                    os.chmod(new_path, permissions)
                    print(f"Applied permissions: {oct(permissions)[2:]} to {new_path}")
            except Exception as e:
                print(f"Error renaming {file_path}: {e}")


def parse_permissions(perm_str):
    if perm_str.isdigit() and len(perm_str) <= 4:
        return int(perm_str, 8)

    result = 0
    for who in perm_str:
        if who == 'u':
            result |= stat.S_IRUSR | stat.S_IWUSR | stat.S_IXUSR
        elif who == 'g':
            result |= stat.S_IRGRP | stat.S_IWGRP | stat.S_IXGRP
        elif who == 'o':
            result |= stat.S_IROTH | stat.S_IWOTH | stat.S_IXOTH
        elif who == 'a':
            result |= (stat.S_IRUSR | stat.S_IWUSR | stat.S_IXUSR |
                      stat.S_IRGRP | stat.S_IWGRP | stat.S_IXGRP |
                      stat.S_IROTH | stat.S_IWOTH | stat.S_IXOTH)
    return result


def main():
    parser = argparse.ArgumentParser(description="Bulk rename files based on patterns")
    parser.add_argument("-d", "--directory", default=".", help="Directory to process files in")
    parser.add_argument("-p", "--pattern", required=True, help="Regex pattern to match in filenames")
    parser.add_argument("-r", "--replacement", required=True, help="Replacement pattern")
    parser.add_argument("-R", "--recursive", action="store_true", help="Process directories recursively")
    parser.add_argument("-m", "--permissions", help="Permissions to apply to renamed files (e.g., 644 or ugo)")

    args = parser.parse_args()

    permissions = None
    if args.permissions:
        permissions = parse_permissions(args.permissions)

    rename_files(args.directory, args.pattern, args.replacement, args.recursive, permissions)


if __name__ == "__main__":
