import os
import json
import hashlib
import difflib
import datetime
import shutil

class VersionControl:
    def __init__(self, repo_path="."):
        self.repo_path = os.path.abspath(repo_path)
        self.vc_dir = os.path.join(self.repo_path, ".vc")
        self.objects_dir = os.path.join(self.vc_dir, "objects")
        self.refs_dir = os.path.join(self.vc_dir, "refs")
        self.current_branch = "main"

    def init(self):
        if os.path.exists(self.vc_dir):
            return "Repository already initialized"

        os.makedirs(self.vc_dir)
        os.makedirs(self.objects_dir)
        os.makedirs(self.refs_dir)
        os.makedirs(os.path.join(self.refs_dir, "heads"))

        with open(os.path.join(self.vc_dir, "HEAD"), "w") as f:
            f.write("ref: refs/heads/main")

        return "Initialized empty repository"

    def hash_object(self, data):
        sha1 = hashlib.sha1(data.encode()).hexdigest()
        path = os.path.join(self.objects_dir, sha1[:2])
        if not os.path.exists(path):
            os.makedirs(path)
        file_path = os.path.join(path, sha1[2:])
        if not os.path.exists(file_path):
            with open(file_path, "wb") as f:
                f.write(data.encode())
        return sha1

    def get_object(self, sha1):
        path = os.path.join(self.objects_dir, sha1[:2], sha1[2:])
        if os.path.exists(path):
            with open(path, "rb") as f:
                return f.read().decode()
        return None

    def commit(self, message):
        status = self.status()
        if not status["staged"]:
            return "No changes staged for commit"

        index = self.read_index()
        tree_content = {}

        for file_path, file_hash in index.items():
            tree_content[file_path] = file_hash

        tree_str = json.dumps(tree_content, sort_keys=True)
        tree_hash = self.hash_object(tree_str)

        parent = self.get_current_commit()
        timestamp = datetime.datetime.now().isoformat()

        commit_content = {
            "tree": tree_hash,
            "parent": parent,
            "author": "User <user@example.com>",
            "timestamp": timestamp,
            "message": message
        }

        commit_str = json.dumps(commit_content, sort_keys=True)
        commit_hash = self.hash_object(commit_str)

        branch_path = os.path.join(self.refs_dir, "heads", self.current_branch)
        with open(branch_path, "w") as f:
            f.write(commit_hash)

        return f"Created commit {commit_hash}"

    def add(self, file_path):
        abs_path = os.path.join(self.repo_path, file_path)
        if not os.path.exists(abs_path):
            return f"File {file_path} does not exist"

        with open(abs_path, "r") as f:
            content = f.read()

        file_hash = self.hash_object(content)
        index = self.read_index()
        index[file_path] = file_hash
        self.write_index(index)

        return f"Added {file_path} to staging area"

    def read_index(self):
        index_path = os.path.join(self.vc_dir, "index")
        if not os.path.exists(index_path):
            return {}
        with open(index_path, "r") as f:
            return json.load(f)

    def write_index(self, index):
        index_path = os.path.join(self.vc_dir, "index")
        with open(index_path, "w") as f:
            json.dump(index, f)

    def get_current_commit(self):
        head_path = os.path.join(self.vc_dir, "HEAD")
        if not os.path.exists(head_path):
            return None

        with open(head_path, "r") as f:
            ref = f.read().strip()

        if ref.startswith("ref: "):
            ref_path = os.path.join(self.vc_dir, ref[5:])
            if os.path.exists(ref_path):
                with open(ref_path, "r") as f:
                    return f.read().strip()
        return None

    def status(self):
        index = self.read_index()

        modified = {}
        staged = {}
        untracked = []

        for root, _, files in os.walk(self.repo_path):
            if os.path.relpath(root, self.repo_path).startswith(".vc"):
                continue

            for file in files:
                file_path = os.path.relpath(os.path.join(root, file), self.repo_path)
                if file_path.startswith(".vc"):
                    continue

                with open(os.path.join(root, file), "r") as f:
                    content = f.read()

                file_hash = hashlib.sha1(content.encode()).hexdigest()

                if file_path in index:
                    if index[file_path] != file_hash:
                        modified[file_path] = (index[file_path], file_hash)
                    staged[file_path] = index[file_path]
                else:
                    untracked.append(file_path)

        return {
            "modified": modified,
            "staged": staged,
            "untracked": untracked
        }

    def branch(self, name=None):
        if name is None:
            branches = []
            heads_dir = os.path.join(self.refs_dir, "heads")
            for branch_name in os.listdir(heads_dir):
                branch_path = os.path.join(heads_dir, branch_name)
                if os.path.isfile(branch_path):
                    branches.append(branch_name)
            return branches
        else:
            current_commit = self.get_current_commit()
            if current_commit is None:
                return "No commits yet, can't create branch"

            branch_path = os.path.join(self.refs_dir, "heads", name)
            if os.path.exists(branch_path):
                return f"Branch {name} already exists"

            with open(branch_path, "w") as f:
                f.write(current_commit)

            return f"Created branch {name}"

    def checkout(self, branch_or_commit):
        branch_path = os.path.join(self.refs_dir, "heads", branch_or_commit)

        if os.path.exists(branch_path):
            with open(branch_path, "r") as f:
                commit_id = f.read().strip()

