import os
import tarfile
import hashlib
import json
import time
import shutil
from pathlib import Path

class DifferentialBackup:
    def __init__(self, source_dir, backup_dir):
        self.source_dir = Path(source_dir)
        self.backup_dir = Path(backup_dir)
        self.metadata_file = self.backup_dir / "backup_metadata.json"
        self.previous_metadata = {}

        if not self.backup_dir.exists():
            self.backup_dir.mkdir(parents=True)

        if self.metadata_file.exists():
            with open(self.metadata_file, 'r') as f:
                self.previous_metadata = json.load(f)

    def calculate_file_hash(self, filepath):
        with open(filepath, 'rb') as f:
            return hashlib.md5(f.read()).hexdigest()

    def create_backup(self):
        current_metadata = {}
        files_to_backup = []

        for root, _, files in os.walk(self.source_dir):
            for filename in files:
                filepath = Path(root) / filename
                rel_path = filepath.relative_to(self.source_dir)

                file_hash = self.calculate_file_hash(filepath)
                file_mtime = os.path.getmtime(filepath)

                current_metadata[str(rel_path)] = {
                    "hash": file_hash,
                    "mtime": file_mtime
                }

                if str(rel_path) not in self.previous_metadata or self.previous_metadata[str(rel_path)]["hash"] != file_hash:
                    files_to_backup.append(filepath)

        if files_to_backup:
            timestamp = int(time.time())
            backup_filename = f"backup_{timestamp}.tar.gz"
            backup_path = self.backup_dir / backup_filename

            with tarfile.open(backup_path, "w:gz") as tar:
                for file_path in files_to_backup:
                    arcname = file_path.relative_to(self.source_dir)
                    tar.add(file_path, arcname=arcname)

            with open(self.metadata_file, 'w') as f:
                json.dump(current_metadata, f)

            return backup_path, len(files_to_backup)
        else:
            return None, 0

    def restore(self, target_dir, backup_file=None):
        target_path = Path(target_dir)

        if not target_path.exists():
            target_path.mkdir(parents=True)

        if backup_file:
            backup_path = self.backup_dir / backup_file
        else:
            backup_files = sorted([f for f in os.listdir(self.backup_dir) if f.startswith("backup_") and f.endswith(".tar.gz")])
            if not backup_files:
                return False
            backup_path = self.backup_dir / backup_files[-1]

        with tarfile.open(backup_path, 'r:gz') as tar:
            tar.extractall(path=target_path)

        return True

if __name__ == "__main__":
    source_directory = "/path/to/source"
    backup_directory = "/path/to/backups"

    backup_tool = DifferentialBackup(source_directory, backup_directory)
    backup_file, files_backed_up = backup_tool.create_backup()

    if backup_file:
        print(f"Backup created: {backup_file}")
        print(f"Files backed up: {files_backed_up}")
    else:
        print("No changes detected. No backup created.")

    # To restore:
    # backup_tool.restore("/path/to/restore")
