        return jsonify({'status': 'error', 'message': 'Calories are required'}), 400

    try:
        calories = float(calories)
    except ValueError:
        return jsonify({'status': 'error', 'message': 'Calories must be a number'}), 400

    cursor = conn.cursor()
    cursor.execute(query, (calories, food_name))

    if cursor.rowcount == 0:
        cursor.execute("INSERT INTO foods (food_name, calories) VALUES (?, ?)", (food_name, calories))

