import os
import requests
import errno

lyrics_dir = '/var/www/lyrics/'

def get_lyrics(song):
    try:
        response = requests.get(f'https://api.lyrics.ovh/v1/{song}')
        response.raise_for_status()
        return response.json().get('lyrics', 'Lyrics not found')
    except (requests.RequestException, ValueError):
        return "Could not fetch lyrics"

def write_lyrics_to_file(lyrics, song):
    try:
        if not os.path.exists(lyrics_dir):
            os.makedirs(lyrics_dir, mode=0o755, exist_ok=True)

        filename = os.path.join(lyrics_dir, song.replace('/', '_')) + '.txt'
        with open(filename, 'w') as f:
            f.write(lyrics)

        os.chmod(filename, 0o644)
        return filename
    except (IOError, OSError) as e:
        if e.errno == errno.EACCES:
            return "Permission denied"
        return f"Error saving lyrics: {str(e)}"

def read_lyrics_from_file(song):
    filename = os.path.join(lyrics_dir, song.replace('/', '_')) + '.txt'
    try:
        if os.path.exists(filename):
            with open(filename, 'r') as f:
                return f.read()
        return None
    except (IOError, OSError):
        return None

if __name__ == '__main__':
    song = input('Enter a song: ')
    cached_lyrics = read_lyrics_from_file(song)

    if cached_lyrics:
        print("Cached lyrics found:")
        print(cached_lyrics)
    else:
        print("Fetching lyrics...")
        lyrics = get_lyrics(song)
        if lyrics != "Could not fetch lyrics":
            filename = write_lyrics_to_file(lyrics, song)
            print(f"Lyrics saved to {filename}")
