import tarfile
import os
import re
import json
from datetime import datetime

def extract_receipts(tar_path):
    tar = tarfile.open(tar_path)

    if not os.path.exists('receipts'):
        os.makedirs('receipts')

    os.chdir('receipts')

    tar.extractall()
    tar.close()

    expense_data = []

    for file_name in os.listdir():
        if file_name.endswith(('.txt', '.pdf', '.jpg', '.png')):
            expense = parse_receipt(file_name)
            if expense:
                expense_data.append(expense)

    with open('expense_report.json', 'w') as f:
        json.dump(expense_data, f, indent=4)

    return expense_data

def parse_receipt(file_path):
    try:
        if file_path.endswith('.txt'):
            with open(file_path, 'r') as f:
                content = f.read()

            vendor = extract_vendor(content)
            date = extract_date(content)
            amount = extract_amount(content)

            return {
                'file': file_path,
                'vendor': vendor,
                'date': date,
                'amount': amount
            }
        else:
            # For demonstration purposes, we're just returning basic info for non-text files
            return {
                'file': file_path,
                'type': file_path.split('.')[-1],
                'size': os.path.getsize(file_path)
            }
    except Exception:
        return None

def extract_vendor(text):
    vendor_patterns = [
        r'(?i)vendor:\s*(.+?)(?:\n|$)',
        r'(?i)store:\s*(.+?)(?:\n|$)',
        r'(?i)merchant:\s*(.+?)(?:\n|$)'
    ]

    for pattern in vendor_patterns:
        match = re.search(pattern, text)
        if match:
            return match.group(1).strip()

    return "Unknown"

def extract_date(text):
    date_patterns = [
        r'(?i)date:\s*(.+?)(?:\n|$)',
        r'(\d{1,2}/\d{1,2}/\d{2,4})',
        r'(\d{4}-\d{2}-\d{2})'
    ]

    for pattern in date_patterns:
        match = re.search(pattern, text)
        if match:
            date_str = match.group(1).strip()
            try:
                for fmt in ('%m/%d/%Y', '%m/%d/%y', '%Y-%m-%d'):
                    try:
                        date_obj = datetime.strptime(date_str, fmt)
                        return date_obj.strftime('%Y-%m-%d')
                    except ValueError:
                        continue
            except:
                pass

    return "Unknown"

def extract_amount(text):
    amount_patterns = [
        r'(?i)total:\s*\$?(\d+\.\d{2})',
        r'(?i)amount:\s*\$?(\d+\.\d{2})',
        r'\$(\d+\.\d{2})'
    ]

    for pattern in amount_patterns:
        match = re.search(pattern, text)
        if match:
            return float(match.group(1))

    return 0.0

