from typing import Any, Dict, Optional, TypeVar

T = TypeVar('T')

class DataCache:
    def __init__(self, ttl_seconds: int = 300, max_size: int = 100):
        self.cache: Dict[str, Dict[str, Any]] = {}
        self.ttl_seconds = ttl_seconds
        self.max_size = max_size

    def get(self, key: str) -> Optional[Any]:
        if key in self.cache:
            entry = self.cache[key]
            if time.time() - entry["timestamp"] < self.ttl_seconds:
                return entry["data"]
            else:
                del self.cache[key]
        return None

    def set(self, key: str, data: Any) -> None:
        if len(self.cache) >= self.max_size:
            oldest_key = min(self.cache.keys(), key=lambda k: self.cache[k]["timestamp"])
            del self.cache[oldest_key]

        self.cache[key] = {
            "data": data,
            "timestamp": time.time()
        }

    def invalidate(self, key: str) -> None:
        if key in self.cache:
            del self.cache[key]

    def clear(self) -> None:
        self.cache.clear()

class GameDataCache:
    def __init__(self, data_source_path: str, ttl_seconds: int = 300):
        self.data_cache = DataCache(ttl_seconds=ttl_seconds)
        self.data_source_path = data_source_path

    @lru_cache(maxsize=32)
    def load_data_source(self, file_path: str) -> Dict[str, Any]:
        with open(f"{self.data_source_path}/{file_path}", "r") as f:
            return json.load(f)

    def get_game_data(self, data_type: str, data_id: str) -> Optional[Any]:
        cache_key = f"{data_type}:{data_id}"
        data = self.data_cache.get(cache_key)

        if data is None:
            try:
                source_data = self.load_data_source(f"{data_type}.json")
                if data_id in source_data:
                    data = source_data[data_id]
                    self.data_cache.set(cache_key, data)
            except (FileNotFoundError, json.JSONDecodeError):
                return None

        return data

    def preload_data(self, data_type: str) -> None:
        try:
            source_data = self.load_data_source(f"{data_type}.json")
            for data_id, data in source_data.items():
                cache_key = f"{data_type}:{data_id}"
