import argparse
import sys

def concatenate_files(input_files, output_file):
    with open(output_file, 'wb') as out:
        for file_path in input_files:
            try:
                with open(file_path, 'rb') as f:
                    out.write(f.read())
            except IOError as e:
                sys.stderr.write(f"Error reading {file_path}: {e}\n")

def main():
    parser = argparse.ArgumentParser(description='Concatenate multiple files into one')
    parser.add_argument('input_files', nargs='+', help='Input files to concatenate')
    parser.add_argument('-o', '--output', default='output.bin', help='Output file name')

    args = parser.parse_args()
    concatenate_files(args.input_files, args.output)

if __name__ == '__main__':
    main()
