import json
from pathlib import Path

class ComplexityAnalyzer:
    def __init__(self, config=None):
        self.config = config or {
            'max_method_length': 50,
            'max_cyclomatic_complexity': 10,
            'extensions': ['.py', '.js', '.java', '.c', '.cpp'],
            'exclude_dirs': ['venv', 'node_modules', '.git']
        }

    def analyze_file(self, filepath):
        issues = []
        ext = os.path.splitext(filepath)[1]

        if ext not in self.config['extensions']:
            return issues

        with open(filepath, 'r', encoding='utf-8', errors='ignore') as file:
            try:
                content = file.read()

                if ext == '.py':
                    issues.extend(self.analyze_python(content, filepath))
                elif ext in ['.js', '.java', '.c', '.cpp']:
                    issues.extend(self.analyze_curly_braces(content, filepath, ext))
            except Exception as e:
                issues.append({
                    'file': filepath,
                    'method': 'N/A',
                    'type': 'error',
                    'message': f'Error analyzing file: {str(e)}'
                })

        return issues

    def analyze_python(self, content, filepath):
        issues = []
        lines = content.split('\n')
        in_method = False
        method_name = ""
        method_start = 0
        method_indent = 0

        for i, line in enumerate(lines):
            stripped = line.strip()
            indent = len(line) - len(line.lstrip())

            if re.match(r'def\s+\w+\s*\(', stripped):
                method_name = re.search(r'def\s+(\w+)', stripped).group(1)
                method_start = i
                method_indent = indent
                in_method = True

            if in_method and (indent <= method_indent and stripped and i > method_start):
                method_length = i - method_start
                in_method = False

                if method_length > self.config['max_method_length']:
                    issues.append({
                        'file': filepath,
                        'method': method_name,
                        'line': method_start + 1,
                        'type': 'length',
                        'message': f'Method too long ({method_length} lines)'
                    })

                complexity = self.calculate_complexity(lines[method_start:i])
                if complexity > self.config['max_cyclomatic_complexity']:
                    issues.append({
                        'file': filepath,
                        'method': method_name,
                        'line': method_start + 1,
                        'type': 'complexity',
                        'message': f'Method too complex (score: {complexity})'
                    })

        return issues

    def analyze_curly_braces(self, content, filepath, ext):
        issues = []

        if ext == '.js':
            method_pattern = r'(function\s+(\w+)|(\w+)\s*:\s*function|\b(\w+)\s*\([^)]*\)\s*{)'
        elif ext == '.java':
            method_pattern = r'(public|private|protected)?\s+\w+\s+(\w+)\s*\([^)]*\)\s*{' 
        else:  # C/C++
            method_pattern = r'\b\w+\s+(\w+)\s*\([^)]*\)\s*{'

        methods = re.finditer(method_pattern, content)

        for match in methods:
            method_start = content[:match.end()].count('\n')

            # Find method name
            if ext == '.js':
                method_name = match.group(2) or match.group(3) or match.group(4) or "anonymous"
            elif ext == '.java':
                method_name = match.group(2)
            else:
                method_name = match.group(1)

            # Find closing brace
            open_braces = 1
            method_end = method_start

            for i, c in enumerate(content[match.end():]):
                if c == '{':
                    open_braces += 1
                elif c == '}':
                    open_braces -= 1
                    if open_braces == 0:
                        method_end = method_start + content[match.end():match.end()+i+1].count('\n')
                        break

            method_length = method_end - method_start + 1
            if method_length > self.config['max_method_length']:
                issues.append({
                    'file': filepath,
                    'method': method_name,
                    'line': method_start + 1,
                    'type': 'length',
                    'message': f'Method too long ({method_length} lines)'
                })

            method_content = content[match.start():match.end() + i + 1]
            complexity = self.calculate_complexity_braces(method_content, ext)
            if complexity > self.config['max_cyclomatic_complexity']:
                issues.append({
                    'file': filepath,
                    'method': method_name,
                    'line': method_start + 1,
                    'type': 'complexity',
                    'message': f'Method too complex (score: {complexity})'
                })

        return issues

    def calculate_complexity(self, method_lines):
        complexity = 1  # Base complexity

        decision_patterns = [
            r'\bif\b',
            r'\belif\b',
            r'\bfor\b',
            r'\bwhile\b',
            r'\bcatch\b',
            r'\band\b',
            r'\bor\b',
            r'\breturn .+\?',  # Ternary operators
        ]

        for line in method_lines:
            for pattern in decision_patterns:
                complexity += len(re.findall(pattern, line))

        return complexity

    def calculate_complexity_braces(self, method_content, ext):
        complexity = 1  # Base complexity

        # Common patterns for all languages
        decision_patterns = [
            r'\bif\b',
            r'\bfor\b',
            r'\bwhile\b',
            r'\bcatch\b',
            r'\bswitch\b',
            r'\b\?\b',  # Ternary operators
            r'\|\|',
            r'&&'
        ]

        # Language specific patterns
        if ext == '.js':
            decision_patterns.extend([
                r'\belse if\b',
                r'\.forEach\b',
                r'\.map\b',
                r'\.filter\b',
                r'\.reduce\b'
            ])

        for pattern in decision_patterns:
            complexity += len(re.findall(pattern, method_content))

        # Count case statements in switch blocks
        complexity += len(re.findall(r'\bcase\b', method_content))

        return complexity

    def analyze_directory(self, directory):
