import os
import shutil
import hashlib
import json
import zipfile
import tarfile
import glob
from datetime import datetime

def create_package(package_name, package_dir):
    package_path = os.path.join(package_dir, package_name)
    os.makedirs(package_path, exist_ok=True)
    os.makedirs(os.path.join(package_path, 'include'), exist_ok=True)
    os.makedirs(os.path.join(package_path, 'lib'), exist_ok=True)
    os.makedirs(os.path.join(package_path, 'bin'), exist_ok=True)

    metadata = {
        "name": package_name,
        "created": datetime.now().isoformat(),
        "files": []
    }

    if os.path.exists('src'):
        for f in os.listdir('src'):
            src = os.path.join('src', f)
            if os.path.isfile(src):
                dst_dir = ''
                if f.endswith('.h') or f.endswith('.hpp'):
                    dst_dir = 'include'
                elif f.endswith('.so') or f.endswith('.a') or f.endswith('.dll') or f.endswith('.lib'):
                    dst_dir = 'lib'
                elif os.access(src, os.X_OK) or f.endswith('.exe'):
                    dst_dir = 'bin'

                if dst_dir:
                    dst = os.path.join(package_path, dst_dir, f)
                    shutil.copy2(src, dst)

                    with open(src, 'rb') as file:
                        file_hash = hashlib.sha256(file.read()).hexdigest()

                    metadata["files"].append({
                        "name": f,
                        "path": os.path.join(dst_dir, f),
                        "sha256": file_hash,
                        "size": os.path.getsize(src)
                    })

    with open(os.path.join(package_path, 'metadata.json'), 'w') as f:
        json.dump(metadata, f, indent=2)

def extract_package(package_archive, output_dir):
    os.makedirs(output_dir, exist_ok=True)

    if package_archive.endswith('.zip'):
        with zipfile.ZipFile(package_archive, 'r') as zip_ref:
            zip_ref.extractall(output_dir)
    elif package_archive.endswith('.tar.gz') or package_archive.endswith('.tgz'):
        with tarfile.open(package_archive, 'r:gz') as tar_ref:
            tar_ref.extractall(output_dir)
    else:
        raise ValueError("Unsupported archive format")

def archive_package(package_dir, output_file):
    if output_file.endswith('.zip'):
        with zipfile.ZipFile(output_file, 'w', zipfile.ZIP_DEFLATED) as zipf:
            for root, _, files in os.walk(package_dir):
                for file in files:
                    file_path = os.path.join(root, file)
                    arcname = os.path.relpath(file_path, os.path.dirname(package_dir))
                    zipf.write(file_path, arcname)
    elif output_file.endswith('.tar.gz') or output_file.endswith('.tgz'):
        with tarfile.open(output_file, "w:gz") as tar:
            tar.add(package_dir, arcname=os.path.basename(package_dir))
    else:
        raise ValueError("Unsupported archive format")

def list_binaries(package_dir):
    bin_dir = os.path.join(package_dir, 'bin')
    lib_dir = os.path.join(package_dir, 'lib')

    binaries = []

    if os.path.exists(bin_dir):
        binaries.extend(glob.glob(os.path.join(bin_dir, '*')))

    if os.path.exists(lib_dir):
        binaries.extend(glob.glob(os.path.join(lib_dir, '*')))

    return binaries

def verify_package(package_dir):
    metadata_path = os.path.join(package_dir, 'metadata.json')

    if not os.path.exists(metadata_path):
        return False, "Metadata file not found"

    with open(metadata_path, 'r') as f:
        metadata = json.load(f)

    for file_info in metadata["files"]:
        file_path = os.path.join(package_dir, file_info["path"])

        if not os.path.exists(file_path):
            return False, f"File not found: {file_info['path']}"

        with open(file_path, 'rb') as file:
            file_hash = hashlib.sha256(file.read()).hexdigest()

        if file_hash != file_info["sha256"]:
            return False, f"Hash mismatch for {file_info['path']}"

    return True, "Package verified successfully"

