    try:
        analysis_results = analyze_dxf(filepath)
        return jsonify(analysis_results)
    except Exception as e:
        return jsonify({"error": str(e)})

def analyze_dxf(filepath):
    doc = ezdxf.readfile(filepath)
    msp = doc.modelspace()

    entities = {
        'lines': 0,
        'circles': 0,
        'arcs': 0,
        'polylines': 0,
        'other': 0
    }

    total_length = 0
    areas = []

    for entity in msp:
        entity_type = entity.dxftype()

        if entity_type == 'LINE':
            entities['lines'] += 1
            start = entity.dxf.start
            end = entity.dxf.end
            length = np.sqrt((end[0] - start[0])**2 + (end[1] - start[1])**2 + (end[2] - start[2])**2)
            total_length += length

        elif entity_type == 'CIRCLE':
            entities['circles'] += 1
            radius = entity.dxf.radius
            area = np.pi * radius**2
            areas.append(area)
            total_length += 2 * np.pi * radius

        elif entity_type == 'ARC':
            entities['arcs'] += 1
            radius = entity.dxf.radius
            start_angle = np.radians(entity.dxf.start_angle)
            end_angle = np.radians(entity.dxf.end_angle)
            angle = end_angle - start_angle
            if angle < 0:
                angle += 2 * np.pi
            total_length += radius * angle

        elif entity_type in ('LWPOLYLINE', 'POLYLINE'):
            entities['polylines'] += 1
            points = list(entity.vertices())
            if len(points) > 2:
                for i in range(len(points) - 1):
                    p1 = points[i]
                    p2 = points[i + 1]
                    try:
                        length = np.sqrt((p2[0] - p1[0])**2 + (p2[1] - p1[1])**2)
                        total_length += length
                    except:
                        pass

                if entity.closed:
                    p1 = points[-1]
                    p2 = points[0]
                    try:
                        length = np.sqrt((p2[0] - p1[0])**2 + (p2[1] - p1[1])**2)
                        total_length += length
                    except:
                        pass
        else:
            entities['other'] += 1

    return {
        'entity_count': entities,
        'total_entities': sum(entities.values()),
        'total_length': round(total_length, 2),
        'total_area': round(sum(areas), 2) if areas else 0,
        'bounding_box': get_bounding_box(msp)
    }

def get_bounding_box(modelspace):
    min_x, min_y, max_x, max_y = float('inf'), float('inf'), float('-inf'), float('-inf')

    for entity in modelspace:
        if hasattr(entity, 'bbox'):
            bbox = entity.bbox()
            if bbox:
                min_x = min(min_x, bbox.extmin[0])
                min_y = min(min_y, bbox.extmin[1])
                max_x = max(max_x, bbox.extmax[0])
                max_y = max(max_y, bbox.extmax[1])

    if min_x == float('inf'):
        return {'width': 0, 'height': 0}

    return {
        'width': round(max_x - min_x, 2),
        'height': round(max_y - min_y, 2),
        'min_x': round(min_x, 2),
        'min_y': round(min_y, 2),
        'max_x': round(max_x, 2),
        'max_y': round(max_y, 2)
    }

