def register():
    if request.method == 'POST':
        username = request.form['username']
        email = request.form['email']
        password = request.form['password']

        if User.query.filter_by(username=username).first() or User.query.filter_by(email=email).first():
            flash('Username or email already exists')
            return redirect(url_for('register'))

        user = User(username=username, email=email)
        user.set_password(password)
        db.session.add(user)
        db.session.commit()

        flash('Registration successful, please login')
        return redirect(url_for('login'))

    return render_template('register.html')

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        user = User.query.filter_by(username=username).first()

        if user and user.check_password(password):
            session['user_id'] = user.id
            return redirect(url_for('index'))

        flash('Invalid username or password')

    return render_template('login.html')

@app.route('/logout')
def logout():
    session.pop('user_id', None)
    return redirect(url_for('index'))

@app.route('/offer-ride', methods=['GET', 'POST'])
def offer_ride():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    if request.method == 'POST':
        origin = request.form['origin']
        destination = request.form['destination']
        date_str = request.form['date']
        available_seats = int(request.form['available_seats'])

        date = datetime.strptime(date_str, '%Y-%m-%dT%H:%M')

        ride = Ride(
            origin=origin,
            destination=destination,
            date=date,
            available_seats=available_seats,
            driver_id=session['user_id']
        )

        db.session.add(ride)
        db.session.commit()

        flash('Ride offered successfully')
        return redirect(url_for('my_rides'))

    return render_template('offer_ride.html')

@app.route('/book-ride/<int:ride_id>', methods=['POST'])
def book_ride(ride_id):
    if 'user_id' not in session:
        return redirect(url_for('login'))

    ride = Ride.query.get_or_404(ride_id)

    if ride.driver_id == session['user_id']:
        flash("You can't book your own ride")
        return redirect(url_for('index'))

    if ride.available_seats <= 0:
        flash('No available seats')
        return redirect(url_for('index'))

    existing_booking = Booking.query.filter_by(
        ride_id=ride_id, passenger_id=session['user_id']).first()

    if existing_booking:
        flash('You have already booked this ride')
    else:
        booking = Booking(ride_id=ride_id, passenger_id=session['user_id'])
        ride.available_seats -= 1
        db.session.add(booking)
        db.session.commit()
        flash('Ride booked successfully')

    return redirect(url_for('my_bookings'))

@app.route('/my-rides')
def my_rides():
    if 'user_id' not in session:
