    def __init__(self, compressed_root, mount_point, idle_timeout=300):
        self.compressed_root = os.path.realpath(compressed_root)
        self.mount_point = os.path.realpath(mount_point)
        self.tmpfs_dir = tempfile.mkdtemp(prefix="compressedfs_")
        self.idle_timeout = idle_timeout
        self.file_locks = {}
        self.file_timestamps = {}
        self.lock = threading.RLock()
        self.compression_thread = threading.Thread(target=self._compression_worker)
        self.compression_thread.daemon = True
        self.running = True
        self.compression_thread.start()
        logging.info(f"CompressedFS initialized: {compressed_root} -> {mount_point} (tmpfs: {self.tmpfs_dir})")

    def _compression_worker(self):
        while self.running:
            time.sleep(10)
            with self.lock:
                current_time = time.time()
                for path, last_access in list(self.file_timestamps.items()):
                    if current_time - last_access > self.idle_timeout:
                        if path not in self.file_locks or not self.file_locks[path]:
                            self._compress_file(path)
                            if path in self.file_timestamps:
                                del self.file_timestamps[path]

    def _compress_file(self, path):
        rel_path = os.path.relpath(path, self.tmpfs_dir)
        compressed_path = os.path.join(self.compressed_root, rel_path)

        if not os.path.exists(path):
            return

        logging.info(f"Compressing {path} to {compressed_path}")

        if not os.path.exists(os.path.dirname(compressed_path)):
            os.makedirs(os.path.dirname(compressed_path), exist_ok=True)

        with open(path, 'rb') as f_in:
            data = f_in.read()

        compressed_data = zlib.compress(data)

        with open(compressed_path, 'wb') as f_out:
            f_out.write(compressed_data)

        os.chmod(compressed_path, os.stat(path).st_mode)

        os.unlink(path)

    def _decompress_file(self, path):
        rel_path = os.path.relpath(path, self.tmpfs_dir)
        compressed_path = os.path.join(self.compressed_root, rel_path)

        if not os.path.exists(compressed_path):
            raise FuseOSError(os.errno.ENOENT)

        logging.info(f"Decompressing {compressed_path} to {path}")

        if not os.path.exists(os.path.dirname(path)):
            os.makedirs(os.path.dirname(path), exist_ok=True)

        with open(compressed_path, 'rb') as f_in:
            compressed_data = f_in.read()

        data = zlib.decompress(compressed_data)

        with open(path, 'wb') as f_out:
            f_out.write(data)

        os.chmod(path, os.stat(compressed_path).st_mode)

        with self.lock:
            self.file_timestamps[path] = time.time()

    def _get_tmpfs_path(self, path):
        return os.path.join(self.tmpfs_dir, os.path.relpath(path, self.mount_point))

    def _get_compressed_path(self, path):
        return os.path.join(self.compressed_root, os.path.relpath(path, self.mount_point))

    def _ensure_file_decompressed(self, path):
        tmpfs_path = self._get_tmpfs_path(path)
