    `<pre><code class="language-${language}">${code}</code></pre>`,
  inlineCode: code => `<code>${code}</code>`,
  list: (items, ordered = false) => {
    const tag = ordered ? 'ol' : 'ul';
    const listItems = items.map(item => `<li>${item}</li>`).join('');
    return `<${tag}>${listItems}</${tag}>`;
  },
  table: (headers, rows) => {
    const headerRow = `<tr>${headers.map(h => `<th>${h}</th>`).join('')}</tr>`;
    const bodyRows = rows.map(row => 
      `<tr>${row.map(cell => `<td>${cell}</td>`).join('')}</tr>`
    ).join('');
    return `<table><thead>${headerRow}</thead><tbody>${bodyRows}</tbody></table>`;
  }
};

// Markdown parser (simplified)
function parseMarkdown(markdown) {
  let html = markdown;

  // Headers
  html = html.replace(/^# (.+)$/gm, '<h1>$1</h1>');
  html = html.replace(/^## (.+)$/gm, '<h2>$1</h2>');
  html = html.replace(/^### (.+)$/gm, '<h3>$1</h3>');

  // Bold and Italic
  html = html.replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>');
  html = html.replace(/\*(.+?)\*/g, '<em>$1</em>');

  // Code blocks
  html = html.replace(/```(.+?)```/gs, '<pre><code>$1</code></pre>');
  html = html.replace(/`(.+?)`/g, '<code>$1</code>');

  // Links and images
  html = html.replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2">$1</a>');
  html = html.replace(/!\[(.+?)\]\((.+?)\)/g, '<img src="$2" alt="$1">');

  // Lists (simplified)
  html = html.replace(/^\* (.+)$/gm, '<li>$1</li>');
  html = html.replace(/(<li>.+<\/li>\n)+/g, '<ul>$&</ul>');

  // Paragraphs (simplified)
  html = html.replace(/^(?!<[hou]).+$/gm, '<p>$&</p>');

  return html;
}

// Search functionality
function searchIndex(articles) {
  const index = {};

  articles.forEach(article => {
    const words = [...article.title.toLowerCase().split(/\W+/), 
                  ...article.content.toLowerCase().split(/\W+/),
                  ...article.tags];

    words.forEach(word => {
      if (word.length < 2) return;

      if (!index[word]) {
        index[word] = new Set();
      }
      index[word].add(article.id);
    });
  });

  return index;
}

function searchByKeyword(keyword, index, articles) {
  const key = keyword.toLowerCase();
  const matchingIds = index[key] || new Set();
  return Array.from(matchingIds).map(id => 
    articles.find(article => article.id === id)
  );
}
