import os
import subprocess
import time

def run_command(command):
    process = subprocess.Popen(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, shell=True)
    stdout, stderr = process.communicate()
    return process.returncode, stdout.decode('utf-8'), stderr.decode('utf-8')

def checkout_code(repository_url, branch="main", directory="./code"):
    if os.path.exists(directory):
        print(f"Cleaning directory: {directory}")
        os.system(f"rm -rf {directory}")

    os.makedirs(directory, exist_ok=True)

    print(f"Cloning repository: {repository_url}, branch: {branch}")
    return run_command(f"git clone --branch {branch} {repository_url} {directory}")

def build_application(directory="./code"):
    os.chdir(directory)

    print("Building application")
    return run_command("pip install -r requirements.txt")

def run_tests(directory="./code"):
    os.chdir(directory)

    print("Running tests")
    return run_command("pytest")

def deploy_application(directory="./code"):
    os.chdir(directory)

    print("Deploying application")
    return run_command("./deploy.sh")

def main():
    repository_url = os.environ.get("REPOSITORY_URL")
    branch = os.environ.get("BRANCH", "main")

    if not repository_url:
        print("Error: REPOSITORY_URL environment variable is required")
        return 1

    # Checkout code
    status, stdout, stderr = checkout_code(repository_url, branch)
    if status != 0:
        print(f"Error checking out code: {stderr}")
        return status

    # Build application
    status, stdout, stderr = build_application()
    if status != 0:
        print(f"Error building application: {stderr}")
        return status

    # Run tests
    status, stdout, stderr = run_tests()
    if status != 0:
        print(f"Error running tests: {stderr}")
        return status

    # Deploy application
    status, stdout, stderr = deploy_application()
    if status != 0:
        print(f"Error deploying application: {stderr}")
        return status

    print("CI/CD pipeline completed successfully")
    return 0

if __name__ == "__main__":
    exit(main())
