import requests
from urllib.parse import urlparse

def trace_redirects(url, max_redirects=10):
    visited = set()
    redirect_chain = []

    current_url = url
    for _ in range(max_redirects):
        if current_url in visited:
            redirect_chain.append(f"{current_url} (Redirect loop detected)")
            break

        visited.add(current_url)
        redirect_chain.append(current_url)

        try:
            response = requests.head(current_url, allow_redirects=False, timeout=5)

            if 300 <= response.status_code < 400:
                if 'location' in response.headers:
                    next_url = response.headers['location']

                    # Handle relative URLs
                    if not urlparse(next_url).netloc:
                        parsed_current = urlparse(current_url)
                        scheme = f"{parsed_current.scheme}://"
                        netloc = parsed_current.netloc
                        if next_url.startswith('/'):
                            next_url = f"{scheme}{netloc}{next_url}"
                        else:
                            path = '/'.join(parsed_current.path.split('/')[:-1])
                            next_url = f"{scheme}{netloc}{path}/{next_url}"

                    current_url = next_url
                else:
                    redirect_chain.append(f"Redirect without location header (status {response.status_code})")
                    break
            else:
                redirect_chain.append(f"Final destination (status {response.status_code})")
                break

        except requests.RequestException as e:
            redirect_chain.append(f"Error: {str(e)}")
            break

    return redirect_chain

if __name__ == "__main__":
    url = input("Enter URL to trace: ")
    chain = trace_redirects(url)

    print("\nRedirect chain:")
    for i, step in enumerate(chain):
        print(f"{i+1}. {step}")
        if i < len(chain) - 1:
            print("   ↓")
