from flask import Flask, request, jsonify
import yaml
import json
import os
import uuid
import time

app = Flask(__name__)

RECORDINGS_DIR = "recordings"
os.makedirs(RECORDINGS_DIR, exist_ok=True)

@app.route('/mock', methods=['POST'])
def mock():
    data = request.data
    loaded = json.loads(data)

    if loaded.get('action') == 'record':
        session_id = str(uuid.uuid4())
        recording = {
            'session_id': session_id,
            'requests': []
        }
        with open(f"{RECORDINGS_DIR}/{session_id}.yaml", 'w') as f:
            yaml.dump(recording, f)
        return jsonify({'session_id': session_id})

    elif loaded.get('action') == 'capture':
        session_id = loaded.get('session_id')
        if not session_id:
            return jsonify({'error': 'session_id required'}), 400

        recording_path = f"{RECORDINGS_DIR}/{session_id}.yaml"
        if not os.path.exists(recording_path):
            return jsonify({'error': 'session not found'}), 404

        with open(recording_path, 'r') as f:
            recording = yaml.safe_load(f)

        request_data = {
            'url': loaded.get('url'),
            'method': loaded.get('method'),
            'headers': loaded.get('headers'),
            'body': loaded.get('body'),
            'response': loaded.get('response'),
            'timestamp': time.time()
        }

        recording['requests'].append(request_data)

        with open(recording_path, 'w') as f:
            yaml.dump(recording, f)

        return jsonify({'status': 'captured'})

    elif loaded.get('action') == 'replay':
        session_id = loaded.get('session_id')
        url = loaded.get('url')
        method = loaded.get('method')

        if not session_id:
            return jsonify({'error': 'session_id required'}), 400

        recording_path = f"{RECORDINGS_DIR}/{session_id}.yaml"
        if not os.path.exists(recording_path):
            return jsonify({'error': 'session not found'}), 404

        with open(recording_path, 'r') as f:
            recording = yaml.safe_load(f)

        for req in recording['requests']:
            if req['url'] == url and req['method'] == method:
                return jsonify(req['response'])

        return jsonify({'error': 'no matching request found'}), 404

    else:
        return jsonify({'error': 'unknown action'}), 400

if __name__ == '__main__':
    app.run()
