import json
from datetime import datetime

class ServerMonitor:
    def __init__(self, servers=None, cpu_threshold=80, memory_threshold=80, log_file='measurements.txt'):
        self.servers = servers or [socket.gethostname()]
        self.cpu_threshold = cpu_threshold
        self.memory_threshold = memory_threshold
        self.log_file = log_file
        self.permissions = {
            'owner': 'rw',
            'group': 'r',
            'others': ''
        }

    def check_server(self, server):
        anomalies = {}

        if server == socket.gethostname():
            cpu_percent = psutil.cpu_percent(interval=1)
            memory_percent = psutil.virtual_memory().percent

            if cpu_percent > self.cpu_threshold:
                anomalies['cpu'] = cpu_percent

            if memory_percent > self.memory_threshold:
                anomalies['memory'] = memory_percent

        else:
            try:
                # In a real implementation, you would use SSH or an API to get remote server metrics
                pass
            except Exception as e:
                anomalies['error'] = str(e)

        return anomalies

    def run(self):
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        results = {}

        for server in self.servers:
            anomalies = self.check_server(server)
            if anomalies:
                results[server] = anomalies

        if results:
            self.save_results(timestamp, results)

    def save_results(self, timestamp, results):
        log_entry = {
            'timestamp': timestamp,
            'anomalies': results
        }

        with open(self.log_file, 'a') as f:
            f.write(json.dumps(log_entry) + '\n')

        self.set_permissions()

    def set_permissions(self):
        mode = 0

        if 'r' in self.permissions['owner']:
            mode |= 0o400
        if 'w' in self.permissions['owner']:
            mode |= 0o200
        if 'x' in self.permissions['owner']:
            mode |= 0o100

        if 'r' in self.permissions['group']:
            mode |= 0o040
        if 'w' in self.permissions['group']:
            mode |= 0o020
        if 'x' in self.permissions['group']:
            mode |= 0o010

        if 'r' in self.permissions['others']:
            mode |= 0o004
        if 'w' in self.permissions['others']:
            mode |= 0o002
        if 'x' in self.permissions['others']:
            mode |= 0o001

        os.chmod(self.log_file, mode)

    def configure_permissions(self, owner_perms='rw', group_perms='r', others_perms=''):
        self.permissions = {
            'owner': owner_perms,
            'group': group_perms,
            'others': others_perms
        }
        self.set_permissions()

log_file = 'measurements.txt'
monitor = ServerMonitor(log_file=log_file, cpu_threshold=75, memory_threshold=80)
monitor.configure_permissions(owner_perms='rw', group_perms='r', others_perms='')
monitor.run()

with open(log_file, 'a') as f:
