import json
import os
from datetime import datetime

class GiftRegistry:
    def __init__(self, file_path="gift_registry.json"):
        self.file_path = file_path
        self.registry = self._load_registry()

    def _load_registry(self):
        if os.path.exists(self.file_path):
            try:
                with open(self.file_path, 'r') as file:
                    return json.load(file)
            except json.JSONDecodeError:
                return {}
        return {}

    def _save_registry(self):
        with open(self.file_path, 'w') as file:
            json.dump(self.registry, file, indent=4)

    def add_gift_idea(self, family_member, gift_idea, price=None):
        if family_member not in self.registry:
            self.registry[family_member] = []

        gift_entry = {
            "idea": gift_idea,
            "price": price,
            "date_added": datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        }

        self.registry[family_member].append(gift_entry)
        self._save_registry()
        return f"Gift idea added for {family_member}"

    def view_gift_ideas(self, family_member=None):
        if family_member:
            if family_member in self.registry:
                return {family_member: self.registry[family_member]}
            return f"No gift ideas found for {family_member}"
        return self.registry

    def list_family_members(self):
        return list(self.registry.keys())

def main():
    registry = GiftRegistry()

    while True:
        print("\nFamily Gift Registry")
        print("1. Add a gift idea")
        print("2. View gift ideas for a family member")
        print("3. View all gift ideas")
        print("4. List all family members")
        print("5. Exit")

        choice = input("Enter your choice (1-5): ")

        if choice == "1":
            member = input("Enter family member name: ")
            idea = input("Enter gift idea: ")
            price = input("Enter price (optional): ")
            price = float(price) if price else None
            print(registry.add_gift_idea(member, idea, price))

        elif choice == "2":
            member = input("Enter family member name: ")
            ideas = registry.view_gift_ideas(member)
            print(json.dumps(ideas, indent=4))

        elif choice == "3":
            ideas = registry.view_gift_ideas()
            print(json.dumps(ideas, indent=4))

        elif choice == "4":
            members = registry.list_family_members()
            print("Family members:")
            for member in members:
                print(f"- {member}")

        elif choice == "5":
            print("Goodbye!")
            break

        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
