from flask import Flask, render_template, request, redirect, url_for, flash, session
import sqlite3
from werkzeug.security import generate_password_hash, check_password_hash
import os

app = Flask(__name__)
app.secret_key = os.urandom(24)

def get_db_connection():
    conn = sqlite3.connect('database.db')
    conn.row_factory = sqlite3.Row
    return conn

def init_db():
    conn = get_db_connection()
    conn.execute('''
    CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password TEXT NOT NULL
    )
    ''')
    conn.execute('''
    CREATE TABLE IF NOT EXISTS connected_apps (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        user_id INTEGER NOT NULL,
        app_name TEXT NOT NULL,
        app_token TEXT NOT NULL,
        date_connected TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
        FOREIGN KEY (user_id) REFERENCES users (id)
    )
    ''')
    conn.commit()
    conn.close()

init_db()

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        conn = get_db_connection()
        user = conn.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()
        conn.close()

        if user and check_password_hash(user['password'], password):
            session['user_id'] = user['id']
            return redirect(url_for('connected_apps'))

        flash('Invalid username or password')

    return render_template('login.html')

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        conn = get_db_connection()
        if conn.execute('SELECT id FROM users WHERE username = ?', (username,)).fetchone():
            flash('Username already exists')
            conn.close()
            return render_template('register.html')

        conn.execute('INSERT INTO users (username, password) VALUES (?, ?)',
                    (username, generate_password_hash(password)))
        conn.commit()
        conn.close()

        flash('Registration successful. Please log in.')
        return redirect(url_for('login'))

    return render_template('register.html')

@app.route('/connected-apps')
def connected_apps():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    conn = get_db_connection()
    apps = conn.execute('SELECT * FROM connected_apps WHERE user_id = ?', 
                        (session['user_id'],)).fetchall()
    conn.close()

    return render_template('connected_apps.html', apps=apps)

@app.route('/add-app', methods=['GET', 'POST'])
def add_app():
    if 'user_id' not in session:
        return redirect(url_for('login'))

    if request.method == 'POST':
        app_name = request.form['app_name']
        app_token = request.form['app_token']

        conn = get_db_connection()
        conn.execute('INSERT INTO connected_apps (user_id, app_name, app_token) VALUES (?, ?, ?)',
                    (session['user_id'], app_name, app_token))
        conn.commit()
        conn.close()

        flash('App successfully connected')
        return redirect(url_for('connected_apps'))

    return render_template('add_app.html')

