import json
import os
from typing import Dict, Any, List, Optional

class JSONSchemaAPIDocGenerator:
    def __init__(self, schema_path: str, output_dir: str):
        self.schema_path = schema_path
        self.output_dir = output_dir
        self.schema = self._load_schema()

    def _load_schema(self) -> Dict[str, Any]:
        with open(self.schema_path, 'r') as f:
            return json.load(f)

    def generate_docs(self) -> None:
        os.makedirs(self.output_dir, exist_ok=True)

        title = self.schema.get('title', 'API Documentation')
        description = self.schema.get('description', '')

        html = f"""
        <!DOCTYPE html>
        <html>
        <head>
            <title>{title}</title>
            <style>
                body {{ font-family: Arial, sans-serif; margin: 20px; }}
                .endpoint {{ margin-bottom: 30px; border-bottom: 1px solid #eee; padding-bottom: 20px; }}
                .method {{ font-weight: bold; color: #333; }}
                .path {{ font-family: monospace; }}
                .params {{ margin-left: 20px; }}
                .param {{ margin-bottom: 10px; }}
                .required {{ color: red; }}
                .type {{ color: #6c757d; }}
                .description {{ margin-top: 10px; }}
            </style>
        </head>
        <body>
            <h1>{title}</h1>
            <p>{description}</p>

            <h2>Endpoints</h2>
            {self._generate_endpoints_html()}

            <h2>Schemas</h2>
            {self._generate_schemas_html()}
        </body>
        </html>
        """

        with open(os.path.join(self.output_dir, 'index.html'), 'w') as f:
            f.write(html)

    def _generate_endpoints_html(self) -> str:
        if 'paths' not in self.schema:
            return "<p>No endpoints defined.</p>"

        html = ""
        for path, methods in self.schema.get('paths', {}).items():
            for method, details in methods.items():
                html += f"""
                <div class="endpoint">
                    <h3><span class="method">{method.upper()}</span> <span class="path">{path}</span></h3>
                    <div class="description">{details.get('description', '')}</div>

                    <h4>Parameters</h4>
                    {self._generate_params_html(details.get('parameters', []))}

                    <h4>Responses</h4>
                    {self._generate_responses_html(details.get('responses', {}))}
                </div>
                """
        return html

    def _generate_params_html(self, parameters: List[Dict[str, Any]]) -> str:
        if not parameters:
            return "<p>No parameters required.</p>"

        html = "<div class='params'>"
        for param in parameters:
            required = "<span class='required'>*</span>" if param.get('required', False) else ""
            html += f"""
            <div class="param">
                <strong>{param.get('name', '')}</strong> {required}
                <span class="type">({param.get('in', '')} - {param.get('type', 'object')})</span>
                <div class="description">{param.get('description', '')}</div>
            </div>
            """
        html += "</div>"
        return html

    def _generate_responses_html(self, responses: Dict[str, Any]) -> str:
        if not responses:
            return "<p>No responses documented.</p>"

        html = "<div class='responses'>"
        for status, details in responses.items():
            html += f"""
            <div class="response">
                <strong>{status}</strong>: {details.get('description', '')}
            </div>
            """
        html += "</div>"
        return html

    def _generate_schemas_html(self) -> str:
        if 'definitions' not in self.schema and 'components' not in self.schema:
            return "<p>No schemas defined.</p>"

        definitions = self.schema.get('definitions', {})
        if not definitions:
            definitions = self.schema.get('components', {}).get('schemas', {})

        if not definitions:
            return "<p>No schemas defined.</p>"

        html = ""
        for name, schema in definitions.items():
            html += f"""
            <div class="schema">
                <h3>{name}</h3>
                <div class="description">{schema.get('description', '')}</div>
                <h4>Properties</h4>
                {self._generate_properties_html(schema.get('properties', {}))}
            </div>
            """
        return html

    def _generate_properties_html(self, properties: Dict[str, Any]) -> str:
        if not properties:
            return "<p>No properties defined.</p>"

        html = "<table border='1' cellpadding='5'>"
        html += "<tr><th>Property</th><th>Type</th><th>Description</th></tr>"

        for name, details in properties.items():
            html += f"""
            <tr>
                <td>{name}</td>
                <td>{details.get('type', 'object')}</td>
                <td>{details.get('description', '')}</td>
            </tr>
            """
        html += "</table>"
        return html

if __name__ == "__main__":
    generator = JSONSchemaAPIDocGenerator("api_schema.json", "api_docs")
    generator.generate_docs()
