import os
import tarfile
import tempfile
import curses
import sys

class TarBrowser:
    def __init__(self, tar_path):
        self.tar_path = tar_path
        self.temp_dir = tempfile.mkdtemp()
        self.current_dir = self.temp_dir
        self.extract_tarball()
        self.file_list = []
        self.selected_idx = 0
        self.scroll_offset = 0
        self.view_content = False
        self.content_lines = []
        self.content_scroll = 0
        self.refresh_file_list()

    def extract_tarball(self):
        with tarfile.open(self.tar_path, 'r:*') as tar:
            tar.extractall(path=self.temp_dir)

    def refresh_file_list(self):
        self.file_list = []
        self.file_list.append(('..',))
        for item in os.listdir(self.current_dir):
            item_path = os.path.join(self.current_dir, item)
            is_dir = os.path.isdir(item_path)
            self.file_list.append((item, is_dir))

    def handle_input(self, key):
        if self.view_content:
            return self.handle_content_view(key)
        else:
            return self.handle_file_list(key)

    def handle_content_view(self, key):
        if key == curses.KEY_UP:
            self.content_scroll = max(0, self.content_scroll - 1)
        elif key == curses.KEY_DOWN:
            self.content_scroll += 1
        elif key == ord('q'):
            self.view_content = False
            self.content_lines = []
            self.content_scroll = 0
        return True

    def handle_file_list(self, key):
        if key == curses.KEY_UP:
            self.selected_idx = max(0, self.selected_idx - 1)
        elif key == curses.KEY_DOWN:
            self.selected_idx = min(len(self.file_list) - 1, self.selected_idx + 1)
        elif key == ord('\n'):
            if self.selected_idx == 0:
                parent_dir = os.path.dirname(self.current_dir)
                if self.temp_dir in parent_dir:
                    self.current_dir = parent_dir
                    self.refresh_file_list()
                    self.selected_idx = 0
                    self.scroll_offset = 0
            else:
                selected = self.file_list[self.selected_idx]
                path = os.path.join(self.current_dir, selected[0])
                if len(selected) > 1 and selected[1]:
                    self.current_dir = path
                    self.refresh_file_list()
                    self.selected_idx = 0
                    self.scroll_offset = 0
                else:
                    self.view_file(path)
        elif key == ord('q'):
            return False
        return True

    def view_file(self, path):
        try:
            with open(path, 'r') as f:
                self.content_lines = f.read().splitlines()
                self.view_content = True
                self.content_scroll = 0
        except UnicodeDecodeError:
            pass

    def cleanup(self):
        import shutil
        shutil.rmtree(self.temp_dir)

    def draw(self, stdscr):
        stdscr.clear()
        height, width = stdscr.getmaxyx()

        if self.view_content:
            self.draw_content(stdscr, height, width)
        else:
            self.draw_file_list(stdscr, height, width)

        stdscr.refresh()

    def draw_content(self, stdscr, height, width):
        max_lines = height - 2

        stdscr.addstr(0, 0, "File Viewer (q to go back)", curses.A_REVERSE)

        for i in range(max_lines):
            line_idx = i + self.content_scroll
            if line_idx < len(self.content_lines):
                line = self.content_lines[line_idx]
                if len(line) > width - 1:
                    line = line[:width - 4] + "..."
                stdscr.addstr(i + 1, 0, line)

    def draw_file_list(self, stdscr, height, width):
        max_items = height - 2

        if self.selected_idx < self.scroll_offset:
            self.scroll_offset = self.selected_idx
        elif self.selected_idx >= self.scroll_offset + max_items:
            self.scroll_offset = self.selected_idx - max_items + 1

        rel_path = os.path.relpath(self.current_dir, self.temp_dir)
        header = f"TarBrowser: {self.tar_path} - {rel_path}"
        if len(header) > width - 1:
            header = header[:width - 4] + "..."
        stdscr.addstr(0, 0, header, curses.A_REVERSE)

        for i in range(max_items):
            idx = i + self.scroll_offset
            if idx < len(self.file_list):
                item = self.file_list[idx]
                name = item[0]
                if len(item) > 1 and item[1]:
                    name = f"[DIR] {name}/"

                if len(name) > width - 1:
                    name = name[:width - 4] + "..."

                if idx == self.selected_idx:
                    stdscr.addstr(i + 1, 0, name, curses.A_REVERSE)
                else:
                    stdscr.addstr(i + 1, 0, name)

def main(stdscr, tar_path):
    curses.curs_set(0)
    browser = TarBrowser(tar_path)

    while True:
        browser.draw(stdscr)
        key = stdscr.getch()
        if not browser.handle_input(key):
            break

    browser.cleanup()

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: tarbrowser.py <tarfile>")
        sys.exit(1)

    tar_path = sys.argv[1]
    if not os.path.isfile(tar_path):
        print(f"Error: {tar_path} is not a file")
        sys.exit(1)

    try:
        curses.wrapper(main, tar_path)
    except KeyboardInterrupt:
        print("Interrupted by user")
