import logging
from typing import Optional, List, Tuple

class FFmpegWrapper:
    def __init__(self, ffmpeg_path: str = "ffmpeg", output_dir: str = "./downloads"):
        self.ffmpeg_path = ffmpeg_path
        self.output_dir = output_dir

        if not os.path.exists(output_dir):
            os.makedirs(output_dir)

        self.logger = logging.getLogger("FFmpegWrapper")

    def download_video(self, url: str, output_filename: str) -> Tuple[bool, str]:
        output_path = os.path.join(self.output_dir, output_filename)

        command = [
            self.ffmpeg_path,
            "-i", url,
            "-c", "copy",
            output_path
        ]

        try:
            subprocess.run(command, check=True, capture_output=True)
            return True, output_path
        except subprocess.CalledProcessError as e:
            self.logger.error(f"Download failed: {e.stderr.decode()}")
            return False, str(e.stderr.decode())

    def convert_format(self, input_path: str, output_format: str, 
                      video_codec: Optional[str] = None,
                      audio_codec: Optional[str] = None,
                      extra_args: Optional[List[str]] = None) -> Tuple[bool, str]:

        filename = os.path.basename(input_path)
        name, _ = os.path.splitext(filename)
        output_path = os.path.join(self.output_dir, f"{name}.{output_format}")

        command = [self.ffmpeg_path, "-i", input_path]

        if video_codec:
            command.extend(["-c:v", video_codec])

        if audio_codec:
            command.extend(["-c:a", audio_codec])

        if extra_args:
            command.extend(extra_args)

        command.append(output_path)

        try:
            subprocess.run(command, check=True, capture_output=True)
            return True, output_path
        except subprocess.CalledProcessError as e:
            self.logger.error(f"Conversion failed: {e.stderr.decode()}")
            return False, str(e.stderr.decode())

    def extract_audio(self, input_path: str, audio_format: str = "mp3", 
                    bitrate: str = "192k") -> Tuple[bool, str]:

        filename = os.path.basename(input_path)
        name, _ = os.path.splitext(filename)
        output_path = os.path.join(self.output_dir, f"{name}.{audio_format}")

        command = [
            self.ffmpeg_path,
            "-i", input_path,
            "-vn",
            "-ar", "44100",
            "-ac", "2",
            "-b:a", bitrate,
            output_path
        ]

        try:
            subprocess.run(command, check=True, capture_output=True)
            return True, output_path
        except subprocess.CalledProcessError as e:
            self.logger.error(f"Audio extraction failed: {e.stderr.decode()}")
            return False, str(e.stderr.decode())

    def trim_video(self, input_path: str, start_time: str, duration: Optional[str] = None,
                 output_format: str = None) -> Tuple[bool, str]:

        filename = os.path.basename(input_path)
        name, ext = os.path.splitext(filename)

        if not output_format:
            output_format = ext.lstrip('.')

        output_path = os.path.join(self.output_dir, f"{name}_trimmed.{output_format}")

        command = [
            self.ffmpeg_path,
            "-i", input_path,
            "-ss", start_time
        ]

        if duration:
            command.extend(["-t", duration])

        command.extend(["-c", "copy", output_path])

        try:
            subprocess.run(command, check=True, capture_output=True)
            return True, output_path
        except subprocess.CalledProcessError as e:
            self.logger.error(f"Trimming failed: {e.stderr.decode()}")
