import datetime

class CalorieCounter:
    def __init__(self):
        self.food_database = {}
        self.daily_intake = {}

    def add_food_to_database(self, name, calories_per_serving, serving_size="1 unit"):
        self.food_database[name.lower()] = {
            "calories_per_serving": calories_per_serving,
            "serving_size": serving_size
        }
        return f"{name} added to database"

    def log_food(self, name, servings=1.0):
        name = name.lower()
        if name not in self.food_database:
            return f"Food '{name}' not found in database"

        date = datetime.date.today().isoformat()
        if date not in self.daily_intake:
            self.daily_intake[date] = []

        calories = self.food_database[name]["calories_per_serving"] * servings
        self.daily_intake[date].append({
            "name": name,
            "servings": servings,
            "calories": calories,
            "time": datetime.datetime.now().strftime("%H:%M")
        })
        return f"{name} ({servings} servings) logged: {calories} calories"

    def get_daily_total(self, date=None):
        if date is None:
            date = datetime.date.today().isoformat()

        if date not in self.daily_intake:
            return 0

        return sum(entry["calories"] for entry in self.daily_intake[date])

    def get_daily_log(self, date=None):
        if date is None:
            date = datetime.date.today().isoformat()

        if date not in self.daily_intake:
            return []

        return self.daily_intake[date]


# Example usage
if __name__ == "__main__":
    counter = CalorieCounter()

    # Add foods to database
    counter.add_food_to_database("Apple", 95, "1 medium")
    counter.add_food_to_database("Chicken Breast", 165, "100g")
    counter.add_food_to_database("Brown Rice", 215, "1 cup cooked")

    # Log food intake
    print(counter.log_food("Apple"))
    print(counter.log_food("Chicken Breast", 1.5))
    print(counter.log_food("Brown Rice", 0.5))

    # Get daily totals
    total = counter.get_daily_total()
    print(f"Total calories today: {total}")

    # View today's log
    print("Today's food log:")
    for entry in counter.get_daily_log():
        print(f"{entry['time']} - {entry['name']} ({entry['servings']} servings): {entry['calories']} calories")
