#!/usr/bin/env python3
import tarfile
import os
import sys
import curses

def browse_tarball(stdscr, tar_path):
    curses.curs_set(0)
    curses.init_pair(1, curses.COLOR_WHITE, curses.COLOR_BLUE)

    with tarfile.open(tar_path, 'r') as tar:
        members = sorted(tar.getmembers(), key=lambda m: m.name)

        current_index = 0
        offset = 0

        while True:
            stdscr.clear()
            height, width = stdscr.getmaxyx()

            display_count = min(height - 2, len(members))

            if current_index >= offset + display_count:
                offset = current_index - display_count + 1
            elif current_index < offset:
                offset = current_index

            stdscr.addstr(0, 0, f"Browsing: {tar_path}", curses.A_BOLD)
            stdscr.addstr(height-1, 0, "q:Quit  Enter:View  e:Extract", curses.A_BOLD)

            for i in range(display_count):
                if offset + i >= len(members):
                    break

                member = members[offset + i]
                file_type = "D" if member.isdir() else "F"
                file_size = member.size if not member.isdir() else 0

                if offset + i == current_index:
                    stdscr.attron(curses.color_pair(1))
                    stdscr.addstr(i+1, 0, f"{file_type} {member.name} ({file_size} bytes)")
                    stdscr.attroff(curses.color_pair(1))
                else:
                    stdscr.addstr(i+1, 0, f"{file_type} {member.name} ({file_size} bytes)")

            key = stdscr.getch()

            if key == ord('q'):
                break
            elif key == curses.KEY_UP:
                current_index = max(0, current_index - 1)
            elif key == curses.KEY_DOWN:
                current_index = min(len(members) - 1, current_index + 1)
            elif key == ord('\n'):
                member = members[current_index]
                if not member.isdir():
                    view_file(stdscr, tar, member)
            elif key == ord('e'):
                extract_file(stdscr, tar, members[current_index])

def view_file(stdscr, tar, member):
    if member.size > 1024*1024:
        show_message(stdscr, "File too large to display")
        return

    try:
        content = tar.extractfile(member).read().decode('utf-8')
        show_content(stdscr, content, member.name)
    except UnicodeDecodeError:
        show_message(stdscr, "Binary file - cannot display")
    except Exception as e:
        show_message(stdscr, f"Error: {str(e)}")

def extract_file(stdscr, tar, member):
    height, width = stdscr.getmaxyx()
    stdscr.clear()

    curses.echo()
    curses.curs_set(1)

    stdscr.addstr(0, 0, "Extract to directory: ")
    extract_path = stdscr.getstr(0, 22).decode('utf-8')

    curses.noecho()
    curses.curs_set(0)

    if not extract_path:
        extract_path = "."

    try:
        tar.extract(member, extract_path)
        show_message(stdscr, f"Extracted to {extract_path}")
    except Exception as e:
        show_message(stdscr, f"Extraction failed: {str(e)}")

def show_content(stdscr, content, title):
    stdscr.clear()
    curses.curs_set(0)

    lines = content.split('\n')
    offset = 0

    while True:
        height, width = stdscr.getmaxyx()
        stdscr.clear()

        stdscr.addstr(0, 0, f"File: {title}", curses.A_BOLD)
        stdscr.addstr(height-1, 0, "q:Back  Up/Down:Scroll", curses.A_BOLD)

        display_count = height - 2

        for i in range(display_count):
            if offset + i >= len(lines):
                break

            line = lines[offset + i]
            if len(line) > width - 1:
                line = line[:width - 4] + "..."

            stdscr.addstr(i+1, 0, line)

        key = stdscr.getch()

        if key == ord('q'):
            break
        elif key == curses.KEY_UP:
            offset = max(0, offset - 1)
        elif key == curses.KEY_DOWN:
            offset = min(len(lines) - display_count, offset + 1)

def show_message(stdscr, message):
    height, width = stdscr.getmaxyx()
    message_win = curses.newwin(3, min(len(message) + 4, width), height//2-1, width//2-min(len(message) + 4, width)//2)
    message_win.box()
    message_win.addstr(1, 2, message[:width-4])
    message_win.refresh()
    message_win.getch()

def main():
    if len(sys.argv) != 2:
        print("Usage: tarball_browser.py <tarball_path>")
        sys.exit(1)

    tar_path = sys.argv[1]

    if not os.path.exists(tar_path):
        print(f"Error: File '{tar_path}' not found")
        sys.exit(1)

    try:
        curses.wrapper(browse_tarball, tar_path)
    except Exception as e:
        print(f"Error: {str(e)}")
        sys.exit(1)

if __name__ == "__main__":
    main()
