class NavigationApp {
  constructor() {
    this.currentLocation = null;
    this.destination = null;
    this.route = [];
    this.currentStep = 0;
  }

  initializeApp() {
    if (navigator.geolocation) {
      navigator.geolocation.watchPosition(
        position => this.updateCurrentLocation(position),
        error => console.error("Error getting location:", error),
        { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
      );
    }
  }

  updateCurrentLocation(position) {
    this.currentLocation = {
      lat: position.coords.latitude,
      lng: position.coords.longitude
    };

    if (this.destination && this.route.length > 0) {
      this.checkProgress();
    }
  }

  setDestination(destination) {
    this.destination = destination;
    this.calculateRoute();
  }

  calculateRoute() {
    fetch(`https://api.routing.com/directions?origin=${this.currentLocation.lat},${this.currentLocation.lng}&destination=${this.destination.lat},${this.destination.lng}`)
      .then(response => response.json())
      .then(data => {
        this.route = data.steps;
        this.currentStep = 0;
        this.announceNextDirection();
      })
      .catch(error => console.error("Error calculating route:", error));
  }

  checkProgress() {
    if (this.isNearNextStep()) {
      this.currentStep++;
      if (this.currentStep < this.route.length) {
        this.announceNextDirection();
      } else {
        this.announceArrival();
      }
    }
  }

  isNearNextStep() {
    if (this.currentStep >= this.route.length) return false;

    const nextStep = this.route[this.currentStep];
    const distance = this.calculateDistance(
      this.currentLocation.lat,
      this.currentLocation.lng,
      nextStep.lat,
      nextStep.lng
    );

    return distance < 20; // Within 20 meters
  }

  calculateDistance(lat1, lon1, lat2, lon2) {
    const R = 6371e3; // Earth radius in meters
    const φ1 = lat1 * Math.PI / 180;
    const φ2 = lat2 * Math.PI / 180;
    const Δφ = (lat2 - lat1) * Math.PI / 180;
    const Δλ = (lon2 - lon1) * Math.PI / 180;

    const a = Math.sin(Δφ/2) * Math.sin(Δφ/2) +
              Math.cos(φ1) * Math.cos(φ2) *
              Math.sin(Δλ/2) * Math.sin(Δλ/2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));

    return R * c;
  }

