import time

class ServiceDiscovery:
    def __init__(self, host='0.0.0.0', port=5353):
        self.host = host
        self.port = port
        self.services = {}
        self.lock = threading.Lock()
        self.running = False
        self.server_socket = None

    def start(self):
        self.running = True
        self.server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.server_socket.bind((self.host, self.port))
        self.server_socket.listen(5)

        listener_thread = threading.Thread(target=self._listen_for_connections)
        listener_thread.daemon = True
        listener_thread.start()

        heartbeat_thread = threading.Thread(target=self._check_service_health)
        heartbeat_thread.daemon = True
        heartbeat_thread.start()

        print(f"Service discovery running on {self.host}:{self.port}")

    def stop(self):
        self.running = False
        if self.server_socket:
            self.server_socket.close()

    def _listen_for_connections(self):
        while self.running:
            try:
                client_socket, address = self.server_socket.accept()
                handler = threading.Thread(target=self._handle_client, args=(client_socket,))
                handler.daemon = True
                handler.start()
            except Exception as e:
                if self.running:
                    print(f"Error accepting connection: {e}")

    def _handle_client(self, client_socket):
        try:
            data = client_socket.recv(4096).decode('utf-8')
            if data:
                request = json.loads(data)
                action = request.get('action')

                if action == 'register':
                    response = self._register_service(request)
                elif action == 'unregister':
                    response = self._unregister_service(request)
                elif action == 'discover':
                    response = self._discover_services(request)
                elif action == 'heartbeat':
                    response = self._process_heartbeat(request)
                else:
                    response = {'status': 'error', 'message': 'Unknown action'}

                client_socket.send(json.dumps(response).encode('utf-8'))
        except Exception as e:
            print(f"Error handling client: {e}")
        finally:
            client_socket.close()

    def _register_service(self, request):
        service_name = request.get('name')
        service_address = request.get('address')
        service_port = request.get('port')

        if not all([service_name, service_address, service_port]):
            return {'status': 'error', 'message': 'Missing required fields'}

        with self.lock:
            service_id = f"{service_name}_{service_address}_{service_port}"
            self.services[service_id] = {
                'name': service_name,
                'address': service_address,
                'port': service_port,
                'last_heartbeat': time.time()
            }

        return {'status': 'success', 'message': 'Service registered', 'service_id': service_id}

    def _unregister_service(self, request):
        service_id = request.get('service_id')

        if not service_id:
            return {'status': 'error', 'message': 'Missing service_id'}

        with self.lock:
            if service_id in self.services:
                del self.services[service_id]
                return {'status': 'success', 'message': 'Service unregistered'}
            else:
                return {'status': 'error', 'message': 'Service not found'}

    def _discover_services(self, request):
        service_name = request.get('name')

        with self.lock:
            if service_name:
                found_services = [service for service_id, service in self.services.items() 
                               if service['name'] == service_name]
            else:
                found_services = list(self.services.values())

        return {'status': 'success', 'services': found_services}

    def _process_heartbeat(self, request):
        service_id = request.get('service_id')

        if not service_id:
            return {'status': 'error', 'message': 'Missing service_id'}

        with self.lock:
            if service_id in self.services:
                self.services[service_id]['last_heartbeat'] = time.time()
                return {'status': 'success', 'message': 'Heartbeat received'}
            else:
                return {'status': 'error', 'message': 'Service not found'}

    def _check_service_health(self):
        while self.running:
            time.sleep(10)
            current_time = time.time()
            with self.lock:
                expired_services = [service_id for service_id, service in self.services.items()
                                  if current_time - service['last_heartbeat'] > 30]

                for service_id in expired_services:
                    del self.services[service_id]
                    print(f"Service {service_id} expired and was removed")

class ServiceClient:
    def __init__(self, discovery_host='localhost', discovery_port=5353):
        self.discovery_host = discovery_host
        self.discovery_port = discovery_port

