import os
import shutil
import argparse
import zipfile
import time
import sys

def check_space(source_size, destination_path):
    dest_stat = os.statvfs(destination_path)
    free_space = dest_stat.f_frsize * dest_stat.f_bavail
    return free_space >= source_size

def get_size(path):
    total_size = 0
    for dirpath, dirnames, filenames in os.walk(path):
        for f in filenames:
            fp = os.path.join(dirpath, f)
            if not os.path.islink(fp):
                total_size += os.path.getsize(fp)
    return total_size

def extract_zip(zip_path, extract_to):
    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        zip_ref.extractall(extract_to)

def copy_files(source_path, destination_path, progress_callback=None):
    if os.path.isfile(source_path):
        shutil.copy2(source_path, destination_path)
        return

    total_size = get_size(source_path)
    copied_size = 0

    if not check_space(total_size, os.path.dirname(destination_path)):
        raise IOError("Not enough space on destination drive")

    if not os.path.exists(destination_path):
        os.makedirs(destination_path)

    for item in os.listdir(source_path):
        s = os.path.join(source_path, item)
        d = os.path.join(destination_path, item)

        if os.path.isdir(s):
            if not os.path.exists(d):
                os.makedirs(d)
            copied_size += copy_files(s, d, progress_callback)
        else:
            shutil.copy2(s, d)
            file_size = os.path.getsize(s)
            copied_size += file_size
            if progress_callback:
                progress_callback(copied_size, total_size)

    return copied_size

def progress_bar(current, total):
    percent = 100 * (current / total)
    bar = '█' * int(percent / 2) + '-' * (50 - int(percent / 2))
    sys.stdout.write(f'\r|{bar}| {percent:.2f}%')
    sys.stdout.flush()

def main():
    parser = argparse.ArgumentParser(description='Extract and copy data from Zip disks to modern storage')
    parser.add_argument('source', help='Source path (Zip disk mount point or zip file)')
    parser.add_argument('destination', help='Destination path')
    parser.add_argument('-z', '--zip', action='store_true', help='Source is a zip file')

    args = parser.parse_args()

    if not os.path.exists(args.source):
        print(f"Error: Source path {args.source} does not exist")
        return

    if args.zip:
        print(f"Extracting {args.source} to {args.destination}...")
        extract_zip(args.source, args.destination)
    else:
        print(f"Copying files from {args.source} to {args.destination}...")
        copy_files(args.source, args.destination, progress_bar)

    print("\nOperation completed successfully!")

if __name__ == "__main__":
    main()
