            self.daily_records[today] = []

        self.daily_records[today].append({"food": food_name, "calories": calories})
        print(f"Added {food_name} ({calories} calories)")

    def display_daily_summary(self, date=None):
        if date is None:
            date = datetime.date.today().isoformat()

        if date not in self.daily_records:
            print(f"No food records for {date}")
            return

        total_calories = 0
        print(f"\nFood diary for {date}:")
        print("-" * 30)

        for item in self.daily_records[date]:
            print(f"{item['food']}: {item['calories']} calories")
            total_calories += item['calories']

        print("-" * 30)
        print(f"Total calories: {total_calories}")

def main():
