import datetime
from decimal import Decimal

class Customer:
    def __init__(self, id, name, email, phone):
        self.id = id
        self.name = name
        self.email = email
        self.phone = phone
        self.purchase_history = []

class Product:
    def __init__(self, id, name, price, stock):
        self.id = id
        self.name = name
        self.price = Decimal(str(price))
        self.stock = stock

class SaleItem:
    def __init__(self, product, quantity):
        self.product = product
        self.quantity = quantity
        self.price = product.price
        self.subtotal = product.price * Decimal(str(quantity))

class Sale:
    def __init__(self, customer):
        self.id = datetime.datetime.now().strftime("%Y%m%d%H%M%S")
        self.customer = customer
        self.items = []
        self.timestamp = datetime.datetime.now()
        self.total = Decimal('0.00')

    def add_item(self, product, quantity):
        if product.stock >= quantity:
            item = SaleItem(product, quantity)
            self.items.append(item)
            self.total += item.subtotal
            product.stock -= quantity
            return True
        return False

    def finalize(self, payment_method):
        self.payment_method = payment_method
        self.customer.purchase_history.append(self)
        return self.generate_receipt()

    def generate_receipt(self):
        receipt = f"Receipt #{self.id}\nDate: {self.timestamp}\nCustomer: {self.customer.name}\n"
        receipt += "----------------------------------------\n"
        for item in self.items:
            receipt += f"{item.product.name} x {item.quantity}: ${item.subtotal}\n"
        receipt += "----------------------------------------\n"
        receipt += f"Total: ${self.total}\nPayment Method: {self.payment_method}\n"
        receipt += "Thank you for your purchase!"
        return receipt

class POS:
    def __init__(self):
        self.customers = {}
        self.products = {}
        self.sales = []

    def add_customer(self, id, name, email, phone):
        customer = Customer(id, name, email, phone)
        self.customers[id] = customer
        return customer

    def add_product(self, id, name, price, stock):
        product = Product(id, name, price, stock)
        self.products[id] = product
        return product

    def create_sale(self, customer_id):
        if customer_id in self.customers:
            sale = Sale(self.customers[customer_id])
            return sale
        return None

    def complete_sale(self, sale, payment_method):
        receipt = sale.finalize(payment_method)
        self.sales.append(sale)
        return receipt
