import json
import os
import hashlib
import uuid
from datetime import datetime

class AccountManager:
    def __init__(self, storage_path="accounts.json"):
        self.storage_path = storage_path
        self.accounts = self._load_accounts()

    def _load_accounts(self):
        if os.path.exists(self.storage_path):
            with open(self.storage_path, 'r') as f:
                return json.load(f)
        return {}

    def _save_accounts(self):
        with open(self.storage_path, 'w') as f:
            json.dump(self.accounts, f, indent=4)

    def _hash_password(self, password, salt=None):
        if not salt:
            salt = uuid.uuid4().hex
        hashed = hashlib.sha256((password + salt).encode()).hexdigest()
        return hashed, salt

    def create_account(self, username, password, email):
        if username in self.accounts:
            return False, "Username already exists"

        hashed_pw, salt = self._hash_password(password)

        self.accounts[username] = {
            "password_hash": hashed_pw,
            "salt": salt,
            "email": email,
            "created_at": datetime.now().isoformat(),
            "settings": {
                "theme": "light",
                "notifications": True,
                "language": "en"
            },
            "profile": {
                "display_name": username,
                "bio": "",
                "avatar": ""
            }
        }

        self._save_accounts()
        return True, "Account created successfully"

    def authenticate(self, username, password):
        if username not in self.accounts:
            return False, "Invalid username or password"

        account = self.accounts[username]
        hashed_pw, _ = self._hash_password(password, account["salt"])

        if hashed_pw != account["password_hash"]:
            return False, "Invalid username or password"

        return True, "Authentication successful"

    def update_profile(self, username, profile_data):
        if username not in self.accounts:
            return False, "Account not found"

        for key, value in profile_data.items():
            self.accounts[username]["profile"][key] = value

        self._save_accounts()
        return True, "Profile updated successfully"

    def update_settings(self, username, settings_data):
        if username not in self.accounts:
            return False, "Account not found"

        for key, value in settings_data.items():
            self.accounts[username]["settings"][key] = value

        self._save_accounts()
        return True, "Settings updated successfully"

    def change_password(self, username, old_password, new_password):
        if username not in self.accounts:
            return False, "Account not found"

        success, message = self.authenticate(username, old_password)
        if not success:
            return False, "Current password is incorrect"

        hashed_pw, salt = self._hash_password(new_password)
        self.accounts[username]["password_hash"] = hashed_pw
        self.accounts[username]["salt"] = salt

        self._save_accounts()
        return True, "Password changed successfully"

    def delete_account(self, username, password):
        success, message = self.authenticate(username, password)
        if not success:
            return False, message

        del self.accounts[username]
        self._save_accounts()
        return True, "Account deleted successfully"

    def get_profile(self, username):
        if username not in self.accounts:
            return None
        return self.accounts[username]["profile"]

    def get_settings(self, username):
        if username not in self.accounts:
            return None
        return self.accounts[username]["settings"]
