      return true;
    }
    return false;
  }

  removeAttendee(userId) {
    const index = this.attendees.indexOf(userId);
    if (index !== -1) {
      this.attendees.splice(index, 1);
      return true;
    }
    return false;
  }
}

// Event management service
class EventService {
  constructor() {
    this.events = new Map();
    this.nextId = 1;
  }

  createEvent(title, description, date, location, userId) {
    const id = this.nextId++;
    const event = new Event(id, title, description, date, location, userId);
    this.events.set(id, event);
    return event;
  }

  getEvent(id) {
    return this.events.get(id);
  }

  getAllEvents() {
    return Array.from(this.events.values());
  }

  updateEvent(id, updates, userId) {
    const event = this.events.get(id);
    if (!event) return false;
    if (event.createdBy !== userId) return false;

    Object.assign(event, updates);
    return true;
  }

  deleteEvent(id, userId) {
    const event = this.events.get(id);
    if (!event) return false;
    if (event.createdBy !== userId) return false;

    return this.events.delete(id);
  }

