                size = os.path.getsize(filepath)
                if size > threshold:
                    huge_files.append((filepath, size))
            except (OSError, PermissionError):
                pass
    huge_files.sort(key=lambda x: x[1], reverse=True)
    return huge_files

if __name__ == '__main__':
    import sys

    path = '/var/www/html'
    threshold = 102400

    if len(sys.argv) > 1:
        path = sys.argv[1]
    if len(sys.argv) > 2:
        threshold = int(sys.argv[2])

    print(f"Scanning {path} for files larger than {threshold} bytes...")
    huge_files = find_huge_files(path, threshold)

    if not huge_files:
        print("No large files found.")
    else:
        print(f"Found {len(huge_files)} large files:")
        for filepath, size in huge_files:
            size_mb = size / (1024 * 1024)
            print(f'{filepath} - {size} bytes ({size_mb:.2f} MB)')
