import datetime
import uuid
from dataclasses import dataclass, field
from typing import Dict, List, Optional, Union
from enum import Enum


class TaskStatus(Enum):
    NOT_STARTED = "Not Started"
    IN_PROGRESS = "In Progress"
    COMPLETED = "Completed"
    BLOCKED = "Blocked"
    CANCELLED = "Cancelled"


@dataclass
class User:
    id: str
    name: str
    email: str

    def __post_init__(self):
        if not self.id:
            self.id = str(uuid.uuid4())


@dataclass
class Task:
    id: str
    title: str
    description: str
    status: TaskStatus = TaskStatus.NOT_STARTED
    assignee: Optional[User] = None
    start_date: Optional[datetime.date] = None
    due_date: Optional[datetime.date] = None
    completed_date: Optional[datetime.date] = None
    dependencies: List[str] = field(default_factory=list)

    def __post_init__(self):
        if not self.id:
            self.id = str(uuid.uuid4())

    def assign_to(self, user: User) -> None:
        self.assignee = user

    def update_status(self, status: TaskStatus) -> None:
        self.status = status
        if status == TaskStatus.COMPLETED:
            self.completed_date = datetime.date.today()


@dataclass
class Project:
    id: str
    name: str
    description: str
    start_date: datetime.date
    end_date: datetime.date
    tasks: Dict[str, Task] = field(default_factory=dict)
    members: Dict[str, User] = field(default_factory=dict)

    def __post_init__(self):
        if not self.id:
            self.id = str(uuid.uuid4())

    def add_task(self, task: Task) -> None:
        self.tasks[task.id] = task

    def remove_task(self, task_id: str) -> None:
        if task_id in self.tasks:
            del self.tasks[task_id]

    def add_member(self, user: User) -> None:
        self.members[user.id] = user

    def remove_member(self, user_id: str) -> None:
        if user_id in self.members:
            del self.members[user_id]

    def get_task(self, task_id: str) -> Optional[Task]:
        return self.tasks.get(task_id)

    def get_tasks_by_status(self, status: TaskStatus) -> List[Task]:
        return [task for task in self.tasks.values() if task.status == status]

    def get_tasks_by_user(self, user_id: str) -> List[Task]:
        return [task for task in self.tasks.values() 
                if task.assignee and task.assignee.id == user_id]


class ProjectManager:
    def __init__(self):
        self.projects: Dict[str, Project] = {}
        self.users: Dict[str, User] = {}

    def create_project(self, name: str, description: str, 
                       start_date: datetime.date, end_date: datetime.date) -> Project:
        project_id = str(uuid.uuid4())
        project = Project(project_id, name, description, start_date, end_date)
        self.projects[project_id] = project
        return project

    def delete_project(self, project_id: str) -> bool:
        if project_id in self.projects:
            del self.projects[project_id]
            return True
        return False

    def create_user(self, name: str, email: str) -> User:
        user_id = str(uuid.uuid4())
        user = User(user_id, name, email)
        self.users[user_id] = user
        return user

    def delete_user(self, user_id: str) -> bool:
        if user_id in self.users:
            del self.users[user_id]
            return True
        return False

    def get_project(self, project_id: str) -> Optional[Project]:
        return self.projects.get(project_id)

    def get_user(self, user_id: str) -> Optional[User]:
        return self.users.get(user_id)

    def create_task(self, project_id: str, title: str, description: str,
                   start_date: Optional[datetime.date] = None,
                   due_date: Optional[datetime.date] = None) -> Optional[Task]:
        project = self.get_project(project_id)
        if not project:
            return None

        task_id = str(uuid.uuid4())
        task = Task(task_id, title, description, 
                   start_date=start_date, due_date=due_date)
        project.add_task(task)
        return task

    def assign_task(self, project_id: str, task_id: str, user_id: str) -> bool:
        project = self.get_project(project_id)
        user = self.get_user(user_id)

        if not project or not user:
            return False

        task = project.get_task(task_id)
        if not task:
            return False

        task.assign_to(user)
        return True

    def update_task_status(self, project_id: str, task_id: str, 
                          status: TaskStatus) -> bool:
        project = self.get_project(project_id)
        if not project:
            return False

        task = project.get_task(task_id)
        if not task:
            return False

        task.update_status(status)
        return True

    def get_project_timeline(self, project_id: str) -> List[Dict]:
        project = self.get_project(project_id)
        if not project:
            return []

        timeline = []
        for task in project.tasks.values():
            timeline.append({
                "task_id": task.id,
                "title": task.title,
                "start_date": task.start_date,
                "due_date": task.due_date,
                "status": task.status.value,
                "assignee": task.assignee.name if task.assignee else None
            })

        return sorted(timeline, key=lambda x: x["start_date"] or datetime.date.max)
