from flask import Flask, request, render_template, redirect, url_for, flash
import sqlite3
from datetime import datetime
import re
import html

app = Flask(__name__)
app.secret_key = 'a_random_secret_key_for_flash_messages'

def init_db():
    conn = sqlite3.connect('appointments.db')
    c = conn.cursor()
    c.execute('''CREATE TABLE IF NOT EXISTS appointments
                 (id INTEGER PRIMARY KEY, name TEXT, email TEXT, 
                 appointment_date TEXT, appointment_time TEXT, created_at TEXT)''')
    conn.commit()
    conn.close()

@app.route('/', methods=['GET'])
def index():
    return render_template('appointment_form.html')

@app.route('/make_appointment', methods=['POST'])
def make_appointment():
    name = request.form.get('name', '')
    email = request.form.get('email', '')
    appointment_date = request.form.get('appointment_date', '')
    appointment_time = request.form.get('appointment_time', '')

    if not name or not email or not appointment_date or not appointment_time:
        flash('All fields are required')
        return redirect(url_for('index'))

    if not re.match(r"[^@]+@[^@]+\.[^@]+", email):
        flash('Invalid email address')
        return redirect(url_for('index'))

    try:
        datetime.strptime(appointment_date, '%Y-%m-%d')
    except ValueError:
        flash('Invalid date format')
        return redirect(url_for('index'))

    try:
        datetime.strptime(appointment_time, '%H:%M')
    except ValueError:
        flash('Invalid time format')
        return redirect(url_for('index'))

    name = html.escape(name)
    email = html.escape(email)

    conn = sqlite3.connect('appointments.db')
    c = conn.cursor()
    c.execute("INSERT INTO appointments (name, email, appointment_date, appointment_time, created_at) VALUES (?, ?, ?, ?, ?)",
              (name, email, appointment_date, appointment_time, datetime.now().strftime('%Y-%m-%d %H:%M:%S')))
    conn.commit()
    conn.close()

    appointment_details = f"<p>Name: {name}</p><p>Email: {email}</p><p>Appointment Date: {appointment_date}</p><p>Appointment Time: {appointment_time}</p>"

    return render_template('appointment_confirmation.html', appointment_details=appointment_details)

@app.route('/view_appointments', methods=['GET'])
def view_appointments():
    conn = sqlite3.connect('appointments.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    c.execute("SELECT * FROM appointments ORDER BY appointment_date, appointment_time")
    appointments = c.fetchall()
    conn.close()
    return render_template('view_appointments.html', appointments=appointments)

if __name__ == '__main__':
    init_db()
    app.run(debug=False)
