import tarfile
import os
import re
import ast
import subprocess

def extract_all_tars(dir_path):
    tar_files = [f for f in os.listdir(dir_path) if f.endswith(".tar")]

    for tar_file in tar_files:
        tar_path = os.path.join(dir_path, tar_file)
        extract_dir = os.path.join(dir_path, tar_file[:-4])

        if not os.path.exists(extract_dir):
            os.makedirs(extract_dir)

        tar = tarfile.open(tar_path)
        tar.extractall(path=extract_dir)
        tar.close()

        analyze_code(extract_dir)

def analyze_code(directory):
    for root, _, files in os.walk(directory):
        for file in files:
            if file.endswith('.py'):
                file_path = os.path.join(root, file)
                print(f"Analyzing {file_path}...")

                with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                    content = f.read()

                check_line_length(file_path, content)
                check_docstrings(file_path, content)
                check_naming_conventions(file_path, content)
                run_linters(file_path)
                print()

def check_line_length(file_path, content):
    long_lines = []
    for i, line in enumerate(content.split('\n')):
        if len(line) > 79:
            long_lines.append(i + 1)

    if long_lines:
        print(f"  Line length > 79 chars on lines: {', '.join(map(str, long_lines))}")

def check_docstrings(file_path, content):
    try:
        tree = ast.parse(content)
        missing = []

        for node in ast.walk(tree):
            if isinstance(node, (ast.FunctionDef, ast.ClassDef, ast.Module)):
                if not ast.get_docstring(node):
                    if isinstance(node, ast.Module):
                        missing.append("module")
                    else:
                        missing.append(node.name)

        if missing:
            print(f"  Missing docstrings: {', '.join(missing)}")
    except SyntaxError:
        print("  Could not parse file for docstring analysis")

def check_naming_conventions(file_path, content):
    try:
        tree = ast.parse(content)
        issues = []

        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef) and not re.match(r'^[A-Z][a-zA-Z0-9]*$', node.name):
                issues.append(f"Class '{node.name}' should use CamelCase")
            elif isinstance(node, ast.FunctionDef) and not re.match(r'^[a-z_][a-z0-9_]*$', node.name):
                issues.append(f"Function '{node.name}' should use snake_case")

        if issues:
            for issue in issues:
                print(f"  {issue}")
    except SyntaxError:
        print("  Could not parse file for naming convention analysis")

def run_linters(file_path):
    try:
        result = subprocess.run(['pylint', file_path, '--output-format=text'], 
                               capture_output=True, text=True)
        score_match = re.search(r'Your code has been rated at ([-\d.]+)/10', result.stdout)
        if score_match:
            score = score_match.group(1)
            print(f"  Pylint score: {score}/10")
    except FileNotFoundError:
        print("  Pylint not available. Install with 'pip install pylint'")

extract_all_tars("tarballs")
