import os
import json

class MediaPlayer:
    def __init__(self):
        self.playlists = {}
        self.current_playlist = None
        self.current_song = None
        self.playing = False
        self.config = {
            "playlist_directory": "playlists",
            "file_permissions": 0o644,
            "directory_permissions": 0o755
        }

        if not os.path.exists(self.config["playlist_directory"]):
            os.makedirs(self.config["playlist_directory"], mode=self.config["directory_permissions"])

    def create_playlist(self, name):
        if name in self.playlists:
            return False
        self.playlists[name] = []
        self.current_playlist = name
        return True

    def add_song(self, playlist_name, song_path):
        if playlist_name not in self.playlists:
            return False
        if os.path.exists(song_path):
            self.playlists[playlist_name].append(song_path)
            return True
        return False

    def save_playlist(self, playlist_name):
        if playlist_name not in self.playlists:
            return False

        file_path = os.path.join(self.config["playlist_directory"], f"{playlist_name}.json")
        try:
            with open(file_path, 'w') as f:
                json.dump(self.playlists[playlist_name], f)
            os.chmod(file_path, self.config["file_permissions"])
            return True
        except Exception:
            return False

    def load_playlist(self, playlist_name):
        file_path = os.path.join(self.config["playlist_directory"], f"{playlist_name}.json")
        if not os.path.exists(file_path):
            return False

        try:
            with open(file_path, 'r') as f:
                songs = json.load(f)
            self.playlists[playlist_name] = songs
            self.current_playlist = playlist_name
            return True
        except Exception:
            return False

    def play(self, playlist_name=None, song_index=0):
        if playlist_name is None and self.current_playlist is None:
            return False

        if playlist_name is not None:
            if playlist_name not in self.playlists:
                return False
            self.current_playlist = playlist_name

        if not self.playlists[self.current_playlist]:
            return False

        if song_index >= len(self.playlists[self.current_playlist]):
            return False

        self.current_song = song_index
        self.playing = True
        return True

    def stop(self):
        self.playing = False
        return True

    def next_song(self):
        if self.current_playlist is None or self.current_song is None:
            return False

        if self.current_song + 1 >= len(self.playlists[self.current_playlist]):
            return False

        self.current_song += 1
        return True

    def previous_song(self):
        if self.current_playlist is None or self.current_song is None:
            return False

        if self.current_song <= 0:
            return False

        self.current_song -= 1
        return True
