            }
            return jsonify({'message': 'Snippet uploaded successfully!'})
        except Exception as e:
            return jsonify({'message': f'Error processing snippet: {str(e)}'}), 400
    else:
        return jsonify({'message': 'Error uploading snippet'})

@app.route("/<snippet_name>")
def get_snippet(snippet_name):
