import os
import zipfile
import tarfile
import argparse

def compress_directory(directory_path, output_path, format_type='zip'):
    if not os.path.exists(directory_path):
        raise FileNotFoundError(f"Directory not found: {directory_path}")

    if format_type == 'zip':
        with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
            for root, _, files in os.walk(directory_path):
                for file in files:
                    file_path = os.path.join(root, file)
                    arcname = os.path.relpath(file_path, os.path.dirname(directory_path))
                    zipf.write(file_path, arcname)
        return output_path

    elif format_type in ['tar', 'tar.gz', 'tar.bz2']:
        mode = 'w'
        if format_type == 'tar.gz':
            mode = 'w:gz'
        elif format_type == 'tar.bz2':
            mode = 'w:bz2'

        with tarfile.open(output_path, mode) as tar:
            tar.add(directory_path, arcname=os.path.basename(directory_path))
        return output_path

    else:
        raise ValueError(f"Unsupported format: {format_type}")

def main():
    parser = argparse.ArgumentParser(description='Compress a directory into an archive file')
    parser.add_argument('directory', help='Directory to compress')
    parser.add_argument('-o', '--output', help='Output file path')
    parser.add_argument('-f', '--format', choices=['zip', 'tar', 'tar.gz', 'tar.bz2'], 
                        default='zip', help='Archive format')

    args = parser.parse_args()

    directory = os.path.abspath(args.directory)

    if args.output:
        output = args.output
    else:
        output = f"{os.path.basename(directory)}.{args.format}"

    try:
        result = compress_directory(directory, output, args.format)
        print(f"Successfully compressed {directory} to {result}")
    except Exception as e:
        print(f"Error: {str(e)}")

if __name__ == "__main__":
    main()
