import tarfile
import os
import sys

def create_backup(paths, output_file="backup.tar"):
    tar = tarfile.open(output_file, "w")
    for path in paths:
        if os.path.exists(path):
            tar.add(path)
        else:
            print(f"Warning: {path} does not exist")
    tar.close()
    print(f"Backup created: {output_file}")

def extract_backup(archive="backup.tar", target_dir="."):
    if not os.path.exists(archive):
        print(f"Error: {archive} does not exist")
        return

    tar = tarfile.open(archive)
    tar.extractall(path=target_dir)
    tar.close()
    print(f"Extracted {archive} to {target_dir}")

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python backup.py [create/extract] [paths/archive] [output_file/target_dir]")
        sys.exit(1)

    action = sys.argv[1]

    if action == "create":
        if len(sys.argv) < 3:
            print("Please specify at least one path to backup")
            sys.exit(1)

        paths = sys.argv[2:-1] if len(sys.argv) > 3 else [sys.argv[2]]
        output_file = sys.argv[-1] if len(sys.argv) > 3 else "backup.tar"

        create_backup(paths, output_file)

    elif action == "extract":
        archive = sys.argv[2] if len(sys.argv) > 2 else "backup.tar"
        target_dir = sys.argv[3] if len(sys.argv) > 3 else "."

        extract_backup(archive, target_dir)

    else:
