import tarfile
import cv2
import numpy as np
from PIL import Image
import io

def detect_faces(image_archive):
    tar = tarfile.open(image_archive)
    face_cascade = cv2.CascadeClassifier(cv2.data.haarcascades + 'haarcascade_frontalface_default.xml')
    faces = {}

    for member in tar.getmembers():
        if member.isfile() and member.name.endswith((".jpg", ".jpeg", ".png")):
            f = tar.extractfile(member)
            if f is not None:
                image_data = f.read()
                img = Image.open(io.BytesIO(image_data))
                img_array = np.array(img)

                if len(img_array.shape) == 3:
                    if img_array.shape[2] == 3:
                        gray = cv2.cvtColor(img_array, cv2.COLOR_RGB2GRAY)
                    else:
                        gray = cv2.cvtColor(img_array, cv2.COLOR_RGBA2GRAY)
                else:
                    gray = img_array

                faces_in_image = face_cascade.detectMultiScale(gray, 1.3, 5)
                faces[member.name] = faces_in_image

    tar.close()
    return faces

