    func searchRestaurants(query: String, location: CLLocation, completion: @escaping ([Restaurant]) -> Void) {
        // API call to fetch restaurants
        let url = URL(string: "https://api.fooddelivery.com/search")!
        var request = URLRequest(url: url)
        request.httpMethod = "POST"

        let parameters = [
            "query": query,
            "latitude": location.coordinate.latitude,
            "longitude": location.coordinate.longitude,
            "radius": 5000
        ] as [String : Any]

        request.httpBody = try? JSONSerialization.data(withJSONObject: parameters)
        request.addValue("application/json", forHTTPHeaderField: "Content-Type")

        URLSession.shared.dataTask(with: request) { data, response, error in
            guard let data = data, error == nil else {
                completion([])
                return
            }

            do {
                let restaurants = try JSONDecoder().decode([Restaurant].self, from: data)
                DispatchQueue.main.async {
                    completion(restaurants)
                }
            } catch {
                DispatchQueue.main.async {
                    completion([])
                }
            }
        }.resume()
    }

    func placeOrder(restaurantId: String, items: [(dish: Dish, quantity: Int)], address: String, completion: @escaping (Bool) -> Void) {
