import os
import tarfile
from tempfile import mkdtemp
import shutil
import readline
import sys

class TarBrowser:
    def __init__(self):
        self.temp_dir = None
        self.current_path = None
        self.tar_path = None

    def extract_tar(self, tar_path):
        self.tar_path = tar_path
        self.temp_dir = mkdtemp()
        with tarfile.open(tar_path, 'r') as tar:
            tar.extractall(path=self.temp_dir)
        self.current_path = self.temp_dir

    def cleanup(self):
        if self.temp_dir and os.path.exists(self.temp_dir):
            shutil.rmtree(self.temp_dir)

    def list_contents(self):
        items = os.listdir(self.current_path)
        dirs = [d + '/' for d in items if os.path.isdir(os.path.join(self.current_path, d))]
        files = [f for f in items if os.path.isfile(os.path.join(self.current_path, f))]
        return sorted(dirs) + sorted(files)

    def view_file(self, filename):
        file_path = os.path.join(self.current_path, filename)
        try:
            with open(file_path, 'r') as f:
                content = f.read()
            return content
        except UnicodeDecodeError:
            return "Binary file: cannot display content"

    def change_directory(self, dirname):
        if dirname == '..':
            if self.current_path != self.temp_dir:
                self.current_path = os.path.dirname(self.current_path)
        else:
            new_path = os.path.join(self.current_path, dirname)
            if os.path.isdir(new_path):
                self.current_path = new_path
            else:
                return False
        return True

def main():
    browser = TarBrowser()

    try:
        if len(sys.argv) != 2:
            print("Usage: python tarbrowser.py <tarball>")
            return

        tar_path = sys.argv[1]
        if not os.path.exists(tar_path):
            print(f"File not found: {tar_path}")
            return

        print(f"Opening {tar_path}...")
        browser.extract_tar(tar_path)

        while True:
            rel_path = os.path.relpath(browser.current_path, browser.temp_dir)
            if rel_path == '.':
                rel_path = '/'
            else:
                rel_path = '/' + rel_path

            print(f"\nCurrent location: {rel_path}")
            items = browser.list_contents()

            for i, item in enumerate(items):
                print(f"{i+1}. {item}")

            command = input("\nEnter command (number to select, 'cd ..', 'q' to quit): ").strip()

            if command.lower() == 'q':
                break

            if command.lower().startswith('cd '):
                dirname = command[3:]
                if dirname.isdigit() and 1 <= int(dirname) <= len(items) and items[int(dirname)-1].endswith('/'):
                    dirname = items[int(dirname)-1]
                if not browser.change_directory(dirname.rstrip('/')):
                    print(f"Cannot change to {dirname}")

            elif command.isdigit():
                idx = int(command) - 1
                if 0 <= idx < len(items):
                    selected = items[idx]
                    if selected.endswith('/'):
                        browser.change_directory(selected.rstrip('/'))
                    else:
                        file_content = browser.view_file(selected)
                        print(f"\n--- {selected} ---\n")
                        print(file_content)
                        input("\nPress Enter to continue...")
                else:
                    print("Invalid selection")
    except KeyboardInterrupt:
        print("\nExiting...")
    finally:
        browser.cleanup()

if __name__ == "__main__":
    main()
