os.makedirs(UPLOAD_FOLDER, exist_ok=True)

users = {}
files = {}

@app.route('/register', methods=['POST'])
def register():
    data = request.json
    username = data.get('username')
    password = data.get('password')

    if not username or not password:
        return jsonify({'error': 'Username and password required'}), 400

    if username in users:
        return jsonify({'error': 'Username already exists'}), 400

    users[username] = {
        'password_hash': generate_password_hash(password),
        'files': []
    }

    return jsonify({'message': 'User registered successfully'}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.json
    username = data.get('username')
    password = data.get('password')

    if not username or not password:
        return jsonify({'error': 'Username and password required'}), 400

    if username not in users:
        return jsonify({'error': 'Invalid credentials'}), 401

    if not check_password_hash(users[username]['password_hash'], password):
        return jsonify({'error': 'Invalid credentials'}), 401

    session['user'] = username
    return jsonify({'message': 'Login successful'}), 200

@app.route('/upload', methods=['POST'])
def upload_file():
    if 'user' not in session:
        return jsonify({'error': 'Unauthorized'}), 401

    if 'file' not in request.files:
        return jsonify({'error': 'No file part'}), 400

    file = request.files['file']

    if file.filename == '':
        return jsonify({'error': 'No selected file'}), 400

    filename = secure_filename(file.filename)
    file_id = str(uuid.uuid4())
    file_path = os.path.join(UPLOAD_FOLDER, file_id)

    file.save(file_path)

    username = session['user']
    files[file_id] = {
        'filename': filename,
        'owner': username,
        'path': file_path
    }

    users[username]['files'].append(file_id)

    return jsonify({
        'message': 'File uploaded successfully',
        'file_id': file_id
    }), 201

@app.route('/files', methods=['GET'])
def list_files():
    if 'user' not in session:
        return jsonify({'error': 'Unauthorized'}), 401

    username = session['user']
    user_files = []

    for file_id in users[username]['files']:
        if file_id in files:
            user_files.append({
                'file_id': file_id,
                'filename': files[file_id]['filename']
            })

    return jsonify({'files': user_files}), 200

@app.route('/download/<file_id>', methods=['GET'])
def download_file(file_id):
    if 'user' not in session:
        return jsonify({'error': 'Unauthorized'}), 401

    username = session['user']

    if file_id not in files or files[file_id]['owner'] != username:
        return jsonify({'error': 'File not found or access denied'}), 404

    return send_file(files[file_id]['path'], 
                     download_name=files[file_id]['filename'],
                     as_attachment=True)

@app.route('/logout', methods=['POST'])
def logout():
    session.pop('user', None)
    return jsonify({'message': 'Logged out successfully'}), 200

if __name__ == '__main__':
    app.run(debug=True)
