                        }
                    }
                }
            ).result()
            self.vm_ids.append(vm_name)
        return self.vm_ids

    def _provision_gcp(self, count):
        client = compute_v1.InstancesClient()

        for i in range(count):
            vm_name = f"test-vm-{uuid.uuid4().hex[:8]}"

