from PIL.ExifTags import TAGS

def get_exif(fname):
    try:
        image = Image.open(fname)
        exif_data = image._getexif()
        if exif_data:
            return {TAGS.get(tag, tag): value for tag, value in exif_data.items()}
        return {}
    except Exception:
        return {}

def move_images(src, dest):
    if not os.path.exists(dest):
        os.makedirs(dest)

    for fname in glob.glob(os.path.join(src, '*.jpg')):
        try:
            exif = get_exif(fname)
            if 'DateTimeOriginal' in exif:
                date = exif['DateTimeOriginal'].split(' ')[0].replace(':', '-')
                new_name = os.path.join(dest, date + '_' + os.path.basename(fname))
            else:
                new_name = os.path.join(dest, os.path.basename(fname))

            shutil.move(fname, new_name)
            print(f"Moved {fname} to {new_name}")
