class Crawler:
    def __init__(self, start_url, max_pages=100, delay=1):
        self.start_url = start_url
        self.max_pages = max_pages
        self.delay = delay
        self.visited = set()
        self.to_visit = deque([start_url])
        self.base_domain = urlparse(start_url).netloc

    def get_links(self, url):
        try:
            response = urlopen(url)
            content_type = response.getheader('Content-Type', '')
            if 'text/html' not in content_type:
                return set()

            html = response.read().decode('utf-8', errors='ignore')
            parser = LinkParser()
            parser.feed(html)

            absolute_links = set()
            for link in parser.links:
                absolute_link = urljoin(url, link)
                absolute_links.add(absolute_link)

            return absolute_links
        except Exception as e:
            print(f"Error fetching {url}: {e}")
            return set()

    def is_same_domain(self, url):
        return urlparse(url).netloc == self.base_domain

    def crawl(self):
        count = 0

        while self.to_visit and count < self.max_pages:
            url = self.to_visit.popleft()

            if url in self.visited:
                continue

            print(f"Crawling: {url}")
            self.visited.add(url)
            count += 1

            links = self.get_links(url)
            for link in links:
                if link not in self.visited and self.is_same_domain(link):
                    self.to_visit.append(link)

            time.sleep(self.delay)

        print(f"Crawling complete. Visited {len(self.visited)} pages.")

