        files = []
        for f in os.listdir(path):
            files.append(f)
        return files

    def change_dir(self, path):
        os.chdir(path)

    def download_file(self, filename):
        with open(filename, 'rb') as f:
            data = f.read()
        return data

    def upload_file(self, filename, data):
        with open(filename, 'wb') as f:
            f.write(data.encode() if isinstance(data, str) else data)

    def run(self):
        while True:
            input_str = input('ftp> ')
            inputs = input_str.split()
            command = inputs[0]
            if command == 'ls':
                path = inputs[1] if len(inputs) > 1 else '.'
                files = self.list_files(os.path.join(self.root, path))
                print('\n'.join(files))
            elif command == 'cd':
                path = inputs[1]
                self.change_dir(os.path.join(self.root, path))
            elif command == 'get':
                filename = inputs[1]
                data = self.download_file(filename)
                print(data)
            elif command == 'put':
                filename = inputs[1]
                data = inputs[2]
                self.upload_file(filename, data)
            elif command == 'quit':
                break

if __name__ == '__main__':
    server = FTPServer()
    server.run()

