import json
import logging
import os
import time
import uuid
from concurrent.futures import ThreadPoolExecutor
from datetime import datetime
from typing import Dict, Any, List

import boto3
from fastapi import FastAPI, Request, HTTPException
from pydantic import BaseModel


class LogEvent(BaseModel):
    timestamp: int = None
    level: str
    message: str
    source: str
    additional_data: Dict[str, Any] = {}


class LogAggregator:
    def __init__(self, storage_type="s3", buffer_size=100, flush_interval=60):
        self.storage_type = storage_type
        self.buffer_size = buffer_size
        self.flush_interval = flush_interval
        self.event_buffer = []
        self.last_flush_time = time.time()
        self.executor = ThreadPoolExecutor(max_workers=4)

        if storage_type == "s3":
            self.s3_client = boto3.client(
                's3',
                aws_access_key_id=os.environ.get('AWS_ACCESS_KEY_ID'),
                aws_secret_access_key=os.environ.get('AWS_SECRET_ACCESS_KEY'),
                region_name=os.environ.get('AWS_REGION', 'us-east-1')
            )
            self.bucket_name = os.environ.get('LOG_BUCKET_NAME')
            if not self.bucket_name:
                raise ValueError("LOG_BUCKET_NAME environment variable must be set")

    def add_event(self, event: LogEvent):
        if event.timestamp is None:
            event.timestamp = int(time.time())

        self.event_buffer.append(event.dict())

        if len(self.event_buffer) >= self.buffer_size or time.time() - self.last_flush_time > self.flush_interval:
            self.executor.submit(self.flush_events)

    def flush_events(self):
        if not self.event_buffer:
            return

        events_to_flush = self.event_buffer.copy()
        self.event_buffer = []
        self.last_flush_time = time.time()

        if self.storage_type == "s3":
            self._write_to_s3(events_to_flush)
        elif self.storage_type == "file":
            self._write_to_file(events_to_flush)
        else:
            logging.error(f"Unsupported storage type: {self.storage_type}")

    def _write_to_s3(self, events: List[Dict]):
        try:
            current_date = datetime.now().strftime("%Y/%m/%d")
            filename = f"{current_date}/{uuid.uuid4()}.json"

            data = json.dumps(events).encode('utf-8')

            self.s3_client.put_object(
                Bucket=self.bucket_name,
                Key=filename,
                Body=data,
                ContentType='application/json'
            )
            logging.info(f"Successfully wrote {len(events)} events to S3: {filename}")
        except Exception as e:
            logging.error(f"Failed to write events to S3: {str(e)}")

    def _write_to_file(self, events: List[Dict]):
        try:
            log_dir = os.environ.get('LOG_DIRECTORY', '/var/log/aggregator')
            os.makedirs(log_dir, exist_ok=True)

            current_date = datetime.now().strftime("%Y-%m-%d")
            filename = f"{log_dir}/events-{current_date}-{uuid.uuid4()}.json"

            with open(filename, 'w') as f:
                json.dump(events, f)

            logging.info(f"Successfully wrote {len(events)} events to file: {filename}")
        except Exception as e:
            logging.error(f"Failed to write events to file: {str(e)}")


app = FastAPI()
log_aggregator = LogAggregator(
    storage_type=os.environ.get('STORAGE_TYPE', 's3'),
    buffer_size=int(os.environ.get('BUFFER_SIZE', '100')),
    flush_interval=int(os.environ.get('FLUSH_INTERVAL', '60'))
)


@app.post("/log")
async def receive_log(event: LogEvent):
    log_aggregator.add_event(event)
    return {"status": "ok"}


@app.post("/logs/batch")
async def receive_logs_batch(events: List[LogEvent]):
    for event in events:
        log_aggregator.add_event(event)
    return {"status": "ok", "processed": len(events)}


@app.get("/health")
async def health_check():
    return {"status": "healthy"}


@app.on_event("shutdown")
def shutdown_event():
    log_aggregator.flush_events()
