import os
import shutil
import stat

def clean_disk(threshold, path, action="list"):
    for fpath, _, fnames in os.walk(path):
        for fname in fnames:
            fp = os.path.join(fpath, fname)
            try:
                size = os.path.getsize(fp)
                if size > threshold:
                    print(f"Large file found: {fp} ({size} bytes)")
                    if action == "delete":
                        os.remove(fp)
                        print(f"Deleted: {fp}")
                    elif action == "readonly":
                        current_mode = os.stat(fp).st_mode
                        os.chmod(fp, current_mode & ~stat.S_IWUSR & ~stat.S_IWGRP & ~stat.S_IWOTH)
                        print(f"Set to read-only: {fp}")
            except (FileNotFoundError, PermissionError) as e:
                print(f"Error processing {fp}: {e}")

def main():
