        ext = os.path.splitext(self.archive_path)[1].lower()
        if ext in ['.zip']:
            return 'zip'
        elif ext in ['.tar', '.tgz', '.tar.gz', '.tar.bz2', '.tar.xz']:
            return 'tar'
        elif ext in ['.gz']:
            return 'gzip'
        elif ext in ['.bz2']:
            return 'bzip2'
        elif ext in ['.xz']:
            return 'lzma'
        elif ext in ['.rar']:
            return 'rar'
        elif ext in ['.7z']:
            return '7z'
        else:
            raise ValueError(f"Unsupported archive format: {ext}")

    def extract(self, output_path=None):
        if output_path is None:
            output_path = os.path.dirname(self.archive_path)

        os.makedirs(output_path, exist_ok=True)

        if self.format == 'zip':
            with zipfile.ZipFile(self.archive_path, 'r') as zip_ref:
                zip_ref.extractall(output_path)

        elif self.format == 'tar':
            with tarfile.open(self.archive_path, 'r:*') as tar_ref:
                tar_ref.extractall(output_path)

        elif self.format == 'gzip':
            output_file = os.path.join(output_path, os.path.basename(self.archive_path)[:-3])
            with gzip.open(self.archive_path, 'rb') as f_in:
                with open(output_file, 'wb') as f_out:
                    shutil.copyfileobj(f_in, f_out)

        elif self.format == 'bzip2':
            output_file = os.path.join(output_path, os.path.basename(self.archive_path)[:-4])
            with bz2.open(self.archive_path, 'rb') as f_in:
                with open(output_file, 'wb') as f_out:
                    shutil.copyfileobj(f_in, f_out)

        elif self.format == 'lzma':
            output_file = os.path.join(output_path, os.path.basename(self.archive_path)[:-3])
            with lzma.open(self.archive_path, 'rb') as f_in:
                with open(output_file, 'wb') as f_out:
                    shutil.copyfileobj(f_in, f_out)

        elif self.format == 'rar':
            with rarfile.RarFile(self.archive_path) as rar_ref:
                rar_ref.extractall(output_path)

        elif self.format == '7z':
            with py7zr.SevenZipFile(self.archive_path, mode='r') as z:
                z.extractall(output_path)

        return output_path

    def list_contents(self):
        if self.format == 'zip':
            with zipfile.ZipFile(self.archive_path, 'r') as zip_ref:
                return zip_ref.namelist()

        elif self.format == 'tar':
            with tarfile.open(self.archive_path, 'r:*') as tar_ref:
                return tar_ref.getnames()

        elif self.format == 'rar':
            with rarfile.RarFile(self.archive_path) as rar_ref:
                return rar_ref.namelist()

        elif self.format == '7z':
            with py7zr.SevenZipFile(self.archive_path, mode='r') as z:
                return list(z.getnames())

        elif self.format in ['gzip', 'bzip2', 'lzma']:
            return [os.path.basename(self.archive_path)[:-len(self.format)]]

        return []
