import os
import shutil
import sys
import stat

def get_permission_choice():
    while True:
        choice = input("Apply source permissions (s) or specify new ones (n)? ").lower()
        if choice in ('s', 'n'):
            return choice
        print("Invalid choice. Please enter 's' or 'n'.")

def get_new_permissions():
    while True:
        try:
            perm_input = input("Enter new permissions (octal, e.g. 755): ")
            return int(perm_input, 8)
        except ValueError:
            print("Invalid permissions. Please enter an octal number.")

def copy_files(manifest_path, target_dir):
    if not os.path.exists(manifest_path):
        print(f"Manifest file not found: {manifest_path}")
        return False

    if not os.path.exists(target_dir):
        try:
            os.makedirs(target_dir)
        except OSError as e:
            print(f"Failed to create target directory: {e}")
            return False

    perm_choice = get_permission_choice()
    new_perm = None
    if perm_choice == 'n':
        new_perm = get_new_permissions()

    with open(manifest_path, 'r') as manifest:
        for line in manifest:
            source_path = line.strip()
            if not source_path or source_path.startswith('#'):
                continue

            if not os.path.exists(source_path):
                print(f"Warning: Source file not found: {source_path}")
                continue

            target_path = os.path.join(target_dir, os.path.basename(source_path))
            try:
                shutil.copy2(source_path, target_path)

                if perm_choice == 'n' and new_perm is not None:
                    os.chmod(target_path, new_perm)

                print(f"Copied: {source_path} -> {target_path}")
            except (IOError, OSError) as e:
                print(f"Error copying {source_path}: {e}")

    return True

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python script.py <manifest_file> <target_directory>")
        sys.exit(1)

    manifest_path = sys.argv[1]
    target_dir = sys.argv[2]

    if copy_files(manifest_path, target_dir):
        print("Copy operation completed.")
    else:
        print("Copy operation failed.")
        sys.exit(1)
