import os
import shutil
import zipfile
import datetime
import argparse

def backup_files(source_dir, backup_dir, archive_name=None):
    if not os.path.exists(source_dir):
        print(f"Source directory {source_dir} does not exist.")
        return False

    if not os.path.exists(backup_dir):
        os.makedirs(backup_dir)

    if archive_name is None:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        archive_name = f"backup_{timestamp}.zip"

    archive_path = os.path.join(backup_dir, archive_name)

    try:
        with zipfile.ZipFile(archive_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
            for root, _, files in os.walk(source_dir):
                for file in files:
                    file_path = os.path.join(root, file)
                    arcname = os.path.relpath(file_path, source_dir)
                    zipf.write(file_path, arcname)

        print(f"Backup created successfully: {archive_path}")
        return True
    except Exception as e:
        print(f"Error creating backup: {e}")
        return False

def restore_files(archive_path, restore_dir):
    if not os.path.exists(archive_path):
        print(f"Archive {archive_path} does not exist.")
        return False

    if not os.path.exists(restore_dir):
        os.makedirs(restore_dir)

    try:
        with zipfile.ZipFile(archive_path, 'r') as zipf:
            zipf.extractall(restore_dir)

        print(f"Files restored successfully to {restore_dir}")
        return True
    except Exception as e:
        print(f"Error restoring files: {e}")
        return False

def list_archives(backup_dir):
    if not os.path.exists(backup_dir):
        print(f"Backup directory {backup_dir} does not exist.")
        return []

    archives = [f for f in os.listdir(backup_dir) if f.endswith('.zip')]
    for i, archive in enumerate(archives, 1):
        archive_path = os.path.join(backup_dir, archive)
        size = os.path.getsize(archive_path) / (1024 * 1024)  # Convert to MB
        print(f"{i}. {archive} ({size:.2f} MB)")

    return archives

def main():
    parser = argparse.ArgumentParser(description="File Backup and Restore Utility")
    parser.add_argument('action', choices=['backup', 'restore', 'list'], help='Action to perform')
    parser.add_argument('--source', help='Source directory for backup')
    parser.add_argument('--backup-dir', default='./backups', help='Directory to store backups')
    parser.add_argument('--archive', help='Archive name for backup or path for restore')
    parser.add_argument('--restore-dir', help='Directory to restore files to')

    args = parser.parse_args()

    if args.action == 'backup':
        if not args.source:
            print("Source directory is required for backup.")
            return
        backup_files(args.source, args.backup_dir, args.archive)

    elif args.action == 'restore':
        if not args.archive:
            print("Archive path is required for restore.")
            return

        archive_path = args.archive
        if not os.path.isabs(archive_path):
            archive_path = os.path.join(args.backup_dir, args.archive)

        restore_dir = args.restore_dir or './restored'
        restore_files(archive_path, restore_dir)

    elif args.action == 'list':
        list_archives(args.backup_dir)

if __name__ == "__main__":
    main()
