import os
import psutil
import time
import json
import schedule
from datetime import datetime
import stat

CONFIG_FILE = 'monitor_config.json'
LOG_FILE = 'mem.log'
DATA_FILE = 'anomalies.json'

def get_config():
    if not os.path.exists(CONFIG_FILE):
        default_config = {
            "servers": ["localhost"],
            "cpu_threshold": 80,
            "memory_threshold": 80,
            "file_permissions": {
                "owner_read": True,
                "owner_write": True,
                "group_read": True,
                "group_write": False,
                "others_read": False,
                "others_write": False
            }
        }
        with open(CONFIG_FILE, 'w') as f:
            json.dump(default_config, f, indent=4)
        return default_config

    with open(CONFIG_FILE, 'r') as f:
        return json.load(f)

def set_file_permissions(filename, permissions):
    mode = 0
    if permissions.get("owner_read"):
        mode |= stat.S_IRUSR
    if permissions.get("owner_write"):
        mode |= stat.S_IWUSR
    if permissions.get("group_read"):
        mode |= stat.S_IRGRP
    if permissions.get("group_write"):
        mode |= stat.S_IWGRP
    if permissions.get("others_read"):
        mode |= stat.S_IROTH
    if permissions.get("others_write"):
        mode |= stat.S_IWOTH

    os.chmod(filename, mode)

def check_server(server, cpu_threshold, memory_threshold):
    anomalies = []
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    try:
        if server == "localhost":
            cpu_percent = psutil.cpu_percent(interval=1)
            memory_percent = psutil.virtual_memory().percent

            if cpu_percent > cpu_threshold:
                anomalies.append({
                    "timestamp": timestamp,
                    "server": server,
                    "type": "CPU",
                    "value": cpu_percent,
                    "threshold": cpu_threshold
                })

            if memory_percent > memory_threshold:
                anomalies.append({
                    "timestamp": timestamp,
                    "server": server,
                    "type": "Memory",
                    "value": memory_percent,
                    "threshold": memory_threshold
                })
        else:
            # For remote servers, you would use SSH or an API
            # This is a placeholder for the remote server monitoring
            pass

    except Exception as e:
        with open(LOG_FILE, 'a') as f:
            f.write(f"{timestamp} - Error checking server {server}: {str(e)}\n")

    return anomalies

def save_anomalies(anomalies, config):
    if not anomalies:
        return

    all_anomalies = []
    if os.path.exists(DATA_FILE):
        with open(DATA_FILE, 'r') as f:
            try:
                all_anomalies = json.load(f)
            except json.JSONDecodeError:
                all_anomalies = []

    all_anomalies.extend(anomalies)

    with open(DATA_FILE, 'w') as f:
        json.dump(all_anomalies, f, indent=4)

    set_file_permissions(DATA_FILE, config["file_permissions"])

    with open(LOG_FILE, 'a') as f:
        timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        f.write(f"{timestamp} - Detected {len(anomalies)} anomalies\n")

    set_file_permissions(LOG_FILE, config["file_permissions"])

def monitor_servers():
    config = get_config()
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    with open(LOG_FILE, 'a') as f:
        f.write(f"{timestamp} - Starting monitoring cycle\n")

    all_anomalies = []
    for server in config["servers"]:
        anomalies = check_server(server, config["cpu_threshold"], config["memory_threshold"])
        all_anomalies.extend(anomalies)

    save_anomalies(all_anomalies, config)

def init():
    if not os.path.exists(LOG_FILE):
        with open(LOG_FILE, 'w') as f:
            timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            f.write(f"{timestamp} - Monitoring system initialized\n")

    config = get_config()
    set_file_permissions(LOG_FILE, config["file_permissions"])

    schedule.every().hour.do(monitor_servers)
    monitor_servers()  # Run once at startup

    while True:
        schedule.run_pending()
        time.sleep(60)

if __name__ == "__main__":
    init()
