import os
import shutil
import subprocess
import hashlib
import json
import stat

def package(src_dir):
    os.system('tar -czf src.tar.gz %s' % src_dir)

def run_tests(test_dir):
    result = subprocess.run(['pytest', test_dir], capture_output=True, text=True)
    return result.returncode == 0

def set_permissions(artifact_path, permissions):
    if os.path.exists(artifact_path):
        if permissions == "readonly":
            os.chmod(artifact_path, stat.S_IRUSR | stat.S_IRGRP | stat.S_IROTH)
        elif permissions == "executable":
            os.chmod(artifact_path, stat.S_IRWXU | stat.S_IRGRP | stat.S_IXGRP | stat.S_IROTH | stat.S_IXOTH)
        elif permissions == "restricted":
            os.chmod(artifact_path, stat.S_IRUSR)

def generate_checksum(file_path):
    sha256 = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            sha256.update(chunk)
    return sha256.hexdigest()

def build(src_dir, build_dir="build"):
    if not os.path.exists(build_dir):
        os.makedirs(build_dir)

    package(src_dir)
    shutil.move("src.tar.gz", os.path.join(build_dir, "src.tar.gz"))

    manifest = {
        "artifact": "src.tar.gz",
        "timestamp": os.path.getmtime(os.path.join(build_dir, "src.tar.gz")),
        "checksum": generate_checksum(os.path.join(build_dir, "src.tar.gz"))
    }

    with open(os.path.join(build_dir, "manifest.json"), "w") as f:
        json.dump(manifest, f)

    return os.path.join(build_dir, "src.tar.gz")

def deploy(artifact_path, environment):
    env_dir = f"deploy/{environment}"
    if not os.path.exists(env_dir):
        os.makedirs(env_dir)

    if environment == "production":
        if not run_tests("tests"):
            print(f"Tests failed, not deploying to {environment}")
            return False

    shutil.copy(artifact_path, env_dir)
    print(f"Deployed to {environment}")
    return True

if __name__ == '__main__':
    package('backend')
