const express = require('express');
const fs = require('fs');
const path = require('path');
const archiver = require('archiver');
const multer = require('multer');

const app = express();
const port = process.env.PORT || 3000;

app.use(express.static('public'));
app.use(express.json());

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, 'uploads/');
  },
  filename: (req, file, cb) => {
    cb(null, Date.now() + '-' + file.originalname);
  }
});

const upload = multer({ storage });

app.get('/api/samples', (req, res) => {
  const samplesPath = path.join(__dirname, 'samples');

  fs.readdir(samplesPath, (err, files) => {
    if (err) {
      return res.status(500).send('Error reading samples directory');
    }

    const categories = {};

    files.forEach(file => {
      const stats = fs.statSync(path.join(samplesPath, file));
      if (stats.isDirectory()) {
        categories[file] = fs.readdirSync(path.join(samplesPath, file));
      }
    });

    res.json(categories);
  });
});

app.get('/api/download/:category', (req, res) => {
  const category = req.params.category;
  const samplesPath = path.join(__dirname, 'samples', category);

  if (!fs.existsSync(samplesPath)) {
    return res.status(404).send('Category not found');
  }

  const zipFileName = `${category}-samples.zip`;
  const zipFilePath = path.join(__dirname, 'temp', zipFileName);

  const output = fs.createWriteStream(zipFilePath);
  const archive = archiver('zip', {
    zlib: { level: 9 }
  });

  output.on('close', () => {
    res.download(zipFilePath, zipFileName, (err) => {
      if (err) {
        console.error('Download error:', err);
      }
      fs.unlinkSync(zipFilePath);
    });
  });

  archive.on('error', (err) => {
    res.status(500).send('Error creating zip file');
  });

  archive.pipe(output);
  archive.directory(samplesPath, false);
  archive.finalize();
});

app.post('/api/upload', upload.array('samples', 10), (req, res) => {
  if (!req.files || req.files.length === 0) {
    return res.status(400).send('No files uploaded');
  }

  const category = req.body.category || 'uncategorized';
  const categoryPath = path.join(__dirname, 'samples', category);

  if (!fs.existsSync(categoryPath)) {
    fs.mkdirSync(categoryPath, { recursive: true });
  }

  req.files.forEach(file => {
    const destination = path.join(categoryPath, file.originalname);
    fs.renameSync(file.path, destination);
  });

  res.send('Files uploaded successfully');
});

app.listen(port, () => {
