def list_signups():
    conn = sqlite3.connect('signup.db')
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    c.execute("SELECT * FROM signups")
    signups = c.fetchall()
    conn.close()
    return render_template('list_signups.html', signups=signups)

if __name__ == '__main__':
    init_db()
    app.run(debug=True)
