from dataclasses import dataclass, field
from typing import List, Dict
import json
from datetime import datetime

@dataclass
class Ingredient:
    name: str
    quantity: float
    unit: str

@dataclass
class Recipe:
    id: int
    name: str
    ingredients: List[Ingredient]
    instructions: List[str]
    serving_size: int
    preparation_time: int

@dataclass
class GroceryItem:
    ingredient: Ingredient
    purchased: bool = False

@dataclass
class GroceryList:
    items: List[GroceryItem] = field(default_factory=list)

    def add_item(self, ingredient: Ingredient):
        self.items.append(GroceryItem(ingredient))

    def mark_purchased(self, item_index: int):
        if 0 <= item_index < len(self.items):
            self.items[item_index].purchased = True

@dataclass
class MenuItem:
    recipe: Recipe
    day: str
    meal_type: str  # breakfast, lunch, dinner, snack

@dataclass
class Menu:
    items: List[MenuItem] = field(default_factory=list)

    def add_item(self, recipe: Recipe, day: str, meal_type: str):
        self.items.append(MenuItem(recipe, day, meal_type))

    def remove_item(self, item_index: int):
        if 0 <= item_index < len(self.items):
            self.items.pop(item_index)

    def generate_grocery_list(self) -> GroceryList:
        grocery_list = GroceryList()
        for menu_item in self.items:
            for ingredient in menu_item.recipe.ingredients:
                grocery_list.add_item(ingredient)
        return grocery_list

class MealPlanner:
    def __init__(self):
        self.recipes: List[Recipe] = []
        self.menus: Dict[str, Menu] = {}

    def add_recipe(self, recipe: Recipe):
        self.recipes.append(recipe)

    def create_menu(self, name: str) -> Menu:
        menu = Menu()
        self.menus[name] = menu
        return menu

    def save_data(self, filename: str):
        data = {
            "recipes": [vars(r) for r in self.recipes],
            "menus": {name: [vars(item) for item in menu.items] for name, menu in self.menus.items()}
        }
        with open(filename, 'w') as f:
            json.dump(data, f)

    def load_data(self, filename: str):
        with open(filename, 'r') as f:
            data = json.load(f)

        self.recipes = []
        for recipe_data in data["recipes"]:
            ingredients = [Ingredient(**ing) for ing in recipe_data["ingredients"]]
            self.recipes.append(Recipe(
                id=recipe_data["id"],
                name=recipe_data["name"],
                ingredients=ingredients,
                instructions=recipe_data["instructions"],
                serving_size=recipe_data["serving_size"],
                preparation_time=recipe_data["preparation_time"]
            ))

        self.menus = {}
        for menu_name, menu_items in data["menus"].items():
            menu = Menu()
            for item_data in menu_items:
                recipe = next((r for r in self.recipes if r.id == item_data["recipe"]["id"]), None)
                if recipe:
                    menu.add_item(recipe, item_data["day"], item_data["meal_type"])
            self.menus[menu_name] = menu

def main():
    planner = MealPlanner()

    # Create sample recipes
    recipe1 = Recipe(
        id=1,
        name="Pasta Carbonara",
        ingredients=[
            Ingredient("pasta", 200, "g"),
            Ingredient("eggs", 2, "pcs"),
            Ingredient("bacon", 100, "g"),
            Ingredient("parmesan", 50, "g")
        ],
        instructions=["Cook pasta", "Fry bacon", "Mix eggs and cheese", "Combine all ingredients"],
        serving_size=2,
        preparation_time=20
    )

    recipe2 = Recipe(
        id=2,
        name="Greek Salad",
        ingredients=[
            Ingredient("cucumber", 1, "pcs"),
            Ingredient("tomato", 2, "pcs"),
            Ingredient("feta cheese", 100, "g"),
            Ingredient("olives", 50, "g"),
            Ingredient("olive oil", 2, "tbsp")
        ],
        instructions=["Chop vegetables", "Add cheese and olives", "Drizzle with olive oil"],
        serving_size=2,
        preparation_time=10
    )

    planner.add_recipe(recipe1)
    planner.add_recipe(recipe2)

    # Create a weekly menu
    weekly_menu = planner.create_menu("Week 1")
    weekly_menu.add_item(recipe1, "Monday", "dinner")
    weekly_menu.add_item(recipe2, "Tuesday", "lunch")

    # Generate grocery list
    grocery_list = weekly_menu.generate_grocery_list()

    # Save data
    planner.save_data("meal_planner_data.json")

    # Print weekly menu
    print("Weekly Menu:")
    for item in weekly_menu.items:
        print(f"{item.day} {item.meal_type}: {item.recipe.name}")

    # Print grocery list
    print("\nGrocery List:")
    for item in grocery_list.items:
        print(f"- {item.ingredient.quantity} {item.ingredient.unit} {item.ingredient.name}")

if __name__ == "__main__":
    main()
