import os
import ast
import graphviz

class UMLGenerator:
    def __init__(self, source_code, output_path="uml_diagram"):
        self.source_code = source_code
        self.output_path = output_path
        self.dot = graphviz.Digraph(comment="UML Diagram")
        self.classes = {}
        self.relationships = []

    def parse_code(self):
        tree = ast.parse(self.source_code)
        for node in ast.walk(tree):
            if isinstance(node, ast.ClassDef):
                class_info = {
                    "name": node.name,
                    "methods": [],
                    "attributes": [],
                    "inherits": []
                }

                for base in node.bases:
                    if isinstance(base, ast.Name):
                        class_info["inherits"].append(base.id)

                for body_node in node.body:
                    if isinstance(body_node, ast.FunctionDef):
                        method = {
                            "name": body_node.name,
                            "params": [a.arg for a in body_node.args.args if a.arg != 'self']
                        }
                        class_info["methods"].append(method)

                    elif isinstance(body_node, ast.Assign):
                        for target in body_node.targets:
                            if isinstance(target, ast.Name):
                                class_info["attributes"].append(target.id)

                self.classes[node.name] = class_info

    def generate_diagram(self):
        for class_name, class_info in self.classes.items():
            label = f"{class_name}|"

            attributes = "\l".join(f"- {attr}" for attr in class_info["attributes"])
            if attributes:
                label += f"{attributes}\l|"

            methods = "\l".join(f"+ {m['name']}({', '.join(m['params'])})" for m in class_info["methods"])
            if methods:
                label += f"{methods}\l"

            self.dot.node(class_name, label=f"{{{label}}}", shape="record")

            for parent in class_info["inherits"]:
                if parent in self.classes:
                    self.dot.edge(parent, class_name, arrowhead="empty")

    def save_diagram(self, file_format="png"):
        try:
            os.makedirs(os.path.dirname(self.output_path), exist_ok=True)
            diagram_path = self.dot.render(self.output_path, format=file_format, cleanup=True)
            os.chmod(diagram_path, 0o644)
            return diagram_path
        except Exception as e:
            print(f"Error saving diagram: {e}")
            return None

def generate_uml_from_file(file_path, output_path="uml_diagram", file_format="png"):
    with open(file_path, 'r') as file:
        source_code = file.read()

    generator = UMLGenerator(source_code, output_path)
    generator.parse_code()
    generator.generate_diagram()
    return generator.save_diagram(file_format)

def generate_uml_from_directory(directory_path, output_path="uml_diagram", file_format="png"):
    combined_code = ""
    for root, _, files in os.walk(directory_path):
        for file in files:
            if file.endswith(".py"):
                with open(os.path.join(root, file), 'r') as f:
                    combined_code += f.read() + "\n\n"

    generator = UMLGenerator(combined_code, output_path)
    generator.parse_code()
    generator.generate_diagram()
    return generator.save_diagram(file_format)
