        self.refs_dir = os.path.join(self.vcs_dir, 'refs')
        self.head_file = os.path.join(self.vcs_dir, 'HEAD')
        self.index_file = os.path.join(self.vcs_dir, 'index')
        self._ensure_repo_structure()

    def _ensure_repo_structure(self):
        for dir_path in [self.vcs_dir, self.objects_dir, self.refs_dir]:
            os.makedirs(dir_path, exist_ok=True)

        if not os.path.exists(self.head_file):
            with open(self.head_file, 'w') as f:
                f.write('refs/heads/master')

        if not os.path.exists(self.index_file):
            with open(self.index_file, 'w') as f:
                f.write(json.dumps({}))

    def init(self):
        print(f"Initialized empty VCS repository in {self.repo_path}")

    def _hash_file(self, file_path: str) -> str:
        with open(file_path, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()

    def _store_object(self, data: str) -> str:
        hash_value = hashlib.sha256(data.encode()).hexdigest()
        obj_path = os.path.join(self.objects_dir, hash_value)
        if not os.path.exists(obj_path):
            with open(obj_path, 'w') as f:
                f.write(data)
        return hash_value

    def _get_object(self, hash_value: str) -> str:
        obj_path = os.path.join(self.objects_dir, hash_value)
        if os.path.exists(obj_path):
            with open(obj_path, 'r') as f:
                return f.read()
        return ""

    def _read_index(self) -> Dict[str, FileMetadata]:
        with open(self.index_file, 'r') as f:
            data = json.loads(f.read())
            index = {}
            for path, metadata in data.items():
                index[path] = FileMetadata(**metadata)
            return index

    def _write_index(self, index: Dict[str, FileMetadata]):
        serialized = {path: asdict(metadata) for path, metadata in index.items()}
        with open(self.index_file, 'w') as f:
            f.write(json.dumps(serialized, indent=2))

    def status(self):
        index = self._read_index()
        staged_files = []
        modified_files = []
        untracked_files = []

        for root, dirs, files in os.walk(self.repo_path):
            if '.vcs' in root:
                continue

            for file in files:
                full_path = os.path.join(root, file)
                rel_path = os.path.relpath(full_path, self.repo_path)

                if rel_path in index:
                    stored_metadata = index[rel_path]
                    current_hash = self._hash_file(full_path)
                    current_perms = os.stat(full_path).st_mode & 0o777

                    if stored_metadata.hash != current_hash:
                        modified_files.append(rel_path)
                    elif stored_metadata.permissions != current_perms:
                        modified_files.append(rel_path)
                else:
                    untracked_files.append(rel_path)

        # Find staged files
        for path, metadata in index.items():
            if metadata.timestamp > 0:
                staged_files.append(path)

        print("Changes to be committed:")
        for file in staged_files:
            print(f"  modified: {file}")

        print("\nChanges not staged for commit:")
        for file in modified_files:
            print(f"  modified: {file}")

        print("\nUntracked files:")
        for file in untracked_files:
            print(f"  {file}")

    def add(self, path: str):
        abs_path = os.path.join(self.repo_path, path)
        if not os.path.exists(abs_path):
            print(f"Error: '{path}' does not exist")
            return

        index = self._read_index()

        if os.path.isdir(abs_path):
            for root, dirs, files in os.walk(abs_path):
                for file in files:
                    file_path = os.path.join(root, file)
                    rel_path = os.path.relpath(file_path, self.repo_path)
                    self._add_file(rel_path, index)
        else:
            self._add_file(path, index)

        self._write_index(index)
        print(f"Added {path} to index")

    def _add_file(self, path: str, index: Dict[str, FileMetadata]):
        abs_path = os.path.join(self.repo_path, path)
        if os.path.isdir(abs_path):
            metadata = FileMetadata(
                path=path,
                permissions=os.stat(abs_path).st_mode & 0o777,
                is_directory=True,
                timestamp=time.time()
            )
        else:
            metadata = FileMetadata(
                path=path,
                permissions=os.stat(abs_path).st_mode & 0o777,
                is_directory=False,
                hash=self._hash_file(abs_path),
                timestamp=time.time()
            )
        index[path] = metadata

    def commit(self, message: str):
        index = self._read_index()

        # Find files that have been staged
        staged_files = {path: metadata for path, metadata in index.items() if metadata.timestamp > 0}
        if not staged_files:
            print("Nothing to commit")
            return

        # Create tree object
        tree_data = json.dumps(asdict(staged_files))
        tree_hash = self._store_object(tree_data)

        # Create commit object
        parent_hash = self._get_head_commit()
        commit_data = {
            "tree": tree_hash,
            "parent": parent_hash,
            "message": message,
            "timestamp": time.time()
        }
        commit_hash = self._store_object(json.dumps(commit_data))

        # Update HEAD
        with open(self.head_file, 'r') as f:
            head_ref = f.read().strip()

        ref_path = os.path.join(self.vcs_dir, head_ref)
        os.makedirs(os.path.dirname(ref_path), exist_ok=True)

        with open(ref_path, 'w') as f:
            f.write(commit_hash)

        # Clear timestamps from index
        for path in staged_files:
            index[path].timestamp = 0

        self._write_index(index)
        print(f"[{commit_hash[:7]}] {message}")

