import os
import datetime

class NoteApp:
    def __init__(self, notes_dir="notes"):
        self.notes_dir = notes_dir
        os.makedirs(self.notes_dir, exist_ok=True)

    def create_note(self, title, content):
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"{timestamp}_{title.replace(' ', '_')}.txt"
        filepath = os.path.join(self.notes_dir, filename)

        with open(filepath, "w") as file:
            file.write(content)
        return filepath

    def read_note(self, filename):
        filepath = os.path.join(self.notes_dir, filename)
        try:
            with open(filepath, "r") as file:
                return file.read()
        except FileNotFoundError:
            return f"Note {filename} not found."

    def list_notes(self):
        notes = []
        for filename in os.listdir(self.notes_dir):
            if filename.endswith(".txt"):
                notes.append(filename)
        return notes

    def delete_note(self, filename):
        filepath = os.path.join(self.notes_dir, filename)
        try:
            os.remove(filepath)
            return True
        except FileNotFoundError:
            return False

def main():
    app = NoteApp()

    while True:
        print("\nNote-taking Application")
        print("1. Create a new note")
        print("2. Read a note")
        print("3. List all notes")
        print("4. Delete a note")
        print("5. Exit")

        choice = input("Enter your choice (1-5): ")

        if choice == "1":
            title = input("Enter note title: ")
            print("Enter content (type END on a new line to finish):")
            lines = []
            while True:
                line = input()
                if line == "END":
                    break
                lines.append(line)
            content = "\n".join(lines)
            filepath = app.create_note(title, content)
            print(f"Note saved to {filepath}")

        elif choice == "2":
            filename = input("Enter filename to read: ")
            content = app.read_note(filename)
            print(f"\n--- {filename} ---\n{content}")

        elif choice == "3":
            notes = app.list_notes()
            if notes:
                print("\nAvailable notes:")
                for i, note in enumerate(notes, 1):
                    print(f"{i}. {note}")
            else:
                print("No notes found.")

        elif choice == "4":
            filename = input("Enter filename to delete: ")
            if app.delete_note(filename):
                print(f"Note {filename} deleted successfully.")
            else:
                print(f"Failed to delete {filename}. File not found.")

        elif choice == "5":
            print("Goodbye!")
            break

        else:
            print("Invalid choice. Please try again.")

if __name__ == "__main__":
    main()
