import os
import hashlib
import socket
import json
import time
import shutil
from pathlib import Path

class FileSync:
    def __init__(self, local_dir, port=5000, peer_list=None):
        self.local_dir = Path(local_dir).absolute()
        self.port = port
        self.peer_list = peer_list or []
        self.file_index = {}
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self.socket.bind(('0.0.0.0', self.port))

    def start(self):
        self.update_file_index()

        # Start listening for incoming connections in a separate thread
        import threading
        server_thread = threading.Thread(target=self.listen_for_connections)
        server_thread.daemon = True
        server_thread.start()

        while True:
            self.sync_with_peers()
            time.sleep(60)  # Sync every minute

    def listen_for_connections(self):
        self.socket.listen(5)
        while True:
            client, addr = self.socket.accept()
            threading.Thread(target=self.handle_client, args=(client,)).start()

    def handle_client(self, client):
        try:
            data = b""
            while True:
                chunk = client.recv(4096)
                if not chunk:
                    break
                data += chunk

            if data:
                request = json.loads(data.decode('utf-8'))
                if request['action'] == 'get_index':
                    client.sendall(json.dumps(self.file_index).encode('utf-8'))
                elif request['action'] == 'get_file':
                    filepath = self.local_dir / request['path']
                    if filepath.exists() and filepath.is_file():
                        with open(filepath, 'rb') as f:
                            client.sendall(f.read())
        except Exception as e:
            print(f"Error handling client: {e}")
        finally:
            client.close()

    def update_file_index(self):
        self.file_index = {}
        for root, _, files in os.walk(self.local_dir):
            for file in files:
                full_path = Path(root) / file
                rel_path = full_path.relative_to(self.local_dir)
                self.file_index[str(rel_path)] = self.get_file_hash(full_path)

    def get_file_hash(self, file_path):
        hasher = hashlib.md5()
        with open(file_path, 'rb') as f:
            buf = f.read(65536)
            while buf:
                hasher.update(buf)
                buf = f.read(65536)
        return hasher.hexdigest()

    def sync_with_peers(self):
        for peer in self.peer_list:
            try:
                peer_index = self.get_peer_index(peer)
                if not peer_index:
                    continue

                # Check for files to download
                for file_path, file_hash in peer_index.items():
                    local_path = self.local_dir / file_path

                    # File doesn't exist locally or has different hash
                    if file_path not in self.file_index or self.file_index[file_path] != file_hash:
                        self.download_file(peer, file_path, local_path)

                # Check for files to upload
                for file_path, file_hash in self.file_index.items():
                    if file_path not in peer_index or peer_index[file_path] != file_hash:
                        # This file is newer on our side, but we don't push
                        # Peer will pull on their next sync
                        pass

            except Exception as e:
                print(f"Error syncing with peer {peer}: {e}")

    def get_peer_index(self, peer):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.connect((peer, self.port))
            s.sendall(json.dumps({'action': 'get_index'}).encode('utf-8'))

            data = b""
            while True:
                chunk = s.recv(4096)
                if not chunk:
                    break
                data += chunk

            s.close()
            return json.loads(data.decode('utf-8'))
        except Exception as e:
            print(f"Error getting index from peer {peer}: {e}")
            return {}

    def download_file(self, peer, file_path, local_path):
        try:
            s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
            s.connect((peer, self.port))
            s.sendall(json.dumps({'action': 'get_file', 'path': file_path}).encode('utf-8'))

            # Ensure directory exists
            local_path.parent.mkdir(parents=True, exist_ok=True)

            # Download the file
            with open(local_path, 'wb') as f:
                while True:
                    chunk = s.recv(4096)
                    if not chunk:
                        break
                    f.write(chunk)

            s.close()

            # Update our index
            self.file_index[file_path] = self.get_file_hash(local_path)
            print(f"Downloaded {file_path} from {peer}")
        except Exception as e:
            print(f"Error downloading file {file_path} from {peer}: {e}")


if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="File synchronization tool")
    parser.add_argument("directory", help="Directory to synchronize")
    parser.add_argument("--port", type=int, default=5000, help="Port to listen on")
    parser.add_argument("--peers", nargs="*", default=[], help="List of peer IP addresses")

    args = parser.parse_args()

    sync = FileSync(args.directory, args.port, args.peers)
    sync.start()
