import React, { useState, useEffect } from 'react';
import { View, Text, Image, Button, FlatList, StyleSheet } from 'react-native';
import * as FileSystem from 'expo-file-system';

const CACHE_DIR = FileSystem.cacheDirectory + 'media/';

const App = () => {
  const [mediaAssets, setMediaAssets] = useState([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    ensureCacheDirectoryExists();
    loadCachedAssets();
  }, []);

  const ensureCacheDirectoryExists = async () => {
    try {
      const dirInfo = await FileSystem.getInfoAsync(CACHE_DIR);
      if (!dirInfo.exists) {
        await FileSystem.makeDirectoryAsync(CACHE_DIR, { intermediates: true });
      }
    } catch (error) {
      console.error('Error creating cache directory:', error);
    }
  };

  const loadCachedAssets = async () => {
    try {
      const files = await FileSystem.readDirectoryAsync(CACHE_DIR);
      const assets = files.map(filename => ({
        id: filename,
        uri: CACHE_DIR + filename,
        isCached: true
      }));
      setMediaAssets(assets);
    } catch (error) {
      console.error('Error loading cached assets:', error);
    }
  };

  const downloadAsset = async (url) => {
    setLoading(true);
    try {
      const filename = url.split('/').pop();
      const localUri = CACHE_DIR + filename;

      const fileInfo = await FileSystem.getInfoAsync(localUri);

      if (!fileInfo.exists) {
        const downloadResumable = FileSystem.createDownloadResumable(
          url,
          localUri,
          {},
          progress => console.log(progress)
        );

        const { uri } = await downloadResumable.downloadAsync();

        setMediaAssets(prev => [...prev, { id: filename, uri, isCached: true }]);
      } else {
        console.log('File already cached');
      }
    } catch (error) {
      console.error('Error downloading asset:', error);
    } finally {
      setLoading(false);
    }
  };

  const clearCache = async () => {
    try {
      await FileSystem.deleteAsync(CACHE_DIR);
      await ensureCacheDirectoryExists();
      setMediaAssets([]);
    } catch (error) {
      console.error('Error clearing cache:', error);
    }
  };

  return (
    <View style={styles.container}>
      <Text style={styles.title}>Media Asset Downloader</Text>

      <Button 
        title="Download Sample Image" 
        onPress={() => downloadAsset('https://picsum.photos/200/300')}
        disabled={loading}
      />

      <Button 
        title="Clear Cache" 
        onPress={clearCache}
        color="red"
      />

      <Text style={styles.subtitle}>Cached Assets:</Text>

      {mediaAssets.length === 0 ? (
        <Text style={styles.emptyText}>No cached assets found</Text>
      ) : (
        <FlatList
          data={mediaAssets}
          keyExtractor={item => item.id}
          renderItem={({ item }) => (
            <View style={styles.assetContainer}>
              <Image source={{ uri: item.uri }} style={styles.image} />
              <Text style={styles.filename}>{item.id}</Text>
            </View>
          )}
        />
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    padding: 20,
    marginTop: 40
  },
  title: {
    fontSize: 24,
    fontWeight: 'bold',
    marginBottom: 20
  },
  subtitle: {
    fontSize: 18,
    fontWeight: 'bold',
    marginTop: 20,
