import os
import re
import argparse
from collections import Counter, defaultdict
from datetime import datetime
import json
import csv

class LogAnalyzer:
    def __init__(self, log_path):
        self.log_path = log_path
        self.lines = []
        self.ip_counts = Counter()
        self.url_counts = Counter()
        self.status_counts = Counter()
        self.hourly_hits = defaultdict(int)
        self.user_agents = Counter()
        self.error_logs = []

    def parse(self):
        if not os.path.exists(self.log_path):
            raise FileNotFoundError(f"Log file not found: {self.log_path}")

        with open(self.log_path, 'r', errors='ignore') as f:
            self.lines = f.readlines()

        ip_pattern = r'(\d+\.\d+\.\d+\.\d+)'
        timestamp_pattern = r'\[(\d+/\w+/\d+:\d+:\d+:\d+) [+-]\d+\]'
        request_pattern = r'"(\w+) ([^"]*) HTTP/[\d.]+"'
        status_pattern = r'" (\d+) '
        user_agent_pattern = r'"([^"]*)"$'

        for line in self.lines:
            try:
                ip_match = re.search(ip_pattern, line)
                if ip_match:
                    self.ip_counts[ip_match.group(1)] += 1

                timestamp_match = re.search(timestamp_pattern, line)
                if timestamp_match:
                    try:
                        timestamp = datetime.strptime(timestamp_match.group(1), '%d/%b/%Y:%H:%M:%S')
                        self.hourly_hits[timestamp.hour] += 1
                    except ValueError:
                        pass

                request_match = re.search(request_pattern, line)
                if request_match and len(request_match.groups()) >= 2:
                    self.url_counts[request_match.group(2)] += 1

                status_match = re.search(status_pattern, line)
                if status_match:
                    self.status_counts[status_match.group(1)] += 1
                    if status_match.group(1).startswith(('4', '5')):
                        self.error_logs.append(line.strip())

                agent_match = re.search(user_agent_pattern, line)
                if agent_match:
                    self.user_agents[agent_match.group(1)] += 1
            except Exception:
                continue

    def generate_report(self):
        return {
            "total_requests": sum(self.ip_counts.values()),
            "unique_ips": len(self.ip_counts),
            "top_ips": dict(self.ip_counts.most_common(10)),
            "top_urls": dict(self.url_counts.most_common(10)),
            "status_codes": dict(self.status_counts),
            "hourly_distribution": dict(sorted(self.hourly_hits.items())),
            "error_count": sum(self.status_counts.get(code, 0) for code in self.status_counts if code.startswith(('4', '5'))),
            "top_user_agents": dict(self.user_agents.most_common(5))
        }

    def export_report(self, output_format='json', output_file=None):
        report = self.generate_report()

        if output_format == 'json':
            output = json.dumps(report, indent=2)
            if output_file:
                with open(output_file, 'w') as f:
                    f.write(output)
            else:
                return output

        elif output_format == 'csv':
            if output_file:
                with open(output_file, 'w', newline='') as f:
                    writer = csv.writer(f)
                    writer.writerow(['Metric', 'Value'])
                    writer.writerow(['Total Requests', report['total_requests']])
                    writer.writerow(['Unique IPs', report['unique_ips']])
                    writer.writerow(['Error Count', report['error_count']])

                    writer.writerow([])
                    writer.writerow(['Top IPs', 'Count'])
                    for ip, count in report['top_ips'].items():
                        writer.writerow([ip, count])

                    writer.writerow([])
                    writer.writerow(['Status Code', 'Count'])
                    for code, count in report['status_codes'].items():
                        writer.writerow([code, count])
            else:
                return "CSV output requires a file destination"

        elif output_format == 'text':
            lines = [
                f"Log Analysis Report for {self.log_path}",
                f"Total Requests: {report['total_requests']}",
                f"Unique IPs: {report['unique_ips']}",
                f"Error Count: {report['error_count']}",
                "\nTop 10 IPs:",
            ]

            for ip, count in report['top_ips'].items():
                lines.append(f"  {ip}: {count}")

            lines.append("\nStatus Code Distribution:")
            for code, count in report['status_codes'].items():
                lines.append(f"  {code}: {count}")

            lines.append("\nHourly Hit Distribution:")
            for hour, count in report['hourly_distribution'].items():
                lines.append(f"  {hour}:00 - {count} hits")

            output = "\n".join(lines)
            if output_file:
                with open(output_file, 'w') as f:
                    f.write(output)
            else:
                return output
        else:
            return "Unsupported output format"

def main():
    parser = argparse.ArgumentParser(description='Analyze log files and generate reports')
    parser.add_argument('log_file', help='Path to the log file')
    parser.add_argument('-o', '--output', help='Output file path')
    parser.add_argument('-f', '--format', choices=['json', 'csv', 'text'], default='text',
                        help='Output format (default: text)')

    args = parser.parse_args()

    analyzer = LogAnalyzer(args.log_file)
    try:
        analyzer.parse()
        result = analyzer.export_report(args.format, args.output)
        if result and not args.output:
            print(result)
        elif args.output:
            print(f"Report saved to {args.output}")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
