        self.patterns = {
            'apache': r'(\S+) - - \[(.*?)\] "(.*?)" (\d+) (\d+)',
            'nginx': r'(\S+) - (\S+) \[(.*?)\] "(.*?)" (\d+) (\d+)',
            'error': r'\[(.*?)\] \[(\w+)\] \[(\w+) (\w+)\] (.*)',
            'custom': r'(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}) (\w+) (.*)'
        }

    def load_log_file(self):
        try:
            with open(self.log_file_path, 'r') as file:
                return file.readlines()
        except Exception as e:
            print(f"Error reading log file: {e}")
            return []

    def detect_log_format(self, sample_lines):
        for format_name, pattern in self.patterns.items():
            matches = sum(1 for line in sample_lines if re.match(pattern, line))
            if matches / len(sample_lines) > 0.5:
                return format_name
        return "unknown"

    def parse_logs(self):
        lines = self.load_log_file()
        if not lines:
            return False

        log_format = self.detect_log_format(lines[:10])
        parser_method = getattr(self, f"parse_{log_format}", self.parse_unknown)

        self.log_entries = [entry for entry in (parser_method(line) for line in lines) if entry]
        return bool(self.log_entries)

    def parse_apache(self, line):
        match = re.match(self.patterns['apache'], line)
        if match:
            ip, timestamp, request, status, size = match.groups()
            return {
                'ip': ip,
                'timestamp': timestamp,
                'request': request,
                'status': int(status),
                'size': int(size)
            }
        return None

    def parse_nginx(self, line):
        match = re.match(self.patterns['nginx'], line)
        if match:
            ip, user, timestamp, request, status, size = match.groups()
            return {
                'ip': ip,
                'user': user,
                'timestamp': timestamp,
                'request': request,
                'status': int(status),
                'size': int(size)
            }
        return None

    def parse_error(self, line):
        match = re.match(self.patterns['error'], line)
        if match:
            timestamp, level, module, thread, message = match.groups()
            return {
                'timestamp': timestamp,
                'level': level,
                'module': module,
                'thread': thread,
                'message': message
            }
        return None

    def parse_custom(self, line):
        match = re.match(self.patterns['custom'], line)
        if match:
            timestamp, level, message = match.groups()
            return {
                'timestamp': timestamp,
                'level': level,
                'message': message
            }
        return None

    def parse_unknown(self, line):
        return {'raw': line.strip()}

    def generate_stats(self):
        if not self.log_entries:
            return False

        self.stats = {
            'total_entries': len(self.log_entries),
            'top_ips': Counter(entry.get('ip') for entry in self.log_entries if 'ip' in entry).most_common(10),
            'status_codes': Counter(entry.get('status') for entry in self.log_entries if 'status' in entry),
            'error_levels': Counter(entry.get('level') for entry in self.log_entries if 'level' in entry),
            'total_size': sum(entry.get('size', 0) for entry in self.log_entries),
            'time_analysis': self.analyze_time()
        }

        if 'request' in self.log_entries[0]:
            self.stats['request_methods'] = Counter(entry.get('request', '').split()[0] 
                                               for entry in self.log_entries if 'request' in entry)

        return True

    def analyze_time(self):
