import React, { useState, useEffect } from 'react';
import { View, Image, Text, ActivityIndicator } from 'react-native';
import RNFS from 'react-native-fs';
import CryptoJS from 'crypto-js';

const CACHE_DIR = `${RNFS.DocumentDirectoryPath}/mediaCache`;

const createCacheDirectory = async () => {
  try {
    const exists = await RNFS.exists(CACHE_DIR);
    if (!exists) {
      await RNFS.mkdir(CACHE_DIR);
    }
  } catch (error) {
    console.error('Failed to create cache directory:', error);
  }
};

const getFilenameFromUrl = (url) => {
  const hash = CryptoJS.MD5(url).toString();
  const extension = url.split('.').pop().split('?')[0];
  return `${hash}.${extension}`;
};

const downloadAndCacheFile = async (url) => {
  await createCacheDirectory();

  const filename = getFilenameFromUrl(url);
  const filePath = `${CACHE_DIR}/${filename}`;

  try {
    const exists = await RNFS.exists(filePath);
    if (exists) {
      return { path: filePath, fromCache: true };
    }

    const tempFilePath = `${filePath}.temp`;

    const { promise } = RNFS.downloadFile({
      fromUrl: url,
      toFile: tempFilePath,
    });

    await promise;

    try {
      await RNFS.moveFile(tempFilePath, filePath);
    } catch (error) {
      const tempExists = await RNFS.exists(tempFilePath);
      if (tempExists) {
        await RNFS.unlink(tempFilePath);
      }

      const fileExists = await RNFS.exists(filePath);
      if (fileExists) {
        const backupPath = `${filePath}.old`;
        await RNFS.moveFile(filePath, backupPath);
        await RNFS.moveFile(tempFilePath, filePath);
        await RNFS.unlink(backupPath);
      }
    }

    return { path: filePath, fromCache: false };
  } catch (error) {
    console.error(`Failed to download and cache file from ${url}:`, error);
    throw error;
  }
};

const MediaLoader = ({ source, style, type = 'image' }) => {
  const [mediaSource, setMediaSource] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    const loadMedia = async () => {
      try {
        setLoading(true);
        setError(null);

        if (!source) {
          setLoading(false);
          return;
        }

        const { path } = await downloadAndCacheFile(source);
        setMediaSource({ uri: `file://${path}` });
        setLoading(false);
      } catch (err) {
        setError(err.message);
        setLoading(false);
      }
    };

    loadMedia();
  }, [source]);

  if (loading) {
    return <ActivityIndicator size="large" color="#0000ff" />;
  }

  if (error) {
    return <Text>Error loading media: {error}</Text>;
  }

  if (!mediaSource) {
    return null;
  }

  if (type === 'image') {
    return <Image source={mediaSource} style={style} />;
  }

  return null;
};

const clearMediaCache = async () => {
  try {
    const exists = await RNFS.exists(CACHE_DIR);
    if (exists) {
      await RNFS.unlink(CACHE_DIR);
      await createCacheDirectory();
    }
  } catch (error) {
    console.error('Failed to clear cache:', error);
    throw error;
  }
};

export { MediaLoader, clearMediaCache, downloadAndCacheFile };
