from pathlib import Path

def extract_archive(archive_path, extract_to=None):
    """Extract data from a compressed archive."""
    if extract_to is None:
        extract_to = os.path.dirname(archive_path)

    # Create the extraction directory if it doesn't exist
    os.makedirs(extract_to, exist_ok=True)

    archive_path = os.path.abspath(archive_path)
    file_name = os.path.basename(archive_path)

    # Handle different archive types
    if zipfile.is_zipfile(archive_path):
        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            zip_ref.extractall(extract_to)
        return extract_to

    elif tarfile.is_tarfile(archive_path):
        with tarfile.open(archive_path, 'r:*') as tar_ref:
            tar_ref.extractall(extract_to)
        return extract_to

    elif file_name.endswith('.gz') and not file_name.endswith('.tar.gz'):
        output_path = os.path.join(extract_to, file_name[:-3])
        with gzip.open(archive_path, 'rb') as f_in:
            with open(output_path, 'wb') as f_out:
                shutil.copyfileobj(f_in, f_out)
        return output_path

    elif file_name.endswith('.bz2') and not file_name.endswith('.tar.bz2'):
        output_path = os.path.join(extract_to, file_name[:-4])
        with bz2.open(archive_path, 'rb') as f_in:
            with open(output_path, 'wb') as f_out:
                shutil.copyfileobj(f_in, f_out)
        return output_path

    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")

def list_archive_contents(archive_path):
    """List contents of an archive without extracting."""
    if zipfile.is_zipfile(archive_path):
        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            return zip_ref.namelist()

    elif tarfile.is_tarfile(archive_path):
        with tarfile.open(archive_path, 'r:*') as tar_ref:
            return [member.name for member in tar_ref.getmembers()]

    elif os.path.basename(archive_path).endswith(('.gz', '.bz2')):
        return [os.path.basename(archive_path)[:-3]]

    else:
        raise ValueError(f"Unsupported archive format: {archive_path}")

def extract_specific_files(archive_path, file_patterns, extract_to=None):
    """Extract only specific files that match the given patterns."""
    if extract_to is None:
        extract_to = os.path.dirname(archive_path)

    os.makedirs(extract_to, exist_ok=True)
    extracted_files = []

    if zipfile.is_zipfile(archive_path):
        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            for item in zip_ref.namelist():
                if any(pattern in item for pattern in file_patterns):
                    zip_ref.extract(item, extract_to)
                    extracted_files.append(os.path.join(extract_to, item))

    elif tarfile.is_tarfile(archive_path):
        with tarfile.open(archive_path, 'r:*') as tar_ref:
            for member in tar_ref.getmembers():
                if any(pattern in member.name for pattern in file_patterns):
                    tar_ref.extract(member, extract_to)
                    extracted_files.append(os.path.join(extract_to, member.name))

    else:
