import socket
import zlib
import os
import json
from pathlib import Path
from threading import Thread
from typing import Dict, Set, Optional

class Node:
    def __init__(self, host: str, port: int, data_dir: Path):
        self.host = host
        self.port = port
        self.data_dir = data_dir
        self.blocks: Dict[str, bytes] = {}
        self.files: Dict[str, Set[str]] = {}
        self.peers: Set[tuple] = set()
        self.socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.socket.bind((host, port))
        self.socket.listen(10)

    def start(self):
        Thread(target=self._accept_connections).start()

    def _accept_connections(self):
        while True:
            conn, addr = self.socket.accept()
            Thread(target=self._handle_connection, args=(conn,)).start()

    def _handle_connection(self, conn):
        try:
            while True:
                msg = json.loads(conn.recv(4096).decode())
                if msg["type"] == "get_block":
                    block_id = msg["block_id"]
                    if block_id in self.blocks:
                        conn.send(self.blocks[block_id])
                elif msg["type"] == "put_block":
                    block_id = msg["block_id"]
                    block_data = zlib.compress(msg["data"].encode())
                    self.blocks[block_id] = block_data
                    conn.send(b"ok")
        except:
            conn.close()

    def store_file(self, filepath: Path):
        file_blocks = set()
        with open(filepath, "rb") as f:
            while data := f.read(1024):
                block_id = str(hash(data))
                compressed = zlib.compress(data)
                self.blocks[block_id] = compressed
                file_blocks.add(block_id)
                self._broadcast_block(block_id, compressed)
        self.files[str(filepath)] = file_blocks

    def get_file(self, filepath: str) -> Optional[bytes]:
        if filepath not in self.files:
            return None
        content = []
        for block_id in self.files[filepath]:
            if block_id in self.blocks:
                data = zlib.decompress(self.blocks[block_id])
                content.append(data)
            else:
                data = self._request_block(block_id)
                if data:
                    content.append(data)
        return b"".join(content)

    def _broadcast_block(self, block_id: str, data: bytes):
        for peer in self.peers:
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s.connect(peer)
                msg = {"type": "put_block", "block_id": block_id, "data": data}
                s.send(json.dumps(msg).encode())
                s.close()
            except:
                continue

    def _request_block(self, block_id: str) -> Optional[bytes]:
        for peer in self.peers:
            try:
                s = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                s.connect(peer)
                msg = {"type": "get_block", "block_id": block_id}
                s.send(json.dumps(msg).encode())
                data = s.recv(4096)
                s.close()
                return zlib.decompress(data)
            except:
                continue
        return None

    def add_peer(self, host: str, port: int):
        self.peers.add((host, port))
