def restore_latest_backup(path):
    backups = sorted([f for f in os.listdir(path) if f.endswith(".tar.gz")])
    if not backups:
        raise ValueError("No backup files found")
    latest_backup = backups[-1]
    temp_dir = tempfile.mkdtemp()
    try:
        with tarfile.open(os.path.join(path, latest_backup), 'r:gz') as tar:
            for member in tar.getmembers():
                if not os.path.isabs(member.name) and '..' not in member.name:
                    tar.extract(member, temp_dir)
        for extracted_file in os.listdir(temp_dir):
            src = os.path.join(temp_dir, extracted_file)
            dst = os.path.join(path, extracted_file)
            shutil.move(src, dst)
    finally:
        shutil.rmtree(temp_dir)

if __name__ == "__main__":
