    try:
        url_domain = urlparse(url).netloc
        return base_domain == url_domain
    except:
        return False

def get_analytics(html):
    soup = BeautifulSoup(html, 'html.parser')
    word_count = len(re.findall(r'\w+', soup.get_text()))
    images = len(soup.find_all('img'))
    headings = len(soup.find_all(['h1', 'h2', 'h3', 'h4', 'h5', 'h6']))
    return {'words': word_count, 'images': images, 'headings': headings}

def crawl(url, visited=None):
    if visited is None:
        visited = set()
    if url in visited or len(visited) > 100:
        return {}

    visited.add(url)
    html = get_html(url)
    analytics = get_analytics(html)
    urls = extract_links(html)

    for new_url in urls:
        if is_same_site(url, new_url):
            sub_analytics = crawl(new_url, visited)
            for key in analytics:
                analytics[key] += sub_analytics.get(key, 0)

    return analytics

