from dataclasses import dataclass

@dataclass
class PackingItem:
    id: str
    name: str
    quantity: int
    category: str
    packed: bool

class PackingList:
    def __init__(self, name: str, owner_id: str):
        self.id = str(uuid.uuid4())
        self.name = name
        self.owner_id = owner_id
        self.items: List[PackingItem] = []
        self.shared_with: List[str] = []
        self.created_at = datetime.now()
        self.updated_at = datetime.now()

    def add_item(self, name: str, quantity: int, category: str) -> PackingItem:
        item = PackingItem(
            id=str(uuid.uuid4()),
            name=name,
            quantity=quantity,
            category=category,
            packed=False
        )
        self.items.append(item)
        self.updated_at = datetime.now()
        return item

    def remove_item(self, item_id: str) -> bool:
        self.items = [item for item in self.items if item.id != item_id]
        self.updated_at = datetime.now()
        return True

    def toggle_item_status(self, item_id: str) -> bool:
        for item in self.items:
            if item.id == item_id:
                item.packed = not item.packed
                self.updated_at = datetime.now()
                return True
        return False

    def share_list(self, user_id: str) -> bool:
        if user_id not in self.shared_with:
            self.shared_with.append(user_id)
            self.updated_at = datetime.now()
            return True
        return False

class User:
    def __init__(self, email: str, password: str):
        self.id = str(uuid.uuid4())
        self.email = email
        self.password_hash = bcrypt.hashpw(password.encode(), bcrypt.gensalt())
        self.lists: Dict[str, PackingList] = {}

    def create_list(self, name: str) -> PackingList:
        packing_list = PackingList(name, self.id)
        self.lists[packing_list.id] = packing_list
        return packing_list

    def delete_list(self, list_id: str) -> bool:
        if list_id in self.lists:
            del self.lists[list_id]
            return True
        return False

    def verify_password(self, password: str) -> bool:
        return bcrypt.checkpw(password.encode(), self.password_hash)

class PackingListApp:
    def __init__(self):
        self.users: Dict[str, User] = {}

    def register_user(self, email: str, password: str) -> User:
        if email not in [user.email for user in self.users.values()]:
            user = User(email, password)
            self.users[user.id] = user
            return user
        raise ValueError("Email already registered")

    def authenticate_user(self, email: str, password: str) -> User:
        for user in self.users.values():
            if user.email == email and user.verify_password(password):
                return user
        raise ValueError("Invalid credentials")
