import os
import hashlib
import json
from datetime import datetime
from pathlib import Path
from typing import Dict, List

class VersionControl:
    def __init__(self, repository_path: str):
        self.repo_path = Path(repository_path)
        self.versions_dir = self.repo_path / '.versions'
        self.versions_dir.mkdir(exist_ok=True)
        self.metadata_file = self.versions_dir / 'metadata.json'
        self.current_version = 0
        self._load_metadata()

    def _load_metadata(self):
        if self.metadata_file.exists():
            with open(self.metadata_file, 'r') as f:
                self.metadata = json.load(f)
            self.current_version = max(int(v) for v in self.metadata.keys())
        else:
            self.metadata = {}

    def _save_metadata(self):
        with open(self.metadata_file, 'w') as f:
            json.dump(self.metadata, f)

    def _calculate_hash(self, file_path: Path) -> str:
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest()

    def commit(self, message: str) -> int:
        new_version = self.current_version + 1
        version_dir = self.versions_dir / str(new_version)
        version_dir.mkdir()

        files_info = {}
        for file_path in self.repo_path.rglob('*'):
            if file_path.is_file() and '.versions' not in str(file_path):
                rel_path = str(file_path.relative_to(self.repo_path))
                file_hash = self._calculate_hash(file_path)
                target_path = version_dir / rel_path
                target_path.parent.mkdir(parents=True, exist_ok=True)
                with open(file_path, 'rb') as src, open(target_path, 'wb') as dst:
                    dst.write(src.read())
                files_info[rel_path] = file_hash

        self.metadata[str(new_version)] = {
            'timestamp': datetime.now().isoformat(),
            'message': message,
            'files': files_info
        }
        self._save_metadata()
        self.current_version = new_version
        return new_version

    def checkout(self, version: int):
        if str(version) not in self.metadata:
            raise ValueError(f"Version {version} does not exist")

        version_dir = self.versions_dir / str(version)
        for file_path in version_dir.rglob('*'):
            if file_path.is_file():
                rel_path = file_path.relative_to(version_dir)
                target_path = self.repo_path / rel_path
                target_path.parent.mkdir(parents=True, exist_ok=True)
                with open(file_path, 'rb') as src, open(target_path, 'wb') as dst:
                    dst.write(src.read())

    def get_history(self) -> List[Dict]:
        return [{
            'version': int(version),
            'timestamp': info['timestamp'],
            'message': info['message']
        } for version, info in sorted(self.metadata.items())]
