import networkx as nx
import matplotlib.pyplot as plt
from urllib.parse import urljoin, urlparse

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except:
        return False

def normalize_url(url, base_url):
    return urljoin(base_url, url)

def crawl(start_url, max_depth=3):
    visited = set()
    url_graph = nx.DiGraph()

    def _crawl(url, depth, parent):
        if depth > max_depth or not is_valid_url(url):
            return

        if url not in visited:
            visited.add(url)
            try:
                resp = requests.get(url, timeout=5)
                if 'text/html' not in resp.headers.get('Content-Type', ''):
                    return

                soup = BeautifulSoup(resp.text, 'html.parser')
                url_graph.add_node(url)

                if parent:
                    url_graph.add_edge(parent, url)

                links = soup.find_all('a')
                for link in links:
                    href = link.get('href')
                    if href:
                        full_url = normalize_url(href, url)
                        _crawl(full_url, depth + 1, url)

            except:
                return

    _crawl(start_url, 1, None)

    plt.figure(figsize=(12,8))
    pos = nx.spring_layout(url_graph)
    nx.draw(url_graph, pos, with_labels=True, node_size=500, node_color='lightblue', 
            font_size=8, font_weight='bold')
    plt.savefig('sitemap.png')
    plt.close()

    return url_graph

