import sys
from datetime import datetime

def backup(source_dir, backup_name=None):
    if not backup_name:
        backup_name = f'backup_{datetime.now().strftime("%Y%m%d_%H%M%S")}.zip'

    with zipfile.ZipFile(backup_name, 'w', zipfile.ZIP_DEFLATED) as backup_zip:
        for root, dirs, files in os.walk(source_dir):
            for file in files:
                file_path = os.path.join(root, file)
                arcname = os.path.relpath(file_path, source_dir)
                backup_zip.write(file_path, arcname)

def restore(backup_file, restore_dir):
    if not os.path.exists(restore_dir):
        os.makedirs(restore_dir)

    with zipfile.ZipFile(backup_file, 'r') as backup_zip:
        backup_zip.extractall(restore_dir)

if __name__ == '__main__':
    if len(sys.argv) < 3:
        sys.exit(1)

    action = sys.argv[1].lower()
    path = os.path.abspath(sys.argv[2])

    if action == 'backup':
        backup_name = sys.argv[3] if len(sys.argv) > 3 else None
        backup(path, backup_name)
    elif action == 'restore':
        if len(sys.argv) < 4:
            sys.exit(1)
        restore_dir = os.path.abspath(sys.argv[3])
        restore(path, restore_dir)
