def validate_drive_path(drive):
    drive_path = Path(drive)
    if not drive_path.is_block_device():
        raise ValueError("Invalid drive path")
    return str(drive_path.resolve())

def mount_drive(drive):
    safe_drive = validate_drive_path(drive)
    mount_point = Path("/mnt/drive")
