class MapDownloader(private val context: Context) {

    private val mapDir = File(context.filesDir, "maps")
    private val downloadManager = context.getSystemService(Context.DOWNLOAD_SERVICE) as DownloadManager

    init {
        mapDir.mkdirs()
    }

    fun downloadMap(cityId: String, url: String): Long {
        val uri = Uri.parse(url)
        val request = DownloadManager.Request(uri).apply {
            setAllowedNetworkTypes(DownloadManager.Request.NETWORK_WIFI or DownloadManager.Request.NETWORK_MOBILE)
            setDestinationInExternalFilesDir(context, "maps", "$cityId.zip")
            setTitle("Downloading $cityId map")
        }
        return downloadManager.enqueue(request)
    }

    fun installMap(downloadId: Long) {
        val query = DownloadManager.Query().setFilterById(downloadId)
        val cursor = downloadManager.query(query)

        if (cursor.moveToFirst()) {
            val status = cursor.getInt(cursor.getColumnIndex(DownloadManager.COLUMN_STATUS))
            if (status == DownloadManager.STATUS_SUCCESSFUL) {
                val zipFile = File(cursor.getString(cursor.getColumnIndex(DownloadManager.COLUMN_LOCAL_URI)))
                unzipFile(zipFile, mapDir)
                zipFile.delete()
            }
        }
        cursor.close()
    }

    private fun unzipFile(zipFile: File, destDir: File) {
        val buffer = ByteArray(1024)
        val zip = ZipInputStream(FileInputStream(zipFile))
        var entry = zip.nextEntry

        while (entry != null) {
            val newFile = File(destDir, entry.name)
            if (entry.isDirectory) {
                newFile.mkdirs()
            } else {
                val parent = newFile.parentFile
                parent?.mkdirs()

                val fos = FileOutputStream(newFile)
                var len = zip.read(buffer)
                while (len > 0) {
                    fos.write(buffer, 0, len)
                    len = zip.read(buffer)
                }
                fos.close()
            }
            entry = zip.nextEntry
        }
        zip.closeEntry()
        zip.close()
    }
}
