from PIL import Image
from PIL.ExifTags import TAGS

def get_exif(fname):
    try:
        with Image.open(fname) as image:
            exif = image._getexif()
            if exif:
                return {TAGS.get(tag, tag): value for tag, value in exif.items()}
            return {}
    except Exception:
        return {}

def rename_images(path):
    if not os.path.isdir(path):
        return

    for fname in glob.glob(os.path.join(path, '*.jpg')):
        try:
            exif = get_exif(fname)
            if 'DateTimeOriginal' in exif:
                date = exif['DateTimeOriginal'].split(' ')[0].replace(':', '-')
                new_name = os.path.join(path, f"{date}_{os.path.basename(fname)}")
                if not os.path.exists(new_name):
                    os.rename(fname, new_name)
        except Exception:
            continue

