import requests
from typing import Dict, List
import time
import json
from datetime import datetime
import hashlib
import hmac
import base64
import os
from dataclasses import dataclass

@dataclass
class ServiceConfig:
    name: str
    api_key: str
    api_secret: str
    base_url: str

class DataSync:
    def __init__(self, config_path: str):
        self.configs = self._load_configs(config_path)
        self.session = requests.Session()

    def _load_configs(self, path: str) -> List[ServiceConfig]:
        with open(path) as f:
            raw_configs = json.load(f)
            return [ServiceConfig(**c) for c in raw_configs]

    def _generate_signature(self, secret: str, message: str) -> str:
        signature = hmac.new(
            secret.encode('utf-8'),
            message.encode('utf-8'),
            hashlib.sha256
        ).digest()
        return base64.b64encode(signature).decode()

    def _make_request(self, config: ServiceConfig, endpoint: str, method: str = 'GET', data: Dict = None) -> Dict:
        timestamp = str(int(time.time()))
        signature = self._generate_signature(config.api_secret, timestamp)

        headers = {
            'Authorization': f'Bearer {config.api_key}',
            'X-Timestamp': timestamp,
            'X-Signature': signature
        }

        url = f"{config.base_url.rstrip('/')}/{endpoint.lstrip('/')}"

        response = self.session.request(
            method=method,
            url=url,
            headers=headers,
            json=data,
            timeout=30
        )
        response.raise_for_status()
        return response.json()

    def sync_service(self, service_name: str, since: datetime = None) -> Dict:
        config = next((c for c in self.configs if c.name == service_name), None)
        if not config:
            raise ValueError(f"Service {service_name} not found")

        params = {'since': since.isoformat()} if since else {}
        return self._make_request(config, 'sync', method='POST', data=params)

    def sync_all(self) -> Dict[str, Dict]:
        results = {}
        for config in self.configs:
            try:
                results[config.name] = self.sync_service(config.name)
            except Exception as e:
                results[config.name] = {'error': str(e)}
        return results

def main():
    sync_client = DataSync('config.json')
    results = sync_client.sync_all()

    success_path = 'sync_results.json'
    with open(success_path, 'w') as f:
        json.dump(results, f)

if __name__ == '__main__':
    main()
