import re
from collections import Counter, defaultdict
from datetime import datetime
import socket

class ApacheLogParser:
    def __init__(self, log_file):
        self.log_file = log_file
        self.pattern = r'([\d.]+)\s+\S+\s+\S+\s+\[([^\]]+)\]\s+"([^"]+)"\s+(\d+)\s+(\d+)'
        self.visits = defaultdict(int)
        self.ips = Counter()
        self.status_codes = Counter()
        self.bytes_sent = 0
        self.requests = []

    def parse(self):
        with open(self.log_file, 'r', encoding='utf-8') as f:
            for line in f:
                match = re.match(self.pattern, line.strip())
                if match:
                    ip, date_str, request, status, bytes_str = match.groups()
                    try:
                        date = datetime.strptime(date_str, '%d/%b/%Y:%H:%M:%S %z')
                        self.visits[date.strftime('%Y-%m-%d')] += 1
                        self.ips[self.resolve_ip(ip)] += 1
                        self.status_codes[status] += 1
                        self.bytes_sent += int(bytes_str)
                        self.requests.append(request)
                    except (ValueError, socket.gaierror):
                        continue

    def resolve_ip(self, ip):
        try:
            return socket.gethostbyaddr(ip)[0]
        except socket.herror:
            return ip

    def generate_report(self):
        report = {
            'total_visits': sum(self.visits.values()),
            'visits_by_date': dict(self.visits),
            'top_visitors': dict(self.ips.most_common(10)),
            'status_codes': dict(self.status_codes),
            'total_bytes': self.bytes_sent,
            'most_common_requests': Counter(self.requests).most_common(10)
        }
        return report

def analyze_logs(log_file):
    parser = ApacheLogParser(log_file)
    parser.parse()
    return parser.generate_report()
