import tarfile
import os
from datetime import datetime
import pathlib
import tempfile

BACKUP_DIR = 'backups'

def extract_latest():
    if not os.path.exists(BACKUP_DIR):
        os.makedirs(BACKUP_DIR)
        return

    backups = sorted([f for f in os.listdir(BACKUP_DIR) if f.startswith('backup-')])
    if not backups:
        return

    latest = os.path.join(BACKUP_DIR, backups[-1])
    if not os.path.isfile(latest):
        return

    with tempfile.TemporaryDirectory() as tmp_dir:
        with tarfile.open(latest, 'r:*') as tar:
            def is_within_directory(directory, target):
                abs_directory = os.path.abspath(directory)
                abs_target = os.path.abspath(target)
                prefix = os.path.commonprefix([abs_directory, abs_target])
                return prefix == abs_directory

            def safe_extract(tar, path):
                for member in tar.getmembers():
                    member_path = os.path.join(path, member.name)
                    if not is_within_directory(path, member_path):
                        raise Exception("Attempted directory traversal!")
                tar.extractall(path)

            safe_extract(tar, tmp_dir)

def create_backup():
    if not os.path.exists(BACKUP_DIR):
        os.makedirs(BACKUP_DIR)

    backup = os.path.join(BACKUP_DIR, 'backup-' + datetime.now().strftime('%Y-%m-%d') + '.tar.gz')
    with tarfile.open(backup, 'w:gz') as tar:
        tar.add('.')

def main():
    while True:
        try:
            extract_latest()
            create_backup()
            break
        except Exception:
            break

if __name__ == "__main__":
    main()
