def rename_images(source_dir):
    for filename in os.listdir(source_dir):
        if filename.lower().endswith(('.png', '.jpg', '.jpeg')):
            filepath = os.path.join(source_dir, filename)
            try:
                with Image.open(filepath) as img:
                    exif_dict = piexif.load(img.info.get('exif', b''))
                    if '0th' in exif_dict and piexif.ImageIFD.DateTime in exif_dict['0th']:
                        date_str = exif_dict['0th'][piexif.ImageIFD.DateTime].decode('utf-8')
                        date_obj = datetime.strptime(date_str, '%Y:%m:%d %H:%M:%S')
                        new_name = date_obj.strftime('%Y%m%d_%H%M%S') + os.path.splitext(filename)[1]
                        new_path = os.path.join(source_dir, new_name)

                        if not os.path.exists(new_path):
                            shutil.move(filepath, new_path)

            except (KeyError, ValueError, OSError):
                continue

if __name__ == "__main__":
    source_directory = os.path.abspath("./images")
    if os.path.exists(source_directory):
        rename_images(source_directory)
