def check_licenses(tarball_path):
    license_patterns = {
        'MIT': r'MIT License|Permission is hereby granted, free of charge',
        'GPL': r'GNU General Public License|GPL',
        'Apache': r'Apache License|Licensed under the Apache License',
        'BSD': r'BSD License|Redistribution and use in source and binary forms'
    }

    licenses_found = set()
    mime = magic.Magic(mime=True)

    with tempfile.TemporaryDirectory() as tmp_dir:
        with tarfile.open(tarball_path, 'r:*') as tar:
            members = tar.getmembers()
            for member in members:
                if not os.path.isabs(member.name) and '..' not in member.name:
                    tar.extract(member, tmp_dir)

        for root, _, files in os.walk(tmp_dir):
            for filename in files:
                file_path = os.path.join(root, filename)
                if os.path.isfile(file_path):
                    try:
                        file_type = mime.from_file(file_path)
                        if 'text' in file_type:
                            with open(file_path, 'r', encoding='utf-8') as f:
                                content = f.read()
                                for license_name, pattern in license_patterns.items():
                                    if re.search(pattern, content, re.IGNORECASE):
                                        licenses_found.add(license_name)
                    except (UnicodeDecodeError, IOError):
                        continue

    return sorted(list(licenses_found))

def get_file_hash(file_path):
    sha256 = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            sha256.update(chunk)
    return sha256.hexdigest()

def analyze_tarball(tarball_path):
