import os
import shutil
import hashlib
import tarfile
from pathlib import Path
import tempfile
import stat

class RepositoryManager:
    def __init__(self, base_path):
        self.base_path = Path(base_path).resolve()
        self.base_path.mkdir(parents=True, exist_ok=True)

    def _verify_path(self, path):
        resolved = Path(path).resolve()
        if not str(resolved).startswith(str(self.base_path)):
            raise ValueError("Path traversal attempt detected")
        return resolved

    def _calculate_hash(self, file_path):
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest()

    def checkout(self, archive_path, target_dir):
        archive_path = self._verify_path(archive_path)
        target_dir = self._verify_path(target_dir)

        if not archive_path.is_file():
            raise FileNotFoundError("Archive not found")

        with tempfile.TemporaryDirectory() as temp_dir:
            temp_path = Path(temp_dir)

            with tarfile.open(archive_path, 'r:*') as tar:
                members = tar.getmembers()
                for member in members:
                    member_path = Path(member.name).resolve()
                    if member_path.is_absolute():
                        raise ValueError("Absolute paths not allowed in archive")
                    if '..' in member_path.parts:
                        raise ValueError("Path traversal attempt in archive")

                    member.mode = member.mode & ~(stat.S_IWGRP | stat.S_IWOTH)
                    if member.islnk() or member.issym():
                        raise ValueError("Links not allowed in archive")

                tar.extractall(temp_path)

            if target_dir.exists():
                shutil.rmtree(target_dir)
            shutil.copytree(temp_path, target_dir)

    def create_archive(self, source_dir, archive_path):
        source_dir = self._verify_path(source_dir)
        archive_path = self._verify_path(archive_path)

        if not source_dir.is_dir():
            raise ValueError("Source directory does not exist")

        with tarfile.open(archive_path, 'w:gz') as tar:
            tar.add(source_dir, arcname=source_dir.name)

        return self._calculate_hash(archive_path)
