import subprocess
import os
from typing import List

class VersionControl:
    def __init__(self, repo_path: str):
        self.repo_path = os.path.abspath(repo_path)

    def init_repo(self) -> None:
        subprocess.run(['git', 'init'], cwd=self.repo_path, check=True)

    def add_files(self, files: List[str]) -> None:
        subprocess.run(['git', 'add'] + files, cwd=self.repo_path, check=True)

    def commit(self, message: str) -> None:
        subprocess.run(['git', 'commit', '-m', message], cwd=self.repo_path, check=True)

    def push(self, remote: str = 'origin', branch: str = 'main') -> None:
        subprocess.run(['git', 'push', remote, branch], cwd=self.repo_path, check=True)

    def pull(self, remote: str = 'origin', branch: str = 'main') -> None:
        subprocess.run(['git', 'pull', remote, branch], cwd=self.repo_path, check=True)

    def get_status(self) -> str:
        result = subprocess.run(['git', 'status'], cwd=self.repo_path, 
                              capture_output=True, text=True, check=True)
        return result.stdout

    def get_log(self, num_entries: int = 10) -> str:
        result = subprocess.run(['git', 'log', f'-{num_entries}'], 
                              cwd=self.repo_path, capture_output=True, 
                              text=True, check=True)
        return result.stdout

    def create_branch(self, branch_name: str) -> None:
        subprocess.run(['git', 'checkout', '-b', branch_name], 
                      cwd=self.repo_path, check=True)

    def checkout_branch(self, branch_name: str) -> None:
        subprocess.run(['git', 'checkout', branch_name], 
                      cwd=self.repo_path, check=True)
