from pathlib import Path

class ArchiveExtractor:
    def __init__(self, archive_path):
        self.archive_path = Path(archive_path)

    def extract(self, output_dir=None):
        if output_dir is None:
            output_dir = self.archive_path.parent
        output_dir = Path(output_dir)

        suffix = self.archive_path.suffix.lower()

        if suffix in ['.zip']:
            with zipfile.ZipFile(self.archive_path, 'r') as zf:
                zf.extractall(path=output_dir)

        elif suffix in ['.tar', '.gz', '.bz2', '.xz']:
            if suffix == '.gz':
                with gzip.open(self.archive_path, 'rb') as gz:
                    with open(output_dir / self.archive_path.stem, 'wb') as f:
                        shutil.copyfileobj(gz, f)

            elif suffix == '.bz2':
                with bz2.open(self.archive_path, 'rb') as bz:
                    with open(output_dir / self.archive_path.stem, 'wb') as f:
                        shutil.copyfileobj(bz, f)

            elif suffix == '.xz':
                with lzma.open(self.archive_path, 'rb') as xz:
                    with open(output_dir / self.archive_path.stem, 'wb') as f:
                        shutil.copyfileobj(xz, f)

            elif tarfile.is_tarfile(self.archive_path):
                with tarfile.open(self.archive_path, 'r:*') as tar:
                    tar.extractall(path=output_dir)

        else:
            raise ValueError(f"Unsupported archive format: {suffix}")

    def list_contents(self):
        suffix = self.archive_path.suffix.lower()

        if suffix == '.zip':
            with zipfile.ZipFile(self.archive_path, 'r') as zf:
                return zf.namelist()

        elif suffix in ['.tar', '.gz', '.bz2', '.xz']:
            if tarfile.is_tarfile(self.archive_path):
