import zipfile
import tarfile
import os
from pathlib import Path

def safe_extract(archive_path, extract_path):
    extract_path = Path(extract_path).resolve()
    parent_path = extract_path.parent.resolve()

    if not str(extract_path).startswith(str(parent_path)):
        raise ValueError("Extraction path must be within parent directory")

    os.makedirs(extract_path, exist_ok=True)

    if zipfile.is_zipfile(archive_path):
        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            members = zip_ref.namelist()
            for member in members:
                member_path = (extract_path / member).resolve()
                if not str(member_path).startswith(str(extract_path)):
                    continue
                zip_ref.extract(member, extract_path)

    elif tarfile.is_tarfile(archive_path):
        with tarfile.open(archive_path, 'r:*') as tar_ref:
            members = tar_ref.getmembers()
            for member in members:
                member_path = (extract_path / member.name).resolve() 
                if not str(member_path).startswith(str(extract_path)):
                    continue
                tar_ref.extract(member, extract_path)
    else:
        raise ValueError("Unsupported archive format")

if __name__ == "__main__":
    safe_extract("archive.zip", "extracted")
