from typing import Dict, List, Tuple
import requests
import folium
import geopy
from geopy.geocoders import Nominatim
from geopy.distance import geodesic
import osmnx as ox
import networkx as nx
from datetime import datetime
import hashlib
import hmac

class NavigationApp:
    def __init__(self, api_key: str):
        self.api_key = api_key
        self.geolocator = Nominatim(user_agent="nav_app")
        self.graph = None
        self.current_route = None

    def authenticate_request(self, payload: str) -> str:
        signature = hmac.new(
            self.api_key.encode(),
            payload.encode(),
            hashlib.sha256
        ).hexdigest()
        return signature

    def search_location(self, query: str) -> Tuple[float, float]:
        location = self.geolocator.geocode(query)
        if location:
            return (location.latitude, location.longitude)
        return None

    def get_nearby_places(self, lat: float, lon: float, category: str, radius: int = 1000) -> List[Dict]:
        url = f"https://api.openstreetmap.org/api/0.6/map"
        params = {
            "bbox": f"{lon-0.01},{lat-0.01},{lon+0.01},{lat+0.01}"
        }
        signature = self.authenticate_request(str(params))
        headers = {"Authorization": signature}

        response = requests.get(url, params=params, headers=headers)
        response.raise_for_status()

        places = []
        for place in response.json().get("elements", []):
            if category in place.get("tags", {}).get("amenity", ""):
                places.append({
                    "name": place.get("tags", {}).get("name"),
                    "location": (place["lat"], place["lon"])
                })
        return places

    def get_route(self, start: Tuple[float, float], end: Tuple[float, float]) -> List[Tuple[float, float]]:
        if not self.graph:
            self.graph = ox.graph_from_point(start, dist=10000, network_type="drive")

        start_node = ox.distance.nearest_nodes(self.graph, start[1], start[0])
        end_node = ox.distance.nearest_nodes(self.graph, end[1], end[0])

        route = nx.shortest_path(self.graph, start_node, end_node, weight="length")
        route_coords = []
        for node in route:
            coords = (self.graph.nodes[node]["y"], self.graph.nodes[node]["x"])
            route_coords.append(coords)

        self.current_route = route_coords
        return route_coords

    def get_traffic(self, route: List[Tuple[float, float]]) -> Dict:
        traffic_url = "https://api.traffic.com/v1/conditions"
        traffic_data = {}

        for i in range(len(route)-1):
            params = {
                "segment": f"{route[i][0]},{route[i][1]},{route[i+1][0]},{route[i+1][1]}",
                "timestamp": datetime.now().isoformat()
            }
            signature = self.authenticate_request(str(params))
            headers = {"Authorization": signature}

            response = requests.get(traffic_url, params=params, headers=headers)
            response.raise_for_status()

            traffic_data[i] = response.json()

        return traffic_data

    def display_map(self, route: List[Tuple[float, float]] = None):
        if not route and not self.current_route:
            return

        route = route or self.current_route
        m = folium.Map(location=route[0], zoom_start=13)

        points = [tuple(reversed(coord)) for coord in route]
        folium.PolyLine(points, weight=5, color='blue', opacity=0.8).add_to(m)

        return m
