    name = bleach.clean(request.form.get('name', '').strip()[:50])
    email = request.form.get('email', '').strip()[:100]
    website = request.form.get('website', '').strip()[:100]
    comment = bleach.clean(request.form.get('comment', '').strip()[:1000])

