        email = valid_email.email
    except EmailNotValidError:
        return make_response('Invalid email', 400)

    if website:
        url_pattern = re.compile(r'^https?:\/\/([\w\-\.]+)\.([a-z]{2,6}\.?)(\/[\w\-\.]*)*\/?$')
        if not url_pattern.match(website):
            return make_response('Invalid website URL', 400)
        website = bleach.clean(website)

    response_data = {
        'name': escape(name),
        'email': escape(email),
        'website': escape(website) if website else '',
        'comment': escape(comment)
    }

    return response_data, 200

