import os
import sys
import re
import argparse
from pathlib import Path
import stat

def validate_path(path):
    return Path(path).resolve().absolute()

def validate_pattern(pattern):
    try:
        re.compile(pattern)
        return True
    except re.error:
        return False

def set_permissions(file_path, perms):
    if not 0 <= perms <= 0o777:
        raise ValueError("Invalid permission value")
    os.chmod(file_path, perms)

def rename_files(directory, pattern, replacement, permissions=None):
    directory = validate_path(directory)
    if not directory.is_dir():
        raise NotADirectoryError(f"{directory} is not a directory")

    if not validate_pattern(pattern):
        raise ValueError("Invalid regex pattern")

    for file_path in directory.iterdir():
        if file_path.is_file():
            new_name = re.sub(pattern, replacement, file_path.name)
            if new_name != file_path.name:
                new_path = file_path.parent / new_name
                file_path.rename(new_path)
                if permissions is not None:
                    set_permissions(new_path, permissions)

def main():
    parser = argparse.ArgumentParser(description='Bulk file renaming tool')
    parser.add_argument('directory', help='Directory containing files to rename')
    parser.add_argument('pattern', help='Regex pattern to match')
    parser.add_argument('replacement', help='Replacement pattern')
    parser.add_argument('-p', '--permissions', type=lambda x: int(x, 8),
                      help='Octal permissions to set (e.g. 644)')

    args = parser.parse_args()

    try:
        rename_files(args.directory, args.pattern, args.replacement, args.permissions)
    except Exception as e:
        sys.exit(f"Error: {str(e)}")

if __name__ == '__main__':
    main()
