import os
import yaml
import shutil
import logging
import subprocess
from pathlib import Path
from typing import Dict, List
from dataclasses import dataclass

@dataclass
class BuildConfig:
    name: str
    artifacts_dir: Path
    logs_dir: Path
    permissions: Dict[str, List[str]]

class Pipeline:
    def __init__(self, config_file: str):
        self.config = self._load_config(config_file)
        self._setup_logging()

    def _load_config(self, config_file: str) -> BuildConfig:
        with open(config_file, 'r') as f:
            cfg = yaml.safe_load(f)

        return BuildConfig(
            name=cfg['name'],
            artifacts_dir=Path(cfg['artifacts_dir']),
            logs_dir=Path(cfg['logs_dir']), 
            permissions=cfg['permissions']
        )

    def _setup_logging(self):
        self.config.logs_dir.mkdir(parents=True, exist_ok=True)
        log_file = self.config.logs_dir / 'pipeline.log'

        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s',
            handlers=[
                logging.FileHandler(log_file),
                logging.StreamHandler()
            ]
        )

    def _set_permissions(self, path: Path, perms: Dict[str, List[str]]):
        for user, access in perms.items():
            if 'read' in access:
                os.chmod(path, os.stat(path).st_mode | 0o400)
            if 'write' in access:
                os.chmod(path, os.stat(path).st_mode | 0o200)
            if 'execute' in access:
                os.chmod(path, os.stat(path).st_mode | 0o100)

    def run_build(self, build_script: str):
        try:
            self.config.artifacts_dir.mkdir(parents=True, exist_ok=True)

            result = subprocess.run(
                [build_script],
                check=True,
                capture_output=True,
                text=True
            )

            logging.info(f"Build succeeded: {result.stdout}")

            artifacts = list(Path(".").glob("*.artifact"))
            for artifact in artifacts:
                dest = self.config.artifacts_dir / artifact.name
                shutil.copy2(artifact, dest)
                self._set_permissions(dest, self.config.permissions)

        except subprocess.CalledProcessError as e:
            logging.error(f"Build failed: {e.stderr}")
            raise
        except Exception as e:
            logging.error(f"Pipeline error: {str(e)}")
            raise

    def cleanup(self):
        shutil.rmtree(self.config.artifacts_dir)
        shutil.rmtree(self.config.logs_dir)

def main():
    pipeline = Pipeline("pipeline_config.yml")
    try:
        pipeline.run_build("./build.sh")
    finally:
        pipeline.cleanup()

if __name__ == "__main__":
    main()
