import tarfile
import shutil
import os

def make_backup(path):
    if not os.path.exists(path):
        raise ValueError("Path does not exist")
    base_name = os.path.basename(path)
    if ".." in base_name or base_name.startswith("/"):
        raise ValueError("Invalid path")
    tar = tarfile.open("backup.tar", "w")
    tar.add(path, arcname=base_name)
    tar.close()

def restore_backup(path, tar_path):
    if not os.path.exists(tar_path): 
        raise ValueError("Backup file does not exist")
    if not tarfile.is_tarfile(tar_path):
        raise ValueError("Invalid tar file")
    if os.path.exists(path):
        shutil.rmtree(path)
    tar = tarfile.open(tar_path, "r")
    members = tar.getmembers()
    for member in members:
        if ".." in member.name or member.name.startswith("/"):
            raise ValueError("Invalid tar content")
    tar.extractall(os.path.dirname(path))
    tar.close()

if __name__ == "__main__":
    make_backup("/home/user/Documents")
    restore_backup("/home/user/Documents", "backup.tar")
