import os
from pathlib import Path
import mimetypes
from PIL import Image

def convert_files(input_dir, output_dir, input_ext, output_ext):
    Path(output_dir).mkdir(parents=True, exist_ok=True)

    valid_exts = {'.jpg', '.jpeg', '.png', '.gif', '.bmp', '.tiff'}
    if input_ext not in valid_exts or output_ext not in valid_exts:
        raise ValueError('Invalid file extension')

    for file in os.listdir(input_dir):
        if file.lower().endswith(input_ext):
            input_path = os.path.join(input_dir, file)
            output_file = os.path.splitext(file)[0] + output_ext
            output_path = os.path.join(output_dir, output_file)

            if not os.path.isfile(input_path):
                continue

            mime = mimetypes.guess_type(input_path)[0]
            if not mime or not mime.startswith('image/'):
                continue

            try:
                with Image.open(input_path) as img:
                    img.save(output_path)
            except Exception:
                continue

def main():
    input_dir = 'input'
    output_dir = 'output'
    convert_files(input_dir, output_dir, '.png', '.jpg')

if __name__ == '__main__':
