import os
import zipfile
import tempfile
import shutil
import requests
from pathlib import Path
from typing import List, Dict
import hashlib

class ResourceBrowser:
    def __init__(self, base_url: str, cache_dir: Path):
        self.base_url = base_url.rstrip('/')
        self.cache_dir = cache_dir
        self.cache_dir.mkdir(parents=True, exist_ok=True)

    def download_package(self, package_name: str, version: str) -> Path:
        url = f"{self.base_url}/{package_name}/{version}.zip"
        cache_path = self.cache_dir / self._get_cache_filename(url)

        if not cache_path.exists():
            with requests.get(url, stream=True) as response:
                response.raise_for_status()
                with tempfile.NamedTemporaryFile(delete=False) as tmp_file:
                    shutil.copyfileobj(response.raw, tmp_file)
                shutil.move(tmp_file.name, cache_path)

        return cache_path

    def extract_resource(self, package_path: Path, resource_path: str, output_dir: Path) -> Path:
        output_dir.mkdir(parents=True, exist_ok=True)

        with zipfile.ZipFile(package_path) as zip_ref:
            zip_info = zip_ref.getinfo(resource_path)
            if '..' in resource_path or resource_path.startswith('/'):
                raise ValueError("Invalid resource path")

            extracted_path = output_dir / Path(resource_path).name
            with zip_ref.open(zip_info) as source, open(extracted_path, 'wb') as target:
                shutil.copyfileobj(source, target)

        return extracted_path

    def list_resources(self, package_path: Path) -> List[str]:
        with zipfile.ZipFile(package_path) as zip_ref:
            return zip_ref.namelist()

    def _get_cache_filename(self, url: str) -> str:
        return hashlib.sha256(url.encode()).hexdigest() + '.zip'

class ResourceManager:
    def __init__(self, browser: ResourceBrowser):
        self.browser = browser

    def get_resource(self, package_name: str, version: str, resource_path: str, output_dir: Path) -> Path:
        package = self.browser.download_package(package_name, version)
        return self.browser.extract_resource(package, resource_path, output_dir)

    def list_package_contents(self, package_name: str, version: str) -> List[str]:
        package = self.browser.download_package(package_name, version)
        return self.browser.list_resources(package)
