import os

def ensure_dir_exists(path):
    if not os.path.exists(path):
        os.makedirs(path, mode=0o700)

def get_replica_paths(key):
    ensure_dir_exists('/tmp/kvstore')
    safe_key = ''.join(c for c in str(key) if c.isalnum())
    return [f'/tmp/kvstore/{safe_key}-{i}.dat' for i in range(3)]

def store_key_value(key, value):
    for path in get_replica_paths(key):
        temp_path = f"{path}.tmp"
        with open(temp_path, 'w', opener=lambda p, f: os.open(p, f | os.O_CREAT, 0o600)) as f:
            f.write(str(value))
        os.replace(temp_path, path)

def get_key_value(key):
    paths = get_replica_paths(key)
    values = []
    for path in paths:
        try:
            with open(path, 'r') as f:
                values.append(f.read())
        except FileNotFoundError:
            continue
    if not values:
        raise KeyError(f"Key {key} not found")
    return max(set(values), key=values.count)

def delete_key_value(key):
