import tarfile
import os
from pathlib import Path

def create_tarball(output_path):
    output_path = Path(output_path).resolve()
    if not output_path.parent.exists():
        raise ValueError("Invalid output directory")
    with tarfile.open(output_path, "w:gz") as tar:
        base_dir = Path("site_files").resolve()
        if not base_dir.exists():
            raise ValueError("Site files directory not found")
        for file in base_dir.rglob("*"):
            if file.is_file():
                arcname = file.relative_to(base_dir)
                tar.add(file, arcname=arcname)

def extract_site(tarball_path):
    tarball_path = Path(tarball_path).resolve()
    if not tarball_path.exists():
        raise ValueError("Tarball not found")
    extract_dir = tarball_path.parent / "extracted_site"
    extract_dir.mkdir(exist_ok=True)
    with tarfile.open(tarball_path, "r:*") as tar:
        def is_safe(member):
            target_path = (extract_dir / member.name).resolve()
            return target_path.parent.is_relative_to(extract_dir)
        members = [m for m in tar.getmembers() if is_safe(m)]
        tar.extractall(path=extract_dir, members=members)

