import os
import sys
import re
from pathlib import Path
from typing import Dict, List, Optional

def analyze_comments(filename: str) -> Dict[str, int]:
    metrics = {
        'total_lines': 0,
        'comment_lines': 0,
        'single_comments': 0,
        'block_comments': 0
    }

    try:
        with open(filename, 'r', encoding='utf-8') as f:
            in_block = False
            for line in f:
                metrics['total_lines'] += 1
                line = line.strip()

                if line.startswith('/*'):
                    in_block = True
                    metrics['block_comments'] += 1
                    metrics['comment_lines'] += 1
                elif line.endswith('*/'):
                    in_block = False
                    metrics['comment_lines'] += 1
                elif in_block:
                    metrics['comment_lines'] += 1
                elif line.startswith('//'):
                    metrics['single_comments'] += 1
                    metrics['comment_lines'] += 1

        return metrics
    except IOError as e:
        print(f"Error reading file {filename}: {e}")
        sys.exit(1)

def generate_report(metrics: Dict[str, int], output_file: Optional[str] = None) -> None:
    density = (metrics['comment_lines'] / metrics['total_lines'] * 100) if metrics['total_lines'] > 0 else 0
    report = f"""Comment Analysis Report
Total Lines: {metrics['total_lines']}
Comment Lines: {metrics['comment_lines']}
Single-line Comments: {metrics['single_comments']}
Block Comments: {metrics['block_comments']}
Comment Density: {density:.1f}%
"""
    if output_file:
        try:
            Path(output_file).parent.mkdir(parents=True, exist_ok=True)
            with open(output_file, 'w', encoding='utf-8') as f:
                os.chmod(output_file, 0o644)
                f.write(report)
        except IOError as e:
            print(f"Error writing report to {output_file}: {e}")
            sys.exit(1)
    else:
        print(report)

def main() -> None:
    if len(sys.argv) < 2:
        print("Usage: script.py <input_file> [output_file]")
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2] if len(sys.argv) > 2 else None

    if not os.path.exists(input_file):
        print(f"Input file {input_file} does not exist")
        sys.exit(1)

    metrics = analyze_comments(input_file)
    generate_report(metrics, output_file)

if __name__ == '__main__':
    main()
