@login_required
def manage_subscriptions():
    if request.method == 'POST':
        email = request.form.get('email', '').strip()
        try:
            validate_email(email)
            subscription = Subscription.query.filter_by(
                user_id=current_user.id,
                email=email
            ).first()

            if not subscription:
                subscription = Subscription(
                    user_id=current_user.id,
                    email=email
                )
                db.session.add(subscription)
                db.session.commit()
                flash('Subscription added successfully', 'success')
            else:
                flash('Email already subscribed', 'warning')

        except (EmailNotValidError, SQLAlchemyError) as e:
            db.session.rollback()
            flash('Invalid email or database error', 'error')

    subscriptions = Subscription.query.filter_by(
        user_id=current_user.id
    ).all()

    return render_template(
        'subscriptions.html',
        subscriptions=subscriptions
    )

@app.route('/unsubscribe/<int:sub_id>', methods=['POST'])
@login_required
def unsubscribe(sub_id):
    try:
        subscription = Subscription.query.filter_by(
            id=sub_id,
            user_id=current_user.id
        ).first_or_404()

        db.session.delete(subscription)
        db.session.commit()
        flash('Unsubscribed successfully', 'success')

    except SQLAlchemyError:
        db.session.rollback()
        flash('Database error occurred', 'error')

    return redirect(url_for('manage_subscriptions'))
