from datetime import datetime
from typing import List, Dict, Optional

class Task:
    def __init__(self, title: str, category: str, priority: int, due_date: datetime):
        self.title = title.strip()
        self.category = category.strip()
        self.priority = max(1, min(5, priority))
        self.due_date = due_date
        self.completed = False

class TodoList:
    def __init__(self):
        self.tasks: List[Task] = []

    def add_task(self, title: str, category: str, priority: int, due_date: datetime) -> None:
        if not title or not category:
            raise ValueError("Title and category cannot be empty")
        task = Task(title, category, priority, due_date)
        self.tasks.append(task)

    def get_tasks_by_category(self, category: str) -> List[Task]:
        return [task for task in self.tasks if task.category.lower() == category.lower()]

    def get_tasks_by_priority(self, priority: int) -> List[Task]:
        return [task for task in self.tasks if task.priority == priority]

    def get_tasks_by_date_range(self, start_date: datetime, end_date: datetime) -> List[Task]:
        return [task for task in self.tasks if start_date <= task.due_date <= end_date]

    def get_overdue_tasks(self) -> List[Task]:
        now = datetime.now()
        return [task for task in self.tasks if task.due_date < now and not task.completed]

    def mark_task_complete(self, title: str) -> None:
        for task in self.tasks:
            if task.title.lower() == title.lower():
                task.completed = True
                break

    def get_stats(self) -> Dict[str, int]:
        total = len(self.tasks)
        completed = len([task for task in self.tasks if task.completed])
        return {
            "total": total,
            "completed": completed,
            "pending": total - completed
        }

    def remove_task(self, title: str) -> None:
        self.tasks = [task for task in self.tasks if task.title.lower() != title.lower()]

    def get_tasks_by_status(self, completed: bool) -> List[Task]:
        return [task for task in self.tasks if task.completed == completed]
