import yaml
from http.server import BaseHTTPRequestHandler, HTTPServer
from yaml.loader import SafeLoader
import json
from typing import Dict, List
import hmac
import hashlib

class Handler(BaseHTTPRequestHandler):
    def do_POST(self):
        data = self.rfile.read(int(self.headers['Content-Length']))

        try:
            request = yaml.load(data, Loader=SafeLoader)

            if not isinstance(request, dict):
                raise ValueError("Invalid request format")

            lessons_db = {
                "basic": {
                    "content": ["Greeting", "Numbers", "Colors"],
                    "quizzes": ["Match words", "Fill blanks"],
                    "conversations": ["Hello dialog", "Shopping dialog"]
                },
                "intermediate": {
                    "content": ["Grammar", "Vocabulary", "Phrases"],
                    "quizzes": ["Complete sentences", "Word order"],
                    "conversations": ["Restaurant", "Direction"]
                }
            }

            user_progress = {
                "current_level": "basic",
                "completed_lessons": [],
                "quiz_scores": {},
                "conversation_progress": []
            }

            action = request.get("action", "")
            if action not in ["get_lesson", "submit_quiz", "start_conversation"]:
                raise ValueError("Invalid action")

            response = {"status": "success", "data": {}}

            if action == "get_lesson":
                level = request.get("level", "basic")
                if level in lessons_db:
                    response["data"] = lessons_db[level]

            elif action == "submit_quiz":
                quiz_id = request.get("quiz_id")
                answers = request.get("answers", [])
                if quiz_id and isinstance(answers, list):
                    response["data"]["score"] = len(answers)

            elif action == "start_conversation":
                conv_id = request.get("conversation_id")
                if conv_id:
                    response["data"]["conversation"] = {"id": conv_id, "status": "started"}

            self.send_response(200)
            self.send_header('Content-type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps(response).encode('utf-8'))
            return

        except (yaml.YAMLError, ValueError, KeyError) as e:
            self.send_response(400)
            self.send_header('Content-type', 'application/json')
            self.end_headers()
            self.wfile.write(json.dumps({"status": "error"}).encode('utf-8'))
            return

server = HTTPServer(('', 80), Handler)
server.serve_forever()

import os
import shutil
import pwd
import stat

def backup_user(username):
    try:
        pwd.getpwnam(username)
    except KeyError:
        raise ValueError("Invalid username")

    backup_path = os.path.join('/home/backups', username)
    source_path = os.path.join('/home', username)

    if not os.path.exists(backup_path):
        os.makedirs(backup_path, mode=0o700)

    if not os.path.isdir(source_path):
        raise ValueError("User home directory not found")

    for item in os.listdir(source_path):
        src = os.path.join(source_path, item)
        dst = os.path.join(backup_path, item)

        if os.path.islink(src):
            continue

        if os.path.isfile(src):
            shutil.copy2(src, dst)
            os.chmod(dst, 0o600)
        elif os.path.isdir(src):
            shutil.copytree(src, dst, symlinks=False)
            os.chmod(dst, 0o700)

