import gzip
import os
from Bio import SeqIO
from pathlib import Path

def process_sequence_files(input_dir, output_dir):
    Path(output_dir).mkdir(parents=True, exist_ok=True)

    for file in os.listdir(input_dir):
        if file.endswith(('.gz', '.gzip')):
            input_path = os.path.join(input_dir, file)
            output_file = os.path.join(output_dir, file.rsplit('.', 1)[0])

            with gzip.open(input_path, 'rt') as f_in:
                sequences = []
                for record in SeqIO.parse(f_in, 'fasta'):
                    sequences.append(record)

                with open(output_file, 'w') as f_out:
                    SeqIO.write(sequences, f_out, 'fasta')

def extract_genome_data(sequence_file):
    genome_data = {}

    with gzip.open(sequence_file, 'rt') as f:
        for record in SeqIO.parse(f, 'fasta'):
            genome_data[record.id] = {
                'sequence': str(record.seq),
                'length': len(record.seq),
                'description': record.description
            }

    return genome_data

def main():
    input_directory = 'sequences/'
    output_directory = 'processed_sequences/'
    process_sequence_files(input_directory, output_directory)

    for file in os.listdir(output_directory):
        file_path = os.path.join(output_directory, file)
        genome_data = extract_genome_data(file_path)

if __name__ == '__main__':
    main()
