    extract_path = pathlib.Path(extract_path).resolve()

    if not extract_path.is_relative_to(os.getcwd()):
        raise ValueError("Extraction path must be within current directory")

    if zipfile.is_zipfile(archive_path):
        with zipfile.ZipFile(archive_path, 'r') as zip_ref:
            safe_extract(zip_ref, extract_path)

    elif tarfile.is_tarfile(archive_path):
        with tarfile.open(archive_path, 'r:*') as tar_ref:
            safe_extract(tar_ref, extract_path)

def safe_extract(archive, path):
    for file in archive.namelist() if isinstance(archive, zipfile.ZipFile) else archive.getnames():
        try:
            out_path = pathlib.Path(path / file).resolve()
            if not out_path.is_relative_to(path):
                raise ValueError(f"Attempted path traversal: {file}")
        except ValueError:
            continue

        archive.extract(file, path)

