    user_id = c.fetchone()[0]
    c.execute('INSERT INTO files (filename, owner_id, permissions) VALUES (?,?,?)',
              (filename, user_id, 'private'))
    conn.commit()
    conn.close()
    return ('File uploaded successfully', 200)

@app.route('/files/<filename>', methods=['GET'])
