import os
import zipfile
import shutil
from pathlib import Path

def extract_ebooks(archive_path, output_dir):
    supported_formats = {'.epub', '.mobi', '.pdf', '.azw', '.azw3'}

    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    with zipfile.ZipFile(archive_path, 'r') as archive:
        for file in archive.namelist():
            if Path(file).suffix.lower() in supported_formats:
                archive.extract(file, output_dir)

def process_archive(archive_path, output_dir):
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    try:
        extract_ebooks(archive_path, output_dir)
    except zipfile.BadZipFile:
        raise ValueError("Invalid or corrupted zip archive")
    except PermissionError:
        raise PermissionError("Permission denied accessing archive or output directory")

def main():
    archive_path = input("Enter path to ebook archive: ").strip()
    output_dir = input("Enter output directory path: ").strip()

    try:
        process_archive(archive_path, output_dir)
        print("Extraction completed successfully")
    except Exception as e:
        print(f"Error: {str(e)}")

if __name__ == "__main__":
    main()
