                files.append(f)
    except (PermissionError, OSError):
        pass
    return files

def remove_files(files):
    deleted = []
    for f in files:
        try:
            filepath = os.path.abspath(str(f))
            if os.path.exists(filepath) and os.access(filepath, os.W_OK):
                os.remove(filepath)
