import os
import zipfile
from pathlib import Path
from typing import List, Set

def archive_files(start_path: str, archive_name: str, patterns: Set[str], exclude_dirs: Set[str] = None) -> None:
    if not os.path.isdir(start_path):
        raise ValueError("Start path must be a valid directory")

    if not archive_name.endswith('.zip'):
        archive_name += '.zip'

    exclude_dirs = exclude_dirs or set()
    matched_files: List[str] = []

    start_path = os.path.abspath(start_path)

    for root, dirs, files in os.walk(start_path, followlinks=False):
        dirs[:] = [d for d in dirs if d not in exclude_dirs]

        for file in files:
            if any(file.endswith(pattern) for pattern in patterns):
                full_path = os.path.join(root, file)
                matched_files.append(full_path)

    with zipfile.ZipFile(archive_name, 'w', zipfile.ZIP_DEFLATED) as archive:
        for file_path in matched_files:
            rel_path = os.path.relpath(file_path, start_path)
            if os.path.getsize(file_path) > 0:
                archive.write(file_path, rel_path)
