def get_size(size):
    sizes = {
        'small': (400, 300),
        'medium': (800, 600),
        'large': (1200, 900)
    }
    return sizes.get(size.lower())

def resize_img(path, size):
    if not os.path.exists(path) or not size:
        return
    if not path.lower().endswith(('.png', '.jpg', '.jpeg', '.gif', '.bmp')):
        return
    try:
        with Image.open(path) as img:
            resized = img.resize(size, Image.Resampling.LANCZOS)
            resized.save(path, quality=95, optimize=True)
    except Exception:
        return

