import os
import sys
import requests
import zipfile
import tarfile
import hashlib
import tempfile
from pathlib import Path
from urllib.parse import urlparse

class PackageDownloader:
    def __init__(self, package_name, version=None):
        self.package_name = package_name
        self.version = version
        self.pypi_url = "https://pypi.org/pypi"
        self.temp_dir = tempfile.mkdtemp()

    def get_package_info(self):
        url = f"{self.pypi_url}/{self.package_name}/json"
        response = requests.get(url, timeout=30)
        response.raise_for_status()
        return response.json()

    def verify_hash(self, file_path, expected_hash):
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest() == expected_hash

    def download_package(self):
        info = self.get_package_info()
        if self.version:
            release_info = info['releases'][self.version]
        else:
            release_info = info['releases'][info['info']['version']]

        for release in release_info:
            if release['packagetype'] == 'sdist':
                url = release['url']
                expected_hash = release['digests']['sha256']
                break

        download_path = Path(self.temp_dir) / os.path.basename(urlparse(url).path)

        response = requests.get(url, stream=True, timeout=30)
        response.raise_for_status()

        with open(download_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        if not self.verify_hash(download_path, expected_hash):
            raise ValueError("Package hash verification failed")

        return download_path

    def extract_package(self, package_path):
        extract_dir = Path(self.temp_dir) / 'extracted'
        os.makedirs(extract_dir, exist_ok=True)

        if tarfile.is_tarfile(package_path):
            with tarfile.open(package_path) as tar:
                def is_safe(member):
                    return not os.path.isabs(member.name) and '..' not in member.name
                members = [m for m in tar.getmembers() if is_safe(m)]
                tar.extractall(path=extract_dir, members=members)
        elif zipfile.is_zipfile(package_path):
            with zipfile.ZipFile(package_path) as zip_file:
                for member in zip_file.namelist():
                    if os.path.isabs(member) or '..' in member:
                        continue
                    zip_file.extract(member, extract_dir)

        return extract_dir

    def cleanup(self):
        if os.path.exists(self.temp_dir):
            for root, dirs, files in os.walk(self.temp_dir, topdown=False):
                for name in files:
                    os.remove(os.path.join(root, name))
                for name in dirs:
                    os.rmdir(os.path.join(root, name))
            os.rmdir(self.temp_dir)

    def download_and_extract(self):
        try:
            package_path = self.download_package()
            extract_path = self.extract_package(package_path)
            return extract_path
        except Exception as e:
            self.cleanup()
            raise e
