from dataclasses import dataclass
import boto3
import os
from typing import Dict, List
import yaml
from botocore.exceptions import ClientError
from cryptography.fernet import Fernet

@dataclass
class Environment:
    name: str
    aws_role: str
    required_approvals: int

class DeploymentSystem:
    def __init__(self, config_path: str, key_path: str):
        self.environments = self._load_environments(config_path)
        self.fernet = Fernet(self._load_key(key_path))
        self.sts = boto3.client('sts')

    def _load_environments(self, path: str) -> Dict[str, Environment]:
        with open(path, 'r') as f:
            config = yaml.safe_load(f)
            return {
                name: Environment(
                    name=name,
                    aws_role=env['role'],
                    required_approvals=env['approvals']
                )
                for name, env in config['environments'].items()
            }

    def _load_key(self, path: str) -> bytes:
        if not os.path.exists(path):
            key = Fernet.generate_key()
            with open(path, 'wb') as f:
                f.write(key)
        with open(path, 'rb') as f:
            return f.read()

    def _assume_role(self, role_arn: str) -> Dict:
        try:
            response = self.sts.assume_role(
                RoleArn=role_arn,
                RoleSessionName='deployment-session',
                DurationSeconds=3600
            )
            return response['Credentials']
        except ClientError:
            raise PermissionError(f"Failed to assume role {role_arn}")

    def deploy(self, app_name: str, env_name: str, approvals: List[str]) -> bool:
        if env_name not in self.environments:
            raise ValueError(f"Unknown environment: {env_name}")

        env = self.environments[env_name]
        if len(set(approvals)) < env.required_approvals:
            raise PermissionError(f"Insufficient approvals for {env_name}")

        credentials = self._assume_role(env.aws_role)
        session = boto3.Session(
            aws_access_key_id=credentials['AccessKeyId'],
            aws_secret_access_key=credentials['SecretAccessKey'],
            aws_session_token=credentials['SessionToken']
        )

        try:
            ecs = session.client('ecs')
            ecs.update_service(
                cluster=f"{env_name}-cluster",
                service=app_name,
                forceNewDeployment=True
            )
            return True
        except ClientError:
            return False

    def encrypt_secret(self, secret: str) -> bytes:
        return self.fernet.encrypt(secret.encode())

    def decrypt_secret(self, encrypted: bytes) -> str:
        return self.fernet.decrypt(encrypted).decode()
