class Game:
    def __init__(self):
        self.score = 0
        self.scores_file = Path("highscores.json")
        self.high_scores = self.load_scores()

    def load_scores(self):
        if self.scores_file.exists():
            with open(self.scores_file, "r") as f:
                return json.load(f)
        return []

    def save_score(self):
        score_entry = {
            "score": self.score,
            "date": time.strftime("%Y-%m-%d %H:%M:%S")
        }
        self.high_scores.append(score_entry)
        self.high_scores.sort(key=lambda x: x["score"], reverse=True)
        self.high_scores = self.high_scores[:10]

        with open(self.scores_file, "w") as f:
            json.dump(self.high_scores, f)

    def play(self):
        self.score = 0
        while True:
            command = input("Press 'a' to add points, 'q' to quit: ").lower()
            if command == 'a':
                self.score += 10
                print(f"Score: {self.score}")
            elif command == 'q':
                self.save_score()
                break

    def show_high_scores(self):
        print("\nHigh Scores:")
        for i, entry in enumerate(self.high_scores, 1):
            print(f"{i}. Score: {entry['score']} - Date: {entry['date']}")

