        if not os.path.exists(repo_path):
            os.makedirs(repo_path)
        if not os.path.exists(self.version_file):
            self._save_versions({})
        if not os.path.exists(self.checkout_file):
            self._save_checkouts({})

    def _load_versions(self):
        with open(self.version_file, 'r') as f:
            return json.load(f)

    def _save_versions(self, versions):
        with open(self.version_file, 'w') as f:
            json.dump(versions, f)

    def _load_checkouts(self):
        with open(self.checkout_file, 'r') as f:
            return json.load(f)

    def _save_checkouts(self, checkouts):
        with open(self.checkout_file, 'w') as f:
            json.dump(checkouts, f)

    def _hash_file(self, filepath):
        sha256 = hashlib.sha256()
        with open(filepath, 'rb') as f:
            for block in iter(lambda: f.read(4096), b''):
                sha256.update(block)
        return sha256.hexdigest()

    def checkout(self, filepath, user):
        checkouts = self._load_checkouts()
        if filepath in checkouts:
            raise Exception(f"File already checked out by {checkouts[filepath]}")
        checkouts[filepath] = user
        self._save_checkouts(checkouts)
        return True

    def checkin(self, filepath, user):
        checkouts = self._load_checkouts()
        if filepath not in checkouts or checkouts[filepath] != user:
            raise Exception("File not checked out by user")

        versions = self._load_versions()
        file_hash = self._hash_file(filepath)

        if filepath not in versions:
            versions[filepath] = []

        versions[filepath].append({
            'hash': file_hash,
            'timestamp': datetime.now().isoformat(),
            'user': user
        })

        self._save_versions(versions)
        del checkouts[filepath]
        self._save_checkouts(checkouts)
        return True

    def get_history(self, filepath):
        versions = self._load_versions()
        return versions.get(filepath, [])

    def revert(self, filepath, version_hash):
        versions = self._load_versions()
        if filepath not in versions:
            raise Exception("File not found in version control")

        version = next((v for v in versions[filepath] if v['hash'] == version_hash), None)
        if not version:
            raise Exception("Version not found")

        backup_path = f"{filepath}.{version['hash']}"
        shutil.copy2(filepath, backup_path)
        return backup_path
