from urllib.parse import urljoin, urlparse
import time
from collections import deque
import hashlib
import sqlite3

class WebCrawler:
    def __init__(self, base_url):
        self.base_url = base_url
        self.domain = urlparse(base_url).netloc
        self.visited = set()
        self.queue = deque([base_url])
        self.db = sqlite3.connect('crawled_pages.db')
        self.cursor = self.db.cursor()
        self.cursor.execute('''CREATE TABLE IF NOT EXISTS pages
                          (url TEXT PRIMARY KEY, content TEXT, hash TEXT)''')

    def is_valid(self, url):
        parsed = urlparse(url)
        return bool(parsed.netloc) and parsed.netloc.endswith(self.domain)

    def get_page_hash(self, content):
        return hashlib.sha256(content.encode('utf-8')).hexdigest()

    def store_page(self, url, content):
        page_hash = self.get_page_hash(content)
        self.cursor.execute('INSERT OR REPLACE INTO pages VALUES (?, ?, ?)',
                          (url, content, page_hash))
        self.db.commit()

    def crawl(self, max_pages=100):
        while self.queue and len(self.visited) < max_pages:
            url = self.queue.popleft()

            if url in self.visited:
                continue

            try:
                headers = {'User-Agent': 'Mozilla/5.0 (compatible; MyCrawler/1.0)'}
                response = requests.get(url, headers=headers, timeout=10)
                response.raise_for_status()

                self.visited.add(url)
                self.store_page(url, response.text)

                soup = BeautifulSoup(response.text, 'html.parser')
                for link in soup.find_all('a'):
                    href = link.get('href')
                    if href:
                        full_url = urljoin(url, href)
                        if self.is_valid(full_url) and full_url not in self.visited:
                            self.queue.append(full_url)

                time.sleep(1)

            except Exception:
                continue

        self.db.close()
