from datetime import datetime
import uuid
from decimal import Decimal
from typing import Dict, List

class Project:
    def __init__(self, title: str, goal: Decimal, deadline: datetime, creator: str):
        self.id = str(uuid.uuid4())
        self.title = title
        self.goal = goal
        self.deadline = deadline
        self.creator = creator
        self.current_amount = Decimal('0')
        self.backers: Dict[str, Decimal] = {}
        self.is_active = True

    def add_contribution(self, backer: str, amount: Decimal) -> bool:
        if not self.is_active or datetime.now() > self.deadline:
            return False

        if amount <= Decimal('0'):
            return False

        if backer in self.backers:
            self.backers[backer] += amount
        else:
            self.backers[backer] = amount

        self.current_amount += amount
        return True

    def refund_contribution(self, backer: str) -> bool:
        if backer not in self.backers:
            return False

        amount = self.backers[backer]
        del self.backers[backer]
        self.current_amount -= amount
        return True

    def close_project(self) -> bool:
        if not self.is_active:
            return False

        self.is_active = False
        return True

class CrowdfundingPlatform:
    def __init__(self):
        self.projects: Dict[str, Project] = {}

    def create_project(self, title: str, goal: Decimal, deadline: datetime, creator: str) -> str:
        if goal <= Decimal('0'):
            raise ValueError("Goal must be positive")

        if deadline <= datetime.now():
            raise ValueError("Deadline must be in the future")

        project = Project(title, goal, deadline, creator)
        self.projects[project.id] = project
        return project.id

    def contribute(self, project_id: str, backer: str, amount: Decimal) -> bool:
        if project_id not in self.projects:
            return False

        return self.projects[project_id].add_contribution(backer, amount)

    def get_project_status(self, project_id: str) -> Dict:
        if project_id not in self.projects:
            raise ValueError("Project not found")

        project = self.projects[project_id]
        return {
            "id": project.id,
            "title": project.title,
            "goal": project.goal,
            "current_amount": project.current_amount,
            "deadline": project.deadline,
            "is_active": project.is_active,
            "backer_count": len(project.backers)
        }

    def list_active_projects(self) -> List[str]:
        return [pid for pid, p in self.projects.items() if p.is_active]
