import os
import shutil
import stat
from pathlib import Path

def copy_files(src_dir, dst_dir, permissions):
    if not os.path.exists(src_dir) or not os.path.isdir(src_dir):
        raise ValueError("Source directory does not exist")

    if not os.path.exists(dst_dir):
        os.makedirs(dst_dir, mode=0o700)

    try:
        permissions_octal = int(str(permissions), 8)
    except ValueError:
        raise ValueError("Invalid permissions format")

    if permissions_octal > 0o777:
        raise ValueError("Invalid permissions value")

    src_path = Path(src_dir).resolve()
    dst_path = Path(dst_dir).resolve()

    if not dst_path.is_relative_to(src_path) and not src_path.is_relative_to(dst_path):
        for item in os.listdir(src_dir):
            src_item = os.path.join(src_dir, item)
            dst_item = os.path.join(dst_dir, item)

            if os.path.isfile(src_item):
                shutil.copy2(src_item, dst_item)
                os.chmod(dst_item, permissions_octal)
    else:
        raise ValueError("Source and destination paths overlap")

if __name__ == "__main__":
    src_directory = input("Enter source directory: ").strip()
    dst_directory = input("Enter destination directory: ").strip()
    file_permissions = input("Enter file permissions (octal): ").strip()

    copy_files(src_directory, dst_directory, file_permissions)

