from moviepy.editor import VideoFileClip, concatenate_videoclips, vfx

class VideoEditor:
    def __init__(self):
        self.clips = []
        self.transitions = []
        self.filters = []

    def add_clip(self, filepath):
        clip = VideoFileClip(filepath)
        self.clips.append(clip)

    def add_transition(self, transition_type, duration=1.0):
        self.transitions.append({
            'type': transition_type,
            'duration': duration
        })

    def add_filter(self, filter_type, params=None):
        self.filters.append({
            'type': filter_type,
            'params': params or {}
        })

    def apply_transition(self, clip1, clip2, transition):
        if transition['type'] == 'fade':
            return clip1.crossfadein(transition['duration'])
        elif transition['type'] == 'slide':
            return clip1.slide_in(transition['duration'], 'right')
        return clip1

    def apply_filter(self, clip, filter_):
        if filter_['type'] == 'grayscale':
            return clip.fx(vfx.blackwhite)
        elif filter_['type'] == 'blur':
            return clip.fx(vfx.blur, filter_['params'].get('radius', 1))
        elif filter_['type'] == 'bright':
            return clip.fx(vfx.colorx, filter_['params'].get('factor', 1.5))
        return clip

    def render(self, output_path):
        final_clips = []
        for i, clip in enumerate(self.clips):
            for filter_ in self.filters:
                clip = self.apply_filter(clip, filter_)
            if i < len(self.transitions):
                clip = self.apply_transition(clip, self.clips[i+1], self.transitions[i])
            final_clips.append(clip)

        final_video = concatenate_videoclips(final_clips)
        final_video.write_videofile(output_path)

def main():
    editor = VideoEditor()
    editor.add_clip("video1.mp4")
    editor.add_clip("video2.mp4")
    editor.add_transition('fade', 1.5)
    editor.add_filter('grayscale')
    editor.add_filter('blur', {'radius': 2})
    editor.render("output.mp4")

if __name__ == "__main__":
    main()
