import tarfile
import os
import shutil

def extract_and_move(tarball):
    if not os.path.exists(tarball) or not tarfile.is_tarfile(tarball):
        raise ValueError("Invalid or missing tarball")

    safe_dir = os.path.abspath(os.path.dirname(tarball))
    tar = tarfile.open(tarball)

    members = tar.getmembers()
    for member in members:
        if member.isdev() or member.islnk() or member.issym():
            continue
        if not os.path.abspath(os.path.join(safe_dir, member.name)).startswith(safe_dir):
            continue
        if '..' in member.name:
            continue
        tar.extract(member, safe_dir)
    tar.close()

    img_dir = os.path.join(safe_dir, tarball.split('.')[0])
    if not os.path.exists(img_dir):
        raise ValueError("Extraction directory not found")

