import os
from git import Repo
import re

repo = Repo('/path/to/repo')

def rename_branch(old_name, new_name):
    if not re.match('^[a-zA-Z0-9_-]+$', old_name) or not re.match('^[a-zA-Z0-9_-]+$', new_name):
        raise ValueError('Invalid branch name')
    if not repo.heads:
        raise ValueError('No branches found')
    if old_name not in [head.name for head in repo.heads]:
        raise ValueError('Source branch does not exist')
    if new_name in [head.name for head in repo.heads]:
        raise ValueError('Target branch already exists')
    repo.git.branch('-m', old_name, new_name)

