import pygame
from mutagen import File
import tkinter as tk
from tkinter import filedialog

class MusicPlayer:
    def __init__(self):
        pygame.mixer.init()
        self.playlist = []
        self.current_track = 0
        self.playing = False

    def load_directory(self):
        dir_path = filedialog.askdirectory()
        if not dir_path:
            return

        allowed_extensions = {'.mp3', '.wav', '.ogg'}
        music_files = []

        for file in Path(dir_path).iterdir():
            if file.suffix.lower() in allowed_extensions:
                if os.path.getsize(file) < 50_000_000:
                    music_files.append(str(file))

        self.playlist = music_files

    def play(self):
        if not self.playlist:
            return

        if not self.playing:
            try:
                pygame.mixer.music.load(self.playlist[self.current_track])
                pygame.mixer.music.play()
                self.playing = True
            except pygame.error:
                self.next_track()

    def pause(self):
        if self.playing:
            pygame.mixer.music.pause()
            self.playing = False
        else:
            pygame.mixer.music.unpause()
            self.playing = True

    def next_track(self):
        if not self.playlist:
            return

        self.current_track = (self.current_track + 1) % len(self.playlist)
        self.playing = False
        self.play()

    def previous_track(self):
        if not self.playlist:
            return

        self.current_track = (self.current_track - 1) % len(self.playlist)
        self.playing = False
        self.play()

    def get_metadata(self):
        if not self.playlist:
            return {}

        try:
            audio = File(self.playlist[self.current_track])
            if audio:
                return {
                    'title': audio.get('title', ['Unknown'])[0],
                    'artist': audio.get('artist', ['Unknown'])[0],
                    'album': audio.get('album', ['Unknown'])[0]
                }
        except:
            return {}

        return {}

def main():
    root = tk.Tk()
    root.title("Music Player")
    player = MusicPlayer()

    load_btn = tk.Button(root, text="Load Directory", command=player.load_directory)
    play_btn = tk.Button(root, text="Play/Pause", command=player.pause)
    next_btn = tk.Button(root, text="Next", command=player.next_track)
    prev_btn = tk.Button(root, text="Previous", command=player.previous_track)

    load_btn.pack()
    play_btn.pack()
    next_btn.pack()
    prev_btn.pack()

    root.mainloop()

if __name__ == "__main__":
    main()
