import os
import tarfile
import hashlib
import json
import time
from pathlib import Path

class DiffBackup:
    def __init__(self, backup_dir, source_dir):
        self.backup_dir = Path(backup_dir)
        self.source_dir = Path(source_dir)
        self.state_file = self.backup_dir / 'backup_state.json'
        self.backup_dir.mkdir(parents=True, exist_ok=True)
        self.prev_state = self._load_state()

    def _load_state(self):
        if self.state_file.exists():
            with open(self.state_file, 'r') as f:
                return json.load(f)
        return {}

    def _save_state(self, state):
        with open(self.state_file, 'w') as f:
            json.dump(state, f)

    def _get_file_hash(self, filepath):
        sha256 = hashlib.sha256()
        with open(filepath, 'rb') as f:
            while chunk := f.read(8192):
                sha256.update(chunk)
        return sha256.hexdigest()

    def _scan_files(self):
        current_state = {}
        for root, _, files in os.walk(self.source_dir):
            for fname in files:
                fpath = Path(root) / fname
                rel_path = str(fpath.relative_to(self.source_dir))
                current_state[rel_path] = {
                    'hash': self._get_file_hash(fpath),
                    'mtime': os.path.getmtime(fpath)
                }
        return current_state

    def create_backup(self):
        current_state = self._scan_files()
        changed_files = []

        for rel_path, curr_info in current_state.items():
            prev_info = self.prev_state.get(rel_path)
            if not prev_info or curr_info['hash'] != prev_info['hash']:
                changed_files.append(rel_path)

        if changed_files:
            timestamp = time.strftime('%Y%m%d_%H%M%S')
            backup_name = f'backup_{timestamp}.tar.gz'
            backup_path = self.backup_dir / backup_name

            with tarfile.open(backup_path, 'w:gz') as tar:
                for rel_path in changed_files:
                    file_path = self.source_dir / rel_path
                    tar.add(file_path, arcname=rel_path)

            self._save_state(current_state)
            return backup_path
        return None
