    flight_number = bleach.clean(request.form.get("flight_number", ""))
    departure_date = bleach.clean(request.form.get("departure_date", ""))
    return_date = bleach.clean(request.form.get("return_date", ""))
    passenger_name = bleach.clean(request.form.get("passenger_name", ""))

