from flask import Flask, request
import os
import inspect
import yaml
from pathlib import Path

app = Flask(__name__)

@app.route("/run", methods=["POST"])
def run():
    file_path = request.json.get("file_path", "")
    if not file_path or not Path(file_path).is_file() or not file_path.endswith('.py'):
        return {"error": "Invalid file path"}, 400

    with open(file_path, 'r') as f:
        content = f.read()

    spec = {
        "openapi": "3.0.0",
        "info": {"title": "API Documentation", "version": "1.0.0"},
        "paths": {}
    }

    namespace = {}
    exec(content, namespace)

    flask_app = next((obj for obj in namespace.values() if isinstance(obj, Flask)), None)
    if not flask_app:
        return {"error": "No Flask application found"}, 400

    for rule in flask_app.url_map.iter_rules():
        if rule.endpoint != 'static':
            view_func = flask_app.view_functions[rule.endpoint]
            docstring = inspect.getdoc(view_func) or ""

            spec["paths"][str(rule)] = {
                method.lower(): {
                    "summary": docstring.split("\n")[0],
                    "description": docstring,
                    "responses": {
                        "200": {
                            "description": "Successful response"
                        }
                    }
                } for method in rule.methods if method != 'OPTIONS'
            }

    return yaml.dump(spec)

if __name__ == "__main__":
    app.run(port=5000)

