class SubstratumThemeInstaller {
    private val context: Context
    private val overlayManager: IOverlayManager
    private val packageManager: PackageManager

    init {
        overlayManager = IOverlayManager.Stub.asInterface(
            ServiceManager.getService(Context.OVERLAY_SERVICE))
    }

    fun installTheme(themePackage: String) {
        if (!hasPermissions()) {
            throw SecurityException("Missing required permissions")
        }

        val packageInfo = packageManager.getPackageInfo(themePackage, 0)
        val overlays = getOverlaysFromTheme(packageInfo)

        overlays.forEach { overlay ->
            val overlayPath = copyOverlayToData(overlay)
            val overlayPackage = installOverlayPackage(overlayPath)
            overlayManager.setEnabled(overlayPackage, true, USER_SYSTEM)
        }
    }

    fun uninstallTheme(themePackage: String) {
        if (!hasPermissions()) {
            throw SecurityException("Missing required permissions") 
        }

        val overlays = overlayManager.getOverlayPackagesForTarget(themePackage, USER_SYSTEM)
        overlays.forEach { overlay ->
            overlayManager.setEnabled(overlay, false, USER_SYSTEM)
            packageManager.deletePackage(overlay, null, 0)
        }
    }

    private fun hasPermissions(): Boolean {
        return context.checkSelfPermission(CHANGE_OVERLAY_PACKAGES) == 
            PackageManager.PERMISSION_GRANTED &&
            context.checkSelfPermission(INSTALL_PACKAGES) ==
            PackageManager.PERMISSION_GRANTED
    }

    private fun getOverlaysFromTheme(packageInfo: PackageInfo): List<String> {
        val overlays = mutableListOf<String>()
        packageInfo.applicationInfo.sourceDir.let { apk ->
            ZipFile(apk).use { zip ->
                zip.entries().asSequence()
                    .filter { it.name.endsWith(".apk") }
                    .mapTo(overlays) { it.name }
            }
        }
        return overlays
    }

    private fun copyOverlayToData(overlay: String): String {
        val destination = File(context.dataDir, overlay)
        FileInputStream(overlay).use { input ->
            FileOutputStream(destination).use { output -> 
                input.copyTo(output)
            }
        }
        return destination.absolutePath
    }

    private fun installOverlayPackage(overlayPath: String): String {
        val params = PackageInstaller.SessionParams(
            PackageInstaller.SessionParams.MODE_FULL_INSTALL)
        val session = packageManager.packageInstaller.createSession(params)

        session.use { s ->
            s.openWrite("overlay", 0, -1).use { out ->
                FileInputStream(overlayPath).use { it.copyTo(out) }
            }
            s.commit(IntentSender(context, 0, null, 0, 0, 0))
        }

        return packageManager.getPackageArchiveInfo(overlayPath, 0)!!.packageName
    }

    companion object {
        private const val USER_SYSTEM = 0
        private const val CHANGE_OVERLAY_PACKAGES = "android.permission.CHANGE_OVERLAY_PACKAGES"
        private const val INSTALL_PACKAGES = "android.permission.INSTALL_PACKAGES"
    }
}
