def download_file(url):
    fname = Path(os.path.basename(url)).name
    headers = {'User-Agent': 'Mozilla/5.0'}
    try:
        r = requests.get(url, stream=True, headers=headers, timeout=10, verify=True)
        r.raise_for_status()
        with open(fname, 'wb') as f:
            for chunk in r.iter_content(chunk_size=8192):
                f.write(chunk)
        return fname
    except requests.exceptions.RequestException:
        if os.path.exists(fname):
            os.remove(fname)
        raise

def extract_tar(tar_file):
    extract_path = Path.cwd()
    try:
        with tarfile.open(tar_file) as tar:
            members = [m for m in tar.getmembers() 
                      if os.path.abspath(os.path.join(extract_path, m.name)).startswith(str(extract_path))]
            tar.extractall(path=extract_path, members=members)
    except tarfile.TarError:
        if os.path.exists(tar_file):
            os.remove(tar_file)
        raise

def main():
    url = get_url()
    tar_file = download_file(url)
    extract_tar(tar_file)
    macosx = Path("__MACOSX")
    if macosx.exists():
        shutil.rmtree(macosx)
    if os.path.exists(tar_file):
