def find_large_files(dirpath, threshold):
    files = []
    try:
        dirpath = os.path.abspath(dirpath)
        for f in Path(dirpath).glob('**/*'):
            if f.is_file() and not f.is_symlink():
                try:
                    if f.stat().st_size > threshold:
                        files.append(f)
                except (PermissionError, OSError):
                    continue
    except (PermissionError, OSError):
        pass
    return files

def remove_large_files(files):
    removed = 0
    for f in files:
        try:
            filepath = os.path.abspath(str(f))
            if os.path.exists(filepath) and os.path.isfile(filepath):
                os.chmod(filepath, stat.S_IWRITE)
                os.remove(filepath)
                removed += 1
        except (PermissionError, OSError):
            continue
    return removed

def secure_path(path):
