import os
from pathlib import Path
import secrets
import string

class NoteTaker:
    def __init__(self):
        self.notes_dir = Path("notes")
        self.notes_dir.mkdir(exist_ok=True)

    def generate_filename(self):
        chars = string.ascii_letters + string.digits
        return ''.join(secrets.choice(chars) for _ in range(16)) + '.txt'

    def save_note(self, content):
        filename = self.generate_filename()
        filepath = self.notes_dir / filename
        try:
            with open(filepath, 'w', encoding='utf-8') as f:
                f.write(content)
            return filename
        except IOError:
            return None

    def read_note(self, filename):
        filepath = self.notes_dir / filename
        if not filepath.is_relative_to(self.notes_dir):
            return None
        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                return f.read()
        except IOError:
            return None

    def list_notes(self):
        try:
            return [f.name for f in self.notes_dir.iterdir() if f.is_file()]
        except IOError:
            return []

    def delete_note(self, filename):
        filepath = self.notes_dir / filename
        if not filepath.is_relative_to(self.notes_dir):
            return False
        try:
            filepath.unlink()
            return True
        except IOError:
            return False

def main():
    app = NoteTaker()
    while True:
        action = input("Choose action (write/read/list/delete/quit): ").lower()
        if action == "write":
            content = input("Enter note content: ")
            filename = app.save_note(content)
            if filename:
                print(f"Note saved as: {filename}")
        elif action == "read":
            filename = input("Enter filename: ")
            content = app.read_note(filename)
            if content:
                print(f"Content: {content}")
        elif action == "list":
            files = app.list_notes()
            for f in files:
                print(f)
        elif action == "delete":
            filename = input("Enter filename: ")
            if app.delete_note(filename):
                print("Note deleted")
        elif action == "quit":
            break

if __name__ == "__main__":
    main()
