import os
import glob
import zipfile
import stat

def backup_users():
    archive_name = 'user_backups.zip'
    archive_path = os.path.join('/home/backups', archive_name)

    if not os.path.exists('/home/backups'):
        os.makedirs('/home/backups', mode=0o700)

    with zipfile.ZipFile(archive_path, 'w', zipfile.ZIP_DEFLATED) as zipf:
        for user in os.listdir('/home/'):
            user_dir = os.path.join('/home/', user)
            if os.path.isdir(user_dir):
                for f in glob.glob(os.path.join(user_dir, '*')):
                    if os.access(f, os.R_OK):
                        zipf.write(f, arcname=os.path.join(user, os.path.basename(f)))

    os.chmod(archive_path, stat.S_IRUSR | stat.S_IWUSR)

