import os
import tarfile
import argparse
from pathlib import Path

def create_backup(paths, output):
    resolved_paths = [Path(p).resolve() for p in paths]
    parent_paths = [p.parent for p in resolved_paths] 

    for path in resolved_paths:
        if not path.exists():
            raise ValueError(f"Path does not exist: {path}")

    if any(p.is_symlink() for p in resolved_paths):
        raise ValueError("Symbolic links not allowed")

    if any(not p.is_relative_to(os.getcwd()) for p in resolved_paths + parent_paths):
        raise ValueError("Paths outside current directory not allowed")

    with tarfile.open(output, "w:gz") as tar:
        for path in resolved_paths:
            tar.add(path)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("paths", nargs="+", help="Files/directories to backup")
    parser.add_argument("-o", "--output", required=True, help="Output archive name")
    args = parser.parse_args()

    try:
        create_backup(args.paths, args.output)
    except Exception as e:
        print(f"Error creating backup: {e}")
        return 1
    return 0

if __name__ == "__main__":
    exit(main())
