import bcrypt
import secrets
from dataclasses import dataclass
from typing import Dict, Optional
from datetime import datetime

@dataclass
class UserProfile:
    username: str
    email: str
    hashed_password: bytes
    settings: Dict
    created_at: datetime
    last_login: Optional[datetime]

class AccountManager:
    def __init__(self):
        self.users: Dict[str, UserProfile] = {}
        self.sessions: Dict[str, str] = {}

    def create_account(self, username: str, email: str, password: str) -> bool:
        if username in self.users:
            return False

        salt = bcrypt.gensalt()
        hashed = bcrypt.hashpw(password.encode(), salt)

        self.users[username] = UserProfile(
            username=username,
            email=email,
            hashed_password=hashed,
            settings={},
            created_at=datetime.now(),
            last_login=None
        )
        return True

    def authenticate(self, username: str, password: str) -> Optional[str]:
        user = self.users.get(username)
        if not user:
            return None

        if bcrypt.checkpw(password.encode(), user.hashed_password):
            session_token = secrets.token_urlsafe(32)
            self.sessions[session_token] = username
            user.last_login = datetime.now()
            return session_token
        return None

    def get_profile(self, session_token: str) -> Optional[UserProfile]:
        username = self.sessions.get(session_token)
        if username:
            return self.users.get(username)
        return None

    def update_settings(self, session_token: str, new_settings: Dict) -> bool:
        user = self.get_profile(session_token)
        if user:
            user.settings.update(new_settings)
            return True
        return False

    def logout(self, session_token: str) -> None:
        if session_token in self.sessions:
            del self.sessions[session_token]
