import os
import shutil
import stat

def copyfiles(src, dst):
    if not os.path.exists(src) or not os.path.isdir(src):
        raise ValueError("Source directory does not exist")
    if not os.path.exists(dst):
        os.makedirs(dst, mode=0o755)
    for f in os.scandir(src):
        s = os.path.abspath(os.path.join(src, f.name))
        d = os.path.abspath(os.path.join(dst, f.name))
        if os.path.commonpath([s, dst]) == dst:
            continue
        if f.is_file():
            shutil.copy2(s, d)
            os.chmod(d, stat.S_IRUSR | stat.S_IWUSR | stat.S_IRGRP | stat.S_IROTH)
        elif f.is_dir():
            copyfiles(s, d)

