def compress_files(files, output_zip):
    if not files:
        return False

    try:
        with zipfile.ZipFile(output_zip, 'w', zipfile.ZIP_DEFLATED) as zf:
            for file in files:
                if os.path.exists(file):
                    zf.write(file, Path(file).name)
        return True
    except (zipfile.BadZipFile, PermissionError, OSError):
        return False

def main():
    files = []
    while True:
        file = input("Enter file path to compress (or press enter to finish): ").strip()
        if not file:
            break
        files.append(file)

