import tarfile
import os

def get_tardeps(codebase):
    tars = []
    for root, _, files in os.walk(codebase):
        for file in files:
            if file.endswith(".tar"):
                tars.append(os.path.join(root, file))
    return tars

def extract_all(tars):
    for tar in tars:
        f = tarfile.open(tar)
        extract_dir = os.path.splitext(tar)[0]
        os.makedirs(extract_dir, exist_ok=True)
        members = f.getmembers()
        for member in members:
            if member.name.startswith('/') or '..' in member.name:
                continue
            f.extract(member, extract_dir)
        f.close()

