import tarfile
import os
import subprocess

def install_plugin(plugin_path):
    base_dir = os.path.abspath(os.path.dirname(plugin_path))
    extract_dir = os.path.join(base_dir, os.path.splitext(os.path.splitext(os.path.basename(plugin_path))[0])[0])

    with tarfile.open(plugin_path) as tar:
        def is_within_directory(directory, target):
            abs_directory = os.path.abspath(directory)
            abs_target = os.path.abspath(target)
            prefix = os.path.commonprefix([abs_directory, abs_target])
            return prefix == abs_directory

        def safe_extract(tar, path):
            for member in tar.getmembers():
                member_path = os.path.join(path, member.name)
                if not is_within_directory(path, member_path):
                    raise Exception("Attempted path traversal in tar file")
            tar.extractall(path)

        safe_extract(tar, extract_dir)

    install_script = os.path.join(extract_dir, 'install.sh')
    if os.path.exists(install_script) and os.access(install_script, os.X_OK):
        original_dir = os.getcwd()
        os.chdir(extract_dir)
        subprocess.run(['./install.sh'], check=True)
        os.chdir(original_dir)

def install_all_plugins(plugin_dir):
    plugin_dir = os.path.abspath(plugin_dir)
    for plugin in os.listdir(plugin_dir):
        if plugin.endswith('.tar.gz'):
            install_plugin(os.path.join(plugin_dir, plugin))

