import shutil
from pathlib import Path

def extract_genome_data(input_file: Path, output_dir: Path) -> None:
    if not input_file.exists() or not output_dir.exists():
        raise FileNotFoundError("Input file or output directory does not exist")

    safe_filename = Path(input_file.name).stem
    output_file = output_dir / f"{safe_filename}.fasta"

    if input_file.suffix == '.gz':
        with gzip.open(input_file, 'rt') as f_in:
            with open(output_file, 'w') as f_out:
                sequences = SeqIO.parse(f_in, 'fasta')
                SeqIO.write(sequences, f_out, 'fasta')

    elif input_file.suffix in ['.fasta', '.fa']:
        shutil.copy2(input_file, output_file)

    else:
        raise ValueError("Unsupported file format")

def process_genome_directory(input_dir: Path, output_dir: Path) -> None:
    input_dir = Path(input_dir)
    output_dir = Path(output_dir)

    if not input_dir.exists() or not output_dir.exists():
        raise FileNotFoundError("Input or output directory does not exist")

    for file in input_dir.glob('*.gz'):
        extract_genome_data(file, output_dir)

    for file in input_dir.glob('*.fa*'):
        extract_genome_data(file, output_dir)
