from watchdog.events import FileSystemEventHandler

class SyncHandler(FileSystemEventHandler):
    def __init__(self, source_dir, target_dirs):
        self.source_dir = Path(source_dir)
        self.target_dirs = [Path(d) for d in target_dirs]
        self.lock = threading.Lock()

    def on_modified(self, event):
        if event.is_directory:
            return

        src_path = Path(event.src_path)
        if not src_path.exists():
            return

        with self.lock:
            for target_dir in self.target_dirs:
                rel_path = src_path.relative_to(self.source_dir)
                target_path = target_dir / rel_path

                if not target_path.parent.exists():
                    target_path.parent.mkdir(parents=True)

                try:
                    shutil.copy2(src_path, target_path)
                except (OSError, IOError):
                    continue

class FileSync:
    def __init__(self, source_dir, target_dirs):
        self.source_dir = Path(source_dir)
        self.target_dirs = [Path(d) for d in target_dirs]
        self.event_handler = SyncHandler(source_dir, target_dirs)
        self.observer = Observer()

    def start(self):
        self.observer.schedule(self.event_handler, str(self.source_dir), recursive=True)
        self.observer.start()

        try:
            while True:
                time.sleep(1)
        except KeyboardInterrupt:
            self.observer.stop()
        self.observer.join()

    def sync_existing(self):
        for root, _, files in os.walk(self.source_dir):
            for filename in files:
                src_path = Path(root) / filename
                rel_path = src_path.relative_to(self.source_dir)

                for target_dir in self.target_dirs:
                    target_path = target_dir / rel_path
                    if not target_path.parent.exists():
                        target_path.parent.mkdir(parents=True)
                    try:
                        if not target_path.exists() or not self._same_file(src_path, target_path):
                            shutil.copy2(src_path, target_path)
                    except (OSError, IOError):
                        continue

    def _same_file(self, path1, path2):
        if not path2.exists():
            return False

        with open(path1, 'rb') as f1, open(path2, 'rb') as f2:
            return hashlib.sha256(f1.read()).hexdigest() == hashlib.sha256(f2.read()).hexdigest()

if __name__ == "__main__":
