class WebIndexer:
    def __init__(self, db_path='index.db'):
        self.visited = set()
        self.queue = deque()
        self.db_conn = sqlite3.connect(db_path)
        self.init_db()

    def init_db(self):
        cursor = self.db_conn.cursor()
        cursor.execute('''CREATE TABLE IF NOT EXISTS pages 
            (url TEXT PRIMARY KEY, title TEXT, content TEXT)''')
        self.db_conn.commit()

    def is_valid_url(self, url):
        parsed = urlparse(url)
        return bool(parsed.netloc) and bool(parsed.scheme)

    def normalize_url(self, url):
        return re.sub(r'[#?].*$', '', url.strip('/'))

    def get_page_links(self, soup, base_url):
        links = set()
        for link in soup.find_all('a'):
            href = link.get('href')
            if href:
                url = urljoin(base_url, href)
                if self.is_valid_url(url):
                    links.add(self.normalize_url(url))
        return links

    def process_page(self, url):
        try:
            headers = {'User-Agent': 'Mozilla/5.0'}
            response = requests.get(url, headers=headers, timeout=10)
            response.raise_for_status()

            soup = BeautifulSoup(response.text, 'html.parser')
            title = soup.title.string if soup.title else ''
            content = ' '.join(p.get_text() for p in soup.find_all('p'))

            cursor = self.db_conn.cursor()
            cursor.execute('INSERT OR REPLACE INTO pages VALUES (?, ?, ?)',
                         (url, title, content))
            self.db_conn.commit()

            return self.get_page_links(soup, url)

        except Exception:
            return set()

    def crawl(self, start_urls, max_pages=100):
        self.queue.extend(start_urls)

        with ThreadPoolExecutor(max_workers=5) as executor:
            while self.queue and len(self.visited) < max_pages:
                url = self.queue.popleft()
                if url not in self.visited:
                    self.visited.add(url)
                    new_links = executor.submit(self.process_page, url).result()
                    self.queue.extend(link for link in new_links 
                                    if link not in self.visited)

    def search(self, query):
        cursor = self.db_conn.cursor()
        cursor.execute('''SELECT url, title FROM pages 
                         WHERE content LIKE ? OR title LIKE ?''',
                      (f'%{query}%', f'%{query}%'))
        return cursor.fetchall()

    def close(self):
        self.db_conn.close()
