import os
import tarfile
import hashlib
import json
import sys
from datetime import datetime
from pathlib import Path

def get_file_hash(filepath):
    sha256 = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            sha256.update(chunk)
    return sha256.hexdigest()

def create_manifest(dir_path):
    manifest = {}
    for root, _, files in os.walk(dir_path):
        for filename in files:
            filepath = os.path.join(root, filename)
            relpath = os.path.relpath(filepath, dir_path)
            manifest[relpath] = {
                'hash': get_file_hash(filepath),
                'mtime': os.path.getmtime(filepath)
            }
    return manifest

def load_previous_manifest(manifest_path):
    try:
        with open(manifest_path, 'r') as f:
            return json.load(f)
    except FileNotFoundError:
        return {}

def create_backup(source_dir, backup_dir):
    source_path = Path(source_dir).resolve()
    backup_path = Path(backup_dir).resolve()
    backup_path.mkdir(parents=True, exist_ok=True)

    manifest_path = backup_path / 'manifest.json'
    previous_manifest = load_previous_manifest(manifest_path)
    current_manifest = create_manifest(source_path)

    timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    backup_name = f'backup_{timestamp}.tar.gz'
    backup_file = backup_path / backup_name

    changed_files = []
    for filepath, file_info in current_manifest.items():
        if (filepath not in previous_manifest or 
            previous_manifest[filepath]['hash'] != file_info['hash']):
            changed_files.append(filepath)

    if changed_files:
        with tarfile.open(backup_file, 'w:gz') as tar:
            for filepath in changed_files:
                full_path = source_path / filepath
                tar.add(full_path, arcname=filepath)

        with open(manifest_path, 'w') as f:
            json.dump(current_manifest, f, indent=2)

        return len(changed_files)
    return 0

if __name__ == '__main__':
    if len(sys.argv) != 3:
        sys.exit("Usage: script.py source_dir backup_dir")

    source_dir = sys.argv[1]
    backup_dir = sys.argv[2]

    changed = create_backup(source_dir, backup_dir)
    sys.exit(0 if changed >= 0 else 1)
