import hashlib
import sqlite3
import requests
from datetime import datetime
from urllib.parse import urlparse

class PageMonitor:
    def __init__(self, db_path):
        self.conn = sqlite3.connect(db_path)
        self.conn.execute('''CREATE TABLE IF NOT EXISTS pages 
            (url TEXT PRIMARY KEY, hash TEXT, last_check TIMESTAMP)''')
        self.conn.execute('''CREATE TABLE IF NOT EXISTS changes
            (url TEXT, old_hash TEXT, new_hash TEXT, detected_at TIMESTAMP)''')

    def add_page(self, url):
        parsed = urlparse(url)
        if not all([parsed.scheme, parsed.netloc]):
            raise ValueError("Invalid URL")

        response = requests.get(url, timeout=30)
        response.raise_for_status()
        content_hash = hashlib.sha256(response.content).hexdigest()

        self.conn.execute(
            "INSERT OR REPLACE INTO pages VALUES (?, ?, ?)",
            (url, content_hash, datetime.utcnow())
        )
        self.conn.commit()

    def check_pages(self):
        pages = self.conn.execute("SELECT url, hash FROM pages").fetchall()
        changes = []

        for url, old_hash in pages:
            response = requests.get(url, timeout=30)
            new_hash = hashlib.sha256(response.content).hexdigest()

            if new_hash != old_hash:
                self.conn.execute(
                    "INSERT INTO changes VALUES (?, ?, ?, ?)",
                    (url, old_hash, new_hash, datetime.utcnow())
                )
                self.conn.execute(
                    "UPDATE pages SET hash = ?, last_check = ? WHERE url = ?",
                    (new_hash, datetime.utcnow(), url)
                )
                changes.append(url)

