import tarfile
import shutil
from pathlib import Path

def extract_zip(zip_path, extract_path):
    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        zip_ref.extractall(path=extract_path)

def extract_tar(tar_path, extract_path):
    with tarfile.open(tar_path, 'r:*') as tar_ref:
        tar_ref.extractall(path=extract_path)

def extract_7z(archive_path, extract_path):
    import py7zr
    with py7zr.SevenZipFile(archive_path, 'r') as sz:
        sz.extractall(extract_path)

def extract_rar(rar_path, extract_path):
    import rarfile
    with rarfile.RarFile(rar_path) as rf:
        rf.extractall(extract_path)

def extract_archive(archive_path, extract_path):
    archive_path = Path(archive_path)
    extract_path = Path(extract_path)

    if not archive_path.exists():
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    os.makedirs(extract_path, exist_ok=True)

    ext = archive_path.suffix.lower()

    if ext == '.zip':
        extract_zip(archive_path, extract_path)
    elif ext in ('.tar', '.gz', '.bz2', '.xz'):
        extract_tar(archive_path, extract_path)
    elif ext == '.7z':
        extract_7z(archive_path, extract_path) 
    elif ext == '.rar':
        extract_rar(archive_path, extract_path)
    else:
        raise ValueError(f"Unsupported archive format: {ext}")

def cleanup(path):
    shutil.rmtree(path)
