             location TEXT, notes TEXT)''')
        self.conn.commit()

    def add_event(self, title, date, location, notes):
        if not all(isinstance(x, str) for x in [title, date, location, notes]):
            raise ValueError("All inputs must be strings")

        if not re.match(r'^\d{4}-\d{2}-\d{2}$', date):
            raise ValueError("Date must be in YYYY-MM-DD format")

        title = title.strip()
        location = location.strip()
        notes = notes.strip()

        if not all(len(x) <= 500 for x in [title, location, notes]):
            raise ValueError("Input fields cannot exceed 500 characters")

        self.cursor.execute('''INSERT INTO events (title, date, location, notes)
            VALUES (?, ?, ?, ?)''', (title, date, location, notes))
        self.conn.commit()

    def get_events(self, date):
        if not re.match(r'^\d{4}-\d{2}-\d{2}$', date):
            raise ValueError("Date must be in YYYY-MM-DD format")

        self.cursor.execute('SELECT * FROM events WHERE date = ?', (date,))
        return self.cursor.fetchall()

    def delete_event(self, event_id):
        if not isinstance(event_id, int):
            raise ValueError("Event ID must be an integer")

        self.cursor.execute('DELETE FROM events WHERE id = ?', (event_id,))
        self.conn.commit()

    def update_event(self, event_id, title, date, location, notes):
        if not isinstance(event_id, int):
            raise ValueError("Event ID must be an integer")

        if not all(isinstance(x, str) for x in [title, date, location, notes]):
            raise ValueError("All inputs must be strings")

        if not re.match(r'^\d{4}-\d{2}-\d{2}$', date):
            raise ValueError("Date must be in YYYY-MM-DD format")

        title = title.strip()
        location = location.strip() 
