from typing import Dict, List
from dataclasses import dataclass
import os
import subprocess
import yaml
from cryptography.fernet import Fernet
from pathlib import Path

@dataclass
class Environment:
    name: str
    permission_level: int
    allowed_users: List[str]
    deploy_path: Path

class DeploymentSystem:
    def __init__(self, config_path: str):
        self.key = Fernet.generate_key()
        self.cipher = Fernet(self.key)
        self.environments = self._load_environments(config_path)

    def _load_environments(self, config_path: str) -> Dict[str, Environment]:
        with open(config_path) as f:
            config = yaml.safe_load(f)

        environments = {}
        for env in config['environments']:
            environments[env['name']] = Environment(
                name=env['name'],
                permission_level=env['permission_level'],
                allowed_users=env['allowed_users'],
                deploy_path=Path(env['deploy_path'])
            )
        return environments

    def deploy(self, app_path: str, environment: str, user: str) -> bool:
        if environment not in self.environments:
            raise ValueError(f"Environment {environment} not found")

        env = self.environments[environment]
        if user not in env.allowed_users:
            raise PermissionError(f"User {user} not authorized for {environment}")

        try:
            subprocess.run(
                ['rsync', '-avz', '--delete', app_path, str(env.deploy_path)],
                check=True,
                capture_output=True
            )

            deploy_script = env.deploy_path / 'deploy.sh'
            if deploy_script.exists():
                subprocess.run(
                    ['bash', str(deploy_script)],
                    check=True,
                    capture_output=True
                )
            return True

        except subprocess.CalledProcessError as e:
            raise RuntimeError(f"Deployment failed: {e.stderr.decode()}")

    def encrypt_secrets(self, data: bytes) -> bytes:
        return self.cipher.encrypt(data)

    def decrypt_secrets(self, encrypted_data: bytes) -> bytes:
        return self.cipher.decrypt(encrypted_data)

if __name__ == '__main__':
    deployment = DeploymentSystem('config.yml')
    deployment.deploy('/path/to/app', 'production', 'admin')
