import os
import stat
from pathlib import Path
import argparse

def scan_files(path, size_threshold_mb):
    size_threshold = size_threshold_mb * 1024 * 1024
    large_files = []

    for dirpath, _, filenames in os.walk(path):
        for f in filenames:
            file_path = os.path.join(dirpath, f)
            try:
                if os.path.getsize(file_path) > size_threshold:
                    large_files.append(file_path)
            except (OSError, IOError):
                continue

    return large_files

def process_files(files, should_delete=False, make_readonly=False):
    for file_path in files:
        try:
            if should_delete:
                os.unlink(file_path)
            elif make_readonly:
                current = stat.S_IMODE(os.lstat(file_path).st_mode)
                os.chmod(file_path, current & ~stat.S_IWUSR & ~stat.S_IWGRP & ~stat.S_IWOTH)
        except (OSError, IOError):
            continue

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--path', type=str, required=True)
    parser.add_argument('--size', type=int, required=True)
    parser.add_argument('--delete', action='store_true')
    parser.add_argument('--readonly', action='store_true')
    args = parser.parse_args()

    if not os.path.exists(args.path):
        return

    if args.delete and args.readonly:
        return

    scan_path = str(Path(args.path).resolve())
    large_files = scan_files(scan_path, args.size)
    process_files(large_files, args.delete, args.readonly)

if __name__ == '__main__':
    main()
