import os
import tarfile
import hashlib
import json
from datetime import datetime
from pathlib import Path

class DiffBackup:
    def __init__(self, source_dir, backup_dir):
        self.source_dir = Path(source_dir)
        self.backup_dir = Path(backup_dir)
        self.metadata_file = self.backup_dir / "backup_metadata.json"
        self.previous_hashes = self.load_metadata()

    def load_metadata(self):
        if self.metadata_file.exists():
            with open(self.metadata_file, "r") as f:
                return json.load(f)
        return {}

    def save_metadata(self, hashes):
        with open(self.metadata_file, "w") as f:
            json.dump(hashes, f)

    def get_file_hash(self, filepath):
        sha256 = hashlib.sha256()
        with open(filepath, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                sha256.update(chunk)
        return sha256.hexdigest()

    def create_backup(self):
        current_hashes = {}
        files_to_backup = []

        for root, _, files in os.walk(self.source_dir):
            for file in files:
                filepath = Path(root) / file
                rel_path = filepath.relative_to(self.source_dir)
                file_hash = self.get_file_hash(filepath)
                current_hashes[str(rel_path)] = file_hash

                if (str(rel_path) not in self.previous_hashes or 
                    self.previous_hashes[str(rel_path)] != file_hash):
                    files_to_backup.append(filepath)

        if files_to_backup:
            timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
            backup_name = f"backup_{timestamp}.tar.gz"
            backup_path = self.backup_dir / backup_name

            with tarfile.open(backup_path, "w:gz") as tar:
                for file in files_to_backup:
                    tar.add(file, arcname=file.relative_to(self.source_dir))

            self.save_metadata(current_hashes)
            return backup_path
        return None
