import tarfile
import os
import shutil
import sys
from pathlib import Path

def install(tar_path):
    if not os.path.isfile(tar_path) or not tar_path.endswith('.tar.gz'):
        sys.exit(1)

    base_dir = Path('/opt/packages')
    if not base_dir.exists() or not base_dir.is_dir():
        sys.exit(1)

    try:
        with tarfile.open(tar_path, 'r:gz') as tar:
            first_member = None
            for member in tar.getmembers():
                if not os.path.isabs(member.name) and '..' not in member.name:
                    member.uid = member.gid = 0
                    if first_member is None:
                        first_member = member.name
                    tar.extract(member, path=str(base_dir))

        if not first_member:
            sys.exit(1)

        pkg_dir = first_member
        version = pkg_dir.split("-")[1]
        target_dir = base_dir / pkg_dir
        final_dir = base_dir / f"{pkg_dir}-{version}"

        if final_dir.exists():
            sys.exit(1)

        shutil.move(str(target_dir), str(final_dir))
        os.chdir(str(final_dir))
        result = os.system("python setup.py install")
        if result != 0:
            sys.exit(1)

    except (tarfile.TarError, OSError):
        sys.exit(1)

