import os
import shutil
import subprocess
import stat
from pathlib import Path

def cleanup():
    build_dir = Path('build')
    zip_file = Path('app.zip')
    if build_dir.exists():
        shutil.rmtree(build_dir)
    if zip_file.exists():
        zip_file.unlink()

def set_permissions(path, mode):
    os.chmod(path, mode)
    if os.path.isdir(path):
        for root, dirs, files in os.walk(path):
            for d in dirs:
                os.chmod(os.path.join(root, d), mode)
            for f in files:
                os.chmod(os.path.join(root, f), mode)

def build(src):
    cleanup()

    src_path = Path(src).resolve()
    if not src_path.exists():
        raise ValueError("Source directory does not exist")

    result = subprocess.run(['npm', 'run', 'build'], 
                          cwd=src_path,
                          capture_output=True,
                          text=True,
                          check=True)

    build_dir = Path('build')
    if build_dir.exists():
        set_permissions(build_dir, stat.S_IRUSR | stat.S_IWUSR | stat.S_IXUSR)

    subprocess.run(['zip', '-r', 'app.zip', 'build'],
                  check=True)

    set_permissions('app.zip', stat.S_IRUSR | stat.S_IWUSR)

if __name__ == '__main__':
