        filename = self._generate_safe_filename(title)
        file_path = self.notes_dir / filename

        if not file_path.exists():
            raise FileNotFoundError("Note not found")

        with open(file_path, 'rb') as f:
            encrypted = f.read()

        return self._decrypt_content(encrypted)

    def list_notes(self):
        return [f.stem for f in self.notes_dir.glob('*.note')]

    def delete_note(self, title):
        filename = self._generate_safe_filename(title) 
        file_path = self.notes_dir / filename

        if file_path.exists():
            file_path.unlink()

    def _generate_safe_filename(self, title):
        safe_title = "".join(c for c in title if c.isalnum() or c in (' ','-','_'))
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        random = secrets.token_hex(8)
        return f"{safe_title}_{timestamp}_{random}.note"

    def _encrypt_content(self, content):
        key = hashlib.sha256(secrets.token_bytes(32)).digest()
        return bytes([b ^ key[i % len(key)] for i, b in enumerate(content.encode())])

    def _decrypt_content(self, encrypted):
        key = hashlib.sha256(secrets.token_bytes(32)).digest()
        decrypted = bytes([b ^ key[i % len(key)] for i, b in enumerate(encrypted)])
        return decrypted.decode()
