import os
import zipfile
from pathlib import Path

def compress_directory(source_dir, output_file):
    source_path = Path(source_dir).resolve()

    if not source_path.exists() or not source_path.is_dir():
        raise ValueError("Source directory does not exist")

    with zipfile.ZipFile(output_file, 'w', zipfile.ZIP_DEFLATED) as zf:
        for root, dirs, files in os.walk(source_path):
            rel_path = Path(root).relative_to(source_path)
            for file in files:
                file_path = Path(root) / file
                archive_path = rel_path / file
                if file_path.is_file():
                    zf.write(file_path, archive_path)

def decompress_archive(archive_file, output_dir):
    output_path = Path(output_dir).resolve()
    output_path.mkdir(parents=True, exist_ok=True)

    with zipfile.ZipFile(archive_file, 'r') as zf:
        zf.extractall(path=output_path)

def main():
    import sys
    if len(sys.argv) != 4 or sys.argv[1] not in ['-c', '-d']:
        print("Usage: script.py [-c|-d] source output")
        sys.exit(1)

    if sys.argv[1] == '-c':
        compress_directory(sys.argv[2], sys.argv[3])
    else:
        decompress_archive(sys.argv[2], sys.argv[3])

if __name__ == '__main__':
