def get_links(soup):
    if not soup:
        return []
    links = []
    for a in soup.find_all('a'):
        url = a.get('href')
        if url and url.startswith('http'):
            links.append(url.strip())
    return list(set(links))

def classify_url(url):
    parsed = urlparse(url)
    ext = tldextract.extract(url)

    categories = []
    if re.search(r'\.(edu|ac\.[a-z]{2})$', parsed.netloc):
        categories.append('educational')
    if re.search(r'\.(gov|mil)$', parsed.netloc):
        categories.append('government')
    if re.search(r'\.(com|biz|shop)$', parsed.netloc):
        categories.append('commercial')
    if re.search(r'\.(org|ngo)$', parsed.netloc):
        categories.append('organization')
    if re.search(r'(news|blog)', parsed.netloc):
        categories.append('news')
    if not categories:
