import os
import stat
import argparse
from pathlib import Path

def get_file_size(file_path):
    try:
        return os.path.getsize(file_path)
    except (OSError, IOError):
        return 0

def process_files(directory, size_threshold, action):
    directory = os.path.abspath(directory)
    if not os.path.exists(directory):
        raise ValueError(f"Directory {directory} does not exist")

    for root, _, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                file_size = get_file_size(file_path)
                if file_size > size_threshold:
                    if action == "delete":
                        os.remove(file_path)
                        print(f"Deleted: {file_path}")
                    elif action == "readonly":
                        current_perms = os.stat(file_path).st_mode
                        os.chmod(file_path, current_perms & ~stat.S_IWUSR & ~stat.S_IWGRP & ~stat.S_IWOTH)
                        print(f"Made readonly: {file_path}")
                    elif action == "list":
                        print(f"Large file found: {file_path} ({file_size} bytes)")
            except (OSError, IOError):
                continue

def main():
    parser = argparse.ArgumentParser(description="Analyze and process large files")
    parser.add_argument("directory", help="Directory to scan")
    parser.add_argument("--size", type=int, default=1000000, help="Size threshold in bytes")
    parser.add_argument("--action", choices=["list", "delete", "readonly"], default="list",
                        help="Action to take on large files")

    args = parser.parse_args()
    directory = str(Path(args.directory).resolve())
    if not os.path.commonprefix([directory, os.path.abspath(os.sep)]) == os.path.abspath(os.sep):
        raise ValueError("Invalid directory path")

    process_files(directory, args.size, args.action)

if __name__ == "__main__":
