import os
import re
from pathlib import Path
from typing import Callable, List

def rename_files(directory: str, pattern: str, replacement: str, recursive: bool = False) -> List[tuple]:
    results = []
    directory = Path(directory).resolve()

    if not directory.exists() or not directory.is_dir():
        raise ValueError("Invalid directory path")

    def process_dir(path: Path) -> None:
        try:
            for item in path.iterdir():
                if item.is_file():
                    new_name = re.sub(pattern, replacement, item.name)
                    if new_name != item.name:
                        new_path = item.parent / new_name
                        if not new_path.exists():
                            item.rename(new_path)
                            results.append((str(item), str(new_path)))
                elif recursive and item.is_dir():
                    process_dir(item)
        except (PermissionError, OSError) as e:
            raise RuntimeError(f"Error accessing {path}: {e}")

    process_dir(directory)
    return results

def rename_with_function(directory: str, rename_func: Callable[[str], str], recursive: bool = False) -> List[tuple]:
    results = []
    directory = Path(directory).resolve()

    if not directory.exists() or not directory.is_dir():
        raise ValueError("Invalid directory path")

    def process_dir(path: Path) -> None:
        try:
            for item in path.iterdir():
                if item.is_file():
                    new_name = rename_func(item.name)
                    if new_name != item.name:
                        new_path = item.parent / new_name
                        if not new_path.exists():
