import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse
import validators
from typing import Set
import hashlib
import time

class WebCrawler:
    def __init__(self, start_url: str, max_pages: int = 100):
        self.start_url = start_url
        self.max_pages = max_pages
        self.visited_urls: Set[str] = set()
        self.session = requests.Session()
        self.session.headers.update({
            'User-Agent': 'Mozilla/5.0 (compatible; MyCrawler/1.0)'
        })

    def is_valid_url(self, url: str) -> bool:
        try:
            result = urlparse(url)
            return all([result.scheme, result.netloc]) and validators.url(url)
        except:
            return False

    def get_normalized_url(self, url: str) -> str:
        return url.rstrip('/')

    def download_page(self, url: str) -> tuple[str, list[str]]:
        try:
            response = self.session.get(url, timeout=10, allow_redirects=True)
            response.raise_for_status()
            soup = BeautifulSoup(response.text, 'html.parser')
            links = [urljoin(url, link.get('href')) for link in soup.find_all('a')]
            valid_links = [link for link in links if self.is_valid_url(link)]

            page_hash = hashlib.sha256(response.content).hexdigest()
            return page_hash, valid_links
        except:
            return "", []

    def crawl(self):
        if not self.is_valid_url(self.start_url):
            return

        queue = [self.get_normalized_url(self.start_url)]

        while queue and len(self.visited_urls) < self.max_pages:
            url = queue.pop(0)
            if url in self.visited_urls:
                continue

            page_hash, new_links = self.download_page(url)
            if page_hash:
                self.visited_urls.add(url)
                queue.extend([self.get_normalized_url(link) for link in new_links 
                            if link not in self.visited_urls])

            time.sleep(1)

        return self.visited_urls
