from typing import Dict, Any
import json
import os

class APIDocGenerator:
    def __init__(self, schema_dir: str):
        self.schema_dir = schema_dir
        self.docs = {}

    def load_schemas(self) -> None:
        for filename in os.listdir(self.schema_dir):
            if filename.endswith('.json'):
                with open(os.path.join(self.schema_dir, filename)) as f:
                    schema = json.load(f)
                    self.docs[filename[:-5]] = schema

    def generate_html(self) -> str:
        html = '<html><body>'
        for endpoint, schema in self.docs.items():
            html += f'<h2>{endpoint}</h2>'
            html += self._schema_to_html(schema)
        html += '</body></html>'
        return html

    def _schema_to_html(self, schema: Dict[str, Any], depth: int = 0) -> str:
        html = ''
        indent = '&nbsp;' * (depth * 4)

        if 'type' in schema:
            html += f'{indent}<strong>Type:</strong> {schema["type"]}<br>'

        if 'properties' in schema:
            html += f'{indent}<strong>Properties:</strong><br>'
            for prop, details in schema['properties'].items():
                html += f'{indent}{prop}:<br>'
                html += self._schema_to_html(details, depth + 1)

        if 'required' in schema:
            html += f'{indent}<strong>Required:</strong> {", ".join(schema["required"])}<br>'

        if 'enum' in schema:
            html += f'{indent}<strong>Enum:</strong> {", ".join(str(x) for x in schema["enum"])}<br>'

        if 'description' in schema:
            html += f'{indent}<strong>Description:</strong> {schema["description"]}<br>'

        return html

    def save_docs(self, output_file: str) -> None:
        with open(output_file, 'w') as f:
            f.write(self.generate_html())

def generate_api_docs(schema_dir: str, output_file: str) -> None:
    generator = APIDocGenerator(schema_dir)
    generator.load_schemas()
    generator.save_docs(output_file)
