import zipfile
import os
from pathlib import Path

def compress_files(files, output_zip):
    if not files:
        return

    output_path = Path(output_zip).resolve()
    parent_dir = output_path.parent

    if not parent_dir.exists() or not parent_dir.is_dir():
        raise ValueError("Invalid output directory")

    with zipfile.ZipFile(output_path, 'w', zipfile.ZIP_DEFLATED) as zf:
        for file in files:
            file_path = Path(file).resolve()
            if not file_path.exists() or not file_path.is_file():
                continue
            if file_path.is_relative_to(parent_dir):
                rel_path = file_path.relative_to(parent_dir)
                zf.write(file_path, rel_path)

def main():
    files = []
    while True:
        file = input("Enter file path to compress (or press Enter to finish): ").strip()
        if not file:
            break
        files.append(file)

    if files:
        output_zip = input("Enter output zip filename: ").strip()
        try:
            compress_files(files, output_zip)
            print("Compression complete")
        except Exception as e:
            print(f"Error: {e}")

if __name__ == "__main__":
