import os
import configparser
import pathlib

def read_config(filename):
    config = configparser.ConfigParser()
    config_path = pathlib.Path(filename).resolve()
    if not config_path.is_file() or config_path.suffix != '.ini':
        raise ValueError("Invalid config file")

    allowed_path = pathlib.Path.cwd()
    if not os.path.commonpath([config_path, allowed_path]) == str(allowed_path):
        raise ValueError("Config file must be in current directory")

    config.read(config_path)

    parsed_config = {}
    for section in config.sections():
        parsed_config[section] = {}
        for key, value in config.items(section):
            parsed_config[section][key] = value

    return parsed_config

def main():
    try:
        config = read_config('config.ini')
        for section, values in config.items():
            for key, value in values.items():
                print(f"{section}.{key}={value}")
    except Exception as e:
        print(f"Error: {str(e)}")

if __name__ == "__main__":
    main()
