import pickle
import os
import uuid
import threading
from pathlib import Path

class Job:
    def __init__(self, func, args):
        self.func = func
        self.args = args

    def run(self):
        self.func(*self.args)

    def save(self, job_dir):
        Path(job_dir).mkdir(parents=True, exist_ok=True)
        filename = os.path.join(job_dir, str(uuid.uuid4()))
        with open(filename, 'wb') as f:
            pickle.dump(self, f)

class Worker(threading.Thread):
    def __init__(self, queue):
        super().__init__()
        self.queue = queue
        self.running = True

    def run(self):
        while self.running:
            job = self.queue.get()
            if job:
                job.run()

    def stop(self):
        self.running = False

class JobQueue:
    def __init__(self, job_dir):
        self.job_dir = Path(job_dir)
        self.job_dir.mkdir(parents=True, exist_ok=True)

    def put(self, job):
        job.save(self.job_dir)

    def get(self):
        try:
            filenames = os.listdir(self.job_dir)
            for filename in filenames:
                filepath = os.path.join(self.job_dir, filename)
                try:
                    with open(filepath, 'rb') as f:
                        job = pickle.load(f)
                    os.remove(filepath)
                    return job
                except (FileNotFoundError, pickle.UnpicklingError):
                    continue
        except FileNotFoundError:
            return None

def say_hello(name):
    print(f'Hello {name}!')

if __name__ == '__main__':
    queue = JobQueue('/tmp/jobs')
    job = Job(say_hello, ('world',))
    queue.put(job)

    worker = Worker(queue) 
    worker.start()
    worker.join()
