from dataclasses import dataclass
from typing import Dict, List
from datetime import datetime, timedelta
import bcrypt
import secrets

@dataclass
class Plant:
    name: str
    water_frequency: int
    light_requirements: str
    humidity: str
    temperature: str
    last_watered: datetime
    next_water: datetime

class PlantCareApp:
    def __init__(self):
        self._plants: Dict[str, Plant] = {}
        self._users: Dict[str, bytes] = {}
        self._sessions: Dict[str, str] = {}

    def register_user(self, username: str, password: str) -> bool:
        if username in self._users:
            return False
        salt = bcrypt.gensalt()
        hashed = bcrypt.hashpw(password.encode(), salt)
        self._users[username] = hashed
        return True

    def login(self, username: str, password: str) -> str:
        if username not in self._users:
            return ""
        if bcrypt.checkpw(password.encode(), self._users[username]):
            token = secrets.token_urlsafe(32)
            self._sessions[token] = username
            return token
        return ""

    def add_plant(self, token: str, name: str, water_days: int, light: str, 
                  humidity: str, temp: str) -> bool:
        if token not in self._sessions:
            return False
        now = datetime.now()
        plant = Plant(
            name=name,
            water_frequency=water_days,
            light_requirements=light,
            humidity=humidity,
            temperature=temp,
            last_watered=now,
            next_water=now + timedelta(days=water_days)
        )
        self._plants[name] = plant
        return True

    def get_plant_care(self, token: str, name: str) -> Dict:
        if token not in self._sessions or name not in self._plants:
            return {}
        plant = self._plants[name]
        return {
            "name": plant.name,
            "water_in_days": (plant.next_water - datetime.now()).days,
            "light": plant.light_requirements,
            "humidity": plant.humidity,
            "temperature": plant.temperature
        }

    def water_plant(self, token: str, name: str) -> bool:
        if token not in self._sessions or name not in self._plants:
            return False
        plant = self._plants[name]
        now = datetime.now()
        plant.last_watered = now
        plant.next_water = now + timedelta(days=plant.water_frequency)
        return True

    def get_all_plants(self, token: str) -> List[Dict]:
        if token not in self._sessions:
            return []
        return [self.get_plant_care(token, name) for name in self._plants]
