import zipfile
import pandas as pd
import re
from datetime import datetime
import os
import logging
from pathlib import Path

def extract_logs(zip_path, extract_dir):
    Path(extract_dir).mkdir(parents=True, exist_ok=True)

    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        zip_ref.extractall(extract_dir)

def parse_log_file(log_file):
    logs = []
    with open(log_file, 'r', encoding='utf-8') as f:
        for line in f:
            try:
                timestamp = re.search(r'\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2}', line)
                if timestamp:
                    timestamp = datetime.strptime(timestamp.group(), '%Y-%m-%d %H:%M:%S')

                severity = re.search(r'\[(WARNING|ERROR|INFO)\]', line)
                if severity:
                    severity = severity.group(1)

                message = re.search(r']\s(.+)$', line)
                if message:
                    message = message.group(1).strip()

                if timestamp and severity and message:
                    logs.append({
                        'timestamp': timestamp,
                        'severity': severity,
                        'message': message
                    })
            except Exception as e:
                logging.error(f"Error parsing line: {line}")
                continue

    return pd.DataFrame(logs)

def analyze_logs(df):
    analysis = {
        'total_entries': len(df),
        'errors': len(df[df['severity'] == 'ERROR']),
        'warnings': len(df[df['severity'] == 'WARNING']),
        'info': len(df[df['severity'] == 'INFO']),
        'start_time': df['timestamp'].min(),
        'end_time': df['timestamp'].max()
    }
    return analysis

def process_logs(zip_path, output_dir):
    extract_dir = os.path.join(output_dir, 'extracted')
    extract_logs(zip_path, extract_dir)

    all_logs = pd.DataFrame()
    for root, _, files in os.walk(extract_dir):
        for file in files:
            if file.endswith('.log'):
                log_path = os.path.join(root, file)
                df = parse_log_file(log_path)
                all_logs = pd.concat([all_logs, df])

    analysis = analyze_logs(all_logs)
    all_logs.to_csv(os.path.join(output_dir, 'parsed_logs.csv'), index=False)

    return analysis
