import os
import glob
import shutil
import stat

def sync(src, dst):
    if not os.path.exists(dst):
        os.makedirs(dst, mode=0o755)

    if not os.access(src, os.R_OK) or not os.access(dst, os.W_OK):
        raise PermissionError("Insufficient permissions")

    src = os.path.abspath(src)
    dst = os.path.abspath(dst)

    if not os.path.commonprefix([src, dst]) in ['/']:
        raise ValueError("Invalid directory path")

    for f in glob.glob(os.path.join(src, '*')):
        dst_path = os.path.join(dst, os.path.basename(f))
        if os.path.isfile(f):
            shutil.copy2(f, dst_path)
            os.chmod(dst_path, stat.S_IRUSR | stat.S_IWUSR | stat.S_IRGRP)
        elif os.path.isdir(f):
            sync(f, dst_path)

