import os
import hashlib
from pathlib import Path
from collections import defaultdict
import shutil

def get_file_hash(filepath):
    hasher = hashlib.sha256()
    with open(filepath, 'rb') as f:
        buf = f.read(65536)
        while len(buf) > 0:
            hasher.update(buf)
            buf = f.read(65536)
    return hasher.hexdigest()

def find_duplicates(directory):
    hash_map = defaultdict(list)
    backup_files = []

    for root, _, files in os.walk(directory):
        for filename in files:
            filepath = os.path.join(root, filename)
            if os.path.isfile(filepath):
                file_hash = get_file_hash(filepath)
                hash_map[file_hash].append(filepath)

                if any(ext in filename.lower() for ext in ['.bak', '~', 'copy']):
                    backup_files.append(filepath)

    return hash_map, backup_files

def delete_file(filepath):
    try:
        os.remove(filepath)
        return True
    except OSError:
        return False

def set_permissions(filepath, mode):
    try:
        os.chmod(filepath, mode)
        return True
    except OSError:
        return False

def analyze_disk_space(directory):
    hash_map, backup_files = find_duplicates(directory)

    duplicate_groups = {k: v for k, v in hash_map.items() if len(v) > 1}

    if duplicate_groups:
        print("\nDuplicate files found:")
        for files in duplicate_groups.values():
            print("\nDuplicate group:")
            for f in files:
                print(f"- {f} ({os.path.getsize(f)} bytes)")

            keep = files[0]
            for duplicate in files[1:]:
                if input(f"\nDelete duplicate {duplicate}? (y/n): ").lower() == 'y':
                    if delete_file(duplicate):
                        print(f"Deleted {duplicate}")
                    else:
                        print(f"Failed to delete {duplicate}")

            if input("\nSet read-only permissions for remaining file? (y/n): ").lower() == 'y':
                if set_permissions(keep, 0o444):
                    print(f"Set read-only permissions for {keep}")
                else:
                    print(f"Failed to set permissions for {keep}")

    if backup_files:
        print("\nBackup files found:")
        for backup in backup_files:
            print(f"- {backup}")
            if input(f"\nDelete backup {backup}? (y/n): ").lower() == 'y':
                if delete_file(backup):
                    print(f"Deleted {backup}")
                else:
                    print(f"Failed to delete {backup}")

if __name__ == "__main__":
    directory = input("Enter directory path to analyze: ")
    if os.path.isdir(directory):
        analyze_disk_space(directory)
    else:
        print("Invalid directory path")
