class ArchiveHandler:
    def __init__(self, seven_zip_path="7z"):
        self.seven_zip_path = seven_zip_path
        self._validate_seven_zip()

    def _validate_seven_zip(self):
        try:
            subprocess.run([self.seven_zip_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        except FileNotFoundError:
            raise RuntimeError("7-Zip executable not found")

    def _sanitize_path(self, path):
        return str(Path(path).resolve())

    def extract(self, archive_path, output_dir=None, password=None):
        archive_path = self._sanitize_path(archive_path)
        if not os.path.exists(archive_path):
            raise FileNotFoundError(f"Archive not found: {archive_path}")

        if output_dir:
            output_dir = self._sanitize_path(output_dir)
            os.makedirs(output_dir, exist_ok=True)
        else:
            output_dir = os.path.dirname(archive_path)

        cmd = [self.seven_zip_path, "x", archive_path, f"-o{output_dir}", "-y"]
        if password:
            cmd.append(f"-p{password}")

        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
        if result.returncode != 0:
            raise RuntimeError(f"Extraction failed: {result.stderr}")

        return output_dir

    def list_contents(self, archive_path):
        archive_path = self._sanitize_path(archive_path)
        if not os.path.exists(archive_path):
            raise FileNotFoundError(f"Archive not found: {archive_path}")

        cmd = [self.seven_zip_path, "l", archive_path]
        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

        if result.returncode != 0:
            raise RuntimeError(f"Listing failed: {result.stderr}")

        return result.stdout

    def test_archive(self, archive_path):
        archive_path = self._sanitize_path(archive_path)
        if not os.path.exists(archive_path):
            raise FileNotFoundError(f"Archive not found: {archive_path}")

        cmd = [self.seven_zip_path, "t", archive_path]
        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)

        return result.returncode == 0
