import math

def tension(m, theta):
    return m * 9.81 * math.sin(theta)

def read_data(filename):
    with open(filename) as f:
        lines = [line.strip() for line in f.readlines()]
        data = []
        for line in lines:
            try:
                vals = line.split()
                if len(vals) != 2:
                    continue
                m = float(vals[0])
                theta = float(vals[1])
                if m > 0 and 0 <= theta <= 360:
                    data.append((m, theta))
            except ValueError:
                continue
    return data

def write_output(tensions, outfile):
    with open(outfile, 'w') as f:
        for t in tensions:
            f.write(f'{t:.2f}\n')

def main():
    if not os.path.exists('string.txt'):
        return

    data = read_data('string.txt')
    data = [(m, theta*math.pi/180) for m, theta in data]
    tensions = [tension(m, theta) for m, theta in data]

    outdir = '/tmp'
    if not os.path.exists(outdir):
        os.makedirs(outdir, mode=0o700)

    outfile = os.path.join(outdir, 'tensions.txt')
    write_output(tensions, outfile)

if __name__ == '__main__':
