import os
import shutil
import stat
from datetime import datetime

def rotate_log(log_path):
    if not os.path.exists(log_path):
        return

    original_perms = stat.S_IMODE(os.lstat(log_path).st_mode)
    timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
    rotated_path = f"{log_path}.{timestamp}"

    try:
        os.rename(log_path, rotated_path)
        with open(log_path, 'w') as f:
            os.chmod(log_path, original_perms)
            os.chown(log_path, os.lstat(rotated_path).st_uid, os.lstat(rotated_path).st_gid)
    except (OSError, IOError):
        if os.path.exists(rotated_path):
            os.remove(rotated_path)
        raise

def rotate_logs_in_dir(directory):
    if not os.path.isdir(directory):
        return

    for filename in os.listdir(directory):
        full_path = os.path.join(directory, filename)
        if os.path.isfile(full_path):
            rotate_log(full_path)
