        self.output_path = Path(output_path)
        self.cpu_threshold = cpu_threshold 
        self.mem_threshold = mem_threshold

    def check_server(self, server):
        cpu_percent = psutil.cpu_percent()
        mem_percent = psutil.virtual_memory().percent

        if cpu_percent > self.cpu_threshold or mem_percent > self.mem_threshold:
            return {
                'timestamp': datetime.now().isoformat(),
                'server': server,
                'cpu': cpu_percent,
                'memory': mem_percent
            }
        return None

    def save_measurements(self, data, permissions=0o600):
        if not data:
            return

        timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
        output_file = self.output_path / f'anomalies_{timestamp}.json'

        self.output_path.mkdir(parents=True, exist_ok=True)

        with open(output_file, 'w') as f:
            json.dump(data, f)

        os.chmod(output_file, permissions)

    def run(self):
        anomalies = []
        for server in self.servers:
            result = self.check_server(server)
            if result:
                anomalies.append(result)

        if anomalies:
            self.save_measurements(anomalies)

def main():
    servers = ['server1', 'server2', 'server3']
    monitor = SystemMonitor(servers, '/var/log/monitoring')

    while True:
        monitor.run()
        time.sleep(3600)

if __name__ == '__main__':
    main()
