import os
from PIL import Image

def resize_image(image_path, size):
    try:
        with Image.open(image_path) as img:
            img = img.convert('RGB')
            img = img.resize(size, Image.Resampling.LANCZOS)
            img.save(image_path, format='JPEG')
    except Exception:
        return False
    return True

def compress_image(image_path, quality):
    try:
        with Image.open(image_path) as img:
            img = img.convert('RGB')
            img.save(image_path, format='JPEG', optimize=True, quality=quality)
    except Exception:
        return False
    return True

def watermark_image(image_path, mark):
    try:
        with Image.open(image_path) as img:
            img = img.convert('RGB')
            w, h = img.size
            mark = mark.resize((w//10, h//10), Image.Resampling.LANCZOS)
            layer = Image.new('RGBA', img.size, (0,0,0,0))
            layer.paste(mark, (w-w//10, h-h//10))
            img = Image.composite(layer, img, layer)
            img.save(image_path, format='JPEG')
    except Exception:
        return False
    return True

def prepare_images_for_web(dir_path, watermark):
    if not os.path.isdir(dir_path):
        return False
    try:
        for file in os.listdir(dir_path):
            if file.lower().endswith(('.jpg', '.jpeg', '.png')):
                path = os.path.join(dir_path, file)
                if os.path.isfile(path):
                    resize_image(path, (1280, 720))
                    compress_image(path, 80)
                    watermark_image(path, watermark)
        return True
    except Exception:
        return False

def process_images(dir_path, watermark_path):
    if not os.path.isfile(watermark_path):
        return False
    try:
        with Image.open(watermark_path) as watermark:
            watermark = watermark.convert('RGBA')
            return prepare_images_for_web(dir_path, watermark)
    except Exception:
        return False

if __name__ == "__main__":
    process_images('/var/www/images', 'logo.png')

