import os
from pathlib import Path
import secrets
import hashlib
import time

class MessageApp:
    def __init__(self):
        self.data_dir = Path('data')
        self.data_dir.mkdir(exist_ok=True)

    def sanitize_username(self, username):
        return ''.join(c for c in username if c.isalnum())

    def get_message_file(self, username):
        safe_username = self.sanitize_username(username)
        return self.data_dir / f"{safe_username}_{hashlib.sha256(safe_username.encode()).hexdigest()[:8]}.txt"

    def send_message(self, username, message):
        if not message or not username:
            return False
        file_path = self.get_message_file(username)
        message_id = secrets.token_hex(16)
        timestamp = str(int(time.time()))

        try:
            with open(file_path, 'a+') as f:
                f.write(f"{message_id}|{timestamp}|{message}\n")
            return message_id
        except:
            return False

    def get_messages(self, username, limit=100):
        file_path = self.get_message_file(username)
        messages = []
        try:
            if file_path.exists():
                with open(file_path, 'r') as f:
                    messages = [tuple(line.strip().split('|')) for line in f.readlines()[-limit:]]
            return messages
        except:
            return []

    def update_message(self, username, message_id, new_message):
        if not new_message or not message_id:
            return False

        file_path = self.get_message_file(username)
        temp_file = file_path.with_suffix('.tmp')

        try:
            with open(file_path, 'r') as f_read, open(temp_file, 'w') as f_write:
                for line in f_read:
                    current_id = line.split('|')[0]
                    if current_id == message_id:
                        timestamp = str(int(time.time()))
                        f_write.write(f"{message_id}|{timestamp}|{new_message}\n")
                    else:
                        f_write.write(line)

            os.replace(temp_file, file_path)
            return True
        except:
            if temp_file.exists():
                temp_file.unlink()
            return False

    def delete_message(self, username, message_id):
        file_path = self.get_message_file(username)
        temp_file = file_path.with_suffix('.tmp')

        try:
            with open(file_path, 'r') as f_read, open(temp_file, 'w') as f_write:
                for line in f_read:
                    if not line.startswith(f"{message_id}|"):
                        f_write.write(line)
            os.replace(temp_file, file_path)
            return True
        except:
            if temp_file.exists():
                temp_file.unlink()
            return False

