import os
import shutil
import stat
from pathlib import Path

def sync(remote, local):
    remote_path = Path(remote).resolve()
    local_path = Path(local).expanduser().resolve()

    if not remote_path.exists() or not remote_path.is_dir():
        raise ValueError("Invalid remote directory")

    local_path.mkdir(parents=True, exist_ok=True)

    for item in remote_path.iterdir():
        dest = local_path / item.name

        if item.is_dir():
            sync(str(item), str(dest))
        else:
            shutil.copy2(str(item), str(dest))
            source_stat = item.stat()
            dest.chmod(source_stat.st_mode & ~stat.S_IWOTH & ~stat.S_IWGRP)

