import os
from git import Repo
import subprocess
import re

def init_repo(path):
    if not os.path.exists(path):
        raise ValueError("Repository path does not exist")
    return Repo(path)

def stash_changes(repo_path):
    try:
        repo = init_repo(repo_path)
        if not repo.is_dirty():
            return "No changes to stash"

        sanitized_path = re.sub(r'[^a-zA-Z0-9/\-_.]', '', repo_path)
        repo = Repo(sanitized_path)

        if not repo.bare:
            stash_result = repo.git.stash('save', '--include-untracked')
            return stash_result
    except Exception as e:
        raise RuntimeError(f"Failed to stash changes: {str(e)}")

def commit_changes(repo_path, message):
    try:
        repo = init_repo(repo_path)
        sanitized_message = re.sub(r'[^a-zA-Z0-9\s\-_.]', '', message)

        if repo.is_dirty():
            repo.index.add('*')
            repo.index.commit(sanitized_message)
            return True
        return False
    except Exception as e:
        raise RuntimeError(f"Failed to commit changes: {str(e)}")

def pull_changes(repo_path):
    try:
        repo = init_repo(repo_path)
        origin = repo.remotes.origin
        origin.pull()
    except Exception as e:
        raise RuntimeError(f"Failed to pull changes: {str(e)}")

def push_changes(repo_path):
    try:
        repo = init_repo(repo_path)
        origin = repo.remotes.origin
        origin.push()
    except Exception as e:
        raise RuntimeError(f"Failed to push changes: {str(e)}")

