from flask import Flask, request, jsonify
import bleach

app = Flask(__name__)

@app.route("/reviews")
def reviews():
    reviews = request.args.getlist("review")
    usernames = request.args.getlist("username")
    ratings = request.args.getlist("rating")

    if not (reviews and usernames and ratings and len(reviews) == len(usernames) == len(ratings)):
        return jsonify({"error": "Invalid input parameters"}), 400

    review_list = []
    for i in range(len(reviews)):
        try:
            sanitized_review = bleach.clean(reviews[i])
            sanitized_username = bleach.clean(usernames[i])
            rating = int(ratings[i])

            if not (0 <= rating <= 5):
                return jsonify({"error": "Rating must be between 0 and 5"}), 400

            review_obj = {
                "username": sanitized_username,
                "rating": rating,
                "review": sanitized_review
            }
            review_list.append(review_obj)
        except ValueError:
            return jsonify({"error": "Invalid rating format"}), 400

    return jsonify({"reviews": review_list})

if __name__ == "__main__":
    app.run(ssl_context="adhoc")

