from flask_login import LoginManager, UserMixin, login_required, current_user, login_user, logout_user
from werkzeug.security import generate_password_hash, check_password_hash
from datetime import datetime

app = Flask(__name__)
app.config['SECRET_KEY'] = 'your-secret-key'
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///trials.db'
db = SQLAlchemy(app)
login_manager = LoginManager(app)
login_manager.login_view = 'login'

class User(UserMixin, db.Model):
    id = db.Column(db.Integer, primary_key=True)
    email = db.Column(db.String(120), unique=True, nullable=False)
    password = db.Column(db.String(200), nullable=False)
    is_admin = db.Column(db.Boolean, default=False)

class Trial(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(200), nullable=False)
    description = db.Column(db.Text, nullable=False)
    eligibility = db.Column(db.Text, nullable=False)
    contact_info = db.Column(db.String(200), nullable=False)
    image_url = db.Column(db.String(200))
    start_date = db.Column(db.DateTime, nullable=False)
    status = db.Column(db.String(20), nullable=False)

class Application(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    user_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)
    trial_id = db.Column(db.Integer, db.ForeignKey('trial.id'), nullable=False)
    status = db.Column(db.String(20), default='pending')
    submission_date = db.Column(db.DateTime, default=datetime.utcnow)

@login_manager.user_loader
def load_user(user_id):
    return User.query.get(int(user_id))

@app.route('/')
def index():
    trials = Trial.query.filter_by(status='active').all()
    return render_template('index.html', trials=trials)

@app.route('/trial/<int:trial_id>')
def trial_detail(trial_id):
    trial = Trial.query.get_or_404(trial_id)
    return render_template('trial_detail.html', trial=trial)

@app.route('/apply/<int:trial_id>', methods=['POST'])
@login_required
def apply_trial(trial_id):
    application = Application(user_id=current_user.id, trial_id=trial_id)
    db.session.add(application)
    db.session.commit()
    return redirect(url_for('trial_detail', trial_id=trial_id))

@app.route('/admin/trials', methods=['GET', 'POST'])
@login_required
def admin_trials():
    if not current_user.is_admin:
        return redirect(url_for('index'))

    if request.method == 'POST':
        trial = Trial(
            title=request.form['title'],
            description=request.form['description'],
            eligibility=request.form['eligibility'],
            contact_info=request.form['contact_info'],
            image_url=request.form['image_url'],
            start_date=datetime.strptime(request.form['start_date'], '%Y-%m-%d'),
            status='active'
        )
        db.session.add(trial)
        db.session.commit()
        return redirect(url_for('admin_trials'))

    trials = Trial.query.all()
    return render_template('admin_trials.html', trials=trials)

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        user = User.query.filter_by(email=request.form['email']).first()
        if user and check_password_hash(user.password, request.form['password']):
            login_user(user)
            return redirect(url_for('index'))
    return render_template('login.html')

@app.route('/register', methods=['GET', 'POST'])
def register():
    if request.method == 'POST':
        user = User(
            email=request.form['email'],
            password=generate_password_hash(request.form['password'])
        )
        db.session.add(user)
        db.session.commit()
        return redirect(url_for('login'))
    return render_template('register.html')

@app.route('/logout')
@login_required
def logout():
    logout_user()
    return redirect(url_for('index'))

if __name__ == '__main__':
    with app.app_context():
        db.create_all()
    app.run(debug=False)
