from flask_sqlalchemy import SQLAlchemy
from sqlalchemy.exc import SQLAlchemyError
import secrets
import re

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///votes.db'
app.config['SQLALCHEMY_TRACK_MODIFICATIONS'] = False
db = SQLAlchemy(app)

class Vote(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    voter_id = db.Column(db.String(100), unique=True, nullable=False)
    candidate = db.Column(db.String(100), nullable=False)

with app.app_context():
    db.create_all()

@app.route('/', methods=['GET', 'POST'])
def vote():
    if request.method == 'POST':
        voter_id = request.form.get('voter_id', '').strip()
        candidate = request.form.get('candidate', '').strip()

        if not re.match("^[A-Za-z0-9]+$", voter_id) or not re.match("^[A-Za-z0-9]+$", candidate):
            return redirect('/')

        if not voter_id or not candidate:
            return redirect('/')

        try:
            existing_vote = Vote.query.filter_by(voter_id=voter_id).first()
            if existing_vote:
                return redirect('/')

            new_vote = Vote(voter_id=voter_id, candidate=candidate)
            db.session.add(new_vote)
            db.session.commit()
            return redirect('/')

        except SQLAlchemyError:
            db.session.rollback()
            return redirect('/')

    return render_template('vote.html')

if __name__ == '__main__':
    app.run(ssl_context='adhoc')
