from dataclasses import dataclass
from typing import List, Dict, Any
import numpy as np
from enum import Enum

class ModuleType(Enum):
    OSCILLATOR = "oscillator"
    FILTER = "filter" 
    SEQUENCER = "sequencer"
    ENVELOPE = "envelope"
    LFO = "lfo"

@dataclass
class Port:
    id: str
    name: str
    direction: str
    value: float = 0.0

@dataclass 
class Module:
    id: str
    type: ModuleType
    name: str
    params: Dict[str, Any]
    inputs: List[Port]
    outputs: List[Port]

class ModularSynth:
    def __init__(self):
        self.modules: Dict[str, Module] = {}
        self.sample_rate = 44100

    def add_module(self, module: Module):
        self.modules[module.id] = module

    def connect(self, from_module: str, from_port: str, to_module: str, to_port: str):
        source = self.modules[from_module].outputs[from_port]
        dest = self.modules[to_module].inputs[to_port]
        dest.value = source.value

    def process_audio(self, num_samples: int) -> np.ndarray:
        output = np.zeros(num_samples)
        for module in self.modules.values():
            if module.type == ModuleType.OSCILLATOR:
                output += self.process_oscillator(module, num_samples)
            elif module.type == ModuleType.FILTER:
                output = self.process_filter(module, output)
        return output

    def process_oscillator(self, module: Module, num_samples: int) -> np.ndarray:
        freq = module.params["frequency"]
        phase = np.linspace(0, num_samples/self.sample_rate * freq * 2*np.pi, num_samples)
        if module.params["waveform"] == "sine":
            return np.sin(phase)
        elif module.params["waveform"] == "square":
            return np.sign(np.sin(phase))
        return np.zeros(num_samples)

    def process_filter(self, module: Module, signal: np.ndarray) -> np.ndarray:
        cutoff = module.params["cutoff"]
        resonance = module.params["resonance"]
        nyquist = self.sample_rate * 0.5
        normal_cutoff = cutoff / nyquist
        return signal * (1 / (1 + (normal_cutoff * resonance)))
