import os
import zipfile
import json

def zipdir(path, ziph):
    allowed_path = os.path.realpath(path)
    for root, dirs, files in os.walk(allowed_path):
        for f in files:
            file_path = os.path.join(root, f)
            if os.path.islink(file_path):
                continue
            if not os.path.realpath(file_path).startswith(allowed_path):
                continue
            try:
                ziph.write(file_path)
                metadata = {}
                file_stat = os.stat(file_path)
                metadata['mode'] = oct(file_stat.st_mode)
                metadata['owner'] = file_stat.st_uid
                metadata['group'] = file_stat.st_gid
                ziph.writestr(f + '.metadata', json.dumps(metadata))
            except (OSError, IOError):
                continue

def backup(path):
    if not os.path.exists('/backups'):
        os.makedirs('/backups', mode=0o700)
    zipf = zipfile.ZipFile('/backups/backup.zip', 'w', zipfile.ZIP_DEFLATED) 
    zipdir(path, zipf)
    zipf.close()
    os.chmod('/backups/backup.zip', 0o600)

