def get_html(url):
    try:
        headers = {'User-Agent': 'Mozilla/5.0'}
        resp = requests.get(url, headers=headers, timeout=10, verify=True)
        resp.raise_for_status()
        return resp.text
    except:
        return ""

def extract_links(html):
    soup = BeautifulSoup(html, 'html.parser')
    links = soup.find_all('a')
    return [link.get('href') for link in links if link.get('href')]

def is_correct_domain(base_url, test_url):
    if not test_url:
        return False
    base_domain = tldextract.extract(base_url).domain
    test_domain = tldextract.extract(test_url).domain
    return base_domain == test_domain

def analyze_page(html):
    soup = BeautifulSoup(html, 'html.parser')
    word_count = len(re.findall(r'\w+', soup.get_text()))
    images = len(soup.find_all('img'))
    headings = len(soup.find_all(['h1', 'h2', 'h3', 'h4', 'h5', 'h6']))
    paragraphs = len(soup.find_all('p'))
    return {'words': word_count, 'images': images, 'headings': headings, 'paragraphs': paragraphs}

def crawl(url, visited=None):
    if visited is None:
        visited = set()
    if url in visited or len(visited) >= 100:
        return {}

    visited.add(url)
    html = get_html(url)
    if not html:
        return {}

    analytics = analyze_page(html)
    urls = extract_links(html)

    for link in urls:
        absolute_url = urljoin(url, link)
        if is_correct_domain(url, absolute_url):
            sub_analytics = crawl(absolute_url, visited)
            for key in analytics:
                analytics[key] += sub_analytics.get(key, 0)

    return analytics

