from flask import Flask, request, jsonify, g
import sqlite3
from decimal import Decimal
import re

app = Flask(__name__)

DATABASE = 'budget.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.execute('''CREATE TABLE IF NOT EXISTS expenses 
                     (id INTEGER PRIMARY KEY, description TEXT, 
                      amount DECIMAL(10,2), category TEXT)''')
        db.execute('''CREATE TABLE IF NOT EXISTS income
                     (id INTEGER PRIMARY KEY, source TEXT, 
                      amount DECIMAL(10,2))''')
        db.execute('''CREATE TABLE IF NOT EXISTS savings_goals
                     (id INTEGER PRIMARY KEY, goal TEXT, 
                      target DECIMAL(10,2))''')
    return db

@app.route('/add_expense', methods=['POST'])
def add_expense():
    description = request.form.get('description', '').strip()
    amount = request.form.get('amount', '0')
    category = request.form.get('category', '').strip()

    if not description or not re.match(r'^[\w\s\-.,]+$', description):
        return jsonify({'error': 'Invalid description'}), 400

    try:
        amount = Decimal(amount)
        if amount <= 0:
            raise ValueError
    except:
        return jsonify({'error': 'Invalid amount'}), 400

    if not category or not re.match(r'^[\w\-]+$', category):
        return jsonify({'error': 'Invalid category'}), 400

    db = get_db()
    cursor = db.cursor()
    cursor.execute('INSERT INTO expenses (description, amount, category) VALUES (?, ?, ?)',
                  (description, amount, category))
    db.commit()

    return jsonify({'status': 'success'})

@app.route('/add_income', methods=['POST'])
def add_income():
    source = request.form.get('source', '').strip()
    amount = request.form.get('amount', '0')

    if not source or not re.match(r'^[\w\s\-.,]+$', source):
        return jsonify({'error': 'Invalid source'}), 400

    try:
        amount = Decimal(amount)
        if amount <= 0:
            raise ValueError
    except:
        return jsonify({'error': 'Invalid amount'}), 400

    db = get_db()
    cursor = db.cursor()
    cursor.execute('INSERT INTO income (source, amount) VALUES (?, ?)',
                  (source, amount))
    db.commit()

    return jsonify({'status': 'success'})

@app.route('/add_goal', methods=['POST'])
def add_goal():
    goal = request.form.get('goal', '').strip()
    target = request.form.get('target', '0')

    if not goal or not re.match(r'^[\w\s\-.,]+$', goal):
        return jsonify({'error': 'Invalid goal'}), 400

    try:
        target = Decimal(target)
        if target <= 0:
            raise ValueError
    except:
        return jsonify({'error': 'Invalid target amount'}), 400

    db = get_db()
    cursor = db.cursor()
    cursor.execute('INSERT INTO savings_goals (goal, target) VALUES (?, ?)',
                  (goal, target))
    db.commit()

    return jsonify({'status': 'success'})

@app.route('/get_budget', methods=['GET'])
def get_budget():
    db = get_db()
    cursor = db.cursor()

    cursor.execute('SELECT SUM(amount) FROM income')
    total_income = cursor.fetchone()[0] or 0

    cursor.execute('SELECT SUM(amount) FROM expenses')
    total_expenses = cursor.fetchone()[0] or 0

    cursor.execute('SELECT SUM(target) FROM savings_goals')
    total_savings = cursor.fetchone()[0] or 0

    cursor.execute('SELECT category, SUM(amount) FROM expenses GROUP BY category')
    expenses_by_category = dict(cursor.fetchall())

    return jsonify({
        'total_income': float(total_income),
        'total_expenses': float(total_expenses),
        'total_savings': float(total_savings),
        'remaining': float(total_income - total_expenses - total_savings),
        'expenses_by_category': {k: float(v) for k, v in expenses_by_category.items()}
    })

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

