from datetime import datetime

class CalorieTracker:
    def __init__(self):
        self.food_log = []
        self.daily_target = 2000

    def add_food(self, meal, calories, description=""):
        entry = {
            'datetime': datetime.now(),
            'meal': meal,
            'calories': calories,
            'description': description
        }
        self.food_log.append(entry)

    def get_daily_total(self, date=datetime.now().date()):
        total = 0
        for entry in self.food_log:
            if entry['datetime'].date() == date:
                total += entry['calories']
        return total

    def get_log(self):
        return self.food_log

    def set_target(self, target):
        if isinstance(target, (int, float)) and target > 0:
            self.daily_target = target
        else:
            raise ValueError("Target must be a positive number")

    def remaining_calories(self, date=datetime.now().date()):
        return self.daily_target - self.get_daily_total(date)

def main():
    tracker = CalorieTracker()
    while True:
        print("\n1. Add Food Entry")
        print("2. View Today's Total")
        print("3. View Food Log")
        print("4. Set Daily Target")
        print("5. View Remaining Calories")
        print("6. Exit")

        choice = input("\nSelect option: ")

        if choice == "1":
            meal = input("Meal type (breakfast/lunch/dinner/snack): ")
            calories = float(input("Calories: "))
            description = input("Description: ")
            tracker.add_food(meal, calories, description)

        elif choice == "2":
            print(f"Today's total: {tracker.get_daily_total()} calories")

        elif choice == "3":
            for entry in tracker.get_log():
                print(f"\nDate: {entry['datetime']}")
                print(f"Meal: {entry['meal']}")
                print(f"Calories: {entry['calories']}")
                print(f"Description: {entry['description']}")

        elif choice == "4":
            target = float(input("Enter daily calorie target: "))
            tracker.set_target(target)

        elif choice == "5":
            remaining = tracker.remaining_calories()
            print(f"Remaining calories for today: {remaining}")

        elif choice == "6":
            break

if __name__ == "__main__":
    main()
