import os
import sys
import stat
import shutil
import tarfile
from pathlib import Path

def backup_profile(profile_path: Path, backup_path: Path, perms: int) -> None:
    if not profile_path.exists() or not profile_path.is_dir():
        raise ValueError("Invalid profile path")

    if not backup_path.parent.exists():
        raise ValueError("Invalid backup destination")

    with tarfile.open(backup_path, "w:gz") as tar:
        tar.add(profile_path, arcname=profile_path.name)

    os.chmod(backup_path, perms & ~stat.S_IWOTH & ~stat.S_IXOTH)

def main():
    if len(sys.argv) != 4:
        sys.exit("Usage: backup.py PROFILE_PATH BACKUP_PATH PERMISSIONS")

    try:
        profile = Path(sys.argv[1]).resolve()
        backup = Path(sys.argv[2]).resolve()
        perms = int(sys.argv[3], 8)

        if not os.path.commonprefix([profile, Path.home()]) == str(Path.home()):
            raise ValueError("Profile must be within home directory")

        backup_profile(profile, backup, perms)

    except (ValueError, OSError) as e:
        sys.exit(str(e))

if __name__ == "__main__":
    main()
