        return hashlib.sha256(sf.read()).hexdigest() == hashlib.sha256(df.read()).hexdigest()

def extract_zip_disk(source_drive, destination_path):
    if not os.path.exists(destination_path):
        os.makedirs(destination_path)

    failed_files = []
    success_count = 0

    for root, dirs, files in os.walk(source_drive):
        for file in files:
            source_file = os.path.join(root, file)
            rel_path = os.path.relpath(root, source_drive)
            dest_dir = os.path.join(destination_path, rel_path)
            dest_file = os.path.join(dest_dir, file)

            if not os.path.exists(dest_dir):
                os.makedirs(dest_dir)

            try:
                shutil.copy2(source_file, dest_file)
