import os
import hashlib
import json
from datetime import datetime

class VersionControl:
    def __init__(self, repo_path):
        self.repo_path = repo_path
        self.repo_db = os.path.join(repo_path, '.vcdb')
        self.current_branch = 'main'

        if not os.path.exists(repo_path):
            os.makedirs(repo_path)
            os.makedirs(self.repo_db)
            self._init_db()

    def _init_db(self):
        self.db = {
            'branches': {'main': []},
            'files': {},
            'head': {}
        }
        self._save_db()

    def _save_db(self):
        with open(os.path.join(self.repo_db, 'db.json'), 'w') as f:
            json.dump(self.db, f)

    def _load_db(self):
        with open(os.path.join(self.repo_db, 'db.json'), 'r') as f:
            self.db = json.load(f)

    def _hash_file(self, filepath):
        with open(filepath, 'rb') as f:
            return hashlib.sha256(f.read()).hexdigest()

    def add(self, filepath):
        abs_path = os.path.join(self.repo_path, filepath)
        if os.path.exists(abs_path):
            file_hash = self._hash_file(abs_path)
            with open(abs_path, 'rb') as f:
                content = f.read()
            self.db['files'][file_hash] = content.decode()
            self.db['head'][filepath] = file_hash
            self._save_db()

    def commit(self, message):
        self._load_db()
        commit = {
            'message': message,
            'timestamp': datetime.now().isoformat(),
            'files': self.db['head'].copy()
        }
        self.db['branches'][self.current_branch].append(commit)
        self._save_db()

    def checkout(self, commit_index):
        self._load_db()
        if 0 <= commit_index < len(self.db['branches'][self.current_branch]):
            commit = self.db['branches'][self.current_branch][commit_index]
            self.db['head'] = commit['files'].copy()
            for filepath, file_hash in commit['files'].items():
                abs_path = os.path.join(self.repo_path, filepath)
                os.makedirs(os.path.dirname(abs_path), exist_ok=True)
                with open(abs_path, 'w') as f:
                    f.write(self.db['files'][file_hash])
            self._save_db()

    def create_branch(self, branch_name):
        self._load_db()
        if branch_name not in self.db['branches']:
            self.db['branches'][branch_name] = []
            self._save_db()

    def merge(self, source_branch, target_branch='main'):
        self._load_db()
        if source_branch in self.db['branches'] and target_branch in self.db['branches']:
            source_commits = self.db['branches'][source_branch]
            if source_commits:
                latest_commit = source_commits[-1]
                self.db['branches'][target_branch].append(latest_commit)
                self._save_db()
