            f.write(f"[{timestamp}] {content}\n")
        os.chmod(log_path, stat.S_IRUSR | stat.S_IWUSR)

    def read_log(self, filename):
        log_path = (self.log_dir / filename).resolve()
        if not log_path.parent.samefile(self.log_dir):
