import os
import sys
import pycdlib
import wimpy
import tempfile
import shutil
from pathlib import Path

def unpack_iso(iso_path: str, target_dir: str):
    iso = pycdlib.PyCdlib()
    iso.open(iso_path)
    if not os.path.exists(target_dir):
        os.makedirs(target_dir)
    iso.extract_files(target_dir)
    iso.close()

def unpack_wim(wim_path: str, target_dir: str):
    wim = wimpy.WIMFile(wim_path)
    if not os.path.exists(target_dir):
        os.makedirs(target_dir)
    with tempfile.TemporaryDirectory() as temp_dir:
        wim.extract(1, temp_dir)
        for item in os.listdir(temp_dir):
            src = os.path.join(temp_dir, item)
            dst = os.path.join(target_dir, item)
            if os.path.isdir(src):
                shutil.copytree(src, dst)
            else:
                shutil.copy2(src, dst)

def unpack_image(image_path: str, target_dir: str):
    image_path = os.path.abspath(image_path)
    target_dir = os.path.abspath(target_dir)

    if not os.path.exists(image_path):
        raise FileNotFoundError(f"Image file not found: {image_path}")

    ext = Path(image_path).suffix.lower()

    if ext == '.iso':
        unpack_iso(image_path, target_dir)
    elif ext == '.wim':
        unpack_wim(image_path, target_dir)
    else:
        raise ValueError(f"Unsupported image format: {ext}")

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <image_path> <target_dir>")
        sys.exit(1)

    try:
        unpack_image(sys.argv[1], sys.argv[2])
    except Exception as e:
        print(f"Error: {str(e)}", file=sys.stderr)
        sys.exit(1)

if __name__ == "__main__":
