import os
import gzip

def rotate_logs(log_dir):
    if not os.path.isdir(log_dir):
        return

    try:
        log_dir = os.path.abspath(log_dir)
        for f in os.scandir(log_dir):
            if f.is_file() and f.name.endswith('.log'):
                src = os.path.join(log_dir, f.name)
                dst = src + '.1.gz'

                with open(src, 'rb') as f_in:
                    with gzip.open(dst, 'wb', compresslevel=9) as f_out:
                        while True:
                            chunk = f_in.read(8192)
                            if not chunk:
                                break
                            f_out.write(chunk)
                os.unlink(src)
    except (OSError, IOError):
        pass

if __name__ == '__main__':
    rotate_logs('/var/log/')

import tarfile
import os

def extract(tar_file):
    tar = tarfile.open(tar_file)
    safe_path = os.path.abspath(os.path.dirname(tar_file))
    for member in tar.getmembers():
        member_path = os.path.abspath(os.path.join(safe_path, member.name))
        if not member_path.startswith(safe_path):
            raise Exception("Attempted path traversal in tar file")
        if member.islnk() or member.issym():
            raise Exception("Unsupported file type in tar")
    tar.extractall(path=safe_path)
    tar.close()

