from git import Repo
import os
import shutil
import stat
from pathlib import Path

class VersionControl:
    def __init__(self, repo_path):
        self.repo_path = Path(repo_path).resolve()
        if not self.repo_path.exists():
            self.repo = Repo.init(self.repo_path)
        else:
            self.repo = Repo(self.repo_path)

    def clone(self, remote_url, branch='main'):
        if self.repo_path.exists():
            shutil.rmtree(self.repo_path, onerror=self._remove_readonly)
        self.repo = Repo.clone_from(remote_url, self.repo_path, branch=branch)

    def add(self, files):
        if isinstance(files, str):
            files = [files]
        self.repo.index.add(files)

    def commit(self, message):
        self.repo.index.commit(message)

    def push(self, remote='origin', branch='main'):
        origin = self.repo.remote(name=remote)
        origin.push(branch)

    def pull(self, remote='origin', branch='main'):
        origin = self.repo.remote(name=remote)
        origin.pull(branch)

    def create_branch(self, branch_name):
        current = self.repo.create_head(branch_name)
        current.checkout()

    def checkout(self, branch_name):
        self.repo.git.checkout(branch_name)

    def get_status(self):
        return self.repo.git.status()

    def _remove_readonly(self, func, path, _):
        os.chmod(path, stat.S_IWRITE)
        func(path)
