import os
import time
import shutil
from pathlib import Path

def remove_temp_files(directory, age_threshold_days=7):
    current_time = time.time()
    age_threshold = current_time - (age_threshold_days * 86400)

    try:
        for root, dirs, files in os.walk(directory, topdown=True):
            for file in files:
                file_path = Path(root) / file
                if any(file.endswith(ext) for ext in ['.tmp', '.temp', '.bak']):
                    try:
                        stats = file_path.stat()
                        if stats.st_mtime < age_threshold:
                            if file_path.exists():
                                file_path.unlink()
                    except (PermissionError, FileNotFoundError):
                        continue

            for dir in dirs[:]:
                dir_path = Path(root) / dir
                if dir.lower() in ['temp', 'tmp']:
                    try:
                        if dir_path.exists():
                            shutil.rmtree(str(dir_path), ignore_errors=False)
                    except (PermissionError, FileNotFoundError):
                        continue

    except Exception as e:
        raise RuntimeError(f"Error cleaning temporary files: {str(e)}")

if __name__ == "__main__":
    remove_temp_files("/path/to/directory")
