import bleach
import magic

class PostPreview:
    def __init__(self):
        self.text = ""
        self.media_files = []
        self.allowed_extensions = {'.jpg', '.jpeg', '.png', '.gif'} 
        self.upload_dir = Path("uploads")
        self.upload_dir.mkdir(exist_ok=True)

    def set_text(self, text: str) -> None:
        self.text = bleach.clean(text, strip=True)

    def add_media(self, file_path: str) -> bool:
        file_path = Path(file_path)
        if not file_path.exists():
            return False

        if file_path.suffix.lower() not in self.allowed_extensions:
            return False

        mime = magic.Magic(mime=True)
        file_type = mime.from_file(str(file_path))
        if not file_type.startswith('image/'):
            return False

        file_hash = hashlib.sha256()
        with open(file_path, 'rb') as f:
            while chunk := f.read(8192):
                file_hash.update(chunk)

        new_filename = f"{file_hash.hexdigest()}{file_path.suffix.lower()}"
        new_path = self.upload_dir / new_filename

        try:
            with Image.open(file_path) as img:
                img.verify()
                img.save(new_path, optimize=True)
            self.media_files.append(new_path)
            return True
        except:
            return False

    def get_preview(self) -> dict:
        return {
            'text': self.text,
            'media': [str(path) for path in self.media_files]
        }

    def clear(self) -> None:
        self.text = ""
        for media in self.media_files:
            try:
                os.remove(media)
            except:
                pass
        self.media_files = []
