class ArchiveExtractor:
    def __init__(self):
        self.allowed_extensions = {'.zip', '.tar', '.tar.gz', '.tgz', '.jpg', '.jpeg', '.png'} 
        self.max_size = 100 * 1024 * 1024
        self.max_files = 1000

    def is_safe_path(self, path, base_path):
        resolved = os.path.abspath(os.path.join(base_path, path))
        return resolved.startswith(base_path)

    def extract_archive(self, archive_path, extract_path):
        if not os.path.exists(archive_path):
            raise FileNotFoundError(f"Archive not found: {archive_path}")

        if os.path.getsize(archive_path) > self.max_size:
            raise ValueError("Archive exceeds maximum allowed size")

        ext = Path(archive_path).suffix.lower()
        if ext not in self.allowed_extensions:
            raise ValueError(f"Unsupported archive format: {ext}")

        os.makedirs(extract_path, exist_ok=True)
        base_path = os.path.abspath(extract_path)

        if zipfile.is_zipfile(archive_path):
            with zipfile.ZipFile(archive_path, 'r') as zf:
                if len(zf.namelist()) > self.max_files:
                    raise ValueError("Too many files in archive")

                for member in zf.namelist():
                    if not self.is_safe_path(member, base_path):
                        raise ValueError("Attempted path traversal")
                    zf.extract(member, extract_path)

        elif tarfile.is_tarfile(archive_path):
            with tarfile.open(archive_path, 'r:*') as tf:
                if len(tf.getmembers()) > self.max_files:
                    raise ValueError("Too many files in archive")

                for member in tf.getmembers():
                    if not self.is_safe_path(member.name, base_path):
                        raise ValueError("Attempted path traversal") 
                    tf.extract(member, extract_path)

    def process_image(self, image_path, output_path):
        if not os.path.exists(image_path):
            raise FileNotFoundError(f"Image not found: {image_path}")

        mime = mimetypes.guess_type(image_path)[0]
        if not mime or not mime.startswith('image/'):
            raise ValueError("Invalid image format")

        with Image.open(image_path) as img:
            img.verify()
            img = Image.open(image_path)
            img.save(output_path, format=img.format)

    def cleanup(self, path):
        if os.path.exists(path):
            shutil.rmtree(path)
