        self.save_dir = Path('edited_photos')
        self.save_dir.mkdir(exist_ok=True)

    def validate_image(self, img_path):
        if not Path(img_path).suffix.lower() in self.ALLOWED_EXTENSIONS:
            raise ValueError("Invalid file extension")

        if not os.path.getsize(img_path) < self.MAX_FILE_SIZE:
            raise ValueError("File too large")

        if not imghdr.what(img_path):
            raise ValueError("Not a valid image file")

    def safe_filename(self, filename):
        name = Path(filename).stem
        ext = Path(filename).suffix.lower()
        return f"{name}_{secrets.token_hex(8)}{ext}"

    def load_image(self, img_path):
        self.validate_image(img_path)
        return Image.open(img_path)

    def save_image(self, image, filename):
        safe_name = self.safe_filename(filename)
        save_path = self.save_dir / safe_name
        image.save(save_path)
        return save_path

    def resize(self, img_path, size):
        image = self.load_image(img_path)
        resized = image.resize(size)
        return self.save_image(resized, img_path)

    def rotate(self, img_path, degrees):
        image = self.load_image(img_path)
        rotated = image.rotate(degrees)
        return self.save_image(rotated, img_path)

    def apply_filter(self, img_path, filter_name):
        image = self.load_image(img_path)
        if filter_name == "blur":
            filtered = image.filter(ImageFilter.BLUR)
        elif filter_name == "sharpen":
            filtered = image.filter(ImageFilter.SHARPEN)
        else:
