import os
import subprocess
import logging
from pathlib import Path

class Builder:
    def __init__(self, source_dir, output_dir):
        self.source_dir = Path(source_dir)
        self.output_dir = Path(output_dir)
        self.output_dir.mkdir(exist_ok=True)
        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger(__name__)

    def compile_source(self, source_file):
        try:
            output_file = self.output_dir / source_file.stem
            cmd = ["gcc", "-o", str(output_file), str(source_file)]
            result = subprocess.run(cmd, capture_output=True, text=True, check=True)
            self.logger.info(f"Compiled {source_file} to {output_file}")
            return True
        except subprocess.CalledProcessError as e:
            self.logger.error(f"Failed to compile {source_file}: {e.stderr}")
            return False

    def build_all(self):
        success = True
        for source_file in self.source_dir.glob("*.c"):
            if not self.compile_source(source_file):
                success = False
        return success

    def clean(self):
        for exe_file in self.output_dir.glob("*"):
            if exe_file.is_file() and not exe_file.suffix:
                exe_file.unlink()
        self.logger.info("Cleaned output directory")

def main():
    builder = Builder("src", "build")
    builder.clean()
    if builder.build_all():
        return 0
    return 1

if __name__ == "__main__":
    exit(main())
