import os
import sys
import re
import stat
from pathlib import Path

def validate_pattern(pattern):
    try:
        re.compile(pattern)
        return True
    except re.error:
        return False

def validate_path(path):
    return Path(path).resolve().exists()

def validate_perms(perms):
    try:
        mode = int(perms, 8)
        return 0 <= mode <= 0o777
    except ValueError:
        return False

def rename_files(directory, old_pattern, new_pattern, permissions=None):
    if not all([validate_pattern(old_pattern), validate_pattern(new_pattern), 
                validate_path(directory)]):
        sys.exit(1)

    dir_path = Path(directory).resolve()
    if not dir_path.is_dir():
        sys.exit(1)

    if permissions and not validate_perms(permissions):
        sys.exit(1)

    mode = int(permissions, 8) if permissions else None

    for file_path in dir_path.iterdir():
        if file_path.is_file():
            old_name = file_path.name
            if re.search(old_pattern, old_name):
                new_name = re.sub(old_pattern, new_pattern, old_name)
                new_path = file_path.parent / new_name

                try:
                    file_path.rename(new_path)
                    if mode is not None:
                        os.chmod(new_path, mode)
                except OSError:
                    continue

if __name__ == "__main__":
    if len(sys.argv) < 4:
        sys.exit(1)

    directory = sys.argv[1]
    old_pattern = sys.argv[2] 
    new_pattern = sys.argv[3]
    permissions = sys.argv[4] if len(sys.argv) > 4 else None

    rename_files(directory, old_pattern, new_pattern, permissions)
