                    created_by TEXT NOT NULL,
                    created_at TIMESTAMP NOT NULL,
                    UNIQUE(file_path, line_number)
                )
            """)

    def require_permission(permission):
        def decorator(f):
            @wraps(f)
            def wrapper(self, *args, **kwargs):
                user = kwargs.get('user')
                if not user or not self._check_permission(user, permission):
                    raise PermissionError(f"User {user} lacks {permission} permission")
                return f(self, *args, **kwargs)
            return wrapper
        return decorator

    def analyze_coverage(self) -> Dict[str, Set[int]]:
        self.coverage.start()
        self._run_tests()
        self.coverage.stop()

        uncovered = {}
