        with sqlite3.connect(str(self.db_path)) as conn:
            cursor = conn.execute(
                "SELECT * FROM annotations WHERE file_path = ?", 
                (file_path,)
            )
            return {
                row[2]: CodeAnnotation(
                    file_path=row[1],
                    line_number=row[2],
                    annotation=row[3],
                    created_by=row[4],
                    created_at=datetime.fromisoformat(row[5])
                )
                for row in cursor.fetchall()
            }

    def _check_permission(self, user: str, permission: str) -> bool:
        permissions = {
            'admin': {'write_annotations', 'read_annotations'},
            'developer': {'read_annotations'}
        }
