    if request.method == 'POST':
        address = bleach.clean(request.form['address'])

        geocoding_url = f'https://maps.googleapis.com/maps/api/geocode/json?address={address}&key={GOOGLE_MAPS_API_KEY}'

        try:
            response = requests.get(geocoding_url)
            data = response.json()

            if data['status'] == 'OK':
                location = data['results'][0]['geometry']['location']
                lat = location['lat']
                lng = location['lng']

                stores = find_nearby_stores(lat, lng)
                return render_template('results.html', stores=stores, address=address)

        except requests.exceptions.RequestException:
            return render_template('error.html')

    return render_template('search.html')

def find_nearby_stores(lat, lng):
    places_url = f'https://maps.googleapis.com/maps/api/place/nearbysearch/json?location={lat},{lng}&radius=5000&type=store&key={GOOGLE_MAPS_API_KEY}'

    try:
        response = requests.get(places_url)
        data = response.json()

        if data['status'] == 'OK':
            stores = []
            for place in data['results'][:5]:
                store = {
                    'name': place['name'],
                    'address': place['vicinity'],
                    'lat': place['geometry']['location']['lat'],
                    'lng': place['geometry']['location']['lng']
                }
                stores.append(store)
            return stores

    except requests.exceptions.RequestException:
        return []

