        if cuisine:
            filtered = [r for r in filtered if r.cuisine == cuisine]

        if min_rating:
            filtered = [r for r in filtered if r.rating >= min_rating]

        return sorted(filtered, key=lambda r: r.rating, reverse=True)

    def place_order(self, token: str, restaurant_id: int, item_ids: List[int]) -> float:
