import os
import requests
import tarfile
import shutil
import subprocess
from pathlib import Path
import hashlib
import yaml

class PackageManager:
    def __init__(self, config_path="config.yml"):
        with open(config_path) as f:
            self.config = yaml.safe_load(f)
        self.repos = self.config["repositories"]
        self.cache_dir = Path(self.config["cache_dir"])
        self.install_dir = Path(self.config["install_dir"]) 

    def install(self, package_name, version=None):
        package_info = self._find_package(package_name, version)
        if not package_info:
            raise Exception(f"Package {package_name} not found")

        package_path = self._download_package(package_info)
        self._verify_checksum(package_path, package_info["checksum"])
        self._install_package(package_path, package_info["format"])

    def _find_package(self, name, version):
        for repo in self.repos:
            response = requests.get(f"{repo['url']}/packages/{name}")
            if response.status_code == 200:
                packages = response.json()
                if version:
                    return next((p for p in packages if p["version"] == version), None)
                return packages[0]
        return None

    def _download_package(self, package_info):
        self.cache_dir.mkdir(exist_ok=True)
        package_path = self.cache_dir / package_info["filename"]

        if not package_path.exists():
            response = requests.get(package_info["url"], stream=True)
            with open(package_path, "wb") as f:
                shutil.copyfileobj(response.raw, f)

        return package_path

    def _verify_checksum(self, file_path, expected_checksum):
        sha256 = hashlib.sha256()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                sha256.update(chunk)
        if sha256.hexdigest() != expected_checksum:
            raise Exception("Package checksum verification failed")

    def _install_package(self, package_path, format_type):
        if format_type == "deb":
            subprocess.run(["dpkg", "-i", str(package_path)], check=True)
        elif format_type == "rpm":
            subprocess.run(["rpm", "-i", str(package_path)], check=True)
        elif format_type == "tar":
            with tarfile.open(package_path) as tar:
                tar.extractall(path=self.install_dir)
