def create_backup(files):
    with tarfile.open('backup.tar.gz', 'w:gz') as tar:
        for f in files:
            if os.path.isabs(f) or '..' in f:
                raise ValueError("Invalid file path")
            if not os.path.exists(f):
                raise FileNotFoundError(f"File not found: {f}")
            tar.add(f)

def restore_backup(backup_file, extraction_dir):
    if not os.path.exists(extraction_dir):
        raise FileNotFoundError("Extraction directory does not exist")

    with tarfile.open(backup_file, 'r:gz') as tar:
        members = tar.getmembers()
        for member in members:
            member_path = os.path.join(extraction_dir, member.name)
            if not os.path.normpath(member_path).startswith(os.path.normpath(extraction_dir)):
                raise ValueError("Attempted path traversal")
        tar.extractall(path=extraction_dir, members=members)

