import os
from pathlib import Path

def rename_files(directory, old_pattern, new_pattern):
    try:
        directory_path = Path(directory).resolve()
        if not directory_path.is_dir():
            raise NotADirectoryError

        for file_path in directory_path.iterdir():
            if file_path.is_file():
                old_name = file_path.name
                if old_pattern in old_name:
                    new_name = old_name.replace(old_pattern, new_pattern)
                    new_path = file_path.with_name(new_name)
                    if not new_path.exists():
                        file_path.rename(new_path)

    except (PermissionError, NotADirectoryError, OSError) as e:
        raise

def main():
    try:
        directory = input("Enter directory path: ").strip()
        old_pattern = input("Enter text to replace: ").strip()
        new_pattern = input("Enter new text: ").strip()

        if not old_pattern or not directory:
            raise ValueError

        rename_files(directory, old_pattern, new_pattern)

    except (ValueError, PermissionError, NotADirectoryError, OSError):
