from string import Template
import os
import re
from pathlib import Path
import secrets

class SecureTemplateEngine:
    def __init__(self, template_dir):
        self.template_dir = Path(template_dir)
        self._verify_path(self.template_dir)

    def _verify_path(self, path):
        resolved = path.resolve()
        if not resolved.exists():
            raise ValueError("Path does not exist")
        if not resolved.is_relative_to(self.template_dir):
            raise ValueError("Path traversal attempt detected")

    def render_template(self, template_name, data):
        template_path = self.template_dir / template_name
        self._verify_path(template_path)

        with open(template_path, 'r') as f:
            template_str = f.read()

        template = Template(template_str)
        safe_data = {k: self._sanitize_value(v) for k,v in data.items()}
        return template.safe_substitute(safe_data)

    def _sanitize_value(self, value):
        if not isinstance(value, str):
            value = str(value)
        value = re.sub(r'[^\w\s-]', '', value)
        return value

    def generate_file(self, template_name, data, output_dir):
        output_dir = Path(output_dir)
        if not output_dir.exists():
            output_dir.mkdir(parents=True)

        output_filename = f"{secrets.token_hex(8)}.txt"
        output_path = output_dir / output_filename

        content = self.render_template(template_name, data)

        with open(output_path, 'w') as f:
            f.write(content)

        return output_path
