import os
import stat
from pathlib import Path
import tempfile

def create_file(path, content):
    path = os.path.abspath(path)
    if not os.path.dirname(path):
        raise ValueError("Invalid path")
    os.makedirs(os.path.dirname(path), mode=0o700, exist_ok=True)
    with open(path, 'w', opener=lambda p, f: os.open(p, f | os.O_CREAT, 0o600)) as f:
        f.write(content)

def get_file_metadata(path):
    path = Path(path).resolve()
    if not path.exists():
        raise FileNotFoundError
    stats = path.stat()
    return {
        'permissions': stat.filemode(stats.st_mode),
        'owner': stats.st_uid,
        'group': stats.st_gid,
        'size': stats.st_size,
        'modified': stats.st_mtime,
        'accessed': stats.st_atime
    }

def list_directory(path):
    path = Path(path).resolve()
    if not path.is_dir():
        raise NotADirectoryError
    entries = []
    for entry in path.iterdir():
        try:
            metadata = get_file_metadata(entry)
            entries.append((str(entry), metadata))
        except (PermissionError, FileNotFoundError):
            continue
    return entries

def main():
    with tempfile.TemporaryDirectory(prefix='secure_') as tmpdir:
        create_file(os.path.join(tmpdir, 'foo.txt'), 'Hello world!')
        print(list_directory(tmpdir))

if __name__ == '__main__':
    main()

