import os
import shutil
import hashlib
import logging
from pathlib import Path

class ArtifactBuilder:
    def __init__(self, source_dir: str, output_dir: str):
        self.source_dir = Path(source_dir)
        self.output_dir = Path(output_dir)
        self.artifacts = []

        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger(__name__)

    def setup_dirs(self):
        os.makedirs(self.output_dir, exist_ok=True)

    def calculate_file_hash(self, file_path: Path) -> str:
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for block in iter(lambda: f.read(4096), b''):
                sha256.update(block)
        return sha256.hexdigest()

    def copy_artifact(self, source: Path, dest: Path):
        shutil.copy2(source, dest)
        self.artifacts.append(dest)
        artifact_hash = self.calculate_file_hash(dest)
        self.logger.info(f'Created artifact: {dest} (SHA256: {artifact_hash})')

    def build(self, file_patterns=None):
        if not file_patterns:
            file_patterns = ['*.py', '*.txt', '*.json']

        self.setup_dirs()

        for pattern in file_patterns:
            for source_file in self.source_dir.rglob(pattern):
                if source_file.is_file():
                    rel_path = source_file.relative_to(self.source_dir)
                    dest_file = self.output_dir / rel_path
                    os.makedirs(dest_file.parent, exist_ok=True)
                    self.copy_artifact(source_file, dest_file)

    def clean(self):
        for artifact in self.artifacts:
            try:
                os.remove(artifact)
            except OSError as e:
                self.logger.error(f'Error removing {artifact}: {e}')
        shutil.rmtree(self.output_dir, ignore_errors=True)
        self.artifacts.clear()
