import os

def extract_and_relocate(package, dest_dir):
    if not os.path.exists(dest_dir):
        os.makedirs(dest_dir, mode=0o755)

    tar = tarfile.open(package)
    members = tar.getmembers()

    for member in members:
        if member.name.startswith(('/', '..')):
            continue
        if not os.path.abspath(os.path.join(os.getcwd(), member.name)).startswith(os.getcwd()):
            continue

    tar.extractall('package')
    tar.close()

    for f in glob.glob('package/*'):
        final_path = os.path.join(dest_dir, os.path.basename(f))
        if os.path.exists(final_path):
            os.remove(final_path)
        shutil.move(f, dest_dir)

    with open(os.path.join(dest_dir, 'installed_files.txt'), 'w') as f:
        for installed_file in glob.glob(os.path.join(dest_dir, '*')):
            f.write(installed_file + '\n')

