        results = {}
        for filename in self.file_lines:
            total_lines = len(self.file_lines[filename])
            covered = len(self.covered_lines[filename])
            if total_lines > 0:
                coverage = (covered / total_lines) * 100
            else:
                coverage = 0
            results[filename] = coverage
        return results

