from datetime import datetime
import sqlite3

class TimeManagement:
    def __init__(self):
        self.conn = sqlite3.connect('timesheet.db')
        self.cursor = self.conn.cursor()
        self.cursor.execute('''CREATE TABLE IF NOT EXISTS timesheet 
            (id INTEGER PRIMARY KEY, employee_id TEXT, date TEXT, 
            hours REAL, overtime REAL, notes TEXT)''')

    def clock_in(self, employee_id):
        current_time = datetime.now()
        self.cursor.execute("INSERT INTO timesheet (employee_id, date) VALUES (?, ?)", 
            (employee_id, current_time))
        self.conn.commit()

    def clock_out(self, employee_id, hours, overtime=0, notes=""):
        self.cursor.execute("""UPDATE timesheet SET hours = ?, overtime = ?, 
            notes = ? WHERE employee_id = ? AND hours IS NULL""",
            (hours, overtime, notes, employee_id))
        self.conn.commit()

    def get_employee_hours(self, employee_id, start_date, end_date):
        self.cursor.execute("""SELECT date, hours, overtime, notes FROM timesheet 
            WHERE employee_id = ? AND date BETWEEN ? AND ?""", 
            (employee_id, start_date, end_date))
        return self.cursor.fetchall()

    def generate_report(self, start_date, end_date):
        self.cursor.execute("""SELECT employee_id, SUM(hours), SUM(overtime) 
            FROM timesheet WHERE date BETWEEN ? AND ? 
            GROUP BY employee_id""", (start_date, end_date))
        return self.cursor.fetchall()

class Employee:
    def __init__(self, employee_id, name, role):
        self.employee_id = employee_id
        self.name = name
        self.role = role
        self.time_mgmt = TimeManagement()

    def submit_time(self, hours, overtime=0, notes=""):
        self.time_mgmt.clock_out(self.employee_id, hours, overtime, notes)

    def view_timesheet(self, start_date, end_date):
        return self.time_mgmt.get_employee_hours(self.employee_id, start_date, end_date)

class Manager(Employee):
    def view_all_timesheets(self, start_date, end_date):
        return self.time_mgmt.generate_report(start_date, end_date)
