import re
from collections import Counter, defaultdict
from datetime import datetime
import os
from typing import Dict, List

class LogAnalyzer:
    def __init__(self, log_path: str):
        self.log_path = log_path
        self.ip_counts: Counter = Counter()
        self.status_codes: Counter = Counter() 
        self.urls: Counter = Counter()
        self.errors: List[str] = []
        self.hourly_traffic: Dict[str, int] = defaultdict(int)

    def parse_log_line(self, line: str) -> dict:
        pattern = r'(\d+\.\d+\.\d+\.\d+).*\[(.*?)\] "(.*?)" (\d+)'
        match = re.search(pattern, line)
        if match:
            ip, timestamp, request, status = match.groups()
            try:
                dt = datetime.strptime(timestamp, '%d/%b/%Y:%H:%M:%S %z')
                hour = dt.strftime('%Y-%m-%d %H:00')
                return {'ip': ip, 'timestamp': dt, 'hour': hour,
                       'request': request, 'status': status}
            except ValueError:
                self.errors.append(f"Invalid timestamp format: {timestamp}")
        return {}

    def analyze(self):
        if not os.path.exists(self.log_path):
            raise FileNotFoundError(f"Log file not found: {self.log_path}")

        with open(self.log_path, 'r', encoding='utf-8') as f:
            for line in f:
                parsed = self.parse_log_line(line.strip())
                if parsed:
                    self.ip_counts[parsed['ip']] += 1
                    self.status_codes[parsed['status']] += 1
                    self.urls[parsed['request']] += 1
                    self.hourly_traffic[parsed['hour']] += 1

    def generate_report(self) -> dict:
        return {
            'top_ips': dict(self.ip_counts.most_common(10)),
            'status_code_dist': dict(self.status_codes),
            'top_urls': dict(self.urls.most_common(10)),
            'hourly_traffic': dict(sorted(self.hourly_traffic.items())),
            'total_requests': sum(self.ip_counts.values()),
            'unique_ips': len(self.ip_counts),
            'errors': self.errors
        }

def main():
    analyzer = LogAnalyzer('/path/to/access.log')
    analyzer.analyze()
    report = analyzer.generate_report()
    for key, value in report.items():
        print(f"\n{key}:")
        print(value)

if __name__ == '__main__':
    main()
