from pathlib import Path
from collections import defaultdict

def get_file_hash(filepath):
    hasher = hashlib.sha256()
    with open(filepath, 'rb') as f:
        buf = f.read(65536)
        while len(buf) > 0:
            hasher.update(buf)
            buf = f.read(65536)
    return hasher.hexdigest()

def find_duplicates(directory):
    file_hashes = defaultdict(list)

    for filepath in Path(directory).rglob('*'):
        if filepath.is_file():
            file_hash = get_file_hash(filepath)
            file_hashes[file_hash].append(str(filepath))

    return {k:v for k,v in file_hashes.items() if len(v) > 1}

def cleanup_duplicates(duplicates):
    for hash_value, file_list in duplicates.items():
        print(f"\nDuplicate files (hash: {hash_value}):")
        for i, filepath in enumerate(file_list, 1):
            print(f"{i}. {filepath} ({os.path.getsize(filepath)} bytes)")

        keep = int(input("\nWhich file to keep? (Enter the number): ")) - 1

        for i, filepath in enumerate(file_list):
            if i != keep:
                try:
                    os.remove(filepath)
                    print(f"Deleted: {filepath}")
                except OSError as e:
                    print(f"Error deleting {filepath}: {e}")

def main():
