    if not os.path.isdir(directory):
        print("Invalid directory path")
        return

    print("Scanning for duplicates...")
    duplicates = find_duplicates(directory)

    if not duplicates:
        print("No duplicates found")
        return

    cleanup_duplicates(duplicates)

