import os
import shutil
from datetime import datetime
import hashlib
import json
from pathlib import Path

class SourceControl:
    def __init__(self, repo_path, backup_path):
        self.repo_path = Path(repo_path).resolve()
        self.backup_path = Path(backup_path).resolve()
        self.backup_path.mkdir(parents=True, exist_ok=True)
        self.manifest_file = self.backup_path / 'manifest.json'
        self.manifest = self._load_manifest()

    def _load_manifest(self):
        if self.manifest_file.exists():
            with open(self.manifest_file, 'r') as f:
                return json.load(f)
        return {'revisions': {}}

    def _save_manifest(self):
        with open(self.manifest_file, 'w') as f:
            json.dump(self.manifest, f, indent=2)

    def _hash_file(self, filepath):
        sha256 = hashlib.sha256()
        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest()

    def backup(self, message=''):
        timestamp = datetime.now().strftime('%Y-%m-%d_%H-%M-%S')
        backup_dir = self.backup_path / timestamp
        backup_dir.mkdir()

        file_hashes = {}
        for root, _, files in os.walk(self.repo_path):
            rel_path = Path(root).relative_to(self.repo_path)
            for file in files:
                src_file = Path(root) / file
                dest_file = backup_dir / rel_path / file
                dest_file.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src_file, dest_file)
                file_hashes[str(rel_path / file)] = self._hash_file(src_file)

        self.manifest['revisions'][timestamp] = {
            'message': message,
            'files': file_hashes
        }
        self._save_manifest()
        return timestamp

    def restore(self, timestamp):
        if timestamp not in self.manifest['revisions']:
            raise ValueError(f'Revision {timestamp} not found')

        backup_dir = self.backup_path / timestamp
        if not backup_dir.exists():
            raise ValueError(f'Backup directory for {timestamp} not found')

        shutil.rmtree(self.repo_path)
        shutil.copytree(backup_dir, self.repo_path)

    def list_revisions(self):
        return list(self.manifest['revisions'].keys())

    def get_revision_info(self, timestamp):
        return self.manifest['revisions'].get(timestamp)

repo = SourceControl('/var/www/repo', '/var/www/backups')
timestamp = repo.backup('Initial commit')
repo.restore(timestamp)
