import os
import shutil
import subprocess
import git
import requests
from pathlib import Path
import tempfile

class BuildSystem:
    def __init__(self, repo_url, build_dir, artifact_dir):
        self.repo_url = repo_url
        self.build_dir = Path(build_dir)
        self.artifact_dir = Path(artifact_dir)
        self.temp_dir = None

    def setup(self):
        self.temp_dir = tempfile.mkdtemp()
        self.build_dir.mkdir(exist_ok=True)
        self.artifact_dir.mkdir(exist_ok=True)

    def fetch_source(self):
        git.Repo.clone_from(self.repo_url, self.temp_dir)

    def run_tests(self):
        test_cmd = ['python', '-m', 'pytest']
        result = subprocess.run(test_cmd, cwd=self.temp_dir, capture_output=True, text=True)
        if result.returncode != 0:
            raise Exception(f"Tests failed: {result.stderr}")

    def build(self):
        build_cmd = ['python', 'setup.py', 'build']
        result = subprocess.run(build_cmd, cwd=self.temp_dir, capture_output=True, text=True)
        if result.returncode != 0:
            raise Exception(f"Build failed: {result.stderr}")

    def publish_artifacts(self):
        for artifact in Path(self.temp_dir).glob('dist/*'):
            shutil.copy2(artifact, self.artifact_dir)

    def cleanup(self):
        if self.temp_dir:
            shutil.rmtree(self.temp_dir)

    def run(self):
        try:
            self.setup()
            self.fetch_source()
            self.run_tests()
            self.build()
            self.publish_artifacts()
        finally:
            self.cleanup()

def main():
    builder = BuildSystem(
        repo_url="https://github.com/example/repo.git",
        build_dir="./build",
        artifact_dir="./artifacts"
    )
    builder.run()

if __name__ == "__main__":
    main()
