        raise FileNotFoundError("Destination directory does not exist")
    if not os.access(parent_dir, os.W_OK):
        raise PermissionError("No write permission for destination directory")

    log_files = glob.glob(os.path.join(directory, '*.log'))
    current_time = os.time()
    old_logs = [f for f in log_files if os.path.getctime(f) < current_time - 60*24*60*60]

    if old_logs:
        with zipfile.ZipFile(zip_path, 'w', zipfile.ZIP_DEFLATED) as z:
            for f in old_logs:
                if os.path.isfile(f) and os.access(f, os.R_OK):
                    z.write(f, os.path.basename(f))

