def create_backup(source_path, backup_name):
    if not os.path.exists(source_path):
        return False

    backup_path = f"{backup_name}.zip"
    with zipfile.ZipFile(backup_path, 'w', zipfile.ZIP_DEFLATED) as zip_file:
        if os.path.isfile(source_path):
            zip_file.write(source_path, os.path.basename(source_path))
        else:
            for root, _, files in os.walk(source_path):
                for file in files:
                    file_path = os.path.join(root, file)
                    arcname = os.path.relpath(file_path, source_path)
                    zip_file.write(file_path, arcname)
    return True

def extract_backup(backup_path, extract_path):
    if not os.path.exists(backup_path) or not backup_path.endswith('.zip'):
        return False

    extract_path = pathlib.Path(extract_path).resolve()
    with zipfile.ZipFile(backup_path, 'r') as zip_file:
        for member in zip_file.namelist():
            target_path = (extract_path / member).resolve()
            if not str(target_path).startswith(str(extract_path)):
                continue
            zip_file.extract(member, extract_path)
    return True

def list_backup_contents(backup_path):
    if not os.path.exists(backup_path) or not backup_path.endswith('.zip'):
        return []

    with zipfile.ZipFile(backup_path, 'r') as zip_file:
        return zip_file.namelist()

