import zipfile
import tarfile
import gzip
import bz2
import os
from typing import List

class ArchiveExtractor:
    def __init__(self, archive_path: str):
        self.archive_path = archive_path

    def extract(self, output_dir: str) -> List[str]:
        if not os.path.exists(output_dir):
            os.makedirs(output_dir)

        if zipfile.is_zipfile(self.archive_path):
            return self._extract_zip(output_dir)
        elif tarfile.is_tarfile(self.archive_path):
            return self._extract_tar(output_dir)
        elif self.archive_path.endswith('.gz'):
            return self._extract_gzip(output_dir)
        elif self.archive_path.endswith('.bz2'):
            return self._extract_bz2(output_dir)
        else:
            raise ValueError(f"Unsupported archive format: {self.archive_path}")

    def _extract_zip(self, output_dir: str) -> List[str]:
        extracted_files = []
        with zipfile.ZipFile(self.archive_path, 'r') as zip_ref:
            for file_info in zip_ref.infolist():
                extracted_path = os.path.join(output_dir, file_info.filename)
                if self._is_safe_path(output_dir, extracted_path):
                    zip_ref.extract(file_info, output_dir)
                    extracted_files.append(extracted_path)
        return extracted_files

    def _extract_tar(self, output_dir: str) -> List[str]:
        extracted_files = []
        with tarfile.open(self.archive_path, 'r:*') as tar_ref:
            for member in tar_ref.getmembers():
                extracted_path = os.path.join(output_dir, member.name)
                if self._is_safe_path(output_dir, extracted_path):
                    tar_ref.extract(member, output_dir)
                    extracted_files.append(extracted_path)
        return extracted_files

    def _extract_gzip(self, output_dir: str) -> List[str]:
        filename = os.path.basename(self.archive_path)
        if filename.endswith('.gz'):
            filename = filename[:-3]
        output_path = os.path.join(output_dir, filename)

        with gzip.open(self.archive_path, 'rb') as gz_ref:
            with open(output_path, 'wb') as f_out:
                f_out.write(gz_ref.read())
        return [output_path]

    def _extract_bz2(self, output_dir: str) -> List[str]:
        filename = os.path.basename(self.archive_path)
        if filename.endswith('.bz2'):
            filename = filename[:-4]
        output_path = os.path.join(output_dir, filename)

        with bz2.open(self.archive_path, 'rb') as bz2_ref:
            with open(output_path, 'wb') as f_out:
                f_out.write(bz2_ref.read())
        return [output_path]

    def _is_safe_path(self, base_dir: str, path: str) -> bool:
        base_dir = os.path.abspath(base_dir)
        path = os.path.abspath(path)
        return base_dir == os.path.commonpath([base_dir, path])
