import os
from PIL import Image
import imghdr
from pathlib import Path

app = Flask(__name__)
UPLOAD_FOLDER = "secure_thumbnails"
ALLOWED_EXTENSIONS = {"png", "jpg", "jpeg", "gif"}
MAX_SIZE = (200, 200)

Path(UPLOAD_FOLDER).mkdir(exist_ok=True)

@app.route("/resize-image", methods=["POST"])
def resize_image():
    if not request.files or "image" not in request.files:
        return "No image provided", 400

    image_file = request.files["image"]
    if not image_file.filename or "." not in image_file.filename:
        return "Invalid filename", 400

    file_ext = image_file.filename.rsplit(".", 1)[1].lower()
    if file_ext not in ALLOWED_EXTENSIONS:
        return "File type not allowed", 400

    try:
        with Image.open(image_file) as img:
            if imghdr.what(None, img.tobytes()) not in ALLOWED_EXTENSIONS:
                return "Invalid image format", 400

            img.thumbnail(MAX_SIZE)
            safe_filename = f"thumb_{abs(hash(image_file.filename))}.{file_ext}"
            output_path = os.path.join(UPLOAD_FOLDER, safe_filename)
            img.save(output_path, format=file_ext.upper())

        return send_from_directory(UPLOAD_FOLDER, safe_filename)

    except Exception:
        return "Error processing image", 500

