import os
import subprocess
from pathlib import Path

class ArchiveExtractor:
    def __init__(self, seven_zip_path="7z"):
        self.seven_zip_path = seven_zip_path

    def extract(self, archive_path, output_dir=None):
        archive_path = Path(archive_path).resolve()
        if not archive_path.exists():
            raise FileNotFoundError(f"Archive not found: {archive_path}")

        if output_dir is None:
            output_dir = archive_path.parent
        output_dir = Path(output_dir).resolve()

        if not output_dir.exists():
            output_dir.mkdir(parents=True)

        cmd = [self.seven_zip_path, "x", str(archive_path), f"-o{output_dir}", "-y"]
        process = subprocess.run(cmd, capture_output=True, text=True)

        if process.returncode != 0:
            raise RuntimeError(f"Extraction failed: {process.stderr}")

        return output_dir

    def list_contents(self, archive_path):
        archive_path = Path(archive_path).resolve()
        if not archive_path.exists():
            raise FileNotFoundError(f"Archive not found: {archive_path}")

        cmd = [self.seven_zip_path, "l", str(archive_path)]
        process = subprocess.run(cmd, capture_output=True, text=True)

        if process.returncode != 0:
            raise RuntimeError(f"Listing failed: {process.stderr}")

        return process.stdout

    def test(self):
        cmd = [self.seven_zip_path, "--help"]
        try:
            subprocess.run(cmd, capture_output=True, check=True)
            return True
        except subprocess.CalledProcessError:
            return False
        except FileNotFoundError:
            return False
