from dataclasses import dataclass
from typing import Dict, List, Optional
import hashlib
import os
import time

@dataclass
class FileRevision:
    content: bytes
    timestamp: float
    hash: str

class VersionControl:
    def __init__(self, working_dir: str):
        self.working_dir = working_dir
        self.file_history: Dict[str, List[FileRevision]] = {}

    def add_file(self, filepath: str) -> None:
        abs_path = os.path.join(self.working_dir, filepath)
        with open(abs_path, 'rb') as f:
            content = f.read()
        revision = FileRevision(
            content=content,
            timestamp=time.time(),
            hash=hashlib.sha256(content).hexdigest()
        )
        if filepath not in self.file_history:
            self.file_history[filepath] = []
        self.file_history[filepath].append(revision)

    def get_revision(self, filepath: str, revision_idx: int = -1) -> Optional[FileRevision]:
        if filepath not in self.file_history:
            return None
        revisions = self.file_history[filepath]
        if not (0 <= revision_idx < len(revisions)):
            return None
        return revisions[revision_idx]

    def merge_changes(self, filepath: str, other_content: bytes) -> bytes:
        current = self.get_revision(filepath)
        if not current:
            return other_content

        original = current.content
        modified = other_content

        merged = bytearray(original)
        diff_start = 0

        for i in range(min(len(original), len(modified))):
            if original[i] != modified[i]:
                diff_start = i
                break

        merged[diff_start:] = modified[diff_start:]
        return bytes(merged)

    def commit_merge(self, filepath: str, merged_content: bytes) -> None:
        revision = FileRevision(
            content=merged_content,
            timestamp=time.time(),
            hash=hashlib.sha256(merged_content).hexdigest()
        )
        self.file_history[filepath].append(revision)
