            raise ValueError("Invalid username")

        user_id = self.next_user_id
        self.users[user_id] = User(user_id, username, set())
        self.next_user_id += 1
        return user_id

    def add_friend(self, user_id: int, friend_id: int) -> None:
        if user_id not in self.users or friend_id not in self.users:
            raise ValueError("Invalid user IDs")
        if user_id == friend_id:
            raise ValueError("Cannot friend yourself")

        self.users[user_id].friends.add(friend_id)
        self.users[friend_id].friends.add(user_id)

    def create_post(self, author_id: int, content: str, tagged_users: List[int]) -> int:
        if author_id not in self.users:
            raise ValueError("Invalid author ID")

        content = bleach.clean(content)[:1000]
        tagged = set()

        for user_id in tagged_users:
            if user_id in self.users and user_id in self.users[author_id].friends:
                tagged.add(user_id)

        post_id = self.next_post_id
        self.posts[post_id] = Post(
            post_id,
            author_id,
            content,
            datetime.now(),
            tagged
        )
        self.next_post_id += 1
        return post_id

    def get_user_posts(self, user_id: int) -> List[Post]:
        if user_id not in self.users:
            raise ValueError("Invalid user ID")

