import time
from pathlib import Path
from typing import List, Set

class BuildSystem:
    def __init__(self, base_dir: str, output_dir: str):
        self.base_dir = Path(base_dir)
        self.output_dir = Path(output_dir)
        self.output_dir.mkdir(parents=True, exist_ok=True)

    def get_files(self) -> List[Path]:
        files: Set[Path] = set()
        for path in self.base_dir.rglob('*'):
            if path.is_file():
                files.add(path)
        return sorted(files)

    def create_tarball(self, version: str) -> str:
        timestamp = int(time.time())
        tarball_name = f"build-{version}-{timestamp}.tar.gz"
        tarball_path = self.output_dir / tarball_name

        with tarfile.open(tarball_path, "w:gz") as tar:
            for file_path in self.get_files():
                rel_path = file_path.relative_to(self.base_dir)
                tar_info = tarfile.TarInfo(name=str(rel_path))
                tar_info.mtime = timestamp
                tar_info.mode = 0o644
                tar_info.uid = 0
                tar_info.gid = 0
                tar_info.uname = "root"
                tar_info.gname = "root"

                with open(file_path, "rb") as f:
                    tar.addfile(tar_info, f)

        return self.get_checksum(tarball_path)

    def get_checksum(self, file_path: Path) -> str:
        sha256 = hashlib.sha256()
        with open(file_path, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                sha256.update(chunk)
        return sha256.hexdigest()

    def build(self, version: str) -> dict:
        checksum = self.create_tarball(version)
        return {
            "version": version,
            "checksum": checksum,
            "timestamp": int(time.time())
        }
