    file_path: str
    uncovered_lines: Set[int]
    permissions: str

class TestCoverageAnalyzer:
    def __init__(self, source_dir: str, test_dir: str):
        self.source_dir = Path(source_dir)
        self.test_dir = Path(test_dir)
        self.cov = coverage.Coverage()

    def analyze(self) -> List[CodeCoverage]:
        self.cov.start()
        self._run_tests()
        self.cov.stop()
        self.cov.save()

        coverage_data = []
        for file in self.source_dir.glob('**/*.py'):
            analysis = self.cov.analysis(str(file))
            if analysis.missing_lines:
                coverage_data.append(
                    CodeCoverage(
                        str(file),
                        set(analysis.missing_lines),
                        "rw-r--r--"
                    )
                )
        return coverage_data

    def annotate_files(self, coverage_data: List[CodeCoverage]):
        for coverage in coverage_data:
            if not os.path.exists(coverage.file_path):
                continue

            with open(coverage.file_path, 'r') as f:
                lines = f.readlines()

            annotated = []
            for i, line in enumerate(lines, 1):
                if i in coverage.uncovered_lines:
                    annotated.append(f"# UNCOVERED\n{line}")
                else:
                    annotated.append(line)

            annotated_path = f"{coverage.file_path}.annotated"
            with open(annotated_path, 'w') as f:
                f.writelines(annotated)

            os.chmod(annotated_path, int(coverage.permissions, 8))

    def _run_tests(self):
