def generate_openapi_doc(app: Flask) -> Dict[str, Any]:
    openapi = {
        'openapi': '3.0.0',
        'info': {
            'title': app.name,
            'version': '1.0.0'
        },
        'paths': {}
    }

    for rule in app.url_map.iter_rules():
        if rule.endpoint == 'static':
            continue

        view_func = app.view_functions[rule.endpoint]
        doc = inspect.getdoc(view_func)

        if not doc:
            continue

        path = str(rule)
        method = list(rule.methods - {'HEAD', 'OPTIONS'})[0].lower()

        if path not in openapi['paths']:
            openapi['paths'][path] = {}

        operation = {
            'summary': doc.split('\n')[0],
            'description': doc,
            'responses': {
                '200': {
                    'description': 'Successful response'
                }
            }
        }

        params = []
        for param in rule.arguments:
            param_type = 'path' if f'<{param}>' in path else 'query'
            params.append({
                'name': param,
                'in': param_type,
                'required': True,
                'schema': {'type': 'string'}
            })

        if params:
            operation['parameters'] = params

        openapi['paths'][path][method] = operation

    return openapi

def generate_openapi_yaml(app: Flask, output_file: str):
    openapi = generate_openapi_doc(app)
    output_path = Path(output_file)
    output_path.write_text(yaml.dump(openapi, sort_keys=False))

def generate_openapi_json(app: Flask, output_file: str):
    import json
    openapi = generate_openapi_doc(app)
    output_path = Path(output_file)
    output_path.write_text(json.dumps(openapi, indent=2))
