from collections import defaultdict
from urllib.parse import urlparse

def get_compression_ratios(urls):
    stats = defaultdict(list)

    for url in urls:
        try:
            response = requests.get(url, timeout=10, verify=True)
            content = response.content
            compressed = gzip.compress(content)
            ratio = len(compressed) / len(content)

            mime_type = response.headers.get('content-type', '')
            if not mime_type:
                mime_type = mimetypes.guess_type(urlparse(url).path)[0] or 'unknown'

            stats[mime_type].append(ratio)

        except requests.exceptions.RequestException:
            continue

    results = {}
    for mime_type, ratios in stats.items():
        results[mime_type] = sum(ratios) / len(ratios)

    return results

def analyze_urls(url_list):
    ratios = get_compression_ratios(url_list)

    for mime_type, ratio in sorted(ratios.items()):
        print(f"{mime_type}: {ratio:.2%}")
