from datetime import datetime
from typing import Dict, List
import bcrypt
from dataclasses import dataclass
import uuid

@dataclass
class Review:
    id: str
    user_id: str
    item_id: str
    rating: int
    title: str
    content: str
    created_at: datetime
    updated_at: datetime

@dataclass
class User:
    id: str
    username: str
    password_hash: bytes
    created_at: datetime

class ReviewSystem:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.reviews: Dict[str, Review] = {}
        self.user_reviews: Dict[str, List[str]] = {}
        self.item_reviews: Dict[str, List[str]] = {}

    def create_user(self, username: str, password: str) -> str:
        if any(u.username == username for u in self.users.values()):
            raise ValueError("Username already exists")

        user_id = str(uuid.uuid4())
        password_hash = bcrypt.hashpw(password.encode(), bcrypt.gensalt())
        user = User(user_id, username, password_hash, datetime.now())
        self.users[user_id] = user
        self.user_reviews[user_id] = []
        return user_id

    def authenticate_user(self, username: str, password: str) -> str:
        user = next((u for u in self.users.values() if u.username == username), None)
        if not user or not bcrypt.checkpw(password.encode(), user.password_hash):
            raise ValueError("Invalid credentials")
        return user.id

    def create_review(self, user_id: str, item_id: str, rating: int, title: str, content: str) -> str:
        if user_id not in self.users:
            raise ValueError("Invalid user")
        if not (1 <= rating <= 5):
            raise ValueError("Rating must be between 1 and 5")

        review_id = str(uuid.uuid4())
        now = datetime.now()
        review = Review(review_id, user_id, item_id, rating, title, content, now, now)

        self.reviews[review_id] = review
        self.user_reviews[user_id].append(review_id)

        if item_id not in self.item_reviews:
            self.item_reviews[item_id] = []
        self.item_reviews[item_id].append(review_id)

        return review_id

    def get_user_reviews(self, user_id: str) -> List[Review]:
        if user_id not in self.users:
            raise ValueError("Invalid user")
        return [self.reviews[review_id] for review_id in self.user_reviews[user_id]]

    def get_item_reviews(self, item_id: str) -> List[Review]:
        if item_id not in self.item_reviews:
            return []
        return [self.reviews[review_id] for review_id in self.item_reviews[item_id]]

    def update_review(self, user_id: str, review_id: str, rating: int, title: str, content: str) -> None:
        if review_id not in self.reviews:
            raise ValueError("Review not found")
        review = self.reviews[review_id]
        if review.user_id != user_id:
            raise ValueError("Not authorized")
        if not (1 <= rating <= 5):
            raise ValueError("Rating must be between 1 and 5")

        review.rating = rating
        review.title = title
        review.content = content
        review.updated_at = datetime.now()

    def delete_review(self, user_id: str, review_id: str) -> None:
        if review_id not in self.reviews:
            raise ValueError("Review not found")
        review = self.reviews[review_id]
        if review.user_id != user_id:
            raise ValueError("Not authorized")

        self.user_reviews[user_id].remove(review_id)
        self.item_reviews[review.item_id].remove(review_id)
        del self.reviews[review_id]
