import os
import json
from pathlib import Path

class MediaPlayer:
    def __init__(self):
        self.playlists = {}
        self.playlist_dir = Path.home() / "playlists"
        self.playlist_dir.mkdir(mode=0o700, exist_ok=True)

    def create_playlist(self, name):
        if not name.isalnum():
            raise ValueError("Playlist name must be alphanumeric")
        self.playlists[name] = []

    def add_to_playlist(self, playlist_name, media_file):
        if playlist_name not in self.playlists:
            raise ValueError("Playlist does not exist")
        if not Path(media_file).exists():
            raise ValueError("Media file does not exist")
        self.playlists[playlist_name].append(str(Path(media_file).resolve()))

    def save_playlist(self, playlist_name):
        if playlist_name not in self.playlists:
            raise ValueError("Playlist does not exist")

        playlist_path = self.playlist_dir / f"{playlist_name}.json"

        with open(playlist_path, 'w') as f:
            json.dump(self.playlists[playlist_name], f)

        os.chmod(playlist_path, 0o600)

    def load_playlist(self, playlist_name):
        playlist_path = self.playlist_dir / f"{playlist_name}.json"

        if not playlist_path.exists():
            raise ValueError("Playlist file does not exist")

        if not playlist_path.is_file():
            raise ValueError("Not a valid playlist file")

        with open(playlist_path, 'r') as f:
            self.playlists[playlist_name] = json.load(f)
