        name = sanitize_input(request.form.get('name', ''))
        email = sanitize_input(request.form.get('email', ''))
        interests = sanitize_input(request.form.get('interests', ''))

        if not name or not email or not interests:
            return 'All fields are required', 400

        if not validate_email(email):
            return 'Invalid email format', 400

        if len(name) > 100 or len(email) > 100 or len(interests) > 500:
            return 'Input length exceeds maximum allowed', 400

        subscriber_id = hashlib.sha256(email.encode()).hexdigest()

        try:
