        self.chat_area.grid(row=0, column=0, padx=10, pady=10)

        self.msg_entry = tk.Entry(self.window, width=30)
        self.msg_entry.grid(row=1, column=0, padx=10, pady=10)

        self.send_button = tk.Button(self.window, text="Send", command=self.send_message)
        self.send_button.grid(row=2, column=0, padx=10, pady=10)

        receive_thread = threading.Thread(target=self.receive_messages)
        receive_thread.daemon = True
        receive_thread.start()

    def send_message(self):
        message = self.msg_entry.get().strip()
        if message:
            encoded_msg = html.escape(message).encode()
            self.sock.send(encoded_msg)
            self.msg_entry.delete(0, tk.END)

    def receive_messages(self):
        while True:
            try:
                message = self.sock.recv(1024).decode()
                safe_message = html.escape(message)
                self.chat_area.insert(tk.END, f"{safe_message}\n")
                self.chat_area.see(tk.END)
            except:
                break

    def run(self):
        self.window.mainloop()

class ChatServer:
    def __init__(self):
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.sock.bind(('localhost', 5555))
        self.sock.listen(5)
        self.clients = []

    def broadcast(self, message, sender=None):
        for client in self.clients:
            if client != sender:
                try:
                    client.send(message)
                except:
                    self.clients.remove(client)

    def handle_client(self, client):
        while True:
            try:
                message = client.recv(1024)
                if message:
                    self.broadcast(message, client)
            except:
                self.clients.remove(client)
                client.close()
                break

    def run(self):
        while True:
            client, address = self.sock.accept()
            self.clients.append(client)
            client_thread = threading.Thread(target=self.handle_client, args=(client,))
            client_thread.daemon = True
            client_thread.start()

if __name__ == "__main__":
    server = ChatServer()
    server_thread = threading.Thread(target=server.run)
    server_thread.daemon = True
    server_thread.start()

    client = ChatClient()
    client.run()
