import tarfile
import os

def extract_artifact(artifact_path):
    if not os.path.exists(artifact_path):
        raise ValueError("File does not exist")

    if not tarfile.is_tarfile(artifact_path):
        raise ValueError("Not a valid tar file")

    dest_path = os.path.dirname(os.path.abspath(artifact_path))

    with tarfile.open(artifact_path) as tar:
        for member in tar.getmembers():
            member_path = os.path.join(dest_path, member.name)
            if os.path.isabs(member.name) or '..' in member.name:
                raise ValueError("Invalid file path in archive")
            if not os.path.normpath(member_path).startswith(dest_path):
                raise ValueError("Path traversal attempt detected")
            tar.extract(member, dest_path)

