    for member in tar.getmembers():
        if member.isfile() and not member.name.startswith(('/','..')) and '..' not in member.name:
            try:
                f = tar.extractfile(member)
                if f:
                    extracted[member.name] = f.read()
            except:
                continue
    tar.close()
    return extracted

