import os
import tarfile
import zipfile
import shutil
from pathlib import Path

def extract_archive(archive_path, dest_path):
    dest = Path(dest_path).resolve()
    archive = Path(archive_path).resolve()

    if not dest.exists():
        os.makedirs(dest)

    if not archive.is_file():
        raise ValueError("Archive does not exist")

    if tarfile.is_tarfile(archive):
        with tarfile.open(archive) as tar:
            def is_safe(member):
                target_path = os.path.join(dest, member.name)
                resolved_path = Path(target_path).resolve()
                return resolved_path.is_relative_to(dest)

            members = [m for m in tar.getmembers() if is_safe(m)]
            tar.extractall(dest, members=members)

    elif zipfile.is_zipfile(archive):
        with zipfile.ZipFile(archive) as zf:
            for member in zf.namelist():
                target_path = os.path.join(dest, member) 
                resolved_path = Path(target_path).resolve()
                if resolved_path.is_relative_to(dest):
                    zf.extract(member, dest)

def deploy_code(archive_path, deploy_path):
    temp_path = os.path.join(deploy_path, 'temp')
    extract_archive(archive_path, temp_path)

    if os.path.exists(deploy_path):
        shutil.rmtree(deploy_path)
    shutil.move(temp_path, deploy_path)
