from datetime import datetime
import bcrypt
import jwt
import uuid

class User:
    def __init__(self, username, password):
        self.user_id = str(uuid.uuid4())
        self.username = username
        self.password = bcrypt.hashpw(password.encode(), bcrypt.gensalt())
        self.rides = []

class Driver:
    def __init__(self, name, vehicle):
        self.driver_id = str(uuid.uuid4())
        self.name = name
        self.vehicle = vehicle
        self.available = True
        self.current_ride = None

class Ride:
    def __init__(self, user, pickup, dropoff):
        self.ride_id = str(uuid.uuid4())
        self.user = user
        self.driver = None
        self.pickup = pickup
        self.dropoff = dropoff
        self.status = "requested"
        self.created_at = datetime.now()

class RideShare:
    def __init__(self):
        self.users = {}
        self.drivers = []
        self.active_rides = []
        self.SECRET_KEY = str(uuid.uuid4())

    def register_user(self, username, password):
        if username in self.users:
            raise ValueError("Username already exists")
        user = User(username, password)
        self.users[username] = user
        return jwt.encode({"user_id": user.user_id}, self.SECRET_KEY, algorithm="HS256")

    def login_user(self, username, password):
        if username not in self.users:
            raise ValueError("Invalid credentials")
        user = self.users[username]
        if not bcrypt.checkpw(password.encode(), user.password):
            raise ValueError("Invalid credentials")
        return jwt.encode({"user_id": user.user_id}, self.SECRET_KEY, algorithm="HS256")

    def add_driver(self, name, vehicle):
        driver = Driver(name, vehicle)
        self.drivers.append(driver)
        return driver.driver_id

    def request_ride(self, token, pickup, dropoff):
        try:
            payload = jwt.decode(token, self.SECRET_KEY, algorithms=["HS256"])
            user = next(u for u in self.users.values() if u.user_id == payload["user_id"])
            ride = Ride(user, pickup, dropoff)
            available_driver = next((d for d in self.drivers if d.available), None)

            if available_driver:
                ride.driver = available_driver
                available_driver.available = False
                available_driver.current_ride = ride
                ride.status = "accepted"

            self.active_rides.append(ride)
            user.rides.append(ride)
            return ride.ride_id

        except jwt.InvalidTokenError:
            raise ValueError("Invalid token")

    def complete_ride(self, ride_id):
        ride = next((r for r in self.active_rides if r.ride_id == ride_id), None)
        if ride and ride.driver:
            ride.status = "completed"
            ride.driver.available = True
            ride.driver.current_ride = None
            self.active_rides.remove(ride)
            return True
        return False

    def get_ride_status(self, ride_id):
        ride = next((r for r in self.active_rides if r.ride_id == ride_id), None)
        return ride.status if ride else None
