import os
import ast
import sys
import stat
from dataclasses import dataclass
from typing import List, Dict
import json

@dataclass
class ComplexityIssue:
    file: str
    method: str
    line_count: int
    complexity: int

class ComplexityAnalyzer:
    def __init__(self, max_lines=50, max_complexity=10):
        self.max_lines = max_lines
        self.max_complexity = max_complexity
        self.issues: List[ComplexityIssue] = []

    def analyze_file(self, filename: str) -> None:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()

            tree = ast.parse(content)
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    line_count = len(node.body)
                    complexity = self._calculate_complexity(node)

                    if line_count > self.max_lines or complexity > self.max_complexity:
                        self.issues.append(ComplexityIssue(
                            file=filename,
                            method=node.name,
                            line_count=line_count,
                            complexity=complexity
                        ))
        except Exception:
            pass

    def _calculate_complexity(self, node: ast.AST) -> int:
        complexity = 1
        for child in ast.walk(node):
            if isinstance(child, (ast.If, ast.While, ast.For, ast.ExceptHandler)):
                complexity += 1
            elif isinstance(child, ast.BoolOp):
                complexity += len(child.values) - 1
        return complexity

    def analyze_directory(self, directory: str) -> None:
        for root, _, files in os.walk(directory):
            for file in files:
                if file.endswith('.py'):
                    self.analyze_file(os.path.join(root, file))

    def generate_report(self, output_file: str) -> None:
        report = {
            'issues': [
                {
                    'file': issue.file,
                    'method': issue.method,
                    'line_count': issue.line_count,
                    'complexity': issue.complexity
                } for issue in self.issues
            ],
            'summary': {
                'total_issues': len(self.issues)
            }
        }

        with open(output_file, 'w', encoding='utf-8') as f:
            os.chmod(output_file, stat.S_IRUSR | stat.S_IWUSR)
            json.dump(report, f, indent=2)

def main():
    if len(sys.argv) < 3:
        sys.exit(1)

    analyzer = ComplexityAnalyzer()
    path = sys.argv[1]
    output_file = sys.argv[2]

    if os.path.isfile(path):
        analyzer.analyze_file(path)
    elif os.path.isdir(path):
        analyzer.analyze_directory(path)

    analyzer.generate_report(output_file)

if __name__ == '__main__':
    main()
