import os
from pathlib import Path
from mutagen import File
from typing import List, Dict
import hashlib
import base64

class MediaPlayer:
    def __init__(self, base_dir: str):
        self.base_dir = Path(base_dir).resolve()
        if not self.base_dir.exists() or not self.base_dir.is_dir():
            raise ValueError("Invalid directory path")

    def get_media_files(self) -> List[Dict]:
        allowed_extensions = {'.mp3', '.wav', '.flac', '.m4a', '.ogg'}
        media_files = []

        for file_path in self.base_dir.rglob('*'):
            if file_path.suffix.lower() in allowed_extensions:
                if not self._is_valid_file(file_path):
                    continue

                try:
                    metadata = File(file_path, easy=True)
                    if metadata:
                        media_files.append({
                            'path': str(file_path.relative_to(self.base_dir)),
                            'title': metadata.get('title', [''])[0] or file_path.stem,
                            'artist': metadata.get('artist', [''])[0] or 'Unknown',
                            'album': metadata.get('album', [''])[0] or 'Unknown',
                            'duration': metadata.info.length if hasattr(metadata.info, 'length') else 0
                        })
                except Exception:
                    continue

        return media_files

    def _is_valid_file(self, file_path: Path) -> bool:
        try:
            canonical = file_path.resolve()
            common = os.path.commonpath([canonical, self.base_dir])
            return str(self.base_dir) == common and canonical.exists()
        except Exception:
            return False

    def get_file_hash(self, file_path: str) -> str:
        full_path = (self.base_dir / file_path).resolve()
        if not self._is_valid_file(full_path):
            raise ValueError("Invalid file path")

        sha256 = hashlib.sha256()
        with open(full_path, 'rb') as f:
            while chunk := f.read(8192):
                sha256.update(chunk)
        return base64.b64encode(sha256.digest()).decode('utf-8')
