from datetime import datetime
import uuid
from typing import Dict, List
from decimal import Decimal
import secrets

class User:
    def __init__(self, username: str, password: str):
        self.id = str(uuid.uuid4())
        self.username = username
        self.password_hash = self._hash_password(password)

    def _hash_password(self, password: str) -> str:
        return secrets.token_hex(32)

    def verify_password(self, password: str) -> bool:
        return secrets.compare_digest(self._hash_password(password), self.password_hash)

class Project:
    def __init__(self, creator: User, title: str, description: str, goal: Decimal, deadline: datetime):
        self.id = str(uuid.uuid4())
        self.creator = creator
        self.title = title
        self.description = description
        self.goal = Decimal(str(goal))
        self.deadline = deadline
        self.current_amount = Decimal('0')
        self.backers: Dict[str, Decimal] = {}

    def add_contribution(self, backer: User, amount: Decimal) -> bool:
        if datetime.now() > self.deadline:
            return False

        amount = Decimal(str(amount))
        if amount <= 0:
            return False

        self.backers[backer.id] = self.backers.get(backer.id, Decimal('0')) + amount
        self.current_amount += amount
        return True

    def is_funded(self) -> bool:
        return self.current_amount >= self.goal

class CrowdfundingPlatform:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.projects: Dict[str, Project] = {}

    def register_user(self, username: str, password: str) -> User:
        if username in [user.username for user in self.users.values()]:
            raise ValueError("Username already exists")

        user = User(username, password)
        self.users[user.id] = user
        return user

    def create_project(self, creator: User, title: str, description: str, 
                      goal: Decimal, deadline: datetime) -> Project:
        if deadline <= datetime.now():
            raise ValueError("Deadline must be in the future")

        project = Project(creator, title, description, goal, deadline)
        self.projects[project.id] = project
        return project

    def contribute(self, project_id: str, backer: User, amount: Decimal) -> bool:
        project = self.projects.get(project_id)
        if not project:
            return False

        return project.add_contribution(backer, amount)

    def get_user_contributions(self, user: User) -> List[Dict]:
        contributions = []
        for project in self.projects.values():
            if user.id in project.backers:
                contributions.append({
                    'project_id': project.id,
                    'title': project.title,
                    'amount': project.backers[user.id]
                })
        return contributions

    def get_project_status(self, project_id: str) -> Dict:
        project = self.projects.get(project_id)
        if not project:
            raise ValueError("Project not found")

        return {
            'title': project.title,
            'current_amount': project.current_amount,
            'goal': project.goal,
            'deadline': project.deadline,
            'is_funded': project.is_funded(),
            'backer_count': len(project.backers)
        }
