import zipfile
import pandas as pd
import re
import os
from pathlib import Path
from typing import List, Dict
import logging

class LogAnalyzer:
    def __init__(self, zip_path: str, output_dir: str):
        self.zip_path = Path(zip_path)
        self.output_dir = Path(output_dir)
        self.output_dir.mkdir(parents=True, exist_ok=True)
        logging.basicConfig(filename=self.output_dir / 'analysis.log', level=logging.INFO)

    def extract_logs(self) -> List[Path]:
        extracted_files = []
        with zipfile.ZipFile(self.zip_path, 'r') as zip_ref:
            for file in zip_ref.namelist():
                if file.endswith('.log'):
                    zip_ref.extract(file, self.output_dir)
                    extracted_files.append(self.output_dir / file)
        return extracted_files

    def parse_log_file(self, log_file: Path) -> pd.DataFrame:
        data = []
        pattern = re.compile(r'(\d{4}-\d{2}-\d{2}\s\d{2}:\d{2}:\d{2})\s+(\w+)\s+(.+)')

        with open(log_file, 'r', encoding='utf-8') as f:
            for line in f:
                match = pattern.match(line.strip())
                if match:
                    timestamp, level, message = match.groups()
                    data.append({
                        'timestamp': pd.to_datetime(timestamp),
                        'level': level,
                        'message': message
                    })
        return pd.DataFrame(data)

    def analyze_logs(self) -> Dict:
        all_logs = pd.DataFrame()
        extracted_files = self.extract_logs()

        for log_file in extracted_files:
            try:
                df = self.parse_log_file(log_file)
                all_logs = pd.concat([all_logs, df])
            except Exception as e:
                logging.error(f"Error processing {log_file}: {str(e)}")

        analysis = {
            'total_entries': len(all_logs),
            'error_count': len(all_logs[all_logs['level'] == 'ERROR']),
            'warning_count': len(all_logs[all_logs['level'] == 'WARNING']),
            'time_range': (all_logs['timestamp'].min(), all_logs['timestamp'].max())
        }

        all_logs.to_csv(self.output_dir / 'processed_logs.csv', index=False)
        return analysis

    def cleanup(self):
        for file in self.output_dir.glob('*.log'):
            file.unlink()
