        self.target_keyword = target_keyword.lower()
        self.visited = set()
        self.queue = PriorityQueue()
        self.queue.put((0, start_url))

    def get_domain(self, url):
        return urlparse(url).netloc

    def calculate_priority(self, url, content):
        priority = 0
        if self.target_keyword in url.lower():
            priority -= 10
        if content:
            keyword_count = len(re.findall(self.target_keyword, content.lower()))
            priority -= keyword_count
        return priority

    def crawl(self, max_pages=20):
        while not self.queue.empty() and len(self.visited) < max_pages:
            priority, current_url = self.queue.get()

            if current_url in self.visited:
                continue

            try:
                response = requests.get(current_url, timeout=5, verify=True)
                self.visited.add(current_url)

                if response.status_code == 200:
                    soup = BeautifulSoup(response.text, 'html.parser')
                    page_content = soup.get_text()

                    for link in soup.find_all('a'):
                        href = link.get('href')
                        if href:
                            full_url = urljoin(current_url, href)
                            if (self.get_domain(full_url) == self.get_domain(self.start_url) 
                                and full_url not in self.visited):
                                new_priority = self.calculate_priority(full_url, link.get_text())
                                self.queue.put((new_priority, full_url))

                    yield current_url, page_content

            except (requests.RequestException, UnicodeDecodeError):
                continue

def main():
    crawler = PriorityCrawler('https://example.com', 'python')
    for url, content in crawler.crawl():
        print(f"Crawled: {url}")

if __name__ == '__main__':
    main()
