import os
import shutil
import stat
from pathlib import Path

def validate_path(path):
    resolved = Path(path).resolve()
    if not resolved.exists():
        raise ValueError("Path does not exist")
    if not resolved.is_dir():
        raise ValueError("Path is not a directory")
    return str(resolved)

def copy_file(src, dst):
    try:
        shutil.copy2(src, dst)
        dst_path = Path(dst)
        dst_path.chmod(stat.S_IRUSR | stat.S_IWUSR)
    except (shutil.Error, OSError) as e:
        raise IOError(f"Failed to copy {src} to {dst}")

def sync(src_dir, dst_dir):
    src_dir = validate_path(src_dir)
    dst_dir = validate_path(dst_dir)

    for root, dirs, files in os.walk(src_dir):
        rel_path = os.path.relpath(root, src_dir)
        dst_root = os.path.join(dst_dir, rel_path)

        os.makedirs(dst_root, exist_ok=True)

        for file in files:
            src_file = os.path.join(root, file) 
            dst_file = os.path.join(dst_root, file)

            try:
                if os.path.exists(dst_file):
                    if not os.access(dst_file, os.W_OK):
                        continue
                    os.remove(dst_file)
                copy_file(src_file, dst_file)
