import re
from dataclasses import dataclass
from typing import List, Dict, Callable
import socket
import threading
import queue

@dataclass
class Rule:
    pattern: str
    backend: str
    priority: int = 0

class LoadBalancer:
    def __init__(self, port: int):
        self.port = port
        self.rules: List[Rule] = []
        self.backends: Dict[str, queue.Queue] = {}
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)

    def add_rule(self, pattern: str, backend: str, priority: int = 0):
        rule = Rule(pattern, backend, priority)
        self.rules.append(rule)
        self.rules.sort(key=lambda x: x.priority, reverse=True)
        if backend not in self.backends:
            self.backends[backend] = queue.Queue()

    def route(self, request: str) -> str:
        for rule in self.rules:
            if re.search(rule.pattern, request):
                return rule.backend
        return None

    def handle_client(self, client_socket: socket.socket):
        try:
            request = client_socket.recv(4096).decode()
            backend = self.route(request)

            if backend:
                backend_queue = self.backends[backend]
                backend_queue.put((client_socket, request))
            else:
                client_socket.close()
        except:
            client_socket.close()

    def backend_worker(self, backend: str, handler: Callable):
        queue = self.backends[backend]
        while True:
            client_socket, request = queue.get()
            try:
                response = handler(request)
                client_socket.send(response.encode())
            finally:
                client_socket.close()

    def start(self):
        self.sock.bind(('', self.port))
        self.sock.listen(5)

        while True:
            client, _ = self.sock.accept()
            thread = threading.Thread(target=self.handle_client, args=(client,))
            thread.daemon = True
            thread.start()
