    with tarfile.open(filename, 'r:*') as tar:
        members = tar.getmembers()
        for member in members:
            member_path = os.path.abspath(os.path.join(abs_outdir, member.name))
            if not member_path.startswith(abs_outdir):
                continue
            if member.islnk() or member.issym():
                continue
            tar.extract(member, abs_outdir)

untar('data.tar', 'extracted_data')

