import os
import zipfile
import tarfile
import shutil
from pathlib import Path

def extract_zip(zip_path, extract_path):
    with zipfile.ZipFile(zip_path, 'r') as zip_ref:
        zip_ref.extractall(path=extract_path)

def extract_tar(tar_path, extract_path):
    with tarfile.open(tar_path, 'r:*') as tar_ref:
        tar_ref.extractall(path=extract_path)

def extract_7z(sz_path, extract_path):
    from py7zr import SevenZipFile
    with SevenZipFile(sz_path, 'r') as sz_ref:
        sz_ref.extractall(path=extract_path)

def extract_rar(rar_path, extract_path):
    from rarfile import RarFile
    with RarFile(rar_path, 'r') as rar_ref:
        rar_ref.extractall(path=extract_path)

def extract_archive(archive_path, extract_path=None):
    if extract_path is None:
        extract_path = os.path.dirname(archive_path)

    extract_path = Path(extract_path)
    archive_path = Path(archive_path)

    if not extract_path.exists():
        extract_path.mkdir(parents=True)

    if archive_path.suffix == '.zip':
        extract_zip(archive_path, extract_path)
    elif archive_path.suffix in ['.tar', '.gz', '.bz2', '.xz']:
        extract_tar(archive_path, extract_path)
    elif archive_path.suffix == '.7z':
        extract_7z(archive_path, extract_path)
    elif archive_path.suffix == '.rar':
        extract_rar(archive_path, extract_path)
    else:
        raise ValueError(f'Unsupported archive format: {archive_path.suffix}')

def cleanup(path):
    if os.path.exists(path):
        shutil.rmtree(path)
