import os
import subprocess
import shutil
import hashlib
import yaml
import logging
from pathlib import Path
from typing import Dict

logging.basicConfig(level=logging.INFO)

class BuildDeployer:
    def __init__(self, config_path: str):
        with open(config_path) as f:
            self.config = yaml.safe_load(f)
        self.build_dir = Path(self.config['build_dir'])
        self.deploy_dir = Path(self.config['deploy_dir'])
        self.source_dir = Path(self.config['source_dir'])

    def verify_checksum(self, file_path: str) -> bool:
        sha256 = hashlib.sha256()
        with open(file_path, 'rb') as f:
            for block in iter(lambda: f.read(4096), b''):
                sha256.update(block)
        return sha256.hexdigest() == self.config['expected_checksum']

    def compile_code(self) -> bool:
        try:
            subprocess.run(
                self.config['build_command'],
                cwd=self.source_dir,
                check=True,
                capture_output=True
            )
            return True
        except subprocess.CalledProcessError:
            logging.error("Build failed")
            return False

    def backup_existing(self):
        if self.deploy_dir.exists():
            backup_dir = self.deploy_dir.parent / f"{self.deploy_dir.name}_backup"
            shutil.copytree(self.deploy_dir, backup_dir, dirs_exist_ok=True)

    def deploy(self) -> bool:
        try:
            if not self.compile_code():
                return False

            self.backup_existing()

            if self.deploy_dir.exists():
                shutil.rmtree(self.deploy_dir)

            shutil.copytree(self.build_dir, self.deploy_dir)

            os.chmod(self.deploy_dir, 0o755)

            subprocess.run(
                self.config['post_deploy_command'],
                cwd=self.deploy_dir,
                check=True
            )

            return True

        except Exception as e:
            logging.error(f"Deployment failed: {str(e)}")
            return False

    def rollback(self):
        backup_dir = self.deploy_dir.parent / f"{self.deploy_dir.name}_backup"
        if backup_dir.exists():
            shutil.rmtree(self.deploy_dir)
            shutil.copytree(backup_dir, self.deploy_dir)

def main():
    deployer = BuildDeployer('config.yml')
    if not deployer.deploy():
        deployer.rollback()

if __name__ == "__main__":
    main()
