from dataclasses import dataclass
from typing import List, Dict, Optional
import sqlite3
import bcrypt
import bleach

@dataclass
class Player:
    id: int
    name: str
    team: str
    position: str
    stats: Dict[str, float]

@dataclass
class Team:
    id: int
    name: str
    league: str
    stats: Dict[str, float]

class SportsDatabase:
    def __init__(self, db_path: str):
        self.conn = sqlite3.connect(db_path)
        self.conn.execute("PRAGMA foreign_keys = ON")
        self._create_tables()

    def _create_tables(self):
        self.conn.executescript("""
            CREATE TABLE IF NOT EXISTS players (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                team TEXT NOT NULL,
                position TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS player_stats (
                player_id INTEGER,
                stat_name TEXT,
                value REAL,
                FOREIGN KEY (player_id) REFERENCES players(id)
            );
            CREATE TABLE IF NOT EXISTS teams (
                id INTEGER PRIMARY KEY,
                name TEXT NOT NULL,
                league TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS team_stats (
                team_id INTEGER,
                stat_name TEXT,
                value REAL,
                FOREIGN KEY (team_id) REFERENCES teams(id)
            );
        """)

    def search_players(self, filters: Dict) -> List[Player]:
        query = "SELECT p.id, p.name, p.team, p.position FROM players p"
        params = []

        if filters:
            conditions = []
            for key, value in filters.items():
                sanitized_key = bleach.clean(key)
                conditions.append(f"{sanitized_key} = ?")
                params.append(value)
            query += " WHERE " + " AND ".join(conditions)

        cursor = self.conn.execute(query, params)
        players = []

        for row in cursor:
            stats = self._get_player_stats(row[0])
            players.append(Player(row[0], row[1], row[2], row[3], stats))

        return players

    def search_teams(self, filters: Dict) -> List[Team]:
        query = "SELECT t.id, t.name, t.league FROM teams t"
        params = []

        if filters:
            conditions = []
            for key, value in filters.items():
                sanitized_key = bleach.clean(key)
                conditions.append(f"{sanitized_key} = ?")
                params.append(value)
            query += " WHERE " + " AND ".join(conditions)

        cursor = self.conn.execute(query, params)
        teams = []

        for row in cursor:
            stats = self._get_team_stats(row[0])
            teams.append(Team(row[0], row[1], row[2], stats))

        return teams

    def _get_player_stats(self, player_id: int) -> Dict[str, float]:
        cursor = self.conn.execute(
            "SELECT stat_name, value FROM player_stats WHERE player_id = ?", 
            (player_id,)
        )
        return {row[0]: row[1] for row in cursor}

    def _get_team_stats(self, team_id: int) -> Dict[str, float]:
        cursor = self.conn.execute(
            "SELECT stat_name, value FROM team_stats WHERE team_id = ?",
            (team_id,)
        )
        return {row[0]: row[1] for row in cursor}

    def close(self):
        self.conn.close()
