        src_path = Path(src_dir).resolve()
        dst_path = Path(dst_dir).resolve()

        if not src_path.exists() or not src_path.is_dir():
            raise ValueError("Source directory does not exist")

        dst_path.mkdir(parents=True, exist_ok=True)

        mode = int(str(permissions), 8)
        if mode > 0o777:
            raise ValueError("Invalid permissions")

        for src_file in src_path.iterdir():
            if src_file.is_file():
                dst_file = dst_path / src_file.name
                shutil.copy2(src_file, dst_file)
                os.chmod(dst_file, mode)

if __name__ == "__main__":
    if len(sys.argv) != 4:
        sys.exit("Usage: script.py src_dir dst_dir permissions(octal)")

    try:
        copy_files(sys.argv[1], sys.argv[2], sys.argv[3])
    except (ValueError, OSError) as e:
