import os
import re
import sys
import stat
from pathlib import Path

def validate_permissions(perm_str):
    try:
        mode = int(perm_str, 8)
        if mode < 0 or mode > 0o777:
            return False
        return True
    except ValueError:
        return False

def search_replace(pattern, replacement, files, permissions=None):
    regex = re.compile(pattern)

    if permissions and not validate_permissions(permissions):
        raise ValueError("Invalid permissions specified")

    for file in files:
        path = Path(file).resolve()
        if not path.is_file() or not os.access(path, os.R_OK | os.W_OK):
            continue

        try:
            with open(path, 'r', encoding='utf-8') as f:
                content = f.read()

            modified = regex.sub(replacement, content)

            if modified != content:
                with open(path, 'w', encoding='utf-8') as f:
                    f.write(modified)

                if permissions:
                    os.chmod(path, int(permissions, 8))

        except (IOError, OSError, UnicodeError):
            continue

def main():
    if len(sys.argv) < 4:
        sys.exit(1)

    pattern = sys.argv[1]
    replacement = sys.argv[2]
    files = sys.argv[3:]

    permissions = os.environ.get('NEW_PERMISSIONS')

    try:
        search_replace(pattern, replacement, files, permissions)
    except (ValueError, re.error):
        sys.exit(1)

if __name__ == '__main__':
    main()
