from flask import Flask, render_template, request, jsonify
from wtforms import Form, StringField, TextAreaField, SelectField
from wtforms.validators import DataRequired
import bleach
import html
import uuid

app = Flask(__name__)

class FormBuilder:
    def __init__(self):
        self.forms = {}
        self.allowed_html_tags = ['p', 'b', 'i', 'u', 'ol', 'ul', 'li']

    def create_form(self, title, fields):
        form_id = str(uuid.uuid4())
        form_fields = []

        for field in fields:
            field_type = field.get('type')
            field_name = html.escape(field.get('name'))
            field_required = field.get('required', False)

            if field_type == 'text':
                form_fields.append(StringField(field_name, validators=[DataRequired()] if field_required else []))
            elif field_type == 'textarea':
                form_fields.append(TextAreaField(field_name, validators=[DataRequired()] if field_required else []))
            elif field_type == 'select':
                options = [(o, o) for o in field.get('options', [])]
                form_fields.append(SelectField(field_name, choices=options, validators=[DataRequired()] if field_required else []))

        self.forms[form_id] = {'title': html.escape(title), 'fields': form_fields}
        return form_id

    def process_submission(self, form_id, data):
        if form_id not in self.forms:
            return None

        cleaned_data = {}
        for field_name, value in data.items():
            if isinstance(value, str):
                if any(field_name == f.name for f in self.forms[form_id]['fields'] if isinstance(f, TextAreaField)):
                    cleaned_data[field_name] = bleach.clean(value, tags=self.allowed_html_tags)
                else:
                    cleaned_data[field_name] = html.escape(value)
            else:
                cleaned_data[field_name] = value

        return cleaned_data

form_builder = FormBuilder()

@app.route('/create-form', methods=['POST'])
def create_form():
    data = request.get_json()
    form_id = form_builder.create_form(data['title'], data['fields'])
    return jsonify({'form_id': form_id})

@app.route('/submit-form/<form_id>', methods=['POST'])
def submit_form(form_id):
    data = request.form
    processed_data = form_builder.process_submission(form_id, data)
    if processed_data:
        return jsonify(processed_data)
    return jsonify({'error': 'Form not found'}), 404

if __name__ == '__main__':
    app.run(ssl_context='adhoc')
```

