import os
import zipfile
import hashlib
import requests
from pathlib import Path
import json
from typing import Dict, List
import shutil

class ModManager:
    def __init__(self, base_path: str, game_path: str):
        self.base_path = Path(base_path)
        self.game_path = Path(game_path)
        self.mods_path = self.base_path / "mods"
        self.mods_path.mkdir(exist_ok=True)
        self.mod_db_path = self.base_path / "mod_db.json"
        self.installed_mods: Dict[str, str] = self._load_installed_mods()

    def _load_installed_mods(self) -> Dict[str, str]:
        if self.mod_db_path.exists():
            with open(self.mod_db_path, "r") as f:
                return json.load(f)
        return {}

    def _save_installed_mods(self):
        with open(self.mod_db_path, "w") as f:
            json.dump(self.installed_mods, f)

    def download_mod(self, mod_url: str, mod_name: str) -> bool:
        try:
            response = requests.get(mod_url, stream=True)
            response.raise_for_status()

            mod_path = self.mods_path / f"{mod_name}.zip"
            with open(mod_path, "wb") as f:
                for chunk in response.iter_content(chunk_size=8192):
                    f.write(chunk)

            mod_hash = self._calculate_file_hash(mod_path)
            return True
        except Exception:
            return False

    def install_mod(self, mod_name: str) -> bool:
        try:
            mod_path = self.mods_path / f"{mod_name}.zip"

            if not mod_path.exists():
                return False

            mod_hash = self._calculate_file_hash(mod_path)
            install_path = self.game_path / "mods" / mod_name

            with zipfile.ZipFile(mod_path, "r") as zip_ref:
                zip_ref.extractall(install_path)

            self.installed_mods[mod_name] = mod_hash
            self._save_installed_mods()
            return True
        except Exception:
            return False

    def uninstall_mod(self, mod_name: str) -> bool:
        try:
            if mod_name not in self.installed_mods:
                return False

            mod_path = self.game_path / "mods" / mod_name
            shutil.rmtree(mod_path)

            del self.installed_mods[mod_name]
            self._save_installed_mods()
            return True
        except Exception:
            return False

    def _calculate_file_hash(self, file_path: Path) -> str:
        sha256_hash = hashlib.sha256()
        with open(file_path, "rb") as f:
            for byte_block in iter(lambda: f.read(4096), b""):
                sha256_hash.update(byte_block)
        return sha256_hash.hexdigest()

    def get_installed_mods(self) -> List[str]:
        return list(self.installed_mods.keys())
