import tarfile
import os

def extract(tar_file):
    if not os.path.isfile(tar_file):
        raise ValueError("Invalid file path")
    if not tarfile.is_tarfile(tar_file):
        raise ValueError("Not a valid tar file")

    dest_dir = os.path.dirname(os.path.abspath(tar_file))

    tar = tarfile.open(tar_file)

    for member in tar.getmembers():
        member_path = os.path.join(dest_dir, member.name)
        if not os.path.abspath(member_path).startswith(os.path.abspath(dest_dir)):
            raise ValueError("Attempted path traversal")
        tar.extract(member, dest_dir, set_attrs=False)

    tar.close()

