def get_file_hash(filepath):
    sha256 = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            sha256.update(chunk)
    return sha256.hexdigest()

def secure_copy(src, dst):
    os.umask(0o077)
    shutil.copy2(src, dst)
    dst.chmod(stat.S_IRUSR | stat.S_IWUSR)

def sync():
    if not source.exists() or not destination.exists():
        raise ValueError("Source or destination directory does not exist")

    if not source.is_relative_to(Path.home()):
        raise ValueError("Source must be within user's home directory")

    for src_path in source.rglob('*'):
        if src_path.is_file():
            rel_path = src_path.relative_to(source)
            dst_path = destination / rel_path

            dst_path.parent.mkdir(parents=True, exist_ok=True)

            try:
                if not dst_path.exists() or get_file_hash(src_path) != get_file_hash(dst_path):
                    secure_copy(src_path, dst_path)
            except (PermissionError, OSError):
                continue

