            self.vehicles[vehicle_id] = Vehicle(vehicle_id, name)
            cursor = self.db.cursor()
            cursor.execute('INSERT INTO vehicles (id, name) VALUES (?, ?)', 
                         (vehicle_id, name))
            self.db.commit()
            return True
        return False

