            cursor = self.db.cursor()
            cursor.execute('''INSERT INTO locations 
                            (vehicle_id, latitude, longitude, timestamp)
                            VALUES (?, ?, ?, ?)''',
                         (vehicle_id, latitude, longitude, timestamp))
            self.db.commit()
            return True
        return False

