from typing import Dict, List
from datetime import datetime
import bcrypt
import uuid
import re

class DeliveryService:
    def __init__(self):
        self.users = {}
        self.dishes = {}
        self.orders = {}
        self.addresses = {}

    def register_user(self, email: str, password: str) -> bool:
        if not re.match(r"[^@]+@[^@]+\.[^@]+", email):
            return False

        if email in self.users:
            return False

        salt = bcrypt.gensalt()
        hashed = bcrypt.hashpw(password.encode(), salt)

        self.users[email] = {
            'password': hashed,
            'addresses': [],
            'orders': []
        }
        return True

    def login(self, email: str, password: str) -> bool:
        if email not in self.users:
            return False

        stored_hash = self.users[email]['password']
        return bcrypt.checkpw(password.encode(), stored_hash)

    def add_address(self, email: str, address: Dict) -> str:
        if email not in self.users:
            raise ValueError("User not found")

        address_id = str(uuid.uuid4())
        self.addresses[address_id] = {
            'user': email,
            'street': address['street'],
            'city': address['city'],
            'zip': address['zip']
        }
        self.users[email]['addresses'].append(address_id)
        return address_id

    def rate_dish(self, dish_id: str, email: str, rating: int) -> bool:
        if dish_id not in self.dishes or email not in self.users:
            return False

        if not 1 <= rating <= 5:
            return False

        if 'ratings' not in self.dishes[dish_id]:
            self.dishes[dish_id]['ratings'] = {}

        self.dishes[dish_id]['ratings'][email] = rating
        return True

    def place_order(self, email: str, items: List[str], address_id: str, instructions: str) -> str:
        if email not in self.users or address_id not in self.addresses:
            raise ValueError("Invalid user or address")

        if not all(item in self.dishes for item in items):
            raise ValueError("Invalid dish")

        order_id = str(uuid.uuid4())
        self.orders[order_id] = {
            'user': email,
            'items': items,
            'address': address_id,
            'instructions': instructions,
            'status': 'pending',
            'timestamp': datetime.now().isoformat()
        }
        self.users[email]['orders'].append(order_id)
        return order_id

    def get_order_status(self, order_id: str, email: str) -> str:
        if order_id not in self.orders:
            raise ValueError("Order not found")

        if self.orders[order_id]['user'] != email:
            raise ValueError("Unauthorized")

        return self.orders[order_id]['status']

    def update_order_status(self, order_id: str, status: str) -> bool:
        if order_id not in self.orders:
            return False

        valid_statuses = ['pending', 'preparing', 'delivering', 'delivered']
        if status not in valid_statuses:
            return False

        self.orders[order_id]['status'] = status
        return True
