for root, dirs, files in os.walk(str(Path('/var/www/html').resolve())):
    for d in dirs[:]:
        try:
            if os.path.islink(os.path.join(root, d)):
                dirs.remove(d)
                continue
            sizes_by_dir[d].extend(os.path.getsize(os.path.join(root, f)) for f in files)
        except (PermissionError, OSError):
            continue

    for f in files:
