            filepath = os.path.join(root, f)
            if os.path.islink(filepath):
                continue
            size = os.path.getsize(filepath)
            all_sizes.append(size)
            if size > 100_000_000:  # Files over 100MB
                large_files.append((size, filepath))
        except (PermissionError, OSError):
            continue

print('Total usage:')
print(f'Total size: {sum(all_sizes)} bytes')
counts = Counter(all_sizes)
for size, count in counts.most_common():
    print(f'{count} files of size {size} bytes')

print('\nUsage by directory:')
for dir, sizes in sizes_by_dir.items():
    print(f'{dir}: {sum(sizes)} bytes over {len(sizes)} files')

print('\nLarge files (>100MB):')
