    destination = bleach.clean(request.args.get('destination', ''))
    departure = bleach.clean(request.args.get('departure', ''))
    return_date = bleach.clean(request.args.get('return', ''))
    num_passengers = bleach.clean(request.args.get('passengers', '1'))

