        if return_date:
            return_datetime = datetime.strptime(return_date, '%Y-%m-%d')
            if return_datetime < departure_date:
                return jsonify({'error': 'Invalid return date'}), 400
    except ValueError:
        return jsonify({'error': 'Invalid date format'}), 400

    try:
        passengers = int(num_passengers)
        if not 1 <= passengers <= 10:
            return jsonify({'error': 'Invalid passenger count'}), 400
    except ValueError:
        return jsonify({'error': 'Invalid passenger count'}), 400

