import subprocess
import os
import shutil
import logging
import yaml
from pathlib import Path

class Build:
    def __init__(self, config_path):
        self.config = self._load_config(config_path)
        self.build_dir = Path('builds').absolute()
        self.deps_dir = Path('dependencies').absolute()
        self._setup_logging()

    def _load_config(self, path):
        with open(path) as f:
            return yaml.safe_load(f)

    def _setup_logging(self):
        logging.basicConfig(
            level=logging.INFO,
            format='%(asctime)s - %(levelname)s - %(message)s',
            handlers=[logging.FileHandler('build.log'), logging.StreamHandler()]
        )

    def _clean(self):
        if self.build_dir.exists():
            shutil.rmtree(self.build_dir)
        self.build_dir.mkdir()
        if self.deps_dir.exists():
            shutil.rmtree(self.deps_dir)
        self.deps_dir.mkdir()

    def _fetch_dependencies(self):
        for dep in self.config['dependencies']:
            proc = subprocess.run(
                ['git', 'clone', dep['url'], str(self.deps_dir / dep['name'])],
                capture_output=True, text=True, check=True
            )
            logging.info(f"Fetched {dep['name']}")

    def _build(self):
        env = os.environ.copy()
        env.update(self.config.get('env', {}))

        for cmd in self.config['build_steps']:
            proc = subprocess.run(
                cmd, shell=True, cwd=self.build_dir,
                env=env, capture_output=True, text=True, check=True
            )
            logging.info(f"Build step completed: {cmd}")

    def run(self):
        try:
            self._clean()
            self._fetch_dependencies()
            self._build()
            logging.info("Build completed successfully")
            return True
        except subprocess.CalledProcessError as e:
