import os
import zipfile
import pathlib
from typing import List

class BackupUtility:
    def __init__(self, archive_path: str):
        self.archive_path = pathlib.Path(archive_path).resolve()

    def create_backup(self, source_paths: List[str]) -> None:
        with zipfile.ZipFile(self.archive_path, 'w', zipfile.ZIP_DEFLATED) as archive:
            for source in source_paths:
                path = pathlib.Path(source).resolve()
                if not path.exists():
                    raise FileNotFoundError(f"Path does not exist: {path}")
                if path.is_file():
                    archive.write(path, path.name)
                elif path.is_dir():
                    for file in path.rglob('*'):
                        if file.is_file():
                            archive.write(file, file.relative_to(path))

    def extract_files(self, destination: str) -> None:
        dest_path = pathlib.Path(destination).resolve()
        if not dest_path.exists():
            dest_path.mkdir(parents=True)
        with zipfile.ZipFile(self.archive_path, 'r') as archive:
            for file in archive.namelist():
                target = (dest_path / file).resolve()
                if not target.parent.exists():
                    target.parent.mkdir(parents=True)
                if str(target).startswith(str(dest_path)):
                    archive.extract(file, dest_path)

def main():
    backup = BackupUtility("backup.zip")
    backup.create_backup(["./test_folder"])
    backup.extract_files("./extracted")

if __name__ == "__main__":
    main()
