        if not content or len(content) > 280:
            return False

        if media_urls:
            allowed_types = ['.jpg', '.jpeg', '.png', '.gif']
            for url in media_urls:
                parsed = urlparse(url)
                if not any(parsed.path.lower().endswith(ext) for ext in allowed_types):
                    return False

        return True

