            for url in media_urls:
                media = self.twitter_api.media_upload(url)
                media_ids.append(media.media_id)

        tweet = self.twitter_api.update_status(
            status=content,
            media_ids=media_ids if media_ids else None
        )
        return {'platform': 'twitter', 'id': tweet.id, 'timestamp': datetime.now().isoformat()}

    def post_facebook(self, content: str, media_urls: List[str] = None) -> Dict:
        post_data = {'message': content}

        if media_urls:
            post_data['source'] = requests.get(media_urls[0]).content

        post = self.fb_api.put_object(
            parent_object='me',
            connection_name='feed',
            **post_data
        )
        return {'platform': 'facebook', 'id': post['id'], 'timestamp': datetime.now().isoformat()}

    def post_all(self, content: str, media_urls: List[str] = None) -> List[Dict]:
        if not self.validate_content(content, media_urls):
            raise ValueError("Invalid content or media")

        sanitized_content = self.sanitize_content(content)
        results = []

        try:
            twitter_result = self.post_twitter(sanitized_content, media_urls)
            results.append(twitter_result)
        except Exception as e:
            results.append({'platform': 'twitter', 'error': str(e)})

        try:
            facebook_result = self.post_facebook(sanitized_content, media_urls)
            results.append(facebook_result)
        except Exception as e:
            results.append({'platform': 'facebook', 'error': str(e)})

