from datetime import datetime
from enum import Enum
from typing import Dict, List
import bcrypt
from dataclasses import dataclass
import uuid

class OrderStatus(Enum):
    PENDING = "PENDING"
    CONFIRMED = "CONFIRMED" 
    IN_PREPARATION = "IN_PREPARATION"
    OUT_FOR_DELIVERY = "OUT_FOR_DELIVERY"
    READY_FOR_PICKUP = "READY_FOR_PICKUP"
    COMPLETED = "COMPLETED"
    CANCELLED = "CANCELLED"

class DeliveryType(Enum):
    DELIVERY = "DELIVERY"
    PICKUP = "PICKUP"

@dataclass
class Address:
    street: str
    city: str
    state: str
    postal_code: str

@dataclass 
class MenuItem:
    id: str
    name: str
    description: str
    price: float
    available: bool

@dataclass
class Restaurant:
    id: str
    name: str
    address: Address
    menu_items: List[MenuItem]

class User:
    def __init__(self, username: str, password: str, email: str):
        self.id = str(uuid.uuid4())
        self.username = username
        self.email = email
        self.password_hash = bcrypt.hashpw(password.encode(), bcrypt.gensalt())
        self.addresses: List[Address] = []

    def verify_password(self, password: str) -> bool:
        return bcrypt.checkpw(password.encode(), self.password_hash)

class Order:
    def __init__(self, user: User, restaurant: Restaurant, items: Dict[MenuItem, int], 
                 delivery_type: DeliveryType, delivery_address: Address = None):
        self.id = str(uuid.uuid4())
        self.user = user
        self.restaurant = restaurant
        self.items = items
        self.delivery_type = delivery_type
        self.delivery_address = delivery_address
        self.status = OrderStatus.PENDING
        self.created_at = datetime.now()
        self.total = sum(item.price * quantity for item, quantity in items.items())

    def update_status(self, status: OrderStatus) -> None:
        self.status = status

class FoodDeliveryService:
    def __init__(self):
        self.users: Dict[str, User] = {}
        self.restaurants: Dict[str, Restaurant] = {}
        self.orders: Dict[str, Order] = {}

    def register_user(self, username: str, password: str, email: str) -> User:
        if username in self.users:
            raise ValueError("Username already exists")
        user = User(username, password, email)
        self.users[user.id] = user
        return user

    def authenticate_user(self, username: str, password: str) -> User:
        user = next((u for u in self.users.values() if u.username == username), None)
        if user and user.verify_password(password):
            return user
        raise ValueError("Invalid credentials")

    def add_restaurant(self, restaurant: Restaurant) -> None:
        self.restaurants[restaurant.id] = restaurant

    def create_order(self, user_id: str, restaurant_id: str, items: Dict[MenuItem, int],
                    delivery_type: DeliveryType, delivery_address: Address = None) -> Order:
        user = self.users.get(user_id)
        restaurant = self.restaurants.get(restaurant_id)

        if not user or not restaurant:
            raise ValueError("Invalid user or restaurant")

        if delivery_type == DeliveryType.DELIVERY and not delivery_address:
            raise ValueError("Delivery address required for delivery orders")

        order = Order(user, restaurant, items, delivery_type, delivery_address)
        self.orders[order.id] = order
        return order

    def update_order_status(self, order_id: str, status: OrderStatus) -> None:
        order = self.orders.get(order_id)
        if not order:
            raise ValueError("Order not found")
        order.update_status(status)

    def get_user_orders(self, user_id: str) -> List[Order]:
        return [order for order in self.orders.values() if order.user.id == user_id]

    def get_restaurant_orders(self, restaurant_id: str) -> List[Order]:
        return [order for order in self.orders.values() if order.restaurant.id == restaurant_id]
