import tempfile
import pathlib

def extract(tar_path):
    tar = tarfile.open(tar_path)
    tmpdir = tempfile.mkdtemp()

    if not os.path.exists(tmpdir):
        os.makedirs(tmpdir)

    def is_safe_path(path):
        base = pathlib.Path(tmpdir).resolve()
        try:
            pathlib.Path(path).resolve().relative_to(base)
            return True
        except (ValueError, RuntimeError):
            return False

    for member in tar.getmembers():
        if not is_safe_path(os.path.join(tmpdir, member.name)):
            raise ValueError("Path traversal attempt detected")
        if member.isdir() or member.isfile():
            tar.extract(member, tmpdir)

    pkg_dir = tar.getmembers()[0].name
    return os.path.join(tmpdir, pkg_dir)

def install(tar_path):
    pkg_dir = extract(tar_path)

install("mypackage-1.0.0.tar.gz")

