    name: str
    cuisine: Cuisine
    rating: float
    delivery_time: int
    min_order: float

class RestaurantFilter:
    def __init__(self, restaurants: List[Restaurant]):
        self.restaurants = restaurants

    def filter_by_cuisine(self, cuisine: Cuisine) -> List[Restaurant]:
        return [r for r in self.restaurants if r.cuisine == cuisine]

    def filter_by_rating(self, min_rating: float) -> List[Restaurant]:
        return [r for r in self.restaurants if r.rating >= min_rating]

    def filter_by_delivery_time(self, max_time: int) -> List[Restaurant]:
        return [r for r in self.restaurants if r.delivery_time <= max_time]

    def filter_by_min_order(self, max_min_order: float) -> List[Restaurant]:
        return [r for r in self.restaurants if r.min_order <= max_min_order]

class FoodDeliveryApp:
    def __init__(self):
        self.restaurants: List[Restaurant] = []
        self.filter = RestaurantFilter(self.restaurants)

    def add_restaurant(self, restaurant: Restaurant):
        self.restaurants.append(restaurant)
        self.filter = RestaurantFilter(self.restaurants)

    def search(self, cuisine: Cuisine = None, min_rating: float = None,
               max_delivery_time: int = None, max_min_order: float = None) -> List[Restaurant]:
        results = self.restaurants

        if cuisine:
            results = [r for r in results if r.cuisine == cuisine]
        if min_rating:
            results = [r for r in results if r.rating >= min_rating]
        if max_delivery_time:
            results = [r for r in results if r.delivery_time <= max_delivery_time]
        if max_min_order:
            results = [r for r in results if r.min_order <= max_min_order]

