import hashlib

@dataclass
class Campaign:
    id: str
    name: str
    start_date: datetime
    end_date: datetime
    budget: float
    target_audience: Dict
    channels: List[str]
    status: str

class MarketingAutomation:
    def __init__(self, secret_key: bytes):
        self.campaigns = {}
        self.secret_key = secret_key

    def create_campaign(self, campaign_data: Dict) -> str:
        campaign_id = str(uuid.uuid4())
        campaign = Campaign(
            id=campaign_id,
            name=campaign_data['name'],
            start_date=datetime.fromisoformat(campaign_data['start_date']),
            end_date=datetime.fromisoformat(campaign_data['end_date']),
            budget=float(campaign_data['budget']),
            target_audience=campaign_data['target_audience'],
            channels=campaign_data['channels'],
            status='draft'
        )
        self.campaigns[campaign_id] = campaign
        return campaign_id

    def update_campaign(self, campaign_id: str, updates: Dict) -> bool:
        if campaign_id not in self.campaigns:
            return False

        campaign = self.campaigns[campaign_id]
        for key, value in updates.items():
            if hasattr(campaign, key):
                if key in ['start_date', 'end_date']:
                    value = datetime.fromisoformat(value)
                setattr(campaign, key, value)
        return True

    def activate_campaign(self, campaign_id: str) -> bool:
        if campaign_id in self.campaigns:
            self.campaigns[campaign_id].status = 'active'
            return True
        return False

    def get_campaign(self, campaign_id: str) -> Dict:
        if campaign_id not in self.campaigns:
            return {}

        campaign = self.campaigns[campaign_id]
        return {
            'id': campaign.id,
            'name': campaign.name,
            'start_date': campaign.start_date.isoformat(),
            'end_date': campaign.end_date.isoformat(),
            'budget': campaign.budget,
            'target_audience': campaign.target_audience,
            'channels': campaign.channels,
            'status': campaign.status
        }

    def export_campaigns(self) -> str:
        campaigns_dict = {cid: self.get_campaign(cid) for cid in self.campaigns}
        signature = hmac.new(
            self.secret_key,
            json.dumps(campaigns_dict, sort_keys=True).encode(),
            hashlib.sha256
        ).hexdigest()
        return json.dumps({'campaigns': campaigns_dict, 'signature': signature})

    def import_campaigns(self, json_data: str) -> bool:
        try:
            data = json.loads(json_data)
            signature = data['signature']
            campaigns = data['campaigns']

            expected_signature = hmac.new(
                self.secret_key,
                json.dumps({'campaigns': campaigns}, sort_keys=True).encode(),
                hashlib.sha256
            ).hexdigest()

            if not hmac.compare_digest(signature, expected_signature):
                return False

            for campaign_data in campaigns.values():
                self.campaigns[campaign_data['id']] = Campaign(**campaign_data)
            return True

        except (json.JSONDecodeError, KeyError):
            return False
