from pathlib import Path
from datetime import datetime

class DiffBackup:
    def __init__(self, backup_dir):
        self.backup_dir = Path(backup_dir)
        self.backup_dir.mkdir(parents=True, exist_ok=True)
        self.manifest_path = self.backup_dir / "manifest.json"
        self.manifest = self._load_manifest()

    def _load_manifest(self):
        if self.manifest_path.exists():
            with open(self.manifest_path, "r") as f:
                return json.load(f)
        return {"files": {}}

    def _save_manifest(self):
        with open(self.manifest_path, "w") as f:
            json.dump(self.manifest, f)

    def _get_file_hash(self, filepath):
        sha256 = hashlib.sha256()
        with open(filepath, "rb") as f:
            for chunk in iter(lambda: f.read(4096), b""):
                sha256.update(chunk)
        return sha256.hexdigest()

    def _create_tarball(self, files_to_backup):
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        backup_name = f"backup_{timestamp}.tar.gz"
        backup_path = self.backup_dir / backup_name

        with tarfile.open(backup_path, "w:gz") as tar:
            for file_path in files_to_backup:
                tar.add(file_path, arcname=os.path.basename(file_path))

        return backup_name

    def backup(self, source_dir):
        source_path = Path(source_dir)
        files_to_backup = []

        for file_path in source_path.rglob("*"):
            if not file_path.is_file():
                continue

            rel_path = str(file_path.relative_to(source_path))
            current_hash = self._get_file_hash(file_path)

            if rel_path not in self.manifest["files"] or self.manifest["files"][rel_path] != current_hash:
                files_to_backup.append(str(file_path))
                self.manifest["files"][rel_path] = current_hash

        if files_to_backup:
            backup_name = self._create_tarball(files_to_backup)
            self._save_manifest()
            return backup_name
        return None

    def restore(self, backup_file, target_dir):
        target_path = Path(target_dir)
        target_path.mkdir(parents=True, exist_ok=True)

        with tempfile.TemporaryDirectory() as temp_dir:
            with tarfile.open(self.backup_dir / backup_file, "r:gz") as tar:
                tar.extractall(path=temp_dir)

            for item in Path(temp_dir).iterdir():
                dest = target_path / item.name
                if dest.exists():
                    dest.unlink()
                item.rename(dest)
