def parse_data(data: str, format_type: str) -> Union[Dict, List]:
    if format_type.lower() == 'json':
        return json.loads(data)
    elif format_type.lower() == 'xml':
        root = ET.fromstring(data)
        def xml_to_dict(element):
            result = {}
            for child in element:
                if len(child):
                    result[child.tag] = xml_to_dict(child)
                else:
                    result[child.tag] = child.text
            return result
        return xml_to_dict(root)
    else:
        raise ValueError("Unsupported format type. Use 'json' or 'xml'")

def serialize_data(data: Union[Dict, List], format_type: str) -> str:
    if format_type.lower() == 'json':
        return json.dumps(data, ensure_ascii=False)
    elif format_type.lower() == 'xml':
        def dict_to_xml(data: Dict) -> ET.Element:
            root = ET.Element('root')
            def _to_xml(data, parent):
                if isinstance(data, dict):
                    for key, value in data.items():
                        child = ET.SubElement(parent, str(key))
                        _to_xml(value, child)
                else:
                    parent.text = str(data)
            _to_xml(data, root)
