import os
import sqlite3
import hashlib

DB_FILE = 'files.db'

def init_db(db_file):
    with sqlite3.connect(db_file) as conn:
        conn.execute('CREATE TABLE files (path TEXT PRIMARY KEY, size INT)')

def get_file_hash(filepath):
    sha256_hash = hashlib.sha256()
    with open(filepath, "rb") as f:
        for byte_block in iter(lambda: f.read(4096), b""):
            sha256_hash.update(byte_block)
    return sha256_hash.hexdigest()

def find_duplicate_files(path):
    duplicates = {}
    real_duplicates = {}

    if not os.path.exists(DB_FILE):
        init_db(DB_FILE)

    for root, dirs, files in os.walk(path):
        for f in files:
            filepath = os.path.join(root, f)
            try:
                file_size = os.path.getsize(filepath)
                if file_size in duplicates:
                    duplicates[file_size].append(filepath)
                else:
                    duplicates[file_size] = [filepath]
            except (OSError, IOError):
                continue

    for size, filepaths in duplicates.items():
        if len(filepaths) > 1:
            file_hashes = {}
            for filepath in filepaths:
                try:
                    file_hash = get_file_hash(filepath)
                    if file_hash in file_hashes:
                        file_hashes[file_hash].append(filepath)
                    else:
                        file_hashes[file_hash] = [filepath]
                except (OSError, IOError):
                    continue

            for hash_val, paths in file_hashes.items():
                if len(paths) > 1:
                    real_duplicates[hash_val] = paths

    return real_duplicates

if __name__ == '__main__':
    duplicates = find_duplicate_files('/home/user/')
    print(duplicates)

