import os
import tarfile
import shutil
import pathlib

class BackupUtility:
    def __init__(self, source_path, backup_path):
        self.source = pathlib.Path(source_path).resolve()
        self.backup = pathlib.Path(backup_path).resolve()

    def create_backup(self):
        if not self.source.exists():
            raise FileNotFoundError(f"Source path does not exist: {self.source}")

        archive_name = f"backup_{self.source.name}.tar.gz"
        archive_path = self.backup / archive_name

        with tarfile.open(archive_path, "w:gz") as tar:
            tar.add(self.source, arcname=self.source.name)

        return archive_path

    def extract_backup(self, archive_path, extract_path):
        archive = pathlib.Path(archive_path).resolve()
        target = pathlib.Path(extract_path).resolve()

        if not archive.exists():
            raise FileNotFoundError(f"Archive not found: {archive}")

        if not archive.is_file():
            raise ValueError("Archive path must be a file")

        if not str(archive).endswith(('.tar.gz', '.tgz')):
            raise ValueError("Invalid archive format")

        if not target.parent.exists():
            raise FileNotFoundError(f"Target directory does not exist: {target.parent}")

        with tarfile.open(archive, "r:gz") as tar:
            def is_within_directory(directory, target):
                abs_directory = os.path.abspath(directory)
                abs_target = os.path.abspath(target)
                prefix = os.path.commonprefix([abs_directory, abs_target])
                return prefix == abs_directory

            def safe_extract(tar, path):
                for member in tar.getmembers():
                    member_path = os.path.join(path, member.name)
                    if not is_within_directory(path, member_path):
                        raise Exception("Attempted path traversal in tar file")
                tar.extractall(path)

            safe_extract(tar, str(target))

if __name__ == "__main__":
    backup = BackupUtility("/path/to/source", "/path/to/backup")
    archive = backup.create_backup()
    backup.extract_backup(archive, "/path/to/extract")
