import os
import json
import tarfile
from pathlib import Path

def save_metadata(path):
    if not os.path.exists(path) or not os.path.isfile(path):
        raise ValueError("Invalid file path")

    metadata = {}
    stat = os.stat(path)
    metadata['mode'] = oct(stat.st_mode)
    metadata['owner'] = stat.st_uid 
    metadata['group'] = stat.st_gid

    metadata_path = Path(str(path) + '.metadata')
    with open(metadata_path, 'w') as f:
        json.dump(metadata, f)

def backup(path):
    if not os.path.exists(path):
        raise ValueError("Backup path does not exist")

    backup_dir = Path('/backups')
    if not backup_dir.exists():
        backup_dir.mkdir(mode=0o700)

    backup_file = backup_dir / 'backup.tar'
    with tarfile.open(backup_file, 'w') as tar:
        for root, dirs, files in os.walk(path):
            if root.startswith(('/dev', '/proc', '/sys', '/tmp', '/run', '/mnt', '/media', '/lost+found')):
                continue
            for file in files:
                file_path = os.path.join(root, file)
                if os.path.exists(file_path) and os.path.isfile(file_path):
                    tar.add(file_path)
                    save_metadata(file_path)

if __name__ == '__main__':
    backup('/home/')
