from datetime import datetime, timedelta
from typing import List, Dict

class Flight:
    def __init__(self, flight_number: str, origin: str, destination: str, 
                 departure: datetime, arrival: datetime, price: float, seats: int):
        self.flight_number = flight_number
        self.origin = origin
        self.destination = destination
        self.departure = departure
        self.arrival = arrival
        self.price = price
        self.available_seats = seats

class BookingSystem:
    def __init__(self):
        self.flights: List[Flight] = []
        self.bookings: Dict[str, List[Flight]] = {}

    def add_flight(self, flight: Flight) -> None:
        self.flights.append(flight)

    def search_flights(self, origin: str, destination: str, 
                      date: datetime) -> List[Flight]:
        return [f for f in self.flights 
                if f.origin == origin and
                f.destination == destination and
                f.departure.date() == date.date() and
                f.available_seats > 0]

    def book_flight(self, user_id: str, flight: Flight) -> bool:
        if flight.available_seats > 0:
            if user_id not in self.bookings:
                self.bookings[user_id] = []
            self.bookings[user_id].append(flight)
            flight.available_seats -= 1
            return True
        return False

    def get_user_bookings(self, user_id: str) -> List[Flight]:
        return self.bookings.get(user_id, [])

    def cancel_booking(self, user_id: str, flight: Flight) -> bool:
        if user_id in self.bookings and flight in self.bookings[user_id]:
            self.bookings[user_id].remove(flight)
            flight.available_seats += 1
            return True
        return False

def calculate_duration(flight: Flight) -> timedelta:
    return flight.arrival - flight.departure
