            links = set()
            for link in soup.find_all('a'):
                href = link.get('href')
                if href:
                    absolute_url = urljoin(base_url, href)
                    if urlparse(absolute_url).netloc == urlparse(base_url).netloc:
                        links.add(absolute_url)
            return links
        except:
            return set()

    def build_graph(self, start_url, max_depth=2, current_depth=0):
        if current_depth >= max_depth or start_url in self.visited:
            return
        self.visited.add(start_url)
        links = self.get_links(start_url)
        for link in links:
            self.graph.add_edge(start_url, link)
