import logging
import os
from logging.handlers import RotatingFileHandler
from datetime import datetime
import hashlib
import hmac
import json

class LogAggregator:
    def __init__(self, log_dir="/var/log/aggregator"):
        self.log_dir = log_dir
        if not os.path.exists(log_dir):
            os.makedirs(log_dir)

        self.logger = self._setup_logger()
        self.hmac_key = os.urandom(32)

    def _setup_logger(self):
        logger = logging.getLogger('aggregator')
        logger.setLevel(logging.INFO)

        formatter = logging.Formatter('%(asctime)s - %(name)s - %(levelname)s - %(message)s')

        file_handler = RotatingFileHandler(
            os.path.join(self.log_dir, 'aggregator.log'),
            maxBytes=10485760,
            backupCount=5
        )
        file_handler.setFormatter(formatter)
        logger.addHandler(file_handler)

        return logger

    def _generate_hmac(self, message):
        h = hmac.new(self.hmac_key, message.encode(), hashlib.sha256)
        return h.hexdigest()

    def collect_log(self, source, log_data):
        timestamp = datetime.utcnow().isoformat()

        log_entry = {
            'timestamp': timestamp,
            'source': source,
            'data': log_data
        }

        log_json = json.dumps(log_entry)
        hmac_sig = self._generate_hmac(log_json)

        self.logger.info(f"{hmac_sig}:{log_json}")

    def analyze_logs(self, time_window=3600):
        log_data = []
        current_time = datetime.utcnow()

        with open(os.path.join(self.log_dir, 'aggregator.log'), 'r') as f:
            for line in f:
                try:
                    hmac_sig, log_json = line.strip().split(':', 1)
                    if self._generate_hmac(log_json) != hmac_sig:
                        continue

                    entry = json.loads(log_json)
                    log_time = datetime.fromisoformat(entry['timestamp'])

                    if (current_time - log_time).total_seconds() <= time_window:
                        log_data.append(entry)
                except:
                    continue

        return log_data

    def get_stats(self, logs):
        stats = {}
        for log in logs:
            source = log['source']
            if source not in stats:
                stats[source] = 0
            stats[source] += 1
        return stats

    def search_logs(self, keyword, logs):
        matching_logs = []
        for log in logs:
            if keyword.lower() in str(log).lower():
                matching_logs.append(log)
        return matching_logs
