import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse
import concurrent.futures

class DeadLinkCrawler:
    def __init__(self, start_url, max_workers=10):
        self.start_url = start_url
        self.base_domain = urlparse(start_url).netloc
        self.visited_urls = set()
        self.dead_links = []
        self.max_workers = max_workers

    def is_valid_url(self, url):
        try:
            result = urlparse(url)
            return all([result.scheme, result.netloc])
        except:
            return False

    def is_same_domain(self, url):
        return urlparse(url).netloc == self.base_domain

    def check_url(self, url):
        try:
            response = requests.head(url, allow_redirects=True, timeout=5)
            if response.status_code >= 400:
                self.dead_links.append((url, response.status_code))
        except:
            self.dead_links.append((url, "Connection Error"))

    def get_links(self, url):
        try:
            response = requests.get(url, timeout=5)
            soup = BeautifulSoup(response.text, 'html.parser')
            links = [urljoin(url, link.get('href')) for link in soup.find_all('a')]
            return [link for link in links if self.is_valid_url(link)]
        except:
            return []

    def crawl(self):
        urls_to_visit = [self.start_url]

        with concurrent.futures.ThreadPoolExecutor(max_workers=self.max_workers) as executor:
            while urls_to_visit:
                current_url = urls_to_visit.pop(0)
                if current_url not in self.visited_urls:
                    self.visited_urls.add(current_url)
                    executor.submit(self.check_url, current_url)

                    if self.is_same_domain(current_url):
                        new_links = self.get_links(current_url)
                        urls_to_visit.extend([url for url in new_links if url not in self.visited_urls])

        return self.dead_links

if __name__ == "__main__":
    crawler = DeadLinkCrawler("https://example.com")
    dead_links = crawler.crawl()
    for url, status in dead_links:
        print(f"Dead link found: {url} (Status: {status})")
