from pathlib import Path
import shutil

def extract_archive(archive_path, extract_path):
    archive_path = os.path.abspath(archive_path)
    extract_path = os.path.abspath(extract_path)

    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    temp_dir = tempfile.mkdtemp()
    try:
        if tarfile.is_tarfile(archive_path):
            with tarfile.open(archive_path) as tar:
                def is_safe(member):
                    target_path = os.path.abspath(os.path.join(temp_dir, member.name))
                    return target_path.startswith(temp_dir)
                members = filter(is_safe, tar.getmembers())
                tar.extractall(path=temp_dir, members=members)

        elif zipfile.is_zipfile(archive_path):
            with zipfile.ZipFile(archive_path) as zf:
                for member in zf.namelist():
                    target_path = os.path.abspath(os.path.join(temp_dir, member))
                    if target_path.startswith(temp_dir):
                        zf.extract(member, temp_dir)

        os.makedirs(extract_path, exist_ok=True)
        for item in os.listdir(temp_dir):
            src = os.path.join(temp_dir, item)
            dst = os.path.join(extract_path, item)
            if os.path.isdir(src):
                shutil.copytree(src, dst)
            else:
                shutil.copy2(src, dst)

    finally:
