@app.route('/login', methods=['POST'])
def login():
    username = request.form.get('username')
    password = request.form.get('password')

    if not username or not password:
        return make_response('Missing credentials', 400)

    if hmac.compare_digest(username, "admin") and hmac.compare_digest(password, "secure_password123"):
        response = make_response('Login successful')
        token = secrets.token_hex(32)
        signature = hmac.new(secret_key.encode(), token.encode(), hashlib.sha256).hexdigest()
        response.set_cookie('session', f'{token}:{signature}', httponly=True, secure=True, samesite='Strict')
        return response

    return make_response('Invalid credentials', 401)

@app.route('/protected', methods=['GET'])
def protected():
    session_cookie = request.cookies.get('session')

    if not session_cookie:
        return make_response('Unauthorized', 401)

    try:
        token, signature = session_cookie.split(':')
        expected_signature = hmac.new(secret_key.encode(), token.encode(), hashlib.sha256).hexdigest()

        if not hmac.compare_digest(signature, expected_signature):
            return make_response('Invalid session', 401)

