import os
import tarfile
import datetime
import hashlib
from pathlib import Path

def get_file_hash(filepath):
    sha256 = hashlib.sha256()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(4096), b''):
            sha256.update(chunk)
    return sha256.hexdigest()

def read_manifest(manifest_path):
    if not os.path.exists(manifest_path):
        return {}
    hashes = {}
    with open(manifest_path, 'r') as f:
        for line in f:
            filepath, filehash = line.strip().split('|')
            hashes[filepath] = filehash
    return hashes

def write_manifest(manifest_path, hashes):
    with open(manifest_path, 'w') as f:
        for filepath, filehash in hashes.items():
            f.write(f'{filepath}|{filehash}\n')

def differential_backup(source_dir, backup_dir):
    manifest_path = os.path.join(backup_dir, 'manifest.txt')
    old_hashes = read_manifest(manifest_path)
    new_hashes = {}
    files_to_backup = []

    source_path = Path(source_dir)
    for filepath in source_path.rglob('*'):
        if filepath.is_file():
            rel_path = str(filepath.relative_to(source_dir))
            file_hash = get_file_hash(filepath)
            new_hashes[rel_path] = file_hash

            if rel_path not in old_hashes or old_hashes[rel_path] != file_hash:
                files_to_backup.append(filepath)

    if files_to_backup:
        backup_name = f'backup_{datetime.datetime.now().strftime("%Y%m%d_%H%M%S")}.tar.gz'
        backup_path = os.path.join(backup_dir, backup_name)

        with tarfile.open(backup_path, 'w:gz') as tar:
            for filepath in files_to_backup:
                tar.add(filepath, arcname=str(filepath.relative_to(source_dir)))

    write_manifest(manifest_path, new_hashes)
    return len(files_to_backup)
