from datetime import datetime, timedelta

class Plant:
    def __init__(self, name, species, water_freq, light_req, humidity):
        self.name = name
        self.species = species
        self.water_frequency = water_freq
        self.light_requirement = light_req
        self.humidity = humidity
        self.last_watered = datetime.now()

    def water_plant(self):
        self.last_watered = datetime.now()
        return f"{self.name} has been watered"

    def needs_water(self):
        days_since = (datetime.now() - self.last_watered).days
        return days_since >= self.water_frequency

class PlantCareApp:
    def __init__(self):
        self.plants = {}

    def add_plant(self, name, species, water_freq, light_req, humidity):
        plant = Plant(name, species, water_freq, light_req, humidity)
        self.plants[name] = plant
        return f"{name} added successfully"

    def get_care_tips(self, name):
        if name not in self.plants:
            return "Plant not found"
        plant = self.plants[name]
        tips = f"Care tips for {plant.name}:\n"
        tips += f"Water every {plant.water_frequency} days\n"
        tips += f"Light requirement: {plant.light_requirement}\n"
        tips += f"Humidity: {plant.humidity}%"
        return tips

    def check_water_status(self, name):
        if name not in self.plants:
            return "Plant not found"
        plant = self.plants[name]
        if plant.needs_water():
            return f"{name} needs water!"
        next_water = plant.last_watered + timedelta(days=plant.water_frequency)
        return f"Next watering due: {next_water.strftime('%Y-%m-%d')}"

def main():
    app = PlantCareApp()
    app.add_plant("Snake Plant", "Sansevieria", 14, "Low to bright indirect", 40)
    app.add_plant("Monstera", "Monstera deliciosa", 7, "Bright indirect", 60)
    app.add_plant("Peace Lily", "Spathiphyllum", 5, "Low to medium", 50)

    for plant_name in app.plants:
        print(app.get_care_tips(plant_name))
        print(app.check_water_status(plant_name))
        print()

if __name__ == "__main__":
