        if suffix not in self.supported_archives:
            raise ValueError(f"Unsupported archive format: {suffix}")

        if not os.path.commonprefix([str(dest.resolve()), str(Path.cwd().resolve())]):
            raise ValueError("Destination path must be within current directory")

        if suffix in {'.zip'}:
            with zipfile.ZipFile(self.path, 'r') as zip_ref:
                zip_ref.extractall(dest)

        elif suffix in {'.tar', '.tar.gz', '.tgz', '.tar.bz2', '.tbz2'}:
            with tarfile.open(self.path, 'r:*') as tar_ref:
                tar_ref.extractall(dest)

    def extract_image_metadata(self):
        suffix = self.path.suffix.lower()
        if suffix not in self.supported_images:
            raise ValueError(f"Unsupported image format: {suffix}")

        with Image.open(self.path) as img:
            return {
                'format': img.format,
                'mode': img.mode,
                'size': img.size,
                'width': img.width,
                'height': img.height
            }

    def compress_file(self, dest_path, method='gzip'):
        if method not in {'gzip', 'bzip2'}:
            raise ValueError("Unsupported compression method")

        dest = Path(dest_path)
        if method == 'gzip':
            with open(self.path, 'rb') as f_in:
                with gzip.open(dest, 'wb') as f_out:
                    f_out.write(f_in.read())
        else:
            with open(self.path, 'rb') as f_in:
                with bz2.open(dest, 'wb') as f_out:
                    f_out.write(f_in.read())
