import requests
import os
import stat
from datetime import datetime
from typing import List, Dict
from pathlib import Path
import yaml
import validators
from urllib.parse import urlparse

def load_config() -> Dict:
    config_path = Path('config.yml')
    if not config_path.exists():
        raise FileNotFoundError("Config file not found")

    with open(config_path, 'r') as f:
        return yaml.safe_load(f)

def validate_url(url: str) -> bool:
    parsed = urlparse(url)
    return bool(parsed.scheme and parsed.netloc and validators.url(url))

def fetch_url(url: str) -> Dict:
    response = requests.get(url, timeout=30)
    response.raise_for_status()
    return {
        'status_code': response.status_code,
        'content': response.text,
        'timestamp': datetime.utcnow().isoformat()
    }

def save_response(data: Dict, output_dir: Path, permissions: int) -> None:
    timestamp = datetime.utcnow().strftime('%Y%m%d_%H%M%S')
    output_file = output_dir / f'response_{timestamp}.txt'

    output_dir.mkdir(parents=True, exist_ok=True)

    with open(output_file, 'w') as f:
        f.write(str(data))

    os.chmod(output_file, permissions)

def main():
    config = load_config()
    urls = config.get('urls', [])
    output_dir = Path(config.get('output_dir', 'responses'))
    permissions = config.get('permissions', 0o600)

    for url in urls:
        if not validate_url(url):
            continue

        try:
            response_data = fetch_url(url)
            save_response(response_data, output_dir, permissions)
        except (requests.RequestException, OSError):
            continue

if __name__ == '__main__':
    main()
