from http.server import HTTPServer, SimpleHTTPRequestHandler
import os
import sys
import pathlib
import urllib.parse

class SecureFileHandler(SimpleHTTPRequestHandler):
    def __init__(self, *args, directory=None, **kwargs):
        super().__init__(*args, directory=directory, **kwargs)

    def do_GET(self):
        try:
            path = urllib.parse.unquote(self.path)
            if path == '/':
                path = '/index.html'

            requested_path = pathlib.Path(self.directory + path)
            base_dir = pathlib.Path(self.directory).resolve()
            requested_path = requested_path.resolve()

            if not str(requested_path).startswith(str(base_dir)):
                self.send_error(403, "Access denied")
                return

            if not requested_path.exists():
                self.send_error(404, "File not found")
                return

            if not requested_path.is_file():
                self.send_error(403, "Access denied")
                return

            return super().do_GET()

        except Exception as e:
            self.send_error(500, str(e))

def run_server(directory, port=8000):
    if not os.path.exists(directory):
        raise ValueError("Directory does not exist")

    handler = lambda *args, **kwargs: SecureFileHandler(*args, directory=directory, **kwargs)
    server = HTTPServer(('', port), handler)
    server.serve_forever()

if __name__ == '__main__':
    if len(sys.argv) != 2:
        print("Usage: script.py <directory>")
        sys.exit(1)
    run_server(sys.argv[1])
