import os
import xml.etree.ElementTree as ET
from pathlib import Path

class ContactManager:
    def __init__(self):
        self.contacts = []

    def load_from_xml(self, xml_file):
        tree = ET.parse(xml_file)
        root = tree.getroot()
        for contact in root.findall('contact'):
            name = contact.find('name').text
            email = contact.find('email').text if contact.find('email') is not None else ''
            phone = contact.find('phone').text if contact.find('phone') is not None else ''
            if name:
                self.contacts.append(Contact(name, email, phone))

    def export_all(self, output_dir):
        output_path = Path(output_dir).resolve()
        if not output_path.exists():
            os.makedirs(output_path)
        for contact in self.contacts:
            contact.export(output_path)

class Contact:
    def __init__(self, name, email, phone):
        self.name = name
        self.email = email
        self.phone = phone

    def to_vcard(self):
        vcard = []
        vcard.append('BEGIN:VCARD')
        vcard.append('VERSION:3.0')
        vcard.append(f'FN:{self._escape_field(self.name)}')
        if self.email:
            vcard.append(f'EMAIL:{self._escape_field(self.email)}')
        if self.phone:
            vcard.append(f'TEL:{self._escape_field(self.phone)}')
        vcard.append('END:VCARD')
        return '\n'.join(vcard)

    def _escape_field(self, field):
        return field.replace(',', r'\,').replace(';', r'\;').replace('\n', r'\n')

    def export(self, output_dir):
        safe_filename = ''.join(c for c in self.name if c.isalnum() or c in ('_', '-', ' '))
        safe_filename = safe_filename.replace(' ', '_')[:255]
        filepath = Path(output_dir).joinpath(f'{safe_filename}.vcf')
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(self.to_vcard())

manager = ContactManager()
manager.load_from_xml('contacts.xml')
manager.export_all('/tmp')
