import os
import re
import argparse
import stat
from pathlib import Path

def sanitize_filename(filename):
    return re.sub(r'[<>:"/\\|?*]', '', filename)

def apply_permissions(filepath, perms):
    os.chmod(filepath, int(perms, 8))

def rename_files(path, pattern, replacement, permissions=None, recursive=False):
    path = os.path.abspath(path)
    if not os.path.exists(path):
        return

    def process_dir(dir_path):
        for entry in os.scandir(dir_path):
            if entry.is_file():
                old_path = entry.path
                filename = entry.name
                new_name = re.sub(pattern, replacement, filename)
                new_name = sanitize_filename(new_name)
                if new_name != filename:
                    new_path = os.path.join(dir_path, new_name)
                    if not os.path.exists(new_path):
                        os.rename(old_path, new_path)
                        if permissions:
                            apply_permissions(new_path, permissions)
            elif entry.is_dir() and recursive:
                process_dir(entry.path)

    process_dir(path)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("path", help="Directory path")
    parser.add_argument("pattern", help="Regex pattern to match")
    parser.add_argument("replacement", help="Replacement string")
    parser.add_argument("-p", "--permissions", help="Octal permissions")
    parser.add_argument("-r", "--recursive", action="store_true", help="Recursive")
    args = parser.parse_args()

    path = os.path.expanduser(args.path)
    rename_files(path, args.pattern, args.replacement, args.permissions, args.recursive)

if __name__ == "__main__":
