import math

class Recommender:
    def __init__(self):
        self.user_ratings = defaultdict(dict)
        self.item_means = defaultdict(float)
        self.user_means = defaultdict(float)

    def add_rating(self, user_id, item_id, rating):
        self.user_ratings[user_id][item_id] = float(rating)

    def calculate_similarity(self, user1, user2):
        common_items = set(self.user_ratings[user1].keys()) & set(self.user_ratings[user2].keys())
        if not common_items:
            return 0.0

        u1_mean = sum(self.user_ratings[user1].values()) / len(self.user_ratings[user1])
        u2_mean = sum(self.user_ratings[user2].values()) / len(self.user_ratings[user2])

        num = sum((self.user_ratings[user1][i] - u1_mean) * (self.user_ratings[user2][i] - u2_mean) for i in common_items)
        den1 = math.sqrt(sum((self.user_ratings[user1][i] - u1_mean) ** 2 for i in common_items))
        den2 = math.sqrt(sum((self.user_ratings[user2][i] - u2_mean) ** 2 for i in common_items))

        if den1 * den2 == 0:
            return 0.0
        return num / (den1 * den2)

    def predict_rating(self, user_id, item_id, k=5):
        if not self.user_ratings[user_id]:
            return 0.0

        similarities = []
        for other_user in self.user_ratings:
            if other_user != user_id and item_id in self.user_ratings[other_user]:
                sim = self.calculate_similarity(user_id, other_user)
                similarities.append((sim, other_user))

        similarities.sort(reverse=True)
        similarities = similarities[:k]

        if not similarities:
            return 0.0

        weighted_sum = sum(sim * self.user_ratings[other][item_id] for sim, other in similarities)
        sum_similarities = sum(abs(sim) for sim, _ in similarities)

        if sum_similarities == 0:
            return 0.0
        return weighted_sum / sum_similarities
