            completion_date = date.today()
        self.completed_dates.add(completion_date)

    def get_streak(self):
        if not self.completed_dates:
            return 0
        sorted_dates = sorted(self.completed_dates)
        streak = 1
        for i in range(1, len(sorted_dates)):
            if (sorted_dates[i] - sorted_dates[i-1]).days == 1:
                streak += 1
            else:
                break
        return streak

class HabitTracker:
    def __init__(self):
        self.habits = {}

    def add_habit(self, name, frequency="daily"):
        if name not in self.habits:
            self.habits[name] = Habit(name, frequency)
            return True
        return False

    def remove_habit(self, name):
        if name in self.habits:
            del self.habits[name]
            return True
        return False

    def complete_habit(self, name, completion_date=None):
