from pathlib import Path

class QueryLogger:
    def __init__(self, log_path="/var/log/slow_queries.log"):
        self.threshold_ms = 1000
        self.log_path = Path(log_path)
        logging.basicConfig(
            filename=str(self.log_path),
            level=logging.INFO,
            format='%(asctime)s - %(message)s'
        )

    def __call__(self, f):
        @wraps(f)
        def wrapped(*args, **kwargs):
            start = time.time()
            result = f(*args, **kwargs)
            duration = (time.time() - start) * 1000

            if duration > self.threshold_ms:
                query = str(args[0])
                logging.info(f"Duration: {duration:.2f}ms - Query: {query}")

            return result
        return wrapped

    def set_threshold(self, ms):
        self.threshold_ms = ms

query_logger = QueryLogger()

@query_logger
def execute_query(query):
    time.sleep(1.5)
    return True
