import os
import shutil
import re
from pathlib import Path

def rename_files(source_dir, pattern, replacement, file_filter="*"):
    source_path = Path(source_dir).resolve()
    if not source_path.is_dir():
        raise ValueError("Source must be a valid directory")

    for file_path in source_path.glob(file_filter):
        if file_path.is_file():
            old_name = file_path.name
            new_name = re.sub(pattern, replacement, old_name)
            if new_name != old_name:
                new_path = file_path.parent / new_name
                if not new_path.exists():
                    file_path.rename(new_path)

def copy_files(file_paths, dest_dir):
    dest_path = Path(dest_dir).resolve()
    dest_path.mkdir(parents=True, exist_ok=True)

    for file_path in file_paths:
        src_path = Path(file_path).resolve()
        if src_path.is_file() and not src_path.is_symlink():
            shutil.copy2(src_path, dest_path / src_path.name)

def batch_rename(source_dir, rules, dest_dir=None):
    if dest_dir:
        temp_dir = Path(dest_dir).resolve()
        temp_dir.mkdir(parents=True, exist_ok=True)
        for file in Path(source_dir).glob("*"):
            if file.is_file():
                shutil.copy2(file, temp_dir / file.name)
        working_dir = temp_dir
    else:
        working_dir = Path(source_dir).resolve()

    for pattern, replacement in rules:
        rename_files(working_dir, pattern, replacement)

