        cursor = self.conn.execute("SELECT * FROM comments WHERE id = ?", (comment_id,))
        comment = cursor.fetchone()
        if comment:
            return Comment(comment[0], comment[1], comment[2], comment[3],
                         datetime.fromisoformat(comment[4]))
        raise ValueError("Comment not found")

    def get_ticket_comments(self, ticket_id: int) -> List[Comment]:
        cursor = self.conn.execute("SELECT * FROM comments WHERE ticket_id = ?", (ticket_id,))
        return [Comment(c[0], c[1], c[2], c[3], datetime.fromisoformat(c[4])) 
                for c in cursor.fetchall()]

    def update_ticket_status(self, ticket_id: int, new_status: str, user_id: int):
        ticket = self.get_ticket(ticket_id)
        cursor = self.conn.execute("SELECT role FROM users WHERE id = ?", (user_id,))
        user_role = cursor.fetchone()[0]
        if user_role == "admin" or ticket.created_by == user_id:
            self.conn.execute("UPDATE tickets SET status = ? WHERE id = ?", 
                            (new_status, ticket_id))
            self.conn.commit()
        else:
            raise ValueError("Unauthorized to update ticket status")
