import os
import gzip
import shutil
from pathlib import Path

def gzip_file(filename):
    try:
        filepath = Path(filename).resolve()
        if not filepath.is_file() or not filepath.exists():
            return False
        output_path = str(filepath) + '.gz'
        with open(filepath, 'rb') as f_in:
            with gzip.open(output_path, 'wb', compresslevel=9) as f_out:
                shutil.copyfileobj(f_in, f_out)
        return True
    except (OSError, IOError):
        return False

def backup_files(source_dir):
    try:
        backup_dir = Path(source_dir).resolve() / 'backup'
        backup_dir.mkdir(exist_ok=True)
        source_path = Path(source_dir).resolve()
        if not source_path.is_dir() or not source_path.exists():
            return False
        for file in source_path.glob('**/*'):
            if file.is_file() and not file.name.endswith('.gz'):
                relative_path = file.relative_to(source_path)
                output_path = backup_dir / relative_path
                output_path.parent.mkdir(parents=True, exist_ok=True)
                gzip_file(str(file))
        return True
    except (OSError, IOError):
        return False

