class WebCrawler:
    def __init__(self, base_url):
        self.base_url = base_url
        self.domain = urlparse(base_url).netloc
        self.visited = set()
        self.broken_links = set()
        self.missing_images = set()

    def is_valid_url(self, url):
        parsed = urlparse(url)
        return bool(parsed.netloc) and parsed.netloc.endswith(self.domain)

    def check_link(self, url):
        try:
            response = requests.head(url, allow_redirects=True, timeout=5)
            if response.status_code >= 400:
                self.broken_links.add(url)
        except:
            self.broken_links.add(url)

    def check_image(self, img_url):
        try:
            response = requests.head(img_url, allow_redirects=True, timeout=5)
            if response.status_code >= 400:
                self.missing_images.add(img_url)
        except:
            self.missing_images.add(img_url)

    def crawl(self, url):
        if url in self.visited or not self.is_valid_url(url):
            return

        self.visited.add(url)

        try:
            response = requests.get(url, timeout=5)
            soup = BeautifulSoup(response.text, 'html.parser')

            with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:
                links = [urljoin(self.base_url, a.get('href')) for a in soup.find_all('a', href=True)]
                images = [urljoin(self.base_url, img.get('src')) for img in soup.find_all('img', src=True)]

                executor.map(self.check_link, links)
                executor.map(self.check_image, images)
                executor.map(self.crawl, links)

        except:
            self.broken_links.add(url)

    def run(self):
        self.crawl(self.base_url)
        return {
            'broken_links': list(self.broken_links),
            'missing_images': list(self.missing_images)
        }
