import os
import glob
import tarfile

def create_archive(directory):
    if not os.path.isabs(directory):
        directory = os.path.abspath(directory)
    if not os.path.exists(directory):
        raise ValueError("Directory does not exist")
    if not os.path.isdir(directory):
        raise ValueError("Path is not a directory")
    tar = tarfile.open('archive.tar.gz', 'w:gz')
    base_dir = os.path.dirname(directory)
    for f in glob.glob(os.path.join(directory, '**'), recursive=True):
        if not f.endswith(('.pyc', '.txt')):
            normalized_path = os.path.normpath(f)
            if os.path.islink(normalized_path):
                continue
            if not os.path.commonprefix([base_dir, normalized_path]).startswith(base_dir):
                continue
            tar.add(normalized_path, arcname=os.path.relpath(normalized_path, directory))
    tar.close()

