import os
import shutil
import stat
import argparse

def copy_files(src_dir, dst_dir, perms=None):
    if not os.path.exists(src_dir):
        raise FileNotFoundError(f"Source directory {src_dir} does not exist")

    os.makedirs(dst_dir, exist_ok=True)

    for item in os.listdir(src_dir):
        src_path = os.path.join(src_dir, item)
        dst_path = os.path.join(dst_dir, item)

        if os.path.isfile(src_path):
            shutil.copy2(src_path, dst_path)
            if perms:
                os.chmod(dst_path, perms)
        elif os.path.isdir(src_path):
            shutil.copytree(src_path, dst_path)
            if perms:
                os.chmod(dst_path, perms)
                for root, dirs, files in os.walk(dst_path):
                    for d in dirs:
                        os.chmod(os.path.join(root, d), perms)
                    for f in files:
                        os.chmod(os.path.join(root, f), perms)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('src', help='Source directory')
    parser.add_argument('dst', help='Destination directory')
    parser.add_argument('-p', '--permissions', type=lambda x: int(x, 8),
                        help='Octal permissions (e.g. 755)')
    args = parser.parse_args()

    try:
        copy_files(args.src, args.dst, args.permissions)
    except Exception as e:
        print(f"Error: {str(e)}")
        exit(1)

if __name__ == '__main__':
    main()
