                error_404[url].append(ip)

    return error_404

def verify_link(url):
    try:
        response = requests.head(url, timeout=5, allow_redirects=True)
        return url, response.status_code
    except:
        return url, 'unreachable'

def check_external_links(urls):
    valid_urls = []
    for url in urls:
        parsed = urlparse(url)
        if parsed.scheme and parsed.netloc:
            valid_urls.append(url)

    results = {}
    with concurrent.futures.ThreadPoolExecutor(max_workers=10) as executor:
        future_to_url = {executor.submit(verify_link, url): url for url in valid_urls}
        for future in concurrent.futures.as_completed(future_to_url):
            url, status = future.result()
            results[url] = status

    return results

def main(log_file):
    dead_links = analyze_logs(log_file)
    external_status = check_external_links(dead_links.keys())

    report = {}
    for url, ips in dead_links.items():
        report[url] = {
            'hit_count': len(ips),
            'unique_ips': len(set(ips)),
            'status': external_status.get(url, 'internal')
        }

    return report

if __name__ == '__main__':
    results = main('access.log')
    for url, data in results.items():
        print(f"URL: {url}")
        print(f"Hits: {data['hit_count']}")
        print(f"Unique IPs: {data['unique_ips']}")
        print(f"Current Status: {data['status']}\n")
