import requests
import zipfile
import hashlib
import os
import json
from pathlib import Path

class ModInstaller:
    def __init__(self, game_path, mod_dir):
        self.game_path = Path(game_path)
        self.mod_dir = Path(mod_dir)
        self.mod_dir.mkdir(exist_ok=True)

    def download_mod(self, mod_url, expected_hash=None):
        response = requests.get(mod_url, stream=True)
        response.raise_for_status()

        filename = mod_url.split('/')[-1]
        file_path = self.mod_dir / filename

        with open(file_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                f.write(chunk)

        if expected_hash:
            file_hash = hashlib.sha256()
            with open(file_path, 'rb') as f:
                for chunk in iter(lambda: f.read(4096), b''):
                    file_hash.update(chunk)
            if file_hash.hexdigest() != expected_hash:
                os.remove(file_path)
                raise ValueError("File hash does not match expected hash")

        return file_path

    def install_mod(self, mod_path):
        with zipfile.ZipFile(mod_path, 'r') as zip_ref:
            for file in zip_ref.namelist():
                if '..' in file or file.startswith('/'):
                    continue
            zip_ref.extractall(self.game_path)

        manifest = self.game_path / 'mod.json'
        if manifest.exists():
            with open(manifest) as f:
                mod_info = json.load(f)
                return mod_info
        return None

    def uninstall_mod(self, mod_info):
        if not mod_info or 'files' not in mod_info:
            return

        for file in mod_info['files']:
            file_path = self.game_path / file
            if file_path.exists():
                os.remove(file_path)
