import os
from pathlib import Path

def extract_ebooks(archive_path, output_dir):
    supported_formats = {'.epub', '.mobi', '.pdf'}

    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    with zipfile.ZipFile(archive_path, 'r') as archive:
        for file in archive.namelist():
            file_ext = Path(file).suffix.lower()
            if file_ext in supported_formats:
                sanitized_name = os.path.basename(file)
                output_path = os.path.join(output_dir, sanitized_name)

                with archive.open(file) as source:
                    with open(output_path, 'wb') as target:
                        target.write(source.read())

def main():
    archive_path = input("Enter path to ebook archive: ").strip()
    output_dir = input("Enter output directory path: ").strip()

