import pathlib
import os
import stat
import csv
from typing import List, Tuple
from pathlib import Path

def walk_dir(dirpath: str) -> List[Path]:
    try:
        return [path for path in Path(dirpath).rglob('*') if path.is_file()]
    except PermissionError:
        return []

def process_files(files: List[Path]) -> List[Tuple[Path, int, str]]:
    data = []
    for f in files:
        try:
            size = f.stat().st_size
            mode = stat.filemode(f.stat().st_mode)
            data.append([f, size, mode])
        except (PermissionError, FileNotFoundError):
            continue
    return data

def write_to_csv(data: List[Tuple[Path, int, str]], csvpath: str) -> None:
    output_path = Path(csvpath).resolve()
    if not output_path.parent.exists():
        raise ValueError("Output directory does not exist")

    with open(output_path, 'w', newline='', encoding='utf-8') as f:
        writer = csv.writer(f)
        writer.writerow(['path', 'size', 'mode'])
        writer.writerows(data)

def analyze_disk_space(dirpath: str, csvfile: str) -> None:
    if not Path(dirpath).exists():
        raise ValueError("Input directory does not exist")
    files = walk_dir(dirpath)
    data = process_files(files)
    write_to_csv(data, csvfile)

if __name__ == '__main__':
    analyze_disk_space('/home', 'report.csv')

