import os
import time
import shutil
from pathlib import Path

def clean_temp_files(directory, age_days=7, extensions=None):
    if extensions is None:
        extensions = ['.tmp', '.temp', '.bak', '~', '.swp']

    current_time = time.time()
    max_age = current_time - (age_days * 86400)

    try:
        for root, _, files in os.walk(Path(directory).resolve(strict=True)):
            for file in files:
                file_path = os.path.join(root, file)
                if os.path.splitext(file)[1].lower() in extensions:
                    try:
                        stats = os.stat(file_path)
                        if stats.st_mtime < max_age:
                            if os.path.isfile(file_path):
                                os.remove(file_path)
                            elif os.path.isdir(file_path):
                                shutil.rmtree(file_path)
                    except (OSError, PermissionError):
                        continue
    except (OSError, PermissionError):
        raise RuntimeError("Unable to access directory")

if __name__ == "__main__":
    clean_temp_files("/path/to/directory")
