    return Path(filename).suffix.lower() in ALLOWED_EXTENSIONS

@app.route('/')
def index():
    samples = []
    for file in app.config['UPLOAD_FOLDER'].glob('**/*'):
        if file.is_file() and allowed_file(file.name):
            samples.append({
                'name': file.name,
                'size': file.stat().st_size,
                'path': file.relative_to(app.config['UPLOAD_FOLDER'])
            })
    return render_template('index.html', samples=samples)

@app.route('/download/<path:filename>')
def download(filename):
    try:
        file_path = app.config['UPLOAD_FOLDER'] / secure_filename(filename)
        if not file_path.is_file() or not allowed_file(file_path.name):
            abort(404)
        return send_file(file_path, as_attachment=True)
    except:
        abort(404)

@app.route('/download-pack/<pack_name>')
def download_pack(pack_name):
    try:
        pack_dir = app.config['UPLOAD_FOLDER'] / secure_filename(pack_name)
        if not pack_dir.is_dir():
            abort(404)

        zip_path = Path(f'/tmp/{pack_name}.zip')
        with zipfile.ZipFile(zip_path, 'w') as zipf:
            for file in pack_dir.glob('**/*'):
                if file.is_file() and allowed_file(file.name):
                    zipf.write(file, file.relative_to(pack_dir))

        return send_file(zip_path, as_attachment=True)
    except:
        abort(404)
    finally:
        if zip_path.exists():
            zip_path.unlink()

if __name__ == '__main__':
    app.config['UPLOAD_FOLDER'].mkdir(exist_ok=True)
    app.run(host='0.0.0.0', port=5000)
