import os
import requests
import shutil
import tarfile
import subprocess
from pathlib import Path
from typing import Optional

class PackageManager:
    def __init__(self, repo_url: str, cache_dir: str = "/var/cache/pkgmgr"):
        self.repo_url = repo_url.rstrip('/')
        self.cache_dir = Path(cache_dir)
        self.cache_dir.mkdir(parents=True, exist_ok=True)

    def download_package(self, package_name: str, version: str) -> Optional[Path]:
        package_url = f"{self.repo_url}/{package_name}/{version}"
        cache_path = self.cache_dir / f"{package_name}-{version}"

        if cache_path.exists():
            return cache_path

        try:
            response = requests.get(package_url, stream=True)
            response.raise_for_status()

            with cache_path.open('wb') as f:
                shutil.copyfileobj(response.raw, f)

            return cache_path
        except requests.exceptions.RequestException:
            return None

    def install_deb(self, package_path: Path) -> bool:
        try:
            subprocess.run(['dpkg', '-i', str(package_path)], check=True)
            return True
        except subprocess.CalledProcessError:
            return False

    def install_rpm(self, package_path: Path) -> bool:
        try:
            subprocess.run(['rpm', '-i', str(package_path)], check=True)
            return True
        except subprocess.CalledProcessError:
            return False

    def install_tarball(self, package_path: Path) -> bool:
        try:
            with tarfile.open(package_path) as tar:
                def is_safe(member):
                    return not member.name.startswith('/') and '..' not in member.name
                members = list(filter(is_safe, tar.getmembers()))
                tar.extractall(path='/tmp', members=members)
            return True
        except tarfile.TarError:
            return False

    def install_package(self, package_name: str, version: str) -> bool:
        package_path = self.download_package(package_name, version)
        if not package_path:
            return False

        if package_path.suffix == '.deb':
            return self.install_deb(package_path)
        elif package_path.suffix == '.rpm':
            return self.install_rpm(package_path)
        elif package_path.suffix in ('.tar.gz', '.tgz'):
            return self.install_tarball(package_path)
        return False
