import os

def write_to_log(msg, path):
    if not isinstance(msg, str) or not isinstance(path, str):
        raise TypeError("Message and path must be strings")

    if len(msg) > 1024:
        raise ValueError("Message too long")

    path = os.path.normpath(os.path.abspath(path))
    log_dir = os.path.dirname(path)

    if not os.path.exists(log_dir):
        raise OSError("Log directory does not exist")

    if not os.access(log_dir, os.W_OK):
        raise OSError("No write permission for log directory")

    with open(path, 'a') as f:
        f.write(msg.strip() + '\n')
