import ebooklib
from ebooklib import epub
import os
from PIL import Image
import io
import fitz
from bs4 import BeautifulSoup

class EbookAnalyzer:
    def __init__(self, filename):
        self.filename = filename
        self.extension = os.path.splitext(filename)[1]

    def extract_content(self):
        if self.extension == '.epub':
            return self._process_epub()
        elif self.extension == '.pdf':
            return self._process_pdf()

    def _process_epub(self):
        book = epub.read_epub(self.filename)
        metadata = {
            'title': book.get_metadata('DC', 'title')[0][0],
            'creator': book.get_metadata('DC', 'creator')[0][0],
            'language': book.get_metadata('DC', 'language')[0][0]
        }

        text_content = []
        images = []

        for item in book.get_items():
            if item.get_type() == ebooklib.ITEM_DOCUMENT:
                soup = BeautifulSoup(item.get_content(), 'html.parser')
                text_content.append(soup.get_text())

            elif item.get_type() == ebooklib.ITEM_IMAGE:
                img = Image.open(io.BytesIO(item.get_content()))
                images.append(img)

        return metadata, text_content, images

    def _process_pdf(self):
        doc = fitz.open(self.filename)
        metadata = {
            'title': doc.metadata['title'],
            'author': doc.metadata['author'],
            'creator': doc.metadata['creator']
        }

        text_content = []
        images = []

        for page in doc:
            text_content.append(page.get_text())
            image_list = page.get_images()

            for img in image_list:
                xref = img[0]
                base_image = doc.extract_image(xref)
                image_bytes = base_image['image']
                img = Image.open(io.BytesIO(image_bytes))
                images.append(img)

        return metadata, text_content, images
