import os
import tarfile
import hashlib
import boto3
from botocore.exceptions import ClientError
from typing import List
from fastapi import FastAPI, File, UploadFile, HTTPException
from pydantic import BaseModel

app = FastAPI()

class ArtifactMetadata(BaseModel):
    name: str
    version: str
    hash: str
    size: int

class Pipeline:
    def __init__(self):
        self.s3_client = boto3.client('s3')
        self.bucket = os.getenv('S3_BUCKET')
        self.artifacts_dir = '/tmp/artifacts'
        os.makedirs(self.artifacts_dir, exist_ok=True)

    def calculate_hash(self, filepath: str) -> str:
        sha256 = hashlib.sha256()
        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest()

    def create_tarball(self, artifact_path: str, output_path: str):
        with tarfile.open(output_path, 'w:gz') as tar:
            tar.add(artifact_path, arcname=os.path.basename(artifact_path))

    async def upload_artifact(self, file: UploadFile) -> ArtifactMetadata:
        artifact_path = os.path.join(self.artifacts_dir, file.filename)
        with open(artifact_path, 'wb+') as f:
            f.write(await file.read())

        tarball_path = f"{artifact_path}.tar.gz"
        self.create_tarball(artifact_path, tarball_path)

        file_hash = self.calculate_hash(tarball_path)
        file_size = os.path.getsize(tarball_path)

        try:
            self.s3_client.upload_file(
                tarball_path,
                self.bucket,
                f"artifacts/{file.filename}.tar.gz"
            )
        except ClientError as e:
            raise HTTPException(status_code=500, detail=str(e))
        finally:
            os.remove(artifact_path)
            os.remove(tarball_path)

        return ArtifactMetadata(
            name=file.filename,
            version="1.0",
            hash=file_hash,
            size=file_size
        )

    def get_artifact(self, name: str) -> str:
        download_path = os.path.join(self.artifacts_dir, f"{name}.tar.gz")
        try:
            self.s3_client.download_file(
                self.bucket,
                f"artifacts/{name}.tar.gz",
                download_path
            )
            return download_path
        except ClientError as e:
            raise HTTPException(status_code=404, detail="Artifact not found")

pipeline = Pipeline()

@app.post("/artifacts/upload")
async def upload_artifact(file: UploadFile = File(...)):
    return await pipeline.upload_artifact(file)

@app.get("/artifacts/{name}")
def get_artifact(name: str):
    return pipeline.get_artifact(name)

@app.get("/artifacts")
def list_artifacts():
    try:
        response = pipeline.s3_client.list_objects_v2(
            Bucket=pipeline.bucket,
            Prefix="artifacts/"
        )
        return [obj['Key'] for obj in response.get('Contents', [])]
    except ClientError as e:
        raise HTTPException(status_code=500, detail=str(e))
