import os
import sys
import subprocess
import yaml
import shutil
from pathlib import Path
from typing import Dict, List

def load_config(config_path: str) -> Dict:
    with open(config_path, 'r') as f:
        return yaml.safe_load(f)

def clone_repo(repo_url: str, target_dir: str) -> None:
    subprocess.run(['git', 'clone', repo_url, target_dir], check=True)

def install_dependencies(project_dir: str, package_manager: str) -> None:
    if package_manager == 'pip':
        requirements = Path(project_dir) / 'requirements.txt'
        if requirements.exists():
            subprocess.run(['pip', 'install', '-r', str(requirements)], check=True)
    elif package_manager == 'npm':
        subprocess.run(['npm', 'install'], cwd=project_dir, check=True)

def setup_environment(config: Dict) -> None:
    workspace = Path(config['workspace_dir']).resolve()
    workspace.mkdir(parents=True, exist_ok=True)

    for project in config['projects']:
        project_dir = workspace / project['name']
        if project_dir.exists():
            shutil.rmtree(project_dir)

        clone_repo(project['repo'], str(project_dir))
        install_dependencies(str(project_dir), project['package_manager'])

def main():
    if len(sys.argv) != 2:
        sys.exit(1)

    config_path = sys.argv[1]
    if not os.path.exists(config_path):
        sys.exit(1)

    try:
        config = load_config(config_path)
        setup_environment(config)
    except (subprocess.CalledProcessError, yaml.YAMLError) as e:
        sys.exit(1)

if __name__ == '__main__':
    main()
