import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin, urlparse
import validators
import time
from requests.exceptions import RequestException
from typing import Set

class SecureWebCrawler:
    def __init__(self, start_url: str, max_pages: int = 100):
        self.start_url = start_url
        self.max_pages = max_pages
        self.crawled_urls: Set[str] = set()
        self.session = requests.Session()
        self.session.headers.update({
            'User-Agent': 'SecureBot/1.0',
        })

    def is_valid_url(self, url: str) -> bool:
        try:
            result = urlparse(url)
            return all([result.scheme, result.netloc]) and validators.url(url)
        except Exception:
            return False

    def download_page(self, url: str) -> tuple[str, list[str]]:
        try:
            response = self.session.get(
                url,
                timeout=10,
                allow_redirects=True,
                verify=True
            )
            response.raise_for_status()
            soup = BeautifulSoup(response.text, 'html.parser')
            links = []
            for link in soup.find_all('a'):
                href = link.get('href')
                if href:
                    absolute_url = urljoin(url, href)
                    if self.is_valid_url(absolute_url):
                        links.append(absolute_url)
            return response.text, links
        except RequestException:
            return "", []

    def crawl(self):
        if not self.is_valid_url(self.start_url):
            return

        queue = [self.start_url]
        while queue and len(self.crawled_urls) < self.max_pages:
            url = queue.pop(0)
            if url in self.crawled_urls:
                continue

            content, links = self.download_page(url)
            if content:
                self.crawled_urls.add(url)
                queue.extend([link for link in links if link not in self.crawled_urls])
            time.sleep(1)

        return self.crawled_urls
