import ast
import libcst as cst
from typing import Optional, Dict, Any
from pathlib import Path
import astroid

class TypeAnnotator(cst.CSTTransformer):
    def __init__(self):
        self.type_map = {}

    def infer_type(self, node: astroid.NodeNG) -> Optional[str]:
        if isinstance(node, astroid.Const):
            return type(node.value).__name__
        elif isinstance(node, astroid.List):
            return "List"
        elif isinstance(node, astroid.Dict):
            return "Dict"
        elif isinstance(node, astroid.Call):
            return node.func.name if hasattr(node.func, "name") else None
        return None

    def visit_FunctionDef(self, node: cst.FunctionDef) -> cst.FunctionDef:
        updated_params = []
        for param in node.params.params:
            param_name = param.name.value
            if param_name in self.type_map:
                annotation = cst.Annotation(
                    annotation=cst.Name(self.type_map[param_name])
                )
                updated_param = param.with_changes(annotation=annotation)
                updated_params.append(updated_param)
            else:
                updated_params.append(param)

        return node.with_changes(
            params=node.params.with_changes(params=updated_params)
        )

def annotate_file(file_path: str) -> str:
    with open(file_path, "r", encoding="utf-8") as f:
        source = f.read()

    module = astroid.parse(source)
    annotator = TypeAnnotator()

    for node in module.nodes_of_class(astroid.FunctionDef):
        for param in node.args.args:
            inferred = None
            try:
                inferred = param.inferred()[0]
                annotator.type_map[param.name] = annotator.infer_type(inferred)
            except:
                continue

    source_tree = cst.parse_module(source)
    modified_tree = source_tree.visit(annotator)
    return modified_tree.code

def main():
    input_file = Path("input.py")
    if not input_file.is_file():
        raise FileNotFoundError("Input file not found")

    annotated_code = annotate_file(str(input_file))

    with open("output.py", "w", encoding="utf-8") as f:
        f.write(annotated_code)

if __name__ == "__main__":
    main()
