from pydantic import BaseModel, validator
from typing import Optional
import hashlib
import uuid
import os
from PIL import Image
import io

app = FastAPI()

class Receipt(BaseModel):
    receipt: bytes

    @validator('receipt')
    def validate_receipt(cls, v):
        try:
            img = Image.open(io.BytesIO(v))
            if img.format not in ['JPEG', 'PNG', 'PDF']:
                raise ValueError
            if len(v) > 10_000_000:
                raise ValueError
            return v
        except:
            raise ValueError("Invalid receipt format or size")

@app.post("/submit-receipt")
async def submit_receipt(receipt: Receipt):
    try:
        receipt_id = uuid.uuid4().hex
        file_hash = hashlib.sha256(receipt.receipt).hexdigest()

        storage_path = f"receipts/{receipt_id[:2]}/{receipt_id}"
        os.makedirs(os.path.dirname(storage_path), exist_ok=True)

        with open(storage_path, "wb") as f:
            f.write(receipt.receipt)

        return {"receipt_id": receipt_id, "hash": file_hash}
    except Exception:
        raise HTTPException(status_code=500, detail="Receipt processing failed")

if __name__ == '__main__':
