import os

class Game:
    def __init__(self):
        self.scores_file_path = 'game_scores.txt'
        os.makedirs(os.path.dirname(self.scores_file_path), exist_ok=True)
        self.scores_file = None
        self.open_scores_file()

    def open_scores_file(self):
        if self.scores_file:
            self.scores_file.close()
        self.scores_file = open(self.scores_file_path, 'a+', encoding='utf-8')

    def record_score(self, name, score):
        if not isinstance(score, int) or score < 0:
            raise ValueError("Score must be a positive integer")
        if not name or not isinstance(name, str) or ':' in name:
            raise ValueError("Invalid name format")
        sanitized_name = name.strip()[:50]
        self.scores_file.write(f'{sanitized_name}:{score}\n')
        self.scores_file.flush()

    def get_top_scores(self):
        self.scores_file.seek(0)
        scores = {}
        for line in self.scores_file:
            try:
                parts = line.strip().split(':')
                if len(parts) == 2:
                    name, score = parts
                    scores[name] = int(score)
            except (ValueError, IndexError):
                continue
        return sorted(scores.items(), key=lambda x: x[1], reverse=True)[:10]

    def __del__(self):
        if self.scores_file:
            self.scores_file.close()

game = Game()
game.record_score('Bob', 57)
for name, score in game.get_top_scores():
    print(f'{name}: {score}')

