import tempfile
from pathlib import Path
import yaml
from typing import Dict

class CISystem:
    def __init__(self, config_path: str):
        self.config = self._load_config(config_path)
        self.workspace = Path(tempfile.mkdtemp())

    def _load_config(self, path: str) -> Dict:
        with open(path, 'r') as f:
            return yaml.safe_load(f)

    def checkout_code(self):
        repo_url = self.config['repository']
        subprocess.run(['git', 'clone', repo_url, str(self.workspace)], check=True)

    def run_tests(self):
        test_cmd = self.config['test_command'].split()
        subprocess.run(test_cmd, cwd=str(self.workspace), check=True)

    def publish_artifacts(self):
        artifacts = self.config['artifacts']
        dest_dir = Path(self.config['artifact_destination'])
        dest_dir.mkdir(parents=True, exist_ok=True)

        for artifact in artifacts:
            src = self.workspace / artifact
            if src.is_file():
                shutil.copy2(src, dest_dir)
            elif src.is_dir():
                shutil.copytree(src, dest_dir / src.name)

    def cleanup(self):
        shutil.rmtree(self.workspace)

    def run(self):
        try:
            self.checkout_code()
            self.run_tests() 
            self.publish_artifacts()
        finally:
            self.cleanup()

def main():
    ci = CISystem('ci_config.yml')
    ci.run()

if __name__ == '__main__':
    main()
