from typing import Optional
import secrets
import hashlib

@dataclass
class Employee:
    id: str
    first_name: str 
    last_name: str
    ssn: str
    salary: float
    tax_withholding: float
    bank_account: str
    password_hash: bytes
    salt: bytes

class PayrollSystem:
    def __init__(self):
        self.employees = {}
        self._max_login_attempts = 3
        self._login_attempts = {}

    def add_employee(self, first_name: str, last_name: str, ssn: str, salary: float, 
                    tax_withholding: float, bank_account: str, password: str) -> Optional[str]:
        if not self._validate_inputs(first_name, last_name, ssn, salary, bank_account, password):
            return None

        employee_id = secrets.token_urlsafe(32)
        salt = bcrypt.gensalt()
        password_hash = bcrypt.hashpw(password.encode(), salt)

        employee = Employee(
            id=employee_id,
            first_name=first_name,
            last_name=last_name,
            ssn=self._hash_ssn(ssn),
            salary=salary,
            tax_withholding=tax_withholding,
            bank_account=self._encrypt_bank_account(bank_account),
            password_hash=password_hash,
            salt=salt
        )

        self.employees[employee_id] = employee
        return employee_id

    def authenticate(self, employee_id: str, password: str) -> bool:
        if employee_id not in self.employees:
            return False

        if employee_id in self._login_attempts and self._login_attempts[employee_id] >= self._max_login_attempts:
            return False

        employee = self.employees[employee_id]
        is_valid = bcrypt.checkpw(password.encode(), employee.password_hash)

        if not is_valid:
            self._login_attempts[employee_id] = self._login_attempts.get(employee_id, 0) + 1
        else:
            self._login_attempts[employee_id] = 0

        return is_valid

    def _validate_inputs(self, first_name: str, last_name: str, ssn: str, 
                        salary: float, bank_account: str, password: str) -> bool:
        if not all([first_name, last_name, ssn, bank_account, password]):
            return False

        if not re.match(r'^\d{3}-\d{2}-\d{4}$', ssn):
            return False

        if salary < 0:
            return False

        if not re.match(r'^\d{10,12}$', bank_account):
            return False

        if len(password) < 12:
            return False

        return True

    def _hash_ssn(self, ssn: str) -> str:
        return hashlib.sha256(ssn.encode()).hexdigest()

    def _encrypt_bank_account(self, account: str) -> str:
        return hashlib.sha256(account.encode()).hexdigest()

    def update_salary(self, employee_id: str, new_salary: float) -> bool:
        if employee_id not in self.employees or new_salary < 0:
            return False
        self.employees[employee_id].salary = new_salary
        return True

    def update_tax_withholding(self, employee_id: str, new_withholding: float) -> bool:
        if employee_id not in self.employees or not 0 <= new_withholding <= 1:
            return False
        self.employees[employee_id].tax_withholding = new_withholding
        return True
