import os
import re
import sys
import stat
from pathlib import Path
from typing import List

def validate_pattern(pattern: str) -> bool:
    try:
        re.compile(pattern)
        return True
    except re.error:
        return False

def validate_path(path: Path) -> bool:
    return path.exists() and path.is_file() and os.access(path.parent, os.W_OK)

def sanitize_filename(filename: str) -> str:
    return "".join(c for c in filename if c.isalnum() or c in "._- ")

def rename_files(directory: str, pattern: str, replacement: str, permissions: int) -> List[tuple]:
    if not validate_pattern(pattern):
        sys.exit(1)

    directory_path = Path(directory).resolve()
    if not directory_path.is_dir():
        sys.exit(1)

    renamed_files = []

    for file_path in directory_path.iterdir():
        if file_path.is_file():
            try:
                new_name = re.sub(pattern, replacement, file_path.name)
                new_name = sanitize_filename(new_name)
                new_path = file_path.parent / new_name

                if validate_path(file_path) and not new_path.exists():
                    file_path.rename(new_path)
                    os.chmod(new_path, permissions)
                    renamed_files.append((file_path.name, new_name))

            except (OSError, re.error):
                continue

    return renamed_files

def main():
    if len(sys.argv) != 5:
        sys.exit(1)

    directory = sys.argv[1]
    pattern = sys.argv[2]
    replacement = sys.argv[3]

    try:
        permissions = int(sys.argv[4], 8)
    except ValueError:
        sys.exit(1)

    renamed = rename_files(directory, pattern, replacement, permissions)
