class FoodTracker:
    def __init__(self):
        self.food_log = {}
        self.daily_total = 0

    def add_food(self, food_name: str, serving_size: float, calories: int) -> None:
        if not isinstance(food_name, str) or not food_name.strip():
            raise ValueError("Food name must be a non-empty string")
        if not isinstance(serving_size, (int, float)) or serving_size <= 0:
            raise ValueError("Serving size must be a positive number")
        if not isinstance(calories, (int, float)) or calories < 0:
            raise ValueError("Calories must be a non-negative number")

        food_name = food_name.strip().lower()
        total_calories = serving_size * calories

        if food_name in self.food_log:
            self.food_log[food_name]["servings"] += serving_size
            self.food_log[food_name]["total_calories"] += total_calories
        else:
            self.food_log[food_name] = {
                "servings": serving_size,
                "calories_per_serving": calories,
                "total_calories": total_calories
            }
        self.daily_total += total_calories

    def get_calories(self) -> float:
        return round(self.daily_total, 2)

    def get_food_log(self) -> dict:
        return dict(self.food_log)

    def reset_day(self) -> None:
        self.food_log.clear()
        self.daily_total = 0

