from typing import Dict, List
import datetime

class Note:
    def __init__(self, title: str, content: str):
        self.title = title.strip()
        self.content = content.strip()
        self.created_at = datetime.datetime.now()
        self.updated_at = self.created_at

    def update(self, content: str):
        self.content = content.strip()
        self.updated_at = datetime.datetime.now()

class NoteManager:
    def __init__(self):
        self.notes: Dict[str, Note] = {}

    def add_note(self, title: str, content: str) -> bool:
        if not title or title.strip() in self.notes:
            return False
        self.notes[title.strip()] = Note(title, content)
        return True

    def update_note(self, title: str, content: str) -> bool:
        if title.strip() not in self.notes:
            return False
        self.notes[title.strip()].update(content)
        return True

    def delete_note(self, title: str) -> bool:
        if title.strip() not in self.notes:
            return False
        del self.notes[title.strip()]
        return True

    def get_note(self, title: str) -> Note:
        return self.notes.get(title.strip())

    def list_notes(self) -> List[str]:
        return sorted(self.notes.keys())

    def search_notes(self, query: str) -> List[str]:
        query = query.lower().strip()
        return [title for title in self.notes.keys() 
                if query in title.lower() or query in self.notes[title].content.lower()]
