    if not validate_path(src):
        raise ValueError("Invalid source path")
    shutil.copy2(src, dst)
    os.chmod(dst, stat.S_IRUSR | stat.S_IWUSR)

def calculate_checksum(file_path):
    sha256 = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for block in iter(lambda: f.read(4096), b''):
            sha256.update(block)
    return sha256.hexdigest()

def rotate_logs(log_file):
    if not os.path.isabs(log_file):
        raise ValueError("Absolute path required")

    log_dir = os.path.dirname(log_file)
    if not os.access(log_dir, os.W_OK):
        raise PermissionError("Insufficient permissions")

    timestamp = time.strftime('%Y%m%d%H%M%S')
    rotated_file = f"{log_file}.{timestamp}"

    if os.path.exists(log_file):
        secure_copy(log_file, rotated_file)
        original_checksum = calculate_checksum(log_file)
        backup_checksum = calculate_checksum(rotated_file)

        if original_checksum == backup_checksum:
            with open(log_file, 'w') as f:
                os.chmod(log_file, stat.S_IRUSR | stat.S_IWUSR)
        else:
            os.remove(rotated_file)
