import os
import zipfile
import hashlib
from pathlib import Path

class Backup:
    def __init__(self, backup_dir):
        self.backup_dir = Path(backup_dir).resolve()
        self.backup_dir.mkdir(parents=True, exist_ok=True)

    def create_backup(self, src_path):
        src_path = Path(src_path).resolve()
        if not src_path.exists():
            raise FileNotFoundError(f"Source path does not exist: {src_path}")

        archive_name = f"{src_path.name}_{hashlib.sha256(str(src_path).encode()).hexdigest()[:8]}.zip"
        archive_path = self.backup_dir / archive_name

        with zipfile.ZipFile(archive_path, 'w', zipfile.ZIP_DEFLATED) as zf:
            if src_path.is_file():
                zf.write(src_path, src_path.name)
            else:
                for root, _, files in os.walk(src_path):
                    root_path = Path(root)
                    for file in files:
                        file_path = root_path / file
                        rel_path = file_path.relative_to(src_path.parent)
                        zf.write(file_path, rel_path)
        return archive_path

    def extract_backup(self, archive_path, dest_path):
        archive_path = Path(archive_path).resolve()
        dest_path = Path(dest_path).resolve()

        if not archive_path.exists():
            raise FileNotFoundError(f"Archive does not exist: {archive_path}")

        if not archive_path.is_file() or archive_path.suffix != '.zip':
            raise ValueError("Invalid archive file")

        if not dest_path.exists():
            dest_path.mkdir(parents=True)

        if not dest_path.is_dir():
            raise NotADirectoryError(f"Destination must be a directory: {dest_path}")

        with zipfile.ZipFile(archive_path, 'r') as zf:
            zf.extractall(path=dest_path)
