import os
import hashlib
from pathlib import Path
from collections import defaultdict
import shutil
import stat

def get_file_hash(filepath):
    sha256_hash = hashlib.sha256()
    with open(filepath, "rb") as f:
        for chunk in iter(lambda: f.read(4096), b""):
            sha256_hash.update(chunk)
    return sha256_hash.hexdigest()

def find_duplicates(root_dir):
    hash_map = defaultdict(list)

    for path in Path(root_dir).rglob('*'):
        if path.is_file():
            file_hash = get_file_hash(str(path))
            hash_map[file_hash].append(str(path))

    return {k:v for k,v in hash_map.items() if len(v) > 1}

def delete_duplicates(duplicate_files, keep_path):
    for filepath in duplicate_files:
        if filepath != keep_path:
            try:
                os.chmod(filepath, stat.S_IWRITE)
                os.remove(filepath)
            except OSError as e:
                print(f"Error deleting {filepath}: {e}")

def set_permissions(filepath, readonly=True):
    try:
        if readonly:
            os.chmod(filepath, stat.S_IREAD)
        else:
