import hashlib

class CSVProcessor:
    def __init__(self, file_path):
        self.allowed_extensions = {'.csv'}
        self.file_path = Path(file_path).resolve()
        if not self._is_valid_file():
            raise ValueError("Invalid file path or file type")

    def _is_valid_file(self):
        return (self.file_path.suffix.lower() in self.allowed_extensions and 
                self.file_path.is_file() and
                os.path.abspath(self.file_path).startswith(os.getcwd()))

    def _validate_df(self, df):
        if df.empty or len(df.columns) == 0:
            raise ValueError("Empty or invalid dataframe")
        return df

    def process_file(self):
        df = pd.read_csv(self.file_path, encoding='utf-8')
        df = self._validate_df(df)
        return df

    def generate_report(self):
        df = self.process_file()
        stats = {
            'row_count': len(df),
            'column_count': len(df.columns),
            'missing_values': df.isnull().sum().to_dict(),
            'data_types': df.dtypes.to_dict(),
            'numeric_summary': df.describe().to_dict(),
            'file_hash': self._get_file_hash()
        }
        return stats

    def _get_file_hash(self):
        sha256 = hashlib.sha256()
        with open(self.file_path, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest()

    def save_report(self, output_path):
        report = self.generate_report()
        output_path = Path(output_path).resolve()
        if not output_path.parent.exists():
            raise ValueError("Output directory does not exist")
        pd.DataFrame([report]).to_json(output_path, orient='records')
