class FolderSync:
    def __init__(self, source: str, target: str):
        self.source = Path(source).resolve()
        self.target = Path(target).resolve()
        self.checksum_cache: Dict[str, str] = {}

    def get_file_hash(self, filepath: Path) -> str:
        if str(filepath) in self.checksum_cache:
            return self.checksum_cache[str(filepath)]

        sha256 = hashlib.sha256()
        with open(filepath, 'rb') as f:
            for block in iter(lambda: f.read(4096), b''):
                sha256.update(block)
        checksum = sha256.hexdigest()
        self.checksum_cache[str(filepath)] = checksum
        return checksum

    def scan_folder(self, folder: Path) -> Dict[str, float]:
        files = {}
        for filepath in folder.rglob('*'):
            if filepath.is_file():
                rel_path = str(filepath.relative_to(folder))
                files[rel_path] = filepath.stat().st_mtime
        return files

    def sync(self):
        source_files = self.scan_folder(self.source)
        target_files = self.scan_folder(self.target)

        for rel_path, src_mtime in source_files.items():
            src_file = self.source / rel_path
            dst_file = self.target / rel_path

            if rel_path not in target_files:
                dst_file.parent.mkdir(parents=True, exist_ok=True)
                shutil.copy2(src_file, dst_file)
            else:
                if src_mtime > target_files[rel_path]:
                    src_hash = self.get_file_hash(src_file)
                    dst_hash = self.get_file_hash(dst_file)
                    if src_hash != dst_hash:
                        shutil.copy2(src_file, dst_file)

        for rel_path in target_files:
            if rel_path not in source_files:
                (self.target / rel_path).unlink()

    def continuous_sync(self, interval: int = 60):
        while True:
            try:
                self.sync()
                time.sleep(interval)
            except KeyboardInterrupt:
                break
            except Exception as e:
                print(f"Error during sync: {e}")
                time.sleep(interval)

if __name__ == "__main__":
