class TestAnalyzer:
    def __init__(self, src_dir, test_dir):
        self.src_dir = src_dir
        self.test_dir = test_dir
        self.cov = coverage.Coverage()

    def analyze_coverage(self):
        self.cov.start()
        import pytest
        pytest.main([self.test_dir])
        self.cov.stop()
        self.cov.save()
        return self.cov.get_data()

    def find_uncovered_code(self):
        uncovered = []
        for src_file in os.listdir(self.src_dir):
            if src_file.endswith('.py'):
                with open(os.path.join(self.src_dir, src_file)) as f:
                    tree = ast.parse(f.read())

                for node in ast.walk(tree):
                    if isinstance(node, (ast.FunctionDef, ast.ClassDef)):
                        if not self._is_covered(node):
                            uncovered.append(node.name)
        return uncovered

    def _is_covered(self, node):
        coverage_data = self.cov.get_data()
        return any(node.lineno in coverage_data.lines for file in coverage_data.measured_files())

    def generate_test(self, function_name, permissions):
