def test_{{ function_name }}():
    {% if 'read' in permissions %}
    result = {{ function_name }}.read()
    assert result is not None
    {% endif %}

    {% if 'write' in permissions %}
    result = {{ function_name }}.write()
    assert result is not None
    {% endif %}

    {% if 'execute' in permissions %} 
    result = {{ function_name }}.execute()
    assert result is not None
    {% endif %}
''')

        return template.render(function_name=function_name, permissions=permissions)

