import os
from googletrans import Translator

def validate_languages(langs):
    valid_codes = Translator().LANGUAGES.keys()
    for src, dest in langs:
        if src not in valid_codes or dest not in valid_codes:
            raise ValueError(f"Invalid language code: {src} or {dest}")

def translate_file(filename, lang_pairs):
    if not os.path.exists(filename):
        raise FileNotFoundError(f"File not found: {filename}")

    validate_languages(lang_pairs)
    translator = Translator()

    with open(filename, 'r', encoding='utf-8') as f:
        text = f.read()

    translations = {}
    for src, dest in lang_pairs:
        translation = translator.translate(text, src=src, dest=dest)
        outfile = f"{filename}_{src}_to_{dest}.txt"

        with open(outfile, 'w', encoding='utf-8') as f:
            f.write(translation.text)
        translations[(src, dest)] = outfile

    return translations

def main():
    filename = input("Enter filename to translate: ").strip()
    pairs = []
    while True:
        try:
            src = input("Enter source language code (or 'done'): ").strip().lower()
            if src == 'done':
                break
            dest = input("Enter destination language code: ").strip().lower()
            pairs.append((src, dest))
        except EOFError:
            break

    try:
        results = translate_file(filename, pairs)
        for (src, dest), outfile in results.items():
            print(f"Translated {src} to {dest}: {outfile}")
    except Exception as e:
        print(f"Error: {str(e)}")

if __name__ == "__main__":
    main()
