from pathlib import Path

def secure_backup(src_path: str, dst_path: str) -> None:
    src = Path(src_path).resolve()
    dst = Path(dst_path).resolve()

    if not src.exists():
        raise FileNotFoundError(f"Source path does not exist")

    if not src.is_absolute():
        raise ValueError("Source path must be absolute")

    if not dst.is_absolute():
        raise ValueError("Destination path must be absolute")

    if not os.access(src, os.R_OK):
        raise PermissionError("No read permission for source")

    if not os.access(dst.parent, os.W_OK):
        raise PermissionError("No write permission for destination")

    if src.is_file():
        shutil.copy2(src, dst)
    elif src.is_dir():
        shutil.copytree(src, dst, dirs_exist_ok=True)
