from datetime import datetime, timedelta
from enum import Enum

class PetType(Enum):
    DOG = "Dog"
    CAT = "Cat"
    BIRD = "Bird"

class Pet:
    def __init__(self, name: str, pet_type: PetType, birth_date: datetime):
        self.name = name
        self.pet_type = pet_type
        self.birth_date = birth_date
        self.feeding_schedule = []
        self.vaccine_history = []
        self.next_vaccines = []

class FeedingRecord:
    def __init__(self, pet: Pet, time: datetime, food_type: str, amount: float):
        self.pet = pet
        self.time = time
        self.food_type = food_type
        self.amount = amount

class VaccineRecord:
    def __init__(self, pet: Pet, vaccine_name: str, date: datetime):
        self.pet = pet
        self.vaccine_name = vaccine_name
        self.date = date

class PetCareManager:
    def __init__(self):
        self.pets = []

    def add_pet(self, name: str, pet_type: PetType, birth_date: datetime) -> Pet:
        pet = Pet(name, pet_type, birth_date)
        self.pets.append(pet)
        return pet

    def record_feeding(self, pet: Pet, food_type: str, amount: float):
        feeding = FeedingRecord(pet, datetime.now(), food_type, amount)
        pet.feeding_schedule.append(feeding)

    def record_vaccine(self, pet: Pet, vaccine_name: str):
        vaccine = VaccineRecord(pet, vaccine_name, datetime.now())
        pet.vaccine_history.append(vaccine)

    def schedule_vaccine(self, pet: Pet, vaccine_name: str, due_date: datetime):
        vaccine = VaccineRecord(pet, vaccine_name, due_date)
        pet.next_vaccines.append(vaccine)

    def get_due_vaccines(self) -> list:
        due_vaccines = []
        for pet in self.pets:
            for vaccine in pet.next_vaccines:
                if vaccine.date <= datetime.now():
                    due_vaccines.append(vaccine)
        return due_vaccines

    def get_feeding_history(self, pet: Pet, days: int) -> list:
        cutoff_date = datetime.now() - timedelta(days=days)
        return [f for f in pet.feeding_schedule if f.time >= cutoff_date]
