import tempfile
from pathlib import Path

class MediaLibrary:
    def __init__(self, library_path: str):
        self.library_path = Path(library_path)
        self.library_path.mkdir(parents=True, exist_ok=True)
        self.temp_dir = Path(tempfile.mkdtemp())

    def add_album(self, album_path: str, artist: str, album: str):
        album_dir = Path(album_path)
        if not album_dir.is_dir():
            raise ValueError("Album path must be a directory")

        archive_name = f"{artist}-{album}.zip"
        archive_path = self.library_path / archive_name

        with zipfile.ZipFile(archive_path, 'w', zipfile.ZIP_DEFLATED) as zf:
            for track in album_dir.glob('*'):
                if track.is_file():
                    zf.write(track, track.name)

    def extract_track(self, artist: str, album: str, track_name: str) -> str:
        archive_name = f"{artist}-{album}.zip"
        archive_path = self.library_path / archive_name

        if not archive_path.exists():
            raise FileNotFoundError("Album not found in library")

        track_path = self.temp_dir / track_name

        with zipfile.ZipFile(archive_path, 'r') as zf:
            if track_name not in zf.namelist():
                raise FileNotFoundError("Track not found in album")
            zf.extract(track_name, self.temp_dir)

        return str(track_path)

    def list_albums(self):
        albums = []
        for archive in self.library_path.glob('*.zip'):
            artist, album = archive.stem.split('-', 1)
            albums.append((artist, album))
        return albums

    def list_tracks(self, artist: str, album: str):
        archive_name = f"{artist}-{album}.zip"
        archive_path = self.library_path / archive_name

        if not archive_path.exists():
            raise FileNotFoundError("Album not found in library")

        with zipfile.ZipFile(archive_path, 'r') as zf:
            return zf.namelist()

    def cleanup(self):
        shutil.rmtree(self.temp_dir)
