import os
import re
from typing import Callable, List

def rename_files(directory: str, rules: List[Callable[[str], str]]) -> None:
    for filename in os.listdir(directory):
        if os.path.isfile(os.path.join(directory, filename)):
            new_name = filename
            for rule in rules:
                new_name = rule(new_name)

            if new_name != filename:
                old_path = os.path.join(directory, filename)
                new_path = os.path.join(directory, new_name)
                os.rename(old_path, new_path)

def remove_spaces(filename: str) -> str:
    return filename.replace(' ', '_')

def lowercase(filename: str) -> str:
    return filename.lower()

def add_prefix(prefix: str) -> Callable[[str], str]:
    return lambda filename: f"{prefix}{filename}"

def add_suffix(suffix: str) -> Callable[[str], str]:
    name, ext = os.path.splitext(filename)
    return lambda filename: f"{name}{suffix}{ext}"

def remove_pattern(pattern: str) -> Callable[[str], str]:
    return lambda filename: re.sub(pattern, '', filename)

def replace_pattern(pattern: str, replacement: str) -> Callable[[str], str]:
    return lambda filename: re.sub(pattern, replacement, filename)

def numbered_sequence(start: int = 1) -> Callable[[str], str]:
    counter = start
    def sequence(filename: str) -> str:
        nonlocal counter
        name, ext = os.path.splitext(filename)
        new_name = f"{counter:03d}{ext}"
        counter += 1
        return new_name
    return sequence
