                'interval': 10000000000,
                'timeout': 5000000000,
                'retries': 3
            }
            healthchecks.append(healthcheck)

    def stop(self):
        for service in self.services:
            service.stop()
        self.network.remove()

class Service:
    def __init__(self, name, image):
        self.name = name 
        self.image = image
        self.container = None

    def run(self, client, network):
        self.container = client.containers.run(
            self.image,
            name=self.name,
            network=network.name,
            mounts=[
                Mount(
                    target='/data',
                    source='app_data',
                    type='volume'
                )
            ],
            restart_policy={
                'Name': 'on-failure',
                'MaximumRetryCount': 3
            },
            detach=True
        )

    def stop(self):
