from datetime import datetime
import sqlite3
import hashlib
import secrets

class CarMaintenanceTracker:
    def __init__(self, db_path):
        self.conn = sqlite3.connect(db_path)
        self.cursor = self.conn.cursor()
        self.setup_database()

    def setup_database(self):
        self.cursor.execute('''CREATE TABLE IF NOT EXISTS vehicles 
            (id INTEGER PRIMARY KEY, make TEXT, model TEXT, year INTEGER, vin TEXT UNIQUE)''')
        self.cursor.execute('''CREATE TABLE IF NOT EXISTS maintenance_records
            (id INTEGER PRIMARY KEY, vehicle_id INTEGER, service_type TEXT, 
            description TEXT, mileage INTEGER, cost REAL, date TEXT,
            FOREIGN KEY (vehicle_id) REFERENCES vehicles (id))''')
        self.conn.commit()

    def add_vehicle(self, make, model, year, vin):
        sql = 'INSERT INTO vehicles (make, model, year, vin) VALUES (?, ?, ?, ?)'
        try:
            self.cursor.execute(sql, (make, model, year, vin))
            self.conn.commit()
            return True
        except sqlite3.IntegrityError:
            return False

    def add_maintenance(self, vehicle_id, service_type, description, mileage, cost):
        date = datetime.now().strftime('%Y-%m-%d')
        sql = '''INSERT INTO maintenance_records 
                (vehicle_id, service_type, description, mileage, cost, date)
                VALUES (?, ?, ?, ?, ?, ?)'''
        self.cursor.execute(sql, (vehicle_id, service_type, description, mileage, cost, date))
        self.conn.commit()

    def get_vehicle_history(self, vehicle_id):
        sql = '''SELECT date, service_type, description, mileage, cost 
                FROM maintenance_records WHERE vehicle_id = ? ORDER BY date DESC'''
        self.cursor.execute(sql, (vehicle_id,))
        return self.cursor.fetchall()

    def get_vehicles(self):
        self.cursor.execute('SELECT * FROM vehicles')
        return self.cursor.fetchall()

    def get_total_cost(self, vehicle_id):
        sql = 'SELECT SUM(cost) FROM maintenance_records WHERE vehicle_id = ?'
        self.cursor.execute(sql, (vehicle_id,))
        return self.cursor.fetchone()[0] or 0

    def close(self):
        self.conn.close()

class User:
    def __init__(self, username, password):
        self.username = username
        self.salt = secrets.token_hex(16)
        self.password_hash = self._hash_password(password, self.salt)

    def _hash_password(self, password, salt):
        return hashlib.pbkdf2_hmac('sha256', password.encode(), salt.encode(), 100000).hex()

    def verify_password(self, password):
        return self._hash_password(password, self.salt) == self.password_hash
