from PIL import Image
import pytesseract
import re
import json
from datetime import datetime
import hashlib
import os
from typing import Dict, List

class ReceiptScanner:
    def __init__(self, upload_dir: str):
        self.upload_dir = upload_dir
        self.allowed_extensions = {'.jpg', '.jpeg', '.png', '.pdf'} 

    def validate_file(self, filename: str) -> bool:
        ext = os.path.splitext(filename)[1].lower()
        return '.' in filename and ext in self.allowed_extensions

    def get_file_hash(self, file_content: bytes) -> str:
        return hashlib.sha256(file_content).hexdigest()

    def sanitize_filename(self, filename: str) -> str:
        return ''.join(c for c in filename if c.isalnum() or c in '._-')

    def scan_receipt(self, file_content: bytes, original_filename: str) -> Dict:
        if not self.validate_file(original_filename):
            raise ValueError("Invalid file type")

        file_hash = self.get_file_hash(file_content)
        safe_filename = self.sanitize_filename(original_filename)

        filepath = os.path.join(self.upload_dir, f"{file_hash}_{safe_filename}")

        with open(filepath, 'wb') as f:
            f.write(file_content)

        image = Image.open(filepath)
        text = pytesseract.image_to_string(image)

        receipt_data = {
            'merchant': self.extract_merchant(text),
            'date': self.extract_date(text),
            'total': self.extract_total(text),
            'items': self.extract_items(text),
            'receipt_id': file_hash
        }

        os.remove(filepath)
        return receipt_data

    def extract_merchant(self, text: str) -> str:
        lines = text.split('\n')
        return lines[0].strip() if lines else ''

    def extract_date(self, text: str) -> str:
        date_pattern = r'\d{1,2}[/-]\d{1,2}[/-]\d{2,4}'
        match = re.search(date_pattern, text)
        if match:
            date_str = match.group()
            try:
                parsed_date = datetime.strptime(date_str, '%m/%d/%Y')
                return parsed_date.strftime('%Y-%m-%d')
            except ValueError:
                return ''
        return ''

    def extract_total(self, text: str) -> float:
        total_pattern = r'TOTAL\s*[\$]?\s*(\d+\.\d{2})'
        match = re.search(total_pattern, text, re.IGNORECASE)
        return float(match.group(1)) if match else 0.0

    def extract_items(self, text: str) -> List[Dict]:
        items = []
        item_pattern = r'(\d+)\s+([A-Za-z\s]+)\s+(\d+\.\d{2})'
        matches = re.finditer(item_pattern, text)

        for match in matches:
            quantity, description, price = match.groups()
            items.append({
                'quantity': int(quantity),
                'description': description.strip(),
                'price': float(price)
            })

        return items
