import os
import shutil
import ast
import sys
from pathlib import Path
from dataclasses import dataclass
from typing import List, Dict

@dataclass
class ComplexityIssue:
    file: str
    method: str
    lines: int
    complexity: int

class CodeAnalyzer:
    def __init__(self, max_lines=50, max_complexity=10):
        self.max_lines = max_lines
        self.max_complexity = max_complexity
        self.issues: List[ComplexityIssue] = []

    def analyze_file(self, filepath: Path) -> None:
        with open(filepath, 'r', encoding='utf-8') as f:
            try:
                tree = ast.parse(f.read())
                for node in ast.walk(tree):
                    if isinstance(node, ast.FunctionDef):
                        lines = node.end_lineno - node.lineno
                        complexity = self._calculate_complexity(node)

                        if lines > self.max_lines or complexity > self.max_complexity:
                            self.issues.append(ComplexityIssue(
                                str(filepath),
                                node.name,
                                lines,
                                complexity
                            ))
            except SyntaxError:
                pass

    def _calculate_complexity(self, node: ast.AST) -> int:
        complexity = 1
        for child in ast.walk(node):
            if isinstance(child, (ast.If, ast.While, ast.For, ast.ExceptHandler)):
                complexity += 1
            elif isinstance(child, ast.BoolOp):
                complexity += len(child.values) - 1
        return complexity

    def generate_report(self, output_file: str) -> None:
        os.makedirs(os.path.dirname(output_file), exist_ok=True)

        with open(output_file, 'w', encoding='utf-8') as f:
            f.write("Code Complexity Report\n")
            f.write("====================\n\n")

            for issue in sorted(self.issues, key=lambda x: (x.complexity, x.lines), reverse=True):
                f.write(f"File: {issue.file}\n")
                f.write(f"Method: {issue.method}\n")
                f.write(f"Lines: {issue.lines}\n")
                f.write(f"Complexity: {issue.complexity}\n")
                f.write("-" * 40 + "\n")

def archive_folder(source_dir: str, archive_path: str) -> None:
    if not os.path.exists(source_dir):
        raise ValueError("Source directory does not exist")
    shutil.make_archive(archive_path, 'zip', source_dir)

def main():
    if len(sys.argv) < 3:
        print("Usage: script.py <source_dir> <report_path> [max_lines] [max_complexity]")
        return

    source_dir = sys.argv[1]
    report_path = sys.argv[2]
    max_lines = int(sys.argv[3]) if len(sys.argv) > 3 else 50
    max_complexity = int(sys.argv[4]) if len(sys.argv) > 4 else 10

    analyzer = CodeAnalyzer(max_lines, max_complexity)

    for path in Path(source_dir).rglob("*.py"):
        analyzer.analyze_file(path)

    analyzer.generate_report(report_path)
    archive_folder(source_dir, f"{source_dir}_archive")

if __name__ == "__main__":
    main()
