        if 'title' in kwargs:
            results = [obj for obj in results 
                      if kwargs['title'].lower() in obj.title.lower()]

        if 'subject' in kwargs:
            results = [obj for obj in results 
                      if kwargs['subject'].lower() == obj.subject.lower()]

        if 'type' in kwargs:
