                      if kwargs['type'].lower() == obj.type.lower()]

        if 'grade' in kwargs:
            results = [obj for obj in results 
                      if obj.grade == kwargs['grade']]

        if 'grade_range' in kwargs:
            min_grade, max_grade = kwargs['grade_range']
            results = [obj for obj in results 
                      if min_grade <= obj.grade <= max_grade]

        return results

    def get_object_by_title(self, title: str) -> LearningObject:
