import os
import subprocess
import hashlib
import shutil
from pathlib import Path

class Builder:
    def __init__(self, source_dir, build_dir, output_dir):
        self.source_dir = Path(source_dir).resolve()
        self.build_dir = Path(build_dir).resolve()
        self.output_dir = Path(output_dir).resolve()

        self.build_dir.mkdir(exist_ok=True)
        self.output_dir.mkdir(exist_ok=True)

    def compute_file_hash(self, filepath):
        sha256 = hashlib.sha256()
        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(4096), b''):
                sha256.update(chunk)
        return sha256.hexdigest()

    def needs_rebuild(self, source_file, output_file):
        if not output_file.exists():
            return True

        source_hash = self.compute_file_hash(source_file)
        output_hash = self.compute_file_hash(output_file) if output_file.exists() else None

        return source_hash != output_hash

    def compile_source(self, source_file):
        output_file = self.output_dir / source_file.stem
        if source_file.suffix == '.cpp':
            subprocess.run(['g++', '-o', str(output_file), str(source_file)], 
                         check=True, capture_output=True)
        elif source_file.suffix == '.c':
            subprocess.run(['gcc', '-o', str(output_file), str(source_file)],
                         check=True, capture_output=True)

    def build(self):
        for source_file in self.source_dir.glob('*.[cp]*'):
            output_file = self.output_dir / source_file.stem

            if self.needs_rebuild(source_file, output_file):
                try:
                    self.compile_source(source_file)
                except subprocess.CalledProcessError as e:
                    print(f"Error compiling {source_file}: {e.stderr.decode()}")
                except Exception as e:
                    print(f"Error processing {source_file}: {str(e)}")

    def clean(self):
        if self.build_dir.exists():
            shutil.rmtree(self.build_dir)
        if self.output_dir.exists():
            shutil.rmtree(self.output_dir)
        self.build_dir.mkdir()
        self.output_dir.mkdir()
