from urllib.parse import urlparse
import re

def validate_url(url):
    parsed = urlparse(url)
    return bool(parsed.scheme and parsed.netloc and
                re.match(r'^[a-zA-Z0-9\-\./:_]+$', url))

def validate_path(path):
    return bool(re.match(r'^[a-zA-Z0-9\-\./_]+$', path) and
                os.path.abspath(path).startswith('/home'))

def clone_repo(url, path):
    if not validate_url(url) or not validate_path(path):
        raise ValueError("Invalid input")

    if os.path.exists(path):
        shutil.rmtree(path)

    result = subprocess.run(['git', 'clone', url, path],
                          capture_output=True, check=True)

    if result.returncode == 0:
        subprocess.run(['git', 'checkout', 'main'],
                      cwd=path, capture_output=True, check=True)

def pull_repo(path):
    if not validate_path(path):
        raise ValueError("Invalid path")

    subprocess.run(['git', 'pull'], 
                  cwd=path, capture_output=True, check=True)

def get_status(path):
    if not validate_path(path):
        raise ValueError("Invalid path")

    result = subprocess.run(['git', 'status'],
                          cwd=path, capture_output=True, text=True, check=True)
    return result.stdout

