        if not re.match(r'^[A-Z]{2}$', state):
            return jsonify({'error': 'Invalid state format'}), 400

        if not re.match(r'^\d{5}(-\d{4})?$', zip_code):
            return jsonify({'error': 'Invalid zip code format'}), 400

        return jsonify({
            'address': address,
            'city': city,
            'state': state,
            'zip_code': zip_code
        }), 200

