from bs4 import BeautifulSoup
from datetime import datetime
import base64

class WebArchiver:
    def __init__(self, storage_dir):
        self.storage_dir = storage_dir
        os.makedirs(storage_dir, exist_ok=True)

    def archive_url(self, url):
        try:
            response = requests.get(url, timeout=30, verify=True)
            response.raise_for_status()

            soup = BeautifulSoup(response.text, 'html.parser')

            archive_id = hashlib.sha256(url.encode()).hexdigest()[:16]
            timestamp = datetime.now().strftime('%Y%m%d_%H%M%S')
            archive_dir = os.path.join(self.storage_dir, archive_id)
            os.makedirs(archive_dir, exist_ok=True)

            html_file = os.path.join(archive_dir, f'{timestamp}.html')
            with open(html_file, 'w', encoding='utf-8') as f:
                f.write(response.text)

            metadata = {
                'url': url,
                'timestamp': timestamp,
                'title': soup.title.text if soup.title else '',
                'resources': []
            }

            for img in soup.find_all('img'):
                src = img.get('src')
                if src:
                    img_url = urljoin(url, src)
                    img_data = self._download_resource(img_url)
                    if img_data:
                        img_hash = hashlib.sha256(img_data).hexdigest()[:16]
                        img_ext = os.path.splitext(urlparse(img_url).path)[1]
                        img_filename = f'{img_hash}{img_ext}'
                        img_path = os.path.join(archive_dir, img_filename)

                        with open(img_path, 'wb') as f:
                            f.write(img_data)

                        metadata['resources'].append({
                            'original_url': img_url,
                            'filename': img_filename
                        })

            return metadata

        except Exception as e:
            return {'error': str(e)}

    def _download_resource(self, url):
        try:
            response = requests.get(url, timeout=10, verify=True)
            response.raise_for_status()
            return response.content
        except:
            return None

    def get_archive_list(self):
        archives = []
        for archive_id in os.listdir(self.storage_dir):
            archive_dir = os.path.join(self.storage_dir, archive_id)
            if os.path.isdir(archive_dir):
                snapshots = [f for f in os.listdir(archive_dir) if f.endswith('.html')]
                archives.append({
                    'id': archive_id,
                    'snapshots': sorted(snapshots)
                })
        return archives
