from typing import Any, Dict, List
import time
import threading
import socket
import pickle

class Node:
    def __init__(self, host: str, port: int, replica_nodes: List[tuple] = None):
        self.host = host
        self.port = port
        self.data: Dict[str, Any] = {}
        self.replicas = replica_nodes or []
        self.lock = threading.Lock()
        self.start_server()

    def start_server(self):
        self.server = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self.server.bind((self.host, self.port))
        self.server.listen()
        threading.Thread(target=self.accept_connections, daemon=True).start()

    def accept_connections(self):
        while True:
            client, _ = self.server.accept()
            threading.Thread(target=self.handle_client, args=(client,)).start()

    def handle_client(self, client: socket.socket):
        try:
            while True:
                data = pickle.loads(client.recv(4096))
                operation, key, value = data
                if operation == "GET":
                    result = self.get(key)
                    client.send(pickle.dumps(result))
                elif operation == "SET":
                    self.set(key, value)
                    client.send(pickle.dumps("OK"))
                elif operation == "DELETE":
                    self.delete(key)
                    client.send(pickle.dumps("OK"))
        except:
            client.close()

    def replicate(self, operation: str, key: str, value: Any = None):
        for replica in self.replicas:
            try:
                sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                sock.connect(replica)
                sock.send(pickle.dumps((operation, key, value)))
                sock.close()
            except:
                continue

    def get(self, key: str) -> Any:
        with self.lock:
            return self.data.get(key)

    def set(self, key: str, value: Any):
        with self.lock:
            self.data[key] = value
            self.replicate("SET", key, value)

    def delete(self, key: str):
        with self.lock:
            if key in self.data:
                del self.data[key]
                self.replicate("DELETE", key)

class Client:
    def __init__(self, nodes: List[tuple]):
        self.nodes = nodes

    def get(self, key: str) -> Any:
        for node in self.nodes:
            try:
                sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                sock.connect(node)
                sock.send(pickle.dumps(("GET", key, None)))
                result = pickle.loads(sock.recv(4096))
                sock.close()
                return result
            except:
                continue
        return None

    def set(self, key: str, value: Any):
        for node in self.nodes:
            try:
                sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                sock.connect(node)
                sock.send(pickle.dumps(("SET", key, value)))
                sock.recv(4096)
                sock.close()
                return
            except:
                continue

    def delete(self, key: str):
        for node in self.nodes:
            try:
                sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                sock.connect(node)
                sock.send(pickle.dumps(("DELETE", key, None)))
                sock.recv(4096)
                sock.close()
                return
            except:
                continue
