import uuid

@dataclass
class Fish:
    id: str
    name: str
    species: str
    age: int
    date_added: datetime

@dataclass 
class Tank:
    id: str
    name: str
    volume: float
    temperature: float
    fish: List[Fish]
    params: Dict[str, float]

class Aquarium:
    def __init__(self):
        self.tanks = {}

    def add_tank(self, name: str, volume: float, temp: float) -> str:
        tank_id = str(uuid.uuid4())
        self.tanks[tank_id] = Tank(
            id=tank_id,
            name=name,
            volume=volume,
            temperature=temp,
            fish=[],
            params={"pH": 7.0, "ammonia": 0.0, "nitrite": 0.0, "nitrate": 0.0}
        )
        return tank_id

    def add_fish(self, tank_id: str, name: str, species: str, age: int) -> str:
        if tank_id not in self.tanks:
            raise ValueError("Tank not found")

        fish = Fish(
            id=str(uuid.uuid4()),
            name=name,
            species=species,
            age=age,
            date_added=datetime.now()
        )
        self.tanks[tank_id].fish.append(fish)
        return fish.id

    def remove_fish(self, tank_id: str, fish_id: str) -> None:
        if tank_id not in self.tanks:
            raise ValueError("Tank not found")

        self.tanks[tank_id].fish = [f for f in self.tanks[tank_id].fish if f.id != fish_id]

    def update_params(self, tank_id: str, params: Dict[str, float]) -> None:
        if tank_id not in self.tanks:
            raise ValueError("Tank not found")

        self.tanks[tank_id].params.update(params)

    def get_tank_info(self, tank_id: str) -> Tank:
        if tank_id not in self.tanks:
            raise ValueError("Tank not found")

        return self.tanks[tank_id]

def main():
    aquarium = Aquarium()
    tank_id = aquarium.add_tank("Main Tank", 75.0, 78.5)
    aquarium.add_fish(tank_id, "Nemo", "Clownfish", 1)
    aquarium.add_fish(tank_id, "Dory", "Blue Tang", 2)
    aquarium.update_params(tank_id, {"pH": 8.1, "ammonia": 0.0})
