from botocore.exceptions import ClientError

class Pipeline:
    def __init__(self, config_file: str):
        with open(config_file) as f:
            self.config = yaml.safe_load(f)
        self.s3 = boto3.client('s3')
        self.repo = None
        self.artifacts_dir = "artifacts"
        os.makedirs(self.artifacts_dir, exist_ok=True)

    def run(self):
        self._checkout_code()
        self._build()
        self._test()
        self._publish()
        self._create_release()
        self._cleanup()

    def _checkout_code(self):
        if os.path.exists("source"):
            shutil.rmtree("source")
        self.repo = git.Repo.clone_from(
            self.config["repository"],
            "source",
            branch=self.config["branch"]
        )

    def _build(self):
        subprocess.run(
            self.config["build_command"],
            cwd="source",
            shell=True,
            check=True
        )

    def _test(self):
        subprocess.run(
            self.config["test_command"], 
            cwd="source",
            shell=True,
            check=True
        )

    def _publish(self):
        artifacts = self.config["artifacts"]
        for artifact in artifacts:
            source = os.path.join("source", artifact)
            dest = os.path.join(self.artifacts_dir, os.path.basename(artifact))
            if os.path.isfile(source):
                shutil.copy2(source, dest)
            elif os.path.isdir(source):
                shutil.copytree(source, dest)

        try:
            for artifact in os.listdir(self.artifacts_dir):
                file_path = os.path.join(self.artifacts_dir, artifact)
                self.s3.upload_file(
                    file_path,
                    self.config["s3_bucket"],
                    f"{self.config['s3_prefix']}/{artifact}",
                    ExtraArgs={'ServerSideEncryption': 'AES256'}
                )
        except ClientError as e:
            raise Exception(f"Failed to upload artifacts: {str(e)}")

    def _create_release(self):
        release_config = {
            "version": self._get_version(),
            "artifacts": self.config["artifacts"],
            "permissions": self.config["release_permissions"]
        }

        with open(os.path.join(self.artifacts_dir, "release.json"), "w") as f:
            json.dump(release_config, f)

        self.s3.upload_file(
            os.path.join(self.artifacts_dir, "release.json"),
            self.config["s3_bucket"],
            f"{self.config['s3_prefix']}/release.json",
            ExtraArgs={'ServerSideEncryption': 'AES256'}
        )

    def _get_version(self):
        return subprocess.check_output(
            self.config["version_command"],
            cwd="source",
            shell=True,
            text=True
        ).strip()

    def _cleanup(self):
        if os.path.exists("source"):
            shutil.rmtree("source")
        if os.path.exists(self.artifacts_dir):
            shutil.rmtree(self.artifacts_dir)

if __name__ == "__main__":
    pipeline = Pipeline("pipeline_config.yml")
    pipeline.run()
