        return path.is_file() and path.suffix == '.log'

    def log_stream(self, filepath: str, offset: int = 0) -> Generator[str, None, None]:
        if not self.validate_path(filepath):
            raise ValueError("Invalid log file path")

        try:
            with open(filepath, 'r', encoding='utf-8') as f:
                if offset > os.path.getsize(filepath):
