        return self.cache_dir / hashed

    def get(self, key):
        filepath = self._get_safe_filename(key)
        try:
            if filepath.exists() and filepath.is_file():
                with open(filepath, 'r') as f:
                    data = json.load(f)
                    value = base64.b64decode(data['value']).decode()
