import os
import zipfile
import shutil
from pathlib import Path

def extract_ebooks(archive_path, output_dir):
    if not os.path.exists(output_dir):
        os.makedirs(output_dir)

    allowed_extensions = {'.epub', '.mobi', '.pdf', '.azw3'}

    with zipfile.ZipFile(archive_path, 'r') as zip_ref:
        for file in zip_ref.namelist():
            ext = os.path.splitext(file)[1].lower()
            if ext in allowed_extensions:
                target_path = os.path.join(output_dir, os.path.basename(file))
                target_path = Path(target_path).resolve()
                if target_path.parent.resolve() != Path(output_dir).resolve():
                    continue

                with zip_ref.open(file) as source, open(target_path, 'wb') as target:
                    shutil.copyfileobj(source, target)

def main():
    archive_path = input("Enter path to ebook archive: ").strip()
    output_dir = input("Enter output directory path: ").strip()

    try:
        extract_ebooks(archive_path, output_dir)
        print("Extraction complete")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    main()
