class User:
    def __init__(self, username: str, password: str):
        self.user_id = str(uuid.uuid4())
        self.username = username
        self.password_hash = bcrypt.hashpw(password.encode(), bcrypt.gensalt())
        self.health_data = {"weight": [], "height": None, "age": None}
        self.workout_history = []
        self.goals = []
        self.devices = []

class WorkoutSession:
    def __init__(self, workout_type: str, duration: int, calories: int):
        self.session_id = str(uuid.uuid4())
        self.timestamp = datetime.now()
        self.workout_type = workout_type
        self.duration = duration
        self.calories = calories
        self.metrics = {}

class FitnessTracker:
    def __init__(self):
        self.users: Dict[str, User] = {}

    def register_user(self, username: str, password: str) -> bool:
        if username in self.users:
            return False
        self.users[username] = User(username, password)
        return True

    def authenticate(self, username: str, password: str) -> bool:
        if username not in self.users:
            return False
        return bcrypt.checkpw(password.encode(), self.users[username].password_hash)

    def add_health_data(self, username: str, data_type: str, value: float) -> bool:
        if username not in self.users:
            return False
        if data_type == "weight":
            self.users[username].health_data["weight"].append({"date": datetime.now(), "value": value})
        else:
            self.users[username].health_data[data_type] = value
        return True

    def add_workout(self, username: str, workout_type: str, duration: int, calories: int) -> bool:
        if username not in self.users:
            return False
        workout = WorkoutSession(workout_type, duration, calories)
        self.users[username].workout_history.append(workout)
        return True

    def set_goal(self, username: str, goal_type: str, target: float, deadline: datetime) -> bool:
        if username not in self.users:
            return False
        goal = {"type": goal_type, "target": target, "deadline": deadline, "created": datetime.now()}
        self.users[username].goals.append(goal)
        return True

    def pair_device(self, username: str, device_id: str, device_type: str) -> bool:
        if username not in self.users:
            return False
        device = {"id": device_id, "type": device_type, "paired_date": datetime.now()}
        self.users[username].devices.append(device)
        return True

    def get_workout_history(self, username: str) -> List[WorkoutSession]:
        if username not in self.users:
            return []
        return self.users[username].workout_history

    def export_user_data(self, username: str) -> str:
        if username not in self.users:
            return ""
        user_data = {
