from typing import Any, Dict, List, Tuple
import time
import threading
import socket
import pickle
import hashlib

class Node:
    def __init__(self, host: str, port: int):
        self.host = host
        self.port = port
        self.data: Dict[str, Tuple[Any, float]] = {}
        self.replicas: List[Tuple[str, int]] = []
        self.sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
        self.sock.bind((host, port))
        self.lock = threading.Lock()

    def start(self):
        threading.Thread(target=self._listen, daemon=True).start()
        threading.Thread(target=self._heartbeat, daemon=True).start()

    def _listen(self):
        while True:
            data, addr = self.sock.recvfrom(4096)
            msg = pickle.loads(data)
            if msg["type"] == "put":
                self._handle_put(msg["key"], msg["value"], msg["timestamp"])
            elif msg["type"] == "get":
                self._handle_get(msg["key"], addr)
            elif msg["type"] == "heartbeat":
                self._handle_heartbeat(addr)

    def _handle_put(self, key: str, value: Any, timestamp: float):
        with self.lock:
            if key not in self.data or timestamp > self.data[key][1]:
                self.data[key] = (value, timestamp)

    def _handle_get(self, key: str, addr: Tuple[str, int]):
        with self.lock:
            if key in self.data:
                response = {"value": self.data[key][0]}
                self.sock.sendto(pickle.dumps(response), addr)

    def _handle_heartbeat(self, addr: Tuple[str, int]):
        if addr not in self.replicas:
            self.replicas.append(addr)

    def _heartbeat(self):
        while True:
            msg = {"type": "heartbeat"}
            for replica in self.replicas:
                try:
                    self.sock.sendto(pickle.dumps(msg), replica)
                except:
                    self.replicas.remove(replica)
            time.sleep(1)

    def put(self, key: str, value: Any):
        timestamp = time.time()
        msg = {"type": "put", "key": key, "value": value, "timestamp": timestamp}
        with self.lock:
            self.data[key] = (value, timestamp)
            for replica in self.replicas:
                try:
                    self.sock.sendto(pickle.dumps(msg), replica)
                except:
                    self.replicas.remove(replica)

    def get(self, key: str) -> Any:
        with self.lock:
            return self.data.get(key, (None, 0))[0]

    def join_cluster(self, host: str, port: int):
        self.replicas.append((host, port))
