import os
import shutil

def sync_dir(remote, local):
    remote = os.path.abspath(os.path.expanduser(remote))
    local = os.path.abspath(os.path.expanduser(local))

    if not os.path.exists(remote):
        raise ValueError("Remote directory does not exist")

    if not os.path.exists(local):
        os.makedirs(local)

    for item in os.scandir(remote):
        remote_path = os.path.join(remote, item.name) 
        local_path = os.path.join(local, item.name)

        if not os.path.exists(os.path.dirname(local_path)):
            os.makedirs(os.path.dirname(local_path))

        if item.is_file():
            shutil.copy2(remote_path, local_path)
        elif item.is_dir():
            if not os.path.exists(local_path):
                os.makedirs(local_path)
            sync_dir(remote_path, local_path)

