import os
import pathlib

def create_backup(path):
    if not os.path.exists(path):
        raise ValueError("Source path does not exist")
    backup_path = pathlib.Path(path + ".tar.gz").resolve()
    with tarfile.open(backup_path, 'w:gz') as tar:
        tar.add(path)

def restore_backup(backup_file, extraction_dir):
    if not os.path.exists(backup_file):
        raise ValueError("Backup file does not exist")
    if not os.path.exists(extraction_dir):
        os.makedirs(extraction_dir)
    extraction_path = pathlib.Path(extraction_dir).resolve()
    with tarfile.open(backup_file, 'r:gz') as tar:
        for member in tar.getmembers():
            member_path = os.path.join(extraction_path, member.name)
            if not os.path.abspath(member_path).startswith(str(extraction_path)):
                raise ValueError("Attempted path traversal")
