def archive_files(source_dir: str, dest_archive: str, patterns: List[str], exclude_dirs: List[str] = None) -> None:
    if not os.path.exists(source_dir):
        raise ValueError("Source directory does not exist")

    source_path = Path(source_dir).resolve()
    exclude_dirs = set(exclude_dirs) if exclude_dirs else set()

    with zipfile.ZipFile(dest_archive, 'w', zipfile.ZIP_DEFLATED) as zf:
        for root, dirs, files in os.walk(source_path, topdown=True):
            dirs[:] = [d for d in dirs if d not in exclude_dirs]

            for pattern in patterns:
