from datetime import datetime, timedelta

class Goal:
    def __init__(self, name, target, timeline):
        self.name = name
        self.target = target
        self.timeline = timeline
        self.progress = 0
        self.completed = False
        self.start_date = datetime.now()
        self.end_date = self.start_date + timedelta(days=timeline)
        self.log = []

    def update_progress(self, value):
        self.progress = min(value, self.target)
        self.completed = self.progress >= self.target
        self.log.append((datetime.now(), value))

    def get_status(self):
        return {
            'name': self.name,
            'target': self.target,
            'progress': self.progress,
            'completed': self.completed,
            'days_remaining': (self.end_date - datetime.now()).days
        }

class WellnessTracker:
    def __init__(self):
        self.goals = {}

    def add_goal(self, category, name, target, timeline):
        if category not in self.goals:
            self.goals[category] = []
        self.goals[category].append(Goal(name, target, timeline))

    def update_goal(self, category, goal_name, value):
        for goal in self.goals.get(category, []):
            if goal.name == goal_name:
                goal.update_progress(value)
                return True
        return False

    def get_goals_status(self, category=None):
        if category:
            return [goal.get_status() for goal in self.goals.get(category, [])]
        return {cat: [goal.get_status() for goal in goals] 
                for cat, goals in self.goals.items()}

    def get_completion_rate(self, category=None):
        if category:
            goals = self.goals.get(category, [])
            completed = sum(1 for goal in goals if goal.completed)
            return completed / len(goals) if goals else 0

        all_goals = [goal for goals in self.goals.values() for goal in goals]
        completed = sum(1 for goal in all_goals if goal.completed)
        return completed / len(all_goals) if all_goals else 0

