        total_length = 0
        line_count = 0
        circle_count = 0
        polyline_count = 0

        for entity in msp:
            if entity.dxftype() == 'LINE':
                start = entity.dxf.start
                end = entity.dxf.end
                length = ((end[0]-start[0])**2 + (end[1]-start[1])**2)**0.5
                total_length += length
                line_count += 1

            elif entity.dxftype() == 'CIRCLE':
                circle_count += 1

            elif entity.dxftype() == 'LWPOLYLINE':
                polyline_count += 1
                points = entity.get_points()
                for i in range(len(points)-1):
                    p1, p2 = points[i], points[i+1]
                    length = ((p2[0]-p1[0])**2 + (p2[1]-p1[1])**2)**0.5
                    total_length += length

        return {
            'total_length': round(total_length, 2),
            'line_count': line_count,
            'circle_count': circle_count,
            'polyline_count': polyline_count
        }

    except ezdxf.DXFError as e:
        raise ValueError(f"Invalid DXF file: {str(e)}")
    except Exception as e:
        raise ValueError(f"Error processing file: {str(e)}")

def main():
    if len(sys.argv) != 2:
        sys.exit("Usage: script.py <dxf_file>")

    try:
        results = analyze_dxf(sys.argv[1])
        print(f"Total length: {results['total_length']}")
        print(f"Line count: {results['line_count']}")
        print(f"Circle count: {results['circle_count']}")
        print(f"Polyline count: {results['polyline_count']}")
    except ValueError as e:
        sys.exit(str(e))

if __name__ == '__main__':
    main()
